# Themes: light and dark palettes, an accent colour, and "System" (follow Windows' app mode).
# $C always holds the current palette; Set-Theme swaps it and re-colours every open window.
function ColorHex([string]$Hex) { [System.Drawing.ColorTranslator]::FromHtml($Hex) }

$Accents = [ordered]@{        # name = light theme shade, dark theme shade
    Blue   = @('#0A5CA8', '#4C9EFF')
    Purple = @('#6342C0', '#A98BFA')
    Green  = @('#0B6B35', '#4CC77A')
    Orange = @('#A84A08', '#FF9B57')
    Pink   = @('#9C2A84', '#F08AD8')
    Teal   = @('#03686B', '#3CC6C6')
}

function Get-ThemePalette([bool]$Dark, [string]$AccentName) {
    if (-not $Accents.Contains($AccentName)) { $AccentName = 'Blue' }
    $accent = ColorHex $Accents[$AccentName][$(if ($Dark) { 1 } else { 0 })]
    if ($Dark) {
        $p = [ordered]@{
            Bg = '#1E1E1F'; Panel = '#262628'; Card = '#2E2E30'; Hover = '#38383B'; Pressed = '#434346'; Line = '#3A3A3D'
            Fore = '#EDEDED'; Dim = '#9C9CA1'; PinBg = '#2C2819'; Pin = '#F5C451'
            Red = '#FF6B6B'; Green = '#5DCB74'; Yellow = '#E8B84A'; Purple = '#B48CF2'; Orange = '#F59E5B'
            HlLine = '#3A3520'; HlMatch = '#7D6414'
        }
    } else {
        $p = [ordered]@{
            Bg = '#FFFFFF'; Panel = '#F3F3F5'; Card = '#FBFBFC'; Hover = '#E6E6E9'; Pressed = '#D6D6DA'; Line = '#CFCFD4'
            Fore = '#0F0F10'; Dim = '#45454B'; PinBg = '#FFF6DC'; Pin = '#B07C00'
            Red = '#B3261E'; Green = '#0B6B35'; Yellow = '#835800'; Purple = '#6A3FB5'; Orange = '#A84A08'
            HlLine = '#FFF4CE'; HlMatch = '#F7D774'
        }
    }
    $pal = @{}
    foreach ($k in $p.Keys) { $pal[$k] = ColorHex $p[$k] }
    $pal.Accent = $accent
    $pal.Sel = [PowerClipTheme]::Mix($pal.Bg, $accent, $(if ($Dark) { 0.32 } else { 0.16 }))
    $pal.SelLine = [PowerClipTheme]::Mix($pal.Bg, $accent, $(if ($Dark) { 0.55 } else { 0.40 }))
    $pal
}

function Test-SystemDark {
    try { (Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name AppsUseLightTheme -ErrorAction Stop).AppsUseLightTheme -eq 0 }
    catch { $true }
}

function Resolve-Dark([string]$Theme) {
    switch ($Theme) { 'Light' { $false } 'Dark' { $true } default { Test-SystemDark } }
}

