function New-AppIcon([System.Drawing.Color]$Color) {
    $bmp = New-Object System.Drawing.Bitmap 32, 32
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = 'AntiAlias'
    $b = New-Object System.Drawing.SolidBrush $Color
    $path = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(4, 5, 24, 26)), 4)
    $g.FillPath($b, $path)
    $g.FillRectangle([System.Drawing.Brushes]::White, 8, 10, 16, 17)
    $clip = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(10, 2, 12, 6)), 2)
    $g.FillPath((New-Object System.Drawing.SolidBrush ([PowerClipTheme]::Mix($Color, [System.Drawing.Color]::Black, 0.45))), $clip)
    $p = New-Object System.Drawing.Pen($Color, 2)
    foreach ($y in 14, 18, 22) { $g.DrawLine($p, 11, $y, 21, $y) }
    $g.Dispose()
    [System.Drawing.Icon]::FromHandle($bmp.GetHicon())
}

# Everything that is built from the palette (pens, icons, status colours, the C# controls' colours).
function Update-ThemeDerived {
    $script:LinePen   = New-Object System.Drawing.Pen($C.Line)
    $script:FileBrush = New-Object System.Drawing.SolidBrush($C.Accent)
    $script:FilePen   = New-Object System.Drawing.Pen(([PowerClipTheme]::Mix($C.Accent, [System.Drawing.Color]::White, 0.55)), 1.5)
    $script:IconActive = New-AppIcon $C.Accent
    $script:IconPaused = New-AppIcon ([System.Drawing.Color]::FromArgb(130, 130, 130))
    $script:DirStatusColor = @($C.Dim, $C.Yellow, $C.Red, $C.Green, $C.Orange)
    $script:NetColors = @($C.Fore, $C.Green, $C.Red, $C.Yellow, $C.Dim, $C.Accent)
    $script:ApiMethodColors = @{ GET = $C.Green; POST = $C.Yellow; PUT = $C.Accent; PATCH = $C.Purple; DELETE = $C.Red; HEAD = $C.Dim; OPTIONS = $C.Dim }

    $dark = $script:IsDark
    [PowerClipTheme]::Dark = $dark
    [PowerClipTheme]::Window = $C.Bg; [PowerClipTheme]::Panel = $C.Panel; [PowerClipTheme]::Card = $C.Card
    [PowerClipTheme]::Hover = $C.Hover; [PowerClipTheme]::Pressed = $C.Pressed; [PowerClipTheme]::Line = $C.Line
    [PowerClipTheme]::Fore = $C.Fore; [PowerClipTheme]::Dim = $C.Dim; [PowerClipTheme]::Accent = $C.Accent; [PowerClipTheme]::Danger = $C.Red

    # Compare view
    $D = [PowerClipDiffView]
    $D::Bg = $C.Bg; $D::GutterBg = $C.Panel; $D::GutterFg = $C.Dim; $D::Fore = $C.Fore; $D::Divider = $C.Line; $D::Accent = $C.Accent
    $D::Selection = $C.Sel; $D::CaretColor = $C.Fore; $D::WsMark = [PowerClipTheme]::Mix($C.Dim, $C.Accent, 0.35)
    if ($dark) {
        $D::Missing = ColorHex '#2B2B2E'
        $D::Changed = ColorHex '#3A3520'; $D::ChangedCur = ColorHex '#524722'; $D::Word = ColorHex '#7D6414'
        $D::Deleted = ColorHex '#472426'; $D::DeletedCur = ColorHex '#64292D'; $D::WordDel = ColorHex '#943A40'
        $D::Inserted = ColorHex '#1F3D29'; $D::InsertedCur = ColorHex '#275A37'; $D::WordIns = ColorHex '#2F8049'
    } else {
        $D::Missing = ColorHex '#F1F1F3'
        $D::Changed = ColorHex '#FFF6D6'; $D::ChangedCur = ColorHex '#FFEBA8'; $D::Word = ColorHex '#F6D46C'
        $D::Deleted = ColorHex '#FDE8EA'; $D::DeletedCur = ColorHex '#F9CDD2'; $D::WordDel = ColorHex '#F2A0A9'
        $D::Inserted = ColorHex '#E3F6E6'; $D::InsertedCur = ColorHex '#C7EDCD'; $D::WordIns = ColorHex '#8FD49E'
    }
    $D::MarkChanged = $C.Yellow; $D::MarkDel = $C.Red; $D::MarkIns = $C.Green

    # Notes pages
    $B = [PowerClipNoteBlock]
    $B::Bg = $C.Bg; $B::Header = $C.Hover; $B::Border = $C.Line; $B::Accent = $C.Accent; $B::Dots = $C.Dim
    $B::SelTint = [System.Drawing.Color]::FromArgb(40, $C.Accent); $B::TextColor = $C.Fore; $B::HintColor = $C.Dim
    $B::KnownTextColors.Clear()
    foreach ($t in @((Get-ThemePalette $true 'Blue').Fore, (Get-ThemePalette $false 'Blue').Fore, [System.Drawing.Color]::FromArgb(232, 232, 232))) { $B::KnownTextColors.Add($t) }
}

# ---- applying the theme to windows -------------------------------------------------------------

function Set-ControlTheme($Ctl, $Map, [bool]$Dark) {
    if ($Map) {
        $bc = $Ctl.BackColor.ToArgb(); if ($Map.ContainsKey($bc)) { try { $Ctl.BackColor = $Map[$bc] } catch { } }
        $fc = $Ctl.ForeColor.ToArgb(); if ($Map.ContainsKey($fc)) { try { $Ctl.ForeColor = $Map[$fc] } catch { } }
        if ($Ctl -is [System.Windows.Forms.DataGridView]) {
            foreach ($style in $Ctl.DefaultCellStyle, $Ctl.ColumnHeadersDefaultCellStyle) {
                foreach ($prop in 'BackColor', 'ForeColor', 'SelectionBackColor', 'SelectionForeColor') {
                    $v = $style.$prop.ToArgb(); if ($Map.ContainsKey($v)) { $style.$prop = $Map[$v] }
                }
            }
            $v = $Ctl.BackgroundColor.ToArgb(); if ($Map.ContainsKey($v)) { $Ctl.BackgroundColor = $Map[$v] }
            $v = $Ctl.GridColor.ToArgb(); if ($Map.ContainsKey($v)) { $Ctl.GridColor = $Map[$v] }
        }
        if ($Ctl -is [System.Windows.Forms.LinkLabel]) {
            foreach ($prop in 'LinkColor', 'ActiveLinkColor') { $v = $Ctl.$prop.ToArgb(); if ($Map.ContainsKey($v)) { $Ctl.$prop = $Map[$v] } }
        }
    }
    if ($Ctl.ContextMenuStrip) { $Ctl.ContextMenuStrip.Renderer = $MenuRenderer }
    if ($Ctl.IsHandleCreated -and ($Ctl -is [System.Windows.Forms.ScrollableControl] -or $Ctl -is [System.Windows.Forms.ListBox] -or
        $Ctl -is [System.Windows.Forms.TreeView] -or $Ctl -is [System.Windows.Forms.TextBoxBase] -or $Ctl -is [System.Windows.Forms.DataGridView] -or
        $Ctl -is [System.Windows.Forms.ListView] -or $Ctl -is [System.Windows.Forms.ComboBox] -or $Ctl -is [System.Windows.Forms.ScrollBar])) {
        [PowerClipTheme]::Scrollbars($Ctl.Handle, $Dark)
    }
    foreach ($child in @($Ctl.Controls)) { Set-ControlTheme $child $Map $Dark }
    $Ctl.Invalidate()
}

# Every window calls this once: theme title bar + scrollbars when shown, and re-theme on switches.
function Limit-FormToScreen($F) {
    $wa = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).WorkingArea
    $maxW = [int]($wa.Width * 0.96); $maxH = [int]($wa.Height * 0.96)
    if ($F.MinimumSize.Width -gt $maxW -or $F.MinimumSize.Height -gt $maxH) { $F.MinimumSize = New-Object System.Drawing.Size([Math]::Min($F.MinimumSize.Width, $maxW), [Math]::Min($F.MinimumSize.Height, $maxH)) }
    $w = [Math]::Min($F.Width, $maxW); $h = [Math]::Min($F.Height, $maxH)
    $resized = $w -ne $F.Width -or $h -ne $F.Height
    if ($resized) { $F.Size = New-Object System.Drawing.Size($w, $h) }
    $b = $F.Bounds
    if ($resized -or $b.Right -gt $wa.Right -or $b.Bottom -gt $wa.Bottom -or $b.Left -lt $wa.Left -or $b.Top -lt $wa.Top) {
        $F.Location = New-Object System.Drawing.Point(($wa.X + [int](($wa.Width - $F.Width) / 2)), ($wa.Y + [int](($wa.Height - $F.Height) / 2)))
    }
}

function Register-ThemedWindow($Window) {
    $Window.add_Load({ param($src, $e) if ($src.WindowState -eq 'Normal' -and $src.TopLevel -and -not ($src -is [PowerClipToast])) { try { Limit-FormToScreen $src } catch { } } })
    $Window.add_HandleCreated({ param($src, $e) [PowerClipTheme]::TitleBar($src.Handle, $script:IsDark) })
    $Window.add_Shown({ param($src, $e) Set-ControlTheme $src $null $script:IsDark })
    $Window.add_FormClosed({ param($src, $e) [void]$script:ThemedWindows.Remove($src) })
    $script:ThemedWindows.Add($Window)
}

function Set-Theme([switch]$Init) {
    $dark = Resolve-Dark $script:Theme
    $new = Get-ThemePalette $dark $script:Accent
    $map = @{}
    if (-not $Init) { foreach ($k in $new.Keys) { if ($C.ContainsKey($k)) { $map[$C[$k].ToArgb()] = $new[$k] } } }
    foreach ($k in @($new.Keys)) { $C[$k] = $new[$k] }
    $script:IsDark = $dark
    Update-ThemeDerived
    if ($Init) { return }
    foreach ($w in $script:ThemedWindows.ToArray()) {
        if ($w.IsDisposed) { continue }
        if ($w.IsHandleCreated) { [PowerClipTheme]::TitleBar($w.Handle, $dark) }
        $w.Icon = if ($script:Paused) { $script:IconPaused } else { $script:IconActive }
        Set-ControlTheme $w $map $dark
        if ($w.Visible -and $w.IsHandleCreated) {        # nudge the frame so the title bar repaints at once
            $s = $w.Size; $w.Size = New-Object System.Drawing.Size(($s.Width + 1), $s.Height); $w.Size = $s
        }
    }
    $tray.Icon = if ($script:Paused) { $script:IconPaused } else { $script:IconActive }
    $trayMenu.Renderer = $MenuRenderer
    if ($NoteUI.Form -and $NoteUI.Current) { Save-CurrentNote; Open-Note $NoteUI.Current }   # reload so note text takes the new colour
    if ($ApiUI.Form -and $ApiUI.LastResponse) { Format-ApiBody $ApiUI.LastResponse $ApiUI.Pretty.Checked }
    $list.Invalidate()
}

