function Format-Age([datetime]$t) {
    $span = (Get-Date) - $t
    if ($span.TotalSeconds -lt 60) { return 'just now' }
    if ($span.TotalMinutes -lt 60) { return '{0} min ago' -f [int][Math]::Floor($span.TotalMinutes) }
    if ($span.TotalHours   -lt 24) { return '{0} h ago'   -f [int][Math]::Floor($span.TotalHours) }
    if ($span.TotalDays    -lt 7)  { return '{0} d ago'   -f [int][Math]::Floor($span.TotalDays) }
    return $t.ToString('d MMM yyyy')
}

function Get-Preview([string]$Text) {
    $t = if ($Text.Length -gt 400) { $Text.Substring(0, 400) } else { $Text }
    $t = $t -replace "`t", ' ' -replace "\r\n|\n|\r", " $RetSym " -replace ' {2,}', ' '
    $t.Trim()
}

function Format-Size([long]$Bytes) {
    if ($Bytes -lt 1KB) { return "$Bytes B" }
    if ($Bytes -lt 1MB) { return '{0:0} KB' -f ($Bytes / 1KB) }
    return '{0:0.0} MB' -f ($Bytes / 1MB)
}

# What the search box matches against.
function Get-SearchText($Item) {
    if ($Item.Kind -eq 'image') { return "image picture screenshot $($Item.Width)x$($Item.Height)" }
    $Item.Text
}

function Read-ImageFile([string]$Path) {
    # Load via a memory copy so the file isn't kept locked.
    $ms = New-Object System.IO.MemoryStream(, [IO.File]::ReadAllBytes($Path))
    $tmp = [System.Drawing.Image]::FromStream($ms)
    $bmp = New-Object System.Drawing.Bitmap $tmp
    $tmp.Dispose(); $ms.Dispose()
    $bmp
}

function Get-Thumb($Item, [int]$MaxW, [int]$MaxH) {
    if ($script:Thumbs.ContainsKey($Item.Id)) { return $script:Thumbs[$Item.Id] }
    $thumb = $null
    try {
        $img = Read-ImageFile (Get-DataPath $Item.Image)
        $ratio = [Math]::Min($MaxW / $img.Width, $MaxH / $img.Height)
        $ratio = [Math]::Min($ratio, 1.0)
        $w = [Math]::Max(1, [int]($img.Width * $ratio)); $h = [Math]::Max(1, [int]($img.Height * $ratio))
        $thumb = New-Object System.Drawing.Bitmap $w, $h
        $g = [System.Drawing.Graphics]::FromImage($thumb)
        $g.InterpolationMode = 'HighQualityBicubic'
        $g.DrawImage($img, 0, 0, $w, $h)
        $g.Dispose(); $img.Dispose()
    } catch { }
    $script:Thumbs[$Item.Id] = $thumb
    $thumb
}

# Small document glyph for file clips.
function Draw-FileGlyph([System.Drawing.Graphics]$G, [int]$X, [int]$Y, [int]$Size) {
    $w = [int]($Size * 0.75); $fold = [int]($Size * 0.28)
    $pts = [System.Drawing.Point[]]@(
        (New-Object System.Drawing.Point($X, $Y)),
        (New-Object System.Drawing.Point(($X + $w - $fold), $Y)),
        (New-Object System.Drawing.Point(($X + $w), ($Y + $fold))),
        (New-Object System.Drawing.Point(($X + $w), ($Y + $Size))),
        (New-Object System.Drawing.Point($X, ($Y + $Size))))
    $G.SmoothingMode = 'AntiAlias'
    $G.FillPolygon($FileBrush, $pts)
    $G.DrawLine($FilePen, ($X + $w - $fold), $Y, ($X + $w - $fold), ($Y + $fold))
    $G.DrawLine($FilePen, ($X + $w - $fold), ($Y + $fold), ($X + $w), ($Y + $fold))
    $G.SmoothingMode = 'Default'
}

