$buttons.Height       = $FontButton.Height + (Px 32)
$buttons.Padding      = New-Object System.Windows.Forms.Padding((Px 10), (Px 10), (Px 10), 0)
$buttons.BackColor    = $C.Panel
$buttons.WrapContents = $false
