$buttons.add_Paint({ param($src, $e) $e.Graphics.DrawLine($LinePen, 0, 0, $src.Width, 0) })

$status = New-Object System.Windows.Forms.Label
$status.Dock      = 'Bottom'
$status.Height    = $FontSmall.Height + (Px 10)
$status.Padding   = New-Object System.Windows.Forms.Padding((Px 14), 0, 0, (Px 2))
$status.TextAlign = 'MiddleLeft'
