# Buttons everywhere: rounded, with hover / pressed states and an optional icon.
# Variant: 0 normal, 1 primary (accent), 2 subtle (flat until hovered), 3 danger.
function New-Button([string]$Text, [string]$Tip, [scriptblock]$OnClick, $Parent = $buttons, [string]$Icon = '', [int]$Variant = 0) {
    $b = New-Object PowerClipButton
    $b.Font    = $FontButton
    $b.Glyph   = $Icon
    $b.Variant = $Variant
    $b.Text    = $Text
    $b.AutoSize = $true
    $b.Margin  = New-Object System.Windows.Forms.Padding((Px 3), (Px 2), (Px 3), 0)
    $b.add_Click($OnClick)
    if ($Tip) { $tooltip.SetToolTip($b, $Tip) }
    $Parent.Controls.Add($b)
    $b
}

# Square icon button (falls back to a short label when the icon font is missing).
function New-IconButton([string]$Icon, [string]$Fallback, [string]$Tip, [scriptblock]$OnClick, $Parent, [int]$Variant = 2) {
    if ($IconFontName) { $b = New-Button '' $Tip $OnClick $Parent $Icon $Variant } else { $b = New-Button $Fallback $Tip $OnClick $Parent '' $Variant }
    $b.Margin = New-Object System.Windows.Forms.Padding((Px 1), 0, (Px 1), 0)
    # In the picker's top bar, pointing at an icon shows the tool's name in the header
    # and its description + shortcut in the status line.
    if ($Parent -eq $tools) {
        $script:IconTips[$b] = $Tip
        $b.add_MouseEnter({ param($src, $e) Show-ToolHover $src })
        $b.add_MouseLeave({ Show-ToolHover $null })
    }
    $b
}

$script:IconTips = @{}
function Get-ToolName([string]$Tip) { (($Tip -split '  \(| - |: ')[0]).Trim() }

function Show-ToolHover($Button) {
    if ($Button -and $script:IconTips.ContainsKey($Button)) {
        $tip = $script:IconTips[$Button]
        $headerTitle.Text = Get-ToolName $tip
        $headerTitle.ForeColor = $C.Accent
        $status.Text = $tip
        $status.ForeColor = $C.Accent
    } else {
        $headerTitle.Text = 'DevTools'
        $headerTitle.ForeColor = $C.Fore
        Update-Status
    }
}

# Small icon for menu items, drawn from the icon font in a neutral grey that suits both themes.
function New-GlyphImage([string]$Icon, $Color = $null) {
    if (-not $IconFontName -or -not $Icon) { return $null }
    $size = Px 16
    $bmp = New-Object System.Drawing.Bitmap $size, $size
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.TextRenderingHint = 'AntiAliasGridFit'
    $f = New-Object System.Drawing.Font($IconFontName, (Fz 9.5))
    $brush = New-Object System.Drawing.SolidBrush $(if ($Color) { $Color } else { [System.Drawing.Color]::FromArgb(140, 140, 146) })
    $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
    $g.DrawString($Icon, $f, $brush, (New-Object System.Drawing.RectangleF(0, 0, $size, $size)), $sf)
    $g.Dispose(); $f.Dispose(); $brush.Dispose()
    $bmp
}

function Add-MenuItem($Menu, [string]$Text, [scriptblock]$OnClick, [string]$Icon = '', [string]$Keys = '') {
    $item = New-Object System.Windows.Forms.ToolStripMenuItem($Text, (New-GlyphImage $Icon), $OnClick)
    if ($Keys) { $item.ShortcutKeyDisplayString = $Keys }
    [void]$Menu.Items.Add($item)
    $item
}

# ---------------------------------------------------------------------------
# Actions
# ---------------------------------------------------------------------------
function Get-Selected {
    $i = $list.SelectedIndex
    if ($i -ge 0 -and $i -lt $script:View.Count) { return $script:View[$i] }
    $null
}

function Update-Status {
    $pinned = @($script:Items | Where-Object { $_.Pinned }).Count
    $state = if ($script:Paused) { 'PAUSED - not capturing' } else { 'Capturing' }
    $status.Text = "$state   $Dot   $($script:Items.Count) clips   $Dot   $pinned pinned"
    $status.ForeColor = if ($script:Paused) { $C.Red } else { $C.Dim }
    $count = $list.SelectedIndices.Count
    if ($count -gt 1) { $status.Text += "   $Dot   $count selected (Ctrl+D to compare)" }
    $sel = Get-Selected
    $btnPin.Text  = if ($sel -and $sel.Pinned) { 'Unpin' } else { 'Pin' }
    $btnPin.Glyph = if ($sel -and $sel.Pinned) { $Glyph.Unpin } else { $Glyph.Pin }
    $btnEdit.Text = if ($sel -and $sel.Kind -eq 'files') { 'Open' } else { 'Edit' }
    $btnEdit.Glyph = if ($sel -and $sel.Kind -eq 'files') { $Glyph.Open } else { $Glyph.Edit }
    foreach ($b in $btnPaste, $btnCopy, $btnPin, $btnEdit, $btnDelete) { $b.Enabled = [bool]$sel; $b.Invalidate() }
    if ($btnActions) {
        $smart = Get-SmartInfo $sel
        $btnActions.Enabled = [bool]($sel -and $sel.Kind -eq 'text')
        $btnActions.Text = if ($smart) { "$($smart.Badge) actions" } else { 'Actions' }
        if ($smart -and $smart.Tip -and $count -le 1) { $status.Text += "   $Dot   $($smart.Tip)" }
    }
}

function Update-List([int]$SelectIndex = -1) {
    $keep = Get-Selected
    $q = $search.Text.Trim()
    $script:View.Clear()
    foreach ($pass in $true, $false) {
        foreach ($i in $script:Items) {
            if ([bool]$i.Pinned -ne $pass) { continue }
            if ($q -and (Get-SearchText $i).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
            if ($script:Filter -eq 'Text' -and $i.Kind -and $i.Kind -ne 'text') { continue }
            if ($script:Filter -eq 'Images' -and $i.Kind -ne 'image') { continue }
            if ($script:Filter -eq 'Files' -and $i.Kind -ne 'files') { continue }
            if ($script:Filter -eq 'Pinned' -and -not $i.Pinned) { continue }
            $script:View.Add($i)
        }
    }
    $list.BeginUpdate()
    $list.Items.Clear()
    for ($n = 0; $n -lt $script:View.Count; $n++) { [void]$list.Items.Add($n) }
    if ($script:View.Count -gt 0) {
        $idx = 0
        if ($SelectIndex -ge 0) { $idx = [Math]::Min($SelectIndex, $script:View.Count - 1) }
        elseif ($keep) {
            for ($n = 0; $n -lt $script:View.Count; $n++) { if ($script:View[$n].Id -eq $keep.Id) { $idx = $n; break } }
        }
        $list.SelectedIndex = $idx
    }
    $list.EndUpdate()
    Update-EmptyHint
    Update-Status
}

function Show-Picker([switch]$FromHotkey) {
    $script:PasteTarget = [IntPtr]::Zero
    if ($FromHotkey) {
        $fg = [PowerClipHost]::GetForegroundWindow()
        if ($fg -ne $form.Handle) { $script:PasteTarget = $fg }
    }
    $search.Text = ''
    Update-List -SelectIndex 0
    $pos = [System.Windows.Forms.Cursor]::Position
    $wa  = [System.Windows.Forms.Screen]::FromPoint($pos).WorkingArea
    $x = [Math]::Max($wa.Left, [Math]::Min($pos.X - 40, $wa.Right  - $form.Width))
    $y = [Math]::Max($wa.Top,  [Math]::Min($pos.Y - 20, $wa.Bottom - $form.Height))
    $form.Location = New-Object System.Drawing.Point($x, $y)
    $form.Show()
    $form.Activate()
    [void][PowerClipHost]::SetForegroundWindow($form.Handle)
    $search.Focus()
}

function Hide-Picker { $form.Hide() }

function Invoke-Clip([bool]$Paste) {
    $item = Get-Selected
    if (-not $item) { return }
    $data = New-Object System.Windows.Forms.DataObject
    try {
        if ($item.Kind -eq 'image') {
            $path = Get-DataPath $item.Image
            $data.SetImage((Read-ImageFile $path))
            $data.SetData('PNG', (New-Object System.IO.MemoryStream(, [IO.File]::ReadAllBytes($path))))
        } elseif ($item.Kind -eq 'files') {
            $drop = New-Object System.Collections.Specialized.StringCollection
            foreach ($f in $item.Files) { [void]$drop.Add((Get-DataPath $f)) }
            $data.SetFileDropList($drop)
        } else {
            $data.SetText($item.Text, [System.Windows.Forms.TextDataFormat]::UnicodeText)
            if ($item.Html -and $item.HtmlText -ceq $item.Text) { $data.SetData([System.Windows.Forms.DataFormats]::Html, (New-CfHtml $item.Html)) }
        }
        $script:IgnoreUntil = (Get-Date).AddMilliseconds(800)
        [System.Windows.Forms.Clipboard]::SetDataObject($data, $true, 10, 50)
    } catch { Write-Log "set clipboard failed: $_"; return }
    Move-ClipToTop $item
    Save-History
    $target = $script:PasteTarget
    Hide-Picker
    if ($Paste -and $target -ne [IntPtr]::Zero) {
        [void][PowerClipHost]::SetForegroundWindow($target)
        Start-Sleep -Milliseconds 120
        [System.Windows.Forms.SendKeys]::SendWait('^v')
    }
}

function Switch-Pin {
    $sel = @(Get-SelectedAll)
    if ($sel.Count -eq 0) { return }
    $pin = -not $sel[0].Pinned
    foreach ($i in $sel) { $i.Pinned = $pin }
    Save-History
    Update-List
}

function Remove-Selected {
    $sel = @(Get-SelectedAll)
    if ($sel.Count -eq 0) { return }
    $idx = $list.SelectedIndex
    foreach ($i in $sel) { Remove-Clip $i.Id }
    Save-History
    Update-List -SelectIndex $idx
}

function Clear-Unpinned {
    $count = @($script:Items | Where-Object { -not $_.Pinned }).Count
    if ($count -eq 0) { return }
    $script:Modal = $true
    try {
        $r = [System.Windows.Forms.MessageBox]::Show($form, "Delete all $count unpinned clips? Pinned clips are kept.",
            'DevTools', 'YesNo', 'Warning')
    } finally { $script:Modal = $false }
    if ($r -eq 'Yes') {
        foreach ($i in @($script:Items | Where-Object { -not $_.Pinned })) { Remove-Clip $i.Id }
        Save-History
        Update-List -SelectIndex 0
    }
    $form.Activate()
}

# Images open in the default viewer; files are shown in Explorer.
function Open-Selected {
    $item = Get-Selected
    if (-not $item -or $item.Kind -eq 'text') { return }
    Hide-Picker
    if ($item.Kind -eq 'image') { Start-Process -FilePath (Get-DataPath $item.Image) }
    else { Start-Process explorer.exe "/select,`"$(Get-DataPath $item.Files[0])`"" }
}

function Edit-Selected {
    $item = Get-Selected
    if (-not $item) { return }
    if ($item.Kind -eq 'image') { [void](Show-ImageEditor $item); return }
    if ($item.Kind -ne 'text') { Open-Selected; return }
    $new = Show-TextEditor $item.Text 'Edit clip' $form
    if ($null -ne $new -and -not [string]::IsNullOrWhiteSpace($new) -and $new -cne $item.Text) {
        $item.Text = $new
        $item.TextDirty = $true
        Save-History
        Update-List
    }
    $form.Activate()
    $list.Focus()
}

# Multi-line text editor dialog. Returns the new text, or $null when cancelled.
function Show-TextEditor([string]$Text, [string]$Title, $Owner) {
    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text          = "$Title  (Ctrl+Enter to save)"
    $dlg.Icon          = $IconActive
    $dlg.Size          = New-Object System.Drawing.Size((Px 620), (Px 440))
    $dlg.StartPosition = 'CenterParent'
    $dlg.ShowInTaskbar = $false
    $dlg.TopMost       = $true
    $dlg.KeyPreview    = $true
    $dlg.BackColor     = $C.Panel
    $dlg.MinimizeBox   = $false

    # A RichTextBox (used as plain text) loads big texts far faster than a TextBox: 30 MB in ~1 s instead of ~15 s.
    $tb = New-Object System.Windows.Forms.RichTextBox
    $tb.AcceptsTab    = $true
    $tb.ScrollBars    = 'Both'
    $tb.WordWrap      = $true
    $tb.DetectUrls    = $false
    $tb.Dock          = 'Fill'
    $tb.BorderStyle   = 'None'
    $tb.BackColor     = $C.Bg
    $tb.ForeColor     = $C.Fore
    $tb.Font          = New-Object System.Drawing.Font('Consolas', (Fz 10.5))
    $tb.MaxLength     = [int]::MaxValue
    $tb.Text          = $Text
    $dlg.Controls.Add($tb)

    $bar = New-Object System.Windows.Forms.FlowLayoutPanel
    $bar.Dock          = 'Bottom'
    $bar.Height        = Px 44
    $bar.FlowDirection = 'RightToLeft'
    $bar.Padding       = New-Object System.Windows.Forms.Padding((Px 6))
    $dlg.Controls.Add($bar)

    $ok = New-Object PowerClipButton
    $ok.Text = 'Save'; $ok.DialogResult = 'OK'; $ok.Variant = 1; $ok.Glyph = $Glyph.Save; $ok.Font = $FontButton; $ok.AutoSize = $true
    $cancel = New-Object PowerClipButton
    $cancel.Text = 'Cancel'; $cancel.DialogResult = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true
    $bar.Controls.AddRange(@($ok, $cancel))
    $dlg.CancelButton = $cancel

    $dlg.add_KeyDown({
        param($src, $e)
        if ($e.Control -and $e.KeyCode -eq 'Return') { $dlg.DialogResult = 'OK'; $e.SuppressKeyPress = $true }
        elseif (($e.Control -and $e.KeyCode -eq 'V') -or ($e.Shift -and $e.KeyCode -eq 'Insert')) {
            # Paste as plain text so pasted formatting (colours, fonts) doesn't come along.
            $t = [System.Windows.Forms.Clipboard]::GetText()
            if ($t) { $tb.SelectedText = $t }
            $e.SuppressKeyPress = $true
        }
    })
    Register-ThemedWindow $dlg
    $dlg.add_Shown({ $tb.SelectionStart = 0; $tb.Focus() })

    $script:Modal = $true
    try { $r = $dlg.ShowDialog($Owner) } finally { $script:Modal = $false }
    $result = $null
    if ($r -eq 'OK') {
        $result = $tb.Text      # RichTextBox gives "\n" line endings; restore CRLF if the text used it
        if ($Text.Contains("`r`n")) { $result = $result -replace '(?<!\r)\n', "`r`n" }
    }
    $dlg.Dispose()
    $result
}

function Show-Message([string]$Text) {
    $script:Modal = $true
    try { [void][System.Windows.Forms.MessageBox]::Show($form, $Text, 'DevTools') } finally { $script:Modal = $false }
}

# ---------------------------------------------------------------------------
# Compare window: side-by-side diff, WinMerge style. Opens empty on demand (tray menu,
# picker button) or with two selected clips. Each side holds a clip, a file or scratch text.
# Handlers find their window's state through Form.Tag, so several can be open.
# ---------------------------------------------------------------------------

# Reads a text file the way WinMerge would: BOMs are honoured, UTF-8 is assumed, and files
# that aren't valid UTF-8 fall back to the Windows ANSI code page. Returns $null for binary files.
function Read-TextFile([string]$Path) {
    $bytes = [IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -gt $script:MaxTextMB * 1MB) { return $null }
    $hasBom = ($bytes.Length -ge 2 -and (($bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) -or ($bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF))) -or
              ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)
    if (-not $hasBom -and [Array]::IndexOf($bytes, [byte]0, 0, [Math]::Min($bytes.Length, 8000)) -ge 0) { return $null }
    $ms = New-Object System.IO.MemoryStream(, $bytes)
    $reader = New-Object System.IO.StreamReader($ms, (New-Object System.Text.UTF8Encoding($false, $true)), $true)
    try {
        $text = $reader.ReadToEnd()
        $enc = $reader.CurrentEncoding
    } catch {
        # Not valid UTF-8 (PowerShell wraps the DecoderFallbackException, so catch everything).
        $enc = [System.Text.Encoding]::Default
        $text = $enc.GetString($bytes)
    } finally { $reader.Dispose() }
    if ($enc -is [System.Text.UTF8Encoding] -and -not $hasBom) { $enc = New-Object System.Text.UTF8Encoding($false) }
    @{ Text = $text; Encoding = $enc }
}

function Get-CompareText($Item) {
    if ($Item.Kind -eq 'text') { return $Item.Text }
    if ($Item.Kind -eq 'files' -and @($Item.Files).Count -eq 1) {
        $path = Get-DataPath $Item.Files[0]
        if (-not [IO.File]::Exists($path)) { return $null }          # a folder
        $f = Read-TextFile $path
        if ($f) { return $f.Text }
    }
    $null
}

function Get-ItemLabel($Item) {
    $name = if ($Item.Kind -eq 'files') { Split-Path -Leaf (@($Item.Text -split "`n")[0]) } else { Get-Preview $Item.Text }
    if ($name.Length -gt 50) { $name = $name.Substring(0, 50) + '...' }
    "clip: $name   ($(Format-Age $Item.Time))"
}

function Get-Newline([string]$Text) {
    if ($Text.Contains("`r`n")) { return "`r`n" }
    if ($Text.Contains("`n")) { return "`n" }
    "`r`n"
}

# A side has changes worth saving only when it came from a clip or a file.
function Test-CompareDirty($St, [int]$Side) {
    [bool](($St.Items[$Side] -or $St.Paths[$Side]) -and $St.View.IsDirty($Side))
}

function Update-CompareStatus($St) {
    if (-not $St.Status) { return }
    $n = $St.View.Blocks.Count
    $St.Status.Text = if ($n -eq 0) { 'No differences' } else { "Difference $($St.View.Current + 1) of $n" }
    if ($n -gt 0 -and ($St.View.IgnoreCase -or $St.View.IgnoreWhitespace)) {
        $St.Status.Text += '   (ignoring ' + (@(if ($St.View.IgnoreCase) { 'case' }; if ($St.View.IgnoreWhitespace) { 'whitespace' }) -join ' and ') + ')'
    }
    foreach ($s in 0, 1) {
        $side = if ($s -eq 0) { 'Left' } else { 'Right' }
        $hasText = $St.View.HasText($s)
        $tooltip.SetToolTip($St["Label$s"], $(if ($St.Paths[$s]) { $St.Paths[$s] } else { '' }))
        $label = if ($St.Paths[$s]) { "file: $(Split-Path -Leaf $St.Paths[$s])" }
                 elseif ($St.Items[$s]) { Get-ItemLabel $St.Items[$s] }
                 elseif ($hasText) { 'text' }
                 else { 'empty  -  click and type, paste (Ctrl+V), open or drop a file' }
        $dirty = Test-CompareDirty $St $s
        $St["Label$s"].Text = "${side}:  $label" + $(if ($dirty) { '   * modified' } else { '' })
        $St["Save$s"].Enabled = $dirty -or (-not $St.Items[$s] -and -not $St.Paths[$s] -and $hasText)
        $St["Save$s"].Text = if ($St.Items[$s] -or $St.Paths[$s]) { 'Save' } else { 'Save as...' }
    }
    $St.Form.Text = if ($n -eq 1) { 'Compare  -  1 difference' } else { "Compare  -  $n differences" }
}

function Merge-Compare($St, [bool]$ToRight) { $St.View.CopyBlock($ToRight) }

# Puts new content into one side. Source is a clip ($Item), a file ($Path) or nothing (typed / pasted text).
function Set-CompareSide($St, [int]$Side, [string]$Text, $Item = $null, [string]$Path = $null, $Encoding = $null) {
    $St.Items[$Side] = $Item
    $St.Paths[$Side] = $Path
    $St.Enc[$Side]   = $Encoding
    $St.View.SetText($Side, $Text)
    Update-CompareStatus $St
}

function Open-CompareFile($St, [int]$Side, [string]$Path) {
    if (-not [IO.File]::Exists($Path)) { return }
    $f = Read-TextFile $Path
    if (-not $f) {
        [void][System.Windows.Forms.MessageBox]::Show($St.Form, "`"$(Split-Path -Leaf $Path)`" is not a text file, or it is bigger than $($script:MaxTextMB) MB.", 'Compare')
        return
    }
    if ((Test-CompareDirty $St $Side) -and
        [System.Windows.Forms.MessageBox]::Show($St.Form, 'This side has unsaved changes. Replace it anyway?', 'Compare', 'YesNo', 'Warning') -ne 'Yes') { return }
    Set-CompareSide $St $Side $f.Text -Path $Path -Encoding $f.Encoding
}

function Open-CompareFileDialog($St, [int]$Side) {
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Title = if ($Side -eq 0) { 'Open the left file' } else { 'Open the right file' }
    $dlg.Filter = 'All files (*.*)|*.*|Text files (*.txt;*.log;*.csv;*.json;*.xml;*.md)|*.txt;*.log;*.csv;*.json;*.xml;*.md'
    if ($dlg.ShowDialog($St.Form) -eq 'OK') { Open-CompareFile $St $Side $dlg.FileName }
    $dlg.Dispose()
}

# "From clipboard": replaces the whole side. A copied text file is opened; otherwise the clipboard text is used.
function Import-CompareClipboard($St, [int]$Side) {
    $d = [System.Windows.Forms.Clipboard]::GetDataObject()
    if (-not $d) { return }
    if ($d.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) {
        $files = [string[]]$d.GetData([System.Windows.Forms.DataFormats]::FileDrop)
        if ($files.Count -ge 1) { Open-CompareFile $St $Side $files[0] }
        return
    }
    $t = [System.Windows.Forms.Clipboard]::GetText()
    if (-not $t) { return }
    if ((Test-CompareDirty $St $Side) -and
        [System.Windows.Forms.MessageBox]::Show($St.Form, 'This side has unsaved changes. Replace it anyway?', 'Compare', 'YesNo', 'Warning') -ne 'Yes') { return }
    Set-CompareSide $St $Side $t
}

# Save: clips are updated, files are rewritten in their original encoding, other text asks for a file name.
function Save-CompareSide($St, [int]$Side, [switch]$OnlyIfDirty) {
    $item = $St.Items[$Side]
    $path = $St.Paths[$Side]
    if (($path -or $item) -and -not $St.View.IsDirty($Side)) { return }
    if ($OnlyIfDirty -and -not (Test-CompareDirty $St $Side)) { return }
    $text = $St.View.GetText($Side)
    if ($path) {
        $enc = if ($St.Enc[$Side]) { $St.Enc[$Side] } else { New-Object System.Text.UTF8Encoding($false) }
        try { [IO.File]::WriteAllText($path, $text, $enc) }
        catch { [void][System.Windows.Forms.MessageBox]::Show($St.Form, "Could not save $path`n$($_.Exception.Message)", 'Compare'); return }
    } elseif ($item) {
        $alive = $item.Kind -eq 'text' -and (Find-Clip 'text' { param($i) $i.Id -eq $item.Id })
        if ($alive) { $item.Text = $text; $item.TextDirty = $true; Save-History } else { Add-ClipText $text }
        if ($form.Visible) { Update-List }
    } else {
        $dlg = New-Object System.Windows.Forms.SaveFileDialog
        $dlg.Title = 'Save as'
        $dlg.Filter = 'Text files (*.txt)|*.txt|All files (*.*)|*.*'
        $ok = $dlg.ShowDialog($St.Form) -eq 'OK'
        $file = $dlg.FileName
        $dlg.Dispose()
        if (-not $ok) { return }
        try { [IO.File]::WriteAllText($file, $text, (New-Object System.Text.UTF8Encoding($false))) }
        catch { [void][System.Windows.Forms.MessageBox]::Show($St.Form, "Could not save $file`n$($_.Exception.Message)", 'Compare'); return }
        $St.Paths[$Side] = $file
    }
    $St.View.MarkSaved($Side)
    Update-CompareStatus $St
}

# Opens a Compare window. Both sides are optional clips; without them it starts empty.
# Both sides are editable in place: click into one and type.
# Formats both sides of a compare the same way, so key order, attribute order and layout don't show as differences.
function Invoke-CompareNormalize($St) {
    $done = @()
    foreach ($s in 0, 1) {
        $t = [string]$St.View.GetText($s)
        $x = $t.Trim()
        if (-not $x) { continue }
        try {
            if ($x[0] -eq '{' -or $x[0] -eq '[') { $out = [PowerClipFormat]::JsonSorted($x); $kind = 'JSON' }
            elseif ($x[0] -eq '<') { $out = [PowerClipFormat]::Xml($x, $true); $kind = 'XML' }
            elseif ($x -match '^(?i)(select|insert|update|delete|with|create|alter|merge)\b') { $out = [PowerClipFormat]::Sql($x); $kind = 'SQL' }
            else { $done += "$(if ($s) { 'right' } else { 'left' }): not JSON, XML or SQL"; continue }
        } catch {
            $m = if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message }
            $done += "$(if ($s) { 'right' } else { 'left' }): $m"; continue
        }
        if ($out -ne $t) { $St.View.SetText($s, $out) }
        $done += "$(if ($s) { 'right' } else { 'left' }): $kind"
    }
    if ($St.Status) { $St.Status.Text = 'Normalized  ' + ($done -join ';  ') + '   (only the view: your files and clips stay as they were)' }
}

function Show-Compare($Left = $null, $Right = $null, $HostPanel = $null) {
    $lt = if ($Left) { Get-CompareText $Left } else { '' }
    $rt = if ($Right) { Get-CompareText $Right } else { '' }
    if ($null -eq $lt -or $null -eq $rt) { Show-Message 'Only text clips and single text files can be compared.'; return }
    if (-not $HostPanel) {          # the Text tab of a new Compare window
        $h = Show-CompareHub ''
        Select-ApiTab $h.Tabs 'Text'
        $st = Show-Compare $Left $Right $h.Tabs.Panels['Text']
        Add-CompareView $h 'Text' $st.Form; $h.TextState = $st; $st.Hub = $h
        Update-CompareHubTitle $h
        return $st
    }
    Hide-Picker

    $st = @{
        Items = @($Left, $Right)
        Paths = @($null, $null)
        Enc   = @($null, $null)
    }

    $cf = New-Object System.Windows.Forms.Form
    $cf.Icon          = $IconActive
    $cf.Size          = New-Object System.Drawing.Size((Px 1150), (Px 720))
    $cf.MinimumSize   = New-Object System.Drawing.Size((Px 600), (Px 300))
    $cf.StartPosition = 'CenterScreen'
    $cf.BackColor     = $C.Panel
    $cf.ForeColor     = $C.Fore
    $cf.Font          = $FontMain
    $cf.KeyPreview    = $true
    $cf.Tag           = $st
    $st.Form = $cf
    $cf.TopLevel = $false; $cf.FormBorderStyle = 'None'; $cf.Dock = 'Fill'; $HostPanel.Controls.Add($cf)

    $view = New-Object PowerClipDiffView
    $view.UiScale = $Scale
    $view.Dock = 'Fill'
    $view.AllowDrop = $true
    $view.add_CurrentChanged({ param($src, $e) $f = $src.FindForm(); if ($f) { Update-CompareStatus $f.Tag } })
    $view.add_ContentChanged({ param($src, $e) $f = $src.FindForm(); if ($f) { Update-CompareStatus $f.Tag } })
    # Drop a file on the left or right half to open it there (two files fill both sides).
    $view.add_DragEnter({
        param($src, $e)
        $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' }
    })
    $view.add_DragDrop({
        param($src, $e)
        $files = [string[]]$e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop)
        if (-not $files) { return }
        $st = $src.FindForm().Tag
        if ($files.Count -ge 2 -and $st.Hub -and (Get-CompareKind $files[0..1]) -ne 'Text') { Open-ComparePaths $st.Hub $files[0] $files[1]; return }   # folders, images, binaries
        if ($files.Count -ge 2) { Open-CompareFile $st 0 $files[0]; Open-CompareFile $st 1 $files[1]; return }
        $x = $src.PointToClient((New-Object System.Drawing.Point($e.X, $e.Y))).X
        Open-CompareFile $st $(if ($x -lt $src.ClientSize.Width / 2) { 0 } else { 1 }) $files[0]
    })
    $cf.Controls.Add($view)
    $st.View = $view

    # One header per side: Open / From clipboard / Copy / Save, then what the side holds.
    $heads = New-Object System.Windows.Forms.TableLayoutPanel
    $heads.Dock = 'Top'
    $heads.Height = Px 36
    $heads.ColumnCount = 2
    [void]$heads.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 50)))
    [void]$heads.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 50)))
    foreach ($s in 0, 1) {
        $p = New-Object System.Windows.Forms.FlowLayoutPanel
        $p.Dock = 'Fill'; $p.WrapContents = $false; $p.Margin = New-Object System.Windows.Forms.Padding(0)
        $p.Padding = New-Object System.Windows.Forms.Padding((Px 4), (Px 2), 0, 0)
        $b = New-Button 'Open...' 'Open a file on this side (or drop a file here)' { param($src, $e) Open-CompareFileDialog $src.FindForm().Tag $src.Tag } $p
        $b.Tag = $s
        $b = New-Button 'From clipboard' 'Replace this side with the clipboard (a copied text file is opened). To paste at the cursor, use Ctrl+V.' { param($src, $e) Import-CompareClipboard $src.FindForm().Tag $src.Tag } $p
        $b.Tag = $s
        $b = New-Button 'Copy all' 'Copy this whole side to the clipboard' {
            param($src, $e)
            $t = $src.FindForm().Tag.View.GetText($src.Tag)
            if ($t) { try { [System.Windows.Forms.Clipboard]::SetDataObject($t, $true, 10, 50) } catch { } }
        } $p
        $b.Tag = $s
        $b = New-Button 'Save' 'Save this side to its clip or file (Ctrl+S saves both)' { param($src, $e) Save-CompareSide $src.FindForm().Tag $src.Tag } $p
        $b.Tag = $s
        $st["Save$s"] = $b
        $lbl = New-Object System.Windows.Forms.Label
        $lbl.AutoSize = $true
        $lbl.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 7), 0, 0)
        $p.Controls.Add($lbl)
        $st["Label$s"] = $lbl
        $heads.Controls.Add($p, $s, 0)
    }
    $cf.Controls.Add($heads)

    $tools = New-Object System.Windows.Forms.FlowLayoutPanel
    $tools.Dock = 'Top'
    $tools.Height = Px 40
    $tools.WrapContents = $false
    $tools.Padding = New-Object System.Windows.Forms.Padding((Px 4), (Px 4), 0, 0)
    [void](New-Button 'Prev diff'        'Previous difference (Alt+Up)'                 { param($src, $e) $src.FindForm().Tag.View.PrevDiff() } $tools)
    [void](New-Button 'Next diff'        'Next difference (Alt+Down)'                   { param($src, $e) $src.FindForm().Tag.View.NextDiff() } $tools)
    [void](New-Button 'Copy to right >>' 'Copy this difference to the right (Alt+Right)' { param($src, $e) Merge-Compare $src.FindForm().Tag $true } $tools)
    [void](New-Button '<< Copy to left'  'Copy this difference to the left (Alt+Left)'   { param($src, $e) Merge-Compare $src.FindForm().Tag $false } $tools)
    [void](New-Button 'Undo'             'Undo (Ctrl+Z)'                                { param($src, $e) $src.FindForm().Tag.View.Undo() } $tools)
    [void](New-Button 'Swap'             'Swap left and right'                          {
        param($src, $e)
        $st = $src.FindForm().Tag
        foreach ($k in 'Items', 'Paths', 'Enc') { $st[$k] = @($st[$k][1], $st[$k][0]) }
        $st.View.Swap()
    } $tools)
    [void](New-Button 'Normalize' 'Structured compare: format both sides the same way (JSON with sorted keys, XML with sorted attributes, SQL), so only real differences show' {
        param($src, $e) Invoke-CompareNormalize $src.FindForm().Tag
    } $tools)
    foreach ($opt in @(@('IgnoreCase', 'Ignore case'), @('IgnoreWhitespace', 'Ignore whitespace'))) {
        $cb = New-Object System.Windows.Forms.CheckBox
        $cb.Text = $opt[1]; $cb.AutoSize = $true; $cb.ForeColor = $C.Fore; $cb.Font = $FontSmall
        $cb.Margin = New-Object System.Windows.Forms.Padding((Px 12), (Px 8), 0, 0)
        $cb.Tag = $opt[0]
        $cb.add_CheckedChanged({ param($src, $e) $src.FindForm().Tag.View.($src.Tag) = $src.Checked })
        $tools.Controls.Add($cb)
    }
    $cb = New-Object System.Windows.Forms.CheckBox
    $cb.Text = 'Show whitespace'; $cb.AutoSize = $true; $cb.ForeColor = $C.Fore; $cb.Font = $FontSmall
    $cb.Margin = New-Object System.Windows.Forms.Padding((Px 12), (Px 8), 0, 0)
    $tooltip.SetToolTip($cb, 'Show spaces, tabs and line endings (CRLF / LF / CR)  -  Ctrl+W')
    $cb.add_CheckedChanged({ param($src, $e) $src.FindForm().Tag.View.ShowWhitespace = $src.Checked })
    $tools.Controls.Add($cb)
    $st.ShowWs = $cb
    $cf.Controls.Add($tools)

    $sb = New-Object System.Windows.Forms.Label
    $sb.Dock = 'Bottom'; $sb.Height = Px 24; $sb.TextAlign = 'MiddleLeft'; $sb.Font = $FontSmall
    $sb.Padding = New-Object System.Windows.Forms.Padding((Px 8), 0, 0, 0)
    $cf.Controls.Add($sb)
    $st.Status = $sb

    # Window-level keys; everything else (typing, Ctrl+C/X/V/Z/Y/A, arrows) goes to the editor.
    $cf.add_KeyDown({
        param($src, $e)
        $st = $src.Tag
        $handled = $true
        if     ($e.Alt -and $e.KeyCode -eq 'Down')  { $st.View.NextDiff() }
        elseif ($e.Alt -and $e.KeyCode -eq 'Up')    { $st.View.PrevDiff() }
        elseif ($e.Alt -and $e.KeyCode -eq 'Right') { Merge-Compare $st $true }
        elseif ($e.Alt -and $e.KeyCode -eq 'Left')  { Merge-Compare $st $false }
        elseif ($e.Control -and $e.KeyCode -eq 'S') { Save-CompareSide $st 0 -OnlyIfDirty; Save-CompareSide $st 1 -OnlyIfDirty }
        elseif ($e.Control -and $e.KeyCode -eq 'W') { $st.ShowWs.Checked = -not $st.ShowWs.Checked }
        elseif ($e.Control -and $e.KeyCode -eq 'O') { Open-CompareFileDialog $st $st.View.ActiveSide }
        else { $handled = $false }
        if ($handled) { $e.Handled = $true; $e.SuppressKeyPress = $true }
    })
    $cf.add_FormClosing({
        param($src, $e)
        $st = $src.Tag
        $dirty = @(0, 1 | Where-Object { Test-CompareDirty $st $_ })
        if ($dirty.Count -eq 0) { return }
        $r = [System.Windows.Forms.MessageBox]::Show($src, 'Save your changes?', 'Compare', 'YesNoCancel', 'Question')
        if ($r -eq 'Cancel') { $e.Cancel = $true }
        elseif ($r -eq 'Yes') { foreach ($s in $dirty) { Save-CompareSide $st $s } }
    })
    $cf.add_FormClosed({ param($src, $e) $src.Dispose() })
    Register-ThemedWindow $cf

    $cf.Show()
    $view.SetText(0, $lt)
    $view.SetText(1, $rt)
    Update-CompareStatus $st
    [void]$view.Focus()
    $st
}

function Get-SelectedAll {
    foreach ($n in $list.SelectedIndices) { if ($n -lt $script:View.Count) { $script:View[$n] } }
}

# With two clips selected they are compared; otherwise the Compare window opens empty.
function Compare-Selected {
    $sel = @(Get-SelectedAll)
    Write-Log "compare: $($sel.Count) selected"
    if ($sel.Count -lt 2) { Show-Compare; return }
    $a = $sel[0]; $b = $sel[1]
    if ($a.Time -gt $b.Time) { $t = $a; $a = $b; $b = $t }    # older on the left
    Show-Compare $a $b
}

# ---------------------------------------------------------------------------
# Folder compare: two folders as one tree, WinMerge style. The walk runs on a background
# thread (PowerClipFolderCompare); a timer picks up the result. Handlers find their window's
# state through Form.Tag / Timer.Tag, so several windows can be open.
# ---------------------------------------------------------------------------
$DirStatusText  = @('same', 'different', 'only left', 'only right', 'unreadable')
$SkipFolderNames = @('.git', '.svn', '.hg', '.vs', 'node_modules', 'bin', 'obj')

# ---------------------------------------------------------------------------
# Compare: one window with tabs for text, folders, images and any files (byte by byte).
# Text and Folders are the existing compare windows, shown inside the tab (TopLevel = false).
# ---------------------------------------------------------------------------
$CompareImageExts = @('.png', '.jpg', '.jpeg', '.jfif', '.gif', '.bmp', '.dib', '.tif', '.tiff', '.ico', '.emf', '.wmf')

function Show-CompareHub([string]$Tab = 'Text') {
    Hide-Picker
    $h = @{ Views = @{}; TextState = $null; FolderState = $null; ImageState = $null; FileState = $null }
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Compare'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px 1180), (Px 780))
    $f.MinimumSize = New-Object System.Drawing.Size((Px 640), (Px 400))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Panel; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $f.Tag = $h
    $h.Form = $f
    $set = New-TabSet $f
    $set.Hub = $h
    $h.Tabs = $set
    foreach ($n in 'Text', 'Folders', 'Images', 'Files') {
        [void](Add-ApiTab $set $n)
        $set.Buttons[$n].add_Click({ param($src, $e) Open-CompareTab $src.Tag.Set.Hub $src.Tag.Name })
    }
    $tip = New-Object System.Windows.Forms.Label
    $tip.AutoSize = $true; $tip.ForeColor = $C.Dim; $tip.Font = $FontSmall; $tip.Margin = New-Object System.Windows.Forms.Padding((Px 14), (Px 8), 0, 0)
    $tip.Text = 'Files: any two files byte by byte (binaries, archives, executables ...). Drop two folders, images or files on any tab and the right tab opens.'
    $set.Strip.Controls.Add($tip)
    # closing: the text tab may ask to save its changes first
    $f.add_FormClosing({
        param($src, $e)
        foreach ($v in @($src.Tag.Views.Values)) {
            if ($v -is [System.Windows.Forms.Form] -and -not $v.IsDisposed) { $v.Close(); if (-not $v.IsDisposed) { $e.Cancel = $true; return } }
        }
    })
    $f.add_FormClosed({
        param($src, $e)
        $hb = $src.Tag
        foreach ($s in $hb.ImageState, $hb.FileState) { if ($s) { Close-CompareExtra $s } }
        $src.Dispose()
    })
    Register-ThemedWindow $f
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $f.Activate()
    if ($Tab) { Open-CompareTab $h $Tab }
    $h
}

function Update-CompareHubTitle($H) {
    if (-not $H -or $H.Form.IsDisposed) { return }
    $v = $H.Views[$H.Tabs.Current]
    $t = switch ($H.Tabs.Current) {
        'Images' { if ($H.ImageState) { $H.ImageState.Title } }
        'Files'  { if ($H.FileState) { $H.FileState.Title } }
        default  { if ($v -is [System.Windows.Forms.Form]) { $v.Text -replace '^(Compare|Folder compare)\s*(-\s*)?', '' } }
    }
    $H.Form.Text = "Compare  -  $($H.Tabs.Current)$(if ($t) { "  -  $t" })"
}

# Shows a tab; its view is made the first time.
function Open-CompareTab($H, [string]$Name) {
    Select-ApiTab $H.Tabs $Name
    if (-not $H.Views.ContainsKey($Name)) {
        $panel = $H.Tabs.Panels[$Name]
        switch ($Name) {
            'Text'    { $st = Show-Compare $null $null $panel; Add-CompareView $H 'Text' $st.Form; $H.TextState = $st; $st.Hub = $H }
            'Folders' { $st = Show-FolderCompare '' '' $panel; Add-CompareView $H 'Folders' $st.Form; $H.FolderState = $st; $st.Hub = $H }
            'Images'  { $H.ImageState = New-ImageCompare $panel $H; $H.Views['Images'] = $H.ImageState.View }
            'Files'   { $H.FileState = New-FileCompare $panel $H; $H.Views['Files'] = $H.FileState.View }
        }
    }
    Update-CompareHubTitle $H
}

function Add-CompareView($H, [string]$Name, $Form) {
    $H.Views[$Name] = $Form
    $Form.add_TextChanged({ param($src, $e) $hb = $src.Tag.Hub; if ($hb) { Update-CompareHubTitle $hb } })
}

# What two paths are: Folders, Images, Text or Files (anything else, compared byte by byte).
function Get-CompareKind([string[]]$Paths) {
    $ps = @($Paths | Where-Object { $_ })
    if (-not $ps) { return 'Text' }
    if (@($ps | Where-Object { Test-Path -LiteralPath $_ -PathType Container }).Count -eq $ps.Count) { return 'Folders' }
    if (@($ps | Where-Object { $CompareImageExts -contains ([IO.Path]::GetExtension($_).ToLowerInvariant()) }).Count -eq $ps.Count) { return 'Images' }
    if (@($ps | Where-Object { Test-TextFile $_ }).Count -eq $ps.Count) { return 'Text' }
    'Files'
}

# A file is text when its start has no zero bytes (UTF-16 with a byte order mark counts as text).
function Test-TextFile([string]$Path) {
    try {
        $fs = [IO.File]::Open($Path, 'Open', 'Read', 'ReadWrite')
        try { $buf = New-Object byte[] 8192; $n = $fs.Read($buf, 0, $buf.Length) } finally { $fs.Dispose() }
    } catch { return $false }
    if ($n -ge 2 -and (($buf[0] -eq 0xFF -and $buf[1] -eq 0xFE) -or ($buf[0] -eq 0xFE -and $buf[1] -eq 0xFF))) { return $true }
    for ($i = 0; $i -lt $n; $i++) { if ($buf[$i] -eq 0) { return $false } }
    $true
}

# Opens two paths (either may be empty) in the fitting tab of a Compare window.
function Open-ComparePaths($H, [string]$A, [string]$B, [string]$Kind = '') {
    if (-not $Kind) { $Kind = Get-CompareKind @($A, $B) }
    Open-CompareTab $H $Kind
    switch ($Kind) {
        'Folders' { $s = $H.FolderState; $s.LeftBox.Text = $A; $s.RightBox.Text = $B; if ($A -and $B) { Start-FolderCompare $s } }
        'Images'  { if ($A) { Set-ImageCompareSide $H.ImageState 0 $A }; if ($B) { Set-ImageCompareSide $H.ImageState 1 $B } }
        'Text'    { if ($A) { Open-CompareFile $H.TextState 0 $A }; if ($B) { Open-CompareFile $H.TextState 1 $B } }
        'Files'   { Set-FileCompare $H.FileState $A $B }
    }
}

# Two files dropped on a view: both sides, or the side under the mouse.
function Get-CompareDrop($Control, $E) {
    $files = @([string[]]$E.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))
    if (-not $files) { return $null }
    $x = $Control.PointToClient((New-Object System.Drawing.Point($E.X, $E.Y))).X
    @{ Files = $files; Side = $(if ($x -lt $Control.ClientSize.Width / 2) { 0 } else { 1 }) }
}

function Close-CompareExtra($S) {
    try { if ($S.Timer) { $S.Timer.Stop(); $S.Timer.Dispose() } } catch { }
    try { if ($S.Job) { $S.Job.Cancel = $true } } catch { }
    try { foreach ($b in $S.View.LeftImage, $S.View.RightImage, $S.View.DiffImage) { if ($b) { $b.Dispose() } } } catch { }
}

# ---- Images tab
function New-ImageCompare($Panel, $H) {
    $s = @{ Hub = $H; Names = @('', ''); Title = '' }
    $v = New-Object DevImageCompareView
    $v.Dock = 'Fill'; $v.UiScale = $Scale; $v.Font = $FontMain; $v.AllowDrop = $true
    $v.Back = $C.Bg; $v.Fore = $C.Fore; $v.Dim = $C.Dim; $v.Line = $C.Line; $v.Accent = $C.Accent; $v.Red = $C.Red
    $v.Tag = $s
    $Panel.Controls.Add($v)
    $s.View = $v
    $v.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
    $v.add_DragDrop({
        param($src, $e)
        $d = Get-CompareDrop $src $e; if (-not $d) { return }
        $st = $src.Tag
        if ($d.Files.Count -ge 2) {
            if ((Get-CompareKind $d.Files[0..1]) -ne 'Images') { Open-ComparePaths $st.Hub $d.Files[0] $d.Files[1]; return }
            Set-ImageCompareSide $st 0 $d.Files[0]; Set-ImageCompareSide $st 1 $d.Files[1]
        } else { Set-ImageCompareSide $st $(if ($src.Mode -eq 0) { $d.Side } elseif (-not $src.LeftImage) { 0 } else { 1 }) $d.Files[0] }
    })
    $v.add_KeyDown({ param($src, $e) if ($e.Control -and $e.KeyCode -eq 'V') { Set-ImageCompareSide $src.Tag $(if (-not $src.LeftImage) { 0 } elseif (-not $src.RightImage) { 1 } else { 1 }) '' -Clipboard; $e.Handled = $true } })
    $v.add_HoverChanged({ param($src, $e) Update-ImageCompareStatus $src.Tag })
    $v.add_ViewChanged({ param($src, $e) Update-ImageCompareStatus $src.Tag })
    $s.Status = New-Object System.Windows.Forms.Label
    $s.Status.Dock = 'Bottom'; $s.Status.Height = $FontSmall.Height * 2 + (Px 10); $s.Status.ForeColor = $C.Dim; $s.Status.Font = $FontSmall
    $s.Status.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 3), 0, 0)
    $Panel.Controls.Add($s.Status)
    $bar = New-TbBar $Panel
    foreach ($side in 0, 1) {
        $nm = @('Left', 'Right')[$side]
        $b = New-Button "Open $($nm.ToLower())..." "Pick the $($nm.ToLower()) image" {
            param($src, $e)
            $dlg = New-Object System.Windows.Forms.OpenFileDialog
            $dlg.Filter = 'Images|*.png;*.jpg;*.jpeg;*.jfif;*.gif;*.bmp;*.tif;*.tiff;*.ico;*.emf;*.wmf|All files|*.*'
            $script:Modal = $true
            try { if ($dlg.ShowDialog($src.FindForm()) -eq 'OK') { Set-ImageCompareSide $src.Tag.S $src.Tag.Side $dlg.FileName } } finally { $script:Modal = $false; $dlg.Dispose() }
        } $bar $Glyph.Open 2
        $b.Tag = @{ S = $s; Side = $side }
        $b = New-Button "Paste $($nm.ToLower())" "Use the picture on the clipboard (e.g. a screenshot) as the $($nm.ToLower()) image" { param($src, $e) Set-ImageCompareSide $src.Tag.S $src.Tag.Side '' -Clipboard } $bar $Glyph.Paste 2
        $b.Tag = @{ S = $s; Side = $side }
    }
    $b = New-Button 'Swap' 'Swap left and right' {
        param($src, $e)
        $st = $src.Tag; $v2 = $st.View
        $t = $v2.LeftImage; $v2.LeftImage = $v2.RightImage; $v2.RightImage = $t; $st.Names = @($st.Names[1], $st.Names[0])
        $v2.Recompute(); Update-ImageCompareStatus $st
    } $bar $Glyph.Refresh 2; $b.Tag = $s
    New-TbLabel $bar 'Show' -Dim | Out-Null
    $s.ModeBox = New-TbCombo $bar @('Side by side', 'Difference (changed pixels in red)', 'Slider (drag the line)') 230
    $s.ModeBox.Tag = $s
    $s.ModeBox.add_SelectedIndexChanged({ param($src, $e) $src.Tag.View.Mode = $src.SelectedIndex; $src.Tag.View.Invalidate(); Update-ImageCompareStatus $src.Tag })
    New-TbLabel $bar 'Tolerance' -Dim | Out-Null
    $tb = New-Object System.Windows.Forms.TrackBar
    $tb.Minimum = 0; $tb.Maximum = 64; $tb.TickStyle = 'None'; $tb.Width = Px 120; $tb.AutoSize = $false; $tb.Height = Px 28; $tb.BackColor = $C.Bg
    $tb.Tag = $s
    $tb.add_ValueChanged({ param($src, $e) $src.Tag.View.Tolerance = $src.Value; $src.Tag.View.Recompute(); Update-ImageCompareStatus $src.Tag })
    $bar.Controls.Add($tb)
    $s.TolBox = $tb
    $b = New-Button 'Fit' 'Fit to the window (or double-click the picture)' { param($src, $e) $src.Tag.View.FitToWindow() } $bar '' 2; $b.Tag = $s
    $b = New-Button '100%' 'Actual size' { param($src, $e) $src.Tag.View.ZoomTo(1) } $bar '' 2; $b.Tag = $s
    Update-ImageCompareStatus $s
    $s
}

# Loads a picture (from a file, or the clipboard) into one side.
function Set-ImageCompareSide($S, [int]$Side, [string]$Path, [switch]$Clipboard) {
    try {
        if ($Clipboard) {
            $img = [System.Windows.Forms.Clipboard]::GetImage()
            if (-not $img) { $S.Status.Text = 'There is no picture on the clipboard.'; $S.Status.ForeColor = $C.Red; return }
            $bmp = New-Object System.Drawing.Bitmap($img); $img.Dispose()
            $name = "clipboard $((Get-Date).ToString('HH:mm:ss'))"
        } else {
            $bytes = [IO.File]::ReadAllBytes($Path)
            $ms = New-Object IO.MemoryStream(, $bytes)
            $img = [System.Drawing.Image]::FromStream($ms)
            $bmp = New-Object System.Drawing.Bitmap($img); $img.Dispose(); $ms.Dispose()
            $name = $Path
        }
    } catch { $S.Status.Text = "Can't open that as a picture: $($_.Exception.Message)"; $S.Status.ForeColor = $C.Red; return }
    $v = $S.View
    $old = if ($Side -eq 0) { $v.LeftImage } else { $v.RightImage }
    if ($Side -eq 0) { $v.LeftImage = $bmp } else { $v.RightImage = $bmp }
    if ($old) { $old.Dispose() }
    $S.Names[$Side] = $name
    $v.Recompute()
    if ($v.LeftImage -and $v.RightImage -and $v.Mode -eq 0 -and $v.DiffPixels -gt 0) { $S.ModeBox.SelectedIndex = 1 }    # show where they differ
    $v.FitToWindow()
    Update-ImageCompareStatus $S
}

function Update-ImageCompareStatus($S) {
    $v = $S.View
    $parts = @()
    foreach ($i in 0, 1) {
        $b = if ($i -eq 0) { $v.LeftImage } else { $v.RightImage }
        $n = if ($S.Names[$i]) { Split-Path -Leaf $S.Names[$i] } else { '' }
        $parts += if ($b) { "$(@('Left', 'Right')[$i]): $n  $($b.Width) x $($b.Height)" } else { "$(@('Left', 'Right')[$i]): (none)" }
    }
    $line1 = $parts -join "      "
    $res = ''; $color = $C.Dim
    if ($v.LeftImage -and $v.RightImage) {
        if ($v.DiffPixels -eq 0) { $res = "Identical$(if ($v.Tolerance) { " (tolerance $($v.Tolerance))" })"; $color = $C.Green }
        else {
            $pct = 100.0 * $v.DiffPixels / [Math]::Max(1, $v.TotalPixels)
            $bb = $v.DiffBounds
            $res = "$($v.DiffPixels.ToString('N0')) pixels differ ($('{0:0.###}' -f $pct)%)  in the area x $($bb.X), y $($bb.Y), $($bb.Width) x $($bb.Height)"
            if ($v.LeftImage.Width -ne $v.RightImage.Width -or $v.LeftImage.Height -ne $v.RightImage.Height) { $res += '  -  the sizes differ' }
            $color = $C.Red
        }
        $S.Title = "$(Split-Path -Leaf $S.Names[0])  <->  $(Split-Path -Leaf $S.Names[1])"
    }
    $zoom = "zoom $([int][Math]::Round($v.CurrentZoom * 100))%"
    $S.Status.Text = "$line1`r`n$(if ($res) { "$res      " })$zoom$(if ($v.HoverText) { "      $($v.HoverText)" })"
    $S.Status.ForeColor = $color
    if ($S.Hub) { Update-CompareHubTitle $S.Hub }
}

# ---- Files tab: any two files, byte by byte
function New-FileCompare($Panel, $H) {
    $s = @{ Hub = $H; Paths = @('', ''); Job = $null; Title = ''; Ranges = @() }
    $v = New-Object DevHexDiffView
    $v.Dock = 'Fill'; $v.UiScale = $Scale; $v.Font = New-Object System.Drawing.Font('Consolas', (Fz 10)); $v.AllowDrop = $true
    $v.Back = $C.Bg; $v.Fore = $C.Fore; $v.Dim = $C.Dim; $v.Line = $C.Line; $v.Accent = $C.Accent; $v.Red = $C.Red
    $v.DiffBack = [PowerClipTheme]::Mix($C.Bg, $C.Red, 0.22)
    $v.Tag = $s
    $Panel.Controls.Add($v)
    $s.View = $v
    $v.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
    $v.add_DragDrop({
        param($src, $e)
        $d = Get-CompareDrop $src $e; if (-not $d) { return }
        $st = $src.Tag
        if ($d.Files.Count -ge 2) { Set-FileCompare $st $d.Files[0] $d.Files[1] }
        else { $p = @($st.Paths); $p[$d.Side] = $d.Files[0]; Set-FileCompare $st $p[0] $p[1] }
    })
    $s.Info = New-TbRtb -ReadOnly
    $s.Info.Dock = 'Top'; $s.Info.Height = $s.Info.Font.Height * 6 + (Px 12); $s.Info.WordWrap = $true; $s.Info.ScrollBars = 'Vertical'
    $Panel.Controls.Add($s.Info)
    $bar = New-TbBar $Panel
    foreach ($side in 0, 1) {
        $nm = @('left', 'right')[$side]
        $b = New-Button "Open $nm..." "Pick the $nm file (any kind)" {
            param($src, $e)
            $dlg = New-Object System.Windows.Forms.OpenFileDialog; $dlg.Filter = 'All files|*.*'
            $script:Modal = $true
            try { if ($dlg.ShowDialog($src.FindForm()) -eq 'OK') { $st = $src.Tag.S; $p = @($st.Paths); $p[$src.Tag.Side] = $dlg.FileName; Set-FileCompare $st $p[0] $p[1] } } finally { $script:Modal = $false; $dlg.Dispose() }
        } $bar $Glyph.Open 2
        $b.Tag = @{ S = $s; Side = $side }
    }
    $b = New-Button 'Swap' 'Swap left and right' { param($src, $e) $st = $src.Tag; Set-FileCompare $st $st.Paths[1] $st.Paths[0] } $bar $Glyph.Refresh 2; $b.Tag = $s
    $b = New-Button 'Previous difference' 'Go to the previous place where they differ (Alt+Up)' { param($src, $e) Move-FileCompareDiff $src.Tag -1 } $bar '' 2; $b.Tag = $s
    $b = New-Button 'Next difference' 'Go to the next place where they differ (Alt+Down)' { param($src, $e) Move-FileCompareDiff $src.Tag 1 } $bar '' 2; $b.Tag = $s
    $b = New-Button 'Compare as text' 'Open both in the Text tab' { param($src, $e) $st = $src.Tag; Open-ComparePaths $st.Hub $st.Paths[0] $st.Paths[1] 'Text' } $bar $Glyph.Compare 2; $b.Tag = $s
    $b = New-Button 'Copy summary' 'Copy sizes, SHA-256 hashes and the result' { param($src, $e) Copy-TbText $src.Tag.Info.Text } $bar $Glyph.Copy 2; $b.Tag = $s
    $v.add_KeyDown({ param($src, $e) if ($e.Alt -and $e.KeyCode -eq 'Down') { Move-FileCompareDiff $src.Tag 1; $e.Handled = $true } elseif ($e.Alt -and $e.KeyCode -eq 'Up') { Move-FileCompareDiff $src.Tag -1; $e.Handled = $true } })
    $s.Timer = New-Object System.Windows.Forms.Timer
    $s.Timer.Interval = 150
    $s.Timer.Tag = $s
    $s.Timer.add_Tick({ param($src, $e) Update-FileCompareJob $src.Tag })
    Update-FileCompareInfo $s
    $s
}

function Set-FileCompare($S, [string]$A, [string]$B) {
    if ($S.Job) { $S.Job.Cancel = $true; $S.Job = $null }
    $S.Paths = @([string]$A, [string]$B); $S.Ranges = @()
    try { $S.View.Open($A, $B) } catch { $S.Info.Text = "Can't open: $($_.Exception.Message)"; return }
    if ($A -and $B) {
        $j = New-Object DevBinCompare
        $j.LeftPath = $A; $j.RightPath = $B
        $S.Job = $j
        $j.Start()
        $S.Timer.Start()        # the timer shows the result (also when it's already done)
    }
    $S.Title = "$(if ($A) { Split-Path -Leaf $A } else { '?' })  <->  $(if ($B) { Split-Path -Leaf $B } else { '?' })"
    Update-FileCompareInfo $S
    if ($S.Hub) { Update-CompareHubTitle $S.Hub }
}

function Update-FileCompareJob($S) {
    $j = $S.Job
    if (-not $j) { $S.Timer.Stop(); return }
    if ($j.Finished) {
        $S.Timer.Stop()
        $S.Ranges = @($j.RangesNow())
        if ($S.Ranges.Count) { $S.View.GoTo($S.Ranges[0][0], $S.Ranges[0][1]); $S.Current = 0 }
    }
    Update-FileCompareInfo $S
}

function Update-FileCompareInfo($S) {
    $r = $S.Info
    $r.Clear()
    foreach ($i in 0, 1) {
        $p = $S.Paths[$i]
        $len = if ($p -and (Test-Path -LiteralPath $p)) { (Get-Item -LiteralPath $p).Length } else { $null }
        $hash = if ($S.Job -and $S.Job.Finished) { @($S.Job.LeftHash, $S.Job.RightHash)[$i] } else { '' }
        $what = if ($p) { "$(Split-Path -Leaf $p)$(if ($null -ne $len) { "   $($len.ToString('N0')) bytes" })$(if ($hash) { "   SHA-256 $hash" })   in $(Split-Path -Parent $p)" } else { '(open a file, or drop one here)' }
        Add-RtbLine $r "$(@('Left ', 'Right')[$i])  $what" $C.Fore
    }
    $j = $S.Job
    if (-not $j) { Add-RtbLine $r 'Open two files of any kind: programs, archives, images, documents, databases ...' $C.Dim; return }
    if (-not $j.Finished) {
        $total = [Math]::Max($j.LeftLength, $j.RightLength)
        Add-RtbLine $r "Comparing... $(if ($total) { [int](100 * $j.Done / $total) } else { 0 })%" $C.Dim; return
    }
    if ($j.Error) { Add-RtbLine $r "Error: $($j.Error)" $C.Red; return }
    if ($j.DiffBytes -eq 0) { Add-RtbLine $r 'Identical: every byte is the same (same SHA-256).' $C.Green; return }
    $sizeNote = if ($j.LeftLength -ne $j.RightLength) { "  The sizes differ by $([Math]::Abs($j.LeftLength - $j.RightLength).ToString('N0')) bytes." } else { '' }
    $rs = @($j.RangesNow())
    $places = "$($rs.Count.ToString('N0'))$(if ($j.RangesCut) { '+' })"
    Add-RtbLine $r "Different: $($j.DiffBytes.ToString('N0')) bytes differ in $places place(s); the first at offset 0x$($rs[0][0].ToString('X')) ($($rs[0][0].ToString('N0'))).$sizeNote  Next / Previous difference (Alt+Down / Alt+Up) jumps between them." $C.Red
}

function Move-FileCompareDiff($S, [int]$Dir) {
    if (-not $S.Ranges.Count) { return }
    $i = if ($null -eq $S.Current) { 0 } else { $S.Current + $Dir }
    $i = [Math]::Max(0, [Math]::Min($S.Ranges.Count - 1, $i))
    $S.Current = $i
    $S.View.GoTo($S.Ranges[$i][0], $S.Ranges[$i][1]); $S.View.Invalidate()
    $S.Info.Select(0, 0)
}

# Opens two files (either may be empty) in a Compare window: text, images or byte by byte, whatever fits.
function Show-CompareFiles([string]$LeftPath, [string]$RightPath) {
    $h = Show-CompareHub ''
    Open-ComparePaths $h $LeftPath $RightPath
}

# A text box for a folder path, with a Browse button and folder drop support, in its own row.
function New-PathRow($Parent, [string]$Label, [string]$Value) {
    $row = New-Object System.Windows.Forms.FlowLayoutPanel
    $row.Dock = 'Top'; $row.Height = Px 34; $row.WrapContents = $false
    $row.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 3), 0, 0)
    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text = $Label; $lbl.AutoSize = $false; $lbl.Width = Px 56; $lbl.Height = Px 26; $lbl.TextAlign = 'MiddleLeft'
    $row.Controls.Add($lbl)
    $tb = New-Object System.Windows.Forms.TextBox
    $tb.Width = Px 760; $tb.BorderStyle = 'FixedSingle'; $tb.BackColor = $C.Bg; $tb.ForeColor = $C.Fore; $tb.Text = $Value
    $tb.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), (Px 6), 0)
    $tb.AllowDrop = $true
    $tb.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
    $tb.add_DragDrop({
        param($src, $e)
        $p = @([string[]]$e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]
        if ($p -and -not (Test-Path -LiteralPath $p -PathType Container)) { $p = Split-Path -Parent $p }
        if ($p) { $src.Text = $p }
    })
    $row.Controls.Add($tb)
    $b = New-Button 'Browse...' 'Pick a folder (or drop one on the box)' {
        param($src, $e)
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.ShowNewFolderButton = $false
        $current = $src.Tag.Text.Trim().Trim('"')
        if ($current -and (Test-Path -LiteralPath $current -PathType Container)) { $dlg.SelectedPath = $current }
        if ($dlg.ShowDialog($src.FindForm()) -eq 'OK') { $src.Tag.Text = $dlg.SelectedPath }
        $dlg.Dispose()
    } $row
    $b.Tag = $tb
    $Parent.Controls.Add($row)
    $tb
}

function New-CheckBox($Parent, [string]$Text, [bool]$Checked, [string]$Tip = '') {
    $cb = New-Object System.Windows.Forms.CheckBox
    $cb.Text = $Text; $cb.AutoSize = $true; $cb.Checked = $Checked; $cb.ForeColor = $C.Fore; $cb.Font = $FontSmall
    $cb.Margin = New-Object System.Windows.Forms.Padding((Px 12), (Px 8), 0, 0)
    if ($Tip) { $tooltip.SetToolTip($cb, $Tip) }
    $Parent.Controls.Add($cb)
    $cb
}

function New-FolderTreeNode($Entry) {
    $tn = New-Object System.Windows.Forms.TreeNode($Entry.Name)
    $tn.Tag = $Entry
    if ($Entry.IsDir -and $Entry.Children.Count -gt 0) { [void]$tn.Nodes.Add('') }     # placeholder until expanded
    $tn
}

# Children are created when a folder is first expanded, so huge trees stay fast.
function Expand-FolderNode($St, $Node) {
    if ($Node.Nodes.Count -ne 1 -or $null -ne $Node.Nodes[0].Tag) { return }
    $Node.Nodes.Clear()
    foreach ($child in $Node.Tag.Children) {
        if ($St.OnlyDiff.Checked -and $child.Status -eq 0) { continue }
        [void]$Node.Nodes.Add((New-FolderTreeNode $child))
    }
}

function Show-FolderResult($St) {
    $job = $St.Job
    $tree = $St.Tree
    $tree.BeginUpdate()
    $tree.Nodes.Clear()
    if ($job.Result) {
        $rootNode = New-FolderTreeNode $job.Result
        [void]$tree.Nodes.Add($rootNode)
        Expand-FolderNode $St $rootNode
        $rootNode.Expand()
    }
    $tree.EndUpdate()
    $St.Status.Text = "$($job.FilesDone) files   $Dot   $($job.Different) different   $Dot   $($job.OnlyLeft) only left   $Dot   $($job.OnlyRight) only right   $Dot   $($job.Same) same"
    $St.Status.ForeColor = if ($job.Different + $job.OnlyLeft + $job.OnlyRight -eq 0) { $C.Green } else { $C.Fore }
}

function Start-FolderCompare($St) {
    $l = $St.LeftBox.Text.Trim().Trim('"'); $r = $St.RightBox.Text.Trim().Trim('"')
    foreach ($p in $l, $r) {
        if (-not $p -or -not (Test-Path -LiteralPath $p -PathType Container)) {
            [void][System.Windows.Forms.MessageBox]::Show($St.Form, "Pick two existing folders.`n`"$p`" is not a folder.", 'Folder compare')
            return
        }
    }
    if ($St.Job -and -not $St.Job.Done) { $St.Job.Cancel = $true }
    $job = New-Object PowerClipFolderCompare
    $job.Left = (Resolve-Path -LiteralPath $l).ProviderPath
    $job.Right = (Resolve-Path -LiteralPath $r).ProviderPath
    $job.Contents = $St.Contents.Checked
    $job.SkipNames = if ($St.SkipJunk.Checked) { [string[]]$SkipFolderNames } else { [string[]]@() }
    $St.Job = $job
    $St.Tree.Nodes.Clear()
    $St.Status.ForeColor = $C.Fore
    $St.Status.Text = 'Comparing...'
    $St.Form.Text = "Folder compare  -  $(Split-Path -Leaf $job.Left)  <->  $(Split-Path -Leaf $job.Right)"
    $job.Start()
    $St.Timer.Start()
}

function Get-FolderSide($St, $Entry, [int]$Side) {
    $base = if ($Side -eq 0) { $St.Job.Left } else { $St.Job.Right }
    if ($Entry.Rel) { Join-Path $base $Entry.Rel } else { $base }
}

function Open-FolderEntry($St, $Entry) {
    if (-not $Entry -or $Entry.IsDir) { return }
    $lp = if ($Entry.Status -ne 3) { Get-FolderSide $St $Entry 0 } else { $null }
    $rp = if ($Entry.Status -ne 2) { Get-FolderSide $St $Entry 1 } else { $null }
    if ($St.Hub -and $lp -and $rp) { Open-ComparePaths $St.Hub $lp $rp } else { Show-CompareFiles $lp $rp }    # in this window's Text / Images / Files tab
}

# Copies a file or folder from one side to the other (overwriting), then compares again.
function Copy-FolderEntry($St, $Entry, [bool]$ToRight) {
    if (-not $Entry) { return }
    $from = Get-FolderSide $St $Entry $(if ($ToRight) { 0 } else { 1 })
    $to   = Get-FolderSide $St $Entry $(if ($ToRight) { 1 } else { 0 })
    if (-not (Test-Path -LiteralPath $from)) { return }
    $what = if ($Entry.Rel) { $Entry.Rel } else { 'the whole folder' }
    $r = [System.Windows.Forms.MessageBox]::Show($St.Form, "Copy $what to the $(if ($ToRight) { 'right' } else { 'left' }) side?`nExisting files there are overwritten.",
        'Folder compare', 'YesNo', 'Question')
    if ($r -ne 'Yes') { return }
    try {
        if ($Entry.IsDir) {
            if (Test-Path -LiteralPath $to) { Copy-Item -Path (Join-Path ([Management.Automation.WildcardPattern]::Escape($from)) '*') -Destination $to -Recurse -Force }
            else { Copy-Item -LiteralPath $from -Destination $to -Recurse -Force }
        } else {
            $parent = Split-Path -Parent $to
            if (-not (Test-Path -LiteralPath $parent)) { [void](New-Item -ItemType Directory -Path $parent -Force) }
            Copy-Item -LiteralPath $from -Destination $to -Force
        }
    } catch { [void][System.Windows.Forms.MessageBox]::Show($St.Form, "Copy failed: $($_.Exception.Message)", 'Folder compare') }
    Start-FolderCompare $St
}

function Show-FolderCompare([string]$Left = '', [string]$Right = '', $HostPanel = $null) {
    if (-not $HostPanel) {          # the Folders tab of a new Compare window
        $h = Show-CompareHub ''
        Select-ApiTab $h.Tabs 'Folders'
        $st = Show-FolderCompare $Left $Right $h.Tabs.Panels['Folders']
        Add-CompareView $h 'Folders' $st.Form; $h.FolderState = $st; $st.Hub = $h
        Update-CompareHubTitle $h
        return
    }
    Hide-Picker
    $st = @{ Job = $null }

    $ff = New-Object System.Windows.Forms.Form
    $ff.Text          = 'Folder compare'
    $ff.Icon          = $IconActive
    $ff.Size          = New-Object System.Drawing.Size((Px 1100), (Px 760))
    $ff.MinimumSize   = New-Object System.Drawing.Size((Px 600), (Px 360))
    $ff.StartPosition = 'CenterScreen'
    $ff.BackColor     = $C.Panel
    $ff.ForeColor     = $C.Fore
    $ff.Font          = $FontMain
    $ff.KeyPreview    = $true
    $ff.Tag           = $st
    $st.Form = $ff
    $ff.TopLevel = $false; $ff.FormBorderStyle = 'None'; $ff.Dock = 'Fill'; $HostPanel.Controls.Add($ff)

    $tree = New-Object System.Windows.Forms.TreeView
    $tree.Dock = 'Fill'; $tree.BorderStyle = 'None'; $tree.BackColor = $C.Bg; $tree.ForeColor = $C.Fore
    $tree.DrawMode = 'OwnerDrawText'; $tree.FullRowSelect = $true; $tree.HideSelection = $false; $tree.ShowLines = $false
    $tree.ItemHeight = Px 24; $tree.Indent = Px 18
    $ff.Controls.Add($tree)
    $st.Tree = $tree

    $tools = New-Object System.Windows.Forms.FlowLayoutPanel
    $tools.Dock = 'Top'; $tools.Height = Px 40; $tools.WrapContents = $false
    $tools.Padding = New-Object System.Windows.Forms.Padding((Px 4), (Px 4), 0, 0)
    [void](New-Button 'Compare' 'Compare the two folders (F5)' { param($src, $e) Start-FolderCompare $src.FindForm().Tag } $tools)
    [void](New-Button 'Swap' 'Swap left and right' {
        param($src, $e)
        $st = $src.FindForm().Tag
        $t = $st.LeftBox.Text; $st.LeftBox.Text = $st.RightBox.Text; $st.RightBox.Text = $t
        if ($st.Job) { Start-FolderCompare $st }
    } $tools)
    [void](New-Button 'Expand differences' 'Open every folder that has differences' {
        param($src, $e)
        $st = $src.FindForm().Tag
        $st.Tree.BeginUpdate()
        $queue = New-Object System.Collections.Generic.Queue[object]
        foreach ($tn in $st.Tree.Nodes) { $queue.Enqueue($tn) }
        $opened = 0
        while ($queue.Count -gt 0 -and $opened -lt 3000) {
            $tn = $queue.Dequeue()
            if ($tn.Tag -and $tn.Tag.IsDir -and $tn.Tag.Status -ne 0) {
                Expand-FolderNode $st $tn; $tn.Expand(); $opened++
                foreach ($child in $tn.Nodes) { $queue.Enqueue($child) }
            }
        }
        $st.Tree.EndUpdate()
    } $tools)
    $st.Contents = New-CheckBox $tools 'Compare file contents' $true 'On: files are compared byte by byte. Off: only size and date (faster).'
    $st.OnlyDiff = New-CheckBox $tools 'Only show differences' $false
    $st.SkipJunk = New-CheckBox $tools ('Skip ' + ($SkipFolderNames -join ', ')) $true
    $st.OnlyDiff.add_CheckedChanged({ param($src, $e) $st = $src.FindForm().Tag; if ($st.Job -and $st.Job.Done) { Show-FolderResult $st } })
    $ff.Controls.Add($tools)

    $paths = New-Object System.Windows.Forms.Panel
    $paths.Dock = 'Top'; $paths.Height = Px 72
    $st.RightBox = New-PathRow $paths 'Right' $Right      # rows dock to the top, so the last added sits on top
    $st.LeftBox  = New-PathRow $paths 'Left' $Left
    $ff.Controls.Add($paths)

    $sb = New-Object System.Windows.Forms.Label
    $sb.Dock = 'Bottom'; $sb.Height = Px 24; $sb.TextAlign = 'MiddleLeft'; $sb.Font = $FontSmall
    $sb.Padding = New-Object System.Windows.Forms.Padding((Px 8), 0, 0, 0)
    $sb.Text = 'Pick two folders (or drop them on the boxes) and press Compare. Double-click a file to compare it.'
    $ff.Controls.Add($sb)
    $st.Status = $sb

    $timer = New-Object System.Windows.Forms.Timer
    $timer.Interval = 200
    $timer.Tag = $st
    $timer.add_Tick({
        param($src, $e)
        $st = $src.Tag
        if (-not $st.Job.Done) { $st.Status.Text = "Comparing...   $($st.Job.FilesDone) files"; return }
        $src.Stop()
        if ($st.Job.Error) { $st.Status.Text = "Error: $($st.Job.Error)"; $st.Status.ForeColor = $C.Red } else { Show-FolderResult $st }
    })
    $st.Timer = $timer

    $tree.add_BeforeExpand({ param($src, $e) Expand-FolderNode $src.FindForm().Tag $e.Node })
    $tree.add_DrawNode({
        param($src, $e)
        $entry = $e.Node.Tag
        if (-not $entry) { return }
        $g = $e.Graphics
        $selected = ($e.State -band [System.Windows.Forms.TreeNodeStates]::Selected) -ne 0
        $row = New-Object System.Drawing.Rectangle($e.Bounds.X, $e.Bounds.Y, ($src.ClientSize.Width - $e.Bounds.X), $e.Bounds.Height)
        $brush = New-Object System.Drawing.SolidBrush $(if ($selected) { $C.Sel } else { $C.Bg })
        $g.FillRectangle($brush, $row); $brush.Dispose()
        $color = $DirStatusColor[$entry.Status]
        $name = if ($entry.IsDir) { "$($entry.Name)\" } else { $entry.Name }
        $nameColor = if ($entry.Status -eq 0) { $C.Fore } else { $color }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $name, $FontMain, $row, $nameColor, $TextFlags)
        # right side: status, then sizes / number of differences
        $info = if ($entry.IsDir) { if ($entry.DiffCount -eq 1) { '1 difference' } elseif ($entry.DiffCount -gt 1) { "$($entry.DiffCount) differences" } else { '' } }
                else { $(if ($entry.LeftSize -ge 0) { Format-Size $entry.LeftSize } else { '-' }) + '  |  ' + $(if ($entry.RightSize -ge 0) { Format-Size $entry.RightSize } else { '-' }) }
        $right = New-Object System.Drawing.Rectangle(($src.ClientSize.Width - (Px 330)), $e.Bounds.Y, (Px 320), $e.Bounds.Height)
        $flags = [System.Windows.Forms.TextFormatFlags]'Right, VerticalCenter, SingleLine, NoPrefix'
        [System.Windows.Forms.TextRenderer]::DrawText($g, $info, $FontSmall, $right, $C.Dim, $flags)
        $tagRect = New-Object System.Drawing.Rectangle(($src.ClientSize.Width - (Px 470)), $e.Bounds.Y, (Px 130), $e.Bounds.Height)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $DirStatusText[$entry.Status], $FontSmall, $tagRect, $color, $flags)
    })
    $tree.add_NodeMouseDoubleClick({ param($src, $e) Open-FolderEntry $src.FindForm().Tag $e.Node.Tag })
    $tree.add_NodeMouseClick({ param($src, $e) if ($e.Button -eq 'Right') { $src.SelectedNode = $e.Node } })
    $tree.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return' -and $src.SelectedNode) { Open-FolderEntry $src.FindForm().Tag $src.SelectedNode.Tag; $e.SuppressKeyPress = $true } })

    $tm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $tm.Tag = $st
    $tm.Items.Add('Compare these files', $null, { param($src, $e) $st = $src.Owner.Tag; Open-FolderEntry $st $st.Tree.SelectedNode.Tag }) | Out-Null
    $tm.Items.Add('-') | Out-Null
    $tm.Items.Add('Copy to the right  >>', $null, { param($src, $e) $st = $src.Owner.Tag; Copy-FolderEntry $st $st.Tree.SelectedNode.Tag $true }) | Out-Null
    $tm.Items.Add('<<  Copy to the left', $null, { param($src, $e) $st = $src.Owner.Tag; Copy-FolderEntry $st $st.Tree.SelectedNode.Tag $false }) | Out-Null
    $tm.Items.Add('-') | Out-Null
    $tm.Items.Add('Open the left one', $null, { param($src, $e) $st = $src.Owner.Tag; $p = Get-FolderSide $st $st.Tree.SelectedNode.Tag 0; if (Test-Path -LiteralPath $p) { Start-Process -FilePath $p } }) | Out-Null
    $tm.Items.Add('Open the right one', $null, { param($src, $e) $st = $src.Owner.Tag; $p = Get-FolderSide $st $st.Tree.SelectedNode.Tag 1; if (Test-Path -LiteralPath $p) { Start-Process -FilePath $p } }) | Out-Null
    $tm.Items.Add('Show left in Explorer', $null, { param($src, $e) $st = $src.Owner.Tag; $p = Get-FolderSide $st $st.Tree.SelectedNode.Tag 0; if (Test-Path -LiteralPath $p) { Start-Process explorer.exe "/select,`"$p`"" } }) | Out-Null
    $tm.Items.Add('Show right in Explorer', $null, { param($src, $e) $st = $src.Owner.Tag; $p = Get-FolderSide $st $st.Tree.SelectedNode.Tag 1; if (Test-Path -LiteralPath $p) { Start-Process explorer.exe "/select,`"$p`"" } }) | Out-Null
    $tm.add_Opening({
        param($src, $e)
        $st = $src.Tag
        $entry = if ($st.Tree.SelectedNode) { $st.Tree.SelectedNode.Tag } else { $null }
        if (-not $entry) { $e.Cancel = $true; return }
        $src.Items[0].Enabled = -not $entry.IsDir
        $src.Items[2].Enabled = $entry.Status -ne 3 -and $entry.Status -ne 0
        $src.Items[3].Enabled = $entry.Status -ne 2 -and $entry.Status -ne 0
    })
    $tree.ContextMenuStrip = $tm

    $ff.add_KeyDown({
        param($src, $e)
        if ($e.KeyCode -eq 'F5') { Start-FolderCompare $src.Tag; $e.Handled = $true }
    })
    $ff.add_FormClosed({ param($src, $e) $st = $src.Tag; $st.Timer.Stop(); if ($st.Job) { $st.Job.Cancel = $true }; $st.Timer.Dispose(); $src.Dispose() })
    Register-ThemedWindow $ff

    $ff.Show()
    if ($Left -and $Right) { Start-FolderCompare $st } else { [void]$st.LeftBox.Focus() }
    $st
}

# ---------------------------------------------------------------------------
# Find in files: every line under a folder that matches a text or regular expression.
# The search runs on a background thread (PowerClipSearch); the list is virtual and is
# filled from it by a timer, so even huge result sets stay quick.
# ---------------------------------------------------------------------------
$script:CodePath = $null

function Get-CodeEditor {
    if ($null -eq $script:CodePath) {
        $cmd = Get-Command code.cmd, code -ErrorAction SilentlyContinue | Select-Object -First 1
        $script:CodePath = if ($cmd) { $cmd.Source } else { '' }
    }
    $script:CodePath
}

function Get-SelectedHit($St) {
    if ($St.List.SelectedIndices.Count -eq 0 -or -not $St.Job) { return $null }
    $i = $St.List.SelectedIndices[0]
    if ($i -ge $St.Job.HitCount) { return $null }
    $St.Job.GetHit($i)
}

function Start-FileSearch($St) {
    $folder = $St.FolderBox.Text.Trim().Trim('"')
    if (-not $folder -or -not (Test-Path -LiteralPath $folder -PathType Container)) {
        [void][System.Windows.Forms.MessageBox]::Show($St.Form, 'Pick the folder to search in.', 'Find in files'); return
    }
    if (-not $St.FindBox.Text) { [void]$St.FindBox.Focus(); return }
    if ($St.Job -and -not $St.Job.Done) { $St.Job.Cancel = $true }
    $job = New-Object PowerClipSearch
    $job.Root = (Resolve-Path -LiteralPath $folder).ProviderPath
    $job.Pattern = $St.FindBox.Text
    $job.Filter = if ($St.FilterBox.Text.Trim()) { $St.FilterBox.Text } else { '*' }
    $job.MatchCase = $St.Case.Checked
    $job.WholeWord = $St.Word.Checked
    $job.UseRegex = $St.Regex.Checked
    $job.Subfolders = $St.Sub.Checked
    $job.SkipDirs = if ($St.SkipJunk.Checked) { [string[]]$SkipFolderNames } else { [string[]]@() }
    $job.MaxFileBytes = [long]($script:MaxTextMB * 1MB)
    $err = $job.Prepare()
    if ($err) { $St.Status.Text = "Bad regular expression: $err"; $St.Status.ForeColor = $C.Red; return }
    $St.Job = $job
    $St.List.VirtualListSize = 0
    $St.Preview.Clear()
    $St.Status.ForeColor = $C.Fore
    $St.Status.Text = 'Searching...'
    $St.Go.Text = 'Stop'
    $St.Form.Text = "Find in files  -  `"$($job.Pattern)`" in $(Split-Path -Leaf $job.Root)"
    $job.Start()
    $St.Timer.Start()
}

function Update-SearchStatus($St) {
    $job = $St.Job
    $n = $job.HitCount
    if ($St.List.VirtualListSize -ne $n) { $St.List.VirtualListSize = $n }
    if (-not $job.Done) { $St.Status.Text = "Searching...   $($job.FilesScanned) files searched   $Dot   $n matches"; return }
    $St.Timer.Stop()
    $St.Go.Text = 'Search'
    $St.Status.Text = "$n matches in $($job.FilesMatched) files   $Dot   $($job.FilesScanned) files searched" +
        $(if ($job.Cancel) { '   (stopped)' } elseif ($n -ge $job.MaxHits) { "   (stopped at $($job.MaxHits) matches)" } else { '' })
    $St.Status.ForeColor = if ($n -gt 0) { $C.Green } else { $C.Dim }
    if ($n -gt 0 -and $St.List.SelectedIndices.Count -eq 0) { $St.List.SelectedIndices.Add(0); $St.List.EnsureVisible(0) }
}

# The lines around the selected match, with the line and the match highlighted.
function Show-SearchPreview($St) {
    $hit = Get-SelectedHit $St
    $rtb = $St.Preview
    $rtb.Clear()
    if (-not $hit) { return }
    $lines = [PowerClipSearch]::ReadContext($hit.File, $hit.Line, 8, 8)
    if ($lines.Count -lt 2) { return }
    $first = [int]$lines[0]
    $sb = New-Object System.Text.StringBuilder
    for ($i = 1; $i -lt $lines.Count; $i++) { [void]$sb.Append(('{0,6}  ' -f ($first + $i - 1))).Append($lines[$i]).Append("`n") }
    $rtb.Text = $sb.ToString()
    $k = $hit.Line - $first
    $start = $rtb.GetFirstCharIndexFromLine($k)
    if ($start -lt 0) { return }
    $rtb.Select($start, $rtb.Lines[$k].Length)
    $rtb.SelectionBackColor = $C.HlLine
    $rtb.Select($start + 8 + $hit.Col, $hit.Len)
    $rtb.SelectionBackColor = $C.HlMatch
    $rtb.SelectionColor = $C.Fore
    $rtb.Select($start, 0)
    $rtb.ScrollToCaret()
}

function Open-SearchHit($St, [switch]$InEditor) {
    $hit = Get-SelectedHit $St
    if (-not $hit) { return }
    $code = Get-CodeEditor
    if ($InEditor -and $code) { Start-Process -FilePath $code -ArgumentList @('-g', "`"$($hit.File):$($hit.Line):$($hit.Col + 1)`"") -WindowStyle Hidden }
    else { Start-Process -FilePath $hit.File }
}

function Show-FindInFiles([string]$Folder = '') {
    Hide-Picker
    $st = @{ Job = $null }

    $sf = New-Object System.Windows.Forms.Form
    $sf.Text          = 'Find in files'
    $sf.Icon          = $IconActive
    $sf.Size          = New-Object System.Drawing.Size((Px 1150), (Px 800))
    $sf.MinimumSize   = New-Object System.Drawing.Size((Px 640), (Px 420))
    $sf.StartPosition = 'CenterScreen'
    $sf.BackColor     = $C.Panel
    $sf.ForeColor     = $C.Fore
    $sf.Font          = $FontMain
    $sf.KeyPreview    = $true
    $sf.Tag           = $st
    $st.Form = $sf

    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.SplitterWidth = 3
    $split.BackColor = $C.Line; $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $sf.Controls.Add($split)

    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.HideSelection = $false; $lv.MultiSelect = $false
    $lv.VirtualMode = $true; $lv.OwnerDraw = $true; $lv.BorderStyle = 'None'
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore; $lv.Font = $FontMain
    [void]$lv.Columns.Add('File', (Px 380))
    [void]$lv.Columns.Add('Line', (Px 60), 'Right')
    [void]$lv.Columns.Add('Text', (Px 1200))
    $lv.Tag = $st
    $split.Panel1.Controls.Add($lv)
    $st.List = $lv

    $rtb = New-Object System.Windows.Forms.RichTextBox
    $rtb.Dock = 'Fill'; $rtb.ReadOnly = $true; $rtb.BorderStyle = 'None'; $rtb.WordWrap = $false; $rtb.DetectUrls = $false
    $rtb.BackColor = $C.Bg; $rtb.ForeColor = $C.Fore; $rtb.Font = New-Object System.Drawing.Font('Consolas', (Fz 10))
    $split.Panel2.Controls.Add($rtb)
    $st.Preview = $rtb

    $opts = New-Object System.Windows.Forms.FlowLayoutPanel
    $opts.Dock = 'Top'; $opts.Height = Px 40; $opts.WrapContents = $false
    $opts.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 2), 0, 0)
    $fl = New-Object System.Windows.Forms.Label
    $fl.Text = 'Files'; $fl.AutoSize = $false; $fl.Width = Px 56; $fl.Height = Px 26; $fl.TextAlign = 'MiddleLeft'
    $opts.Controls.Add($fl)
    $filter = New-Object System.Windows.Forms.TextBox
    $filter.Width = Px 200; $filter.BorderStyle = 'FixedSingle'; $filter.BackColor = $C.Bg; $filter.ForeColor = $C.Fore; $filter.Text = '*'
    $filter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, 0)
    $tooltip.SetToolTip($filter, 'Which files to search, e.g.  *.cs;*.ps1;*.txt   (* = all)')
    $opts.Controls.Add($filter)
    $st.FilterBox = $filter
    $st.Case     = New-CheckBox $opts 'Match case' $false
    $st.Word     = New-CheckBox $opts 'Whole word' $false
    $st.Regex    = New-CheckBox $opts 'Regular expression' $false
    $st.Sub      = New-CheckBox $opts 'Subfolders' $true
    $st.SkipJunk = New-CheckBox $opts ('Skip ' + ($SkipFolderNames -join ', ')) $true
    $sf.Controls.Add($opts)

    $findRow = New-Object System.Windows.Forms.FlowLayoutPanel
    $findRow.Dock = 'Top'; $findRow.Height = Px 36; $findRow.WrapContents = $false
    $findRow.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 3), 0, 0)
    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text = 'Find'; $lbl.AutoSize = $false; $lbl.Width = Px 56; $lbl.Height = Px 26; $lbl.TextAlign = 'MiddleLeft'
    $findRow.Controls.Add($lbl)
    $find = New-Object System.Windows.Forms.TextBox
    $find.Width = Px 760; $find.BorderStyle = 'FixedSingle'; $find.BackColor = $C.Bg; $find.ForeColor = $C.Fore
    $find.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), (Px 6), 0)
    $findRow.Controls.Add($find)
    $st.FindBox = $find
    $st.Go = New-Button 'Search' 'Search (Enter). Stop a running search with Esc.' {
        param($src, $e)
        $st = $src.FindForm().Tag
        if ($st.Job -and -not $st.Job.Done) { $st.Job.Cancel = $true } else { Start-FileSearch $st }
    } $findRow
    $sf.Controls.Add($findRow)

    $paths = New-Object System.Windows.Forms.Panel
    $paths.Dock = 'Top'; $paths.Height = Px 36
    $st.FolderBox = New-PathRow $paths 'Folder' $Folder
    $sf.Controls.Add($paths)

    $sb = New-Object System.Windows.Forms.Label
    $sb.Dock = 'Bottom'; $sb.Height = Px 24; $sb.TextAlign = 'MiddleLeft'; $sb.Font = $FontSmall
    $sb.Padding = New-Object System.Windows.Forms.Padding((Px 8), 0, 0, 0)
    $sb.Text = 'Pick a folder, type what to find and press Enter. Double-click a match to open the file.'
    $sf.Controls.Add($sb)
    $st.Status = $sb

    $timer = New-Object System.Windows.Forms.Timer
    $timer.Interval = 250
    $timer.Tag = $st
    $timer.add_Tick({ param($src, $e) Update-SearchStatus $src.Tag })
    $st.Timer = $timer

    $lv.add_RetrieveVirtualItem({
        param($src, $e)
        $hit = $src.Tag.Job.GetHit($e.ItemIndex)
        $item = New-Object System.Windows.Forms.ListViewItem($hit.Rel)
        [void]$item.SubItems.Add([string]$hit.Line)
        [void]$item.SubItems.Add($hit.Text.Trim())
        $e.Item = $item
    })
    $lv.add_DrawColumnHeader({
        param($src, $e)
        $brush = New-Object System.Drawing.SolidBrush $C.Panel
        $e.Graphics.FillRectangle($brush, $e.Bounds); $brush.Dispose()
        $r = New-Object System.Drawing.Rectangle(($e.Bounds.X + (Px 6)), $e.Bounds.Y, ($e.Bounds.Width - (Px 10)), $e.Bounds.Height)
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $e.Header.Text, $FontSmall, $r, $C.Dim, $TextFlags)
    })
    $lv.add_DrawItem({ param($src, $e) })
    # Dark rows with the dark selection colour (the default draws a bright white selection).
    $lv.add_DrawSubItem({
        param($src, $e)
        $selected = $src.SelectedIndices.Contains($e.ItemIndex)
        $brush = New-Object System.Drawing.SolidBrush $(if ($selected) { $C.Sel } else { $C.Bg })
        $e.Graphics.FillRectangle($brush, $e.Bounds); $brush.Dispose()
        $r = New-Object System.Drawing.Rectangle(($e.Bounds.X + (Px 4)), $e.Bounds.Y, ($e.Bounds.Width - (Px 8)), $e.Bounds.Height)
        $flags = if ($e.ColumnIndex -eq 1) { [System.Windows.Forms.TextFormatFlags]'Right, VerticalCenter, SingleLine, NoPrefix, EndEllipsis' } else { $TextFlags }
        $color = if ($e.ColumnIndex -eq 0) { $C.Fore } elseif ($e.ColumnIndex -eq 1) { $C.Dim } else { $C.Fore }
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $e.SubItem.Text, $FontMain, $r, $color, $flags)
    })
    $lv.add_SelectedIndexChanged({ param($src, $e) Show-SearchPreview $src.Tag })
    $lv.add_DoubleClick({ param($src, $e) Open-SearchHit $src.Tag -InEditor })
    $lv.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Open-SearchHit $src.Tag -InEditor; $e.SuppressKeyPress = $true } })

    $lm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $lm.Tag = $st
    $miCode = $lm.Items.Add('Open in VS Code at this line', $null, { param($src, $e) Open-SearchHit $src.Owner.Tag -InEditor })
    [void]$lm.Items.Add('Open with the default app', $null, { param($src, $e) Open-SearchHit $src.Owner.Tag })
    [void]$lm.Items.Add('Open in Compare', $null, { param($src, $e) $h = Get-SelectedHit $src.Owner.Tag; if ($h) { Show-CompareFiles $h.File $null } })
    [void]$lm.Items.Add('Show in Explorer', $null, { param($src, $e) $h = Get-SelectedHit $src.Owner.Tag; if ($h) { Start-Process explorer.exe "/select,`"$($h.File)`"" } })
    [void]$lm.Items.Add('-')
    [void]$lm.Items.Add('Copy path', $null, { param($src, $e) $h = Get-SelectedHit $src.Owner.Tag; if ($h) { [System.Windows.Forms.Clipboard]::SetText($h.File) } })
    [void]$lm.Items.Add('Copy line', $null, { param($src, $e) $h = Get-SelectedHit $src.Owner.Tag; if ($h) { [System.Windows.Forms.Clipboard]::SetText($h.Text) } })
    $lm.add_Opening({
        param($src, $e)
        if (-not (Get-SelectedHit $src.Tag)) { $e.Cancel = $true; return }
        $src.Items[0].Visible = [bool](Get-CodeEditor)
    })
    $lv.ContextMenuStrip = $lm

    $find.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Start-FileSearch $src.FindForm().Tag; $e.SuppressKeyPress = $true } })
    $filter.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Start-FileSearch $src.FindForm().Tag; $e.SuppressKeyPress = $true } })
    $sf.add_KeyDown({
        param($src, $e)
        $st = $src.Tag
        if ($e.KeyCode -eq 'Escape' -and $st.Job -and -not $st.Job.Done) { $st.Job.Cancel = $true; $e.Handled = $true }
        elseif ($e.KeyCode -eq 'F5') { Start-FileSearch $st; $e.Handled = $true }
    })
    $sf.add_FormClosed({ param($src, $e) $st = $src.Tag; $st.Timer.Stop(); if ($st.Job) { $st.Job.Cancel = $true }; $st.Timer.Dispose(); $src.Dispose() })
    Register-ThemedWindow $sf
    $find.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Text to find (or a regular expression)') })

    $sf.Show()
    [PowerClipHost]::EnsureShown($sf.Handle)
    $split.SplitterDistance = [int]($split.Height * 0.62)
    $sf.Activate()
    if ($Folder) { [void]$find.Focus() } else { [void]$st.FolderBox.Focus() }
}

# Opens Transform with the selected text clip (if any) as input.
function Open-TransformFromPicker {
    $sel = Get-Selected
    $text = if ($sel -and $sel.Kind -eq 'text') { $sel.Text } else { '' }
    [void](Show-Transform $text)
}

# ---------------------------------------------------------------------------
# Transform: hex, binary, Base64, hashes, AES encryption, case changes, line tools, JSON ...
# Pick an operation on the left; the output updates as you type. "Use as input" chains steps.
# The operations themselves are in PowerClipTransform (C#).
# ---------------------------------------------------------------------------
$TransformOps = foreach ($o in [PowerClipTransform]::Ops) {
    $p = $o.Split('|')
    [pscustomobject]@{ Group = $p[0]; Name = $p[1]; Key = $p[2]; Default = $p[3] }
}

# ---- Code guides for Transform: how to do the selected operation in other languages. {T} = the input as a
#      string literal of that language, {K} = the key / password; hashes use one template with {A}.
$TransformLangs = [ordered]@{ 'C#' = 'cs'; 'PowerShell' = 'ps'; 'Python' = 'py'; 'JavaScript (Node.js)' = 'js'; 'Java' = 'java'; 'Go' = 'go'; 'Bash' = 'sh'; 'PHP' = 'php' }
$TransformCode = @{}
function Add-TransformCode([string]$Op, [hashtable]$Code) { $TransformCode[$Op] = $Code }

Add-TransformCode 'Text to hex' @{
    cs = 'using System.Text;
string hex = Convert.ToHexString(Encoding.UTF8.GetBytes({T})).ToLowerInvariant();   // .NET 5+
// older .NET: BitConverter.ToString(bytes).Replace("-", "").ToLowerInvariant()
Console.WriteLine(hex);'
    ps = '$hex = -join ([Text.Encoding]::UTF8.GetBytes({T}) | ForEach-Object { $_.ToString(''x2'') })
$hex'
    py = 'hex_text = {T}.encode("utf-8").hex()
print(hex_text)'
    js = 'const hex = Buffer.from({T}, "utf8").toString("hex");
console.log(hex);'
    java = 'import java.nio.charset.StandardCharsets;
import java.util.HexFormat;   // Java 17+

String hex = HexFormat.of().formatHex({T}.getBytes(StandardCharsets.UTF_8));
System.out.println(hex);'
    go = 'import ("encoding/hex"; "fmt")

fmt.Println(hex.EncodeToString([]byte({T})))'
    sh = 'printf ''%s'' {T} | xxd -p | tr -d ''\n''      # or: | od -An -tx1 | tr -d '' \n'''
    php = '<?php
echo bin2hex({T});'
}
