Add-TransformCode 'Base64URL encode' @{
    cs = 'using System.Text;
string b64url = Convert.ToBase64String(Encoding.UTF8.GetBytes({T})).TrimEnd(''='').Replace(''+'', ''-'').Replace(''/'', ''_'');
