Add-TransformCode 'Base64URL decode' @{
    cs = 'using System.Text;
string s = {T}.Replace(''-'', ''+'').Replace(''_'', ''/'');
s = s.PadRight(s.Length + (4 - s.Length % 4) % 4, ''='');
Console.WriteLine(Encoding.UTF8.GetString(Convert.FromBase64String(s)));'
