    $tf.StartPosition = 'CenterScreen'
    $tf.BackColor     = $C.Panel
    $tf.ForeColor     = $C.Fore
    $tf.Font          = $FontMain
    $tf.KeyPreview    = $true
    $tf.Tag           = $st
    $st.Form = $tf

    # Right: input, options, output.
