    } $sfr $Glyph.Folder 2)
    $iff.Controls.Add($sfr)
    $ChainUI.ESaveWhat = New-TbCombo $iff @('The body only', 'Status, headers and body') 230
    $ChainUI.ESaveAppend = New-CheckBox $iff 'Add to the end of the file (don''t overwrite it)' $false
    $ch2 = New-TbLabel $iff "{{timestamp}}, {{date}}, {{time}} and your {{variables}} work in the path. Without a folder it goes to Documents\DevTools API results. Saved after every run of this step." -Dim
    $ch2.MaximumSize = New-Object System.Drawing.Size((Px 470), 0)
    $ChainUI.ETabs = $etabs
    # request tab
    $rq = New-Object System.Windows.Forms.FlowLayoutPanel
    $rq.Dock = 'Fill'; $rq.FlowDirection = 'TopDown'; $rq.WrapContents = $false; $rq.BackColor = $C.Bg; $rq.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
    $pReq.Controls.Add($rq)
    New-TbLabel $rq 'Name' -Dim | Out-Null
    $ChainUI.EName = New-TbBox; $ChainUI.EName.Width = Px 470; $rq.Controls.Add($ChainUI.EName)
    New-TbLabel $rq 'Method and URL  (use {{variables}})' -Dim | Out-Null
    $mu = New-Object System.Windows.Forms.FlowLayoutPanel; $mu.AutoSize = $true; $mu.WrapContents = $false; $mu.BackColor = $C.Bg
    $ChainUI.EMethod = New-Object System.Windows.Forms.ComboBox
    $ChainUI.EMethod.DropDownStyle = 'DropDown'; $ChainUI.EMethod.FlatStyle = 'Flat'; $ChainUI.EMethod.BackColor = $C.Bg; $ChainUI.EMethod.ForeColor = $C.Fore; $ChainUI.EMethod.Width = Px 100
    foreach ($x in $ApiMethods) { [void]$ChainUI.EMethod.Items.Add($x) }
    $ChainUI.EUrl = New-TbBox -Mono; $ChainUI.EUrl.Width = Px 362
    $mu.Controls.AddRange(@($ChainUI.EMethod, $ChainUI.EUrl))
    $rq.Controls.Add($mu)
    $ChainUI.EStop = New-CheckBox $rq 'Stop the chain here if it fails (error, 4xx / 5xx, or a value not found)' $true
    $ChainUI.EStop.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $ChainUI.EAuth = New-TbLabel $rq '' -Dim
    $eb = New-Object System.Windows.Forms.FlowLayoutPanel; $eb.AutoSize = $true; $eb.WrapContents = $true; $eb.BackColor = $C.Bg; $eb.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    [void](New-Button 'Run this step' 'Send only this request, with the variables and cookies from the last run (Shift+F5)' { $n = $ChainUI.Canvas.SelectedNode; if ($n) { Start-ChainRun $n.Id } } $eb $Glyph.Play 2)
    [void](New-Button 'Open in API tester' 'Edit every detail (auth, params, form-data ...) in the API tester; then come back and press Take from API tester' {
        $n = $ChainUI.Canvas.SelectedNode; if (-not $n) { return }
        Save-ChainEditor
        Show-ApiTester; Set-ApiModel $ChainUI.Data[$n.Id].Request
    } $eb $Glyph.Globe 2)
    [void](New-Button 'Take from API tester' 'Replace this step with the request open in the API tester' {
        $n = $ChainUI.Canvas.SelectedNode; if (-not $n -or -not $ApiUI.Form) { Set-ChainStatus 'Open the API tester with the request first.' $C.Red; return }
        $m = Get-ApiModel; $m.Id = $null
        if (-not $m.Name) { $m.Name = $ChainUI.Data[$n.Id].Request.Name }
        $ChainUI.Data[$n.Id].Request = $m
        $ChainUI.EditId = $null; Show-ChainStep $n; Save-ChainEditor; Save-Chains
    } $eb $Glyph.Undo 2)
    $rq.Controls.Add($eb)
    # headers / body / extract
    $ChainUI.EHeaders = New-KvGrid $pHead 'Header' 'Value'
    $bb = New-TbBar $pBody
    New-TbLabel $bb 'Body' -Dim | Out-Null
    $ChainUI.EBodyType = New-TbCombo $bb @('none', 'JSON', 'Text', 'XML', 'Form URL-encoded', 'Form-data') 170
    New-TbLabel $bb '(form: one name=value per line)' -Dim | Out-Null
    $ChainUI.EBody = New-TbBox -Mono -Multi; $ChainUI.EBody.Dock = 'Fill'
    $pBody.Controls.Add($ChainUI.EBody); $ChainUI.EBody.BringToFront()
    $xg = New-KvGrid $pExt 'x' 'y' -ReadOnly
    $xg.ReadOnly = $false; $xg.AllowUserToAddRows = $true; $xg.AllowUserToDeleteRows = $true
    $xg.Columns.Clear()
    [void]$xg.Columns.Add('Var', 'Save as {{variable}}')
    $fc = New-Object System.Windows.Forms.DataGridViewComboBoxColumn
    $fc.HeaderText = 'From'; $fc.FlatStyle = 'Flat'; foreach ($x in $ChainExtractFrom) { [void]$fc.Items.Add($x) }
    [void]$xg.Columns.Add($fc)
    [void]$xg.Columns.Add('Expr', 'Path / name / pattern')
    $xg.Columns[0].FillWeight = 30; $xg.Columns[1].FillWeight = 22; $xg.Columns[2].FillWeight = 48
    $xg.add_DefaultValuesNeeded({ param($src, $e) $e.Row.Cells[1].Value = 'JSON path' })
    $xg.add_DataError({ param($src, $e) $e.ThrowException = $false })
    Enable-GridClipboard $xg
    $ChainUI.EExtract = $xg
    $xh = New-TbBar $pExt 'Bottom'
    $xl = New-TbLabel $xh 'JSON path: $.token, $.data.items[0].id   Header: X-Csrf-Token   Cookie: session   Regex: id="(\d+)"   Then use {{token}} in later steps.  Cookies are sent along by themselves.' -Dim
    $xl.MaximumSize = New-Object System.Drawing.Size((Px 480), 0)
    $ChainUI.GotoTable = New-Object System.Data.DataTable
    [void]$ChainUI.GotoTable.Columns.Add('Id'); [void]$ChainUI.GotoTable.Columns.Add('Name')
    $jg = New-KvGrid $pGo 'x' 'y' -ReadOnly
    $jg.ReadOnly = $false; $jg.AllowUserToAddRows = $true; $jg.AllowUserToDeleteRows = $true
    $jg.Columns.Clear()
    $jon = New-Object System.Windows.Forms.DataGridViewCheckBoxColumn
    $jon.HeaderText = ''; $jon.AutoSizeMode = 'None'; $jon.Width = Px 34; $jon.FlatStyle = 'Flat'
    [void]$jg.Columns.Add($jon)
    [void]$jg.Columns.Add('When', 'If  (empty = always)')
    $jgo = New-Object System.Windows.Forms.DataGridViewComboBoxColumn
    $jgo.HeaderText = 'Then go to'; $jgo.FlatStyle = 'Flat'; $jgo.DataSource = $ChainUI.GotoTable; $jgo.ValueMember = 'Id'; $jgo.DisplayMember = 'Name'
    [void]$jg.Columns.Add($jgo)
    [void]$jg.Columns.Add('Wait', 'Wait ms')
    $jg.Columns[1].FillWeight = 50; $jg.Columns[2].FillWeight = 38; $jg.Columns[3].FillWeight = 12
    $jg.add_DefaultValuesNeeded({ param($src, $e) $e.Row.Cells[0].Value = $true })
    $jg.add_DataError({ param($src, $e) $e.ThrowException = $false })
    $jg.add_CurrentCellDirtyStateChanged({ param($src, $e) if ($src.CurrentCell -is [System.Windows.Forms.DataGridViewCheckBoxCell] -or $src.CurrentCell -is [System.Windows.Forms.DataGridViewComboBoxCell]) { [void]$src.CommitEdit('CurrentCellChange') } })
    Enable-GridClipboard $jg
    $ChainUI.EJumps = $jg
    $jh = New-TbBar $pGo 'Bottom'
    $jl = New-TbLabel $jh "After this step has run, the first rule whose If is true decides where the chain goes next: back to a step (repeat, retry, poll until it's done), forward (the steps in between are skipped) or to the end. Same conditions as Run only if: {{lastStatus}} == 401, {{count}} >= 5, {{state}} != done. Wait ms pauses first. A step runs at most 100 times per run." -Dim
    $jl.MaximumSize = New-Object System.Drawing.Size((Px 480), 0)
    # paging
    $pgf = New-Object System.Windows.Forms.FlowLayoutPanel
    $pgf.Dock = 'Fill'; $pgf.FlowDirection = 'TopDown'; $pgf.WrapContents = $false; $pgf.AutoScroll = $true; $pgf.BackColor = $C.Bg; $pgf.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
    $pPg.Controls.Add($pgf)
    $PG = @{}
    $PG.On = New-CheckBox $pgf 'Repeat this request page by page (pagination) and collect the records' $false
    $pgRow = { $f = New-Object System.Windows.Forms.FlowLayoutPanel; $f.AutoSize = $true; $f.WrapContents = $false; $f.BackColor = $C.Bg; $pgf.Controls.Add($f); $f }
    $pgBox = { param($Row, [int]$W, [string]$Cue) $b = New-TbBox -Cue $Cue; $b.Width = Px $W; $b.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0); $Row.Controls.Add($b); $b }
    $r1 = & $pgRow; New-TbLabel $r1 'Next page by' -Dim | Out-Null
    $PG.Mode = New-TbCombo $r1 @('a number that goes up (page / offset)', 'a cursor or link from each answer') 280
    $r2 = & $pgRow; New-TbLabel $r2 'Variable  {{' -Dim | Out-Null; $PG.Var = & $pgBox $r2 80 'page'; New-TbLabel $r2 '}}  starts at' -Dim | Out-Null
    $PG.Start = & $pgBox $r2 110 '1'; $PG.StepLabel = New-TbLabel $r2 '+ each page' -Dim; $PG.Step = & $pgBox $r2 60 '1'
    $r3 = & $pgRow; New-TbLabel $r3 'Next page from' -Dim | Out-Null
    $PG.CFrom = New-TbCombo $r3 @('JSON path', 'Header', 'Link header (rel=next)', 'Regex') 170; $PG.CExpr = & $pgBox $r3 180 '$.next'
    $r4 = & $pgRow; New-TbLabel $r4 'Records at' -Dim | Out-Null; $PG.Items = & $pgBox $r4 120 '$.items'
    New-TbLabel $r4 'a full page has' -Dim | Out-Null; $PG.Size = & $pgBox $r4 60 '100'
    $r5 = & $pgRow; New-TbLabel $r5 'Also stop when' -Dim | Out-Null; $PG.Stop = & $pgBox $r5 260 '{{hasMore}} == false'
    $r6 = & $pgRow; New-TbLabel $r6 'At most' -Dim | Out-Null; $PG.Max = & $pgBox $r6 70 '10000'; New-TbLabel $r6 'pages,  wait' -Dim | Out-Null
    $PG.Delay = & $pgBox $r6 60 '0'; New-TbLabel $r6 'ms between pages,  retries on 429 / 5xx' -Dim | Out-Null; $PG.Retries = & $pgBox $r6 40 '3'
    $pgt = New-TbLabel $pgf 'Collect the records into one file' -Title; $pgt.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $r7 = & $pgRow; $PG.File = & $pgBox $r7 300 'records-{{timestamp}}.json   (empty = don''t save)'
    [void](New-Button 'Browse...' 'Pick the file' {
        $dd = New-Object System.Windows.Forms.SaveFileDialog; $dd.Filter = 'JSON|*.json|JSON lines|*.jsonl;*.ndjson|CSV|*.csv|All files|*.*'; $dd.OverwritePrompt = $false
        $script:Modal = $true
        try { if ($dd.ShowDialog($ChainUI.Form) -eq 'OK') { $ChainUI.PG.File.Text = $dd.FileName } } finally { $script:Modal = $false; $dd.Dispose() }
    } $r7 $Glyph.Folder 2)
    $PG.Format = New-TbCombo $r7 @('JSON array', 'JSON lines (a record a line)', 'CSV') 190
    $pgh = New-TbLabel $pgf "Put the variable in the URL or body, e.g.  {{baseUrl}}/records?page={{page}}&size=100  (an offset: starts at 0, + 100 each page; a cursor: ...?cursor={{cursor}} starting empty). It stops at an empty page, a page with fewer records than a full one, the stop condition or the page limit. Every page goes straight into the file, so 100,000+ records are fine; a page that is retried is written once. {{records}} and {{pages}} hold the totals afterwards; Stop keeps what was collected." -Dim
    $pgh.MaximumSize = New-Object System.Drawing.Size((Px 480), 0); $pgh.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $ChainUI.PG = $PG
    Select-ApiTab $etabs 'Request'
    $ed.Visible = $false

    # result + variables
    $rtabs = New-TabSet $right.Panel2
    $pRes = Add-ApiTab $rtabs 'Result'
    $pPick = Add-ApiTab $rtabs 'Pick a value'
    $pVars = Add-ApiTab $rtabs 'Variables & cookies'
    $pk = New-Object System.Windows.Forms.TreeView
    $pk.Dock = 'Fill'; $pk.BorderStyle = 'None'; $pk.BackColor = $C.Bg; $pk.ForeColor = $C.Fore; $pk.HideSelection = $false
    $pk.Font = New-Object System.Drawing.Font('Consolas', (Fz 10))
    $pk.add_BeforeExpand({ param($src, $e) if ($e.Node.Nodes.Count -eq 1 -and $e.Node.Nodes[0].Text -eq '') { $e.Node.Nodes.Clear(); Add-JsonTreeChildren $e.Node.Nodes $e.Node.Tag.V $e.Node.Tag.Steps } })
    $pk.add_NodeMouseDoubleClick({ param($src, $e) if ($e.Node.Tag) { Add-ChainPick $e.Node } })
    $pkm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $pkm 'Use in other steps as {{variable}}' { $n = $ChainUI.Pick.SelectedNode; if ($n) { Add-ChainPick $n } } $Glyph.Add 'double-click')
    [void](Add-MenuItem $pkm 'Copy the value' { $n = $ChainUI.Pick.SelectedNode; if ($n) { Add-ChainPick $n -ValueOnly } } $Glyph.Copy)
    $pk.ContextMenuStrip = $pkm
    $pk.add_NodeMouseClick({ param($src, $e) if ($e.Button -eq 'Right') { $src.SelectedNode = $e.Node } })
    $pPick.Controls.Add($pk)
    $pkh = New-TbBar $pPick 'Bottom'
    $pkl = New-TbLabel $pkh 'Double-click a value (token, id ...): the rule to take it is made for you and {{name}} is copied - paste it into a later step.' -Dim
    $pkl.MaximumSize = New-Object System.Drawing.Size((Px 480), 0)
    $ChainUI.Pick = $pk
    $ChainUI.Result = New-TbRtb -ReadOnly; $ChainUI.Result.Dock = 'Fill'; $ChainUI.Result.WordWrap = $true; $pRes.Controls.Add($ChainUI.Result)
    $ChainUI.VarsOut = New-TbRtb -ReadOnly; $ChainUI.VarsOut.Dock = 'Fill'; $pVars.Controls.Add($ChainUI.VarsOut)
    Select-ApiTab $rtabs 'Result'

    # left: chains (folders) above the request palette
    $left = New-Object System.Windows.Forms.SplitContainer
    $left.Dock = 'Left'; $left.Width = Px 270; $left.Orientation = 'Horizontal'; $left.SplitterWidth = 4
    $left.BackColor = $C.Line; $left.Panel1.BackColor = $C.Panel; $left.Panel2.BackColor = $C.Panel
    $ct = New-Object System.Windows.Forms.TreeView
    $ct.Dock = 'Fill'; $ct.BorderStyle = 'None'; $ct.BackColor = $C.Panel; $ct.ForeColor = $C.Fore; $ct.ItemHeight = Px 26; $ct.ShowLines = $false; $ct.FullRowSelect = $true; $ct.HideSelection = $false
    $ct.add_AfterSelect({ param($src, $e) if (-not $ChainUI.TreeLoading) { Open-ChainFromTree $e.Node } })
    $ct.add_NodeMouseClick({ param($src, $e) $src.SelectedNode = $e.Node })
    $ct.add_AfterCollapse({ param($src, $e) if (-not $ChainUI.TreeLoading -and $e.Node.Tag.Kind -eq 'folder') { [void]$ChainUI.Collapsed.Add($e.Node.Tag.Path) } })
    $ct.add_AfterExpand({ param($src, $e) if (-not $ChainUI.TreeLoading -and $e.Node.Tag.Kind -eq 'folder') { [void]$ChainUI.Collapsed.Remove($e.Node.Tag.Path) } })
    # drag a chain or folder onto a folder (DevTools' own drag, like the request list)
    $ct.add_ItemDrag({ param($src, $e) $t = $e.Item.Tag; if ($t -and ($t.Kind -eq 'chain' -or ($t.Kind -eq 'folder' -and -not $t.Examples))) { $ChainUI.TreeDrag = $t; $src.Capture = $true; $src.Cursor = [System.Windows.Forms.Cursors]::Hand } })
    $ct.add_MouseUp({
        param($src, $e)
        $d = $ChainUI.TreeDrag; $ChainUI.TreeDrag = $null
        $src.Capture = $false; $src.Cursor = [System.Windows.Forms.Cursors]::Default
        if (-not $d) { return }
        $pt = $src.PointToClient([System.Windows.Forms.Cursor]::Position)
        if (-not $src.ClientRectangle.Contains($pt)) { return }
        $target = $src.GetNodeAt($pt)
        $folder = if (-not $target) { '' } elseif ($target.Tag.Kind -eq 'folder') { $target.Tag.Path } elseif ($target.Tag.Kind -eq 'chain') { [string]$target.Tag.Chain.Folder } else { 'Examples' }
        if ($d.Kind -eq 'chain') { if ($folder -ne $d.Chain.Folder) { Move-ChainToFolder $d.Chain $folder } }
        else {
            if ($folder -eq 'Examples' -or $folder -eq $d.Path -or $folder.StartsWith("$($d.Path)/")) { return }
            $leaf = ($d.Path -split '/')[-1]
            Set-ChainFolderPath $d.Path $(if ($folder) { "$folder/$leaf" } else { $leaf })
        }
    })
    $ctm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $ctm.add_Opening({ param($src, $e) Show-ChainTreeMenu $src; if (-not $src.Items.Count) { $e.Cancel = $true } })
    $ct.ContextMenuStrip = $ctm
    $ct.add_MouseDown({ param($src, $e) if ($e.Button -eq 'Right') { $n = $src.GetNodeAt($e.Location); $ChainUI.TreeLoading = $true; $src.SelectedNode = $n; $ChainUI.TreeLoading = $false } })
    $left.Panel1.Controls.Add($ct)
    $cth = New-Object System.Windows.Forms.Label
    $cth.Text = '  CHAINS  (right-click for folders)'; $cth.Dock = 'Top'; $cth.Height = Px 28; $cth.TextAlign = 'MiddleLeft'; $cth.Font = $FontSmall; $cth.ForeColor = $C.Accent
    $left.Panel1.Controls.Add($cth)
    $ChainUI.Tree = $ct
    $pal = New-Object System.Windows.Forms.TreeView
    $pal.Dock = 'Fill'; $pal.BorderStyle = 'None'; $pal.BackColor = $C.Panel; $pal.ForeColor = $C.Fore; $pal.ItemHeight = Px 26; $pal.ShowLines = $false; $pal.FullRowSelect = $true
    $pal.add_MouseDown({
        param($src, $e)
        $ChainUI.PalDrag = $null
        if ($e.Button -ne 'Left') { return }
        $n = $src.GetNodeAt($e.Location)
        if ($n -and $n.Tag -and [string]$n.Tag -match '^(ex|chain):') { $src.SelectedNode = $n; $ChainUI.PalOpen = $n; [void]$src.BeginInvoke([System.Action]{ $x = $ChainUI.PalOpen; $ChainUI.PalOpen = $null; Open-ChainPaletteNode $x }); return }
        if ($n -and $n.Tag) { $src.SelectedNode = $n; $ChainUI.PalDrag = @{ Tag = [string]$n.Tag; From = $e.Location; On = $false; Text = $n.Text } }
    })
    # the tree view reports a drag here (its MouseDown can come late); start DevTools' own drag
    $pal.add_ItemDrag({ param($src, $e) if ($e.Item.Tag -and [string]$e.Item.Tag -notmatch '^(ex|chain):') { $src.SelectedNode = $e.Item; $ChainUI.PalDrag = @{ Tag = [string]$e.Item.Tag; From = $src.PointToClient([System.Windows.Forms.Cursor]::Position); On = $true; Text = $e.Item.Text }; $src.Capture = $true } })
    $pal.add_MouseMove({
        param($src, $e)
        $d = $ChainUI.PalDrag
        if (-not $d -or $e.Button -ne 'Left') { return }
        if (-not $d.On -and ([Math]::Abs($e.X - $d.From.X) + [Math]::Abs($e.Y - $d.From.Y)) -gt (Px 6)) { $d.On = $true; $src.Capture = $true }
        if ($d.On) {
            $cv2 = $ChainUI.Canvas
            $over = $cv2.ClientRectangle.Contains($cv2.PointToClient([System.Windows.Forms.Cursor]::Position))
            $src.Cursor = if ($over) { [System.Windows.Forms.Cursors]::Hand } else { [System.Windows.Forms.Cursors]::No }
            Set-ChainStatus $(if ($over) { "Release to add: $($d.Text)" } else { "Drag onto the canvas: $($d.Text)" }) $C.Accent
        }
    })
    $pal.add_MouseUp({
        param($src, $e)
        $d = $ChainUI.PalDrag; $ChainUI.PalDrag = $null
        $src.Cursor = [System.Windows.Forms.Cursors]::Default; $src.Capture = $false
        if (-not $d -or -not $d.On) { return }
        $cv2 = $ChainUI.Canvas
        $pt = $cv2.PointToClient([System.Windows.Forms.Cursor]::Position)
        if (-not $cv2.ClientRectangle.Contains($pt)) { Set-ChainStatus 'Not added - release it over the canvas (or double-click the item).' $C.Dim; return }
        $p = $cv2.ToCanvas($pt)
        $cv2.SelectedNode = $null             # dropping doesn't link by itself; drag the dot for that
        Add-ChainFromPalette $d.Tag ($p.X - $cv2.NodeW / 2) ($p.Y - $cv2.NodeH / 2)
        Set-ChainStatus "Added: $($d.Text)" $C.Green
    })
    $pal.add_NodeMouseDoubleClick({ param($src, $e) if ($e.Node.Tag -and [string]$e.Node.Tag -notmatch '^(ex|chain):') { Add-ChainFromPalette ([string]$e.Node.Tag) } })
    $pm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $pm.add_Opening({ param($src, $e) Show-ChainPaletteMenu $src; if (-not $src.Items.Count) { $e.Cancel = $true } })
    $pal.ContextMenuStrip = $pm
    $pal.add_MouseUp({ param($src, $e) if ($e.Button -eq 'Right') { $src.SelectedNode = $src.GetNodeAt($e.Location) } })
    $left.Panel2.Controls.Add($pal)
    $lh = New-Object System.Windows.Forms.Label
    $lh.Text = '  EXAMPLES & REQUESTS (drag onto canvas)'; $lh.AutoEllipsis = $true; $lh.UseMnemonic = $false; $lh.Dock = 'Top'; $lh.Height = Px 28; $lh.TextAlign = 'MiddleLeft'; $lh.Font = $FontSmall; $lh.ForeColor = $C.Accent
    $left.Panel2.Controls.Add($lh)
    $f.Controls.Add($left)
    if ($ChainUI.LeftWidth) { $left.Width = $ChainUI.LeftWidth }
    $lsp = New-Object System.Windows.Forms.Splitter
    $lsp.Dock = 'Left'; $lsp.Width = Px 5; $lsp.BackColor = $C.Line; $lsp.MinSize = Px 160; $lsp.MinExtra = Px 300
    $lsp.add_SplitterMoved({ $ChainUI.LeftWidth = $ChainUI.LeftSplit.Width })
    $f.Controls.Add($lsp); $f.Controls.SetChildIndex($lsp, $f.Controls.GetChildIndex($left))   # docks right of the left panel
    $ChainUI.LeftSplit = $left
    $ChainUI.LeftReady = $false
    $left.add_SplitterMoved({ param($src, $e) if ($ChainUI.LeftReady -and $src.Height -gt 0) { $ChainUI.LeftRatio = $src.SplitterDistance / $src.Height } })
    $ChainUI.Palette = $pal

    # canvas
    $cv = New-Object DevChainCanvas
    $cv.Dock = 'Fill'; $cv.UiScale = $Scale * $TextZoom; $cv.Font = $FontMain; $cv.AllowDrop = $true
    $cv.Back = $C.Bg; $cv.GridDot = $C.Line; $cv.Card = $C.Card; $cv.Fore = $C.Fore; $cv.Dim = $C.Dim; $cv.Line = $C.Line; $cv.Accent = $C.Accent; $cv.Green = $C.Green; $cv.Red = $C.Red; $cv.Yellow = $C.Yellow
    $cv.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop) -or $e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::UnicodeText)) { [System.Windows.Forms.DragDropEffects]::Copy } else { [System.Windows.Forms.DragDropEffects]::None } })
    $cv.add_DragOver({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop) -or $e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::UnicodeText)) { [System.Windows.Forms.DragDropEffects]::Copy } else { [System.Windows.Forms.DragDropEffects]::None } })
    $cv.add_DragDrop({
        param($src, $e)
        $p = $src.ToCanvas($src.PointToClient((New-Object System.Drawing.Point($e.X, $e.Y))))
        Add-ChainDrop $e.Data ($p.X - $src.NodeW / 2) ($p.Y - $src.NodeH / 2)
    })
    $cv.add_SelectionChanged({
        param($src, $e)
        Show-ChainStep $src.SelectedNode
        $k = $src.Selection.Count
        if ($k -gt 1) { Set-ChainStatus "$k cards selected  -  Shift+F5 runs only these, drag one to move them together, Del deletes them, Ctrl+C copies them." $C.Accent }
        elseif ($ChainUI.Status -and $ChainUI.Status.Text -match '^\d+ cards selected') { Set-ChainStatus 'Ctrl+click, or double-click empty space and drag a box, to select several cards.' $C.Dim }
    })
    $cv.add_Changed({ param($src, $e) Update-ChainOrder; Save-Chains })
    $cv.add_NodeOpen({ Select-ApiTab $ChainUI.ETabs 'Request'; [void]$ChainUI.EUrl.Focus() })
    $cm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $cm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $cv2 = $ChainUI.Canvas
        $pt = $cv2.ToCanvas($cv2.PointToClient([System.Windows.Forms.Cursor]::Position))
        $src.Tag = $pt
        $add = New-Object System.Windows.Forms.ToolStripMenuItem('Add a request here', (New-GlyphImage $Glyph.Add))
        foreach ($k in (Get-ChainTemplates).Keys) { $it = $add.DropDownItems.Add($k, $null, { param($s2, $e2) $p = $s2.OwnerItem.Owner.Tag; Add-ChainFromPalette $s2.Tag ($p.X) ($p.Y) }); $it.Tag = "tpl:$k" }
        if ($ApiUI.Collections.Count) { [void]$add.DropDownItems.Add('-') }
        foreach ($m in $ApiUI.Collections) { $it = $add.DropDownItems.Add("$($m.Method)  $($m.Folder) / $($m.Name)", $null, { param($s2, $e2) $p = $s2.OwnerItem.Owner.Tag; Add-ChainFromPalette $s2.Tag ($p.X) ($p.Y) }); $it.Tag = "req:$($m.Id)" }
        $add.DropDown.Renderer = $MenuRenderer
        [void]$src.Items.Add($add)
        $pp = Get-RequestPart
        $clipText = ''; try { $clipText = [System.Windows.Forms.Clipboard]::GetText() } catch { }
        if (($pp -and $pp.DevToolsRequestPart -in 'request', 'requests') -or $clipText -match '^\s*(curl\s|https?://)') {
            [void](Add-MenuItem $src $(if ($pp -and $pp.DevToolsRequestPart -eq 'requests') { "Paste the $(@($pp.Items).Count) copied cards here" } elseif ($pp) { 'Paste the copied request here' } else { 'Paste (curl command / link) here' }) { param($s2, $e2) $p = $s2.Owner.Tag; $ChainUI.Canvas.SelectedNode = $null; Invoke-ChainPaste ($p.X) ($p.Y) } $Glyph.Paste 'Ctrl+V')
        }
        if ($cv2.Selection.Count -gt 1) {
            [void](Add-MenuItem $src "Run the $($cv2.Selection.Count) selected cards" { Start-ChainRunSelected } $Glyph.Play 'Shift+F5')
            [void](Add-MenuItem $src "Copy $($cv2.Selection.Count) cards" { Copy-ChainCards } $Glyph.Copy 'Ctrl+C')
            [void](Add-MenuItem $src "Delete $($cv2.Selection.Count) cards" { $ChainUI.Canvas.RemoveSelected() } $Glyph.Delete 'Del')
            [void](Add-MenuItem $src 'Select all' { $ChainUI.Canvas.SelectAll() } '' 'Ctrl+A')
        } elseif ($cv2.SelectedNode) {
            [void](Add-MenuItem $src 'Run this step' { Start-ChainRun $ChainUI.Canvas.SelectedNode.Id } $Glyph.Play)
            Add-ChainCopyMenu $src $cv2.SelectedNode
            [void](Add-MenuItem $src 'Duplicate' { $n = $ChainUI.Canvas.SelectedNode; $m = $ChainUI.Data[$n.Id].Request | ConvertTo-Json -Depth 6 | ConvertFrom-Json; $sel = $ChainUI.Canvas.SelectedNode; $ChainUI.Canvas.SelectedNode = $null; $x = Add-ChainStep $m ($sel.X + (Px 30)) ($sel.Y + (Px 100)); foreach ($r in $ChainUI.Data[$sel.Id].Extract) { $ChainUI.Data[$x.Id].Extract.Add($r) }; Save-Chains } $Glyph.Copy)
            [void](Add-MenuItem $src 'Delete' { $ChainUI.Canvas.RemoveSelected() } $Glyph.Delete 'Del')
        } elseif ($cv2.SelectedLink) { [void](Add-MenuItem $src 'Delete arrow' { $ChainUI.Canvas.RemoveSelected() } $Glyph.Delete 'Del') }
    })
    $cv.ContextMenuStrip = $cm
    $f.Controls.Add($cv)
    $cv.BringToFront()
    $ChainUI.Canvas = $cv

    # top bar
    $top = New-Object System.Windows.Forms.FlowLayoutPanel
    $top.Dock = 'Top'; $top.AutoSize = $true; $top.WrapContents = $true; $top.BackColor = $C.Panel
    $top.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 4))
    $ChainUI.ChainBox = New-TbCombo $top @() 220
    $ChainUI.ChainBox.Visible = $false                 # the chains tree on the left does this now
    $ChainUI.ChainBox.add_SelectedIndexChanged({ param($src, $e) if ($ChainUI.Loading -or $src.SelectedIndex -lt 0) { return }; Save-ChainEditor; Save-Chains; Open-Chain $ChainUI.Chains[$src.SelectedIndex] })
    [void](New-Button 'New chain' 'New chain in the selected folder' { New-ChainInFolder (Get-SelectedChainFolder) } $top $Glyph.Add 2)
    [void](New-Button 'New folder' 'New folder (inside the selected folder)' { New-ChainFolder (Get-SelectedChainFolder) } $top $Glyph.Folder 2)
    [void](New-Button 'Rename' 'Rename this chain' { $c = $ChainUI.Current; $n = Read-TextDialog 'Rename chain' 'Name' $c.Name $ChainUI.Form; if ($n) { $c.Name = $n.Trim(); Update-ChainCombo; Save-Chains } } $top $Glyph.Edit 2)
    [void](New-Button 'Delete' 'Delete this chain' {
        $c = $ChainUI.Current
        if ([System.Windows.Forms.MessageBox]::Show($ChainUI.Form, "Delete the chain $($c.Name)?", 'API chains', 'YesNo', 'Warning') -ne 'Yes') { return }
        [void]$ChainUI.Chains.Remove($c)
        if (-not $ChainUI.Chains.Count) { $ChainUI.Chains.Add((New-ChainRecord 'My chain')) }
        $ChainUI.EditId = $null
        Open-Chain $ChainUI.Chains[0]; Update-ChainCombo; Save-Chains
    } $top $Glyph.Delete 2)
    $ChainUI.RunBtn = New-Button 'Run chain' 'Run every step in order (F5). Steps after a failed step are skipped.' { Start-ChainRun } $top $Glyph.Play 1
    [void](New-Button 'Run selected' 'Run only the selected cards, in chain order, with the variables and cookies of the last run (Shift+F5)' { Start-ChainRunSelected } $top $Glyph.Play 2)
    [void](New-Button 'Variables...' 'Start values for {{variables}}, e.g. baseUrl, user, password' { Show-ChainVarsDialog } $top $Glyph.Code 2)
    New-TbLabel $top '  Environment' -Dim | Out-Null
    $ChainUI.EnvBox = New-TbCombo $top @(@('(none)') + @($ApiUI.Environments | ForEach-Object { [string]$_.Name })) 150
    $ChainUI.EnvBox.SelectedIndex = [math]::Max(0, @($ApiUI.Environments | ForEach-Object { [string]$_.Name }).IndexOf([string]$ApiUI.EnvName) + 1)
    $ChainUI.EnvBox.add_SelectedIndexChanged({ param($src, $e) $ApiUI.EnvName = if ($src.SelectedIndex -le 0) { '' } else { [string]$src.SelectedItem }; if ($ApiUI.EnvBox -and -not $ApiUI.EnvBox.IsDisposed) { Update-ApiEnvCombo } })
    $ChainUI.AutoCookies = New-CheckBox $top 'Send cookies along' $true 'Cookies a response sets are sent with the next requests to the same site (like a browser)'
    $ChainUI.AutoCookies.add_CheckedChanged({ param($src, $e) if ($ChainUI.Current -and -not $ChainUI.Loading) { $ChainUI.Current.AutoCookies = $src.Checked; Save-Chains } })
    [void](New-Button 'Add request' 'Add an empty request after the selected one' { Add-ChainFromPalette 'tpl:New empty request' } $top $Glyph.Add 2)
    [void](New-Button 'Arrange' 'Line the cards up in run order (mouse wheel or middle-button drag scrolls the canvas)' { Invoke-ChainArrange } $top $Glyph.Apps 2)
    [void](New-Button 'Examples' 'Ready-made chains to learn from: log in -> token, session cookie, create and read, headers / regex / status' { param($src, $e) Show-ChainExampleMenu $src } $top $Glyph.Lightning 2)
    [void](New-Button 'Share' 'Export this chain for a colleague, or import one' { param($src, $e) Show-ChainShareMenu $src } $top $Glyph.Send 2)
    $ChainUI.TestApiBtn = New-Button 'Test API' 'A practice API on this PC: log in, token, cookie, CSRF, items. No internet needed.' { param($src, $e) Show-TestApiMenu $src } $top $Glyph.Network 2
    $f.Controls.Add($top)

    $status = New-Object System.Windows.Forms.Label
    $status.Dock = 'Bottom'; $status.Height = $FontMain.Height + (Px 10); $status.TextAlign = 'MiddleLeft'; $status.ForeColor = $C.Dim; $status.BackColor = $C.Panel
    $status.Padding = New-Object System.Windows.Forms.Padding((Px 10), 0, 0, 0)
    $f.Controls.Add($status)
    $ChainUI.Status = $status

    # editing writes back to the card and is saved shortly after
    $ChainUI.SaveTimer = New-Object System.Windows.Forms.Timer
    $ChainUI.SaveTimer.Interval = 800
    $ChainUI.SaveTimer.add_Tick({ $ChainUI.SaveTimer.Stop(); Save-Chains })
    foreach ($ctl in $ChainUI.EName, $ChainUI.EUrl, $ChainUI.EBody) { $ctl.add_TextChanged({ Start-ChainEditorSave }) }
    $ChainUI.EMethod.add_TextChanged({ Start-ChainEditorSave })
    $ChainUI.EBodyType.add_SelectedIndexChanged({ Start-ChainEditorSave })
    $ChainUI.EStop.add_CheckedChanged({ Start-ChainEditorSave })
    foreach ($ctl in $ChainUI.ECond, $ChainUI.ESave) { $ctl.add_TextChanged({ Start-ChainEditorSave }) }
    $ChainUI.EAfterFail.add_CheckedChanged({ Start-ChainEditorSave }); $ChainUI.ESaveAppend.add_CheckedChanged({ Start-ChainEditorSave })
    $ChainUI.ESaveWhat.add_SelectedIndexChanged({ Start-ChainEditorSave })
    $ChainUI.EHeaders.add_CellEndEdit({ Start-ChainEditorSave })
    $ChainUI.EExtract.add_CellEndEdit({ Start-ChainEditorSave })
    $ChainUI.EJumps.add_CellValueChanged({ Start-ChainEditorSave }); $ChainUI.EJumps.add_UserDeletedRow({ Start-ChainEditorSave })
    foreach ($k in 'Var', 'Start', 'Step', 'CExpr', 'Items', 'Size', 'Stop', 'Max', 'Delay', 'Retries', 'File') { $ChainUI.PG[$k].add_TextChanged({ Start-ChainEditorSave }) }
    foreach ($k in 'Mode', 'CFrom', 'Format') { $ChainUI.PG[$k].add_SelectedIndexChanged({ Start-ChainEditorSave }) }
    $ChainUI.PG.On.add_CheckedChanged({ Start-ChainEditorSave })
    $ChainUI.EExtract.add_UserDeletedRow({ Start-ChainEditorSave })
    $ChainUI.EHeaders.add_UserDeletedRow({ Start-ChainEditorSave })

    $ChainUI.Timer = New-Object System.Windows.Forms.Timer
    $ChainUI.Timer.Interval = 100
    $ChainUI.Timer.add_Tick({
        $r = $ChainUI.Run
        if ($r -and $r.WaitUntil) { if ((Get-Date) -ge $r.WaitUntil) { $r.WaitUntil = $null; $ChainUI.Timer.Stop(); Invoke-ChainNext } }
        else { Complete-ChainStep }
    })

    $f.add_KeyDown({
        param($src, $e)
        if ($e.KeyCode -eq 'F5' -and $e.Shift) { Start-ChainRunSelected; $e.Handled = $true }
        elseif ($e.KeyCode -eq 'F5') { Start-ChainRun; $e.Handled = $true }
        elseif ($ChainUI.Canvas.Focused -and $e.Control -and $e.KeyCode -eq 'C' -and $ChainUI.Canvas.Selection.Count) {
            Copy-ChainCards
            $e.Handled = $true; $e.SuppressKeyPress = $true
        }
        elseif ($ChainUI.Canvas.Focused -and $e.Control -and $e.KeyCode -eq 'V') {
            $sel = $ChainUI.Canvas.SelectedNode
            if ($sel) { $ChainUI.Canvas.SelectedNode = $null; Invoke-ChainPaste ($sel.X + (Px 30)) ($sel.Y + $ChainUI.Canvas.NodeH + (Px 30)) } else { Invoke-ChainPaste }
            $e.Handled = $true; $e.SuppressKeyPress = $true
        }
    })
    $f.add_FormClosing({ Save-ChainEditor; Save-Chains; Stop-ChainRun })
    $f.add_FormClosed({ param($src, $e) $ChainUI.Form = $null; $ChainUI.Canvas = $null; $ChainUI.EditId = $null; $ChainUI.Timer.Dispose(); $ChainUI.SaveTimer.Dispose(); $src.Dispose() })
    Register-ThemedWindow $f

    Update-ChainPalette
    $ChainUI.Current = @($ChainUI.Chains | Where-Object { -not (Test-ChainIsExample $_) })[0]   # one of your chains, not an example
    if (-not $ChainUI.Current) { $ChainUI.Current = $ChainUI.Chains[0] }
    $f.add_Shown({ $l = $ChainUI.LeftSplit; $q = if ($ChainUI.LeftRatio) { $ChainUI.LeftRatio } else { 0.4 }; try { $l.SplitterDistance = [int]($l.Height * $q) } catch { }; $ChainUI.LeftReady = $true })
    Update-ChainCombo
    Open-Chain $ChainUI.Current
    Set-ChainStatus 'F5 runs the chain. Values taken from a response are available to the next steps as {{name}}. Examples (top bar or the list on the left) show how.' $C.Dim
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    if ($firstTime) { New-ChainFromExample 'Log in, then use the token' }
    $f.Activate()
}

function Open-ApiText([string]$Text) {
    $t = $Text.Trim()
    if ($t -match '^curl(\.exe)?\s') { Import-ApiCurl $t; return }
    if ($t -match '^https?://\S+$') {
        $m = New-ApiModel; $m.Url = $t
        Set-ApiModel $m
        Set-ApiStatus 'URL from the clipboard. Press Send (Ctrl+Enter).' $C.Dim
    }
}

function Open-ApiFromPicker {
    $sel = Get-Selected
    $text = if ($sel -and $sel.Kind -eq 'text') { $sel.Text } else { '' }
    Show-ApiTester $text
}

# ---------------------------------------------------------------------------
# Notes window: OneNote-style pages. Click anywhere on a page to write, paste text or screenshots
# anywhere, drag things around. Files can also be attached below the page.
# data\notes\index.json lists the notes. A note's page is <id>.page.json (positions are stored at
# 96 DPI), its pictures live in <id>.images\ and its attachments in <id>\.
# There is one Notes window; its controls and state live in $NoteUI (not $N: PowerShell names ignore case, and loops use $n).
# ---------------------------------------------------------------------------
$NotesDir   = Join-Path $DataDir 'notes'
$NotesIndex = Join-Path $NotesDir 'index.json'
$script:Notes = New-Object System.Collections.Generic.List[object]
$NoteUI = @{ Form = $null; Current = $null; Dirty = $false; Loading = $false; Updating = $false
        View = (New-Object System.Collections.Generic.List[object]) }

function Convert-Time($Value) {
    if ($Value -is [datetime]) { return $Value }
    if ($Value) { try { return [datetime]::Parse([string]$Value, $null, [Globalization.DateTimeStyles]::RoundtripKind).ToLocalTime() } catch { } }
    Get-Date
}

function New-NoteItem([string]$Title = '', [string]$Text = '', $Created = $null, $Modified = $null, [string]$Id = '', [string]$Folder = '') {
    if (-not $Id) { $Id = [guid]::NewGuid().ToString('N') }
    [pscustomobject]@{ Id = $Id; Title = $Title; Text = $Text; Created = (Convert-Time $Created); Modified = (Convert-Time $Modified); Folder = $Folder; Locked = $false; Remind = $null; Repeat = '' }
}

# Folders group notes in the list; each can be collapsed. Stored in notes\folders.json.
$script:NoteFolders = New-Object System.Collections.Generic.List[object]
$NoteFoldersFile = Join-Path $NotesDir 'folders.json'

function Get-NoteFolder([string]$Name) { foreach ($x in $script:NoteFolders) { if ($x.Name -eq $Name) { return $x } }; $null }

# Folders nest: a folder's name is its path, e.g. "Work/Projects/Alpha". Adding one adds its parents too.
function ConvertTo-FolderPath([string]$Path) { (@($Path -split '/' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) -join '/') }
function Get-FolderParent([string]$Path) { $i = $Path.LastIndexOf('/'); if ($i -lt 0) { '' } else { $Path.Substring(0, $i) } }
function Get-FolderLeaf([string]$Path) { $Path.Substring($Path.LastIndexOf('/') + 1) }
function Get-FolderDepth([string]$Path) { ($Path.ToCharArray() | Where-Object { $_ -eq '/' }).Count }
function Test-InFolder([string]$Path, [string]$Folder) { $Path -eq $Folder -or $Path.StartsWith("$Folder/") }
function Join-FolderPath([string]$Parent, [string]$Leaf) { if ($Parent) { "$Parent/$Leaf" } else { $Leaf } }

function Add-NoteFolder([string]$Name) {
    $Name = ConvertTo-FolderPath $Name
    if (-not $Name) { return $null }
    $parts = $Name.Split('/')
    $x = $null
    for ($k = 1; $k -le $parts.Count; $k++) {
        $p = $parts[0..($k - 1)] -join '/'
        $x = Get-NoteFolder $p
        if (-not $x) { $x = [pscustomobject]@{ Name = $p; Collapsed = $false }; $script:NoteFolders.Add($x) }
    }
    $x
}

# Opens a folder and every folder above it.
function Show-NoteFolderPath([string]$Path) {
    while ($Path) { $f = Get-NoteFolder $Path; if ($f) { $f.Collapsed = $false }; $Path = Get-FolderParent $Path }
}

# Renames a folder path and everything inside it (subfolders and notes); merges with an existing folder of that name.
function Rename-FolderPath([string]$Old, [string]$New) {
    foreach ($f in $script:NoteFolders.ToArray()) { if (Test-InFolder $f.Name $Old) { $f.Name = $New + $f.Name.Substring($Old.Length) } }
    foreach ($n in $script:Notes) { if ($n.Folder -and (Test-InFolder $n.Folder $Old)) { $n.Folder = $New + $n.Folder.Substring($Old.Length) } }
    $seen = @{}
    foreach ($f in $script:NoteFolders.ToArray()) {
        if ($seen.ContainsKey($f.Name)) { [void]$script:NoteFolders.Remove($f) } else { $seen[$f.Name] = $true }
    }
    if ($NoteUI.SelectedFolder -and (Test-InFolder $NoteUI.SelectedFolder $Old)) { $NoteUI.SelectedFolder = $New + $NoteUI.SelectedFolder.Substring($Old.Length) }
    [void](Add-NoteFolder $New)
}

function Save-NoteFolders {
    $json = ConvertTo-Json -InputObject @($script:NoteFolders | ForEach-Object { [ordered]@{ Name = $_.Name; Collapsed = [bool]$_.Collapsed } }) -Depth 3
    try { Write-JsonFile $NoteFoldersFile $json } catch { Write-Log "note folders save failed: $_" }
}

# Lock and reminder from a saved index entry.
function Set-NoteExtras($Note, $Saved) {
    $Note.Locked = [bool]$Saved.Locked
    $Note.Remind = if ($Saved.Remind) { Convert-Time $Saved.Remind } else { $null }
    $Note.Repeat = [string]$Saved.Repeat
}

function Get-NoteIndexEntry($n) {
    [ordered]@{ Id = $n.Id; Title = $n.Title; Text = $n.Text; Created = $n.Created.ToString('o'); Modified = $n.Modified.ToString('o'); Folder = [string]$n.Folder; Locked = [bool]$n.Locked
                Remind = $(if ($n.Remind) { ([datetime]$n.Remind).ToString('o') } else { $null }); Repeat = [string]$n.Repeat }
}

function Import-Notes {
    if (-not (Test-Path $NotesDir)) { [void](New-Item -ItemType Directory -Path $NotesDir) }
    if (-not (Test-Path $NotesIndex)) { return }
    try {
        foreach ($x in (ConvertFrom-Json (Read-DataText $NotesIndex))) {
            if ($x.Id) { $nn = New-NoteItem ([string]$x.Title) ([string]$x.Text) $x.Created $x.Modified ([string]$x.Id) ([string]$x.Folder); Set-NoteExtras $nn $x; $script:Notes.Add($nn) }
        }
    } catch {
        Copy-Item $NotesIndex "$NotesIndex.corrupt-$(Get-Date -Format yyyyMMddHHmmss)" -ErrorAction SilentlyContinue
    }
    if (Test-Path $NoteFoldersFile) {
        try {
            foreach ($x in @(ConvertFrom-JsonList (Read-DataText $NoteFoldersFile))) {
                if ($x.Name) { (Add-NoteFolder ([string]$x.Name)).Collapsed = [bool]$x.Collapsed }
            }
        } catch { }
    }
    foreach ($n in $script:Notes) { if ($n.Folder) { [void](Add-NoteFolder $n.Folder) } }
}

function Save-NotesIndex {
    if ($script:NoSave) { return }
    $out = foreach ($n in $script:Notes) { Get-NoteIndexEntry $n }
    $json = ConvertTo-Json -InputObject @($out) -Depth 3
    if (-not $json) { $json = '[]' }
    try { Write-JsonFile $NotesIndex $json } catch { Write-Log "notes index save failed: $_" }
}

function Get-NoteRtf($Note)       { Join-Path $NotesDir "$($Note.Id).rtf" }          # notes saved before pages existed
function Get-NotePage($Note)      { Join-Path $NotesDir "$($Note.Id).page.json" }
function Get-NoteImagesDir($Note) { Join-Path $NotesDir "$($Note.Id).images" }
function Get-NoteFilesDir($Note)  { Join-Path $NotesDir $Note.Id }

function Get-NoteTitle($Note) {
    if ($Note.Title.Trim()) { return $Note.Title.Trim() }
    $first = @($Note.Text -split "`n" | Where-Object { $_.Trim() })[0]
    if ($first) {
        $first = $first.Trim()
        if ($first.Length -gt 60) { $first = $first.Substring(0, 60) + '...' }
        return $first
    }
    'Untitled'
}

# The list is a tree: folders (open / closed) with their subfolders and notes, then notes in no folder.
# While searching, folders open to show their matches and folders without matches are hidden.
function Update-NoteList {
    if (-not $NoteUI.Form) { return }
    $q = $NoteUI.Search.Text.Trim()
    $NoteUI.View.Clear()
    $hits = @($script:Notes | Sort-Object Modified -Descending | Where-Object { -not $q -or "$($_.Title)`n$($_.Text)".IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -ge 0 })
    $addFolder = $null
    $addFolder = {
        param($Parent, $Depth)
        foreach ($folder in @($script:NoteFolders | Where-Object { (Get-FolderParent $_.Name) -eq $Parent } | Sort-Object { Get-FolderLeaf $_.Name })) {
            $total = @($hits | Where-Object { $_.Folder -and (Test-InFolder $_.Folder $folder.Name) }).Count
            if ($q -and $total -eq 0) { continue }
            $open = [bool]($q -or -not $folder.Collapsed)
            $NoteUI.View.Add([pscustomobject]@{ IsFolder = $true; Name = $folder.Name; Label = (Get-FolderLeaf $folder.Name); Depth = $Depth; Count = $total; Open = $open; Folder = $folder })
            if ($open) {
                & $addFolder $folder.Name ($Depth + 1)
                foreach ($n in $hits) { if ($n.Folder -eq $folder.Name) { $NoteUI.View.Add($n) } }
            }
        }
    }
    & $addFolder '' 0
    foreach ($n in $hits) { if (-not $n.Folder -or -not (Get-NoteFolder $n.Folder)) { $NoteUI.View.Add($n) } }
    $NoteUI.Updating = $true
    try {
        $NoteUI.List.BeginUpdate()
        $NoteUI.List.Items.Clear()
        $pick = -1
        for ($i = 0; $i -lt $NoteUI.View.Count; $i++) {
            [void]$NoteUI.List.Items.Add($i)
            $row = $NoteUI.View[$i]
            if ($NoteUI.SelectedFolder) { if ($row.IsFolder -and $row.Name -eq $NoteUI.SelectedFolder) { $pick = $i } }
            elseif ($NoteUI.Current -and -not $row.IsFolder -and $row.Id -eq $NoteUI.Current.Id) { $pick = $i }
        }
        if ($pick -lt 0 -and $NoteUI.Current -and $NoteUI.Current.Folder) {       # open note is inside a closed folder: select the nearest visible one
            $p = $NoteUI.Current.Folder
            while ($p -and $pick -lt 0) {
                for ($i = 0; $i -lt $NoteUI.View.Count; $i++) { if ($NoteUI.View[$i].IsFolder -and $NoteUI.View[$i].Name -eq $p) { $pick = $i } }
                $p = Get-FolderParent $p
            }
        }
        if ($pick -ge 0) { $NoteUI.List.SelectedIndex = $pick }
        $NoteUI.List.EndUpdate()
    } finally { $NoteUI.Updating = $false }
    $count = $script:Notes.Count
    $NoteUI.Form.Text = "DevTools Notes  -  $count $(if ($count -eq 1) { 'note' } else { 'notes' })"
}

# Writes the open page: each text box (as rich text) and picture with its position.
# A locked note is written as one encrypted file (pictures inside it) with the Secrets master password key.
function Save-CurrentNote {
    $note = $NoteUI.Current
    if (-not $note -or -not $NoteUI.Dirty -or $NoteUI.ShowingLock) { return }
    $NoteUI.SaveTimer.Stop()
    $locked = [bool]$note.Locked
    $key = $null
    if ($locked) {
        $key = Get-NotesKey
        if (-not $key) { Write-Log 'locked note not saved: notes are locked'; return }
    }
    $canvas = $NoteUI.Canvas
    $imgDir = Get-NoteImagesDir $note
    $texts = New-Object System.Collections.Generic.List[string]
    try {
        $blocks = foreach ($b in $canvas.Blocks) {
            $p = $canvas.PagePos($b)
            $o = [ordered]@{ Kind = $b.Kind; X = [int]($p.X / $Scale); Y = [int]($p.Y / $Scale); W = [int]($b.Width / $Scale) }
            if ($b.Kind -eq 'text') {
                if ($b.IsEmpty) { continue }
                $o.Rtf  = $b.Box.Rtf
                $o.Text = $b.Box.Text
                $texts.Add($b.Box.Text)
            } elseif ($locked) {
                $ms = New-Object IO.MemoryStream
                $b.Picture.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png)
                $o.Png = [Convert]::ToBase64String($ms.ToArray())
                $ms.Dispose()
                $b.File = $null                      # written again as a file if the lock is removed
            } else {
                if (-not $b.File) {
                    if (-not (Test-Path $imgDir)) { [void](New-Item -ItemType Directory -Path $imgDir) }
                    $name = "$([guid]::NewGuid().ToString('N')).png"
                    $b.Picture.Save((Join-Path $imgDir $name), [System.Drawing.Imaging.ImageFormat]::Png)
                    $b.File = $name
                }
                $o.File = $b.File
            }
            $o
        }
        $json = ConvertTo-Json -InputObject ([ordered]@{ Blocks = @($blocks) }) -Depth 4
        if ($locked) {
            Write-SealedFile (Get-NoteEncPath $note) ([PowerClipVault]::Seal($json, $key))
            Remove-Item -LiteralPath (Get-NotePage $note) -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $imgDir -Recurse -Force -ErrorAction SilentlyContinue
        } else {
            Write-JsonFile (Get-NotePage $note) $json
            Remove-Item -LiteralPath (Get-NoteEncPath $note) -Force -ErrorAction SilentlyContinue
        }
    } catch { Write-Log "note save failed: $_"; return }
    # Pictures removed from the page.
    if (-not $locked) {
        $used = @{}
        foreach ($b in $canvas.Blocks) { if ($b.Kind -eq 'image' -and $b.File) { $used[$b.File] = $true } }
        if (Test-Path $imgDir) {
            Get-ChildItem -LiteralPath $imgDir -File | Where-Object { -not $used.ContainsKey($_.Name) } | Remove-Item -Force -ErrorAction SilentlyContinue
        }
    }
    Remove-Item -LiteralPath (Get-NoteRtf $note) -Force -ErrorAction SilentlyContinue      # now stored as a page
    $note.Title    = $NoteUI.Title.Text
    $note.Text     = if ($locked) { '' } else { $texts -join "`n" }     # a locked note's text stays out of the index (and search)
    $note.Modified = Get-Date
    $NoteUI.Dirty = $false
    Save-NotesIndex
    Update-NoteList
}

# Marks the note changed and saves it shortly after the last change.
function Start-NoteAutosave {
    if ($NoteUI.Loading -or -not $NoteUI.Current -or $NoteUI.ShowingLock) { return }
    $NoteUI.Dirty = $true
    $NoteUI.SaveTimer.Stop()
    $NoteUI.SaveTimer.Start()
}

function Open-Note($Note, [switch]$Prompt) {
    Save-CurrentNote
    $canvas = $NoteUI.Canvas
    $NoteUI.Loading = $true
    $canvas.Loading = $true
    $reseal = $false
    try {
        $NoteUI.Current = $Note
        $NoteUI.Title.Text = $Note.Title
        $canvas.ClearPage()
        Show-NoteLockPanel $false
        $page = $null
        $encPath = Get-NoteEncPath $Note
        if ($Note.Locked -and (Test-Path -LiteralPath $encPath)) {
            $r = Read-LockedNotePage $Note -Prompt:$Prompt
            if (-not $r) { Show-NoteLockPanel $true; return }
            $page = $r.Page; $reseal = $r.Reseal
        } elseif (Test-Path (Get-NotePage $Note)) {
            $page = Read-DataText (Get-NotePage $Note) | ConvertFrom-Json
        }
        if ($page) {
            foreach ($b in @($page.Blocks)) {
                if ($b.Kind -eq 'image') {
                    if ($b.Png) {
                        $ms = New-Object IO.MemoryStream(, [Convert]::FromBase64String([string]$b.Png))
                        $tmp = [System.Drawing.Image]::FromStream($ms); $img = New-Object System.Drawing.Bitmap $tmp; $tmp.Dispose(); $ms.Dispose()
                        [void]$canvas.AddImage((Px $b.X), (Px $b.Y), (Px $b.W), $img, $null)
                    } else {
                        $path = Join-Path (Get-NoteImagesDir $Note) ([string]$b.File)
                        if (Test-Path -LiteralPath $path) { [void]$canvas.AddImage((Px $b.X), (Px $b.Y), (Px $b.W), (Read-ImageFile $path), [string]$b.File) }
                    }
                } else {
                    [void]$canvas.AddText((Px $b.X), (Px $b.Y), (Px $b.W), [string]$b.Rtf, [string]$b.Text)
                }
            }
        } elseif (Test-Path (Get-NoteRtf $Note)) {
            [void]$canvas.AddText((Px 16), (Px 16), (Px 760), [IO.File]::ReadAllText((Get-NoteRtf $Note)), $Note.Text)
        } elseif ($Note.Text) {
            [void]$canvas.AddText((Px 16), (Px 16), (Px 760), $null, $Note.Text)
        }
        Update-Attachments
    } catch {
        Write-Log "note load failed: $_"
    } finally {
        $canvas.Loading = $false
        $NoteUI.Loading = $false
        $NoteUI.Dirty = $false
    }
    if ($reseal) { $NoteUI.Dirty = $true; Save-CurrentNote }      # opened with an older password: store it with the current one
}

# The folder that "New note" puts notes in: the selected folder, else the open note's folder.
function Get-TargetNoteFolder {
    if ($NoteUI.SelectedFolder) { return $NoteUI.SelectedFolder }
    if ($NoteUI.Current -and $NoteUI.Current.Folder) { return $NoteUI.Current.Folder }
    ''
}

function New-Note([string]$Title = '', [string]$Folder = $null) {
    Save-CurrentNote
    # no folder given ([string] turns $null into ''): the selected folder
    if (-not $PSBoundParameters.ContainsKey('Folder')) { $Folder = if ($NoteUI.Form) { Get-TargetNoteFolder } else { '' } }
    $note = New-NoteItem $Title '' $null $null '' $Folder
    if ($Folder) { [void](Add-NoteFolder $Folder); Show-NoteFolderPath $Folder; Save-NoteFolders }
    $NoteUI.SelectedFolder = $null
    $script:Notes.Add($note)
    Save-NotesIndex
    $NoteUI.Search.Text = ''
    Open-Note $note
    Update-NoteList
    $note
}

function Remove-CurrentNote {
    $note = $NoteUI.Current
    if (-not $note) { return }
    $r = [System.Windows.Forms.MessageBox]::Show($NoteUI.Form, "Delete the note `"$(Get-NoteTitle $note)`" with its pictures and attachments?",
        'Notes', 'YesNo', 'Warning')
    if ($r -ne 'Yes') { return }
    Add-Tombstone $note.Id
    $NoteUI.SaveTimer.Stop()
    $NoteUI.Dirty = $false
    $NoteUI.Current = $null
    for ($i = 0; $i -lt $script:Notes.Count; $i++) { if ($script:Notes[$i].Id -eq $note.Id) { $script:Notes.RemoveAt($i); break } }
    $NoteUI.Canvas.ClearPage()
    foreach ($p in (Get-NoteRtf $note), (Get-NotePage $note), (Get-NoteEncPath $note)) { Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue }
    foreach ($p in (Get-NoteImagesDir $note), (Get-NoteFilesDir $note)) { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue }
    Save-NotesIndex
    if ($script:Notes.Count -eq 0) { [void](New-Note) }
    else {
        Update-NoteList
        $first = @($NoteUI.View | Where-Object { -not $_.IsFolder })[0]
        if (-not $first) { $first = @($script:Notes | Sort-Object Modified -Descending)[0] }
        Open-Note $first; Update-NoteList
    }
}

function Update-Attachments {
    $NoteUI.Files.Items.Clear()
    $dir = Get-NoteFilesDir $NoteUI.Current
    if (Test-Path $dir) { foreach ($f in Get-ChildItem -LiteralPath $dir) { [void]$NoteUI.Files.Items.Add($f.Name) } }
    $NoteUI.FilesLabel.Text = "Attachments ($($NoteUI.Files.Items.Count))   $Dot   drop or paste files here (pictures go onto the page)"
}

function Add-NoteFiles([string[]]$Paths) {
    if (-not $NoteUI.Current -or -not $Paths) { return }
    $dir = Get-NoteFilesDir $NoteUI.Current
    if (-not (Test-Path $dir)) { [void](New-Item -ItemType Directory -Path $dir) }
    foreach ($p in $Paths) {
        $name = Split-Path -Leaf $p
        $dest = Join-Path $dir $name
        $base = [IO.Path]::GetFileNameWithoutExtension($name); $ext = [IO.Path]::GetExtension($name); $k = 1
        while (Test-Path -LiteralPath $dest) { $k++; $dest = Join-Path $dir "$base ($k)$ext" }
        try { Copy-Item -LiteralPath $p -Destination $dest -Recurse } catch { Write-Log "attach failed: $_" }
    }
    $NoteUI.Current.Modified = Get-Date
    Save-NotesIndex
    Update-Attachments
    Update-NoteList
}

function Get-SelectedAttachment {
    if ($NoteUI.Files.SelectedIndex -lt 0) { return $null }
    Join-Path (Get-NoteFilesDir $NoteUI.Current) ([string]$NoteUI.Files.SelectedItem)
}

# ---- note folders: create, rename, delete, move notes -------------------------------------------

function Read-TextDialog([string]$Title, [string]$Prompt, [string]$Value = '', $Owner = $null) {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = $Title; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (380 * $TextZoom)), ($FontMain.Height * 2 + $FontButton.Height + (Px 70)))
    $l = New-Object System.Windows.Forms.Label; $l.Text = $Prompt; $l.Font = $FontMain; $l.AutoSize = $true; $l.Location = New-Object System.Drawing.Point((Px 14), (Px 12))
    $l.MaximumSize = New-Object System.Drawing.Size(($d.ClientSize.Width - (Px 28)), 0)          # long prompts wrap
    $b = New-Object System.Windows.Forms.TextBox; $b.Text = $Value; $b.BorderStyle = 'FixedSingle'; $b.BackColor = $C.Bg; $b.ForeColor = $C.Fore
    $b.Location = New-Object System.Drawing.Point((Px 14), ($l.Top + $l.PreferredSize.Height + (Px 8))); $b.Width = $d.ClientSize.Width - (Px 28)
    $ok = New-Object PowerClipButton; $ok.Text = 'OK'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true; $ok.DialogResult = 'OK'
    $cancel = New-Object PowerClipButton; $cancel.Text = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $d.Controls.AddRange(@($l, $b, $ok, $cancel))
    $y = $b.Bottom + (Px 14)
    $cancel.Location = New-Object System.Drawing.Point(($d.ClientSize.Width - $cancel.Width - (Px 14)), $y)
    $ok.Location = New-Object System.Drawing.Point(($cancel.Left - $ok.Width - (Px 8)), $y)
    $d.ClientSize = New-Object System.Drawing.Size($d.ClientSize.Width, ($cancel.Bottom + (Px 14)))
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Register-ThemedWindow $d
    $script:Modal = $true
    try { $r = $d.ShowDialog($Owner) } finally { $script:Modal = $false }
    $text = $b.Text.Trim()
    $d.Dispose()
    if ($r -eq 'OK' -and $text) { return $text }
    $null
}

# New folder inside $Parent (by default inside the selected folder, or at the top).
function New-NoteFolderPrompt($Parent = $null) {
    if ($null -eq $Parent) { $Parent = if ($NoteUI.SelectedFolder) { $NoteUI.SelectedFolder } else { '' } }
    $prompt = if ($Parent) { "Folder name (inside `"$($Parent.Replace('/', ' > '))`")" } else { 'Folder name' }
    $name = Read-TextDialog 'New folder' $prompt '' $NoteUI.Form
    if (-not $name) { return $null }
    $name = ($name -replace '[\r\n]', ' ') -replace '[/\\]', '-'
    $path = Join-FolderPath $Parent $name.Trim()
    [void](Add-NoteFolder $path)
    Show-NoteFolderPath $path
    Save-NoteFolders
    $NoteUI.SelectedFolder = $path
    Update-NoteList
    $path
}

function Rename-NoteFolder([string]$Name) {
    if (-not (Get-NoteFolder $Name)) { return }
    $leaf = Read-TextDialog 'Rename folder' 'New name' (Get-FolderLeaf $Name) $NoteUI.Form
    if (-not $leaf) { return }
    $new = Join-FolderPath (Get-FolderParent $Name) (($leaf -replace '[/\\]', '-').Trim())
    if ($new -eq $Name) { return }
    Rename-FolderPath $Name $new
    Save-NoteFolders; Save-NotesIndex; Update-NoteList
}

# Moves a folder (with everything in it) into another folder, or to the top when $NewParent is ''.
function Move-NoteFolder([string]$Name, [string]$NewParent) {
    if (-not (Get-NoteFolder $Name)) { return }
    if ($NewParent -and (Test-InFolder $NewParent $Name)) { return }          # not into itself or its own subfolder
    $new = Join-FolderPath $NewParent (Get-FolderLeaf $Name)
    if ($new -eq $Name) { return }
    Rename-FolderPath $Name $new
    Show-NoteFolderPath $new
    Save-NoteFolders; Save-NotesIndex; Update-NoteList
}

# Deletes a folder; its notes and subfolders move up one level (nothing is deleted).
function Remove-NoteFolder([string]$Name, [switch]$NoPrompt) {
    $folder = Get-NoteFolder $Name
    if (-not $folder) { return }
    $parent = Get-FolderParent $Name
    $notes = @($script:Notes | Where-Object { $_.Folder -and (Test-InFolder $_.Folder $Name) }).Count
    $subs = @($script:NoteFolders | Where-Object { $_.Name.StartsWith("$Name/") }).Count
    if ($notes + $subs -gt 0 -and -not $NoPrompt) {
        $where = if ($parent) { "`"$($parent.Replace('/', ' > '))`"" } else { 'the top level' }
        $r = [System.Windows.Forms.MessageBox]::Show($NoteUI.Form, "Delete the folder `"$(Get-FolderLeaf $Name)`"? Nothing inside is deleted: its $notes note(s) and $subs subfolder(s) move up to $where.",
            'Notes', 'OKCancel', 'Question')
        if ($r -ne 'OK') { return }
    }
    foreach ($n in $script:Notes) {
        if ($n.Folder -eq $Name) { $n.Folder = $parent }
        elseif ($n.Folder -and $n.Folder.StartsWith("$Name/")) { $n.Folder = Join-FolderPath $parent $n.Folder.Substring($Name.Length + 1) }
    }
    Add-Tombstone "folder:$Name"
    [void]$script:NoteFolders.Remove($folder)
    foreach ($f in $script:NoteFolders.ToArray()) { if ($f.Name.StartsWith("$Name/")) { $f.Name = Join-FolderPath $parent $f.Name.Substring($Name.Length + 1) } }
    $seen = @{}
    foreach ($f in $script:NoteFolders.ToArray()) { if ($seen.ContainsKey($f.Name)) { [void]$script:NoteFolders.Remove($f) } else { $seen[$f.Name] = $true } }
    $NoteUI.SelectedFolder = $null
    Save-NoteFolders; Save-NotesIndex; Update-NoteList
}

function Move-NoteToFolder($Note, [string]$Folder) {
    if (-not $Note -or $Note.Folder -eq $Folder) { return }
    $Note.Modified = Get-Date                 # so the move reaches other PCs when syncing
    $Note.Folder = $Folder
    if ($Folder) { [void](Add-NoteFolder $Folder); Show-NoteFolderPath $Folder; Save-NoteFolders }
    Save-NotesIndex
    $NoteUI.SelectedFolder = $null
    Update-NoteList
}

function Switch-NoteFolder([string]$Name) {
    $f = Get-NoteFolder $Name
    if (-not $f) { return }
    $f.Collapsed = -not $f.Collapsed
    Save-NoteFolders
    Update-NoteList
}

function Get-NoteRow([int]$Index) { if ($Index -ge 0 -and $Index -lt $NoteUI.View.Count) { $NoteUI.View[$Index] } else { $null } }

# Formatting applies to the text box you were last typing in.
function Get-ActiveNoteText {
    $t = $NoteUI.Canvas.ActiveText
    if ($t -and -not $t.IsDisposed) { return $t }
    $null
}

# ---------------------------------------------------------------------------
# Locked notes: encrypted with the Secrets master password (AES-256, the vault's key). The title stays
# visible in the list; the text and pictures are only in the encrypted file.
# ---------------------------------------------------------------------------
$script:NotesKey = $null

function Get-NoteEncPath($Note) { Join-Path $NotesDir "$($Note.Id).page.enc" }

function Write-SealedFile([string]$Path, [byte[]]$Bytes) {
    $tmp = "$Path.tmp"
    [IO.File]::WriteAllBytes($tmp, $Bytes)
    if (Test-Path -LiteralPath $Path) { [IO.File]::Replace($tmp, $Path, [NullString]::Value) } else { [IO.File]::Move($tmp, $Path) }
}

# The key for locked notes: the open vault's, else asks for the master password (with -Prompt).
function Get-NotesKey([switch]$Prompt, [string]$Why = 'Enter your Secrets master password to open locked notes.') {
    if ($VaultUI.Key) { Touch-Vault; return $VaultUI.Key }
    if ($script:NotesKey) { Touch-Vault; return $script:NotesKey }
    if (-not $Prompt) { return $null }
    if (-not (Test-Path $VaultFile)) {
        [void][System.Windows.Forms.MessageBox]::Show($NoteUI.Form, 'Locked notes are encrypted with your Secrets master password. Create the vault first (Secrets), then lock the note.', 'Lock note', 'OK', 'Information')
        Show-Vault
        return $null
    }
    $msg = $Why
    for ($i = 0; $i -lt 5; $i++) {
        $pw = Read-PasswordDialog 'Locked notes' $msg
        if ($null -eq $pw) { return $null }
        try {
            $k = $null
            [void][PowerClipVault]::Open([IO.File]::ReadAllBytes($VaultFile), $pw, [ref]$k)
            $script:NotesKey = $k
            Touch-Vault
            return $k
        } catch { $msg = 'That is not the master password. Try again.' }
    }
    $null
}

# @{ Page; Reseal } or $null while the notes are locked (or the password is not given).
function Read-LockedNotePage($Note, [switch]$Prompt) {
    $key = Get-NotesKey -Prompt:$Prompt
    if (-not $key) { return $null }
    $bytes = [IO.File]::ReadAllBytes((Get-NoteEncPath $Note))
    try { return @{ Page = ([PowerClipVault]::OpenWithKey($bytes, $key) | ConvertFrom-Json); Reseal = $false } } catch { }
    if (-not $Prompt) { if ($NoteUI.LockHint) { $NoteUI.LockHint.Text = 'This note was locked with another master password (on another PC, or before a password change).' }; return $null }
    $msg = 'This note was locked with another master password (on another PC, or before a password change). Enter that password.'
    for ($i = 0; $i -lt 3; $i++) {
        $pw = Read-PasswordDialog 'Locked note' $msg
        if ($null -eq $pw) { return $null }
        try { $k = $null; $json = [PowerClipVault]::Open($bytes, $pw, [ref]$k); $k.Dispose(); return @{ Page = ($json | ConvertFrom-Json); Reseal = $true } }
        catch { $msg = 'That password does not open it. Try again.' }
    }
    $null
}

function Show-NoteLockPanel([bool]$Show) {
    if (-not $NoteUI.LockPanel) { return }
    $NoteUI.ShowingLock = $Show
    $NoteUI.LockPanel.Visible = $Show
    $NoteUI.Canvas.Visible = -not $Show
    $NoteUI.Title.ReadOnly = $Show
    if ($Show) { $NoteUI.LockPanel.BringToFront(); if (-not $NoteUI.LockHint.Text) { $NoteUI.LockHint.Text = 'Its text and pictures are encrypted with your Secrets master password.' } }
    else { $NoteUI.LockHint.Text = '' }
}

# Lock (encrypt) or unlock (decrypt for good) the open note.
function Set-NoteLock([bool]$Lock) {
    $note = $NoteUI.Current
    if (-not $note -or $NoteUI.ShowingLock -or $Lock -eq [bool]$note.Locked) { return }
    if ($Lock -and -not (Get-NotesKey -Prompt -Why 'Locking encrypts this note with your Secrets master password. Enter it.')) { return }
    Save-CurrentNote
    $note.Locked = $Lock
    $NoteUI.Dirty = $true
    Save-CurrentNote
    Update-NoteList
}

# The notes key is forgotten with the vault (it locks after a few idle minutes); an open locked note closes.
function Lock-Notes {
    if ($script:NotesKey) { try { $script:NotesKey.Dispose() } catch { }; $script:NotesKey = $null }
    if ($NoteUI.Form -and $NoteUI.Current -and $NoteUI.Current.Locked -and -not $NoteUI.ShowingLock -and -not $VaultUI.Key) {
        $NoteUI.Dirty = $false
        Open-Note $NoteUI.Current
    }
}

# After a master password change: encrypt the locked notes with the new key.
function Update-LockedNotesKey($Old, $New) {
    foreach ($n in @($script:Notes | Where-Object { $_.Locked })) {
        $p = Get-NoteEncPath $n
        if (-not (Test-Path -LiteralPath $p)) { continue }
        try { $json = [PowerClipVault]::OpenWithKey([IO.File]::ReadAllBytes($p), $Old) } catch { continue }
        try { Write-SealedFile $p ([PowerClipVault]::Seal($json, $New)) } catch { Write-Log "re-lock note failed: $_" }
    }
    if ($script:NotesKey) { try { $script:NotesKey.Dispose() } catch { }; $script:NotesKey = $null }
}

# ---------------------------------------------------------------------------
# Notes: code blocks with colours, export as Markdown / web page / text.
# ---------------------------------------------------------------------------
$NoteCodeLanguages = [ordered]@{ 'Detect the language' = ''; 'PowerShell' = 'ps'; 'C#' = 'cs'; 'JavaScript / TypeScript' = 'js'; 'Python' = 'py'; 'SQL' = 'sql'; 'JSON' = 'json'
    'XML / HTML' = 'xml'; 'Bash / shell' = 'sh'; 'YAML' = 'yaml'; 'CSS' = 'css'; 'Java / Kotlin' = 'java'; 'Go' = 'go'; 'Rust' = 'rust'; 'C / C++' = 'c'; 'Batch (.cmd)' = 'bat' }

# Formats the selection (or the paragraph with the caret) as code: monospace, shaded, coloured.
function Format-NoteCode([string]$Lang = '', [switch]$Plain) {
    $t = Get-ActiveNoteText
    if (-not $t) { return }
    $box = $t.Box
    $start = $box.SelectionStart; $len = $box.SelectionLength
    if ($len -eq 0) {
        $txt = $box.Text
        $s0 = if ($start -gt 0) { $txt.LastIndexOf("`n", $start - 1) + 1 } else { 0 }
        $e0 = $txt.IndexOf("`n", $start); if ($e0 -lt 0) { $e0 = $txt.Length }
        $start = $s0; $len = $e0 - $s0
    }
    if ($len -le 0) { return }
    if ($Plain) {
        [DevNoteFormat]::Plain($box, $start, $len, $box.Font, $box.ForeColor, $box.BackColor)
    } else {
        $dark = [bool]$script:IsDark
        $cols = if ($dark) { '#D4D4D4', '#C586C0', '#CE9178', '#6A9955', '#B5CEA8', '#4EC9B0' } else { '#24292F', '#8250DF', '#0A3069', '#6E7781', '#0550AE', '#953800' }
        $colors = [System.Drawing.Color[]]@($cols | ForEach-Object { [System.Drawing.ColorTranslator]::FromHtml($_) })
        $back = [System.Drawing.ColorTranslator]::FromHtml($(if ($dark) { '#2B2D31' } else { '#F3F4F6' }))
        [void][DevNoteFormat]::Colorize($box, $start, $len, $Lang, $colors, $back, [float]($box.Font.Size * 0.92))
    }
    $NoteUI.Canvas.RaiseChanged()
    [void]$box.Focus()
}

function Show-NoteCodeMenu($Button) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    foreach ($k in $NoteCodeLanguages.Keys) {
        $it = Add-MenuItem $m $k { param($src, $e) Format-NoteCode $src.Tag }
        $it.Tag = $NoteCodeLanguages[$k]
    }
    [void]$m.Items.Add('-')
    [void](Add-MenuItem $m 'Back to normal text' { Format-NoteCode -Plain } $Glyph.Text)
    $m.Show($Button, (New-Object System.Drawing.Point(0, $Button.Height)))
}

# The open note as Markdown. Pictures are written to $AssetDir (as $AssetRel/<name>), or left out.
function ConvertTo-NoteMarkdown([string]$AssetDir = '', [string]$AssetRel = '') {
    $note = $NoteUI.Current
    $canvas = $NoteUI.Canvas
    $parts = New-Object System.Collections.Generic.List[string]
    $parts.Add("# $(Get-NoteTitle $note)")
    $n = 0
    foreach ($b in @($canvas.Blocks | Sort-Object { $canvas.PagePos($_).Y }, { $canvas.PagePos($_).X })) {
        if ($b.Kind -eq 'text') {
            if ($b.IsEmpty) { continue }
            $parts.Add([DevNoteFormat]::ToMarkdown($b.Box.Rtf, $b.Box.Text))
        } elseif ($AssetDir) {
            $n++
            if (-not (Test-Path -LiteralPath $AssetDir)) { [void](New-Item -ItemType Directory -Path $AssetDir) }
            $b.Picture.Save((Join-Path $AssetDir "picture-$n.png"), [System.Drawing.Imaging.ImageFormat]::Png)
            $parts.Add("![picture $n]($($AssetRel.Replace(' ', '%20'))/picture-$n.png)")
        } else { $parts.Add('*(picture)*') }
    }
    $dir = Get-NoteFilesDir $note
    if ($AssetDir -and (Test-Path -LiteralPath $dir)) {
        $files = @(Get-ChildItem -LiteralPath $dir -File)
        if ($files) {
            if (-not (Test-Path -LiteralPath $AssetDir)) { [void](New-Item -ItemType Directory -Path $AssetDir) }
            $parts.Add('## Attachments')
            $parts.Add((($files | ForEach-Object { Copy-Item -LiteralPath $_.FullName -Destination $AssetDir -Force; "- [$($_.Name)]($($AssetRel.Replace(' ', '%20'))/$($_.Name.Replace(' ', '%20')))" }) -join "`n"))
        }
    }
    $parts -join "`n`n"
}

function Export-CurrentNote([string]$Format) {
    $note = $NoteUI.Current
    if (-not $note -or $NoteUI.ShowingLock) { return }
    Save-CurrentNote
    $title = Get-NoteTitle $note
    if ($Format -eq 'clip') {
        $md = ConvertTo-NoteMarkdown
        try { [System.Windows.Forms.Clipboard]::SetText($md) } catch { }
        return
    }
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = switch ($Format) { 'html' { 'Web page (*.html)|*.html' } 'txt' { 'Text (*.txt)|*.txt' } default { 'Markdown (*.md)|*.md' } }
    $d.FileName = ($title -replace '[\\/:*?"<>|]', '_').Trim()
    $script:Modal = $true
    try {
        if ($d.ShowDialog($NoteUI.Form) -ne 'OK') { return }
        $file = $d.FileName
        $rel = [IO.Path]::GetFileNameWithoutExtension($file) + '_files'
        $assets = Join-Path (Split-Path $file) $rel
        $utf8 = New-Object System.Text.UTF8Encoding $false
        if ($Format -eq 'txt') {
            $texts = foreach ($b in @($NoteUI.Canvas.Blocks | Sort-Object { $NoteUI.Canvas.PagePos($_).Y })) { if ($b.Kind -eq 'text' -and -not $b.IsEmpty) { $b.Box.Text } }
            [IO.File]::WriteAllText($file, (@($title, '') + @($texts) -join "`r`n"), $utf8)
        } else {
            $md = ConvertTo-NoteMarkdown $assets $rel
            $out = if ($Format -eq 'html') { [DevMarkdown]::Page($md, $title, $false) } else { $md }
            [IO.File]::WriteAllText($file, $out, $utf8)
        }
        Start-Process explorer.exe "/select,`"$file`""
    } catch {
        [void][System.Windows.Forms.MessageBox]::Show($NoteUI.Form, "Could not export: $($_.Exception.Message)", 'Export', 'OK', 'Error')
    } finally { $script:Modal = $false; $d.Dispose() }
}

# ---------------------------------------------------------------------------
# Reminders on notes: a notification at the time you pick (once, or repeating).
# ---------------------------------------------------------------------------
$ReminderRepeats = [ordered]@{ '' = 'Once'; 'daily' = 'Every day'; 'weekdays' = 'Every weekday (Mon-Fri)'; 'weekly' = 'Every week'; 'monthly' = 'Every month' }

function Format-ReminderTime($At) {
    $d = ([datetime]$At).Date
    $day = if ($d -eq (Get-Date).Date) { 'today' } elseif ($d -eq (Get-Date).Date.AddDays(1)) { 'tomorrow' } else { ([datetime]$At).ToString('ddd d MMM') }
    "$day $(([datetime]$At).ToString('HH:mm'))"
}

function Get-NextReminder([datetime]$At, [string]$Repeat, [datetime]$Now) {
    if (-not $Repeat) { return $null }
    $t = $At
    do {
        $t = switch ($Repeat) {
            'daily'    { $t.AddDays(1) }
            'weekly'   { $t.AddDays(7) }
            'monthly'  { $t.AddMonths(1) }
            'weekdays' { $x = $t.AddDays(1); while ($x.DayOfWeek -in 'Saturday', 'Sunday') { $x = $x.AddDays(1) }; $x }
            default    { $Now.AddYears(100) }
        }
    } while ($t -le $Now)
    $t
}

function Show-NoteReminder($Note) {
    if (-not $Note) { return }
    $d = New-Object System.Windows.Forms.Form
    $d.Text = 'Reminder'; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.AutoSize = $true; $d.AutoSizeMode = 'GrowAndShrink'
    $flow = New-Object System.Windows.Forms.FlowLayoutPanel
    $flow.FlowDirection = 'TopDown'; $flow.WrapContents = $false; $flow.AutoSize = $true; $flow.BackColor = $C.Panel
    $flow.Padding = New-Object System.Windows.Forms.Padding((Px 14), (Px 10), (Px 14), (Px 10))
    $d.Controls.Add($flow)
    $l = New-Object System.Windows.Forms.Label; $l.AutoSize = $true; $l.Text = "Remind me about  $(Get-NoteTitle $Note)"; $l.MaximumSize = New-Object System.Drawing.Size((Px 460), 0)
    $l.Font = New-Object System.Drawing.Font($UiFont, (Fz 10.5), [System.Drawing.FontStyle]::Bold)
    $flow.Controls.Add($l)
    $row = New-Object System.Windows.Forms.FlowLayoutPanel; $row.AutoSize = $true; $row.WrapContents = $false; $row.BackColor = $C.Panel
    $date = New-Object System.Windows.Forms.DateTimePicker; $date.Format = 'Long'; $date.Width = Px (230 * $TextZoom)
    $time = New-Object System.Windows.Forms.DateTimePicker; $time.Format = 'Custom'; $time.CustomFormat = 'HH:mm'; $time.ShowUpDown = $true; $time.Width = Px (90 * $TextZoom)
    $at = if ($Note.Remind) { [datetime]$Note.Remind } else { $x = (Get-Date).AddHours(1); $x.Date.AddHours($x.Hour) }
    $date.Value = $at.Date; $time.Value = $at
    $row.Controls.AddRange(@($date, $time))
    $flow.Controls.Add($row)
    $quick = New-Object System.Windows.Forms.FlowLayoutPanel; $quick.AutoSize = $true; $quick.WrapContents = $true; $quick.MaximumSize = New-Object System.Drawing.Size((Px 520), 0); $quick.BackColor = $C.Panel
    $set = { param($src, $e) $v = [datetime]$src.Tag.At; $src.Tag.Date.Value = $v.Date; $src.Tag.Time.Value = $v }
    $now = Get-Date
    $monday = $now.Date.AddDays(((8 - [int]$now.DayOfWeek) % 7) + $(if ($now.DayOfWeek -eq 'Monday') { 7 } else { 0 })).AddHours(9)
    foreach ($q in @(@('In 10 min', $now.AddMinutes(10)), @('In 1 hour', $now.AddHours(1)), @('This evening', $now.Date.AddHours(18)), @('Tomorrow 9:00', $now.Date.AddDays(1).AddHours(9)), @('Monday 9:00', $monday))) {
        if ($q[0] -eq 'This evening' -and $now.Hour -ge 18) { continue }
        $b = New-Button $q[0] '' $set $quick '' 2
        $b.Tag = @{ At = $q[1]; Date = $date; Time = $time }
    }
    $flow.Controls.Add($quick)
    $rep = New-Object System.Windows.Forms.ComboBox
    $rep.DropDownStyle = 'DropDownList'; $rep.FlatStyle = 'Flat'; $rep.BackColor = $C.Bg; $rep.ForeColor = $C.Fore; $rep.Width = Px (260 * $TextZoom)
    foreach ($v in $ReminderRepeats.Values) { [void]$rep.Items.Add($v) }
    $rep.SelectedIndex = [math]::Max(0, @($ReminderRepeats.Keys).IndexOf([string]$Note.Repeat))
    $flow.Controls.Add($rep)
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel; $btns.AutoSize = $true; $btns.WrapContents = $false; $btns.BackColor = $C.Panel
    $btns.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
    $ok = New-Button 'Save' '' { param($src, $e) $src.FindForm().DialogResult = 'OK' } $btns $Glyph.Save 1
    if ($Note.Remind) { $rm = New-Button 'Remove reminder' '' { param($src, $e) $src.FindForm().DialogResult = 'Abort' } $btns $Glyph.Delete 2 }
    $cancel = New-Button 'Cancel' '' { param($src, $e) $src.FindForm().DialogResult = 'Cancel' } $btns '' 2
    $flow.Controls.Add($btns)
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Set-ControlTheme $d $null $script:IsDark
    $d.add_Shown({ param($src, $e) [PowerClipHost]::EnsureShown($src.Handle) })
    $script:Modal = $true
    try {
        $owner = if ($NoteUI.Form) { $NoteUI.Form } else { $null }
        $r = $d.ShowDialog($owner)
        if ($r -eq 'OK') {
            $Note.Remind = $date.Value.Date + $time.Value.TimeOfDay
            $Note.Repeat = @($ReminderRepeats.Keys)[$rep.SelectedIndex]
        } elseif ($r -eq 'Abort') { $Note.Remind = $null; $Note.Repeat = '' }
        else { return }
        $Note.Modified = Get-Date
        Save-NotesIndex
        if ($NoteUI.Form) { Update-NoteList }
        if ($Note.Remind) { $tray.ShowBalloonTip(2500, 'Reminder set', "$(Get-NoteTitle $Note): $(Format-ReminderTime $Note.Remind)$(if ($Note.Repeat) { ", $($ReminderRepeats[$Note.Repeat].ToLower())" })", 'Info') }
    } finally { $script:Modal = $false; $d.Dispose() }
}

function Invoke-Reminders {
    $now = Get-Date
    $due = @($script:Notes | Where-Object { $_.Remind -and $_.Remind -le $now })
    if ($due.Count -eq 0) { return }
    foreach ($n in $due) {
        $script:BalloonNoteId = $n.Id
        $body = if ($n.Locked) { 'Locked note - click to open it.' } else { Get-Preview $n.Text }
        if (-not $body) { $body = 'Click to open the note.' }
        $tray.ShowBalloonTip(20000, "Reminder: $(Get-NoteTitle $n)", $body, 'Info')
        [System.Media.SystemSounds]::Asterisk.Play()
        $n.Remind = Get-NextReminder $n.Remind $n.Repeat $now
        if (-not $n.Remind) { $n.Repeat = '' }
    }
    Save-NotesIndex
    if ($NoteUI.Form) { Update-NoteList }
}

# A quick reminder from the palette or the tray: a note with the text and a reminder.
function New-QuickReminder {
    $text = Read-TextDialog 'New reminder' 'What should I remind you about?' ''
    if (-not $text -or -not $text.Trim()) { return }
    $n = New-NoteItem $text.Trim() '' $null $null '' ''
    $script:Notes.Add($n)
    Save-NotesIndex
    Show-NoteReminder $n
    if (-not $n.Remind) { [void]$script:Notes.Remove($n); Save-NotesIndex }
    elseif ($NoteUI.Form) { Update-NoteList }
}

function Show-NoteMoreMenu($Button) {
    $note = $NoteUI.Current
    if (-not $note) { return }
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $m $(if ($note.Remind) { "Reminder: $(Format-ReminderTime $note.Remind)..." } else { 'Remind me...' }) { Show-NoteReminder $NoteUI.Current } $Glyph.History)
    if ($note.Locked) { [void](Add-MenuItem $m 'Remove the lock (decrypt this note)' { Set-NoteLock $false } $Glyph.Lock) }
    else { [void](Add-MenuItem $m 'Lock with the master password' { Set-NoteLock $true } $Glyph.Lock) }
    [void]$m.Items.Add('-')
    [void](Add-MenuItem $m 'Export as Markdown (.md)...' { Export-CurrentNote 'md' } $Glyph.Save)
    [void](Add-MenuItem $m 'Export as web page (.html)...' { Export-CurrentNote 'html' } $Glyph.Globe)
    [void](Add-MenuItem $m 'Export as text (.txt)...' { Export-CurrentNote 'txt' } $Glyph.Document)
    [void](Add-MenuItem $m 'Copy as Markdown' { Export-CurrentNote 'clip' } $Glyph.Copy)
    [void](Add-MenuItem $m 'Preview as Markdown' { Show-Toolbox 'markdown' (ConvertTo-NoteMarkdown) } $Glyph.View)
    if ($NoteUI.ShowingLock) { foreach ($x in @($m.Items)) { if ($x.Text -notlike 'Remind*' -and $x.Text -notlike 'Reminder*') { $x.Enabled = $false } } }
    $m.Show($Button, (New-Object System.Drawing.Point(0, $Button.Height)))
}

function Show-Notes {
