    $split.Panel1.Controls.Add($nbar)

    $sp = New-Object System.Windows.Forms.Panel
    $sp.Dock = 'Top'; $sp.Height = Px 40
    $sp.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 8), (Px 8), (Px 4))
    $nsearch = New-Object System.Windows.Forms.TextBox
    $nsearch.Dock = 'Fill'; $nsearch.BorderStyle = 'FixedSingle'; $nsearch.BackColor = $C.Bg; $nsearch.ForeColor = $C.Fore
    $sp.Controls.Add($nsearch)
