    $fmt = New-Object System.Windows.Forms.FlowLayoutPanel
    $fmt.Dock = 'Top'; $fmt.AutoSize = $true; $fmt.AutoSizeMode = 'GrowAndShrink'; $fmt.WrapContents = $true; $fmt.BackColor = $C.Panel
