    $b = New-Button 'B' 'Bold (Ctrl+B)'      { $t = Get-ActiveNoteText; if ($t) { $t.ToggleStyle([System.Drawing.FontStyle]::Bold); $t.Box.Focus() } } $fmt
    $b.Font = New-Object System.Drawing.Font($UiFont, (Fz 9), [System.Drawing.FontStyle]::Bold)
    $b = New-Button 'I' 'Italic (Ctrl+I)'    { $t = Get-ActiveNoteText; if ($t) { $t.ToggleStyle([System.Drawing.FontStyle]::Italic); $t.Box.Focus() } } $fmt
    $b.Font = New-Object System.Drawing.Font($UiFont, (Fz 9), [System.Drawing.FontStyle]::Italic)
