    $lflow.Controls.AddRange(@($ll, $lh))
    [void](New-Button 'Unlock' 'Enter the Secrets master password to read and edit it' { if ($NoteUI.Current) { Open-Note $NoteUI.Current -Prompt } } $lflow $Glyph.Lock 1)
    $lp.Controls.Add($lflow)
