    $fmenu = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void]$fmenu.Items.Add('Open', $null, { $p = Get-SelectedAttachment; if ($p) { Start-Process -FilePath $p } })
    [void]$fmenu.Items.Add('Show in Explorer', $null, { $p = Get-SelectedAttachment; if ($p) { Start-Process explorer.exe "/select,`"$p`"" } })
    [void]$fmenu.Items.Add('-')
    [void]$fmenu.Items.Add('Remove', $null, {
