        }
    }
    foreach ($ctl in $files, $ap) { $ctl.add_DragEnter($dragEnter); $ctl.add_DragDrop($dragDrop) }

    $NoteUI.SaveTimer = New-Object System.Windows.Forms.Timer
    $NoteUI.SaveTimer.Interval = 1000
    $NoteUI.SaveTimer.add_Tick({ Save-CurrentNote })

    $canvas.add_Changed({ Start-NoteAutosave })
    $canvas.add_FilesPasted({ Add-NoteFiles $NoteUI.Canvas.PastedFiles })

    $nlist.add_MeasureItem({
        param($src, $e)
        $row = Get-NoteRow $e.Index
        $e.ItemHeight = if ($row -and $row.IsFolder) { $FontMain.Height + (Px 16) } else { $NoteUI.TitleFont.Height + $FontSmall.Height + (Px 18) }
    })
    $nlist.add_DrawItem({
        param($src, $e)
        $row = Get-NoteRow $e.Index
        if (-not $row) { return }
        $r = $e.Bounds; $g = $e.Graphics
        $selected = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $drop = $NoteUI.DropIndex -eq $e.Index
        $bg = if ($drop) { $C.SelLine } elseif ($selected) { $C.Sel } elseif ($row.IsFolder) { $C.Panel } else { $C.Panel }
        $brush = New-Object System.Drawing.SolidBrush $bg
        $g.FillRectangle($brush, $r); $brush.Dispose()
        if ($row.IsFolder) {
            $x = $r.X + (Px 8) + $row.Depth * (Px 18)
            $chev = if ($row.Open) { [string][char]0xE70D } else { [string][char]0xE76C }
            $flags = [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding'
            if ($FontIconSmall) {
                [System.Windows.Forms.TextRenderer]::DrawText($g, $chev, $FontIconSmall, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 16), $r.Height)), $C.Dim, $flags)
                [System.Windows.Forms.TextRenderer]::DrawText($g, $Glyph.Folder, $FontIconSmall, (New-Object System.Drawing.Rectangle(($x + (Px 18)), $r.Y, (Px 20), $r.Height)), $C.Yellow, $flags)
            } else {
                [System.Windows.Forms.TextRenderer]::DrawText($g, $(if ($row.Open) { 'v' } else { '>' }), $FontMain, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 16), $r.Height)), $C.Dim, $flags)
            }
            $countText = [string]$row.Count
            $cw = [System.Windows.Forms.TextRenderer]::MeasureText($countText, $FontSmall).Width
            $nameRect = New-Object System.Drawing.Rectangle(($x + (Px 42)), $r.Y, ($r.Right - $x - (Px 60) - $cw), $r.Height)
            [System.Windows.Forms.TextRenderer]::DrawText($g, $row.Label, $NoteUI.TitleFont, $nameRect, $C.Fore, $TextFlags)
            $countRect = New-Object System.Drawing.Rectangle(($r.Right - $cw - (Px 12)), $r.Y, ($cw + (Px 4)), $r.Height)
            [System.Windows.Forms.TextRenderer]::DrawText($g, $countText, $FontSmall, $countRect, $C.Dim, $TextFlags)
        } else {
            $indent = if ($row.Folder -and (Get-NoteFolder $row.Folder)) { (Px 26) + (Get-FolderDepth $row.Folder) * (Px 18) } else { 0 }
            if ($selected -and -not $drop) { $bar = New-Object System.Drawing.SolidBrush $C.Accent; $g.FillRectangle($bar, $r.X, ($r.Y + (Px 6)), (Px 3), ($r.Height - (Px 12))); $bar.Dispose() }
            $x = $r.X + (Px 12) + $indent; $w = $r.Width - (Px 20) - $indent
            $th = $NoteUI.TitleFont.Height + (Px 2)
            $titleRect = New-Object System.Drawing.Rectangle($x, ($r.Y + (Px 7)), $w, $th)
            [System.Windows.Forms.TextRenderer]::DrawText($g, (Get-NoteTitle $row), $NoteUI.TitleFont, $titleRect, $C.Fore, $TextFlags)
            $preview = if ($row.Locked) { 'Locked' } else { Get-Preview $row.Text }
            $meta = "$(if ($row.Remind) { "Reminder $(Format-ReminderTime $row.Remind)   $Dot   " })$(Format-Age $row.Modified)   $Dot   $preview"
            $metaRect = New-Object System.Drawing.Rectangle($x, $titleRect.Bottom, $w, ($FontSmall.Height + (Px 2)))
            [System.Windows.Forms.TextRenderer]::DrawText($g, $meta, $FontSmall, $metaRect, $C.Dim, $TextFlags)
        }
        $g.DrawLine($LinePen, $r.X, $r.Bottom - 1, $r.Right, $r.Bottom - 1)
    })
    $NoteUI.DropIndex = -1

    # Click a folder to open / close it. Drag a note or a folder onto a folder to move it there,
    # or onto a note outside folders / the empty space to move it to the top level.
    $nlist.add_MouseDown({
        param($src, $e)
        $NoteUI.DragItem = $null; $NoteUI.ClickFolder = $null
        $i = $src.IndexFromPoint($e.Location)
        $row = Get-NoteRow $i
        if (-not $row) { return }
        if ($e.Button -eq 'Right') { if ($i -ge 0 -and $src.SelectedIndex -ne $i) { $src.SelectedIndex = $i }; return }
        if ($e.Button -ne 'Left') { return }
        if ($row.IsFolder) { $NoteUI.SelectedFolder = $row.Name; $NoteUI.ClickFolder = $row.Name; $NoteUI.DragItem = "devtools-folder:$($row.Name)" }
        else { $NoteUI.DragItem = "devtools-note:$($row.Id)" }
        $NoteUI.DragFrom = $e.Location
    })
    $nlist.add_MouseMove({
        param($src, $e)
        if ($e.Button -ne 'Left' -or -not $NoteUI.DragItem) { return }
        if ([Math]::Abs($e.X - $NoteUI.DragFrom.X) + [Math]::Abs($e.Y - $NoteUI.DragFrom.Y) -lt (Px 8)) { return }
        $data = $NoteUI.DragItem
        $NoteUI.DragItem = $null; $NoteUI.ClickFolder = $null
        [void]$src.DoDragDrop($data, 'Move')
    })
    $nlist.add_MouseUp({
        param($src, $e)
        if ($NoteUI.ClickFolder) { $f = $NoteUI.ClickFolder; $NoteUI.ClickFolder = $null; Switch-NoteFolder $f }
        $NoteUI.DragItem = $null
    })
    $nlist.add_DragOver({
        param($src, $e)
        $data = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::UnicodeText)) { [string]$e.Data.GetData([System.Windows.Forms.DataFormats]::UnicodeText) } else { '' }
        if (-not ($data.StartsWith('devtools-note:') -or $data.StartsWith('devtools-folder:'))) { $e.Effect = 'None'; return }
        $i = $src.IndexFromPoint($src.PointToClient((New-Object System.Drawing.Point($e.X, $e.Y))))
        $row = Get-NoteRow $i
        $targetName = if ($row -and $row.IsFolder) { $row.Name } elseif ($row -and $row.Folder -and (Get-NoteFolder $row.Folder)) { $row.Folder } else { '' }
        $target = -1
        if ($targetName) { for ($k = 0; $k -lt $NoteUI.View.Count; $k++) { if ($NoteUI.View[$k].IsFolder -and $NoteUI.View[$k].Name -eq $targetName) { $target = $k; break } } }
        if ($data.StartsWith('devtools-folder:')) {
            $moving = $data.Substring(16)
            if ($targetName -and (Test-InFolder $targetName $moving)) { $e.Effect = 'None'; if ($NoteUI.DropIndex -ne -1) { $NoteUI.DropIndex = -1; $src.Invalidate() }; return }
        }
        $e.Effect = 'Move'
        if ($NoteUI.DropIndex -ne $target) { $NoteUI.DropIndex = $target; $src.Invalidate() }
    })
    $nlist.add_DragLeave({ param($src, $e) $NoteUI.DropIndex = -1; $src.Invalidate() })
    $nlist.add_DragDrop({
        param($src, $e)
        $data = [string]$e.Data.GetData([System.Windows.Forms.DataFormats]::UnicodeText)
        $target = $NoteUI.DropIndex
        $NoteUI.DropIndex = -1
        $folder = if ($target -ge 0) { $NoteUI.View[$target].Name } else { '' }
        if ($data.StartsWith('devtools-folder:')) { Move-NoteFolder $data.Substring(16) $folder; return }
        $id = $data.Substring(14)
        $note = $script:Notes | Where-Object { $_.Id -eq $id } | Select-Object -First 1
        Move-NoteToFolder $note $folder
    })

    # Right-click menu: move a note to a folder; rename / delete a folder.
    $lmenu = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $lmenu.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        # what is under the mouse (empty space -> new note / folder at the top level)
        $hit = $NoteUI.List.IndexFromPoint($NoteUI.List.PointToClient([System.Windows.Forms.Cursor]::Position))
        if ($hit -lt 0) {
            [void](Add-MenuItem $src 'New note' { $NoteUI.SelectedFolder = $null; [void](New-Note '' ''); $NoteUI.Title.Focus() } $Glyph.Add)
            [void](Add-MenuItem $src 'New folder...' { [void](New-NoteFolderPrompt '') } $Glyph.Folder)
            return
        }
        $row = Get-NoteRow $NoteUI.List.SelectedIndex
        if (-not $row) { $e.Cancel = $true; return }
        if ($row.IsFolder) {
            $name = $row.Name
            [void](Add-MenuItem $src 'New note here' { [void](New-Note '' $NoteUI.SelectedFolder); $NoteUI.Title.Focus() } $Glyph.Add)
            [void](Add-MenuItem $src 'New subfolder...' { [void](New-NoteFolderPrompt $NoteUI.SelectedFolder) } $Glyph.Folder)
            [void](Add-MenuItem $src 'Rename folder...' { Rename-NoteFolder $NoteUI.SelectedFolder } $Glyph.Edit)
            if ($name.Contains('/')) { [void](Add-MenuItem $src 'Move to the top level' { Move-NoteFolder $NoteUI.SelectedFolder '' } $Glyph.Undo) }
            [void]$src.Items.Add('-')
            [void](Add-MenuItem $src 'Delete folder' { Remove-NoteFolder $NoteUI.SelectedFolder } $Glyph.Delete)
        } else {
            $move = New-Object System.Windows.Forms.ToolStripMenuItem('Move to folder', (New-GlyphImage $Glyph.Folder))
            foreach ($folder in @($script:NoteFolders | Sort-Object { $_.Name.Replace('/', [string][char]1) })) {
                $label = ('     ' * (Get-FolderDepth $folder.Name)) + (Get-FolderLeaf $folder.Name)
                $it = $move.DropDownItems.Add($label, $null, { param($s2, $e2) Move-NoteToFolder $NoteUI.Current $s2.Tag })
                $it.Tag = $folder.Name
                if ($row.Folder -eq $folder.Name) { $it.Enabled = $false }
            }
            if ($script:NoteFolders.Count -gt 0) { [void]$move.DropDownItems.Add('-') }
            $it = $move.DropDownItems.Add('No folder', $null, { Move-NoteToFolder $NoteUI.Current '' }); $it.Enabled = [bool]$row.Folder
            [void]$move.DropDownItems.Add('New folder...', $null, { $n = $NoteUI.Current; $name = New-NoteFolderPrompt $(if ($n.Folder) { $n.Folder } else { '' }); if ($name) { Move-NoteToFolder $n $name } })
            $move.DropDown.Renderer = $MenuRenderer
            [void]$src.Items.Add($move)
            [void](Add-MenuItem $src 'New folder...' { $nn = $NoteUI.Current; [void](New-NoteFolderPrompt $(if ($nn -and $nn.Folder) { $nn.Folder } else { '' })) } $Glyph.Folder)
            [void](Add-MenuItem $src $(if ($row.Remind) { "Reminder: $(Format-ReminderTime $row.Remind)..." } else { 'Remind me...' }) { Show-NoteReminder $NoteUI.Current } $Glyph.History)
            if (-not $NoteUI.ShowingLock) {
                if ($row.Locked) { [void](Add-MenuItem $src 'Remove the lock' { Set-NoteLock $false } $Glyph.Lock) } else { [void](Add-MenuItem $src 'Lock with the master password' { Set-NoteLock $true } $Glyph.Lock) }
                [void](Add-MenuItem $src 'Export as Markdown...' { Export-CurrentNote 'md' } $Glyph.Save)
            }
            [void]$src.Items.Add('-')
            [void](Add-MenuItem $src 'Delete note' { Remove-CurrentNote } $Glyph.Delete)
        }
    })
    $nlist.ContextMenuStrip = $lmenu
    $NoteUI.TitleFont = New-Object System.Drawing.Font($UiFont, (Fz 10), [System.Drawing.FontStyle]::Bold)
    $nlist.add_SelectedIndexChanged({
        if ($NoteUI.Updating) { return }
        $row = Get-NoteRow $NoteUI.List.SelectedIndex
        if (-not $row) { return }
        if ($row.IsFolder) { $NoteUI.SelectedFolder = $row.Name; return }
        $NoteUI.SelectedFolder = $null
        if (-not $NoteUI.Current -or $row.Id -ne $NoteUI.Current.Id) { Open-Note $row }
    })
    # Left / Right close / open the selected folder.
    $nlist.add_KeyDown({
        param($src, $e)
        $row = Get-NoteRow $src.SelectedIndex
        if ($row -and $row.IsFolder -and (($e.KeyCode -eq 'Left' -and $row.Open) -or ($e.KeyCode -eq 'Right' -and -not $row.Open) -or $e.KeyCode -eq 'Return')) {
            Switch-NoteFolder $row.Name; $e.Handled = $true; $e.SuppressKeyPress = $true
        }
    })
    $nsearch.add_TextChanged({ Update-NoteList })
    $ntitle.add_TextChanged({ Start-NoteAutosave })
    $ntitle.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { $NoteUI.Canvas.Focus(); $e.SuppressKeyPress = $true } })
    $nf.add_KeyDown({
        param($src, $e)
        $handled = $true
        if ($e.Control -and $e.Shift -and $e.KeyCode -eq 'N') { [void](New-NoteFolderPrompt) }
        elseif ($e.Control -and $e.KeyCode -eq 'N') { [void](New-Note); $NoteUI.Title.Focus() }
        elseif ($e.Control -and $e.KeyCode -eq 'F') { $NoteUI.Search.Focus(); $NoteUI.Search.SelectAll() }
        elseif ($e.Control -and $e.KeyCode -eq 'S') { Save-CurrentNote }
        else { $handled = $false }
        if ($handled) { $e.Handled = $true; $e.SuppressKeyPress = $true }
    })
    $nf.add_FormClosing({ Save-CurrentNote })
    $nf.add_FormClosed({ param($src, $e) $NoteUI.SaveTimer.Dispose(); $NoteUI.Form = $null; $NoteUI.Current = $null; $NoteUI.LockPanel = $null; $NoteUI.LockHint = $null; $NoteUI.ShowingLock = $false; $src.Dispose() })
    Register-ThemedWindow $nf
    $nsearch.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Search notes...') })
    $ntitle.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Title') })

    $nf.Show()
    [PowerClipHost]::EnsureShown($nf.Handle)
    $split.SplitterDistance = Px (310 * $TextZoom)
    if ($script:Notes.Count -eq 0) { [void](New-Note) }
    else {
        Update-NoteList
        $first = @($NoteUI.View | Where-Object { -not $_.IsFolder })[0]
        if (-not $first) { $first = @($script:Notes | Sort-Object Modified -Descending)[0] }
        Open-Note $first; Update-NoteList
    }
    $nf.Activate()
    $NoteUI.Canvas.Focus()
}

# Puts the selected clips onto a note's page, one below the other: text as a text box,
# images as pictures, files as attachments.
function Send-ClipsToNotes([bool]$NewNote) {
    $sel = @(Get-SelectedAll)
    if ($sel.Count -eq 0) { return }
    Hide-Picker
    $hadNote = [bool]($NoteUI.Form -and $NoteUI.Current)
    Show-Notes
    if ($NewNote -or -not $hadNote) {
        $first = $sel[0]
        $title = switch ($first.Kind) {
            'image' { "Image $($first.Width) x $($first.Height)" }
            'files' { (@($first.Text -split "`n") | ForEach-Object { Split-Path -Leaf $_ }) -join ', ' }
            default { (@($first.Text.Trim() -split "`n")[0]).Trim() }
        }
        if ($title.Length -gt 80) { $title = $title.Substring(0, 80) }
        [void](New-Note $title)
    }
    $canvas = $NoteUI.Canvas
    foreach ($item in $sel) {
        $y = $canvas.NextFreeY()
        switch ($item.Kind) {
            'text'  { [void]$canvas.AddText((Px 16), $y, 0, $null, $item.Text) }
            'image' { [void]$canvas.AddImage((Px 16), $y, 0, (Read-ImageFile (Get-DataPath $item.Image)), $null) }
            'files' { Add-NoteFiles @($item.Files | ForEach-Object { Get-DataPath $_ }) }
        }
    }
    Start-NoteAutosave
    Save-CurrentNote
    $NoteUI.Form.Activate()
}

Import-Notes

# ---------------------------------------------------------------------------
# Secrets: an encrypted vault for passwords, API keys and tokens, locked with a master password.
# Stored in data\vault.dat (AES-256 + HMAC, PBKDF2 key), so it travels with the data folder.
# Copied secrets are hidden from the clipboard history (ours and Windows') and cleared after a while.
# ---------------------------------------------------------------------------
$VaultFile = Join-Path $DataDir 'vault.dat'
$VaultUI = @{ Form = $null; Key = $null; Entries = $null; View = (New-Object System.Collections.Generic.List[object]); Current = $null
              Updating = $false; LastUse = (Get-Date); Pending = $null; ClearText = $null; ClearAt = $null }

# Copies text so that clipboard tools and Windows clipboard history skip it.
function Set-SecretClipboard([string]$Text, [string]$What = 'Secret') {
    if (-not $Text) { return }
    $data = New-Object System.Windows.Forms.DataObject
    $data.SetText($Text, [System.Windows.Forms.TextDataFormat]::UnicodeText)
    $data.SetData('ExcludeClipboardContentFromMonitorProcessing', (New-Object IO.MemoryStream(, [byte[]](0, 0, 0, 0))))
    $data.SetData('CanIncludeInClipboardHistory', (New-Object IO.MemoryStream(, [BitConverter]::GetBytes([int]0))))
    $data.SetData('CanUploadToCloudClipboard', (New-Object IO.MemoryStream(, [BitConverter]::GetBytes([int]0))))
    try { [System.Windows.Forms.Clipboard]::SetDataObject($data, $true, 10, 50) } catch { return }
    $VaultUI.ClearText = $Text
    $VaultUI.ClearAt = (Get-Date).AddSeconds($script:VaultClearSec)
    $VaultUI.ClearWhat = $What
    $VaultClearTimer.Start()
    Update-VaultStatus
}

$VaultClearTimer = New-Object System.Windows.Forms.Timer
$VaultClearTimer.Interval = 1000
$VaultClearTimer.add_Tick({
    if (-not $VaultUI.ClearAt) { $VaultClearTimer.Stop(); return }
    if ((Get-Date) -ge $VaultUI.ClearAt) {
        try { if ([System.Windows.Forms.Clipboard]::GetText() -eq $VaultUI.ClearText) { [System.Windows.Forms.Clipboard]::Clear() } } catch { }
        $VaultUI.ClearText = $null; $VaultUI.ClearAt = $null
        $VaultClearTimer.Stop()
    }
    Update-VaultStatus
})

# Locks after a few idle minutes.
$VaultLockTimer = New-Object System.Windows.Forms.Timer
$VaultLockTimer.Interval = 10000
$VaultLockTimer.add_Tick({
    if (($VaultUI.Key -or $script:NotesKey) -and ((Get-Date) - $VaultUI.LastUse).TotalMinutes -ge $script:VaultLockMin) { Lock-Vault }
})
$VaultLockTimer.Start()

function Touch-Vault { $VaultUI.LastUse = Get-Date }

function Save-Vault {
    if (-not $VaultUI.Key -or $null -eq $VaultUI.Entries) { return }
    $VaultUI.SaveTimer.Stop()
    $json = ConvertTo-Json -InputObject @($VaultUI.Entries.ToArray()) -Depth 3 -Compress
    $bytes = [PowerClipVault]::Seal($json, $VaultUI.Key)
    $tmp = "$VaultFile.tmp"
    [IO.File]::WriteAllBytes($tmp, $bytes)
    if (Test-Path $VaultFile) { [IO.File]::Replace($tmp, $VaultFile, [NullString]::Value) } else { [IO.File]::Move($tmp, $VaultFile) }
}

function Lock-Vault {
    if ($NoteUI.Form -and $NoteUI.Current -and $NoteUI.Current.Locked) { Save-CurrentNote }     # while the key is still here
    if ($VaultUI.Key) {
        try { Save-Vault } catch { Write-Log "vault save failed: $_" }
        $VaultUI.Key.Dispose()
    }
    $VaultUI.Key = $null; $VaultUI.Entries = $null; $VaultUI.Current = $null; $VaultUI.View.Clear()
    if ($VaultUI.Form -and -not $VaultUI.Form.IsDisposed) {
        $VaultUI.Updating = $true
        foreach ($f in $VaultUI.Fields.Values) { $f.Text = '' }
        $VaultUI.Updating = $false
        $VaultUI.List.Items.Clear()
        Show-VaultLockScreen
    }
    Lock-Notes
}

function Show-VaultLockScreen {
    $exists = Test-Path $VaultFile
    $VaultUI.Main.Visible = $false
    $VaultUI.Lock.Visible = $true
    $VaultUI.LockTitle.Text = if ($exists) { 'Secrets are locked' } else { 'Create your secrets vault' }
    $VaultUI.LockHint.Text = if ($exists) { 'Enter your master password.' } else {
        "Choose a master password. It encrypts everything in the vault (AES-256).`nThere is no way to recover it, so pick one you will remember." }
    $VaultUI.Confirm.Visible = -not $exists
    $VaultUI.ConfirmLabel.Visible = -not $exists
    $VaultUI.UnlockBtn.Text = if ($exists) { 'Unlock' } else { 'Create vault' }
    $VaultUI.Password.Text = ''; $VaultUI.Confirm.Text = ''; $VaultUI.LockError.Text = ''
    [void]$VaultUI.Password.Focus()
}

function Unlock-Vault {
    $pw = $VaultUI.Password.Text
    $VaultUI.LockError.Text = ''
    if (-not (Test-Path $VaultFile)) {
        if ($pw.Length -lt 8) { $VaultUI.LockError.Text = 'Use at least 8 characters.'; return }
        if ($pw -ne $VaultUI.Confirm.Text) { $VaultUI.LockError.Text = 'The two passwords are different.'; return }
        $VaultUI.Key = [PowerClipVault]::NewKey($pw)
        $VaultUI.Entries = New-Object System.Collections.Generic.List[object]
        Save-Vault
    } else {
        $VaultUI.Form.Cursor = 'WaitCursor'
        try {
            $key = $null
            $json = [PowerClipVault]::Open([IO.File]::ReadAllBytes($VaultFile), $pw, [ref]$key)
            $VaultUI.Key = $key
            $VaultUI.Entries = New-Object System.Collections.Generic.List[object]
            if ($json.Trim() -and $json.Trim() -ne '[]') {
                foreach ($x in @(ConvertFrom-JsonList $json)) {
                    $VaultUI.Entries.Add([pscustomobject]@{ Id = [string]$x.Id; Name = [string]$x.Name; User = [string]$x.User; Secret = [string]$x.Secret
                                                            Url = [string]$x.Url; Notes = [string]$x.Notes; Modified = [string]$x.Modified })
                }
            }
        } catch {
            $VaultUI.LockError.Text = $_.Exception.InnerException.Message
            if (-not $VaultUI.LockError.Text) { $VaultUI.LockError.Text = $_.Exception.Message }
            $VaultUI.Password.SelectAll()
            return
        } finally { $VaultUI.Form.Cursor = 'Default' }
    }
    $VaultUI.Password.Text = ''; $VaultUI.Confirm.Text = ''
    Touch-Vault
    $VaultUI.Lock.Visible = $false
    $VaultUI.Main.Visible = $true
    Update-VaultList -SelectIndex 0
    if ($VaultUI.Pending) {
        $p = $VaultUI.Pending; $VaultUI.Pending = $null
        Add-VaultEntry $p.Name $p.Secret
        if ($p.ClipId) { Remove-Clip $p.ClipId; Save-History; Update-List }
    }
}

function Update-VaultList([int]$SelectIndex = -1) {
    if ($null -eq $VaultUI.Entries) { return }
    $keep = $VaultUI.Current
    $q = $VaultUI.Search.Text.Trim()
    $VaultUI.View.Clear()
    foreach ($e in ($VaultUI.Entries | Sort-Object Name)) {
        if ($q -and "$($e.Name) $($e.User) $($e.Url) $($e.Notes)".IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        $VaultUI.View.Add($e)
    }
    $l = $VaultUI.List
    $l.BeginUpdate(); $l.Items.Clear()
    for ($i = 0; $i -lt $VaultUI.View.Count; $i++) { [void]$l.Items.Add($i) }
    $l.EndUpdate()
    $idx = -1
    if ($keep) { for ($i = 0; $i -lt $VaultUI.View.Count; $i++) { if ($VaultUI.View[$i].Id -eq $keep.Id) { $idx = $i } } }
    if ($SelectIndex -ge 0 -and $VaultUI.View.Count -gt 0) { $idx = [Math]::Min($SelectIndex, $VaultUI.View.Count - 1) }
    if ($idx -ge 0) { $l.SelectedIndex = $idx } else { Show-VaultEntry $null }
    $VaultUI.Count.Text = "$($VaultUI.Entries.Count) $(if ($VaultUI.Entries.Count -eq 1) { 'secret' } else { 'secrets' })"
}

function Show-VaultEntry($Entry) {
    $VaultUI.Current = $Entry
    $VaultUI.Updating = $true
    foreach ($k in $VaultUI.Fields.Keys) { $VaultUI.Fields[$k].Text = if ($Entry) { [string]$Entry.$k } else { '' } }
    foreach ($f in $VaultUI.Fields.Values) { $f.Enabled = [bool]$Entry }
    $VaultUI.Fields.Secret.UseSystemPasswordChar = -not $VaultUI.ShowSecret.Selected
    $VaultUI.Updating = $false
}

function Add-VaultEntry([string]$Name = 'New secret', [string]$Secret = '') {
    if ($null -eq $VaultUI.Entries) { return }
    $e = [pscustomobject]@{ Id = [guid]::NewGuid().ToString('N'); Name = $Name; User = ''; Secret = $Secret; Url = ''; Notes = ''
                            Modified = (Get-Date).ToString('s') }
    $VaultUI.Entries.Add($e)
    $VaultUI.Current = $e
    $VaultUI.Search.Text = ''
    Update-VaultList
    Save-Vault
    $VaultUI.Fields.Name.Focus(); $VaultUI.Fields.Name.SelectAll()
}

function Remove-VaultEntry {
    $e = $VaultUI.Current
    if (-not $e) { return }
    $r = [System.Windows.Forms.MessageBox]::Show($VaultUI.Form, "Delete `"$($e.Name)`"? This cannot be undone.", 'Secrets', 'YesNo', 'Warning')
    if ($r -ne 'Yes') { return }
    [void]$VaultUI.Entries.Remove($e)
    $VaultUI.Current = $null
    Update-VaultList -SelectIndex 0
    Save-Vault
}

function Update-VaultStatus {
    if (-not $VaultUI.Form -or $VaultUI.Form.IsDisposed) { return }
    if ($VaultUI.ClearAt) {
        $left = [Math]::Max(0, [int][Math]::Ceiling(($VaultUI.ClearAt - (Get-Date)).TotalSeconds))
        $VaultUI.Status.Text = "$($VaultUI.ClearWhat) copied  $Dot  the clipboard is cleared in $left s  $Dot  not saved in any clipboard history"
        $VaultUI.Status.ForeColor = $C.Accent
    } else {
        $VaultUI.Status.Text = "Encrypted with your master password  $Dot  locks after $($script:VaultLockMin) min idle  $Dot  copied secrets clear after $($script:VaultClearSec) s"
        $VaultUI.Status.ForeColor = $C.Dim
    }
}

function Show-VaultPasswordDialog {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = 'Change master password'; $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px 420), (Px 230))
    $boxes = @()
    $y = Px 16
    foreach ($label in 'Current password', 'New password', 'Repeat new password') {
        $l = New-Object System.Windows.Forms.Label; $l.Text = $label; $l.AutoSize = $true; $l.Location = New-Object System.Drawing.Point((Px 16), ($y + (Px 4)))
        $b = New-Object System.Windows.Forms.TextBox; $b.UseSystemPasswordChar = $true; $b.BorderStyle = 'FixedSingle'; $b.BackColor = $C.Bg; $b.ForeColor = $C.Fore
        $b.Location = New-Object System.Drawing.Point((Px 190), $y); $b.Width = Px 210
        $d.Controls.AddRange(@($l, $b)); $boxes += $b
        $y += Px 40
    }
    $err = New-Object System.Windows.Forms.Label; $err.AutoSize = $true; $err.ForeColor = $C.Red; $err.Location = New-Object System.Drawing.Point((Px 16), $y)
    $d.Controls.Add($err)
    $ok = New-Object PowerClipButton; $ok.Text = 'Change'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true
    $ok.Location = New-Object System.Drawing.Point((Px 220), (Px 180))
    $cancel = New-Object PowerClipButton; $cancel.Text = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $cancel.Location = New-Object System.Drawing.Point((Px 320), (Px 180))
    $d.Controls.AddRange(@($ok, $cancel)); $d.AcceptButton = $ok; $d.CancelButton = $cancel
    $ok.Tag = @{ Dialog = $d; Boxes = $boxes; Error = $err }
    $ok.add_Click({
        param($src, $e)
        $t = $src.Tag; $b = $t.Boxes
        try { $k = $null; [void][PowerClipVault]::Open([IO.File]::ReadAllBytes($VaultFile), $b[0].Text, [ref]$k); $k.Dispose() }
        catch { $t.Error.Text = 'The current password is wrong.'; return }
        if ($b[1].Text.Length -lt 8) { $t.Error.Text = 'Use at least 8 characters.'; return }
        if ($b[1].Text -ne $b[2].Text) { $t.Error.Text = 'The new passwords are different.'; return }
        $old = $VaultUI.Key
        $VaultUI.Key = [PowerClipVault]::NewKey($b[1].Text)
        Update-DataKeyPassword $b[1].Text
        Update-LockedNotesKey $old $VaultUI.Key
        Save-Vault
        $old.Dispose()
        $t.Dialog.DialogResult = 'OK'
    })
    Register-ThemedWindow $d
    $r = $d.ShowDialog($VaultUI.Form)
    $d.Dispose()
    if ($r -eq 'OK') { [void][System.Windows.Forms.MessageBox]::Show($VaultUI.Form, 'The master password was changed.', 'Secrets') }
}

function Show-Vault {
    Hide-Picker
    if ($VaultUI.Form -and -not $VaultUI.Form.IsDisposed) {
        [PowerClipHost]::EnsureShown($VaultUI.Form.Handle)
        if ($VaultUI.Form.WindowState -eq 'Minimized') { $VaultUI.Form.WindowState = 'Normal' }
        $VaultUI.Form.Activate()
        if ($VaultUI.Key -and $VaultUI.Pending) {
            $p = $VaultUI.Pending; $VaultUI.Pending = $null
            Add-VaultEntry $p.Name $p.Secret
            if ($p.ClipId) { Remove-Clip $p.ClipId; Save-History; Update-List }
        }
        return
    }
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Secrets'
    $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px (980 * $TextZoom)), (Px 620))
    $f.MinimumSize = New-Object System.Drawing.Size((Px 700), (Px 420))
    $f.StartPosition = 'CenterScreen'
    $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $f.KeyPreview = $true
    $VaultUI.Form = $f
    $VaultUI.SaveTimer = New-Object System.Windows.Forms.Timer
    $VaultUI.SaveTimer.Interval = 800
    $VaultUI.SaveTimer.add_Tick({ try { Save-Vault } catch { Write-Log "vault save failed: $_" } })

    # ---- lock screen (centred card)
    $lock = New-Object System.Windows.Forms.Panel
    $lock.Dock = 'Fill'; $lock.BackColor = $C.Bg
    $card = New-Object System.Windows.Forms.Panel
    $card.Size = New-Object System.Drawing.Size((Px (440 * $TextZoom)), (Px (300 * $TextZoom))); $card.BackColor = $C.Card
    $card.add_Paint({
        param($src, $e)
        $e.Graphics.SmoothingMode = 'AntiAlias'
        $p = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(0.5, 0.5, ($src.Width - 1.5), ($src.Height - 1.5))), (Px 10))
        $pen = New-Object System.Drawing.Pen $C.Line; $e.Graphics.DrawPath($pen, $p); $pen.Dispose(); $p.Dispose()
    })
    $lock.add_Resize({ param($src, $e) $cx = $src.Controls[0]; $cx.Location = New-Object System.Drawing.Point([Math]::Max(0, [int](($src.Width - $cx.Width) / 2)), [Math]::Max(0, [int](($src.Height - $cx.Height) / 2.4))) })
    $lock.Controls.Add($card)
    $flow = New-Object System.Windows.Forms.FlowLayoutPanel
    $flow.Dock = 'Fill'; $flow.FlowDirection = 'TopDown'; $flow.WrapContents = $false; $flow.BackColor = $C.Card
    $flow.Padding = New-Object System.Windows.Forms.Padding((Px 26), (Px 20), (Px 26), (Px 10))
    $card.Controls.Add($flow)
    $inner = $card.Width - (Px 52)
    $VaultUI.LockTitle = New-Object System.Windows.Forms.Label
    $VaultUI.LockTitle.AutoSize = $true; $VaultUI.LockTitle.Font = $FontTitle; $VaultUI.LockTitle.BackColor = $C.Card; $VaultUI.LockTitle.ForeColor = $C.Fore
    $VaultUI.LockHint = New-Object System.Windows.Forms.Label
    $VaultUI.LockHint.AutoSize = $true; $VaultUI.LockHint.MaximumSize = New-Object System.Drawing.Size($inner, 0); $VaultUI.LockHint.BackColor = $C.Card; $VaultUI.LockHint.ForeColor = $C.Dim
    $VaultUI.LockHint.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), 0, (Px 10))
    $VaultUI.Password = New-Object System.Windows.Forms.TextBox
    $VaultUI.Password.UseSystemPasswordChar = $true; $VaultUI.Password.Width = $inner; $VaultUI.Password.BorderStyle = 'FixedSingle'
    $VaultUI.Password.BackColor = $C.Bg; $VaultUI.Password.ForeColor = $C.Fore
    $VaultUI.ConfirmLabel = New-Object System.Windows.Forms.Label
    $VaultUI.ConfirmLabel.Text = 'Repeat it'; $VaultUI.ConfirmLabel.AutoSize = $true; $VaultUI.ConfirmLabel.BackColor = $C.Card; $VaultUI.ConfirmLabel.ForeColor = $C.Dim
    $VaultUI.ConfirmLabel.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, (Px 2))
    $VaultUI.Confirm = New-Object System.Windows.Forms.TextBox
    $VaultUI.Confirm.UseSystemPasswordChar = $true; $VaultUI.Confirm.Width = $inner; $VaultUI.Confirm.BorderStyle = 'FixedSingle'
    $VaultUI.Confirm.BackColor = $C.Bg; $VaultUI.Confirm.ForeColor = $C.Fore
    $VaultUI.LockError = New-Object System.Windows.Forms.Label
    $VaultUI.LockError.AutoSize = $true; $VaultUI.LockError.BackColor = $C.Card; $VaultUI.LockError.ForeColor = $C.Red
    $VaultUI.LockError.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), 0, (Px 4))
    $flow.Controls.AddRange(@($VaultUI.LockTitle, $VaultUI.LockHint, $VaultUI.Password, $VaultUI.ConfirmLabel, $VaultUI.Confirm, $VaultUI.LockError))
    $VaultUI.UnlockBtn = New-Button 'Unlock' '' { Unlock-Vault } $flow $Glyph.Lock 1
    foreach ($b in $VaultUI.Password, $VaultUI.Confirm) {
        $b.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Unlock-Vault; $e.SuppressKeyPress = $true } })
    }
    $VaultUI.Lock = $lock
    $f.Controls.Add($lock)

    # ---- unlocked view
    $main = New-Object System.Windows.Forms.Panel
    $main.Dock = 'Fill'; $main.BackColor = $C.Bg; $main.Visible = $false
    $VaultUI.Main = $main

    $detail = New-Object System.Windows.Forms.TableLayoutPanel
    $detail.Dock = 'Fill'; $detail.ColumnCount = 3; $detail.BackColor = $C.Bg
    $detail.Padding = New-Object System.Windows.Forms.Padding((Px 20), (Px 16), (Px 20), (Px 10))
    [void]$detail.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    [void]$detail.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    [void]$detail.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    $main.Controls.Add($detail)
    $VaultUI.Fields = [ordered]@{}
    $rowIndex = 0
    foreach ($spec in @(@('Name', 'Name'), @('User', 'Username'), @('Secret', 'Secret'), @('Url', 'Website'), @('Notes', 'Notes'))) {
        $l = New-Object System.Windows.Forms.Label
        $l.Text = $spec[1]; $l.AutoSize = $true; $l.ForeColor = $C.Dim; $l.BackColor = $C.Bg
        $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), (Px 14), 0)
        $box = New-Object System.Windows.Forms.TextBox
        $box.Dock = 'Fill'; $box.BorderStyle = 'FixedSingle'; $box.BackColor = $C.Card; $box.ForeColor = $C.Fore
        $box.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), (Px 6), (Px 4))
        if ($spec[0] -eq 'Secret') { $box.Font = New-Object System.Drawing.Font('Consolas', (Fz 11)); $box.UseSystemPasswordChar = $true }
        if ($spec[0] -eq 'Notes') { $box.Multiline = $true; $box.ScrollBars = 'Vertical'; $box.AcceptsReturn = $true }
        $box.Tag = $spec[0]
        $box.add_TextChanged({
            param($src, $e)
            if ($VaultUI.Updating -or -not $VaultUI.Current) { return }
            $VaultUI.Current.($src.Tag) = $src.Text
            $VaultUI.Current.Modified = (Get-Date).ToString('s')
            Touch-Vault
            if ($src.Tag -in 'Name', 'User') { $VaultUI.List.Invalidate() }
            $VaultUI.SaveTimer.Stop(); $VaultUI.SaveTimer.Start()
        })
        $detail.Controls.Add($l, 0, $rowIndex)
        $detail.Controls.Add($box, 1, $rowIndex)
        $actions = New-Object System.Windows.Forms.FlowLayoutPanel
        $actions.AutoSize = $true; $actions.WrapContents = $false; $actions.BackColor = $C.Bg; $actions.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), 0, 0)
        switch ($spec[0]) {
            'User'   { [void](New-Button 'Copy' 'Copy the username' { Touch-Vault; Set-SecretClipboard $VaultUI.Fields.User.Text 'Username' } $actions $Glyph.Copy) }
            'Secret' {
                [void](New-Button 'Copy' 'Copy the secret (Ctrl+C when nothing is selected). It is cleared from the clipboard after a while.' { Touch-Vault; Set-SecretClipboard $VaultUI.Fields.Secret.Text } $actions $Glyph.Copy 1)
                $VaultUI.ShowSecret = New-Button 'Show' 'Show / hide the secret' {
                    param($src, $e)
                    $src.Selected = -not $src.Selected; $src.Invalidate()
                    $VaultUI.Fields.Secret.UseSystemPasswordChar = -not $src.Selected
                    Touch-Vault
                } $actions $Glyph.View 2
                [void](New-Button 'Generate' 'Replace with a new random password (20 characters)' {
                    Touch-Vault
                    if ($VaultUI.Fields.Secret.Text -and [System.Windows.Forms.MessageBox]::Show($VaultUI.Form, 'Replace the current secret with a new random password?', 'Secrets', 'YesNo', 'Question') -ne 'Yes') { return }
                    $VaultUI.Fields.Secret.Text = [PowerClipVault]::Generate(20, $true, $true, $true, $true)
                } $actions $Glyph.Refresh 2)
            }
            'Url'    { [void](New-Button 'Open' 'Open the website' { $u = $VaultUI.Fields.Url.Text.Trim(); if ($u) { if ($u -notmatch '^[a-z]+://') { $u = "https://$u" }; try { Start-Process $u } catch { } } } $actions $Glyph.Globe 2) }
        }
        $detail.Controls.Add($actions, 2, $rowIndex)
        if ($spec[0] -eq 'Notes') { [void]$detail.RowStyles.Add((New-Object System.Windows.Forms.RowStyle('Percent', 100))) }
        else { [void]$detail.RowStyles.Add((New-Object System.Windows.Forms.RowStyle('AutoSize'))) }
        $VaultUI.Fields[$spec[0]] = $box
        $rowIndex++
    }
    $detail.RowCount = $rowIndex

    $VaultUI.Status = New-Object System.Windows.Forms.Label
    $VaultUI.Status.Dock = 'Bottom'; $VaultUI.Status.Height = $FontSmall.Height + (Px 12); $VaultUI.Status.Font = $FontSmall
    $VaultUI.Status.Padding = New-Object System.Windows.Forms.Padding((Px 12), 0, 0, 0); $VaultUI.Status.TextAlign = 'MiddleLeft'
    $VaultUI.Status.BackColor = $C.Panel; $VaultUI.Status.ForeColor = $C.Dim
    $main.Controls.Add($VaultUI.Status)

    # left: search, list, buttons
    $left = New-Object System.Windows.Forms.Panel
    $left.Dock = 'Left'; $left.Width = Px (300 * $TextZoom); $left.BackColor = $C.Panel
    $list = New-Object System.Windows.Forms.ListBox
    $list.Dock = 'Fill'; $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawFixed'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + $FontSmall.Height + (Px 16); $list.BackColor = $C.Panel; $list.ForeColor = $C.Fore
    $list.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0 -or $e.Index -ge $VaultUI.View.Count) { return }
        $it = $VaultUI.View[$e.Index]
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $b = New-Object System.Drawing.SolidBrush $(if ($sel) { $C.Sel } else { $C.Panel })
        $e.Graphics.FillRectangle($b, $e.Bounds); $b.Dispose()
        if ($sel) { $bar = New-Object System.Drawing.SolidBrush $C.Accent; $e.Graphics.FillRectangle($bar, $e.Bounds.X, ($e.Bounds.Y + (Px 6)), (Px 3), ($e.Bounds.Height - (Px 12))); $bar.Dispose() }
        $x = $e.Bounds.X + (Px 14); $w = $e.Bounds.Width - (Px 20)
        $name = if ($it.Name) { $it.Name } else { '(no name)' }
        $sub = if ($it.User) { $it.User } elseif ($it.Url) { $it.Url } else { '' }
        $top = New-Object System.Drawing.Rectangle($x, ($e.Bounds.Y + (Px 6)), $w, ($FontMain.Height + (Px 2)))
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $name, $FontMain, $top, $C.Fore, $TextFlags)
        $bot = New-Object System.Drawing.Rectangle($x, ($top.Bottom), $w, ($FontSmall.Height + (Px 2)))
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $sub, $FontSmall, $bot, $C.Dim, $TextFlags)
    })
    $list.add_SelectedIndexChanged({
        Touch-Vault
        $i = $VaultUI.List.SelectedIndex
        if ($i -ge 0 -and $i -lt $VaultUI.View.Count) { Show-VaultEntry $VaultUI.View[$i] } else { Show-VaultEntry $null }
    })
    $list.add_DoubleClick({ Touch-Vault; Set-SecretClipboard $VaultUI.Fields.Secret.Text })
    $VaultUI.List = $list
    $left.Controls.Add($list)
    $searchWrap = New-Object System.Windows.Forms.Panel
    $searchWrap.Dock = 'Top'; $searchWrap.Height = $FontMain.Height + (Px 22); $searchWrap.BackColor = $C.Panel
    $searchWrap.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 10), (Px 10), (Px 4))
    $VaultUI.Search = New-Object System.Windows.Forms.TextBox
    $VaultUI.Search.Dock = 'Fill'; $VaultUI.Search.BorderStyle = 'FixedSingle'; $VaultUI.Search.BackColor = $C.Bg; $VaultUI.Search.ForeColor = $C.Fore
    $VaultUI.Search.add_TextChanged({ Touch-Vault; Update-VaultList })
    $VaultUI.Search.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Search secrets...') })
    $VaultUI.Search.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Down' -and $VaultUI.List.Items.Count) { $VaultUI.List.Focus(); $e.SuppressKeyPress = $true } })
    $searchWrap.Controls.Add($VaultUI.Search)
    $left.Controls.Add($searchWrap)
    $leftBtns = New-Object System.Windows.Forms.FlowLayoutPanel
    $leftBtns.Dock = 'Bottom'; $leftBtns.Height = $FontButton.Height + (Px 30); $leftBtns.BackColor = $C.Panel; $leftBtns.WrapContents = $false
    $leftBtns.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 8), 0, 0)
    [void](New-Button 'New' 'Add a secret (Ctrl+N)' { Touch-Vault; Add-VaultEntry } $leftBtns $Glyph.Add 1)
    [void](New-Button 'Delete' 'Delete the selected secret' { Touch-Vault; Remove-VaultEntry } $leftBtns $Glyph.Delete)
    $VaultUI.Count = New-Object System.Windows.Forms.Label
    $VaultUI.Count.AutoSize = $true; $VaultUI.Count.ForeColor = $C.Dim; $VaultUI.Count.BackColor = $C.Panel; $VaultUI.Count.Font = $FontSmall
    $VaultUI.Count.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 8), 0, 0)
    $leftBtns.Controls.Add($VaultUI.Count)
    $left.Controls.Add($leftBtns)
    $main.Controls.Add($left)

    # top bar: title + lock / change password
    $bar = New-Object System.Windows.Forms.Panel
    $bar.Dock = 'Top'; $bar.Height = $FontTitle.Height + (Px 24); $bar.BackColor = $C.Panel
    $bar.Padding = New-Object System.Windows.Forms.Padding(0, 0, 0, 1)
    $bar.add_Paint({ param($src, $e) $e.Graphics.DrawLine($LinePen, 0, ($src.Height - 1), $src.Width, ($src.Height - 1)) })
    $t = New-Object System.Windows.Forms.Label
    $t.Text = 'Secrets'; $t.Font = $FontTitle; $t.Dock = 'Left'; $t.AutoSize = $false; $t.Width = Px 200; $t.TextAlign = 'MiddleLeft'
    $t.Padding = New-Object System.Windows.Forms.Padding((Px 14), 0, 0, 0); $t.BackColor = $C.Panel; $t.ForeColor = $C.Fore
    $barBtns = New-Object System.Windows.Forms.FlowLayoutPanel
    $barBtns.Dock = 'Right'; $barBtns.AutoSize = $true; $barBtns.WrapContents = $false; $barBtns.BackColor = $C.Panel
    $barBtns.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 8), 0)
    [void](New-Button 'Change master password' 'Choose a new master password' { Touch-Vault; Show-VaultPasswordDialog } $barBtns $Glyph.Settings 2)
    [void](New-Button 'Lock' 'Lock the vault now (Ctrl+L)' { Lock-Vault } $barBtns $Glyph.Lock)
    $bar.Controls.Add($barBtns); $bar.Controls.Add($t)
    $main.Controls.Add($bar)
    $f.Controls.Add($main)

    $f.add_KeyDown({
        param($src, $e)
        Touch-Vault
        if (-not $VaultUI.Key) { return }
        $handled = $true
        if ($e.Control -and $e.KeyCode -eq 'N') { Add-VaultEntry }
        elseif ($e.Control -and $e.KeyCode -eq 'L') { Lock-Vault }
        elseif ($e.Control -and $e.KeyCode -eq 'F') { $VaultUI.Search.Focus(); $VaultUI.Search.SelectAll() }
        elseif ($e.Control -and $e.KeyCode -eq 'C' -and $VaultUI.List.Focused) { Set-SecretClipboard $VaultUI.Fields.Secret.Text }
        elseif ($e.Control -and $e.KeyCode -eq 'B' -and $VaultUI.List.Focused) { Set-SecretClipboard $VaultUI.Fields.User.Text 'Username' }
        else { $handled = $false }
        if ($handled) { $e.Handled = $true; $e.SuppressKeyPress = $true }
    })
    $f.add_Activated({ Touch-Vault })
    $f.add_FormClosing({ Lock-Vault })
    $f.add_FormClosed({ param($src, $e) $VaultUI.SaveTimer.Dispose(); $VaultUI.Form = $null; $src.Dispose() })
    Register-ThemedWindow $f
    if ($VaultUI.Key) { $VaultUI.Lock.Visible = $false; $main.Visible = $true; Update-VaultList -SelectIndex 0 } else { Show-VaultLockScreen }
    Update-VaultStatus
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $f.Activate()
    if (-not $VaultUI.Key) { [void]$VaultUI.Password.Focus() }
}

# ---------------------------------------------------------------------------
# Backup: zips the whole data folder (clips, notes, secrets - still encrypted - API collections, settings).
# Point the backup folder at OneDrive / Dropbox to keep a copy in the cloud. Restore swaps the data back in.
# ---------------------------------------------------------------------------
Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem

function Get-BackupDir {
    if ($script:BackupDir) { return $script:BackupDir }
    Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'DevTools backups'
}

function Invoke-Backup([switch]$Quiet) {
    $dir = Get-BackupDir
    if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
    Save-History; Save-NotesIndex
    if ($NoteUI.Form) { Save-CurrentNote }
    if ($VaultUI.Key) { try { Save-Vault } catch { } }
    $zipPath = Join-Path $dir "DevTools-$(Get-Date -Format 'yyyy-MM-dd_HHmmss').zip"
    $root = (Resolve-Path -LiteralPath $DataDir).Path.TrimEnd('\') + '\'
    $skipped = 0
    $zip = [System.IO.Compression.ZipFile]::Open($zipPath, 'Create')
    try {
        foreach ($file in Get-ChildItem -LiteralPath $DataDir -Recurse -File -Force) {
            if ($file.Name -like '*.tmp' -or $file.Name -like 'debug*') { continue }
            $rel = $file.FullName.Substring($root.Length).Replace('\', '/')
            try {
                $entry = $zip.CreateEntry($rel, 'Optimal')
                $entry.LastWriteTime = $file.LastWriteTime
                $in = [IO.File]::Open($file.FullName, 'Open', 'Read', 'ReadWrite')
                $out = $entry.Open()
                try { $in.CopyTo($out) } finally { $out.Dispose(); $in.Dispose() }
            } catch { $skipped++; Write-Log "backup skipped $rel : $_" }
        }
    } finally { $zip.Dispose() }
    # Keep only the newest backups.
    Get-ChildItem -LiteralPath $dir -Filter 'DevTools-*.zip' | Sort-Object Name -Descending | Select-Object -Skip $script:BackupKeep |
        Remove-Item -Force -ErrorAction SilentlyContinue
    $script:BackupLast = Get-Date
    Save-Settings
    Write-Log "backup: $zipPath (skipped $skipped)"
    if (-not $Quiet) {
        $tray.ShowBalloonTip(3000, 'Backup done', "Saved $(Split-Path -Leaf $zipPath)", 'Info')
    }
    $zipPath
}

function Restore-Backup($Owner) {
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Title = 'Restore a DevTools backup'; $dlg.Filter = 'DevTools backup (*.zip)|*.zip'
    $dir = Get-BackupDir; if (Test-Path -LiteralPath $dir) { $dlg.InitialDirectory = $dir }
    $script:Modal = $true
    try {
        if ($dlg.ShowDialog($Owner) -ne 'OK') { return }
        $zipPath = $dlg.FileName
        $r = [System.Windows.Forms.MessageBox]::Show($Owner,
            "Replace your current clips, notes, secrets and settings with the backup`n$(Split-Path -Leaf $zipPath)?`n`nA backup of the current data is made first. DevTools restarts afterwards.",
            'Restore backup', 'OKCancel', 'Warning')
        if ($r -ne 'OK') { return }
    } finally { $script:Modal = $false; $dlg.Dispose() }
    Restore-BackupFile $zipPath $Owner
}

function Restore-BackupFile([string]$zipPath, $Owner = $null, [switch]$NoRestart) {
    # Check it really is a DevTools backup before touching anything.
    try {
        $z = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        $ok = [bool]($z.Entries | Where-Object { $_.FullName -in 'history.json', 'settings.json' -or $_.FullName -like 'notes/*' })
        $z.Dispose()
    } catch { $ok = $false }
    if (-not $ok) { [void][System.Windows.Forms.MessageBox]::Show($Owner, 'That file is not a DevTools backup.', 'Restore backup'); return }
    [void](Invoke-Backup -Quiet)
    if ($NoteUI.Form) { $NoteUI.Form.Close() }
    if ($VaultUI.Form) { $VaultUI.Form.Close() }
    $script:NoSave = $true
    $root = (Resolve-Path -LiteralPath $DataDir).Path.TrimEnd('\') + '\'
    $z = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
    try {
        foreach ($entry in $z.Entries) {
            if (-not $entry.Name) { continue }
            $dest = [IO.Path]::GetFullPath((Join-Path $DataDir $entry.FullName))
            if (-not $dest.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { continue }      # no paths outside data\
            $parent = Split-Path -Parent $dest
            if (-not (Test-Path -LiteralPath $parent)) { [void](New-Item -ItemType Directory -Path $parent -Force) }
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $dest, $true)
        }
    } finally { $z.Dispose() }
    if (-not $NoRestart) { Restart-App }
}

# Automatic backups: checked every hour, made when the last one is older than the chosen interval.
$BackupTimer = New-Object System.Windows.Forms.Timer
$BackupTimer.Interval = 60000
$BackupTimer.add_Tick({
    $BackupTimer.Interval = 3600000
    if ($script:BackupHours -le 0) { return }
    if (-not $script:BackupLast -or ((Get-Date) - $script:BackupLast).TotalHours -ge $script:BackupHours) {
        try { [void](Invoke-Backup -Quiet) } catch { Write-Log "auto backup failed: $_" }
    }
})
$BackupTimer.Start()

# ---------------------------------------------------------------------------
# Pasting into the app the user came from (palette, snippets, plain-text paste).
# ---------------------------------------------------------------------------
function Send-PasteTo([IntPtr]$Target) {
    if ($Target -eq [IntPtr]::Zero) { return }
    [void][PowerClipHost]::SetForegroundWindow($Target)
    Start-Sleep -Milliseconds 120
    [System.Windows.Forms.SendKeys]::SendWait('^v')
}

# Puts text on the clipboard (without adding it to the history again) and pastes it into $Target.
function Invoke-PasteText([string]$Text, [IntPtr]$Target = [IntPtr]::Zero) {
    if ($null -eq $Text) { return }
    $script:IgnoreUntil = (Get-Date).AddMilliseconds(800)
    try { [System.Windows.Forms.Clipboard]::SetText($(if ($Text) { $Text } else { ' ' }), [System.Windows.Forms.TextDataFormat]::UnicodeText) }
    catch { Write-Log "set clipboard failed: $_"; return }
    Send-PasteTo $Target
}

# Ctrl+Alt+V anywhere: paste what is on the clipboard as plain text (no fonts, colours, links or tables).
function Invoke-PlainPaste {
    $target = [PowerClipHost]::GetForegroundWindow()
    $text = $null
    try { if ([System.Windows.Forms.Clipboard]::ContainsText()) { $text = [System.Windows.Forms.Clipboard]::GetText() } } catch { }
    if ($null -eq $text) { return }
    # Wait until the user lets go of Ctrl / Alt, or the paste would arrive as Ctrl+Alt+V again.
    for ($i = 0; $i -lt 100 -and [PowerClipHost]::AnyModifierDown(); $i++) { Start-Sleep -Milliseconds 20 }
    if ([PowerClipHost]::AnyModifierDown()) { return }
    Invoke-PasteText $text $target
}

# ---------------------------------------------------------------------------
# Snippets: saved text you paste by name. Placeholders are filled in when pasting:
#   {date} {time} {datetime} {date:yyyy-MM-dd HH:mm}  {guid}  {clipboard}  {user} {computer}  {input:Label}
# ---------------------------------------------------------------------------
$SnippetsFile = Join-Path $DataDir 'snippets.json'
$script:Snippets = New-Object System.Collections.Generic.List[object]
$SnipUI = @{ Form = $null; Updating = $false; Current = $null; View = (New-Object System.Collections.Generic.List[object]) }

function Import-Snippets {
    if (-not (Test-Path $SnippetsFile)) {
        foreach ($x in @(
            @('Today''s date', '{date:yyyy-MM-dd}'),
            @('New GUID', '{guid}'),
            @('Email sign-off', "Best regards,`r`n{user}"),
            @('Meeting notes template', "Meeting notes - {date:dddd d MMMM yyyy}`r`n`r`nAttendees:`r`n- `r`n`r`nDecisions:`r`n- `r`n`r`nAction items:`r`n- [ ] "),
            @('Quote the clipboard', '"{clipboard}"'),
            @('Greeting with a name', 'Hi {input:Name},'))) {
            $script:Snippets.Add([pscustomobject]@{ Id = [guid]::NewGuid().ToString('N'); Name = $x[0]; Text = $x[1] })
        }
        Save-Snippets
        return
    }
    try {
        foreach ($x in @(ConvertFrom-JsonList (Read-DataText $SnippetsFile))) {
            if ($x.Id) { $script:Snippets.Add([pscustomobject]@{ Id = [string]$x.Id; Name = [string]$x.Name; Text = [string]$x.Text }) }
        }
    } catch { Write-Log "snippets load failed: $_" }
}

function Save-Snippets {
    if ($script:NoSave) { return }
    $json = ConvertTo-Json -InputObject $script:Snippets.ToArray() -Depth 3
    if (-not $json) { $json = '[]' }
    try { Write-JsonFile $SnippetsFile $json } catch { Write-Log "snippets save failed: $_" }
}

# Returns the snippet text with its placeholders filled in, or $null when the user cancelled an {input:...}.
function Expand-Snippet([string]$Text) {
    $now = Get-Date
    $clip = ''
    try { if ([System.Windows.Forms.Clipboard]::ContainsText()) { $clip = [System.Windows.Forms.Clipboard]::GetText() } } catch { }
    $answers = @{}
    $cancelled = $false
    $result = [regex]::Replace($Text, '\{(date|time|datetime|guid|clipboard|user|computer|input)(?::([^}]*))?\}', {
        param($m)
        $arg = $m.Groups[2].Value
        switch ($m.Groups[1].Value.ToLower()) {
            'date'      { if ($arg) { $now.ToString($arg) } else { $now.ToShortDateString() } }
            'time'      { if ($arg) { $now.ToString($arg) } else { $now.ToShortTimeString() } }
            'datetime'  { if ($arg) { $now.ToString($arg) } else { $now.ToString('g') } }
            'guid'      { [guid]::NewGuid().ToString() }
            'clipboard' { $clip }
            'user'      { $env:USERNAME }
            'computer'  { $env:COMPUTERNAME }
            'input'     {
                $label = if ($arg) { $arg } else { 'Value' }
                if (-not $answers.ContainsKey($label)) {
                    $v = Read-TextDialog 'Snippet' $label '' $null
                    if ($null -eq $v) { $script:SnippetCancelled = $true; $v = '' }
                    $answers[$label] = $v
                }
                $answers[$label]
            }
        }
    }, 'IgnoreCase')
    if ($script:SnippetCancelled) { $script:SnippetCancelled = $false; return $null }
    $result
}

function Invoke-Snippet($Snippet, [IntPtr]$Target = [IntPtr]::Zero) {
    if (-not $Snippet) { return }
    $text = Expand-Snippet $Snippet.Text
    if ($null -eq $text) { return }
    if ($Target -ne [IntPtr]::Zero) { Invoke-PasteText $text $Target }
    else {
        $script:IgnoreUntil = (Get-Date).AddMilliseconds(800)
        try { [System.Windows.Forms.Clipboard]::SetText($text) } catch { }
    }
}

function Update-SnippetList([int]$SelectIndex = -1) {
    if (-not $SnipUI.Form) { return }
    $q = $SnipUI.Search.Text.Trim()
    $SnipUI.View.Clear()
    foreach ($x in ($script:Snippets | Sort-Object Name)) {
        if ($q -and "$($x.Name) $($x.Text)".IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -lt 0) { continue }
        $SnipUI.View.Add($x)
    }
    $l = $SnipUI.List
    $l.BeginUpdate(); $l.Items.Clear()
    for ($i = 0; $i -lt $SnipUI.View.Count; $i++) { [void]$l.Items.Add($i) }
    $l.EndUpdate()
    $idx = -1
    if ($SnipUI.Current) { for ($i = 0; $i -lt $SnipUI.View.Count; $i++) { if ($SnipUI.View[$i].Id -eq $SnipUI.Current.Id) { $idx = $i } } }
    if ($SelectIndex -ge 0 -and $SnipUI.View.Count -gt 0) { $idx = [Math]::Min($SelectIndex, $SnipUI.View.Count - 1) }
    if ($idx -ge 0) { $l.SelectedIndex = $idx } else { Show-SnippetEntry $null }
}

function Show-SnippetEntry($Snippet) {
    $SnipUI.Current = $Snippet
    $SnipUI.Updating = $true
    $SnipUI.Name.Text = if ($Snippet) { $Snippet.Name } else { '' }
    $SnipUI.Text.Text = if ($Snippet) { $Snippet.Text } else { '' }
    $SnipUI.Name.Enabled = [bool]$Snippet; $SnipUI.Text.Enabled = [bool]$Snippet
    $SnipUI.Updating = $false
}

function New-Snippet([string]$Text = '') {
    $x = [pscustomobject]@{ Id = [guid]::NewGuid().ToString('N'); Name = 'New snippet'; Text = $Text }
    $script:Snippets.Add($x)
    Save-Snippets
    Show-Snippets
    $SnipUI.Current = $x
    $SnipUI.Search.Text = ''
    Update-SnippetList
    $SnipUI.Name.Focus(); $SnipUI.Name.SelectAll()
}

function Show-Snippets {
    Hide-Picker
    if ($SnipUI.Form -and -not $SnipUI.Form.IsDisposed) {
        if ($SnipUI.Form.WindowState -eq 'Minimized') { $SnipUI.Form.WindowState = 'Normal' }
        [PowerClipHost]::EnsureShown($SnipUI.Form.Handle); $SnipUI.Form.Activate(); return
    }
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Snippets'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px (900 * $TextZoom)), (Px 580))
    $f.MinimumSize = New-Object System.Drawing.Size((Px 640), (Px 380))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $SnipUI.Form = $f
    $SnipUI.SaveTimer = New-Object System.Windows.Forms.Timer
    $SnipUI.SaveTimer.Interval = 700
    $SnipUI.SaveTimer.add_Tick({ $SnipUI.SaveTimer.Stop(); Save-Snippets })

    $right = New-Object System.Windows.Forms.Panel
    $right.Dock = 'Fill'; $right.BackColor = $C.Bg
    $right.Padding = New-Object System.Windows.Forms.Padding((Px 18), (Px 14), (Px 18), (Px 10))
    $SnipUI.Text = New-Object System.Windows.Forms.TextBox
    $SnipUI.Text.Dock = 'Fill'; $SnipUI.Text.Multiline = $true; $SnipUI.Text.AcceptsReturn = $true; $SnipUI.Text.AcceptsTab = $true
    $SnipUI.Text.ScrollBars = 'Vertical'; $SnipUI.Text.BorderStyle = 'FixedSingle'; $SnipUI.Text.BackColor = $C.Card; $SnipUI.Text.ForeColor = $C.Fore
    $SnipUI.Text.Font = New-Object System.Drawing.Font('Consolas', (Fz 10.5))
    $right.Controls.Add($SnipUI.Text)
    $help = New-Object System.Windows.Forms.Label
    $help.Dock = 'Bottom'; $help.AutoSize = $false; $help.Height = $FontSmall.Height * 5 + (Px 12); $help.Font = $FontSmall; $help.ForeColor = $C.Dim
    $help.Text = "Placeholders, filled in when you paste:  {date}  {time}  {datetime}  {date:yyyy-MM-dd HH:mm}  {guid}  {clipboard}  {user}  {computer}`r`n{input:Name} asks you for a value (the same name is asked once).  Paste a snippet from the command palette (Ctrl+Shift+Space) by typing its name."
    $help.Padding = New-Object System.Windows.Forms.Padding(0, (Px 6), 0, 0)
    $right.Controls.Add($help)
    $nameRow = New-Object System.Windows.Forms.TableLayoutPanel
    $nameRow.Dock = 'Top'; $nameRow.Height = $FontMain.Height + (Px 22); $nameRow.ColumnCount = 2; $nameRow.BackColor = $C.Bg
    [void]$nameRow.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    [void]$nameRow.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $nl = New-Object System.Windows.Forms.Label; $nl.Text = 'Name'; $nl.AutoSize = $true; $nl.ForeColor = $C.Dim; $nl.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), (Px 12), 0)
    $SnipUI.Name = New-Object System.Windows.Forms.TextBox
    $SnipUI.Name.Dock = 'Fill'; $SnipUI.Name.BorderStyle = 'FixedSingle'; $SnipUI.Name.BackColor = $C.Card; $SnipUI.Name.ForeColor = $C.Fore
    $nameRow.Controls.Add($nl, 0, 0); $nameRow.Controls.Add($SnipUI.Name, 1, 0)
    $right.Controls.Add($nameRow)
    $f.Controls.Add($right)
    foreach ($box in $SnipUI.Name, $SnipUI.Text) {
        $box.add_TextChanged({
            if ($SnipUI.Updating -or -not $SnipUI.Current) { return }
            $SnipUI.Current.Name = $SnipUI.Name.Text; $SnipUI.Current.Text = $SnipUI.Text.Text
            $SnipUI.List.Invalidate()
            $SnipUI.SaveTimer.Stop(); $SnipUI.SaveTimer.Start()
        })
    }

    $left = New-Object System.Windows.Forms.Panel
    $left.Dock = 'Left'; $left.Width = Px (280 * $TextZoom); $left.BackColor = $C.Panel
    $list = New-Object System.Windows.Forms.ListBox
    $list.Dock = 'Fill'; $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawFixed'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + $FontSmall.Height + (Px 16); $list.BackColor = $C.Panel; $list.ForeColor = $C.Fore
    $list.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0 -or $e.Index -ge $SnipUI.View.Count) { return }
        $it = $SnipUI.View[$e.Index]
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $b = New-Object System.Drawing.SolidBrush $(if ($sel) { $C.Sel } else { $C.Panel }); $e.Graphics.FillRectangle($b, $e.Bounds); $b.Dispose()
        if ($sel) { $bar = New-Object System.Drawing.SolidBrush $C.Accent; $e.Graphics.FillRectangle($bar, $e.Bounds.X, ($e.Bounds.Y + (Px 6)), (Px 3), ($e.Bounds.Height - (Px 12))); $bar.Dispose() }
        $x = $e.Bounds.X + (Px 14); $w = $e.Bounds.Width - (Px 20)
        $top = New-Object System.Drawing.Rectangle($x, ($e.Bounds.Y + (Px 6)), $w, ($FontMain.Height + (Px 2)))
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $(if ($it.Name) { $it.Name } else { '(no name)' }), $FontMain, $top, $C.Fore, $TextFlags)
        $bot = New-Object System.Drawing.Rectangle($x, $top.Bottom, $w, ($FontSmall.Height + (Px 2)))
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, (Get-Preview $it.Text), $FontSmall, $bot, $C.Dim, $TextFlags)
    })
    $list.add_SelectedIndexChanged({ $i = $SnipUI.List.SelectedIndex; if ($i -ge 0 -and $i -lt $SnipUI.View.Count) { Show-SnippetEntry $SnipUI.View[$i] } })
    $list.add_DoubleClick({ Invoke-Snippet $SnipUI.Current })
    $SnipUI.List = $list
    $left.Controls.Add($list)
    $sw = New-Object System.Windows.Forms.Panel
    $sw.Dock = 'Top'; $sw.Height = $FontMain.Height + (Px 22); $sw.BackColor = $C.Panel
    $sw.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 10), (Px 10), (Px 4))
    $SnipUI.Search = New-Object System.Windows.Forms.TextBox
    $SnipUI.Search.Dock = 'Fill'; $SnipUI.Search.BorderStyle = 'FixedSingle'; $SnipUI.Search.BackColor = $C.Bg; $SnipUI.Search.ForeColor = $C.Fore
    $SnipUI.Search.add_TextChanged({ Update-SnippetList })
    $SnipUI.Search.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Search snippets...') })
    $sw.Controls.Add($SnipUI.Search)
    $left.Controls.Add($sw)
    $lb = New-Object System.Windows.Forms.FlowLayoutPanel
    $lb.Dock = 'Bottom'; $lb.Height = $FontButton.Height + (Px 30); $lb.BackColor = $C.Panel; $lb.WrapContents = $false
    $lb.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 8), 0, 0)
    [void](New-Button 'New' 'New snippet (Ctrl+N)' { New-Snippet } $lb $Glyph.Add 1)
    [void](New-Button 'Copy' 'Copy the snippet, with placeholders filled in' { Invoke-Snippet $SnipUI.Current } $lb $Glyph.Copy)
    [void](New-Button '' 'Delete the snippet' {
        $x = $SnipUI.Current; if (-not $x) { return }
        if ([System.Windows.Forms.MessageBox]::Show($SnipUI.Form, "Delete the snippet `"$($x.Name)`"?", 'Snippets', 'YesNo', 'Question') -ne 'Yes') { return }
        [void]$script:Snippets.Remove($x); Add-Tombstone $x.Id; $SnipUI.Current = $null; Save-Snippets; Update-SnippetList -SelectIndex 0
    } $lb $Glyph.Delete)
    $left.Controls.Add($lb)
    $f.Controls.Add($left)

    $f.add_KeyDown({
        param($src, $e)
        if ($e.Control -and $e.KeyCode -eq 'N') { New-Snippet; $e.SuppressKeyPress = $true }
        elseif ($e.Control -and $e.KeyCode -eq 'F') { $SnipUI.Search.Focus(); $e.SuppressKeyPress = $true }
    })
    $f.add_FormClosing({ $SnipUI.SaveTimer.Stop(); Save-Snippets })
    $f.add_FormClosed({ param($src, $e) $SnipUI.SaveTimer.Dispose(); $SnipUI.Form = $null; $src.Dispose() })
    Register-ThemedWindow $f
    Update-SnippetList -SelectIndex 0
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $f.Activate()
}

Import-Snippets

# ---------------------------------------------------------------------------
# Command palette (Ctrl+Shift+Space anywhere, Ctrl+K in the picker): type to find any tool, action,
# note, snippet, saved API request or recent clip, then Enter.
# Tools add themselves with Register-PaletteCommand.
# ---------------------------------------------------------------------------
$script:PaletteCommands = New-Object System.Collections.Generic.List[object]
$PalUI = @{ Form = $null; Items = $null; View = (New-Object System.Collections.Generic.List[object]); Target = [IntPtr]::Zero }

function Register-PaletteCommand([string]$Title, [string]$Keys, [string]$Icon, [scriptblock]$Action, [string]$Words = '') {
    $script:PaletteCommands.Add([pscustomobject]@{ Kind = 'Command'; Title = $Title; Sub = $Keys; Icon = $Icon; Action = $Action; Words = $Words; Data = $null })
}

