        }
        throw new Exception("The function " + e.Fn + " isn't supported across sources");
    }

    // ---- joining
    List<object[][]> Join(List<object[][]> left, DgFedSource s, int k) {
        var outRows = new List<object[][]>();
        int ns = sources.Count;
        Func<object[][], object[], object[][]> combine = (l, r) => { var x = new object[ns][]; if (l != null) Array.Copy(l, x, ns); x[k] = r; return x; };
        if (s.JoinType == "CROSS") { foreach (var l in left) foreach (var r in s.Rows) { if (cancel) return outRows; outRows.Add(combine(l, r)); } return outRows; }
        // equal-key parts of ON: left side from the tables before, right side from this one -> a hash join
        var leftKeys = new List<DgFedExpr>(); var rightKeys = new List<DgFedExpr>(); var rest = new List<DgFedExpr>();
        foreach (var c in Conjuncts(s.On)) {
            if (c.Op == "bin" && c.Sym == "=") {
                var a = new HashSet<int>(); var b = new HashSet<int>(); Sources(c.Args[0], a); Sources(c.Args[1], b);
                if (a.Count > 0 && b.Count == 1 && b.Contains(k) && !a.Contains(k) && a.All(i => i < k)) { leftKeys.Add(c.Args[0]); rightKeys.Add(c.Args[1]); continue; }
                if (b.Count > 0 && a.Count == 1 && a.Contains(k) && !b.Contains(k) && b.All(i => i < k)) { leftKeys.Add(c.Args[1]); rightKeys.Add(c.Args[0]); continue; }
            }
            rest.Add(c);
        }
        var matchedRight = new bool[s.Rows.Count];
        Func<object[][], bool> restOk = x => rest.All(c => Truth(Eval(c, x, null)));
        if (leftKeys.Count > 0) {
            var map = new Dictionary<string, List<int>>();
            var probe = new object[ns][];
            for (int i = 0; i < s.Rows.Count; i++) {
                probe[k] = s.Rows[i];
                var kk = KeyOf(rightKeys, probe); if (kk == null) continue;
                List<int> l; if (!map.TryGetValue(kk, out l)) { l = new List<int>(); map[kk] = l; } l.Add(i);
            }
            foreach (var l in left) {
                if (cancel) return outRows;
                var kk = KeyOf(leftKeys, l);
                bool any = false; List<int> hits;
                if (kk != null && map.TryGetValue(kk, out hits))
                    foreach (var i in hits) { var x = combine(l, s.Rows[i]); if (rest.Count == 0 || restOk(x)) { outRows.Add(x); matchedRight[i] = true; any = true; } }
                if (!any && (s.JoinType == "LEFT" || s.JoinType == "FULL")) outRows.Add(combine(l, null));
            }
        } else {
            foreach (var l in left) {
                if (cancel) return outRows;
                bool any = false;
                for (int i = 0; i < s.Rows.Count; i++) { var x = combine(l, s.Rows[i]); if (Truth(Eval(s.On, x, null))) { outRows.Add(x); matchedRight[i] = true; any = true; } }
                if (!any && (s.JoinType == "LEFT" || s.JoinType == "FULL")) outRows.Add(combine(l, null));
            }
        }
        if (s.JoinType == "RIGHT" || s.JoinType == "FULL") for (int i = 0; i < s.Rows.Count; i++) if (!matchedRight[i]) outRows.Add(combine(null, s.Rows[i]));
        return outRows;
    }
    string KeyOf(List<DgFedExpr> exprs, object[][] row) {
        var sb = new StringBuilder();
        foreach (var e in exprs) { var k = Key(Eval(e, row, null)); if (k == null) return null; sb.Append(k).Append('\u0001'); }
        return sb.ToString();
    }

    // ---- the whole run
    void Run(Dictionary<string, string> connMap, int maxPerSource, int maxRows) {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        conns = connMap;
        try {
            try { Parse(); }
            catch (FedError fe) { int line = 1; for (int i = 0; i < Math.Min(fe.Pos, sql.Length); i++) if (sql[i] == '\n') line++; Result.ErrorLine = line; Result.Error = fe.Message + "  (line " + line + ")"; return; }
            var dup = sources.GroupBy(s => s.Alias, StringComparer.OrdinalIgnoreCase).FirstOrDefault(g => g.Count() > 1);
            if (dup != null) throw new Exception("Two tables are called " + dup.Key + ": give them different aliases.");
            // which rows can be missing (outer joins): their WHERE parts must not be done by the database
            for (int i = 1; i < sources.Count; i++) {
                var jt = sources[i].JoinType;
                if (jt == "LEFT" || jt == "FULL") sources[i].Nullable = true;
                if (jt == "RIGHT" || jt == "FULL") for (int j = 0; j < i; j++) sources[j].Nullable = true;
            }
            // 1. the columns of every source (in parallel)
            Parallel(sources.Select(s => (Action)(() => Describe(s))).ToList(), "Reading the columns");
            if (cancel) { Result.Cancelled = true; return; }
            // 2. what each name means, which columns each source sends, which WHERE parts it does itself
            bool star = select.Any(e => e.Op == "star" && e.Table.Length == 0);
            if (star) foreach (var s in sources) s.All = true;
            foreach (var e in select) Bind(e);
            foreach (var s in sources) Bind(s.On);
            Bind(where); foreach (var g in groupBy) Bind(g); Bind(having);
            for (int i = 0; i < orderBy.Count; i++) {
                var o = orderBy[i];
                bool alias = o.Op == "col" && o.Table.Length == 0 && selNames.Any(n => string.Equals(n, o.Name, StringComparison.OrdinalIgnoreCase)) && !sources.Any(s => Find(s.Cols, o.Name) >= 0);
                if (!(o.Op == "lit" && o.Value is long) && !alias) Bind(o);
            }
            foreach (var c in Conjuncts(where)) {
                var used = new HashSet<int>(); Sources(c, used);
                if (used.Count == 1 && Pushable(c)) { var s = sources[used.First()]; if (!s.Nullable && !s.IsFile) s.Push.Add(c); }
            }
            // 3. the rows (in parallel)
            Parallel(sources.Select(s => (Action)(() => Fetch(s, maxPerSource))).ToList(), "Reading the rows");
            if (cancel) { Result.Cancelled = true; return; }
            foreach (var s in sources) {
                lock (Result.Messages) Result.Messages.Add(s.Alias + "  (" + s.Label + "): " + s.Rows.Count + " row" + (s.Rows.Count == 1 ? "" : "s") + " in " + s.Ms + " ms" + (s.Truncated ? "  -  CUT at " + maxPerSource + " rows, the result may miss rows" : "") + (s.Sql.Length > 0 ? "\n    " + s.Sql : ""));
                if (s.Truncated) Result.Truncated = true;
            }
            // column positions in the fetched rows
            Action<DgFedExpr> place = null;
            place = e => { if (e == null) return; if (e.Op == "col" && e.Src >= 0) { e.Col = Find(sources[e.Src].Names, e.Name); if (e.Col < 0) throw new Exception("Column " + e.Name + " didn't come back from " + sources[e.Src].Label); } foreach (var a in e.Args) place(a); if (e.Op == "case" && e.Value is DgFedExpr) place((DgFedExpr)e.Value); };
            foreach (var e in select) place(e); foreach (var s in sources) place(s.On); place(where); foreach (var g in groupBy) place(g); place(having); foreach (var o in orderBy) place(o);
            // 4. join, filter
            var rows = sources[0].Rows.Select(r => { var x = new object[sources.Count][]; x[0] = r; return x; }).ToList();
            for (int k = 1; k < sources.Count; k++) { rows = Join(rows, sources[k], k); if (cancel) { Result.Cancelled = true; return; } }
            if (where != null) rows = rows.Where(r => Truth(Eval(where, r, null))).ToList();
            // 5. columns of the result
            var outCols = new List<string>(); var outExpr = new List<DgFedExpr>();
            for (int i = 0; i < select.Count; i++) {
                var e = select[i];
                if (e.Op == "star") {
                    foreach (int si in e.Table.Length == 0 ? Enumerable.Range(0, sources.Count) : new[] { e.Src })
                        for (int c = 0; c < sources[si].Names.Count; c++) { outCols.Add(sources[si].Names[c]); outExpr.Add(new DgFedExpr("col") { Src = si, Col = c, Name = sources[si].Names[c] }); }
                } else { outCols.Add(selNames[i]); outExpr.Add(e); }
            }
            bool grouped = groupBy.Count > 0 || select.Any(HasAgg) || HasAgg(having);
            var result = new List<object[]>(); var keys = new List<object[]>();
            Func<object[][], List<object[][]>, object[], object[]> orderVals = (r, g, outRow) => orderBy.Select((o, i) => {
                if (o.Op == "lit" && o.Value is long) { int n = (int)(long)o.Value - 1; return n >= 0 && n < outRow.Length ? outRow[n] : null; }
                if (o.Op == "col" && o.Src < 0) { int n = outCols.FindIndex(c => string.Equals(c, o.Name, StringComparison.OrdinalIgnoreCase)); return n >= 0 ? outRow[n] : null; }
                return Eval(o, r, g);
            }).ToArray();
            if (grouped) {
                var groups = new Dictionary<string, List<object[][]>>(); var order = new List<string>();
                foreach (var r in rows) {
                    var sb = new StringBuilder(); foreach (var g in groupBy) sb.Append(Key(Eval(g, r, null)) ?? "\u0002").Append('\u0001');
                    var k = sb.ToString(); List<object[][]> l; if (!groups.TryGetValue(k, out l)) { l = new List<object[][]>(); groups[k] = l; order.Add(k); } l.Add(r);
                }
                if (groupBy.Count == 0 && order.Count == 0) { groups[""] = new List<object[][]>(); order.Add(""); }
                foreach (var k in order) {
                    var g = groups[k]; var first = g.Count > 0 ? g[0] : new object[sources.Count][];
                    if (having != null && !Truth(Eval(having, first, g))) continue;
                    var o = outExpr.Select(e => Eval(e, first, g)).ToArray();
                    result.Add(o); keys.Add(orderVals(first, g, o));
                }
            } else foreach (var r in rows) { var o = outExpr.Select(e => Eval(e, r, null)).ToArray(); result.Add(o); keys.Add(orderVals(r, null, o)); }
            // 6. DISTINCT, ORDER BY, OFFSET / TOP
            var idx = Enumerable.Range(0, result.Count).ToList();
            if (distinct) { var seen = new HashSet<string>(); idx = idx.Where(i => seen.Add(string.Join("\u0001", result[i].Select(v => Key(v) ?? "\u0002")))).ToList(); }
            if (orderBy.Count > 0) {
                idx.Sort((a, b) => {
                    for (int j = 0; j < orderBy.Count; j++) {
                        object x = keys[a][j], y = keys[b][j]; int c;
                        if (x == null && y == null) c = 0; else if (x == null) c = -1; else if (y == null) c = 1; else c = Compare(x, y) ?? 0;
                        if (c != 0) return orderDesc[j] ? -c : c;
                    }
                    return a.CompareTo(b);
                });
            }
            idx = idx.Skip((int)Math.Min(int.MaxValue, offset)).ToList();
            if (top >= 0) idx = idx.Take((int)Math.Min(int.MaxValue, top)).ToList();
            var tb = new System.Data.DataTable("Result 1");
            var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var n0 in outCols) { string n = string.IsNullOrEmpty(n0) ? "(no name)" : n0; string u = n; int k = 2; while (names.Contains(u)) u = n + " (" + k++ + ")"; names.Add(u); tb.Columns.Add(u, typeof(object)); }
            tb.BeginLoadData();
            foreach (var i in idx) {
                if (maxRows > 0 && tb.Rows.Count >= maxRows) { Result.Truncated = true; break; }
                tb.LoadDataRow(result[i].Select(v => DgSqlRun.Show(v)).ToArray(), true);
            }
            tb.EndLoadData();
            Result.Tables.Add(tb);
            lock (Result.Messages) Result.Messages.Add("Joined here: " + rows.Count + " row" + (rows.Count == 1 ? "" : "s") + " after the joins and WHERE, " + tb.Rows.Count + " in the result.");
        } catch (Exception ex) {
            if (cancel) Result.Cancelled = true;
            else Result.Error = DgDb.ErrorText(ex is AggregateException && ex.InnerException != null ? ex.InnerException : ex);
        } finally { Result.Ms = sw.ElapsedMilliseconds; Done = true; }
    }

    // runs the steps at the same time; the first error (with the source it came from) stops the query
    void Parallel(List<Action> steps, string what) {
        var errors = new List<Exception>();
        var threads = steps.Select((a, i) => new System.Threading.Thread(() => { try { a(); } catch (Exception ex) { lock (errors) errors.Add(new Exception(sources[i].Alias + " (" + sources[i].Label + "): " + DgDb.ErrorText(ex), ex)); } }) { IsBackground = true }).ToList();
        foreach (var th in threads) th.Start();
        foreach (var th in threads) th.Join();
        if (errors.Count > 0 && !cancel) throw errors[0];
    }
}

// ---- Importing diagrams: DevTools' own exports (they carry the diagram text), draw.io / diagrams.net and Graphviz DOT.
public class DgImported { public string Name = "", Text = ""; }

public static class DgImport {
    // ---- the diagram text inside an export: "devtools-diagram:<base64 of the text>:end" in a comment / PNG text chunk
    public static string Marker(string text) { return "devtools-diagram:" + Convert.ToBase64String(Encoding.UTF8.GetBytes(text ?? "")) + ":end"; }
    public static string FindSource(string content) {
        var m = Regex.Match(content ?? "", @"devtools-diagram:([A-Za-z0-9+/=]+):end");
        if (!m.Success) return null;
        try { return Encoding.UTF8.GetString(Convert.FromBase64String(m.Groups[1].Value)); } catch { return null; }
    }

    // ---- exports in plain ASCII, so they show the same in any page, whatever its encoding: characters beyond ASCII
    //      become &#x2013; in markup (SVG, HTML, JSX), \u2013 inside <script> and \2013 inside <style>
    public static string AsciiSafe(string code) {
        if (code == null) return "";
        bool any = false; foreach (char ch in code) if (ch > 127) { any = true; break; }
        if (!any) return code;
        var sb = new StringBuilder(code.Length + 64);
        string mode = "";                                                  // "", "script", "style"
        int i = 0, n = code.Length;
        while (i < n) {
            char c = code[i];
            if (c == '<') {
                if (mode == "" && At(code, i, "<script")) mode = "script";
                else if (mode == "" && At(code, i, "<style")) mode = "style";
                else if (mode == "script" && At(code, i, "</script")) mode = "";
                else if (mode == "style" && At(code, i, "</style")) mode = "";
            }
            if (c <= 127) { sb.Append(c); i++; continue; }
            int cp = c;
            if (char.IsHighSurrogate(c) && i + 1 < n && char.IsLowSurrogate(code[i + 1])) cp = char.ConvertToUtf32(c, code[i + 1]);
            if (mode == "script") { sb.Append("\\u").Append(((int)c).ToString("x4")); if (cp > 0xFFFF) sb.Append("\\u").Append(((int)code[i + 1]).ToString("x4")); }
            else if (mode == "style") sb.Append("\\").Append(cp.ToString("x")).Append(' ');
            else sb.Append("&#x").Append(cp.ToString("X")).Append(';');
            i += cp > 0xFFFF ? 2 : 1;
        }
        return sb.ToString();
    }
    static bool At(string s, int i, string w) { return string.Compare(s, i, w, 0, w.Length, StringComparison.OrdinalIgnoreCase) == 0; }

    // ---- PNG text chunks (tEXt / zTXt / iTXt): DevTools puts its text in one, draw.io its diagram ("mxfile")
    static uint Crc(byte[] b, int off, int len) {
        uint c = 0xFFFFFFFF;
        for (int i = off; i < off + len; i++) { c ^= b[i]; for (int k = 0; k < 8; k++) c = (c & 1) != 0 ? 0xEDB88320 ^ (c >> 1) : c >> 1; }
        return c ^ 0xFFFFFFFF;
    }
    static uint BE(byte[] b, int i) { return (uint)(b[i] << 24 | b[i + 1] << 16 | b[i + 2] << 8 | b[i + 3]); }
    public static void PngAddText(string path, string key, string value) {
        var b = System.IO.File.ReadAllBytes(path);
        if (b.Length < 12 || b[1] != 'P' || b[2] != 'N' || b[3] != 'G') return;
        int i = 8, iend = -1;
        while (i + 8 <= b.Length) { uint len = BE(b, i); string type = Encoding.ASCII.GetString(b, i + 4, 4); if (type == "IEND") { iend = i; break; } i += 12 + (int)len; }
        if (iend < 0) return;
        var data = Encoding.ASCII.GetBytes(key + "\0" + value);
        var chunk = new byte[12 + data.Length];
        chunk[0] = (byte)(data.Length >> 24); chunk[1] = (byte)(data.Length >> 16); chunk[2] = (byte)(data.Length >> 8); chunk[3] = (byte)data.Length;
        Encoding.ASCII.GetBytes("tEXt").CopyTo(chunk, 4); data.CopyTo(chunk, 8);
        uint crc = Crc(chunk, 4, 4 + data.Length);
        chunk[8 + data.Length] = (byte)(crc >> 24); chunk[9 + data.Length] = (byte)(crc >> 16); chunk[10 + data.Length] = (byte)(crc >> 8); chunk[11 + data.Length] = (byte)crc;
        var outB = new byte[b.Length + chunk.Length];
        Array.Copy(b, 0, outB, 0, iend); chunk.CopyTo(outB, iend); Array.Copy(b, iend, outB, iend + chunk.Length, b.Length - iend);
        System.IO.File.WriteAllBytes(path, outB);
    }
    public static string PngText(string path, string key) {
        var b = System.IO.File.ReadAllBytes(path);
        if (b.Length < 12 || b[1] != 'P' || b[2] != 'N' || b[3] != 'G') return null;
        int i = 8;
        while (i + 12 <= b.Length) {
            int len = (int)BE(b, i); string type = Encoding.ASCII.GetString(b, i + 4, 4);
            if (len < 0 || i + 12 + len > b.Length) break;
            if (type == "tEXt" || type == "zTXt" || type == "iTXt") {
                int z = Array.IndexOf(b, (byte)0, i + 8, len);
                if (z > 0 && Encoding.ASCII.GetString(b, i + 8, z - i - 8) == key) {
                    int start = z + 1, end = i + 8 + len;
                    if (type == "tEXt") return Encoding.GetEncoding(28591).GetString(b, start, end - start);
                    if (type == "zTXt") return Inflate(b, start + 1 + 2, end - start - 1 - 2, 28591);
                    // iTXt: compression flag, method, language\0, translated keyword\0, text
                    bool comp = b[start] == 1; int p = start + 2;
                    p = Array.IndexOf(b, (byte)0, p, end - p) + 1; p = Array.IndexOf(b, (byte)0, p, end - p) + 1;
                    return comp ? Inflate(b, p + 2, end - p - 2, 65001) : Encoding.UTF8.GetString(b, p, end - p);
                }
            }
            if (type == "IEND") break;
            i += 12 + len;
        }
        return null;
    }
    static string Inflate(byte[] b, int off, int len, int codePage) {
        using (var ms = new System.IO.MemoryStream(b, off, len))
        using (var ds = new System.IO.Compression.DeflateStream(ms, System.IO.Compression.CompressionMode.Decompress))
        using (var outS = new System.IO.MemoryStream()) { ds.CopyTo(outS); return Encoding.GetEncoding(codePage).GetString(outS.ToArray()); }
    }

    // ---- draw.io / diagrams.net: .drawio, its uncompressed or compressed pages, an SVG or PNG with the diagram inside
    public static bool IsDrawio(string content) { return content != null && (content.Contains("<mxfile") || content.Contains("<mxGraphModel") || content.Contains("&lt;mxfile") || content.Contains("&lt;mxGraphModel")); }
    public static List<DgImported> FromDrawio(string content) {
        var r = new List<DgImported>();
        content = content ?? "";
        // an SVG export holds the file in content="..."; a PNG export (already read) holds it URL-encoded
        var cm = Regex.Match(content, @"\scontent=""([^""]*)""");
        if (!content.TrimStart().StartsWith("<mxfile") && cm.Success && System.Net.WebUtility.HtmlDecode(cm.Groups[1].Value).Contains("<mx")) content = System.Net.WebUtility.HtmlDecode(cm.Groups[1].Value);
        if (content.TrimStart().StartsWith("%3C")) content = Uri.UnescapeDataString(content);
        var x = System.Xml.Linq.XDocument.Parse(content.Trim());
        var root = x.Root;
        if (root.Name.LocalName == "mxGraphModel") { r.Add(new DgImported { Name = "", Text = Drawio(root, "") }); return r; }
        foreach (var dia in root.Elements().Where(e => e.Name.LocalName == "diagram")) {
            string name = (string)dia.Attribute("name") ?? "";
            var model = dia.Elements().FirstOrDefault(e => e.Name.LocalName == "mxGraphModel");
            if (model == null) {
                string raw = dia.Value.Trim();
                if (raw.Length == 0) continue;
                string xml;
                if (raw.StartsWith("<")) xml = raw;
                else {
                    var bytes = Convert.FromBase64String(raw);
                    using (var ms = new System.IO.MemoryStream(bytes)) using (var ds = new System.IO.Compression.DeflateStream(ms, System.IO.Compression.CompressionMode.Decompress)) using (var sr = new System.IO.StreamReader(ds, Encoding.UTF8)) xml = sr.ReadToEnd();
                    xml = Uri.UnescapeDataString(xml);
                }
                model = System.Xml.Linq.XElement.Parse(xml);
            }
            r.Add(new DgImported { Name = name, Text = Drawio(model, name) });
        }
        return r;
    }
    static Dictionary<string, string> Style(string s) {
        var d = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in (s ?? "").Split(';')) {
            if (p.Trim().Length == 0) continue;
            int e = p.IndexOf('=');
            if (e < 0) { if (!d.ContainsKey("_kind")) d["_kind"] = p.Trim(); d[p.Trim()] = "1"; } else d[p.Substring(0, e).Trim()] = p.Substring(e + 1).Trim();
        }
        return d;
    }
    // a draw.io label (HTML) as plain lines
    static List<string> LabelLines(string v) {
        v = v ?? "";
        v = Regex.Replace(v, @"<\s*br\s*/?\s*>|</\s*(div|p|li|tr|h\d)\s*>", "\n", RegexOptions.IgnoreCase);
        v = Regex.Replace(v, @"<[^>]+>", "");
        v = System.Net.WebUtility.HtmlDecode(v).Replace('\u00A0', ' ');
        return v.Split('\n').Select(t => Regex.Replace(t, @"\s+", " ").Trim()).Where(t => t.Length > 0).ToList();
    }
    static string Hex(string c) { if (string.IsNullOrEmpty(c) || c == "none" || c == "default") return ""; return Regex.IsMatch(c, @"^#[0-9a-fA-F]{3,8}$") ? c : ""; }
    static string Q(string s) { return "\"" + (s ?? "").Replace("\"", "'") + "\""; }
    // a label as a node line takes it: quoted, without brackets or arrows that would make the line a link
    static string Lbl(string s) { s = (s ?? "").Replace("[", "(").Replace("]", ")").Replace("->", "\u2192").Replace("<-", "\u2190").Replace("--", "\u2013").Replace("==", "= ="); return s.Trim().Length == 0 ? "\" \"" : Q(s); }
    static string F(double v) { return Math.Round(v).ToString(CultureInfo.InvariantCulture); }
    class Cell { public string Id = "", Parent = "", Value = "", Src = "", Dst = ""; public Dictionary<string, string> St; public bool Vertex, Edge; public double X, Y, W, H, AX, AY; public bool Placed; }

    static string Drawio(System.Xml.Linq.XElement model, string name) {
        var cells = new Dictionary<string, Cell>();
        var order = new List<Cell>();
        var rootEl = model.Elements().FirstOrDefault(e => e.Name.LocalName == "root") ?? model;
        foreach (var el in rootEl.Elements()) {
            // a cell, or an <object> / <UserObject> wrapping one (its label is in the label attribute)
            var cellEl = el.Name.LocalName == "mxCell" ? el : el.Elements().FirstOrDefault(e => e.Name.LocalName == "mxCell");
            if (cellEl == null) continue;
            var c = new Cell { Id = (string)el.Attribute("id") ?? (string)cellEl.Attribute("id") ?? "", Parent = (string)cellEl.Attribute("parent") ?? "",
                               Value = (string)el.Attribute("label") ?? (string)cellEl.Attribute("value") ?? "", St = Style((string)cellEl.Attribute("style")),
                               Vertex = (string)cellEl.Attribute("vertex") == "1", Edge = (string)cellEl.Attribute("edge") == "1", Src = (string)cellEl.Attribute("source") ?? "", Dst = (string)cellEl.Attribute("target") ?? "" };
            var g = cellEl.Elements().FirstOrDefault(e => e.Name.LocalName == "mxGeometry");
            Func<string, double> num = a => { double v; return g != null && double.TryParse((string)g.Attribute(a), NumberStyles.Float, CultureInfo.InvariantCulture, out v) ? v : 0; };
            c.X = num("x"); c.Y = num("y"); c.W = num("width"); c.H = num("height");
            if (c.Id.Length == 0) continue;
            cells[c.Id] = c; order.Add(c);
        }
        // absolute positions (a shape inside a container is placed relative to it)
        Func<Cell, int, bool> place = null;
        place = (c, depth) => {
            if (c.Placed || depth > 50) return true;
            Cell p; if (cells.TryGetValue(c.Parent, out p) && p.Vertex) { place(p, depth + 1); c.AX = p.AX + c.X; c.AY = p.AY + c.Y; } else { c.AX = c.X; c.AY = c.Y; }
            c.Placed = true; return true;
        };
        foreach (var c in order) { Cell pe; if (c.Vertex && cells.TryGetValue(c.Parent, out pe) && pe.Edge) c.Vertex = false; }      // a link's label
        foreach (var c in order) if (c.Vertex) place(c, 0);
        Func<Cell, bool> isGroup = c => c.St.ContainsKey("swimlane") || c.St.ContainsKey("group") || (c.St.ContainsKey("container") && c.St["container"] == "1") || c.St.ContainsKey("shape") && c.St["shape"].StartsWith("mxgraph.") && c.St["shape"].Contains("group");
        var ids = new Dictionary<string, string>();
        int n = 0, gN = 0;
        foreach (var c in order) if (c.Vertex) ids[c.Id] = isGroup(c) ? "g" + (++gN) : "n" + (++n);
        var sb = new StringBuilder();
        sb.Append("title " + (name.Length > 0 ? name : "Imported from draw.io") + "\r\ntheme corporate light\r\nhide legend, header\r\n");
        bool ortho = order.Any(c => c.Edge && c.St.ContainsKey("edgeStyle") && c.St["edgeStyle"].ToLowerInvariant().Contains("orthogonal"));
        sb.Append("route " + (ortho ? "ortho" : "straight") + "\r\n\r\n");
        Func<Cell, string> groupOf = null;
        groupOf = c => { Cell p; int guard = 0; var cur = c; while (guard++ < 50 && cells.TryGetValue(cur.Parent, out p)) { if (p.Vertex && isGroup(p)) return ids[p.Id]; cur = p; } return ""; };
        // groups first
        foreach (var c in order.Where(c => c.Vertex && isGroup(c))) {
            var title = LabelLines(c.Value);
            var members = order.Where(m => m.Vertex && !isGroup(m) && groupOf(m) == ids[c.Id]).Select(m => ids[m.Id]).ToList();
            if (members.Count == 0) continue;
            sb.Append("group " + ids[c.Id] + " " + Q(title.Count > 0 ? title[0] : "Group") + " [" + (c.St.ContainsKey("dashed") && c.St["dashed"] == "1" ? "dashed" : "solid") + (Hex(Get(c.St, "fillColor")).Length > 0 ? ", fill " + Hex(Get(c.St, "fillColor")) : "") + "] { " + string.Join(", ", members) + " }\r\n");
        }
        int skipped = 0;
        foreach (var c in order.Where(c => c.Vertex && !isGroup(c))) {
            var lines = LabelLines(c.Value);
            string kind = Get(c.St, "_kind").ToLowerInvariant(), shp = Get(c.St, "shape").ToLowerInvariant();
            string shape;
            if (kind == "text" || kind == "edgelabel") shape = "text";
            else if (kind == "ellipse" || shp == "ellipse" || kind.Contains("ellipse")) shape = Math.Abs(c.W - c.H) < 4 ? "circle" : "pill";
            else if (kind == "rhombus" || shp == "rhombus") shape = "diamond";
            else if (shp.Contains("cylinder") || shp.Contains("datastore") || shp == "database" || kind.Contains("cylinder")) shape = "cylinder";
            else if (shp == "hexagon" || kind == "hexagon") shape = "hexagon";
            else if (shp == "parallelogram" || kind == "parallelogram") shape = "parallelogram";
            else if (shp == "document" || kind == "document") shape = "doc";
            else if (shp == "note" || kind == "note") shape = "note";
            else if (shp.Contains("actor") || kind.Contains("actor")) shape = "actor";
            else if (Get(c.St, "rounded") == "1") shape = Get(c.St, "arcSize").Length > 0 && Get(c.St, "arcSize") == "50" ? "pill" : "rounded";
            else shape = "rect";
            if (kind == "image" || shp == "image") shape = "rect";
            var attrs = new List<string> { "shape " + shape, "at " + F(c.AX) + " " + F(c.AY), "w " + F(c.W), "h " + F(c.H) };
            string fill = Hex(Get(c.St, "fillColor")), stroke = Hex(Get(c.St, "strokeColor")), fc = Hex(Get(c.St, "fontColor"));
            if (fill.Length > 0) attrs.Add("fill " + fill);
            if (stroke.Length > 0) attrs.Add("stroke " + stroke);
            if (fc.Length > 0) attrs.Add("color " + fc);
            if (Get(c.St, "dashed") == "1") attrs.Add("dashed");
            if (Get(c.St, "fontStyle") == "1") attrs.Add("bold");
            if (lines.Count > 1) attrs.Add("lines " + string.Join(" ", lines.Skip(1).Take(8).Select(Q)));
            string label = lines.Count > 0 ? lines[0] : "";
            sb.Append(ids[c.Id] + ": " + Lbl(label) + " [" + string.Join(", ", attrs) + "]\r\n");
        }
        sb.Append("\r\n");
        foreach (var c in order.Where(c => c.Edge)) {
            string a, b;
            if (!ids.TryGetValue(c.Src, out a) || !ids.TryGetValue(c.Dst, out b) || a.StartsWith("g") || b.StartsWith("g")) { skipped++; continue; }
            var attrs = new List<string>();
            var lines = LabelLines(c.Value);
            // edge labels can also be child cells of the edge
            if (lines.Count == 0) { var lc = order.FirstOrDefault(k => k.Parent == c.Id && LabelLines(k.Value).Count > 0); if (lc != null) lines = LabelLines(lc.Value); }
            if (lines.Count > 0) attrs.Add("label " + Q(string.Join(" ", lines)));
            if (Get(c.St, "dashed") == "1") attrs.Add(Get(c.St, "dashPattern").Length > 0 && Get(c.St, "dashPattern").StartsWith("1 ") ? "dotted" : "dashed");
            bool end = Get(c.St, "endArrow") != "none", start = Get(c.St, "startArrow").Length > 0 && Get(c.St, "startArrow") != "none";
            if (!end || start) attrs.Add("arrow " + (end && start ? "both" : start ? "start" : "none"));
            string sc = Hex(Get(c.St, "strokeColor")); if (sc.Length > 0) attrs.Add("color " + sc);
            sb.Append(a + " -> " + b + (attrs.Count > 0 ? " [" + string.Join(", ", attrs) + "]" : "") + "\r\n");
        }
        if (skipped > 0) sb.Append("% " + skipped + " link(s) to a container or to nothing were left out\r\n");
        return sb.ToString();
    }
    static string Get(Dictionary<string, string> d, string k) { string v; return d.TryGetValue(k, out v) ? v : ""; }

    // ---- Graphviz DOT
    class DTok { public string T; public bool Id; }
    static List<DTok> DotLex(string s) {
        var r = new List<DTok>(); int i = 0, n = s.Length;
        while (i < n) {
            char c = s[i];
            if (char.IsWhiteSpace(c)) { i++; continue; }
            if (c == '/' && i + 1 < n && s[i + 1] == '/') { while (i < n && s[i] != '\n') i++; continue; }
            if (c == '#' && (i == 0 || s[i - 1] == '\n')) { while (i < n && s[i] != '\n') i++; continue; }
            if (c == '/' && i + 1 < n && s[i + 1] == '*') { int e = s.IndexOf("*/", i + 2); i = e < 0 ? n : e + 2; continue; }
            if (c == '"') { var sb = new StringBuilder(); i++; while (i < n && s[i] != '"') { if (s[i] == '\\' && i + 1 < n) { char nx = s[i + 1]; if (nx == 'n' || nx == 'l' || nx == 'r') sb.Append('\n'); else sb.Append(nx); i += 2; continue; } sb.Append(s[i]); i++; } i++;
                // "a" + "b" concatenation
                r.Add(new DTok { T = sb.ToString(), Id = true }); continue; }
            if (c == '<') { int d = 0, st = i; while (i < n) { if (s[i] == '<') d++; else if (s[i] == '>') { d--; if (d == 0) { i++; break; } } i++; } r.Add(new DTok { T = Regex.Replace(Regex.Replace(s.Substring(st + 1, Math.Max(0, i - st - 2)), @"<\s*br\s*/?\s*>", "\n", RegexOptions.IgnoreCase), @"<[^>]+>", ""), Id = true }); continue; }
            if (c == '-' && i + 1 < n && (s[i + 1] == '>' || s[i + 1] == '-')) { r.Add(new DTok { T = s.Substring(i, 2) }); i += 2; continue; }
            if (char.IsLetterOrDigit(c) || c == '_' || c == '.' || c == '-' || c > 127) { int st = i; while (i < n && (char.IsLetterOrDigit(s[i]) || s[i] == '_' || s[i] == '.' || s[i] > 127 || (s[i] == '-' && !(i + 1 < n && (s[i + 1] == '>' || s[i + 1] == '-'))))) i++; r.Add(new DTok { T = s.Substring(st, i - st), Id = true }); continue; }
            r.Add(new DTok { T = c.ToString() }); i++;
        }
        return r;
    }
    class DNode { public string Id = "", Key = ""; public Dictionary<string, string> A = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); public string Group = ""; }
    public static string FromDot(string dot) {
        var t = DotLex(dot ?? "");
        int p = 0;
        Func<string, bool> isT = s => p < t.Count && !t[p].Id && t[p].T == s;
        var nodes = new Dictionary<string, DNode>(); var order = new List<DNode>();
        var edges = new List<KeyValuePair<string[], Dictionary<string, string>>>();
        var groups = new List<string[]>();     // id, title
        var graphA = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        bool directed = true;
        if (p < t.Count && t[p].Id && t[p].T.ToLowerInvariant() == "strict") p++;
        if (p < t.Count && t[p].Id) { directed = t[p].T.ToLowerInvariant() == "digraph"; p++; }
        if (p < t.Count && t[p].Id) p++;                                       // the graph's name
        if (isT("{")) p++;
        Func<Dictionary<string, string>> attrList = () => {
            var a = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            while (isT("[")) {
                p++;
                while (p < t.Count && !isT("]")) {
                    if (isT(",") || isT(";")) { p++; continue; }
                    string k = t[p].T; p++;
                    if (isT("=")) { p++; if (p < t.Count) { a[k] = t[p].T; p++; } } else a[k] = "true";
                }
                p++;
            }
            return a;
        };
        int gCount = 0;
        Func<Dictionary<string, string>, string, DNode> node = null;
        List<string> collect = null;                      // the nodes named inside the { ... } being read
        Action<string, Dictionary<string, string>, Dictionary<string, string>> stmts = null;
        node = (a, key) => {
            DNode d;
            if (!nodes.TryGetValue(key, out d)) { d = new DNode { Key = key, Id = "n" + (nodes.Count + 1) }; nodes[key] = d; order.Add(d); foreach (var kv in a) d.A[kv.Key] = kv.Value; }
            return d;
        };
        // a statement list; group = the cluster being read; nodeDefaults = node [..] in force
        stmts = (group, nodeDef, edgeDef) => {
            while (p < t.Count && !isT("}")) {
                if (isT(";") || isT(",")) { p++; continue; }
                // the endpoints of a statement: a node, or { ... } / subgraph x { ... }
                Func<List<string>> endpoint = null;
                endpoint = () => {
                    var keys = new List<string>();
                    if (p < t.Count && t[p].Id && t[p].T.ToLowerInvariant() == "subgraph" || isT("{")) {
                        string gid = "";
                        if (t[p].Id && t[p].T.ToLowerInvariant() == "subgraph") { p++; if (p < t.Count && t[p].Id) { gid = t[p].T; p++; } }
                        if (!isT("{")) return keys;
                        p++;
                        var saved = collect; collect = new List<string>();
                        bool cluster = gid.StartsWith("cluster", StringComparison.OrdinalIgnoreCase);
                        string gname = cluster ? "g" + (++gCount) : group;
                        int gi = groups.Count;
                        if (cluster) groups.Add(new[] { gname, gid.Substring(7).Trim('_', ' ') });
                        var nd = new Dictionary<string, string>(nodeDef, StringComparer.OrdinalIgnoreCase);
                        // the cluster's label is a statement inside it
                        stmts(gname, nd, edgeDef);
                        if (isT("}")) p++;
                        foreach (var k0 in collect.Distinct()) keys.Add(k0);
                        if (saved != null) saved.AddRange(collect);
                        collect = saved;
                        if (cluster && graphLabel.ContainsKey(gname)) groups[gi][1] = graphLabel[gname];
                        return keys;
                    }
                    if (p < t.Count && t[p].Id) {
                        string k = t[p].T; p++;
                        if (isT(":")) { p++; if (p < t.Count && t[p].Id) p++; if (isT(":")) { p++; p++; } }      // ports
                        var d = node(nodeDef, k);
                        if (group.Length > 0 && d.Group.Length == 0) d.Group = group;
                        if (collect != null) collect.Add(k);
                        keys.Add(k);
                    } else p++;
                    return keys;
                };
                if (p < t.Count && t[p].Id) {
                    string w = t[p].T.ToLowerInvariant();
                    if ((w == "graph" || w == "node" || w == "edge") && p + 1 < t.Count && !t[p + 1].Id && t[p + 1].T == "[") {
                        p++; var a = attrList();
                        if (w == "node") foreach (var kv in a) nodeDef[kv.Key] = kv.Value;
                        else if (w == "edge") foreach (var kv in a) edgeDef[kv.Key] = kv.Value;
                        else foreach (var kv in a) { if (group.Length > 0 && kv.Key == "label") graphLabel[group] = kv.Value; else graphA[kv.Key] = kv.Value; }
                        continue;
                    }
                    if (p + 1 < t.Count && !t[p + 1].Id && t[p + 1].T == "=") {            // name = value
                        string k = t[p].T; p += 2; string v = p < t.Count ? t[p].T : ""; p++;
                        if (group.Length > 0 && k == "label") graphLabel[group] = v; else graphA[k] = v;
                        continue;
                    }
                }
                var first = endpoint();
                if (isT("->") || isT("--")) {
                    var chain = new List<List<string>> { first };
                    while (isT("->") || isT("--")) { p++; chain.Add(endpoint()); }
                    var ea = new Dictionary<string, string>(edgeDef, StringComparer.OrdinalIgnoreCase);
                    foreach (var kv in attrList()) ea[kv.Key] = kv.Value;
                    for (int k = 0; k + 1 < chain.Count; k++) foreach (var a0 in chain[k]) foreach (var b0 in chain[k + 1]) edges.Add(new KeyValuePair<string[], Dictionary<string, string>>(new[] { a0, b0 }, ea));
                } else if (isT("[")) {
                    var a = attrList();
                    foreach (var k in first) { var d = nodes[k]; foreach (var kv in a) d.A[kv.Key] = kv.Value; }
                }
            }
        };
        graphLabel = new Dictionary<string, string>();
        stmts("", new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase), new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase));
        // the diagram text
        var sb = new StringBuilder();
        string gTitle; graphA.TryGetValue("label", out gTitle);
        string rank; graphA.TryGetValue("rankdir", out rank);
        sb.Append("title " + (string.IsNullOrEmpty(gTitle) ? "Imported from Graphviz" : gTitle.Replace("\n", " ")) + "\r\ntheme corporate light\r\nhide legend, header\r\n");
        sb.Append("direction " + (rank != null && (rank.ToUpperInvariant() == "LR" || rank.ToUpperInvariant() == "RL") ? "LR" : "TD") + "\r\nroute " + (graphA.ContainsKey("splines") && graphA["splines"] == "ortho" ? "ortho" : "curve") + "\r\n\r\n");
        foreach (var g in groups) {
            var members = order.Where(d => d.Group == g[0]).Select(d => d.Id).ToList();
            if (members.Count > 0) sb.Append("group " + g[0] + " " + Q(g[1].Length > 0 ? g[1] : g[0]) + " [dashed] { " + string.Join(", ", members) + " }\r\n");
        }
        foreach (var d in order) {
            string label = d.A.ContainsKey("label") ? d.A["label"] : d.Key;
            string shp = d.A.ContainsKey("shape") ? d.A["shape"].ToLowerInvariant() : "ellipse";
            var lines = new List<string>();
            if (shp == "record" || shp == "mrecord") {
                var parts = Regex.Split(label.Trim('{', '}', ' '), @"\s*\|\s*").Select(x => Regex.Replace(x, @"<[^>]*>", "").Trim('{', '}', ' ')).Where(x => x.Length > 0).ToList();
                label = parts.Count > 0 ? parts[0] : d.Key; lines = parts.Skip(1).ToList();
            } else {
                var ls = label.Split('\n').Select(x => x.Trim()).Where(x => x.Length > 0).ToList();
                label = ls.Count > 0 ? ls[0] : ""; lines = ls.Skip(1).ToList();
            }
            string shape = shp == "box" || shp == "rect" || shp == "rectangle" || shp == "square" ? (d.A.ContainsKey("style") && d.A["style"].Contains("rounded") ? "rounded" : "rect")
                         : shp == "circle" || shp == "doublecircle" || shp == "point" ? "circle" : shp == "ellipse" || shp == "oval" ? "pill"
                         : shp == "diamond" ? "diamond" : shp == "cylinder" ? "cylinder" : shp == "note" ? "note" : shp == "hexagon" ? "hexagon"
                         : shp == "parallelogram" ? "parallelogram" : shp == "folder" || shp == "tab" || shp == "component" ? "card"
                         : shp == "plaintext" || shp == "plain" || shp == "none" || shp == "underline" ? "text" : shp == "record" || shp == "mrecord" ? "table" : "rounded";
            var attrs = new List<string> { "shape " + shape };
            string fill = DotColor(d.A.ContainsKey("fillcolor") ? d.A["fillcolor"] : (d.A.ContainsKey("style") && d.A["style"].Contains("filled") && d.A.ContainsKey("color") ? d.A["color"] : ""));
            string stroke = DotColor(d.A.ContainsKey("color") ? d.A["color"] : ""), fc = DotColor(d.A.ContainsKey("fontcolor") ? d.A["fontcolor"] : "");
            if (fill.Length > 0) attrs.Add("fill " + fill);
            if (stroke.Length > 0) attrs.Add("stroke " + stroke);
            if (fc.Length > 0) attrs.Add("color " + fc);
            if (d.A.ContainsKey("style") && (d.A["style"].Contains("dashed") || d.A["style"].Contains("dotted"))) attrs.Add("dashed");
            if (lines.Count > 0) attrs.Add("lines " + string.Join(" ", lines.Take(12).Select(Q)));
            sb.Append(d.Id + ": " + Lbl(label) + " [" + string.Join(", ", attrs) + "]\r\n");
        }
        sb.Append("\r\n");
        foreach (var e in edges) {
            var a = e.Value; var attrs = new List<string>();
            if (a.ContainsKey("label") && a["label"].Length > 0) attrs.Add("label " + Q(a["label"].Replace("\n", " ")));
            if (a.ContainsKey("style") && a["style"].Contains("dotted")) attrs.Add("dotted"); else if (a.ContainsKey("style") && a["style"].Contains("dashed")) attrs.Add("dashed");
            string dir = a.ContainsKey("dir") ? a["dir"].ToLowerInvariant() : (directed ? "forward" : "none");
            if (dir != "forward") attrs.Add("arrow " + (dir == "both" ? "both" : dir == "back" ? "start" : "none"));
            string col = DotColor(a.ContainsKey("color") ? a["color"] : ""); if (col.Length > 0) attrs.Add("color " + col);
            sb.Append(nodes[e.Key[0]].Id + " -> " + nodes[e.Key[1]].Id + (attrs.Count > 0 ? " [" + string.Join(", ", attrs) + "]" : "") + "\r\n");
        }
        return sb.ToString();
    }
    static Dictionary<string, string> graphLabel = new Dictionary<string, string>();
    // a Graphviz colour (#rrggbb, a name like "lightblue", or "0.6 0.3 0.9" HSV) as #rrggbb
    static string DotColor(string c) {
        if (string.IsNullOrEmpty(c)) return "";
        c = c.Split(':')[0].Trim();
        if (Regex.IsMatch(c, @"^#[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$")) return c.Substring(0, 7);
        var col = System.Drawing.Color.FromName(c.Replace(" ", ""));
        if (col.IsKnownColor || col.A > 0 && (col.R | col.G | col.B) != 0) return "#" + col.R.ToString("x2") + col.G.ToString("x2") + col.B.ToString("x2");
        return "";
    }
    public static bool IsDot(string s) { return Regex.IsMatch(s ?? "", @"^\s*(?://[^\n]*\n\s*|/\*[\s\S]*?\*/\s*)*(strict\s+)?(di)?graph\b[^{]*\{", RegexOptions.IgnoreCase); }
}

// ---- Query plan tuner: SQL Server's plan (estimated or actual) as a diagram, with suggestions and fixes.
public class DgPlanOp {
    public int Id, Parent = -1, Depth;
    public string Physical = "", Logical = "", Table = "", Index = "", Alias = "", Warn = "";
    public double SubtreeCost, OwnCost, Pct, EstRows, ActRows = -1, Executions = -1;
    public List<string> Predicates = new List<string>(), Outputs = new List<string>();
}
public class DgPlanTip { public int Level; public string Title = "", Detail = "", Fix = ""; }     // level: 3 high, 2 medium, 1 low
public class DgPlanReport {
    public List<DgPlanOp> Ops = new List<DgPlanOp>();
    public List<DgPlanTip> Tips = new List<DgPlanTip>();
    public List<string> Xml = new List<string>();
    public string Statement = "", Error = "";
    public double TotalCost;
    public bool Actual;
    public long Ms;
    public DgSqlResult Result;
}

public class DgPlanRun {
    public volatile bool Done;
    public DgPlanReport Report = new DgPlanReport();
    System.Data.SqlClient.SqlCommand cmd;
    volatile bool cancel;
    public void Cancel() { cancel = true; try { if (cmd != null) cmd.Cancel(); } catch { } }

    public static DgPlanRun Start(string conn, string sql, bool actual, int maxRows) {
        var r = new DgPlanRun();
        new System.Threading.Thread(() => r.Run(conn, sql, actual, maxRows)) { IsBackground = true, Name = "DevTools plan" }.Start();
        return r;
    }
    void Run(string connStr, string sql, bool actual, int maxRows) {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        Report.Actual = actual;
        var res = new DgSqlResult();
        try {
            using (var conn = new System.Data.SqlClient.SqlConnection(connStr)) {
                conn.InfoMessage += (s, e) => { lock (res.Messages) foreach (System.Data.SqlClient.SqlError er in e.Errors) res.Messages.Add(er.Message); };
                conn.Open();
                using (var on = new System.Data.SqlClient.SqlCommand(actual ? "SET STATISTICS XML ON" : "SET SHOWPLAN_XML ON", conn)) on.ExecuteNonQuery();
                try {
                    foreach (var batch in DgSqlRun.Batches(sql)) {
                        if (cancel) break;
                        using (var c = new System.Data.SqlClient.SqlCommand(batch.Value, conn)) {
                            c.CommandTimeout = 0; cmd = c;
                            using (var rd = c.ExecuteReader()) {
                                do {
                                    if (rd.FieldCount == 1 && rd.GetName(0).IndexOf("Showplan", StringComparison.OrdinalIgnoreCase) >= 0) { while (rd.Read()) Report.Xml.Add(rd.GetValue(0).ToString()); continue; }
                                    if (rd.FieldCount == 0) continue;
                                    var tb = new System.Data.DataTable("Result " + (res.Tables.Count + 1));
                                    for (int i = 0; i < rd.FieldCount; i++) tb.Columns.Add(i + ":" + rd.GetName(i), typeof(object));
                                    var vals = new object[rd.FieldCount];
                                    var udt = DgSqlRun.Udt(rd);
                                    while (rd.Read()) { if (cancel || tb.Rows.Count >= maxRows) { if (!cancel) res.Truncated = true; break; } DgSqlRun.Read(rd, vals, udt); tb.Rows.Add(vals); }
                                    for (int i = 0; i < tb.Columns.Count; i++) tb.Columns[i].ColumnName = UniqueName(tb, rd.GetName(i), i);
                                    res.Tables.Add(tb);
                                } while (rd.NextResult());
                            }
                            cmd = null;
                        }
                    }
                } finally {
                    try { using (var off = new System.Data.SqlClient.SqlCommand(actual ? "SET STATISTICS XML OFF" : "SET SHOWPLAN_XML OFF", conn)) off.ExecuteNonQuery(); } catch { }
                }
            }
        } catch (Exception ex) { Report.Error = cancel ? "Cancelled." : ex.Message; }
        Report.Result = res;
        Report.Ms = sw.ElapsedMilliseconds;
        try { if (Report.Xml.Count > 0) DgPlan.Analyze(Report, sql); } catch (Exception ex) { Report.Error += (Report.Error.Length > 0 ? " / " : "") + "Plan: " + ex.Message; }
        Done = true;
    }
    static string UniqueName(System.Data.DataTable t, string n, int i) {
        if (string.IsNullOrEmpty(n)) n = "(no name)";
        string u = n; int k = 2;
        for (int j = 0; j < i; j++) if (string.Equals(t.Columns[j].ColumnName, u, StringComparison.OrdinalIgnoreCase)) { u = n + " (" + k++ + ")"; j = -1; }
        return u;
    }
}

public static class DgPlan {
    static readonly System.Xml.Linq.XNamespace S = "http://schemas.microsoft.com/sqlserver/2004/07/showplan";
    static double D(System.Xml.Linq.XAttribute a) { double v; return a != null && double.TryParse(a.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out v) ? v : 0; }
    static string Col(System.Xml.Linq.XElement c) {
        var t = (string)c.Attribute("Table"); var a = (string)c.Attribute("Alias"); var n = (string)c.Attribute("Column");
        return (a ?? t ?? "").Trim('[', ']') + (a != null || t != null ? "." : "") + (n ?? "").Trim('[', ']');
    }
    static string Name(string s) { return (s ?? "").Trim('[', ']'); }

    public static void Analyze(DgPlanReport r, string sql) {
        var seenIdx = new HashSet<string>();
        foreach (var xml in r.Xml) {
            var doc = System.Xml.Linq.XDocument.Parse(xml);
            foreach (var stmt in doc.Descendants(S + "StmtSimple")) {
                double cost = D(stmt.Attribute("StatementSubTreeCost"));
                var qp = stmt.Element(S + "QueryPlan");
                if (qp == null) continue;
                if (cost > r.TotalCost) { r.TotalCost = cost; r.Statement = Regex.Replace((string)stmt.Attribute("StatementText") ?? "", @"\s+", " ").Trim(); }
                int baseId = r.Ops.Count;
                var root = qp.Element(S + "RelOp");
                if (root != null) Walk(root, -1, 0, r, baseId);
                // operator costs as a share of the statement
                foreach (var op in r.Ops.Skip(baseId)) {
                    double kids = r.Ops.Skip(baseId).Where(k => k.Parent == op.Id).Sum(k => k.SubtreeCost);
                    op.OwnCost = Math.Max(0, op.SubtreeCost - kids);
                    op.Pct = cost > 0 ? op.OwnCost / cost * 100 : 0;
                }
                // missing indexes that SQL Server itself suggests
                foreach (var g in qp.Descendants(S + "MissingIndexGroup")) {
                    double impact = D(g.Attribute("Impact"));
                    foreach (var mi in g.Elements(S + "MissingIndex")) {
                        string db = Name((string)mi.Attribute("Database")), sch = Name((string)mi.Attribute("Schema")), tb = Name((string)mi.Attribute("Table"));
                        Func<string, List<string>> cols = u => mi.Elements(S + "ColumnGroup").Where(cg => (string)cg.Attribute("Usage") == u).SelectMany(cg => cg.Elements(S + "Column")).Select(c => Name((string)c.Attribute("Name"))).ToList();
                        var eq = cols("EQUALITY"); var ineq = cols("INEQUALITY"); var inc = cols("INCLUDE");
                        var keys = eq.Concat(ineq).ToList();
                        if (keys.Count == 0) continue;
                        string ixName = "IX_" + tb + "_" + string.Join("_", keys.Take(3));
                        string fix = "CREATE NONCLUSTERED INDEX [" + ixName + "]\r\n    ON [" + sch + "].[" + tb + "] (" + string.Join(", ", keys.Select(k => "[" + k + "]")) + ")" + (inc.Count > 0 ? "\r\n    INCLUDE (" + string.Join(", ", inc.Select(k => "[" + k + "]")) + ")" : "") + ";";
                        if (!seenIdx.Add(fix)) continue;
                        r.Tips.Add(new DgPlanTip { Level = impact >= 50 ? 3 : 2, Title = "Missing index on " + sch + "." + tb + "  (SQL Server estimates " + impact.ToString("0") + "% less cost)",
                            Detail = "Searched by " + string.Join(", ", eq.Concat(ineq)) + (inc.Count > 0 ? "; also reads " + string.Join(", ", inc) : "") + ". An index lets SQL Server seek straight to the rows instead of reading the whole table. Check it against the indexes you already have, and keep in mind every index slows inserts and updates a little.",
                            Fix = fix });
                    }
                }
                // statement warnings
                foreach (var w in qp.Elements(S + "Warnings")) Warnings(w, null, r);
            }
        }
        // operator rules
        foreach (var op in r.Ops) {
            bool scan = op.Physical == "Table Scan" || op.Physical == "Clustered Index Scan" || op.Physical == "Index Scan";
            double rows = op.ActRows >= 0 ? op.ActRows : op.EstRows;
            if (scan && op.Predicates.Count > 0 && (op.Pct >= 20 || rows >= 1000))
                r.Tips.Add(new DgPlanTip { Level = op.Pct >= 40 ? 3 : 2, Title = op.Physical + " on " + op.Table + " (" + op.Pct.ToString("0") + "% of the cost) to filter rows",
                    Detail = "It reads every row and then keeps only those where " + string.Join(" and ", op.Predicates.Take(2)) + ". An index on the filtered column(s) would let it seek instead; if the filter wraps the column in a function or compares it with a different type, the index can't be used." });
            else if (scan && op.Pct >= 50 && rows >= 10000)
                r.Tips.Add(new DgPlanTip { Level = 2, Title = op.Physical + " reads all of " + op.Table + " (" + DgChartCalc.Short(rows) + " rows, " + op.Pct.ToString("0") + "% of the cost)", Detail = "If you only need some rows, add a WHERE that an index can use; if you need all of them, select only the columns you need." });
            if (op.Physical == "Key Lookup" || op.Physical == "RID Lookup") {
                var cols = op.Outputs.Select(o => o.Substring(o.LastIndexOf('.') + 1)).Distinct().ToList();
                r.Tips.Add(new DgPlanTip { Level = op.Pct >= 25 ? 3 : 2, Title = op.Physical + " into " + op.Table + " (" + op.Pct.ToString("0") + "% of the cost)",
                    Detail = "For every row found through an index, SQL Server goes back to the table for " + (cols.Count > 0 ? string.Join(", ", cols) : "more columns") + ". Adding them to the index as INCLUDE columns (a covering index) removes the lookups.",
                    Fix = cols.Count > 0 ? "-- add to the index the plan seeks on:\r\n-- CREATE INDEX ... ON " + op.Table + " (...) INCLUDE (" + string.Join(", ", cols.Select(k => "[" + k + "]")) + ") WITH (DROP_EXISTING = ON);" : "" });
            }
            if (op.Physical == "Sort" && op.Pct >= 25)
                r.Tips.Add(new DgPlanTip { Level = 2, Title = "Sort is " + op.Pct.ToString("0") + "% of the cost", Detail = "An index whose key is in the ORDER BY / GROUP BY order returns the rows already sorted. Otherwise sort fewer rows (filter first, or TOP)." });
            if (op.Physical == "Hash Match" && op.Pct >= 30 && op.Logical.Contains("Join"))
                r.Tips.Add(new DgPlanTip { Level = 1, Title = "Hash join is " + op.Pct.ToString("0") + "% of the cost", Detail = "Big hash joins usually mean both sides are read in full. Indexes on the join columns allow nested loops or merge joins." });
            if (op.ActRows >= 0 && op.EstRows > 0) {
                double ratio = (op.ActRows + 1) / (op.EstRows + 1);
                if ((ratio > 10 || ratio < 0.1) && Math.Abs(op.ActRows - op.EstRows) > 1000)
                    r.Tips.Add(new DgPlanTip { Level = 2, Title = "Estimate far off at " + op.Physical + (op.Table.Length > 0 ? " on " + op.Table : "") + ": " + DgChartCalc.Short(op.EstRows) + " estimated, " + DgChartCalc.Short(op.ActRows) + " actual",
                        Detail = "Wrong estimates lead to wrong join types and memory grants. Fresh statistics usually fix it.", Fix = op.Table.Length > 0 ? "UPDATE STATISTICS " + op.Table + " WITH FULLSCAN;" : "" });
            }
        }
        // SQL text rules
        var s0 = Regex.Replace(sql ?? "", @"--[^\n]*|/\*[\s\S]*?\*/|'(?:[^']|'')*'", m => m.Value.StartsWith("'") ? "''" : " ");
        if (Regex.IsMatch(s0, @"\bSELECT\s+(TOP\s*\(?\s*\d+\s*\)?\s+)?(DISTINCT\s+)?\*", RegexOptions.IgnoreCase))
            r.Tips.Add(new DgPlanTip { Level = 1, Title = "SELECT * reads every column", Detail = "Listing only the columns you need moves less data and lets narrower (covering) indexes be used." });
        if (Regex.IsMatch(sql ?? "", @"LIKE\s+N?'%", RegexOptions.IgnoreCase))
            r.Tips.Add(new DgPlanTip { Level = 2, Title = "LIKE '%...' can't use an index", Detail = "A pattern that starts with % has to check every row. If you search inside text often, consider full-text search or a computed column." });
        var fn = Regex.Match(s0, @"\b(WHERE|AND|OR|ON)\s+(YEAR|MONTH|DAY|UPPER|LOWER|LTRIM|RTRIM|TRIM|CONVERT|CAST|ISNULL|COALESCE|DATEPART|LEFT|SUBSTRING|DATEADD)\s*\(\s*([\w\.\[\]]+)", RegexOptions.IgnoreCase);
        if (fn.Success)
            r.Tips.Add(new DgPlanTip { Level = 2, Title = "A function on a column in the filter: " + fn.Groups[2].Value.ToUpperInvariant() + "(" + fn.Groups[3].Value + ")", Detail = "Wrapping a column in a function hides it from its index (the filter is not 'sargable'). Compare the bare column instead, e.g. WHERE d >= '2024-01-01' AND d < '2025-01-01' instead of YEAR(d) = 2024." });
        if (Regex.IsMatch(s0, @"\bNOT\s+IN\s*\(\s*SELECT\b", RegexOptions.IgnoreCase))
            r.Tips.Add(new DgPlanTip { Level = 1, Title = "NOT IN (SELECT ...)", Detail = "If the subquery returns a NULL, NOT IN returns no rows at all. NOT EXISTS is safer and often faster." });
        if (Regex.IsMatch(s0, @"\bSELECT\b[\s\S]*\(\s*SELECT\b", RegexOptions.IgnoreCase) && Regex.IsMatch(s0, @"\bSELECT\s+[^;]*?,\s*\(\s*SELECT\b", RegexOptions.IgnoreCase))
            r.Tips.Add(new DgPlanTip { Level = 1, Title = "A subquery in the SELECT list", Detail = "It may run once per row. A JOIN (or OUTER APPLY) is often faster." });
        if (r.Tips.Count == 0) r.Tips.Add(new DgPlanTip { Level = 0, Title = "Nothing obvious to improve", Detail = "The plan has no warnings, missing indexes or expensive scans" + (r.Actual ? "" : " (estimated plan; Run with plan shows real row counts)") + "." });
