        '<span class=""' + (totals.dropped ? P + '-bad' : '') + '""><b>' + fmt(totals.dropped * 1180) + '</b> dropped</span><span>' + (down ? '<b class=""' + P + '-bad"">' + down + ' down</b>' : 'all up') + '</span>';
      var dot = q(cls('live')); if (dot) dot.classList.toggle(P + '-bad', down > 0);
    }
