function Get-DiagramFiles {
    if (-not (Test-Path -LiteralPath $DgDir)) { return @() }
    @(Get-ChildItem -LiteralPath $DgDir -Filter '*.dgm' -File -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending)
}
# the folder new diagrams go into: the one selected in the Saved tree (or the folder of the selected diagram)
function Get-DiagramTargetDir {
    $d = if ($DgUI.Folders) { Get-DiagramDirOf (Get-DvFolderSelected $DgUI.Folders) } else { $DgDir }
    if ($d -and (Test-Path -LiteralPath $d) -and (Test-DiagramInside $d)) { return $d }
    $DgDir
}
function Test-DiagramInside([string]$Path) {
    $root = [IO.Path]::GetFullPath($DgDir).TrimEnd('\') + '\'
    ([IO.Path]::GetFullPath($Path).TrimEnd('\') + '\').StartsWith($root, [StringComparison]::OrdinalIgnoreCase)
}
function Get-DiagramRelative([string]$Path) {
    $root = [IO.Path]::GetFullPath($DgDir).TrimEnd('\')
    $full = [IO.Path]::GetFullPath($Path)
    if ($full.Length -le $root.Length) { return '' }
    $full.Substring($root.Length + 1)
}

# The text changed (typed, or an edit on the canvas): parse, lay out, draw.
function Update-Diagram([switch]$Fit) {
    $t = $DgUI.Text
    $d = [DgText]::Parse($t)
    [DgLayout]::Apply($d)
    $DgUI.Doc = $d
    $cv = $DgUI.Canvas
    $cv.Theme = [DgTheme]::Get($d.Theme)
    if (-not $DgUI.ModeSet) { $cv.Dark = if ($d.Mode -eq 'auto') { [bool]$script:IsDark } else { $d.Mode -ne 'light' } }
    $cv.SetDoc($d, (-not $Fit))
    if ($Fit) { $cv.UserView = $false; $cv.ZoomToFit() }
    $w = @($d.Warnings)
    $DgUI.Warn.Text = if ($w.Count) { ($w | Select-Object -First 3) -join "`n" } else { "$(@($d.Nodes).Count) shapes, $(@($d.Edges).Count) links" }
    $DgUI.Warn.ForeColor = if ($w.Count) { $C.Yellow } else { $C.Dim }
    Update-DiagramProps
    Update-DiagramTitle
    if ($DgUI.File) { $DgUI.SaveTimer.Stop(); $DgUI.SaveTimer.Start() }
}

function Update-DiagramTitle {
    if (-not $DgUI.Form) { return }
    $n = if ($DgUI.File) { [IO.Path]::GetFileNameWithoutExtension($DgUI.File) } else { 'not saved' }
    $DgUI.Form.Text = "Diagram studio  -  $n"
}

# Replaces the text (from an edit), with undo.
function Set-DiagramText([string]$Text, [switch]$Fit, [switch]$NoUndo) {
    if ($Text -ceq $DgUI.Text) { return }
    if (-not $NoUndo) { $DgUI.Undo.Add($DgUI.Text); if ($DgUI.Undo.Count -gt 200) { $DgUI.Undo.RemoveAt(0) }; $DgUI.Redo.Clear() }
    $DgUI.Text = $Text
    $DgUI.Quiet = $true
    try {
        $ed = $DgUI.Editor
        $top = $ed.GetCharIndexFromPosition((New-Object System.Drawing.Point(2, 2)))     # keep what was in view
        $sel = $ed.SelectionStart
        [PowerClipTheme]::Redraw($ed.Handle, $false)
        try {
            $ed.Text = $Text
            Set-DiagramColors
            $ed.Select([Math]::Min($top, $ed.TextLength), 0); $ed.ScrollToCaret()
            $ed.Select([Math]::Min($sel, $ed.TextLength), 0)
        } finally { [PowerClipTheme]::Redraw($ed.Handle, $true); $ed.Invalidate() }
    } finally { $DgUI.Quiet = $false }
    Update-Diagram -Fit:$Fit
}

function Undo-Diagram {
    if ($DgUI.Undo.Count -eq 0) { return }
    $DgUI.Redo.Add($DgUI.Text)
    $t = $DgUI.Undo[$DgUI.Undo.Count - 1]; $DgUI.Undo.RemoveAt($DgUI.Undo.Count - 1)
    Set-DiagramText $t -NoUndo
}
function Redo-Diagram {
    if ($DgUI.Redo.Count -eq 0) { return }
    $DgUI.Undo.Add($DgUI.Text)
    $t = $DgUI.Redo[$DgUI.Redo.Count - 1]; $DgUI.Redo.RemoveAt($DgUI.Redo.Count - 1)
    Set-DiagramText $t -NoUndo
}

# Colours in the text: comments, keywords, ids, [attributes], "strings", arrows, #colours.
function Set-DiagramColors {
    $ed = $DgUI.Editor
    $t = $ed.Text
    [PowerClipTheme]::Redraw($ed.Handle, $false)
    $ss = $ed.SelectionStart; $sl = $ed.SelectionLength
    try {
        $ed.SelectAll(); $ed.SelectionColor = $C.Fore
        $paint = { param($rx, $col, $grp) foreach ($m in [regex]::Matches($t, $rx, 'Multiline')) { $g = $m.Groups[$grp]; if ($g.Length) { $ed.Select($g.Index, $g.Length); $ed.SelectionColor = $col } } }
        & $paint '^\s*(title|subtitle|theme|mode|font|mono|layout|direction|dir|graph|flowchart|route|routing|spacing|radius|hide|show|category|cat|flow|lanes|lane|group|subgraph|end|style|hint|click|chart|data|x|y|series|agg|sort|top|labels|stacked|prefix|suffix)\b' $C.Accent 1
        & $paint '^\s*([A-Za-z_][\w\-]*)\s*:' $C.Purple 1
        & $paint '^\s+(desc|description|tags|lines|line|items|url|link|metric|badge|status|note)\b' $C.Green 1
        & $paint '(\s\[[^\]\r\n]*\])\s*$' $C.Dim 1
        & $paint '(<?(-\.+-?>?|={2,3}>|-{2,3}>|-{3}|->)(\|[^|\r\n]*\|)?)' $C.Green 1
        & $paint '("[^"\r\n]*")' $C.Orange 1
        & $paint '(#[0-9a-fA-F]{3,8})\b' $C.Orange 1
        & $paint '^\s*((%%|//|#(?![0-9a-fA-F]{3,8}\b)).*)$' $C.Dim 1
    } finally { $ed.Select($ss, $sl); [PowerClipTheme]::Redraw($ed.Handle, $true); $ed.Invalidate() }
}

# ---- saving
function Save-DiagramFile {
    if (-not $DgUI.File) { return }
    try {
        if (-not (Test-Path -LiteralPath $DgDir)) { [void](New-Item -ItemType Directory -Path $DgDir -Force) }
        Write-JsonFile $DgUI.File $DgUI.Text
    } catch { Write-Log "diagram save failed: $_" }
}
function New-DiagramName([string]$Base, [string]$Dir = '', [string]$Ext = '.dgm') {
    if (-not $Dir) { $Dir = $DgDir }
    $Base = (($Base -replace '[\\/:*?"<>|]', ' ') -replace '\s+', ' ').Trim().TrimEnd('.')
    if (-not $Base) { $Base = 'Diagram' }
    $n = $Base; $i = 2
    while (Test-Path -LiteralPath (Join-Path $Dir "$n$Ext")) { $n = "$Base $i"; $i++ }
    $n
}
function Open-DiagramFile([string]$Path) {
    Save-DiagramFile
    try { $t = Read-DataText $Path } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't open it: $($_.Exception.Message)", 'Diagram studio'); return }
    $DgUI.File = $Path
    $DgUI.Undo.Clear(); $DgUI.Redo.Clear()
    Set-DiagramText $t -Fit -NoUndo
    Update-DiagramList
}
function New-DiagramFromText([string]$Name, [string]$Text) {
    Save-DiagramFile
    $dir = Get-DiagramTargetDir
    if (-not (Test-Path -LiteralPath $dir)) { [void](New-Item -ItemType Directory -Path $dir -Force) }
    $DgUI.File = Join-Path $dir ((New-DiagramName $Name $dir) + '.dgm')
    $DgUI.Undo.Clear(); $DgUI.Redo.Clear()
    Set-DiagramText $Text -Fit -NoUndo
    Save-DiagramFile
    Update-DiagramList
}
# ---- the Saved tab: folders like in Notes (real folders under data\diagrams; "Work/Network" = data\diagrams\Work\Network)
function Get-DiagramDirOf([string]$Folder) { if ($Folder) { Join-Path $DgDir ($Folder -replace '/', '\') } else { $DgDir } }
function Get-DiagramFolderOf([string]$Dir) { (Get-DiagramRelative $Dir) -replace '\\', '/' }
function Get-DiagramFolders {
    if (-not (Test-Path -LiteralPath $DgDir)) { return @() }
    @(Get-ChildItem -LiteralPath $DgDir -Directory -Recurse -ErrorAction SilentlyContinue | ForEach-Object { Get-DiagramFolderOf $_.FullName })
}
function Get-DiagramItems {
    foreach ($f in @(Get-DiagramFiles)) { [pscustomobject]@{ Folder = (Get-DiagramFolderOf (Split-Path -Parent $f.FullName)); Path = $f.FullName; Name = $f.BaseName; Time = $f.LastWriteTime } }
}
$DgCollapsedFile = Join-Path (Split-Path -Parent $DgDir) 'diagram-folders.json'
function Save-DiagramCollapsed { if ($DgUI.Folders) { try { Write-JsonFile $DgCollapsedFile (ConvertTo-Json -InputObject @($DgUI.Folders.Collapsed) -Compress) } catch { } } }
# keeps closed folders closed after a folder is renamed or moved
function Move-DiagramCollapsed([string]$Old, [string]$New) {
    $fl = $DgUI.Folders
    if (-not $fl -or -not $Old) { return }
    foreach ($p in @($fl.Collapsed)) { if ($p -eq $Old -or $p.StartsWith($Old + '/', [StringComparison]::OrdinalIgnoreCase)) { [void]$fl.Collapsed.Remove($p); if ($New) { [void]$fl.Collapsed.Add($New + $p.Substring($Old.Length)) } } }
    Save-DiagramCollapsed
}
# the open diagram's file after a file or folder moved
function Update-DiagramOpenPath([string]$Old, [string]$New) {
    if (-not $DgUI.File) { return }
    if ($DgUI.File -eq $Old) { $DgUI.File = $New }
    elseif ($DgUI.File.StartsWith($Old + '\', [StringComparison]::OrdinalIgnoreCase)) { $DgUI.File = $New + $DgUI.File.Substring($Old.Length) }
}
function Show-DiagramFolder([string]$Folder) {
    $fl = $DgUI.Folders
    if (-not $fl) { return }
    $x = $Folder; while ($x) { [void]$fl.Collapsed.Remove($x); $x = Get-DvFolderParent $x }
    Save-DiagramCollapsed
}

function Update-DiagramList {
    if (-not $DgUI.Folders) { return }
    if (-not (Test-Path -LiteralPath $DgDir)) { [void](New-Item -ItemType Directory -Path $DgDir -Force) }
    if ($DgUI.File) { Show-DiagramFolder (Get-DiagramFolderOf (Split-Path -Parent $DgUI.File)) }
    Update-DvFolderList $DgUI.Folders
}

function New-DiagramNamed {
    $dir = Get-DiagramTargetDir
    $rel = Get-DiagramFolderOf $dir
    $n = Read-TextDialog 'New diagram' $(if ($rel) { "Name  (in the folder $($rel.Replace('/', ' > ')))" } else { 'Name' }) 'Diagram' $DgUI.Form
    if (-not $n) { return }
    New-DiagramFromText $n "title $n`r`ntheme midnight dark`r`n`r`na: Start`r`nb: Next step`r`na -> b"
    Select-ApiTab $DgUI.Tabs 'Text'
}

# a folder ("Work/Network") inside $Parent ('' = the top)
function New-DiagramFolder([string]$Parent = '', [string]$Name = '') {
    $dir = Get-DiagramDirOf $Parent
    $n = if ($Name) { $Name } else { Read-TextDialog 'New folder' $(if ($Parent) { "Folder name  (inside $($Parent.Replace('/', ' > ')))" } else { 'Folder name' }) '' $DgUI.Form }
    if (-not $n) { return }
    $n = (($n -replace '[\\/:*?"<>|]', ' ') -replace '\s+', ' ').Trim().TrimEnd('.')
    if (-not $n) { return }
    $path = Join-Path $dir $n
    if (Test-Path -LiteralPath $path) { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "There is already a ""$n"" there.", 'Diagram studio'); return }
    [void](New-Item -ItemType Directory -Path $path -Force)
    $folder = Get-DiagramFolderOf $path
    Show-DiagramFolder $folder
    if ($DgUI.Folders) { $DgUI.Folders.SelectedFolder = $folder; $DgUI.Folders.FocusFolder = $true }
    Update-DiagramList
}

# moves a diagram file or a folder into another folder (keeps the open diagram open)
function Move-DiagramItem([string]$Path, [string]$ToDir) {
    if (-not (Test-Path -LiteralPath $Path) -or -not (Test-DiagramInside $ToDir)) { return }
    $isDir = Test-Path -LiteralPath $Path -PathType Container
    if ($isDir -and ([IO.Path]::GetFullPath($ToDir).TrimEnd('\') + '\').StartsWith(([IO.Path]::GetFullPath($Path).TrimEnd('\') + '\'), [StringComparison]::OrdinalIgnoreCase)) { return }   # not into itself
    if ((Split-Path -Parent $Path) -eq $ToDir.TrimEnd('\')) { return }
    $name = Split-Path -Leaf $Path
    $dest = Join-Path $ToDir $name
    if (Test-Path -LiteralPath $dest) {
        if ($isDir) { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "There is already a folder ""$name"" there.", 'Diagram studio'); return }
        $dest = Join-Path $ToDir ((New-DiagramName ([IO.Path]::GetFileNameWithoutExtension($name)) $ToDir) + '.dgm')
    }
    Save-DiagramFile
    try { Move-Item -LiteralPath $Path -Destination $dest -ErrorAction Stop } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't move it: $($_.Exception.Message)", 'Diagram studio'); return }
    Update-DiagramOpenPath $Path $dest
    if ($isDir) { Move-DiagramCollapsed (Get-DiagramFolderOf $Path) (Get-DiagramFolderOf $dest) }
    Show-DiagramFolder (Get-DiagramFolderOf $ToDir)
    Update-DiagramTitle
    Update-DiagramList
}

# the file or folder a row of the list stands for
function Get-DiagramRowPath($Row) { if (-not $Row) { return $null }; if ($Row.IsFolder) { Get-DiagramDirOf $Row.Path } else { $Row.Item.Path } }

function Rename-DiagramItem($Row, [string]$NewName = '') {
    if (-not $Row -or $Row.Empty) { return }
    $path = Get-DiagramRowPath $Row
    $old = if ($Row.IsFolder) { Split-Path -Leaf $path } else { [IO.Path]::GetFileNameWithoutExtension($path) }
    $n = if ($NewName) { $NewName } else { Read-TextDialog $(if ($Row.IsFolder) { 'Rename folder' } else { 'Rename diagram' }) 'New name' $old $DgUI.Form }
    if (-not $n -or $n -ceq $old) { return }
    $n = (($n -replace '[\\/:*?"<>|]', ' ') -replace '\s+', ' ').Trim().TrimEnd('.')
    if (-not $n) { return }
    $dir = Split-Path -Parent $path
    Save-DiagramFile
    try {
        if (-not $Row.IsFolder) {
            $new = Join-Path $dir ((New-DiagramName $n $dir) + '.dgm')
            Move-Item -LiteralPath $path -Destination $new -ErrorAction Stop
        } else {
            $new = Join-Path $dir $n
            if ((Test-Path -LiteralPath $new) -and $n -ne $old) { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "There is already a ""$n"" there.", 'Diagram studio'); return }
            Move-Item -LiteralPath $path -Destination $new -ErrorAction Stop
            Move-DiagramCollapsed $Row.Path (Get-DiagramFolderOf $new)
        }
    } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't rename it: $($_.Exception.Message)", 'Diagram studio'); return }
    Update-DiagramOpenPath $path $new
    Update-DiagramTitle
    Update-DiagramList
}

# a diagram: deleted after asking.  A folder: like in Notes, only the folder goes - what is in it moves up one level.
function Remove-DiagramItem($Row, [switch]$NoPrompt) {
    if (-not $Row -or $Row.Empty) { return }
    $path = Get-DiagramRowPath $Row
    if (-not (Test-Path -LiteralPath $path)) { Update-DiagramList; return }
    if (-not $Row.IsFolder) {
        if (-not $NoPrompt -and [System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Delete the diagram ""$($Row.Item.Name)""?", 'Diagram studio', 'YesNo', 'Question') -ne 'Yes') { return }
        if ($DgUI.File -eq $path) { $DgUI.File = ''; Update-DiagramTitle }
        Remove-Item -LiteralPath $path -Force
        Update-DiagramList
        return
    }
    $parentDir = Split-Path -Parent $path
    $parent = Get-DvFolderParent $Row.Path
    $files = @(Get-ChildItem -LiteralPath $path -Filter '*.dgm' -File -ErrorAction SilentlyContinue).Count
    $subs = @(Get-ChildItem -LiteralPath $path -Directory -ErrorAction SilentlyContinue).Count
    if ($files + $subs -gt 0 -and -not $NoPrompt) {
        $where = if ($parent) { """$($parent.Replace('/', ' > '))""" } else { 'the top level' }
        if ([System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Delete the folder ""$($Row.Label)""? Nothing inside is deleted: its $files diagram(s) and $subs subfolder(s) move up to $where.", 'Diagram studio', 'OKCancel', 'Question') -ne 'OK') { return }
    }
    Save-DiagramFile
    foreach ($it in @(Get-ChildItem -LiteralPath $path -Force -ErrorAction SilentlyContinue)) {
        $dest = Join-Path $parentDir $it.Name
        if (Test-Path -LiteralPath $dest) {
            if ($it.PSIsContainer) { $k = 2; while (Test-Path -LiteralPath "$dest $k") { $k++ }; $dest = "$dest $k" }
            else { $dest = Join-Path $parentDir ((New-DiagramName $it.BaseName $parentDir $it.Extension) + $it.Extension) }
        }
        try { Move-Item -LiteralPath $it.FullName -Destination $dest -ErrorAction Stop } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't move ""$($it.Name)"" out: $($_.Exception.Message)", 'Diagram studio'); Update-DiagramList; return }
        Update-DiagramOpenPath $it.FullName $dest
        if ($it.PSIsContainer) { Move-DiagramCollapsed (Get-DiagramFolderOf $it.FullName) (Get-DiagramFolderOf $dest) }
    }
    Move-DiagramCollapsed $Row.Path ''
    if (-not @(Get-ChildItem -LiteralPath $path -Force -ErrorAction SilentlyContinue).Count) { Remove-Item -LiteralPath $path -Force }
    if ($DgUI.Folders) { $DgUI.Folders.SelectedFolder = $parent; $DgUI.Folders.FocusFolder = [bool]$parent }
    Update-DiagramTitle
    Update-DiagramList
}

function Copy-DiagramItem($Row) {
    if (-not $Row -or $Row.IsFolder -or $Row.Empty) { return }
    Save-DiagramFile
    $src = $Row.Item.Path
    $dir = Split-Path -Parent $src
    $new = Join-Path $dir ((New-DiagramName ([IO.Path]::GetFileNameWithoutExtension($src) + ' copy') $dir) + '.dgm')
    Copy-Item -LiteralPath $src -Destination $new
    Open-DiagramFile $new
}

# the right-click menu, worded like the API chains one
function Show-DiagramTreeMenu($Menu, $Row) {
    if ($Row -and $Row.IsFolder) {
        [void](Add-MenuItem $Menu 'New diagram here...' { $DgUI.Folders.SelectedFolder = $DgUI.Folders.MenuRow.Path; $DgUI.Folders.List.ClearSelected(); New-DiagramNamed } $Glyph.Add)
        [void](Add-MenuItem $Menu 'New folder inside...' { New-DiagramFolder $DgUI.Folders.MenuRow.Path } $Glyph.Folder)
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Rename folder...' { Rename-DiagramItem $DgUI.Folders.MenuRow } $Glyph.Edit 'F2')
        Add-DvMoveMenu $Menu $DgUI.Folders (Get-DvFolderParent $Row.Path) $Row.Path { param($to) Move-DiagramItem (Get-DiagramRowPath $DgUI.Folders.MenuRow) (Get-DiagramDirOf $to) }
        [void](Add-MenuItem $Menu 'Delete folder...' { Remove-DiagramItem $DgUI.Folders.MenuRow } $Glyph.Delete 'Del')
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Show in Explorer' { Start-Process explorer.exe (Get-DiagramRowPath $DgUI.Folders.MenuRow) } $Glyph.Open)
    } elseif ($Row) {
        [void](Add-MenuItem $Menu 'Open' { Open-DiagramFile $DgUI.Folders.MenuRow.Item.Path; Select-ApiTab $DgUI.Tabs 'Text' } $Glyph.Open 'Enter')
        [void](Add-MenuItem $Menu 'Duplicate' { Copy-DiagramItem $DgUI.Folders.MenuRow } $Glyph.Copy)
        [void](Add-MenuItem $Menu 'Rename...' { Rename-DiagramItem $DgUI.Folders.MenuRow } $Glyph.Edit 'F2')
        Add-DvMoveMenu $Menu $DgUI.Folders ([string]$Row.Item.Folder) '' { param($to) Move-DiagramItem $DgUI.Folders.MenuRow.Item.Path (Get-DiagramDirOf $to) }
        [void](Add-MenuItem $Menu 'Delete' { Remove-DiagramItem $DgUI.Folders.MenuRow } $Glyph.Delete 'Del')
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Show in Explorer' { Start-Process explorer.exe "/select,`"$($DgUI.Folders.MenuRow.Item.Path)`"" } $Glyph.Open)
    } else {
        [void](Add-MenuItem $Menu 'New diagram...' { $DgUI.Folders.SelectedFolder = ''; New-DiagramNamed } $Glyph.Add)
        [void](Add-MenuItem $Menu 'New folder...' { New-DiagramFolder '' } $Glyph.Folder)
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Show in Explorer' { Start-Process explorer.exe $DgDir } $Glyph.Open)
    }
}

# ---- edits from the canvas and the properties panel (all go through the text)
function Set-DiagramNodeAttr([string]$Id, [string]$Key, $Value) { Set-DiagramText ([DgText]::SetNodeAttr($DgUI.Text, $Id, $Key, $Value)) }
function Format-DiagramWords($Lines) { (@($Lines | Where-Object { $_ -ne '' } | ForEach-Object { '"' + ($_ -replace '"', "'") + '"' }) -join ' ') }

function Add-DiagramNode([float]$X, [float]$Y, [switch]$Text) {
    $pre = if ($Text) { 't' } else { 'n' }
    $i = 1; while ($DgUI.Doc.Find("$pre$i")) { $i++ }
    $id = "$pre$i"
    $line = if ($Text) { "${id}: Your text [shape text, at $([int]$X) $([int]$Y)]" } else { "${id}: New shape [at $([int]$X) $([int]$Y)]" }
    Set-DiagramText ([DgText]::AddLine($DgUI.Text, $line))
    $DgUI.Canvas.Select([string[]]@($id))
}

function Remove-DiagramSelection {
    $cv = $DgUI.Canvas
    $t = $DgUI.Text
    if ($cv.View.Selected.Count) { foreach ($id in @($cv.View.Selected)) { $t = [DgText]::RemoveNode($t, $id) } }
    elseif ($cv.View.SelectedEdge) {
        $e = $DgUI.Doc.Edges | Where-Object { $_.Id -eq $cv.View.SelectedEdge } | Select-Object -First 1
        if ($e -and $e.SrcLine -ge 0) { $t = [DgText]::RemoveLine($t, $e.SrcLine) }
    } else { return }
    Set-DiagramText $t
}

# after an edit the links are new objects: find the same link again (same ends and items) and select it
function Find-DiagramEdgeLike($Doc, $Edge) {
    $Doc.Edges | Where-Object { $_.From -eq $Edge.From -and $_.To -eq $Edge.To -and $_.FromItem -eq $Edge.FromItem -and $_.ToItem -eq $Edge.ToItem } | Select-Object -First 1
}
function Select-DiagramEdgeLike($Edge) {
    $ne = Find-DiagramEdgeLike $DgUI.Doc $Edge
    if ($ne) { $cv = $DgUI.Canvas; $cv.View.Selected.Clear(); $cv.View.SelectedEdge = $ne.Id; $cv.Invalidate(); Update-DiagramProps }
}

# ---- copy / paste between diagrams (the clipboard holds diagram text)
function Copy-DiagramSelection([switch]$Quiet) {
    $cv = $DgUI.Canvas
    $t = [DgClip]::Copy($DgUI.Doc, $cv.Theme, [string[]]@($cv.View.Selected))
    if (-not $t) { return '' }
    if (-not $Quiet) { try { [System.Windows.Forms.Clipboard]::SetText($t) } catch { } }
    $t
}
function Paste-DiagramClip([string]$Clip = '', [switch]$Offset) {
    if (-not $Clip) { try { $Clip = [System.Windows.Forms.Clipboard]::GetText() } catch { $Clip = '' } }
    if (-not $Clip.Trim()) { return }
    $cv = $DgUI.Canvas
    $x = [float]::NaN; $y = [float]::NaN
    if (-not $Offset) {
        if ($cv.MouseInside) { $x = $cv.MouseCanvas.X; $y = $cv.MouseCanvas.Y }
        else { $b = $DgUI.Doc.Bounds; $x = $b.Right + 40; $y = $b.Y + 40 }     # free space to the right
    }
    $new = [DgClip]::Paste($DgUI.Text, $DgUI.Doc, $Clip, $x, $y)
    if ($new -ceq $DgUI.Text) { return }
    Set-DiagramText $new
    $cv.Select([string[]]@([DgClip]::Pasted))
}
function Copy-DiagramDuplicate { $t = Copy-DiagramSelection -Quiet; if ($t) { Paste-DiagramClip $t -Offset } }

function Edit-DiagramLabel {
    $cv = $DgUI.Canvas
    $n = $DgUI.Doc.Find($cv.SelectedId)
    if (-not $n) { return }
    $tb = New-Object System.Windows.Forms.TextBox
    $tb.BorderStyle = 'FixedSingle'; $tb.BackColor = $C.Bg; $tb.ForeColor = $C.Fore; $tb.Font = $FontMain
    $tb.Text = $n.Title -replace "`n", ' '
    $x = ($n.X - $cv.Pan.X) * $cv.Zoom; $y = ($n.Y + $n.H / 2 - $cv.Pan.Y) * $cv.Zoom
    $tb.Width = [Math]::Max((Px 160), [int]($n.W * $cv.Zoom)); $tb.Location = New-Object System.Drawing.Point([int]$x, [int]($y - $tb.Height / 2))
    $tb.Tag = $n.Id
    $done = {
        param($src, $commit)
        if ($src.Tag -eq '') { return }
        $id = $src.Tag; $src.Tag = ''
        $v = $src.Text.Trim()
        $DgUI.Canvas.Controls.Remove($src); $src.Dispose()
        if ($commit -and $v) { Set-DiagramText ([DgText]::SetNodeLabel($DgUI.Text, $id, $v)) }
        $DgUI.Canvas.Focus()
    }
    $tb.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Enter') { $e.SuppressKeyPress = $true; & $done $src $true } elseif ($e.KeyCode -eq 'Escape') { $e.SuppressKeyPress = $true; & $done $src $false } }.GetNewClosure())
    $tb.add_LostFocus({ param($src, $e) & $done $src $true }.GetNewClosure())
    $cv.Controls.Add($tb); $tb.Focus(); $tb.SelectAll()
}

# ---- properties (right): the selected shape or link, or the whole diagram; in Preview: the details of a shape
function Add-DgProp($Panel, [string]$Label, $Control, [int]$Width = 250) {
    if ($Label) { $l = New-TbLabel $Panel $Label -Dim; $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, (Px 2)) }
    if ($Control) { if ($Control.Width -lt (Px 40) -or $Width -gt 0) { $Control.Width = Px ($Width * $TextZoom) }; $Panel.Controls.Add($Control) }
    $Control
}
function New-DgBox([string]$Text, [scriptblock]$OnChange, [switch]$Multi, [int]$Height = 0) {
    $b = New-TbBox -Multi:$Multi
    if ($Multi) { $b.ScrollBars = 'Vertical'; $b.AcceptsReturn = $true; $b.Height = Px $(if ($Height) { $Height } else { 70 }) }
    $b.Text = $Text
    $b.Tag = @{ On = $OnChange; Old = $Text }
    $b.add_Leave({ param($src, $e) if ($src.Text -cne $src.Tag.Old) { $src.Tag.Old = $src.Text; & $src.Tag.On $src.Text } })
    if (-not $Multi) { $b.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Enter') { $e.SuppressKeyPress = $true; if ($src.Text -cne $src.Tag.Old) { $src.Tag.Old = $src.Text; & $src.Tag.On $src.Text } } }) }
    $b
}
function New-DgCombo($Items, [string]$Value, [scriptblock]$OnChange, [switch]$Editable) {
    $cx = New-Object System.Windows.Forms.ComboBox
    $cx.DropDownStyle = if ($Editable) { 'DropDown' } else { 'DropDownList' }; $cx.FlatStyle = 'Flat'; $cx.BackColor = $C.Bg; $cx.ForeColor = $C.Fore
    foreach ($i in $Items) { [void]$cx.Items.Add($i) }
    $cx.Text = $Value; if (-not $Editable) { $k = $cx.Items.IndexOf($Value); if ($k -ge 0) { $cx.SelectedIndex = $k } }
    $cx.Tag = @{ On = $OnChange; Ready = $true }
    $cx.add_SelectionChangeCommitted({ param($src, $e) & $src.Tag.On ([string]$src.SelectedItem) })
    if ($Editable) { $cx.add_Leave({ param($src, $e) if ($src.Text -and -not $src.Items.Contains($src.Text)) { & $src.Tag.On $src.Text } }) }
    $cx
}
function New-DgColorButton($Parent, [string]$Label, [string]$Value, [scriptblock]$OnChange) {
    $b = New-Button $(if ($Value) { "$Label  $Value" } else { "$Label  (auto)" }) 'Pick a colour (right-click: back to automatic)' {
        param($src, $e)
        $dlg = New-Object System.Windows.Forms.ColorDialog; $dlg.FullOpen = $true
        if ($src.Tag.Value) { $dlg.Color = [DgColors]::Parse($src.Tag.Value) }
        $script:Modal = $true
        try { if ($dlg.ShowDialog($DgUI.Form) -eq 'OK') { $hex = '#' + $dlg.Color.R.ToString('x2') + $dlg.Color.G.ToString('x2') + $dlg.Color.B.ToString('x2'); & $src.Tag.On $hex } } finally { $script:Modal = $false; $dlg.Dispose() }
    } $Parent $Glyph.Color 2
    $b.Tag = @{ Value = $Value; On = $OnChange }
    $b.add_MouseUp({ param($src, $e) if ($e.Button -eq 'Right') { & $src.Tag.On $null } })
    $b
}

function Update-DiagramProps {
    $p = $DgUI.Props
    if (-not $p -or $DgUI.PropsBusy) { return }
    $cv = $DgUI.Canvas; $d = $DgUI.Doc
    $p.SuspendLayout()
    foreach ($ctl in @($p.Controls)) { $p.Controls.Remove($ctl); $ctl.Dispose() }
    $cats = @($d.Cats | ForEach-Object { $_.Id })
    $node = if ($cv.View.Selected.Count -eq 1) { $d.Find(@($cv.View.Selected)[0]) } else { $null }
    $edge = if ($cv.View.SelectedEdge) { $d.Edges | Where-Object { $_.Id -eq $cv.View.SelectedEdge } | Select-Object -First 1 } else { $null }
    if (-not $cv.Editable -and $node) { Show-DiagramDetails $p $node }
    elseif ($node) {
        $id = $node.Id
        New-TbLabel $p "Shape  $id" -Title | Out-Null
        Add-DgProp $p 'Title' (New-DgBox $node.Label { param($v) Set-DiagramText ([DgText]::SetNodeLabel($DgUI.Text, $DgUI.PropId, $v)) }) | Out-Null
        Add-DgProp $p 'Badge (short code on the card)' (New-DgBox $node.Badge { param($v) Set-DiagramNodeAttr $DgUI.PropId 'badge' $(if ($v) { $v } else { $null }) }) 140 | Out-Null
        Add-DgProp $p 'Category (colour; type a new name to add one)' (New-DgCombo (@('(none)') + $cats) $(if ($node.Cat) { $node.Cat } else { '(none)' }) { param($v) Set-DiagramNodeAttr $DgUI.PropId 'cat' $(if ($v -and $v -ne '(none)') { $v -replace '\W', '' } else { $null }) } -Editable) | Out-Null
        $shapes = @('auto', 'card', 'rounded', 'rect', 'pill', 'circle', 'diamond', 'hexagon', 'parallelogram', 'cylinder', 'doc', 'note', 'actor', 'table', 'text')
        Add-DgProp $p 'Shape' (New-DgCombo $shapes $(if ($node.Shape) { $node.Shape } else { 'auto' }) { param($v) Set-DiagramNodeAttr $DgUI.PropId 'shape' $(if ($v -ne 'auto') { $v } else { $null }) }) 160 | Out-Null
        if ($d.LaneMode) {
            $lanes = @('auto') + @(for ($i = 0; $i -lt [Math]::Max($d.Lanes.Count, 1); $i++) { "$($i + 1)  $(if ($i -lt $d.Lanes.Count) { $d.Lanes[$i] })" })
            Add-DgProp $p 'Lane (column)' (New-DgCombo $lanes $(if ($node.Lane -ge 0) { $lanes[$node.Lane + 1] } else { 'auto' }) { param($v) Set-DiagramNodeAttr $DgUI.PropId 'lane' $(if ($v -ne 'auto') { ($v -split ' ')[0] } else { $null }) }) 200 | Out-Null
        }
        Add-DgProp $p 'Status dot' (New-DgCombo @('none', 'ok', 'warn', 'down') $(if ($node.Status) { $node.Status } else { 'none' }) { param($v) Set-DiagramNodeAttr $DgUI.PropId 'status' $(if ($v -ne 'none') { $v } else { $null }) }) 120 | Out-Null
        $sp = New-CheckBox $p 'Sparkline (live traffic graph)' $node.Spark; $sp.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
        $sp.add_CheckedChanged({ param($src, $e) Set-DiagramNodeAttr $DgUI.PropId 'spark' $(if ($src.Checked) { '' } else { $null }) })
        Add-DgProp $p 'Text lines under the title (one per line)' (New-DgBox (@($node.Lines) -join "`r`n") { param($v) $w = Format-DiagramWords ($v -split "`r?`n"); Set-DiagramText ([DgText]::SetNodeKey($DgUI.Text, $DgUI.PropId, 'lines', $(if ($w) { $w } else { $null }))) } -Multi -Height 54) | Out-Null
        Add-DgProp $p 'Items inside (one per line; link to them as id.1, id.2 ...)' (New-DgBox (@($node.Items) -join "`r`n") { param($v) $w = Format-DiagramWords ($v -split "`r?`n"); Set-DiagramText ([DgText]::SetNodeKey($DgUI.Text, $DgUI.PropId, 'items', $(if ($w) { $w } else { $null }))) } -Multi -Height 54) | Out-Null
        Add-DgProp $p 'Description (shown when the shape is clicked)' (New-DgBox $node.Desc { param($v) Set-DiagramText ([DgText]::SetNodeKey($DgUI.Text, $DgUI.PropId, 'desc', $(if ($v.Trim()) { '"' + (($v -replace '"', "'") -replace "`r?`n", ' ') + '"' } else { $null }))) } -Multi -Height 64) | Out-Null
        Add-DgProp $p 'Tags (comma separated)' (New-DgBox (@($node.Tags) -join ', ') { param($v) $w = (@($v -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) -join '; '); Set-DiagramText ([DgText]::SetNodeKey($DgUI.Text, $DgUI.PropId, 'tags', $(if ($w) { $w } else { $null }))) }) | Out-Null
        Add-DgProp $p 'Link (opens when clicked in the web page)' (New-DgBox $node.Url { param($v) Set-DiagramText ([DgText]::SetNodeKey($DgUI.Text, $DgUI.PropId, 'url', $(if ($v) { '"' + $v + '"' } else { $null }))) }) | Out-Null
        $gb = New-CheckBox $p 'Open website button on hover (web page)' ($node.Button.Length -gt 0); $gb.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), 0, 0)
        $gb.add_CheckedChanged({ param($src, $e) Set-DiagramNodeAttr $DgUI.PropId 'button' $(if ($src.Checked) { '' } else { $null }) })
        $row = New-Object System.Windows.Forms.FlowLayoutPanel; $row.AutoSize = $true; $row.WrapContents = $true; $row.MaximumSize = New-Object System.Drawing.Size((Px (260 * $TextZoom)), 0); $row.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
        [void](New-DgColorButton $row 'Fill' $node.Fill { param($v) Set-DiagramNodeAttr $DgUI.PropId 'fill' $v })
        [void](New-DgColorButton $row 'Border' $node.Stroke { param($v) Set-DiagramNodeAttr $DgUI.PropId 'stroke' $v })
        [void](New-DgColorButton $row 'Text' $node.TextColor { param($v) Set-DiagramNodeAttr $DgUI.PropId 'color' $v })
        $p.Controls.Add($row)
        $b2 = New-Object System.Windows.Forms.FlowLayoutPanel; $b2.AutoSize = $true; $b2.WrapContents = $true; $b2.MaximumSize = New-Object System.Drawing.Size((Px (260 * $TextZoom)), 0); $b2.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
        [void](New-Button 'Auto position' 'Let the layout place it again' { Set-DiagramNodeAttr $DgUI.PropId 'at' $null } $b2 $Glyph.Refresh 2)
        [void](New-Button 'Delete' 'Delete this shape and its links (Del)' { Remove-DiagramSelection } $b2 $Glyph.Delete 2)
        $p.Controls.Add($b2)
        $DgUI.PropId = $id
    } elseif ($edge) {
        $DgUI.PropLine = $edge.SrcLine
        New-TbLabel $p 'Link' -Title | Out-Null
        $fromN = $d.Find($edge.From); $toN = $d.Find($edge.To)
        New-TbLabel $p "$($fromN.Title)$(if ($edge.FromItem) { " ($($edge.FromItem))" })  ->  $($toN.Title)$(if ($edge.ToItem) { " ($($edge.ToItem))" })" -Dim | Out-Null
        $DgUI.PropEdge = $edge
        $setE = { param($k, $v) $pe = $DgUI.PropEdge; Set-DiagramText ([DgText]::EdgeSetAttr($DgUI.Text, $DgUI.Doc, $pe, $k, $v)); Select-DiagramEdgeLike $pe }
        $DgUI.SetEdge = $setE
        Add-DgProp $p 'Label' (New-DgBox $edge.Label { param($v) & $DgUI.SetEdge 'label' $(if ($v) { '"' + ($v -replace '"', "'") + '"' } else { $null }) }) | Out-Null
        Add-DgProp $p 'Category / flow (colour)' (New-DgCombo (@('(none)') + $cats) $(if ($edge.Cat) { $edge.Cat } else { '(none)' }) { param($v) & $DgUI.SetEdge 'cat' $(if ($v -and $v -ne '(none)') { $v -replace '\W', '' } else { $null }) } -Editable) | Out-Null
        Add-DgProp $p 'Line' (New-DgCombo @('solid', 'dashed', 'dotted') @('solid', 'dashed', 'dotted')[$edge.Dash] { param($v) & $DgUI.SetEdge 'dashed' $null; foreach ($k in 'dotted', 'solid') { & $DgUI.SetEdge $k $null }; if ($v -ne 'solid') { & $DgUI.SetEdge $v '' } }) 120 | Out-Null
        Add-DgProp $p 'Route' (New-DgCombo @('auto', 'ortho', 'curve', 'straight') $(if ($edge.Route) { $edge.Route } else { 'auto' }) { param($v) & $DgUI.SetEdge 'route' $(if ($v -ne 'auto') { $v } else { $null }) }) 120 | Out-Null
        Add-DgProp $p 'Arrows' (New-DgCombo @('auto', 'end', 'both', 'start', 'none') $(if ($edge.ArrowAttr) { if ($edge.ArrowStart -and $edge.ArrowEnd) { 'both' } elseif ($edge.ArrowStart) { 'start' } elseif ($edge.ArrowEnd) { 'end' } else { 'none' } } else { 'auto' }) { param($v) & $DgUI.SetEdge 'noarrow' $null; & $DgUI.SetEdge 'arrow' $(if ($v -ne 'auto') { $v } else { $null }) }) 120 | Out-Null
        $sides = @('auto', 'left', 'right', 'top', 'bottom')
        Add-DgProp $p 'Starts at the side' (New-DgCombo $sides $(if ($edge.FromSide) { $edge.FromSide } else { 'auto' }) { param($v) & $DgUI.SetEdge 'from' $(if ($v -ne 'auto') { $v } else { $null }) }) 120 | Out-Null
        Add-DgProp $p 'Ends at the side' (New-DgCombo $sides $(if ($edge.ToSide) { $edge.ToSide } else { 'auto' }) { param($v) & $DgUI.SetEdge 'to' $(if ($v -ne 'auto') { $v } else { $null }) }) 120 | Out-Null
        New-TbLabel $p 'Or drag the blue dots at its ends to any point on any side of the cards; drag the link itself to move its bend.' -Dim | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 250), 0) }
        $an = New-CheckBox $p 'Animated: packets flow along it' $edge.Animate; $an.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0)
        $an.add_CheckedChanged({ param($src, $e) & $DgUI.SetEdge 'animate' $(if ($src.Checked) { '' } else { $null }) })
        $bo = New-CheckBox $p 'Both ways' $edge.Both; $bo.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, 0)
        $bo.add_CheckedChanged({ param($src, $e) & $DgUI.SetEdge 'both' $(if ($src.Checked) { '' } else { $null }) })
        $row = New-Object System.Windows.Forms.FlowLayoutPanel; $row.AutoSize = $true; $row.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
        [void](New-DgColorButton $row 'Colour' $edge.Color { param($v) & $DgUI.SetEdge 'color' $v })
        [void](New-Button 'Delete' 'Delete this link (its whole line in the text)' { Remove-DiagramSelection } $row $Glyph.Delete 2)
        if (-not [float]::IsNaN($edge.LabelAt.X)) { [void](New-Button 'Label back' 'Put the label back in the middle of the link' { & $DgUI.SetEdge 'labelat' $null } $row $Glyph.Refresh 2) }
        if ($edge.Via.Count -or $edge.FromSide -or $edge.ToSide) { [void](New-Button 'Reset route' 'Automatic route and ends again' { $pe = $DgUI.PropEdge; $t = $DgUI.Text; foreach ($k in 'via', 'from', 'to') { $t = [DgText]::EdgeSetAttr($t, [DgText]::Parse($t), (Find-DiagramEdgeLike ([DgText]::Parse($t)) $pe), $k, $null) }; Set-DiagramText $t; Select-DiagramEdgeLike $pe } $row $Glyph.Refresh 2) }
        $p.Controls.Add($row)

    } else {
        New-TbLabel $p 'Diagram' -Title | Out-Null
        Add-DgProp $p 'Title' (New-DgBox $d.Title { param($v) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'title', $(if ($v) { $v } else { $null }))) }) | Out-Null
        Add-DgProp $p 'Theme' (New-DgCombo ([DgTheme]::Names) $d.Theme { param($v) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'theme', "$v $($DgUI.Doc.Mode)")) }) 160 | Out-Null
        $starts = @('Dark', 'Light', "Visitor's system setting")
        Add-DgProp $p 'Starts in' (New-DgCombo $starts $starts[[Math]::Max(0, @('dark', 'light', 'auto').IndexOf($d.Mode))] { param($v) $DgUI.ModeSet = $false; Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'theme', "$($DgUI.Doc.Theme) $(@('dark', 'light', 'auto')[[Array]::IndexOf(@('Dark', 'Light', "Visitor's system setting"), $v)])")) }) 160 | Out-Null
        $layouts = @('auto', 'lanes', 'layered', 'grid', 'circle', 'force')
        Add-DgProp $p 'Layout' (New-DgCombo $layouts $(if ($d.Layout) { $d.Layout } else { 'auto' }) { param($v) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'layout', $(if ($v -ne 'auto') { $v } else { $null }))) -Fit }) 160 | Out-Null
        Add-DgProp $p 'Direction' (New-DgCombo @('LR  left to right', 'TB  top to bottom', 'RL  right to left', 'BT  bottom to top') $(switch ($d.Direction) { 'TB' { 'TB  top to bottom' } 'RL' { 'RL  right to left' } 'BT' { 'BT  bottom to top' } default { 'LR  left to right' } }) { param($v) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'direction', ($v -split ' ')[0])) -Fit }) 160 | Out-Null
        Add-DgProp $p 'Links' (New-DgCombo @('ortho', 'curve', 'straight') $(if ($d.Route) { $d.Route } else { 'ortho' }) { param($v) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'route', $(if ($v -ne 'ortho') { $v } else { $null }))) }) 120 | Out-Null
        $sn = New-TbNumber $p ([int]($d.Spacing * 100)) 40 400; Add-DgProp $p 'Spacing %' $null | Out-Null; $p.Controls.SetChildIndex($sn, $p.Controls.Count - 1)
        $sn.add_ValueChanged({ param($src, $e) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'spacing', $(if ($src.Value -ne 100) { ([double]$src.Value / 100).ToString([Globalization.CultureInfo]::InvariantCulture) } else { $null }))) })
        $rn = New-TbNumber $p ([int]$d.Radius) 0 40; Add-DgProp $p 'Corner radius' $null | Out-Null; $p.Controls.SetChildIndex($rn, $p.Controls.Count - 1)
        $rn.add_ValueChanged({ param($src, $e) Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'radius', $(if ($src.Value -ne 10) { [string]$src.Value } else { $null }))) })
        foreach ($feat in @(@('header', 'Title and totals at the top'), @('legend', 'Legend (click a flow to hide it)'), @('grid', 'Dotted background'))) {
            $cb = New-CheckBox $p $feat[1] (-not $d.Off.Contains($feat[0])); $cb.Tag = $feat[0]; $cb.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), 0, 0)
            $cb.add_CheckedChanged({ param($src, $e) $off = @($DgUI.Doc.Off | Where-Object { $_ -ne $src.Tag }); if (-not $src.Checked) { $off += $src.Tag }; Set-DiagramText ([DgText]::SetDirective($DgUI.Text, 'hide', $(if ($off) { $off -join ' ' } else { $null }))) })
        }
        if (@($d.Cats).Count) {
            New-TbLabel $p 'Categories: light / dark colour' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 12), 0, (Px 2)) }
            $cl = New-Object DgColors($d, $DgUI.Canvas.Theme, $false, $false); $cdk = New-Object DgColors($d, $DgUI.Canvas.Theme, $true, $false)
            foreach ($k in $d.Cats) {
                $row = New-Object System.Windows.Forms.FlowLayoutPanel; $row.AutoSize = $true; $row.WrapContents = $false; $row.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), 0, 0)
                $nm = New-TbLabel $row $k.Name; $nm.Width = Px 90; $nm.AutoSize = $false; $nm.Height = $FontMain.Height + (Px 8)
                foreach ($dark in $false, $true) {
                    $hex = if ($dark) { $cdk.Raw("c:$($k.Id)") } else { $cl.Raw("c:$($k.Id)") }
                    $sw = New-Object System.Windows.Forms.Panel; $sw.Size = New-Object System.Drawing.Size((Px 26), (Px 20)); $sw.BackColor = [DgColors]::Parse($hex); $sw.Cursor = 'Hand'; $sw.Margin = New-Object System.Windows.Forms.Padding((Px 4), (Px 2), 0, 0)
                    $sw.Tag = @{ Id = $k.Id; Name = $k.Name; Dark = $dark; L = $cl.Raw("c:$($k.Id)"); D = $cdk.Raw("c:$($k.Id)") }
                    $tooltip.SetToolTip($sw, $(if ($dark) { 'Colour in the dark theme' } else { 'Colour in the light theme' }))
                    $sw.add_Click({
                        param($src, $e)
                        $dlg = New-Object System.Windows.Forms.ColorDialog; $dlg.FullOpen = $true; $dlg.Color = $src.BackColor
                        $script:Modal = $true
                        try {
                            if ($dlg.ShowDialog($DgUI.Form) -eq 'OK') {
                                $hx = '#' + $dlg.Color.R.ToString('x2') + $dlg.Color.G.ToString('x2') + $dlg.Color.B.ToString('x2')
                                $tg = $src.Tag; $l = if ($tg.Dark) { $tg.L } else { $hx }; $dk = if ($tg.Dark) { $hx } else { $tg.D }
                                Set-DiagramText ([DgText]::SetCategory($DgUI.Text, $tg.Id, $tg.Name, $l, $dk))
                            }
                        } finally { $script:Modal = $false; $dlg.Dispose() }
                    })
                    $row.Controls.Add($sw)
                }
                $p.Controls.Add($row)
            }
        }
        New-TbLabel $p "Tips: drag shapes to move them; drag from a shape's dot to another shape to link them; double-click a shape to rename it; right-click for more. Shift+drag selects several; click inside a group's frame to select (and drag) the whole group. Ctrl+C / Ctrl+V copy shapes and groups into any other diagram; Ctrl+D duplicates." -Dim | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 250), 0); $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 14), 0, 0) }
    }
    Set-ControlTheme $p $null $script:IsDark
    $p.ResumeLayout()
}

# Preview mode: what the web page shows when a shape is clicked.
function Show-DiagramDetails($P, $Node) {
    $d = $DgUI.Doc; $cv = $DgUI.Canvas
    $DgUI.PropId = $Node.Id
    $cat = $d.FindCat($Node.Cat)
    $cn = if ($cat -and $cat.Name -ne $Node.Badge) { $cat.Name.ToUpper() } else { '' }
    $hd = New-TbLabel $P (@($Node.Badge, $cn) -join '   ').Trim() -Dim
    New-TbLabel $P $Node.Title -Title | Out-Null
    if ($Node.Desc) { New-TbLabel $P $Node.Desc | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 250), 0); $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), 0, (Px 4)) } }
    if (@($Node.Tags).Count) { New-TbLabel $P ((@($Node.Tags) | ForEach-Object { "[$_]" }) -join '  ') -Dim | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 250), 0) } }
    $ins = @($d.Edges | Where-Object { $_.To -eq $Node.Id -and $_.From -ne $Node.Id } | ForEach-Object { $d.Find($_.From).Title } | Select-Object -Unique)
    $outs = @($d.Edges | Where-Object { $_.From -eq $Node.Id -and $_.To -ne $Node.Id } | ForEach-Object { $d.Find($_.To).Title } | Select-Object -Unique)
    New-TbLabel $P 'Receives from' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0) }
    New-TbLabel $P $(if ($ins) { $ins -join ', ' } else { '-' }) | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 250), 0) }
    New-TbLabel $P 'Sends to' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0) }
    New-TbLabel $P $(if ($outs) { $outs -join ', ' } else { '-' }) | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 250), 0) }
    $isDown = $cv.View.Down.Contains($Node.Id)
    $st = New-TbLabel $P $(if ($isDown) { 'DOWN (simulated outage)' } else { 'Operational' })
    $st.ForeColor = if ($isDown) { $C.Red } else { $C.Green }; $st.Margin = New-Object System.Windows.Forms.Padding(0, (Px 12), 0, (Px 4))
    [void](New-Button $(if ($isDown) { 'End outage' } else { 'Simulate outage' }) 'Stop the traffic from this shape (only in the preview)' {
        $id = $DgUI.PropId; $v = $DgUI.Canvas.View
        if ($v.Down.Contains($id)) { [void]$v.Down.Remove($id) } else { [void]$v.Down.Add($id) }
        $DgUI.Canvas.Invalidate(); Update-DiagramProps
    } $P $Glyph.Pause 2)
}

# ---- export: picture, PNG, SVG code
function Save-DiagramPng([float]$Scale) {
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = 'PNG picture|*.png'; $d.FileName = "$(if ($DgUI.Doc.Title) { $DgUI.Doc.Title } else { 'diagram' }).png" -replace '[\\/:*?"<>|]', '_'
    $script:Modal = $true
    try { if ($d.ShowDialog($DgUI.Form) -ne 'OK') { return }; $path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    $bmp = $DgUI.Canvas.RenderBitmap($Scale, (-not $DgUI.Transparent), $DgUI.Canvas.Dark)
    try { $bmp.Save($path, [System.Drawing.Imaging.ImageFormat]::Png) } finally { $bmp.Dispose() }
    try { [DgImport]::PngAddText($path, 'devtools-diagram', [DgImport]::Marker($DgUI.Text)) } catch { }      # so Import gets the diagram back from the picture
}

function Show-DiagramCode([string]$Kind = 'page') {
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Diagram code'; $f.Icon = $IconActive; $f.StartPosition = 'CenterParent'
    $f.Size = New-Object System.Drawing.Size((Px 1100), (Px 760)); $f.BackColor = $C.Panel; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $f.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Escape') { $src.Close() } })
    $st = @{ Form = $f; Ready = $false }
    $opt = New-Object System.Windows.Forms.FlowLayoutPanel
    $opt.Dock = 'Top'; $opt.AutoSize = $true; $opt.WrapContents = $true; $opt.BackColor = $C.Panel; $opt.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 8), (Px 10), (Px 6))
    New-TbLabel $opt 'Output' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 9), (Px 4), 0) }
    $kinds = @('Interactive web page', 'Embeddable widget (paste into a page)', 'React component', 'Plain SVG')
    $st.Kind = New-TbCombo $opt $kinds 270
    $st.Kind.SelectedIndex = [Math]::Max(0, @('page', 'widget', 'react', 'svg').IndexOf($Kind))
    New-TbLabel $opt 'Starts in' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 9), (Px 4), 0) }
    $st.Mode = New-TbCombo $opt @("Visitor's system setting", 'Dark', 'Light') 190
    $st.Mode.SelectedIndex = [Math]::Max(0, @('auto', 'dark', 'light').IndexOf($DgUI.Doc.Mode))
    $tooltip.SetToolTip($st.Mode, 'The look the page opens in. Visitors can still switch with Dark / Light, and their choice is remembered until you pick a different start here')
    New-TbLabel $opt 'Prefix' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 9), (Px 4), 0) }
    $st.Prefix = New-TbBox -Mono; $st.Prefix.Width = Px 140; $st.Prefix.Text = [DgSvg]::SuggestPrefix($DgUI.Doc); $st.Prefix.Margin = New-Object System.Windows.Forms.Padding(0, (Px 5), (Px 8), 0)
    $tooltip.SetToolTip($st.Prefix, 'Every class and id starts with this, so several diagrams can sit on the same page without clashing')
    $opt.Controls.Add($st.Prefix)
    $st.HLabel = New-TbLabel $opt 'Height' -Dim; $st.HLabel.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 9), (Px 4), 0)
    $st.Height = New-TbBox -Mono; $st.Height.Width = Px 80; $st.Height.Text = '640px'; $st.Height.Margin = New-Object System.Windows.Forms.Padding(0, (Px 5), 0, 0)
    $opt.Controls.Add($st.Height)
    # interactive options
    $io = New-Object System.Windows.Forms.FlowLayoutPanel; $io.AutoSize = $true; $io.WrapContents = $true; $io.BackColor = $C.Panel; $io.MaximumSize = New-Object System.Drawing.Size((Px 1060), 0)
    $st.Feat = [ordered]@{}
    foreach ($ft in @(@('Header', 'Title and live totals'), @('Flows', 'Flowing packets, pause and speed'), @('ThemeSwitch', 'Dark / light switch'), @('Zoom', 'Zoom and fit buttons'), @('Legend', 'Legend (hide flows)'),
                      @('Panel', 'Details panel on click'), @('Hover', 'Hover dimming'), @('Outage', 'Simulate outage'), @('Hint', 'Hint text'), @('Glow', 'Glow on packets'), @('WebFont', 'Load the font from Google Fonts (needs internet)'))) {
        $cb = New-CheckBox $io $ft[1] ($ft[0] -ne 'WebFont'); $st.Feat[$ft[0]] = $cb      # pages work offline unless asked
    }
    $opt.Controls.Add($io); $opt.SetFlowBreak($st.Height, $true)
    $st.IO = $io
    # plain SVG options
    $so = New-Object System.Windows.Forms.FlowLayoutPanel; $so.AutoSize = $true; $so.WrapContents = $true; $so.BackColor = $C.Panel
    $st.Vars = New-CheckBox $so 'Colours as CSS variables' $true
    $st.Bg = New-CheckBox $so 'Background' $true
    $st.Resp = New-CheckBox $so 'Scales to its container' $true
    $st.Acc = New-CheckBox $so 'Title and description (accessibility)' $true
    $st.Hover = New-CheckBox $so 'Hover highlight' $true
    $st.Draw = New-CheckBox $so 'Draw-in animation' $false
    $st.Min = New-CheckBox $so 'Minified' $false
    $opt.Controls.Add($so)
    $st.SO = $so
    $bar = New-Object System.Windows.Forms.FlowLayoutPanel
    $bar.Dock = 'Bottom'; $bar.AutoSize = $true; $bar.BackColor = $C.Panel; $bar.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 6), (Px 10), (Px 8))
    $code = New-TbRtb -ReadOnly; $code.Dock = 'Fill'; $code.WordWrap = $false
    $st.Code = $code
    $f.Controls.Add($code); $f.Controls.Add($opt); $f.Controls.Add($bar)
    $f.Tag = $st
    $st.Make = {
        param($s)
        $kind = @('page', 'widget', 'react', 'svg')[$s.Kind.SelectedIndex]
        $mode = @('auto', 'dark', 'light')[$s.Mode.SelectedIndex]
        if ($kind -eq 'svg') {
            $o = New-Object DgSvgOptions
            $o.Vars = $s.Vars.Checked; $o.Background = $s.Bg.Checked; $o.Responsive = $s.Resp.Checked; $o.Accessible = $s.Acc.Checked
            $o.Hover = $s.Hover.Checked; $o.DrawIn = $s.Draw.Checked; $o.Pretty = -not $s.Min.Checked; $o.Prefix = $s.Prefix.Text
            $o.Mode = $mode
            if (-not $o.Vars -and $o.Mode -eq 'auto') { $o.Mode = if ($DgUI.Canvas.Dark) { 'dark' } else { 'light' } }
            return (Add-DiagramSource ([DgSvg]::Document($DgUI.Doc, $DgUI.Canvas.Theme, $o)) 'svg')
        }
        $o = New-Object DgHtmlOptions
        $o.Kind = $kind; $o.Prefix = $s.Prefix.Text; $o.Mode = $mode
        if ($kind -ne 'page') { $o.Height = $s.Height.Text.Trim() }
        foreach ($k in $s.Feat.Keys) { $o.$k = $s.Feat[$k].Checked }
        Add-DiagramSource ([DgHtml]::Build($DgUI.Doc, $DgUI.Canvas.Theme, $o)) $kind
    }
    $st.Refresh = {
        param($s)
        if (-not $s.Ready) { return }
        $kind = @('page', 'widget', 'react', 'svg')[$s.Kind.SelectedIndex]
        $s.IO.Visible = $kind -ne 'svg'; $s.SO.Visible = $kind -eq 'svg'
        $s.Height.Visible = $kind -eq 'widget' -or $kind -eq 'react'; $s.HLabel.Visible = $s.Height.Visible
        $s.OpenBtn.Enabled = $kind -ne 'react'
        try { $t = & $s.Make $s } catch { $t = "Couldn't make it: $($_.Exception.Message)" }
        $s.Text = $t
        $lang = if ($kind -eq 'react') { 'js' } elseif ($kind -eq 'svg') { 'svg' } else { 'html' }
        Set-RtbCode $s.Code $(if ($t.Length -gt 150000) { $t.Substring(0, 150000) + "`n... (copy or save to get all of it)" } else { $t }) $lang
        $s.Info.Text = "$([Math]::Round($t.Length / 1KB, 1)) KB" + $(switch ($kind) { 'page' { '  -  a complete page: save it and open it, or put it on any web server' } 'widget' { '  -  paste into any page; give each diagram its own prefix' } 'react' { '  -  save as a .jsx file; props: theme, onSelect' } default { '' } })
    }
    [void](New-Button 'Copy' 'Copy the code' { $s = $this.FindForm().Tag; [System.Windows.Forms.Clipboard]::SetText($s.Text); $s.Info.Text = 'Copied.' } $bar $Glyph.Copy 1)
    [void](New-Button 'Save...' 'Save as a file' {
        $s = $this.FindForm().Tag
        $kind = @('page', 'widget', 'react', 'svg')[$s.Kind.SelectedIndex]
        $ext = @{ page = 'html'; widget = 'html'; react = 'jsx'; svg = 'svg' }[$kind]
        $base = $(if ($DgUI.Doc.Title) { $DgUI.Doc.Title } else { 'diagram' }) -replace '[\\/:*?"<>|]', '_'
        $dd = New-Object System.Windows.Forms.SaveFileDialog; $dd.Filter = "$($ext.ToUpper()) file|*.$ext"; $dd.FileName = "$base.$ext"
        $script:Modal = $true
        try { if ($dd.ShowDialog($s.Form) -eq 'OK') { [IO.File]::WriteAllText($dd.FileName, $s.Text, (New-Object System.Text.UTF8Encoding $false)); $s.Info.Text = "Saved $(Split-Path -Leaf $dd.FileName)." } } finally { $script:Modal = $false; $dd.Dispose() }
    } $bar $Glyph.Save 2)
    $st.OpenBtn = New-Button 'Open in browser' 'See it in your web browser (a temporary file on this PC)' {
        $s = $this.FindForm().Tag
        $kind = @('page', 'widget', 'react', 'svg')[$s.Kind.SelectedIndex]
        $tmp = Join-Path ([IO.Path]::GetTempPath()) ('devtools-diagram-' + [guid]::NewGuid().ToString('N').Substring(0, 8) + '.html')
        $page = if ($kind -eq 'page') { $s.Text } else { "<!doctype html><html><head><meta charset=""utf-8""><title>Diagram</title><style>html,body{margin:0;background:#8a8f99}body{padding:16px}</style></head><body>`n" + $s.Text + "`n</body></html>" }
        [IO.File]::WriteAllText($tmp, $page, (New-Object System.Text.UTF8Encoding $false))
        Start-Process $tmp
    } $bar $Glyph.Open 2
    $st.Info = New-TbLabel $bar '' -Dim
    $st.Info.Margin = New-Object System.Windows.Forms.Padding((Px 10), (Px 8), 0, 0)
    $st.Timer = New-TbDebounce 300 { $fm = [System.Windows.Forms.Form]::ActiveForm; if ($fm -and $fm.Tag -is [hashtable] -and $fm.Tag.Refresh) { & $fm.Tag.Refresh $fm.Tag } }
    foreach ($ctl in @($st.Kind, $st.Mode)) { $ctl.add_SelectedIndexChanged({ param($src, $e) $s = $src.FindForm().Tag; & $s.Refresh $s }) }
    foreach ($ctl in @($st.Prefix, $st.Height)) { $ctl.add_TextChanged({ param($src, $e) $s = $src.FindForm().Tag; $s.Timer.Stop(); $s.Timer.Start() }) }
    foreach ($ctl in @($st.Vars, $st.Bg, $st.Resp, $st.Acc, $st.Hover, $st.Draw, $st.Min) + @($st.Feat.Values)) { $ctl.add_CheckedChanged({ param($src, $e) $s = $src.FindForm().Tag; & $s.Refresh $s }) }
    Register-ThemedWindow $f
    $st.Ready = $true
    & $st.Refresh $st
    $script:Modal = $true
    try { [void]$f.ShowDialog($DgUI.Form) } finally { $script:Modal = $false; $st.Timer.Dispose(); $f.Dispose() }
}

function Show-DiagramExportMenu($Anchor) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $m 'Copy as picture' { $b = $DgUI.Canvas.RenderBitmap(2, $true, $DgUI.Canvas.Dark); try { Set-ClipboardImage $b } finally { $b.Dispose() } } $Glyph.Copy)
    [void](Add-MenuItem $m 'Save PNG (1x)...' { Save-DiagramPng 1 } $Glyph.Photo)
    [void](Add-MenuItem $m 'Save PNG (2x, sharp)...' { Save-DiagramPng 2 } $Glyph.Photo)
    [void](Add-MenuItem $m 'Save PNG (3x, print)...' { Save-DiagramPng 3 } $Glyph.Photo)
    $tp = Add-MenuItem $m 'Transparent PNG background' { $DgUI.Transparent = -not $DgUI.Transparent }
    $tp.Checked = [bool]$DgUI.Transparent
    [void]$m.Items.Add('-')
    [void](Add-MenuItem $m 'Interactive web page...' { Show-DiagramCode 'page' } $Glyph.Code)
    [void](Add-MenuItem $m 'Embeddable widget...' { Show-DiagramCode 'widget' } $Glyph.Code)
    [void](Add-MenuItem $m 'React component...' { Show-DiagramCode 'react' } $Glyph.Code)
    [void](Add-MenuItem $m 'SVG code...' { Show-DiagramCode 'svg' } $Glyph.Code)
    $m.Show($Anchor, (New-Object System.Drawing.Point(0, $Anchor.Height)))
}

function Show-DiagramExamplesMenu($Anchor) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $subs = @{}
    foreach ($k in (Get-DiagramExamples).Keys) {
        $grp, $name = $k -split '/', 2
        if (-not $subs[$grp]) { $subs[$grp] = New-Object System.Windows.Forms.ToolStripMenuItem($grp, (New-GlyphImage $Glyph.Apps)); [void]$m.Items.Add($subs[$grp]) }
        $it = New-Object System.Windows.Forms.ToolStripMenuItem($name, $null, { param($src, $e) New-DiagramFromText ($src.Tag -split '/', 2)[1] ((Get-DiagramExamples)[$src.Tag]) })
        $it.Tag = $k
        [void]$subs[$grp].DropDownItems.Add($it)
    }
    $m.Show($Anchor, (New-Object System.Drawing.Point(0, $Anchor.Height)))
}

function Show-DiagramStudio([string]$Text = '') {
    Hide-Picker
    if (-not (Initialize-Diagrams)) { return }
    if ($DgUI.Form) {
        if ($DgUI.Form.WindowState -eq 'Minimized') { $DgUI.Form.WindowState = 'Normal' }
        $DgUI.Form.Activate()
        if ($Text) { New-DiagramFromText 'Diagram' $Text }
        return
    }
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Diagram studio'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px 1500), (Px 900)); $f.MinimumSize = New-Object System.Drawing.Size((Px 1000), (Px 600))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Panel; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $DgUI.Form = $f

    # right: properties
    $right = New-Object System.Windows.Forms.FlowLayoutPanel
    $right.Dock = 'Right'; $right.Width = Px (290 * $TextZoom); $right.FlowDirection = 'TopDown'; $right.WrapContents = $false; $right.AutoScroll = $true
    $right.BackColor = $C.Bg; $right.Padding = New-Object System.Windows.Forms.Padding((Px 14), (Px 10), (Px 8), (Px 10))
    $DgUI.Props = $right

    # left: text editor and saved diagrams
    $left = New-Object System.Windows.Forms.Panel
    $left.Dock = 'Left'; $left.Width = Px 430; $left.BackColor = $C.Bg
    $tabs = New-TabSet $left
    $pText = Add-ApiTab $tabs 'Text'
    $DgUI.Tabs = $tabs
    Add-DiagramDataTab $tabs
    $pSaved = Add-ApiTab $tabs 'Saved'
    $ed = New-TbRtb; $ed.Dock = 'Fill'; $ed.AcceptsTab = $true; $ed.WordWrap = $false
    $DgUI.Editor = $ed
    Register-PlainPaste $ed
    $warn = New-Object System.Windows.Forms.Label
    $warn.Dock = 'Bottom'; $warn.AutoSize = $false; $warn.Height = Px 46; $warn.ForeColor = $C.Dim; $warn.BackColor = $C.Bg; $warn.Font = $FontSmall; $warn.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 4), (Px 6), 0)
    $DgUI.Warn = $warn
    $help = New-Object System.Windows.Forms.LinkLabel
    $help.Dock = 'Bottom'; $help.Text = 'Syntax help'; $help.LinkColor = $C.Accent; $help.BackColor = $C.Bg; $help.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 2), 0, (Px 4)); $help.AutoSize = $false; $help.Height = $FontMain.Height + (Px 8)
    $help.add_LinkClicked({ Show-DiagramHelp })
    $pText.Controls.Add($ed); $pText.Controls.Add($warn); $pText.Controls.Add($help)
    # Saved: folders like in Notes (click a folder to open / close it, drag diagrams and folders onto a folder)
    $fl = New-DvFolderList $pSaved 'Search diagrams...'
    $fl.GetFolders = { Get-DiagramFolders }
    $fl.GetItems = { Get-DiagramItems }
    $fl.Title = { param($it) $it.Name }
    $fl.Meta = { param($it) 'edited ' + (Format-Age $it.Time) }
    $fl.IsCurrent = { param($it) $DgUI.File -and $it.Path -eq $DgUI.File }
    $fl.OnOpen = { param($it) if ($it.Path -ne $DgUI.File) { Open-DiagramFile $it.Path } }
    $fl.OnMove = { param($row, $to) Move-DiagramItem (Get-DiagramRowPath $row) (Get-DiagramDirOf $to) }
    $fl.OnMenu = { param($menu, $row) Show-DiagramTreeMenu $menu $row }
    $fl.OnRename = { param($row) Rename-DiagramItem $row }
    $fl.OnDelete = { param($row) Remove-DiagramItem $row }
    $fl.OnCollapse = { Save-DiagramCollapsed }
    $fl.EmptyText = 'No diagrams yet. Pick an example, or New diagram.'
    try { if (Test-Path -LiteralPath $DgCollapsedFile) { foreach ($p in @(ConvertFrom-JsonList (Read-DataText $DgCollapsedFile))) { if ($p) { [void]$fl.Collapsed.Add([string]$p) } } } } catch { }
    $DgUI.Folders = $fl
    $hdr = New-Object System.Windows.Forms.Label
    $hdr.Dock = 'Top'; $hdr.AutoSize = $false; $hdr.Height = Px 28; $hdr.Text = '  DIAGRAMS  (right-click for folders)'; $hdr.Font = $FontSmall; $hdr.ForeColor = $C.Accent; $hdr.BackColor = $C.Panel; $hdr.TextAlign = 'MiddleLeft'
    $sbar = New-Object System.Windows.Forms.FlowLayoutPanel
    $sbar.Dock = 'Top'; $sbar.AutoSize = $true; $sbar.WrapContents = $true; $sbar.BackColor = $C.Panel; $sbar.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 6), (Px 6), (Px 2))
    [void](New-Button 'New diagram' 'A new diagram in the selected folder' { New-DiagramNamed } $sbar $Glyph.Add 2)
    [void](New-Button 'Folder' 'A new folder inside the selected one' { New-DiagramFolder (Get-DvFolderSelected $DgUI.Folders) } $sbar $Glyph.Folder 2)
    [void](New-Button '' 'Open the diagrams folder in Explorer' { Start-Process explorer.exe (Get-DiagramTargetDir) } $sbar $Glyph.Open 2)
    $pSaved.Controls.Add($hdr); $pSaved.Controls.Add($sbar)
    $DgUI.List = $fl.List; $DgUI.Tabs = $tabs
    Select-ApiTab $tabs 'Text'

    # top: commands
    $top = New-Object System.Windows.Forms.FlowLayoutPanel
    $top.Dock = 'Top'; $top.AutoSize = $true; $top.WrapContents = $true; $top.BackColor = $C.Panel; $top.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 6))
    [void](New-Button 'New' 'A new, empty diagram (in the folder selected in Saved)' { New-DiagramNamed } $top $Glyph.Add 2)
    $exb = New-Button 'Examples' 'Start from an example' { Show-DiagramExamplesMenu $this } $top $Glyph.Apps 2
    [void](New-Button 'Import...' 'Open a diagram from a file (or drop it on this window): .dgm / .txt, Mermaid, draw.io, Graphviz DOT, CSV / Excel, or an SVG / HTML / PNG exported by DevTools' { Open-DiagramImport } $top $Glyph.Open 2)
    $exp = New-Button 'Export' 'Picture, PNG, SVG, an interactive web page, a widget or a React component' { Show-DiagramExportMenu $this } $top $Glyph.Save 1
    [void](New-Button '' 'Undo (Ctrl+Z)' { Undo-Diagram } $top ([string][char]0xE7A7) 2)
    [void](New-Button '' 'Redo (Ctrl+Y)' { Redo-Diagram } $top ([string][char]0xE7A6) 2)
    $DgUI.ModeBtn = New-Button 'Edit' 'Edit: drag, link and style shapes.  Preview: click shapes for details and try outages, as in the web page.' {
        $cv = $DgUI.Canvas; $cv.Editable = -not $cv.Editable
        $this.Text = if ($cv.Editable) { 'Edit' } else { 'Preview' }
        $cv.View.Selected.Clear(); $cv.View.SelectedEdge = ''; $cv.Invalidate(); Update-DiagramProps
    } $top $Glyph.Edit 2
    $DgUI.DarkBtn = New-Button 'Dark' 'Switch between the dark and the light colours' {
        $cv = $DgUI.Canvas; $cv.Dark = -not $cv.Dark; $DgUI.ModeSet = $true
        $this.Text = if ($cv.Dark) { 'Dark' } else { 'Light' }
        $cv.Invalidate()
    } $top ([string][char]0xE793) 2
    $DgUI.PauseBtn = New-Button 'Pause' 'Pause / play the flowing packets' { $cv = $DgUI.Canvas; $cv.Paused = -not $cv.Paused; $this.Text = if ($cv.Paused) { 'Play' } else { 'Pause' } } $top $Glyph.Pause 2
    $sp = New-TbCombo $top @('0.5x', '1x', '2x', '4x') 70; $sp.SelectedIndex = 1
    $sp.add_SelectedIndexChanged({ param($src, $e) $DgUI.Canvas.Speed = @(0.5, 1, 2, 4)[$src.SelectedIndex] })
    [void](New-Button 'Re-layout' 'Forget moved positions and lay everything out again' {
        $t = $DgUI.Text
        foreach ($n in $DgUI.Doc.Nodes) { if ($n.HasPos) { $t = [DgText]::SetNodeAttr($t, $n.Id, 'at', $null) } }
        Set-DiagramText $t -Fit
    } $top $Glyph.Refresh 2)

    # middle: canvas
    $cv = New-Object DgCanvas
    $cv.Dock = 'Fill'; $cv.UiScale = $Scale * $TextZoom; $cv.Font = $FontMain
    $DgUI.Canvas = $cv
    $cv.add_SelectionChanged({ Update-DiagramProps })
    $cv.add_Moved({
        param($src, $e)
        $t = $DgUI.Text
        foreach ($id in $src.MovedIds) { $n = $DgUI.Doc.Find($id); if ($n) { $t = [DgText]::SetNodeAttr($t, $id, 'at', "$([int]$n.X) $([int]$n.Y)") } }
        Set-DiagramText $t
    })
    $cv.add_EdgeAdded({ param($src, $e) Set-DiagramText ([DgText]::AddLine($DgUI.Text, "$($src.NewEdgeFrom) -> $($src.NewEdgeTo)")) })
    $cv.add_DeleteRequested({ Remove-DiagramSelection })
    $cv.add_NodeOpened({ if ($DgUI.Canvas.Editable) { Edit-DiagramLabel } })
    $cv.add_CopyRequested({ [void](Copy-DiagramSelection) })
    $cv.add_EndMoved({
        param($src, $e)
        $le = $src.MovedEdge; if (-not $le) { return }
        $k = if ($src.MovedSource) { 'from' } else { 'to' }
        $sd = if ($src.MovedSource) { "$($le.FromSide) $($le.FromT.ToString([Globalization.CultureInfo]::InvariantCulture))" } else { "$($le.ToSide) $($le.ToT.ToString([Globalization.CultureInfo]::InvariantCulture))" }
        $sel = $le.Id
        Set-DiagramText ([DgText]::EdgeSetAttr($DgUI.Text, $DgUI.Doc, $le, $k, $sd))
        Select-DiagramEdgeLike $le
    })
    $cv.add_RouteMoved({
        param($src, $e)
        $le = $src.MovedEdge; if (-not $le -or $le.Via.Count -eq 0) { return }
        Set-DiagramText ([DgText]::EdgeSetAttr($DgUI.Text, $DgUI.Doc, $le, 'via', "$([int]$le.Via[0].X) $([int]$le.Via[0].Y)"))
        Select-DiagramEdgeLike $le
    })
    $cv.add_LabelMoved({ param($src, $e) $le = $src.MovedLabel; if ($le -and $le.SrcLine -ge 0) { Set-DiagramText ([DgText]::EdgeSetAttr($DgUI.Text, $DgUI.Doc, $le, 'labelat', "$([int]$le.LabelAt.X) $([int]$le.LabelAt.Y)")); Select-DiagramEdgeLike $le } })
    $cv.add_PasteRequested({ Paste-DiagramClip })
    $cv.add_DuplicateRequested({ Copy-DiagramDuplicate })
    $cm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $cm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $cv = $DgUI.Canvas
        $pt = $cv.PointToClient([System.Windows.Forms.Cursor]::Position)
        $w = New-Object System.Drawing.PointF(($pt.X / $cv.Zoom + $cv.Pan.X), ($pt.Y / $cv.Zoom + $cv.Pan.Y))
        $DgUI.MenuAt = $w
        $n = $cv.NodeAt($w)
        if ($n -and -not $cv.View.Selected.Contains($n.Id)) { $cv.Select([string[]]@($n.Id)) }
        [void](Add-MenuItem $src 'Add a shape here' { Add-DiagramNode $DgUI.MenuAt.X $DgUI.MenuAt.Y } $Glyph.Add)
        [void](Add-MenuItem $src 'Add text here' { Add-DiagramNode $DgUI.MenuAt.X $DgUI.MenuAt.Y -Text } $Glyph.Edit)
        $g = if (-not $n) { $cv.GroupAt($w) } else { $null }
        if ($g) { $cv.Select([string[]]@($g.Members)) }
        if ($cv.View.Selected.Count) {
            [void](Add-MenuItem $src $(if ($g) { "Copy the group ""$($g.Title)""" } else { 'Copy (to paste into any diagram)' }) { [void](Copy-DiagramSelection) } $Glyph.Copy 'Ctrl+C')
            [void](Add-MenuItem $src 'Duplicate' { Copy-DiagramDuplicate } $Glyph.Copy 'Ctrl+D')
        }
        $clipText = ''; try { $clipText = [System.Windows.Forms.Clipboard]::GetText() } catch { }
        if ($clipText.Trim()) { [void](Add-MenuItem $src 'Paste here' { Paste-DiagramClip } $Glyph.Paste 'Ctrl+V') }
        if ($n) {
            [void](Add-MenuItem $src 'Rename' { Edit-DiagramLabel } $Glyph.Edit 'Double-click')
            [void](Add-MenuItem $src 'Auto position' { $t = $DgUI.Text; foreach ($id in @($DgUI.Canvas.View.Selected)) { $t = [DgText]::SetNodeAttr($t, $id, 'at', $null) }; Set-DiagramText $t } $Glyph.Refresh)
            [void](Add-MenuItem $src 'Delete' { Remove-DiagramSelection } $Glyph.Delete 'Del')
        }
        [void]$src.Items.Add('-')
        [void](Add-MenuItem $src 'Fit to window' { $DgUI.Canvas.ZoomToFit() } $Glyph.View 'Ctrl+0')
    })
    $cv.ContextMenuStrip = $cm

    $f.Controls.Add($cv); $f.Controls.Add($right); $f.Controls.Add($left); $f.Controls.Add($top)
    $cv.BringToFront()

    $DgUI.ColorTimer = New-TbDebounce 500 { if ($DgUI.Form) { Set-DiagramColors } }
    $DgUI.TypeTimer = New-TbDebounce 380 {
        if (-not $DgUI.Form) { return }
        $t = $DgUI.Editor.Text
        if ($t -cne $DgUI.Text) { $DgUI.Undo.Add($DgUI.Text); $DgUI.Redo.Clear(); $DgUI.Text = $t; Update-Diagram }
    }
    $DgUI.SaveTimer = New-TbDebounce 1500 { Save-DiagramFile }
    $ed.add_TextChanged({ if ($DgUI.Quiet) { return }; $DgUI.TypeTimer.Stop(); $DgUI.TypeTimer.Start(); $DgUI.ColorTimer.Stop(); $DgUI.ColorTimer.Start() })
    $f.add_KeyDown({
        param($src, $e)
        if ($e.Control -and $e.KeyCode -eq 'Z') { $e.SuppressKeyPress = $true; Undo-Diagram }
        elseif ($e.Control -and $e.KeyCode -eq 'Y') { $e.SuppressKeyPress = $true; Redo-Diagram }
        elseif ($e.Control -and $e.KeyCode -eq 'S') { $e.SuppressKeyPress = $true; Save-DiagramFile }
    })
    Register-DiagramDrop $f
    $f.add_FormClosing({ $DgUI.TypeTimer.Stop(); $t = $DgUI.Editor.Text; if ($t -cne $DgUI.Text) { $DgUI.Text = $t }; Save-DiagramFile })
    $f.add_FormClosed({ foreach ($k in 'TypeTimer', 'ColorTimer', 'SaveTimer') { if ($DgUI[$k]) { $DgUI[$k].Dispose(); $DgUI[$k] = $null } }; $DgUI.Form = $null; $DgUI.Canvas = $null; $DgUI.Props = $null; $DgUI.List = $null; $DgUI.Folders = $null; $DgUI.ModeSet = $false })
    Register-ThemedWindow $f
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    # the last diagram, or the example
    $files = Get-DiagramFiles
    if ($Text) { New-DiagramFromText 'Diagram' $Text }
    elseif ($files.Count) { Open-DiagramFile $files[0].FullName }
    else { New-DiagramFromText 'Network visibility map' ((Get-DiagramExamples)['Architecture/Network visibility map']) }
    Update-DiagramList
}

function Show-DiagramHelp {
    $t = @'
DIAGRAM TEXT  -  a line each; indent to add details to the shape above

title My diagram                  theme midnight dark   (daylight blueprint pastel mono neon corporate aurora ocean forest
                                  sunset arctic sand rose graphite dusk;  dark | light | auto = the page starts in that look)
direction LR                      LR TB RL BT  (auto layout)       layout lanes | layered | grid | circle | force
route ortho                       ortho | curve | straight         spacing 1.2     radius 10     font Segoe UI
hide header legend grid           turn parts off
category prod "Production" #3f4fc4 / #8b97ff      a colour for light / dark (bare words in [ ] become categories too)
lanes "Clients" | "Servers" | "Storage"           columns; put shapes in them with  lane 2

SHAPES
web: Web app [badge WEB, prod, lane 1, status ok, spark]
  desc Shown when the shape is clicked.
  tags Fast, Cached
  lines "First line under the title" "Second line"
  items "Device A" "TAP" "Device B"              small boxes inside; link them as web.1 or web.TAP
db[(Orders DB)]   a([Pill])   b{Decision?}   c((Circle))   d{{Hex}}   e[/Lean/]    (Mermaid shapes)
[shape card|rounded|rect|pill|circle|diamond|hexagon|parallelogram|cylinder|doc|note|actor|table|text]   (text = free text, no box)
[fill #123456, stroke #..., color #..., font 16, bold, dashed, size 240 90, at 120 80, url "https://..."]

LINKS
a -> b            a --> b        a -.-> b (dashed)     a ==> b (thick)      a --- b (no arrow)     a <-> b (both)
a -yes-> b        a -- yes --> b     a -->|yes| b      a -> b, c, d     a & b -> c     a -> b -> c
a -> b [prod, animate, density 2, dashed, dotted, curve, straight, both, noarrow, arrow both, label "x", via 300 120]
                  labelat 340 120  = where the label sits (drag it on the canvas)
                  from top 0.25, to left 0.8  = which side of the card an end sits on, and where along it (drag the ends)
                  via 300 120  = a bend the link goes through (drag the link)

GROUPS
group core "Core services" [svc, dashed] { a, b, c }      or      subgraph core [Core services] ... end

Graph TD / flowchart LR Mermaid text works as it is.
'@
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Diagram text'; $f.Icon = $IconActive; $f.StartPosition = 'CenterParent'; $f.Size = New-Object System.Drawing.Size((Px 1000), (Px 640))
    $f.BackColor = $C.Bg; $f.KeyPreview = $true; $f.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Escape') { $src.Close() } })
    $r = New-TbRtb -ReadOnly; $r.Dock = 'Fill'; $r.Text = $t
    $f.Controls.Add($r)
    Register-ThemedWindow $f
    $f.Show($DgUI.Form)
}

# ---- A folder list like the one in Notes: folder rows (open / close with a click, a count), item rows with a title
#      and a grey line under it, a search box, drag and drop onto folders. Used by the Diagram studio and the SQL client.
# $Fl fields set by the caller:
#   GetFolders  {} -> folder paths like "Work/Network"
#   GetItems    {} -> items, each with .Folder (a path or '') and anything the callbacks need
#   Title       {param($item)} -> the item's title;  Meta {param($item)} -> the grey line;  IsCurrent {param($item)} -> bold / selected
#   OnOpen      {param($item)} (click, or double-click when OpenOnDoubleClick)
#   OnMove      {param($row, [string]$toFolder)}  (row.IsFolder: a folder path is moved)
#   OnMenu      {param($menu, $row)}  (row may be $null: empty space)
#   OnDelete / OnRename {param($row)}  (Del / F2)
#   Collapsed   a HashSet of closed folder paths;  OnCollapse {} called after it changes (to save it)
function New-DvFolderList($Parent, [string]$Cue = 'Search...') {
    $fl = @{ View = (New-Object System.Collections.Generic.List[object]); Collapsed = (New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)); DropIndex = -1; Drag = $null; OpenOnDoubleClick = $false; SelectedFolder = ''; FocusFolder = $false }
    $fl.TitleFont = New-Object System.Drawing.Font($UiFont, (Fz 10), [System.Drawing.FontStyle]::Bold)
    $lb = New-Object System.Windows.Forms.ListBox
    $lb.Dock = 'Fill'; $lb.BorderStyle = 'None'; $lb.DrawMode = 'OwnerDrawVariable'; $lb.IntegralHeight = $false; $lb.BackColor = $C.Panel; $lb.ForeColor = $C.Fore
    $lb.Tag = $fl
    $fl.List = $lb
    $sp = New-Object System.Windows.Forms.Panel
    $sp.Dock = 'Top'; $sp.Height = Px 38; $sp.BackColor = $C.Panel
    $sp.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 4))
    $sb = New-Object System.Windows.Forms.TextBox
    $sb.Dock = 'Fill'; $sb.BorderStyle = 'FixedSingle'; $sb.BackColor = $C.Bg; $sb.ForeColor = $C.Fore; $sb.Tag = $fl
    $sb.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, $src.Tag.Cue) })
    $fl.Cue = $Cue
    $sb.add_TextChanged({ param($src, $e) Update-DvFolderList $src.Tag })
    $sp.Controls.Add($sb)
    $fl.Search = $sb
    $Parent.Controls.Add($lb); $Parent.Controls.Add($sp)

    $lb.add_MeasureItem({
        param($src, $e)
        $f = $src.Tag; $row = if ($e.Index -ge 0 -and $e.Index -lt $f.View.Count) { $f.View[$e.Index] } else { $null }
        $e.ItemHeight = if ($row -and $row.IsFolder) { $FontMain.Height + (Px 16) } elseif ($row -and $row.Empty) { $FontMain.Height + (Px 20) } else { $f.TitleFont.Height + $FontSmall.Height + (Px 18) }
    })
    $lb.add_DrawItem({
        param($src, $e)
        $f = $src.Tag
        if ($e.Index -lt 0 -or $e.Index -ge $f.View.Count) { return }
        $row = $f.View[$e.Index]
        $r = $e.Bounds; $g = $e.Graphics
        $selected = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $drop = $f.DropIndex -eq $e.Index
        $brush = New-Object System.Drawing.SolidBrush $(if ($drop) { $C.SelLine } elseif ($selected -and -not $row.Empty) { $C.Sel } else { $C.Panel })
        $g.FillRectangle($brush, $r); $brush.Dispose()
        if ($row.Empty) { [System.Windows.Forms.TextRenderer]::DrawText($g, $row.Text, $FontSmall, (New-Object System.Drawing.Rectangle(($r.X + (Px 12)), $r.Y, ($r.Width - (Px 20)), $r.Height)), $C.Dim, $TextFlags); return }
        if ($row.IsFolder) {
            $x = $r.X + (Px 8) + $row.Depth * (Px 18)
            $flags = [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding'
            if ($FontIconSmall) {
                [System.Windows.Forms.TextRenderer]::DrawText($g, $(if ($row.Open) { [string][char]0xE70D } else { [string][char]0xE76C }), $FontIconSmall, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 16), $r.Height)), $C.Dim, $flags)
                [System.Windows.Forms.TextRenderer]::DrawText($g, $Glyph.Folder, $FontIconSmall, (New-Object System.Drawing.Rectangle(($x + (Px 18)), $r.Y, (Px 20), $r.Height)), $C.Yellow, $flags)
            } else {
                [System.Windows.Forms.TextRenderer]::DrawText($g, $(if ($row.Open) { 'v' } else { '>' }), $FontMain, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 16), $r.Height)), $C.Dim, $flags)
            }
            $countText = [string]$row.Count
            $cw = [System.Windows.Forms.TextRenderer]::MeasureText($countText, $FontSmall).Width
            [System.Windows.Forms.TextRenderer]::DrawText($g, $row.Label, $f.TitleFont, (New-Object System.Drawing.Rectangle(($x + (Px 42)), $r.Y, ($r.Right - $x - (Px 60) - $cw), $r.Height)), $C.Fore, $TextFlags)
            [System.Windows.Forms.TextRenderer]::DrawText($g, $countText, $FontSmall, (New-Object System.Drawing.Rectangle(($r.Right - $cw - (Px 12)), $r.Y, ($cw + (Px 4)), $r.Height)), $C.Dim, $TextFlags)
        } else {
            $indent = if ($row.Depth -gt 0) { (Px 26) + ($row.Depth - 1) * (Px 18) } else { 0 }
            $current = $f.IsCurrent -and (& $f.IsCurrent $row.Item)
            if (($selected -or $current) -and -not $drop) { $bar = New-Object System.Drawing.SolidBrush $C.Accent; $g.FillRectangle($bar, $r.X, ($r.Y + (Px 6)), (Px 3), ($r.Height - (Px 12))); $bar.Dispose() }
            $x = $r.X + (Px 12) + $indent; $w = $r.Width - (Px 20) - $indent
            $th = $f.TitleFont.Height + (Px 2)
            $titleRect = New-Object System.Drawing.Rectangle($x, ($r.Y + (Px 7)), $w, $th)
            [System.Windows.Forms.TextRenderer]::DrawText($g, (& $f.Title $row.Item), $f.TitleFont, $titleRect, $(if ($current) { $C.Accent } else { $C.Fore }), $TextFlags)
            $meta = if ($f.Meta) { & $f.Meta $row.Item } else { '' }
            [System.Windows.Forms.TextRenderer]::DrawText($g, $meta, $FontSmall, (New-Object System.Drawing.Rectangle($x, $titleRect.Bottom, $w, ($FontSmall.Height + (Px 2)))), $C.Dim, $TextFlags)
        }
        $g.DrawLine($LinePen, $r.X, $r.Bottom - 1, $r.Right, $r.Bottom - 1)
    })
    # click a folder: open / close it; drag a row onto a folder (or empty space = the top) to move it
    $lb.add_MouseDown({
        param($src, $e)
        $f = $src.Tag; $f.Drag = $null
        $i = $src.IndexFromPoint($e.Location)
        if ($i -lt 0 -or $i -ge $f.View.Count -or -not $src.GetItemRectangle($i).Contains($e.Location)) { $i = -1 }
        if ($e.Button -eq 'Right') { if ($i -ge 0) { $src.SelectedIndex = $i } else { $src.ClearSelected() }; return }
        if ($e.Button -ne 'Left' -or $i -lt 0) { return }
        $row = $f.View[$i]
        if ($row.Empty) { return }
        $f.Drag = @{ Row = $row; From = $e.Location; On = $false; Index = $i }
    })
    $lb.add_MouseMove({
        param($src, $e)
        $f = $src.Tag; $d = $f.Drag
        if (-not $d -or $e.Button -ne 'Left') { return }
        if (-not $d.On -and ([Math]::Abs($e.X - $d.From.X) + [Math]::Abs($e.Y - $d.From.Y)) -gt (Px 6)) { $d.On = $true; $src.Capture = $true; $src.Cursor = [System.Windows.Forms.Cursors]::Hand }
        if (-not $d.On) { return }
        $i = $src.IndexFromPoint($e.Location)
        if ($i -ge 0 -and -not $src.GetItemRectangle($i).Contains($e.Location)) { $i = -1 }
        $t = if ($i -ge 0 -and $f.View[$i].IsFolder) { $i } else { -1 }
        if ($t -ne $f.DropIndex) { $old = $f.DropIndex; $f.DropIndex = $t; if ($old -ge 0 -and $old -lt $src.Items.Count) { $src.Invalidate($src.GetItemRectangle($old)) }; if ($t -ge 0) { $src.Invalidate($src.GetItemRectangle($t)) } }
    })
    $lb.add_MouseUp({
        param($src, $e)
        $f = $src.Tag; $d = $f.Drag; $f.Drag = $null
        $src.Capture = $false; $src.Cursor = [System.Windows.Forms.Cursors]::Default
        $di = $f.DropIndex; $f.DropIndex = -1
        if (-not $d) { return }
        if (-not $d.On) {
            # a click
            if ($d.Row.IsFolder) {
                $f.SelectedFolder = $d.Row.Path; $f.FocusFolder = $true
                if ($f.Collapsed.Contains($d.Row.Path)) { [void]$f.Collapsed.Remove($d.Row.Path) } else { [void]$f.Collapsed.Add($d.Row.Path) }
                if ($f.OnCollapse) { & $f.OnCollapse }
                Update-DvFolderList $f
            } else {
                $f.SelectedFolder = [string]$d.Row.Item.Folder
                if (-not $f.OpenOnDoubleClick -and $f.OnOpen) { & $f.OnOpen $d.Row.Item }
            }
            return
        }
        $src.Invalidate()
        $pt = $e.Location
        if (-not $src.ClientRectangle.Contains($pt)) { return }
        $to = ''
        $i = $src.IndexFromPoint($pt)
        if ($i -ge 0 -and $i -lt $f.View.Count -and $src.GetItemRectangle($i).Contains($pt)) { $tr = $f.View[$i]; $to = if ($tr.IsFolder) { $tr.Path } elseif ($tr.Empty) { '' } else { [string]$tr.Item.Folder } }
        if ($d.Row.IsFolder -and ($to -eq $d.Row.Path -or $to.StartsWith($d.Row.Path + '/'))) { return }
        if ($f.OnMove) { & $f.OnMove $d.Row $to }
    })
    $lb.add_DoubleClick({
        param($src, $e)
        $f = $src.Tag; $i = $src.SelectedIndex
        if ($f.OpenOnDoubleClick -and $i -ge 0 -and $i -lt $f.View.Count -and -not $f.View[$i].IsFolder -and -not $f.View[$i].Empty -and $f.OnOpen) { & $f.OnOpen $f.View[$i].Item }
    })
    $lb.add_KeyDown({
        param($src, $e)
        $f = $src.Tag; $i = $src.SelectedIndex
        if ($i -lt 0 -or $i -ge $f.View.Count -or $f.View[$i].Empty) { return }
        $row = $f.View[$i]
        if ($e.KeyCode -eq 'Return' -and -not $row.IsFolder -and $f.OnOpen) { $e.SuppressKeyPress = $true; & $f.OnOpen $row.Item }
        elseif ($e.KeyCode -eq 'F2' -and $f.OnRename) { $e.SuppressKeyPress = $true; & $f.OnRename $row }
        elseif ($e.KeyCode -eq 'Delete' -and $f.OnDelete) { $e.SuppressKeyPress = $true; & $f.OnDelete $row }
        elseif (($e.KeyCode -eq 'Right' -or $e.KeyCode -eq 'Left') -and $row.IsFolder) {
            $e.SuppressKeyPress = $true
            if ($e.KeyCode -eq 'Left') { [void]$f.Collapsed.Add($row.Path) } else { [void]$f.Collapsed.Remove($row.Path) }
            $f.SelectedFolder = $row.Path; $f.FocusFolder = $true
            if ($f.OnCollapse) { & $f.OnCollapse }
            Update-DvFolderList $f
        }
    })
    $cm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $cm.Tag = $fl
    $cm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $f = $src.Tag; $i = $f.List.SelectedIndex
        $row = if ($i -ge 0 -and $i -lt $f.View.Count -and -not $f.View[$i].Empty) { $f.View[$i] } else { $null }
        $f.MenuRow = $row
        if ($f.OnMenu) { & $f.OnMenu $src $row }
        if (-not $src.Items.Count) { $e.Cancel = $true }
    })
    $lb.ContextMenuStrip = $cm
    $fl
}

function Get-DvFolderParent([string]$Path) { $i = $Path.LastIndexOf('/'); if ($i -gt 0) { $Path.Substring(0, $i) } else { '' } }
function Get-DvFolderLeaf([string]$Path) { $i = $Path.LastIndexOf('/'); if ($i -ge 0) { $Path.Substring($i + 1) } else { $Path } }

function Update-DvFolderList($Fl) {
    if (-not $Fl -or -not $Fl.List -or $Fl.List.IsDisposed) { return }
    $q = $Fl.Search.Text.Trim()
    $items = @(& $Fl.GetItems)
    $hits = @($items | Where-Object { -not $q -or (& $Fl.Title $_).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -ge 0 -or ($Fl.Meta -and (& $Fl.Meta $_).IndexOf($q, [StringComparison]::OrdinalIgnoreCase) -ge 0) })
    # every folder, also the parents of the ones the items are in
    $folders = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($p in @(& $Fl.GetFolders) + @($items | ForEach-Object { [string]$_.Folder })) { $x = [string]$p; while ($x) { [void]$folders.Add($x); $x = Get-DvFolderParent $x } }
    $Fl.View.Clear()
    $add = $null
    $add = {
        param([string]$Parent, [int]$Depth)
        foreach ($fp in @($folders | Where-Object { (Get-DvFolderParent $_) -eq $Parent } | Sort-Object { Get-DvFolderLeaf $_ })) {
            $count = @($hits | Where-Object { $_.Folder -and ([string]$_.Folder -eq $fp -or ([string]$_.Folder).StartsWith($fp + '/', [StringComparison]::OrdinalIgnoreCase)) }).Count
            if ($q -and $count -eq 0) { continue }
            $open = [bool]($q -or -not $Fl.Collapsed.Contains($fp))
            $Fl.View.Add([pscustomobject]@{ IsFolder = $true; Empty = $false; Path = $fp; Label = (Get-DvFolderLeaf $fp); Depth = $Depth; Count = $count; Open = $open })
            if ($open) {
                & $add $fp ($Depth + 1)
                foreach ($it in @($hits | Where-Object { [string]$_.Folder -eq $fp } | Sort-Object { & $Fl.Title $_ })) { $Fl.View.Add([pscustomobject]@{ IsFolder = $false; Empty = $false; Item = $it; Depth = $Depth + 1 }) }
            }
        }
    }
    & $add '' 0
    foreach ($it in @($hits | Where-Object { -not $_.Folder } | Sort-Object { & $Fl.Title $_ })) { $Fl.View.Add([pscustomobject]@{ IsFolder = $false; Empty = $false; Item = $it; Depth = 0 }) }
    if ($Fl.View.Count -eq 0) { $Fl.View.Add([pscustomobject]@{ IsFolder = $false; Empty = $true; Text = $(if ($q) { 'Nothing found.' } elseif ($Fl.EmptyText) { $Fl.EmptyText } else { 'Nothing here yet.' }) }) }
    $lb = $Fl.List
    $lb.BeginUpdate()
    try {
        $lb.Items.Clear()
        $pick = -1
        for ($i = 0; $i -lt $Fl.View.Count; $i++) {
            [void]$lb.Items.Add($i)
            $row = $Fl.View[$i]
            if ($row.Empty) { continue }
            if ($Fl.FocusFolder) { if ($row.IsFolder -and $row.Path -eq $Fl.SelectedFolder) { $pick = $i } }
            elseif (-not $row.IsFolder -and $Fl.IsCurrent -and (& $Fl.IsCurrent $row.Item)) { $pick = $i }
        }
        $Fl.FocusFolder = $false
        if ($pick -ge 0) { $lb.SelectedIndex = $pick }
    } finally { $lb.EndUpdate() }
}

# the folder of the selected row ('' = the top)
function Get-DvFolderSelected($Fl) {
    $i = $Fl.List.SelectedIndex
    if ($i -ge 0 -and $i -lt $Fl.View.Count -and -not $Fl.View[$i].Empty) { $row = $Fl.View[$i]; if ($row.IsFolder) { return $row.Path } else { return [string]$row.Item.Folder } }
    [string]$Fl.SelectedFolder
}

# "Move to" with every folder, indented
function Add-DvMoveMenu($Menu, $Fl, [string]$Current, [string]$Exclude, [scriptblock]$OnPick) {
    $mv = New-Object System.Windows.Forms.ToolStripMenuItem('Move to', (New-GlyphImage $Glyph.Folder))
    $folders = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($p in @(& $Fl.GetFolders) + @(@(& $Fl.GetItems) | ForEach-Object { [string]$_.Folder })) { $x = [string]$p; while ($x) { [void]$folders.Add($x); $x = Get-DvFolderParent $x } }
    $top = $mv.DropDownItems.Add('(top level)', $null, { param($s2, $e2) & $s2.Tag.Pick $s2.Tag.To }); $top.Tag = @{ Pick = $OnPick; To = '' }; $top.Enabled = [bool]$Current
    foreach ($p in @($folders | Sort-Object)) {
        if ($Exclude -and ($p -eq $Exclude -or $p.StartsWith($Exclude + '/'))) { continue }
        $it = $mv.DropDownItems.Add(('    ' * ($p.Split('/').Count - 1)) + (Get-DvFolderLeaf $p), $null, { param($s2, $e2) & $s2.Tag.Pick $s2.Tag.To })
        $it.Tag = @{ Pick = $OnPick; To = $p }; $it.Enabled = $p -ne $Current
    }
    [void]$Menu.Items.Add($mv)
}

# ---- folders that are only paths ("Work/Prod") on items with a .Folder, plus a list of folder paths (also the empty ones)
function Set-DvItemFolder($Item, [string]$Folder) { if ($Item.PSObject.Properties['Folder']) { $Item.Folder = $Folder } else { $Item | Add-Member -NotePropertyName Folder -NotePropertyValue $Folder } }
function Join-DvFolder([string]$Parent, [string]$Rest) { if ($Parent -and $Rest) { "$Parent/$Rest" } elseif ($Parent) { $Parent } else { $Rest } }
function ConvertTo-DvFolderName([string]$Name) { (($Name -replace '[/\\]', ' ') -replace '\s+', ' ').Trim() }
# a folder renamed or moved: the items, the folder list and the closed folders follow
function Rename-DvFolderPath($Items, $Folders, $Collapsed, [string]$Old, [string]$New) {
    $cmp = [StringComparison]::OrdinalIgnoreCase
    foreach ($it in $Items) { $f = [string]$it.Folder; if ($f -eq $Old -or $f.StartsWith($Old + '/', $cmp)) { Set-DvItemFolder $it ($New + $f.Substring($Old.Length)) } }
    for ($i = $Folders.Count - 1; $i -ge 0; $i--) { $f = [string]$Folders[$i]; if ($f -eq $Old -or $f.StartsWith($Old + '/', $cmp)) { $Folders[$i] = $New + $f.Substring($Old.Length) } }
    if (-not $Folders.Contains($New)) { $Folders.Add($New) }
    if ($Collapsed) { foreach ($p in @($Collapsed)) { if ($p -eq $Old -or $p.StartsWith($Old + '/', $cmp)) { [void]$Collapsed.Remove($p); [void]$Collapsed.Add($New + $p.Substring($Old.Length)) } } }
    Optimize-DvFolders $Folders
}
# a folder deleted: like in Notes, what is in it moves up one level
function Remove-DvFolderPath($Items, $Folders, $Collapsed, [string]$Path) {
    $cmp = [StringComparison]::OrdinalIgnoreCase
    $parent = Get-DvFolderParent $Path
    foreach ($it in $Items) { $f = [string]$it.Folder; if ($f -eq $Path) { Set-DvItemFolder $it $parent } elseif ($f.StartsWith($Path + '/', $cmp)) { Set-DvItemFolder $it (Join-DvFolder $parent $f.Substring($Path.Length + 1)) } }
    for ($i = $Folders.Count - 1; $i -ge 0; $i--) { $f = [string]$Folders[$i]; if ($f -eq $Path) { $Folders.RemoveAt($i) } elseif ($f.StartsWith($Path + '/', $cmp)) { $Folders[$i] = Join-DvFolder $parent $f.Substring($Path.Length + 1) } }
    if ($Collapsed) { foreach ($p in @($Collapsed)) { if ($p -eq $Path -or $p.StartsWith($Path + '/', $cmp)) { [void]$Collapsed.Remove($p) } } }
    Optimize-DvFolders $Folders
}
function Optimize-DvFolders($Folders) {
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    for ($i = 0; $i -lt $Folders.Count; $i++) { if (-not $Folders[$i] -or -not $seen.Add([string]$Folders[$i])) { $Folders.RemoveAt($i); $i-- } }
}

# ---- Data tab: CSV / TSV / Excel (pasted or a file) into a chart, a graph (from -> to) or a tree (id -> parent).
function Add-DiagramDataTab($Tabs) {
    $pData = Add-ApiTab $Tabs 'Data'
    $fl = New-Object System.Windows.Forms.FlowLayoutPanel
    $fl.Dock = 'Fill'; $fl.FlowDirection = 'TopDown'; $fl.WrapContents = $false; $fl.AutoScroll = $true; $fl.BackColor = $C.Bg
    $fl.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 8))
    $pData.Controls.Add($fl)
    $st = @{ Name = 'Data'; File = ''; Busy = $false }
    $DgUI.Data = $st
    $row = New-Object System.Windows.Forms.FlowLayoutPanel; $row.AutoSize = $true; $row.WrapContents = $true; $row.BackColor = $C.Bg; $row.MaximumSize = New-Object System.Drawing.Size((Px 410), 0)
    [void](New-Button 'Open file...' 'A .csv, .tsv, .txt or Excel .xlsx file' { Open-DiagramDataFile } $row $Glyph.Open 2)
    [void](New-Button 'Paste' 'Cells copied from Excel, a database tool or CSV text' { $t = ''; try { $t = [System.Windows.Forms.Clipboard]::GetText() } catch { }; if ($t) { $DgUI.Data.Name = 'Data'; $DgUI.Data.File = ''; $DgUI.Data.Sheet.Visible = $false; $DgUI.Data.SheetLabel.Visible = $false; $DgUI.Data.Box.Text = $t } } $row $Glyph.Paste 2)
    [void](New-Button 'Sample' 'Example sales data to try it' { $DgUI.Data.Name = 'Sales'; $DgUI.Data.Box.Text = "Month,Region,Sales,Costs`r`nJan,EU,1200,800`r`nFeb,EU,1400,950`r`nMar,US,1100,1020`r`nApr,US,1700,990`r`nMay,EU,2100,1200`r`nJun,US,1950,1300`r`nJan,US,300,150" } $row $Glyph.Apps 2)
    $fl.Controls.Add($row)
    $st.SheetLabel = New-TbLabel $fl 'Sheet' -Dim; $st.SheetLabel.Visible = $false
    $st.Sheet = New-TbCombo $fl @() 250; $st.Sheet.Visible = $false
    $fl.Controls.SetChildIndex($st.SheetLabel, $fl.Controls.IndexOf($st.Sheet))
    $st.Sheet.add_SelectedIndexChanged({ param($src, $e) if (-not $DgUI.Data.Busy) { Read-DiagramDataSheet } })
    New-TbLabel $fl 'Data (first row = column names)' -Dim | Out-Null
    $box = New-TbBox -Mono -Multi; $box.ScrollBars = 'Both'; $box.WordWrap = $false; $box.AcceptsReturn = $true; $box.Height = Px 170; $box.Width = Px 400
    $fl.Controls.Add($box); $st.Box = $box
    $st.Info = New-TbLabel $fl '' -Dim
    New-TbLabel $fl 'Make' -Dim | Out-Null
    $st.Kind = New-TbCombo $fl @('Chart', 'Links (from -> to)', 'Tree (id -> parent)') 250; $st.Kind.SelectedIndex = 0
    $st.L1 = New-TbLabel $fl 'X axis / categories' -Dim
    $st.C1 = New-TbCombo $fl @() 250
    $st.L2 = New-TbLabel $fl 'Values (tick one or more)' -Dim
    $st.Vals = New-Object System.Windows.Forms.CheckedListBox
    $st.Vals.CheckOnClick = $true; $st.Vals.BorderStyle = 'FixedSingle'; $st.Vals.BackColor = $C.Bg; $st.Vals.ForeColor = $C.Fore; $st.Vals.Width = Px 250; $st.Vals.Height = Px 90; $st.Vals.IntegralHeight = $false
    $fl.Controls.Add($st.Vals)
    $st.C2 = New-TbCombo $fl @() 250
    $st.L3 = New-TbLabel $fl 'Label (optional)' -Dim
    $st.C3 = New-TbCombo $fl @() 250
    $st.L4 = New-TbLabel $fl 'Colour by (optional)' -Dim
    $st.C4 = New-TbCombo $fl @() 250
    $st.LT = New-TbLabel $fl 'Chart' -Dim
    $st.Type = New-TbCombo $fl @('column', 'bar', 'stacked column', 'stacked bar', 'line', 'area', 'pie', 'donut', 'scatter') 160; $st.Type.SelectedIndex = 0
    $st.LA = New-TbLabel $fl 'Combine rows with the same X by' -Dim
    $st.Agg = New-TbCombo $fl @('sum', 'count', 'avg', 'min', 'max', 'first') 120; $st.Agg.SelectedIndex = 0
    $st.LS = New-TbLabel $fl 'Order' -Dim
    $st.Sort = New-TbCombo $fl @('as in the data', 'largest first', 'A-Z', 'Z-A') 160; $st.Sort.SelectedIndex = 0
    New-TbLabel $fl 'Theme' -Dim | Out-Null
    $st.Theme = New-TbCombo $fl ([DgTheme]::Names) 160; $st.Theme.SelectedItem = 'corporate'
    $go = New-Button 'Create the diagram' 'Make a new diagram from this data' { New-DiagramFromData } $fl $Glyph.Add 1
    $go.Margin = New-Object System.Windows.Forms.Padding(0, (Px 12), 0, 0)
    New-TbLabel $fl 'The chart keeps its data in the diagram text (data ... end), so it can be edited there later.' -Dim | ForEach-Object { $_.MaximumSize = New-Object System.Drawing.Size((Px 400), 0); $_.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0) }
    $st.Kind.add_SelectedIndexChanged({ Update-DiagramDataForm })
    $st.Timer = New-TbDebounce 400 { if ($DgUI.Form) { Update-DiagramDataColumns } }
    $box.add_TextChanged({ $DgUI.Data.Timer.Stop(); $DgUI.Data.Timer.Start() })
    Update-DiagramDataForm
}

function Get-DiagramDataRows { , [DgChartCalc]::Rows([System.Collections.Generic.List[string]]@($DgUI.Data.Box.Text -split "`r?`n")) }

function Update-DiagramDataColumns {
    $st = $DgUI.Data
    $rows = Get-DiagramDataRows
    $heads = if ($rows.Count) { @($rows[0]) } else { @() }
    $st.Info.Text = if ($rows.Count -gt 1) { "$($rows.Count - 1) rows, $($heads.Count) columns" } else { 'No data yet' }
    $keep = @{ C1 = $st.C1.SelectedItem; C2 = $st.C2.SelectedItem; C3 = $st.C3.SelectedItem; C4 = $st.C4.SelectedItem }
    $checked = @($st.Vals.CheckedItems)
    foreach ($k in 'C1', 'C2', 'C3', 'C4') {
        $cb = $st[$k]; $cb.Items.Clear()
        if ($k -in 'C3', 'C4') { [void]$cb.Items.Add('(none)') }
        foreach ($h in $heads) { [void]$cb.Items.Add($h) }
        if ($keep[$k] -and $cb.Items.Contains($keep[$k])) { $cb.SelectedItem = $keep[$k] } elseif ($cb.Items.Count) { $cb.SelectedIndex = $(if ($k -eq 'C2' -and $cb.Items.Count -gt 1) { 1 } else { 0 }) }
    }
    $st.Vals.Items.Clear()
    # number columns are ticked at first
    $body = @($rows | Select-Object -Skip 1 -First 50)
    for ($i = 0; $i -lt $heads.Count; $i++) {
        $isNum = @($body | Where-Object { $i -lt $_.Count -and $null -ne [DgChartCalc]::Num($_[$i]) }).Count -gt [Math]::Max(0, $body.Count / 2)
        $on = if ($checked.Count) { $checked -contains $heads[$i] } else { $isNum -and $i -gt 0 }
        [void]$st.Vals.Items.Add($heads[$i], $on)
    }
}

function Update-DiagramDataForm {
    $st = $DgUI.Data
    $k = $st.Kind.SelectedIndex
    $chart = $k -eq 0
    $st.L1.Text = @('X axis / categories', 'From (one end of a link)', 'Id')[$k]
    $st.L2.Text = @('Values (tick one or more)', 'To (the other end)', 'Parent id')[$k]
    $st.Vals.Visible = $chart; $st.C2.Visible = -not $chart
    $st.L3.Text = @('Label (optional)', 'Link label (optional)', 'Name shown (optional)')[$k]
    $st.L3.Visible = -not $chart; $st.C3.Visible = -not $chart
    $st.L4.Visible = $k -eq 1; $st.C4.Visible = $k -eq 1
    foreach ($kk in 'LT', 'Type', 'LA', 'Agg', 'LS', 'Sort') { $st[$kk].Visible = $chart }
}

function Open-DiagramDataFile {
    $d = New-Object System.Windows.Forms.OpenFileDialog
    $d.Filter = 'Data files|*.csv;*.tsv;*.txt;*.xlsx|Excel|*.xlsx|CSV|*.csv;*.tsv;*.txt|All files|*.*'
    $script:Modal = $true
    try { if ($d.ShowDialog($DgUI.Form) -ne 'OK') { return }; $path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    Import-DiagramDataFile $path
}

function Import-DiagramDataFile([string]$Path) {
    $st = $DgUI.Data
    $st.File = $Path; $st.Name = [IO.Path]::GetFileNameWithoutExtension($Path)
    if ($Path -match '\.xlsx$') {
        try { $sheets = @([DgXlsx]::Sheets($Path)) } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't read it: $($_.Exception.Message)", 'Diagram studio'); return }
        $st.Busy = $true
        $st.Sheet.Items.Clear(); foreach ($s in $sheets) { [void]$st.Sheet.Items.Add($s) }
        $st.Sheet.Visible = $sheets.Count -gt 0; $st.SheetLabel.Visible = $st.Sheet.Visible
        if ($sheets.Count) { $st.Sheet.SelectedIndex = 0 }
        $st.Busy = $false
        Read-DiagramDataSheet
    } else {
        $st.Sheet.Visible = $false; $st.SheetLabel.Visible = $false
        try { $st.Box.Text = [IO.File]::ReadAllText($Path) } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't read it: $($_.Exception.Message)", 'Diagram studio') }
    }
}

function Read-DiagramDataSheet {
    $st = $DgUI.Data
    if (-not $st.File -or $st.File -notmatch '\.xlsx$') { return }
    try {
        $rows = [DgXlsx]::Read($st.File, [string]$st.Sheet.SelectedItem, 20000)
        $st.Box.Text = [DgXlsx]::ToCsv($rows)
        if ($st.Sheet.SelectedItem) { $st.Name = "$([IO.Path]::GetFileNameWithoutExtension($st.File)) - $($st.Sheet.SelectedItem)" }
    } catch { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "Couldn't read the sheet: $($_.Exception.Message)", 'Diagram studio') }
}

# a name that works as a diagram id
function ConvertTo-DiagramId([string]$Name, $Used) {
    $b = ($Name -replace '[^\w]+', '_').Trim('_')
    if (-not $b) { $b = 'n' }
    if ($b -match '^\d') { $b = "n$b" }
    if (-not $Used.ContainsKey($b) -or $Used[$b] -eq $Name) { $Used[$b] = $Name; return $b }
    $i = 2; while ($Used.ContainsKey("${b}_$i") -and $Used["${b}_$i"] -ne $Name) { $i++ }
    $Used["${b}_$i"] = $Name; "${b}_$i"
}

function New-DiagramFromData {
    $st = $DgUI.Data
    $rows = Get-DiagramDataRows
    if ($rows.Count -lt 2) { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, 'There is no data yet: paste some, open a file or try the sample.', 'Diagram studio'); return }
    $heads = @($rows[0]); $body = @($rows | Select-Object -Skip 1)
    $title = $st.Name
    $theme = [string]$st.Theme.SelectedItem
    $q = { param($s) '"' + ($s -replace '"', "'") + '"' }
    $col = { param($name) [Array]::IndexOf($heads, $name) }
    $sb = New-Object System.Text.StringBuilder
    switch ($st.Kind.SelectedIndex) {
        0 {
            $vals = @($st.Vals.CheckedItems | ForEach-Object { [string]$_ })
            $agg = [string]$st.Agg.SelectedItem
            if (-not $vals.Count -and $agg -ne 'count') { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, 'Tick at least one column with values (or combine by count).', 'Diagram studio'); return }
            $type = [string]$st.Type.SelectedItem
            [void]$sb.AppendLine("title $title").AppendLine("theme $theme light").AppendLine("chart $type")
            [void]$sb.AppendLine("x $($st.C1.SelectedItem)")
            if ($vals.Count) { [void]$sb.AppendLine("y " + (($vals | ForEach-Object { if ($_ -match ',') { & $q $_ } else { $_ } }) -join ', ')) }
            [void]$sb.AppendLine("agg $agg")
            $so = @('', 'value', 'asc', 'desc')[$st.Sort.SelectedIndex]; if ($so) { [void]$sb.AppendLine("sort $so") }
            if ($body.Count -le 24) { [void]$sb.AppendLine('labels on') }
            [void]$sb.AppendLine('data')
            foreach ($l in ($st.Box.Text -split "`r?`n")) { if ($l.Trim() -and $l.Trim() -ne 'end') { [void]$sb.AppendLine($l) } }
            [void]$sb.Append('end')
        }
        1 {
            $fi = & $col $st.C1.SelectedItem; $ti = & $col $st.C2.SelectedItem
            $li = if ($st.C3.SelectedIndex -gt 0) { & $col $st.C3.SelectedItem } else { -1 }
            $ci = if ($st.C4.SelectedIndex -gt 0) { & $col $st.C4.SelectedItem } else { -1 }
            [void]$sb.AppendLine("title $title").AppendLine("theme $theme light").AppendLine('direction LR').AppendLine()
            $used = @{}; $ids = @{}; $nodes = New-Object System.Collections.Generic.List[string]
            foreach ($r in $body) { foreach ($i in $fi, $ti) { $v = if ($i -lt $r.Count) { $r[$i] } else { '' }; if ($v -and -not $ids.ContainsKey($v)) { $ids[$v] = ConvertTo-DiagramId $v $used; $nodes.Add($v) } } }
            foreach ($v in $nodes) { [void]$sb.AppendLine("$($ids[$v]): $v") }
            [void]$sb.AppendLine()
            foreach ($r in $body) {
                $f = if ($fi -lt $r.Count) { $r[$fi] } else { '' }; $t = if ($ti -lt $r.Count) { $r[$ti] } else { '' }
                if (-not $f -or -not $t) { continue }
                $at = @()
                if ($ci -ge 0 -and $ci -lt $r.Count -and $r[$ci]) { $at += ('cat ' + (($r[$ci] -replace '[^\w]+', '_').Trim('_'))) }
                if ($li -ge 0 -and $li -lt $r.Count -and $r[$li]) { $at += ('label ' + (& $q $r[$li])) }
                [void]$sb.AppendLine("$($ids[$f]) -> $($ids[$t])" + $(if ($at) { ' [' + ($at -join ', ') + ']' }))
            }
        }
        2 {
            $ii = & $col $st.C1.SelectedItem; $pi = & $col $st.C2.SelectedItem
            $ni = if ($st.C3.SelectedIndex -gt 0) { & $col $st.C3.SelectedItem } else { -1 }
            [void]$sb.AppendLine("title $title").AppendLine("theme $theme light").AppendLine('direction TB').AppendLine('route ortho').AppendLine()
            $used = @{}; $ids = @{}
            foreach ($r in $body) { $v = if ($ii -lt $r.Count) { $r[$ii] } else { '' }; if ($v -and -not $ids.ContainsKey($v)) { $ids[$v] = ConvertTo-DiagramId $v $used } }
            foreach ($r in $body) {
                $v = if ($ii -lt $r.Count) { $r[$ii] } else { '' }; if (-not $v) { continue }
                $name = if ($ni -ge 0 -and $ni -lt $r.Count -and $r[$ni]) { $r[$ni] } else { $v }
                [void]$sb.AppendLine("$($ids[$v]): $name")
            }
            [void]$sb.AppendLine()
            foreach ($r in $body) {
                $v = if ($ii -lt $r.Count) { $r[$ii] } else { '' }; $p = if ($pi -lt $r.Count) { $r[$pi] } else { '' }
                if ($v -and $p -and $ids.ContainsKey($p)) { [void]$sb.AppendLine("$($ids[$p]) -> $($ids[$v])") }
            }
        }
    }
    New-DiagramFromText $title $sb.ToString()
    Select-ApiTab $DgUI.Tabs 'Text'
}

# ---- importing diagrams: Import... or a file dropped on the window. .dgm / .txt / Mermaid (.mmd, a ```mermaid block in .md),
#      draw.io (.drawio / .xml, its SVG and PNG exports), Graphviz (.dot / .gv), CSV / Excel (into the Data tab), and the
#      SVG / HTML / React / PNG exports of DevTools (they carry the diagram text, so it comes back as it was)
function Add-DiagramSource([string]$Code, [string]$Kind) {
    $Code = [DgImport]::AsciiSafe($Code)                 # plain ASCII: the same in any page, whatever its encoding
    $mk = [DgImport]::Marker($DgUI.Text)
    switch ($Kind) {
        'react' { return $Code.TrimEnd() + "`n/* $mk */`n" }
        'svg' { $i = $Code.LastIndexOf('</svg>'); if ($i -ge 0) { return $Code.Substring(0, $i) + "<!-- $mk -->" + $Code.Substring($i) }; return $Code + "`n<!-- $mk -->" }
        default { $i = $Code.LastIndexOf('</body>'); if ($i -ge 0) { return $Code.Substring(0, $i) + "<!-- $mk -->`n" + $Code.Substring($i) }; return $Code.TrimEnd() + "`n<!-- $mk -->`n" }
    }
}

function Get-DrawioPages([string]$Content, [string]$Name) {
    $pages = @([DgImport]::FromDrawio($Content))
    foreach ($pg in $pages) { @{ Name = $(if ($pages.Count -gt 1 -and $pg.Name) { "$Name - $($pg.Name)" } else { $Name }); Text = $pg.Text } }
}

function Import-DiagramFile([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
    $name = [IO.Path]::GetFileNameWithoutExtension($Path)
    $ext = [IO.Path]::GetExtension($Path).ToLowerInvariant()
    if ($ext -in '.csv', '.tsv', '.xlsx', '.xlsm') { Select-ApiTab $DgUI.Tabs 'Data'; Import-DiagramDataFile $Path; return }
    $pages = @(); $why = ''
    try {
        if ($ext -in '.png') {
            $t = [DgImport]::FindSource([DgImport]::PngText($Path, 'devtools-diagram'))
            if ($t) { $pages = @(@{ Name = $name; Text = $t }) }
            else { $mx = [DgImport]::PngText($Path, 'mxfile'); if ($mx) { $pages = @(Get-DrawioPages $mx $name) } else { $why = 'This picture has no diagram inside it. PNGs exported by DevTools (from now on) or by draw.io with "Include a copy of my diagram" do.' } }
        } else {
            $raw = [IO.File]::ReadAllText($Path)
            $src = [DgImport]::FindSource($raw)
            if ($src) { $pages = @(@{ Name = $name; Text = $src }) }
            elseif ([DgImport]::IsDrawio($raw)) { $pages = @(Get-DrawioPages $raw $name) }
            elseif ($ext -in '.dot', '.gv' -or [DgImport]::IsDot($raw)) { $pages = @(@{ Name = $name; Text = [DgImport]::FromDot($raw) }) }
            elseif ($ext -eq '.md') {
                $m = [regex]::Match($raw, '(?ms)^\s*```\s*mermaid\s*\r?\n(.*?)^\s*```')
                if ($m.Success) { $pages = @(@{ Name = $name; Text = $m.Groups[1].Value }) } else { $why = 'There is no ```mermaid block in this Markdown file.' }
            }
            elseif ($ext -in '.svg', '.html', '.htm', '.jsx', '.tsx', '.js') { $why = 'This file has no diagram text inside it. SVG / HTML / React files exported by DevTools from now on carry it, and so do SVGs exported by draw.io.' }
            else { $pages = @(@{ Name = $name; Text = $raw }) }                    # .dgm, .txt, .mmd, .mermaid: diagram text or Mermaid as it is
        }
    } catch { $e0 = $_.Exception; while ($e0.InnerException) { $e0 = $e0.InnerException }; $why = "Couldn't read $(Split-Path -Leaf $Path): $($e0.Message)" }
    if (-not $pages.Count) { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, $why, 'Diagram studio'); return }
    foreach ($pg in $pages) { New-DiagramFromText $pg.Name ($pg.Text -replace '^title Imported from (Graphviz|draw\.io)', "title $($pg.Name)") }     # untitled: the file's name
    Select-ApiTab $DgUI.Tabs 'Text'
    if ($pages.Count -gt 1) { [void][System.Windows.Forms.MessageBox]::Show($DgUI.Form, "$(Split-Path -Leaf $Path) has $($pages.Count) pages: each is now its own diagram in Saved.", 'Diagram studio') }
}

function Open-DiagramImport {
    $d = New-Object System.Windows.Forms.OpenFileDialog
    $d.Title = 'Import a diagram'; $d.Multiselect = $true
    $d.Filter = 'Diagrams|*.dgm;*.txt;*.mmd;*.mermaid;*.md;*.drawio;*.dio;*.xml;*.dot;*.gv;*.svg;*.html;*.htm;*.jsx;*.png;*.csv;*.tsv;*.xlsx|DevTools diagram text|*.dgm;*.txt|Mermaid|*.mmd;*.mermaid;*.md|draw.io / diagrams.net|*.drawio;*.dio;*.xml;*.svg;*.png|Graphviz|*.dot;*.gv|Exports from DevTools|*.svg;*.html;*.htm;*.jsx;*.png|Data (CSV / Excel)|*.csv;*.tsv;*.xlsx|All files|*.*'
    $script:Modal = $true
    try { if ($d.ShowDialog($DgUI.Form) -ne 'OK') { return }; $files = @($d.FileNames) } finally { $script:Modal = $false; $d.Dispose() }
    foreach ($p in $files) { Import-DiagramFile $p }
}

# files dropped anywhere on the window are imported
function Register-DiagramDrop($Control) {
    $Control.AllowDrop = $true
    $Control.add_DragEnter({ param($src, $e) if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { $e.Effect = 'Copy' } })
    # (imported after the drop returns, so Explorer isn't kept waiting)
    $Control.add_DragDrop({ param($src, $e) $DgUI.DropFiles = @($e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop)); if ($DgUI.DropFiles.Count) { [void]$DgUI.Form.BeginInvoke([Action]{ $files = $DgUI.DropFiles; $DgUI.DropFiles = $null; foreach ($p in $files) { Import-DiagramFile $p } }) } })
    foreach ($ch in $Control.Controls) { if ($ch -isnot [System.Windows.Forms.TextBox]) { Register-DiagramDrop $ch } }
}

# ======================================================================================
# SQL client: SQL Server (Windows or SQL login) with nothing to install. Object browser, editor with colours,
# runs in the background (Cancel), results in grids, export, history, saved queries, charts / ER diagrams.
# PostgreSQL and Oracle too, through a driver found on this PC (ODBC, ODP.NET, Npgsql).
# ======================================================================================
$SqlDir = Join-Path $DataDir 'sql'
$SqlUI = @{ Form = $null; Conns = (New-Object System.Collections.Generic.List[object]); Queries = (New-Object System.Collections.Generic.List[object]); History = (New-Object System.Collections.Generic.List[object]); Run = $null; Fl = @{}; FedCap = 200000 }

function Import-SqlData {
    $SqlUI.Conns.Clear(); $SqlUI.Queries.Clear(); $SqlUI.History.Clear()
    foreach ($pair in @(@('connections.json', $SqlUI.Conns), @('queries.json', $SqlUI.Queries), @('history.json', $SqlUI.History))) {
        $p = Join-Path $SqlDir $pair[0]
        if (Test-Path -LiteralPath $p) { try { foreach ($x in @(ConvertFrom-JsonList (Read-DataText $p))) { if ($x) { $pair[1].Add($x) } } } catch { Write-Log "sql $($pair[0]): $_" } }
    }
    Import-SqlFolders
}
function Save-SqlData([string]$What) {
    if ($script:NoSave) { return }
    if (-not (Test-Path -LiteralPath $SqlDir)) { [void](New-Item -ItemType Directory -Path $SqlDir -Force) }
    $items = @(switch ($What) { 'connections' { $SqlUI.Conns } 'queries' { $SqlUI.Queries } default { $SqlUI.History } })     # switch unrolls the list
    $json = ConvertTo-Json -InputObject $items -Depth 5
    if (-not $json -or $json -eq 'null') { $json = '[]' }
    try { Write-JsonFile (Join-Path $SqlDir "$What.json") $json } catch { Write-Log "sql save $What : $_" }
}

# passwords are kept protected for this Windows account (DPAPI)
function Protect-SqlPassword([string]$Pw) { if (-not $Pw) { return '' }; [Convert]::ToBase64String([PowerClipVault]::ProtectForUser([Text.Encoding]::UTF8.GetBytes($Pw))) }
function Unprotect-SqlPassword([string]$Blob) { if (-not $Blob) { return '' }; try { [Text.Encoding]::UTF8.GetString([PowerClipVault]::UnprotectForUser([Convert]::FromBase64String($Blob))) } catch { '' } }

$SqlDriverDir = Join-Path $DataDir 'drivers'
$SqlTypes = [ordered]@{ mssql = 'SQL Server'; pg = 'PostgreSQL'; oracle = 'Oracle' }
function Get-SqlDialect($Conn) { if ($Conn -and $Conn.Type) { [string]$Conn.Type } else { 'mssql' } }
function Get-SqlConnString($Conn, [string]$Db = '') {
    if (-not $Conn) { return $null }
    $d = if ($Db) { $Db } else { [string]$Conn.Database }
    $t = Get-SqlDialect $Conn
    if ($t -ne 'mssql') { return [DgDb]::Build($t, [string]$Conn.Driver, [string]$Conn.Server, $d, [string]$Conn.User, (Unprotect-SqlPassword ([string]$Conn.Pw)), [bool]$Conn.Encrypt, [bool]$Conn.Trust, 15) }
    [DgSql]::Build([string]$Conn.Server, $d, [bool]$Conn.Windows, [string]$Conn.User, (Unprotect-SqlPassword ([string]$Conn.Pw)), [bool]$Conn.Encrypt, [bool]$Conn.Trust, 15)
}
# the database to connect to for listing the databases: SQL Server master, PostgreSQL the connection's own, Oracle any
function Get-SqlListDb($Conn) { switch (Get-SqlDialect $Conn) { 'mssql' { 'master' } 'pg' { if ($Conn.Database) { [string]$Conn.Database } else { 'postgres' } } default { '' } } }
function Get-SqlError($Err) { $e = $Err.Exception; while ($e.InnerException -and ($e -is [System.Management.Automation.MethodInvocationException] -or $e -is [System.Reflection.TargetInvocationException])) { $e = $e.InnerException }; $e.Message }

# ---- the connection dialog
function Edit-SqlConnection($Conn = $null) {
    $f = New-Object System.Windows.Forms.Form
    $f.Text = if ($Conn) { 'Edit connection' } else { 'New connection' }; $f.Icon = $IconActive; $f.StartPosition = 'CenterParent'
    $f.Size = New-Object System.Drawing.Size((Px 560), (Px 720)); $f.FormBorderStyle = 'FixedDialog'; $f.MaximizeBox = $false; $f.MinimizeBox = $false
    $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $p = New-Object System.Windows.Forms.FlowLayoutPanel
    $p.Dock = 'Fill'; $p.FlowDirection = 'TopDown'; $p.WrapContents = $false; $p.AutoScroll = $true; $p.BackColor = $C.Bg; $p.Padding = New-Object System.Windows.Forms.Padding((Px 16), (Px 10), (Px 16), (Px 10))
    $f.Controls.Add($p)
    $st = @{ Form = $f; Panel = $p }
    $box = { param($label, $value, [switch]$pw) $l = New-TbLabel $p $label -Dim; $b = New-TbBox; $b.Width = Px 480; $b.Text = $value; if ($pw) { $b.UseSystemPasswordChar = $true }; $p.Controls.Add($b); $b.Tag = $l; $b }
    $st.Name = & $box 'Name' $(if ($Conn) { $Conn.Name } else { '' })
    New-TbLabel $p 'Database type' -Dim | Out-Null
    $st.Type = New-TbCombo $p @($SqlTypes.Values) 220
    $st.Type.SelectedIndex = [Math]::Max(0, @($SqlTypes.Keys).IndexOf((Get-SqlDialect $Conn)))
    $st.DriverLabel = New-TbLabel $p 'Driver  (found on this PC)' -Dim
    $st.Driver = New-TbCombo $p @() 430
    $st.DriverInfo = New-TbLabel $p '' -Dim; $st.DriverInfo.MaximumSize = New-Object System.Drawing.Size((Px 480), 0)
    $st.Server = & $box 'Server' $(if ($Conn) { $Conn.Server } else { 'localhost' })
    $st.AuthLabel = New-TbLabel $p 'Sign in with' -Dim
    $st.Auth = New-TbCombo $p @('Windows account', 'SQL Server login') 220
    $st.Auth.SelectedIndex = if ($Conn -and -not $Conn.Windows -and (Get-SqlDialect $Conn) -eq 'mssql') { 1 } else { 0 }
    $st.User = & $box 'User' $(if ($Conn) { $Conn.User } else { '' })
    $st.Pw = & $box 'Password  (kept protected for your Windows account)' $(if ($Conn) { Unprotect-SqlPassword $Conn.Pw } else { '' }) -pw
    $st.DbLabel = New-TbLabel $p 'Database' -Dim
    $dbrow = New-Object System.Windows.Forms.FlowLayoutPanel; $dbrow.AutoSize = $true; $dbrow.WrapContents = $false; $dbrow.BackColor = $C.Bg
    $st.Db = New-Object System.Windows.Forms.ComboBox; $st.Db.DropDownStyle = 'DropDown'; $st.Db.FlatStyle = 'Flat'; $st.Db.BackColor = $C.Bg; $st.Db.ForeColor = $C.Fore; $st.Db.Width = Px 300
    $st.Db.Text = if ($Conn) { $Conn.Database } else { 'master' }
    $dbrow.Controls.Add($st.Db)
    $p.Controls.Add($dbrow)
    $st.Encrypt = New-CheckBox $p 'Encrypt the connection' $(if ($Conn) { [bool]$Conn.Encrypt } else { $false })
    $st.Trust = New-CheckBox $p 'Trust the server certificate (self-signed)' $(if ($Conn) { [bool]$Conn.Trust } else { $true })
    $st.Confirm = New-CheckBox $p 'Ask before running statements that change data (INSERT, UPDATE, DELETE, DROP ...)' $(if ($Conn) { $Conn.Confirm -ne $false } else { $true })
    foreach ($cb in $st.Encrypt, $st.Trust, $st.Confirm) { $cb.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0); $cb.MaximumSize = New-Object System.Drawing.Size((Px 480), 0) }
    $st.Info = New-TbLabel $p '' -Dim; $st.Info.MaximumSize = New-Object System.Drawing.Size((Px 480), 0)
    $st.TypeKey = { param($s) @($SqlTypes.Keys)[[Math]::Max(0, $s.Type.SelectedIndex)] }
    $st.DriverId = { param($s) $i = $s.Driver.SelectedIndex; if ($i -ge 0 -and $s.DriverIds -and $i -lt $s.DriverIds.Count) { $s.DriverIds[$i] } else { '' } }
    # shows what the database type needs, and the drivers found for it
    $st.Apply = {
        param($s, [string]$Keep = '')
        $t = & $s.TypeKey $s
        $other = $t -ne 'mssql'
        $s.DriverLabel.Visible = $other; $s.Driver.Visible = $other; $s.DriverInfo.Visible = $other
        $s.AuthLabel.Visible = -not $other; $s.Auth.Visible = -not $other
        $s.Encrypt.Visible = $t -ne 'oracle'; $s.Trust.Visible = $t -ne 'oracle'
        $s.Encrypt.Text = if ($t -eq 'pg') { 'Use SSL (sslmode=require)' } else { 'Encrypt the connection' }
        $s.Server.Tag.Text = switch ($t) { 'pg' { 'Server   (host, or host:port; the port is 5432 when left out)' } 'oracle' { 'Server   (host:port/service, e.g. dbhost:1521/ORCLPDB1, or a TNS alias)' } default { 'Server   (localhost, .\SQLEXPRESS, (localdb)\MSSQLLocalDB, server.domain.com,1433)' } }
        $s.DbLabel.Text = switch ($t) { 'oracle' { 'Schema   (empty = your own)' } default { 'Database' } }
        $s.Panel.PerformLayout()
        if (-not $other) { return }
        $list = @([DgDb]::Drivers($t, $SqlDriverDir))
        $s.DriverIds = @($list | ForEach-Object { $_[0] })
        $s.Driver.Items.Clear(); foreach ($x in $list) { [void]$s.Driver.Items.Add($x[1]) }
        if ($list.Count) {
            $k = [Math]::Max(0, [Array]::IndexOf($s.DriverIds, $Keep))
            $s.Driver.SelectedIndex = $k
            $s.DriverInfo.Text = ''
        } else {
            $s.DriverInfo.ForeColor = $C.Yellow
            $s.DriverInfo.Text = if ($t -eq 'pg') { "No PostgreSQL driver found on this PC. Install the PostgreSQL ODBC driver (psqlODBC, 64-bit) from postgresql.org, or put Npgsql.dll (with the DLLs it needs) into $SqlDriverDir, then open this window again." } else { "No Oracle driver found on this PC. Install the Oracle Instant Client with its ODBC driver, or put Oracle.ManagedDataAccess.dll (ODP.NET managed, for .NET Framework) into $SqlDriverDir, then open this window again." }
        }
    }
    $st.Type.add_SelectionChangeCommitted({
        param($src, $e)
        $s = $src.FindForm().Tag
        $t = & $s.TypeKey $s
        if (-not $s.Server.Text.Trim() -or $s.Server.Text -in 'localhost', 'localhost:5432', 'localhost:1521/FREEPDB1') { $s.Server.Text = switch ($t) { 'pg' { 'localhost:5432' } 'oracle' { 'localhost:1521/FREEPDB1' } default { 'localhost' } } }
        if (-not $s.Db.Text.Trim() -or $s.Db.Text -in 'master', 'postgres') { $s.Db.Text = switch ($t) { 'pg' { 'postgres' } 'oracle' { '' } default { 'master' } } }
        & $s.Apply $s
    })
    $st.Make = { param($s) $t = & $s.TypeKey $s
        [pscustomobject]@{ Name = $(if ($s.Name.Text.Trim()) { $s.Name.Text.Trim() } else { $s.Server.Text.Trim() }); Type = $t; Driver = (& $s.DriverId $s); Server = $s.Server.Text.Trim(); Database = $s.Db.Text.Trim(); Windows = ($t -eq 'mssql' -and $s.Auth.SelectedIndex -eq 0)
                           User = $s.User.Text.Trim(); Pw = (Protect-SqlPassword $s.Pw.Text); Encrypt = $s.Encrypt.Checked; Trust = $s.Trust.Checked; Confirm = $s.Confirm.Checked } }
    $f.Tag = $st
    & $st.Apply $st $(if ($Conn) { [string]$Conn.Driver } else { '' })
    [void](New-Button 'Databases' 'Connect and list the databases (Oracle: the schemas)' {
        $s = $this.FindForm().Tag; $c0 = & $s.Make $s
        if ($c0.Type -ne 'mssql' -and -not $c0.Driver) { $s.Info.Text = 'Pick a driver first.'; $s.Info.ForeColor = $C.Red; return }
        $s.Form.Cursor = 'WaitCursor'
        try {
            $t = [DgDb]::Databases((Get-SqlConnString $c0 (Get-SqlListDb $c0)))
            $cur = $s.Db.Text; $s.Db.Items.Clear(); foreach ($r in $t.Rows) { [void]$s.Db.Items.Add([string]$r[0]) }; $s.Db.Text = $cur
            $s.Info.Text = "Connected: $($t.Rows.Count) $(if ($c0.Type -eq 'oracle') { 'schemas' } else { 'databases' })."; $s.Info.ForeColor = $C.Green
            $s.Db.DroppedDown = $true
        } catch { $s.Info.Text = Get-SqlError $_; $s.Info.ForeColor = $C.Red } finally { $s.Form.Cursor = 'Default' }
    } $dbrow $Glyph.Refresh 2)
    $bar = New-Object System.Windows.Forms.FlowLayoutPanel; $bar.Dock = 'Bottom'; $bar.AutoSize = $true; $bar.BackColor = $C.Panel; $bar.Padding = New-Object System.Windows.Forms.Padding((Px 12), (Px 8), (Px 12), (Px 8)); $bar.FlowDirection = 'RightToLeft'
    $f.Controls.Add($bar)
    [void](New-Button 'Cancel' '' { $this.FindForm().DialogResult = 'Cancel' } $bar '' 2)
    [void](New-Button 'Save' 'Save the connection' {
        $s = $this.FindForm().Tag
        if (-not $s.Server.Text.Trim()) { $s.Info.Text = 'The server is needed.'; $s.Info.ForeColor = $C.Red; return }
        $s.Result = & $s.Make $s; $this.FindForm().DialogResult = 'OK'
    } $bar $Glyph.Save 1)
    [void](New-Button 'Test' 'Try to connect' {
        $s = $this.FindForm().Tag; $c0 = & $s.Make $s
        if ($c0.Type -ne 'mssql' -and -not $c0.Driver) { $s.Info.Text = 'Pick a driver first.'; $s.Info.ForeColor = $C.Red; return }
        $s.Form.Cursor = 'WaitCursor'
        $q = switch ($c0.Type) {
            'pg' { 'SELECT inet_server_addr()::text, current_database(), current_user, version()' }
            'oracle' { "SELECT SYS_CONTEXT('USERENV', 'SERVER_HOST'), SYS_CONTEXT('USERENV', 'DB_NAME') || ' / ' || SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA'), USER, SYS_CONTEXT('USERENV', 'DB_UNIQUE_NAME') FROM dual" }
            default { 'SELECT @@SERVERNAME, DB_NAME(), SUSER_SNAME(), ''SQL Server '' + CAST(SERVERPROPERTY(''ProductVersion'') AS varchar(40))' }
        }
        try { $t = [DgSql]::Query((Get-SqlConnString $c0), $q, 15); $r = $t.Rows[0]; $s.Info.Text = "Connected to $($r[0]), database $($r[1]) as $($r[2]) ($(([string]$r[3]) -replace ',.*$', ''))."; $s.Info.ForeColor = $C.Green }
        catch { $s.Info.Text = Get-SqlError $_; $s.Info.ForeColor = $C.Red } finally { $s.Form.Cursor = 'Default' }
    } $bar $Glyph.Play 2)
    Register-ThemedWindow $f
    $script:Modal = $true
    try { if ($f.ShowDialog($SqlUI.Form) -eq 'OK') { return $st.Result } } finally { $script:Modal = $false; $f.Dispose() }
    $null
}

function Update-SqlConnList([string]$Select = '') {
    $cb = $SqlUI.ConnBox
    $cb.Items.Clear()
    $i = 0
    for ($k = 0; $k -lt $SqlUI.Conns.Count; $k++) {
        $c0 = $SqlUI.Conns[$k]
        [void]$cb.Items.Add($(if ($c0.Folder) { "$(([string]$c0.Folder).Replace('/', ' > ')) > $($c0.Name)" } else { $c0.Name }))
        if ($Select -and $c0.Name -eq $Select) { $i = $k }
    }
    [void]$cb.Items.Add('New connection...')
    if ($SqlUI.Conns.Count) { $cb.SelectedIndex = $i; $SqlUI.ConnName = $SqlUI.Conns[$i].Name } else { $cb.SelectedIndex = -1; $SqlUI.ConnName = '' }
    if ($SqlUI.Fl.connections) { $SqlUI.Fl.connections.List.Invalidate() }
}
function Get-SqlConn { $i = $SqlUI.ConnBox.SelectedIndex; if ($i -ge 0 -and $i -lt $SqlUI.Conns.Count) { $SqlUI.Conns[$i] } else { $null } }

# ---- object browser (SQL Server, PostgreSQL: databases; Oracle: schemas)
function Update-SqlTree {
    $tv = $SqlUI.Tree; $tv.Nodes.Clear()
    $c0 = Get-SqlConn
    if (-not $c0) { return }
    $dl = Get-SqlDialect $c0
    $root = $tv.Nodes.Add("$([string]$c0.Server)$(if ($dl -ne 'mssql') { "   ($($SqlTypes[$dl]))" })"); $root.Tag = @{ Kind = 'server' }
    if ($dl -ne 'mssql' -and -not $c0.Driver) { $n = $root.Nodes.Add('No driver: edit the connection and pick one.'); $n.ForeColor = $C.Red; $root.Expand(); return }
    try {
        $t = [DgDb]::Databases((Get-SqlConnString $c0 (Get-SqlListDb $c0)))
        foreach ($r in $t.Rows) { $n = $root.Nodes.Add([string]$r[0]); $n.Tag = @{ Kind = 'db'; Db = [string]$r[0] }; [void]$n.Nodes.Add('...') }
        $root.Expand()
        $want = if ($SqlUI.DbBox.Text) { [string]$SqlUI.DbBox.Text } else { '' }
        $cur = @($root.Nodes | Where-Object { $_.Text -eq $want }) | Select-Object -First 1
        if (-not $cur -and $dl -eq 'oracle' -and $root.Nodes.Count) { $cur = $root.Nodes[0] }       # your own schema comes first
        if ($cur) { $cur.Expand() }
    } catch { $n = $root.Nodes.Add("Can't connect: $(Get-SqlError $_)"); $n.ForeColor = $C.Red }
    if ($SqlUI.TreeFilter -and $SqlUI.TreeFilter.Text.Trim()) { Update-SqlTreeFilter }
}
function Expand-SqlNode($Node) {
    $tg = $Node.Tag
    if (-not $tg -or $Node.Nodes.Count -ne 1 -or $Node.Nodes[0].Text -ne '...') { return }
    $Node.Nodes.Clear()
    $c0 = Get-SqlConn
    try {
        switch ($tg.Kind) {
            'db' {
                foreach ($k in @(@('Tables', 'U'), @('Views', 'V'), @('Procedures', 'P'), @('Functions', 'FN'))) { $n = $Node.Nodes.Add($k[0]); $n.Tag = @{ Kind = 'folder'; Db = $tg.Db; Type = $k[1] }; [void]$n.Nodes.Add('...') }
            }
            'folder' {
                $rows = Get-SqlObjectList $c0 $tg.Db $tg.Type
                foreach ($r in $rows) { [void](Add-SqlObjectNode $Node $r[0] $r[1] $tg.Db $tg.Type) }
                if ($rows.Count -eq 0) { $e = $Node.Nodes.Add('(none)'); $e.ForeColor = $C.Dim }
            }
            'object' {
                $t = [DgDb]::Columns((Get-SqlConnString $c0 $tg.Db), $tg.Schema, $tg.Object)
                foreach ($r in $t.Rows) {
                    $keys = (@($(if ($r['pk'] -eq 1) { 'PK' }), $(if ($r['fk'] -eq 1) { 'FK' })) | Where-Object { $_ }) -join ' '
                    $n = $Node.Nodes.Add("$($r['col'])   $($r['typ'])$(if ($keys) { "  $keys" })$(if ($r['nul'] -eq 0) { '  not null' })"); $n.Tag = @{ Kind = 'column'; Name = [string]$r['col'] }
                    if ($keys) { $n.ForeColor = $C.Accent }
                }
            }
        }
    } catch { $n = $Node.Nodes.Add((Get-SqlError $_)); $n.ForeColor = $C.Red }
}

function Insert-SqlText([string]$Text) { $ed = $SqlUI.Editor; $ed.SelectedText = $Text; $ed.Focus() }
function ConvertTo-SqlName([string]$Full) { [DgDb]::QuoteName((Get-SqlDialect (Get-SqlConn)), $Full) }
# the first rows of a table / view, and its definition, the way each database writes it
function Get-SqlTopSql($Obj) {
    $n = ConvertTo-SqlName $Obj.Name
    switch (Get-SqlDialect (Get-SqlConn)) { 'pg' { "SELECT *`r`nFROM $n`r`nLIMIT 100;" } 'oracle' { "SELECT *`r`nFROM $n`r`nFETCH FIRST 100 ROWS ONLY" } default { "SELECT TOP 100 *`r`nFROM $n;" } }
}
function Get-SqlScriptSql($Obj) {
    $s = $Obj.Schema -replace "'", "''"; $o = $Obj.Object -replace "'", "''"
    switch (Get-SqlDialect (Get-SqlConn)) {
        'pg' {
            switch ($Obj.Type) {
                'U' { "SELECT column_name, data_type, character_maximum_length, is_nullable, column_default`r`nFROM information_schema.columns WHERE table_schema = '$s' AND table_name = '$o'`r`nORDER BY ordinal_position;" }
                'V' { "SELECT pg_get_viewdef('$(ConvertTo-SqlName $Obj.Name)'::regclass, true) AS definition;" }
                default { "SELECT pg_get_functiondef(p.oid) AS definition`r`nFROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace`r`nWHERE n.nspname = '$s' AND p.proname = '$o';" }
            }
        }
        'oracle' { "SELECT DBMS_METADATA.GET_DDL(object_type, object_name, owner) AS ddl`r`nFROM all_objects`r`nWHERE owner = '$s' AND object_name = '$o' AND object_type IN ('TABLE', 'VIEW', 'PROCEDURE', 'PACKAGE', 'FUNCTION')" }
        default { if ($Obj.Type -eq 'U') { "SELECT c.name, TYPE_NAME(c.user_type_id) AS type, c.max_length, c.is_nullable, c.is_identity`r`nFROM sys.columns c WHERE c.object_id = OBJECT_ID('$($Obj.Name -replace "'", "''")')`r`nORDER BY c.column_id;" } else { "SELECT OBJECT_DEFINITION(OBJECT_ID('$($Obj.Name -replace "'", "''")')) AS definition;" } }
    }
}

# ---- run
function Start-SqlRun {
    if ($SqlUI.Run -and -not $SqlUI.Run.Done) { return }
    $c0 = Get-SqlConn
    if (-not $c0) { Set-SqlStatus 'Add a connection first (the list at the top left).' $C.Red; return }
    $ed = $SqlUI.Editor
    $sql = if ($ed.SelectionLength -gt 0) { $ed.SelectedText } else { $ed.Text }
    if (-not $sql.Trim()) { return }
    # a query whose tables name other saved connections or files: each source runs its part, the join happens here
    $names = @($SqlUI.Conns | ForEach-Object { [string]$_.Name })
    if ([DgFedRun]::IsFederated($sql, [string[]]$names)) {
        $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach ($cx in $SqlUI.Conns) { if ($cx.Name -and -not $map.ContainsKey([string]$cx.Name)) { $map[[string]$cx.Name] = Get-SqlConnString $cx } }
        $map[''] = Get-SqlConnString $c0 $SqlUI.DbBox.Text
        $SqlUI.RunSql = $sql; $SqlUI.TextPlan = $false
        $SqlUI.Run = [DgFedRun]::Start($sql, $map, [int]$SqlUI.FedCap, [int]$SqlUI.MaxRows.Value)
        $SqlUI.RunBtn.Enabled = $false; $SqlUI.CancelBtn.Enabled = $true
        Set-SqlStatus 'Running across sources...' $C.Accent
        $SqlUI.Started = Get-Date
        $SqlUI.Timer.Start()
        return
    }
    $w = [DgSql]::Writes($sql, (Get-SqlDialect $c0))
    if ($w -and $c0.Confirm -ne $false) {
        if ([System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "This changes data or objects ($w) on $($c0.Name) / $($SqlUI.DbBox.Text).`n`nRun it?", 'SQL client', 'YesNo', 'Warning') -ne 'Yes') { return }
    }
    $SqlUI.RunSql = $sql
    $SqlUI.TextPlan = $false
    $SqlUI.Run = [DgSqlRun]::Start((Get-SqlConnString $c0 $SqlUI.DbBox.Text), $sql, [int]$SqlUI.MaxRows.Value, 0)
    $SqlUI.RunBtn.Enabled = $false; $SqlUI.CancelBtn.Enabled = $true
    Set-SqlStatus 'Running...' $C.Accent
    $SqlUI.Started = Get-Date
    $SqlUI.Timer.Start()
}

function Complete-SqlRun {
    $r = $SqlUI.Run.Result
    $SqlUI.RunBtn.Enabled = $true; $SqlUI.CancelBtn.Enabled = $false
    Show-SqlResults $r
    if ($SqlUI.TextPlan) {
        $SqlUI.TextPlan = $false
        $n = $r.Tables.Count
        if ($n -gt 0 -and -not $r.Error) { Select-ApiTab $SqlUI.ResTabs "Result $n  ($($r.Tables[$n - 1].Rows.Count))"; Set-SqlStatus "The plan is in Result $n." $C.Green }
    }
}

function Show-SqlResults($r, $Plan = $null) {
    $tabs = $SqlUI.ResTabs
    foreach ($k in @($tabs.Panels.Keys)) { $p = $tabs.Panels[$k]; foreach ($ctl in @($p.Controls)) { $ctl.Dispose() }; $tabs.Host.Controls.Remove($p); $tabs.Strip.Controls.Remove($tabs.Buttons[$k]); $tabs.Buttons[$k].Dispose(); $p.Dispose() }
    $tabs.Panels.Clear(); $tabs.Buttons.Clear()
    $SqlUI.Tables = @($r.Tables)
    $SqlUI.GridState = @{}
    $i = 0; $first = ''
    foreach ($t in $r.Tables) {
        $i++
        $name = "Result $i  ($($t.Rows.Count))"
        $p = Add-ApiTab $tabs $name
        $g = New-SqlGrid $p; $g.DataSource = $t; $g.Tag = $t
        if (-not $first) { $first = $name }
    }
    $mp = Add-ApiTab $tabs 'Messages'
    $mb = New-TbRtb -ReadOnly; $mb.Dock = 'Fill'
    $lines = @($r.Messages) + $(if ($r.Error) { "Error: $($r.Error)" }) + $(if ($r.Cancelled) { 'Cancelled.' }) + $(if ($r.Truncated) { "Only the first $($SqlUI.MaxRows.Value) rows of a result are shown (Max rows)." })
    $mb.Text = (@($lines | Where-Object { $_ }) -join "`r`n")
    if ($r.Error) { $mb.ForeColor = $C.Red }
    $mp.Controls.Add($mb)
    if ($Plan) { Add-SqlPlanTab $Plan }
    Select-ApiTab $tabs $(if ($Plan -and $Plan.Ops.Count) { 'Plan' } elseif ($first -and -not $r.Error) { $first } else { 'Messages' })
    $rows = 0; foreach ($tt in $r.Tables) { $rows += $tt.Rows.Count }
    if ($r.Error) {
        Set-SqlStatus $r.Error $C.Red
        if ($r.ErrorLine -gt 0 -and $SqlUI.Editor.SelectionLength -eq 0) {
            $ln = $r.ErrorLine - 1; if ($ln -lt $SqlUI.Editor.Lines.Count) { $s0 = $SqlUI.Editor.GetFirstCharIndexFromLine($ln); $SqlUI.Editor.Select($s0, $SqlUI.Editor.Lines[$ln].Length) }
        }
    } elseif ($r.Cancelled) { Set-SqlStatus "Cancelled after $([Math]::Round($r.Ms / 1000, 1)) s." $C.Yellow }
    else { Set-SqlStatus "$($r.Tables.Count) result$(if ($r.Tables.Count -ne 1) { 's' }), $rows row$(if ($rows -ne 1) { 's' })  -  $(if ($r.Ms -lt 1000) { "$($r.Ms) ms" } else { "$([Math]::Round($r.Ms / 1000, 2)) s" })$(if ($r.Truncated) { '  (rows cut at Max rows)' })" $C.Green }
    # history
    $c0 = Get-SqlConn
    $SqlUI.History.Insert(0, [pscustomobject]@{ Time = (Get-Date).ToString('o'); Conn = $(if ($c0) { $c0.Name } else { '' }); Db = $SqlUI.DbBox.Text; Sql = $SqlUI.RunSql; Rows = [int]$rows; Ms = $r.Ms; Ok = -not $r.Error })
    while ($SqlUI.History.Count -gt 200) { $SqlUI.History.RemoveAt($SqlUI.History.Count - 1) }
    Save-SqlData 'history'
    Update-SqlSideLists
}

function New-SqlGrid($Parent) {
    $g = New-Object System.Windows.Forms.DataGridView
    $g.Dock = 'Fill'; $g.BorderStyle = 'None'; $g.BackgroundColor = $C.Bg; $g.GridColor = $C.Line
    $g.RowHeadersVisible = $false; $g.EnableHeadersVisualStyles = $false
    $g.ColumnHeadersDefaultCellStyle.BackColor = $C.Panel; $g.ColumnHeadersDefaultCellStyle.ForeColor = $C.Dim
    $g.ColumnHeadersDefaultCellStyle.SelectionBackColor = $C.Panel; $g.ColumnHeadersDefaultCellStyle.Font = $FontSmall
    $g.ColumnHeadersBorderStyle = 'Single'; $g.ColumnHeadersHeight = Px 28
    $g.DefaultCellStyle.BackColor = $C.Bg; $g.DefaultCellStyle.ForeColor = $C.Fore; $g.DefaultCellStyle.Font = New-Object System.Drawing.Font('Consolas', (Fz 10))
    $g.DefaultCellStyle.SelectionBackColor = $C.Sel; $g.DefaultCellStyle.SelectionForeColor = $C.Fore
    $g.DefaultCellStyle.NullValue = 'NULL'
    $g.RowTemplate.Height = Px 24; $g.AllowUserToResizeRows = $false; $g.AutoSizeColumnsMode = 'None'
    $g.CellBorderStyle = 'SingleHorizontal'; $g.SelectionMode = 'CellSelect'
    $g.ReadOnly = $true; $g.AllowUserToAddRows = $false; $g.AllowUserToDeleteRows = $false
    $g.ClipboardCopyMode = 'EnableAlwaysIncludeHeaderText'
    $g.add_CellFormatting({ param($src, $e) if ($e.Value -is [DBNull]) { $e.CellStyle.ForeColor = $C.Dim } })
    Register-SqlGridMenu $g
    $g.add_DataBindingComplete({ param($src, $e) foreach ($col in $src.Columns) { $col.Width = [Math]::Min($(if ($src.Columns.Count -eq 1) { Px 1600 } else { Px 360 }), [Math]::Max([Math]::Max((Px 70), $col.GetPreferredWidth('AllCellsExceptHeader', $true) + (Px 12)), $col.GetPreferredWidth('ColumnHeader', $true))) } })
    $Parent.Controls.Add($g)
    $g
}

function Set-SqlStatus([string]$Text, $Color) { $SqlUI.Status.Text = $Text; $SqlUI.Status.ForeColor = $Color }
function Get-SqlCurrentTable {
    $tabs = $SqlUI.ResTabs
    $p = $tabs.Panels[$tabs.Current]
    if (-not $p) { return $null }
    $g = @($p.Controls | Where-Object { $_ -is [System.Windows.Forms.DataGridView] }) | Select-Object -First 1
    if ($g) { , $g.Tag } else { $null }     # the comma keeps PowerShell from turning the table into its rows
}

function Export-SqlResult([string]$As) {
    $t = Get-SqlCurrentTable
    if (-not $t) { Set-SqlStatus 'Run a query that returns rows first.' $C.Yellow; return }
    if ($As -eq 'copy') { [System.Windows.Forms.Clipboard]::SetText([DgSql]::ToCsv($t, "`t")); Set-SqlStatus "Copied $($t.Rows.Count) rows with headers (paste into Excel)." $C.Green; return }
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = if ($As -eq 'json') { 'JSON|*.json' } else { 'CSV|*.csv' }; $d.FileName = "result.$As"
    $script:Modal = $true
    try { if ($d.ShowDialog($SqlUI.Form) -ne 'OK') { return }; $path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    $text = if ($As -eq 'json') { [DgSql]::ToJson($t) } else { [DgSql]::ToCsv($t, ',') }
    [IO.File]::WriteAllText($path, $text, (New-Object System.Text.UTF8Encoding $true))
    Set-SqlStatus "Saved $($t.Rows.Count) rows to $(Split-Path -Leaf $path)." $C.Green
}

# the current result into the Diagram studio's Data tab (chart, links or tree)
function Send-SqlToDiagram([int]$Kind) {
    $t = Get-SqlCurrentTable
    if (-not $t) { Set-SqlStatus 'Run a query that returns rows first.' $C.Yellow; return }
    $csv = [DgSql]::ToCsv($t, ',')
    Show-DiagramStudio
    if (-not $DgUI.Data) { return }
    Select-ApiTab $DgUI.Tabs 'Data'
    $first = ($SqlUI.RunSql -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 1)
    $DgUI.Data.Name = if ($first) { ($first.Trim() -replace '\s+', ' ').Substring(0, [Math]::Min(40, ($first.Trim() -replace '\s+', ' ').Length)) } else { 'Query' }
    $DgUI.Data.Box.Text = $csv
    Update-DiagramDataColumns
    $DgUI.Data.Kind.SelectedIndex = $Kind
}

function New-SqlErDiagram([string[]]$Tables = $null) {
    $c0 = Get-SqlConn
    if (-not $c0) { return }
    $db = $SqlUI.DbBox.Text
    $SqlUI.Form.Cursor = 'WaitCursor'
    try { $text = [DgSql]::ErText((Get-SqlConnString $c0 $db), $db, $Tables, [bool]$Tables) }
    catch { Set-SqlStatus "Couldn't read the tables: $($_.Exception.InnerException.Message)" $C.Red; return } finally { $SqlUI.Form.Cursor = 'Default' }
    Show-DiagramStudio
    New-DiagramFromText "$db tables" $text
}

function Update-SqlSideLists {
    $l = $SqlUI.HistList
    if ($l) { $l.BeginUpdate(); $l.Items.Clear(); foreach ($h in $SqlUI.History) { $t = ($h.Sql -replace '\s+', ' ').Trim(); [void]$l.Items.Add("$(if (-not $h.Ok) { '! ' })$($t.Substring(0, [Math]::Min(90, $t.Length)))") }; $l.EndUpdate() }
    foreach ($k in 'queries', 'connections') { if ($SqlUI.Fl[$k]) { Update-DvFolderList $SqlUI.Fl[$k] } }
}

# ---- query plan tuner: the plan (estimated, or actual by running it) drawn, with suggestions and fixes
function Start-SqlPlan([bool]$Actual) {
    if (($SqlUI.Run -and -not $SqlUI.Run.Done) -or ($SqlUI.PlanRun -and -not $SqlUI.PlanRun.Done)) { return }
    $c0 = Get-SqlConn
    if (-not $c0) { Set-SqlStatus 'Add a connection first (the list at the top left).' $C.Red; return }
    $ed = $SqlUI.Editor
    $sql = if ($ed.SelectionLength -gt 0) { $ed.SelectedText } else { $ed.Text }
    if (-not $sql.Trim()) { return }
    if ((Get-SqlDialect $c0) -ne 'mssql') { Start-SqlTextPlan $c0 $sql $Actual; return }
    if ($Actual) {
        $w = [DgSql]::Writes($sql, (Get-SqlDialect $c0))
        if ($w -and $c0.Confirm -ne $false -and [System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "Getting the actual plan runs the query, and it changes data or objects ($w).`n`nRun it?", 'SQL client', 'YesNo', 'Warning') -ne 'Yes') { return }
    }
    $SqlUI.RunSql = $sql
    $SqlUI.PlanRun = [DgPlanRun]::Start((Get-SqlConnString $c0 $SqlUI.DbBox.Text), $sql, $Actual, [int]$SqlUI.MaxRows.Value)
    $SqlUI.RunBtn.Enabled = $false; $SqlUI.CancelBtn.Enabled = $true
    Set-SqlStatus $(if ($Actual) { 'Running with the plan...' } else { 'Asking for the plan (the query is not run)...' }) $C.Accent
    $SqlUI.Started = Get-Date
    $SqlUI.PlanTimer.Start()
}

# PostgreSQL EXPLAIN / Oracle DBMS_XPLAN of one statement (the selected one, or the one the cursor is in), shown as text
function Start-SqlTextPlan($Conn, [string]$Sql, [bool]$Actual) {
    $dl = Get-SqlDialect $Conn
    $ed = $SqlUI.Editor
    $sts = @([DgDb]::Statements($dl, $Sql))
    if (-not $sts.Count) { return }
    $one = $sts[0].Value
    if ($sts.Count -gt 1 -and $ed.SelectionLength -eq 0) { $line = $ed.GetLineFromCharIndex($ed.SelectionStart); foreach ($kv in $sts) { if ($kv.Key -le $line) { $one = $kv.Value } } }
    if ($Actual) {
        $w = [DgSql]::Writes($one, $dl)
        if ($w -and $Conn.Confirm -ne $false -and [System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "Getting the actual plan runs the statement, and it changes data or objects ($w).`n`nRun it?", 'SQL client', 'YesNo', 'Warning') -ne 'Yes') { return }
    }
    $SqlUI.RunSql = $one
    $SqlUI.TextPlan = $true
    $SqlUI.Run = [DgSqlRun]::Start((Get-SqlConnString $Conn $SqlUI.DbBox.Text), [DgDb]::PlanSql($dl, $one, $Actual), [int]$SqlUI.MaxRows.Value, 0)
    $SqlUI.RunBtn.Enabled = $false; $SqlUI.CancelBtn.Enabled = $true
    Set-SqlStatus $(if ($Actual) { 'Running with the plan...' } else { 'Asking for the plan (the statement is not run)...' }) $C.Accent
    $SqlUI.Started = Get-Date
    $SqlUI.Timer.Start()
}

function Complete-SqlPlan {
    $p = $SqlUI.PlanRun.Report
    $SqlUI.RunBtn.Enabled = $true; $SqlUI.CancelBtn.Enabled = $false
    $SqlUI.Plan = $p
    Show-SqlResults $p.Result $p
    if ($p.Error) { Set-SqlStatus $p.Error $C.Red }
    elseif (-not $p.Ops.Count) { Set-SqlStatus 'No plan came back (only SELECT / INSERT / UPDATE / DELETE statements have one).' $C.Yellow }
    else {
        $high = @($p.Tips | Where-Object { $_.Level -ge 3 }).Count
        Set-SqlStatus "$(if ($p.Actual) { 'Actual' } else { 'Estimated' }) plan: $($p.Ops.Count) steps, cost $([Math]::Round($p.TotalCost, 3)), $(@($p.Tips | Where-Object { $_.Level -gt 0 }).Count) suggestion(s)$(if ($high) { ", $high important" })" $(if ($high) { $C.Yellow } else { $C.Green })
    }
}

function Add-SqlPlanTab($Plan) {
    $tabs = $SqlUI.ResTabs
    $pp = Add-ApiTab $tabs 'Plan'
    $sp = New-Object System.Windows.Forms.SplitContainer
    $sp.Dock = 'Fill'; $sp.Orientation = 'Vertical'; $sp.SplitterWidth = 5; $sp.BackColor = $C.Line; $sp.Panel1.BackColor = $C.Bg; $sp.Panel2.BackColor = $C.Bg
    $pp.Controls.Add($sp)
    # suggestions
    $fl = New-Object System.Windows.Forms.FlowLayoutPanel
    $fl.Dock = 'Fill'; $fl.FlowDirection = 'TopDown'; $fl.WrapContents = $false; $fl.AutoScroll = $true; $fl.BackColor = $C.Bg; $fl.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 8), (Px 10), (Px 8))
    $sp.Panel1.Controls.Add($fl)
    $wid = Px 440
    $hd = New-TbLabel $fl 'Suggestions' -Title
    foreach ($tip in $Plan.Tips) {
        $t1 = New-TbLabel $fl $(switch ($tip.Level) { 3 { "!!  $($tip.Title)" } 2 { "!  $($tip.Title)" } 0 { $tip.Title } default { $tip.Title } })
        $t1.Font = New-Object System.Drawing.Font($UiFont, (Fz 10), [System.Drawing.FontStyle]::Bold)
        $t1.ForeColor = switch ($tip.Level) { 3 { $C.Red } 2 { $C.Orange } 0 { $C.Green } default { $C.Accent } }
        $t1.MaximumSize = New-Object System.Drawing.Size($wid, 0); $t1.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, (Px 2))
        if ($tip.Detail) { $t2 = New-TbLabel $fl $tip.Detail -Dim; $t2.MaximumSize = New-Object System.Drawing.Size($wid, 0) }
        if ($tip.Fix) {
            $fx = New-TbBox -Mono -Multi -ReadOnly; $fx.Text = $tip.Fix; $fx.Width = $wid; $fx.Height = [Math]::Min((Px 120), ($fx.Font.Height * (@($tip.Fix -split "`r?`n").Count + 1)) + (Px 6)); $fx.ScrollBars = 'Vertical'
            $fl.Controls.Add($fx)
            $row = New-Object System.Windows.Forms.FlowLayoutPanel; $row.AutoSize = $true; $row.BackColor = $C.Bg; $row.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), 0, 0)
            $b1 = New-Button 'Copy' 'Copy the fix' { [System.Windows.Forms.Clipboard]::SetText($this.Tag); Set-SqlStatus 'Copied.' $C.Green } $row $Glyph.Copy 2; $b1.Tag = $tip.Fix
            $b2 = New-Button 'Into the editor' 'Add the fix at the end of the editor (it is not run)' { $ed = $SqlUI.Editor; $ed.AppendText("`r`n`r`n" + $this.Tag); $ed.Select($ed.TextLength - $this.Tag.Length, $this.Tag.Length); $ed.ScrollToCaret(); $ed.Focus() } $row $Glyph.Paste 2; $b2.Tag = $tip.Fix
            $fl.Controls.Add($row)
        }
    }
    if ($Plan.Statement) { $st = New-TbLabel $fl "Most expensive statement: $($Plan.Statement.Substring(0, [Math]::Min(300, $Plan.Statement.Length)))" -Dim; $st.MaximumSize = New-Object System.Drawing.Size($wid, 0); $st.Margin = New-Object System.Windows.Forms.Padding(0, (Px 14), 0, 0) }
    # the plan drawn
    $right = New-Object System.Windows.Forms.Panel; $right.Dock = 'Fill'; $right.BackColor = $C.Bg
    $sp.Panel2.Controls.Add($right)
    $bar = New-Object System.Windows.Forms.FlowLayoutPanel; $bar.Dock = 'Top'; $bar.AutoSize = $true; $bar.BackColor = $C.Panel; $bar.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 3), (Px 6), (Px 3))
    [void](New-Button 'Open in Diagram studio' 'Edit, style or export the plan diagram' { Show-DiagramStudio; New-DiagramFromText 'Query plan' ([DgPlan]::Diagram($SqlUI.Plan, $script:IsDark)) } $bar $Glyph.Apps 2)
    [void](New-Button 'Save .sqlplan' 'The plan as XML: SQL Server Management Studio and Azure Data Studio open it' {
        $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'SQL Server plan|*.sqlplan'; $d.FileName = 'query.sqlplan'
        $script:Modal = $true
        try { if ($d.ShowDialog($SqlUI.Form) -eq 'OK') { [IO.File]::WriteAllText($d.FileName, ($SqlUI.Plan.Xml | Select-Object -First 1), (New-Object System.Text.UTF8Encoding $false)); Set-SqlStatus "Saved $(Split-Path -Leaf $d.FileName)." $C.Green } } finally { $script:Modal = $false; $d.Dispose() }
    } $bar $Glyph.Save 2)
    New-TbLabel $bar 'Read right to left: data flows from the tables to the result. Red = expensive; thick = many rows.' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 8), 0, 0) }
    $cv = New-Object DgCanvas
    $cv.Dock = 'Fill'; $cv.UiScale = $Scale * $TextZoom; $cv.Font = $FontMain; $cv.Editable = $false
    $right.Controls.Add($cv); $right.Controls.Add($bar)
    if ($Plan.Ops.Count) {
        $d = [DgText]::Parse([DgPlan]::Diagram($Plan, $script:IsDark)); [DgLayout]::Apply($d)
        $cv.Theme = [DgTheme]::Get($d.Theme); $cv.Dark = $script:IsDark
        $cv.SetDoc($d, $false)
    }
    $sp.SplitterDistance = [Math]::Min((Px 480), [int]($sp.Width * 0.45))
    Set-ControlTheme $pp $null $script:IsDark
}

# ---- live query diagram (beside the editor): the statement under the cursor, redrawn as you type
function Update-SqlLive {
    if (-not $SqlUI.Form -or $SqlUI.LiveSplit.Panel2Collapsed) { return }
    $c0 = Get-SqlConn
    $schema = Get-SqlSchema
    $ed = $SqlUI.Editor
    $text = [DgSqlViz]::Build($ed.Text, $ed.SelectionStart, $schema, $script:IsDark)
    $SqlUI.LiveText = $text
    $SqlUI.LiveInfo.Text = if ($SqlUI.SchemaError -and -not $schema) { "Columns not loaded: $($SqlUI.SchemaError)" } else { [DgSqlViz]::Info }
    $cv = $SqlUI.LiveCanvas
    if (-not $text) { $cv.SetDoc((New-Object DgDoc), $true); return }
    $d = [DgText]::Parse($text)
    # tables you dragged stay where you put them (by table and alias), the others are laid out around them
    if ($SqlUI.LivePos -and $SqlUI.LivePos.Count) { foreach ($n in $d.Nodes) { $p = $SqlUI.LivePos["$($n.Label)|$($n.Badge)"]; if ($p) { $n.X = $p[0]; $n.Y = $p[1]; $n.HasPos = $true } } }
    [DgLayout]::Apply($d)
    $cv.Theme = [DgTheme]::Get($d.Theme); $cv.Dark = $script:IsDark
    $sig = (@($d.Nodes | ForEach-Object { $_.Label }) -join '|')
    $refit = $sig -ne $SqlUI.LiveSig
    $SqlUI.LiveSig = $sig
    $cv.SetDoc($d, $true)
    if ($refit) { $cv.UserView = $false; $cv.ZoomToFit() }
}

# ---- folders for saved queries and connections (like in Notes). folders.json keeps the folder lists (also empty
#      folders) and which ones are closed; each query / connection has a .Folder ("Work/Prod", '' = the top).
function Get-SqlItems([string]$Kind) { if ($Kind -eq 'connections') { $SqlUI.Conns } else { $SqlUI.Queries } }
function Import-SqlFolders {
    $SqlUI.FolderList = @{ queries = (New-Object System.Collections.Generic.List[string]); connections = (New-Object System.Collections.Generic.List[string]) }
    $SqlUI.Closed = @{ queries = (New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)); connections = (New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)) }
    $p = Join-Path $SqlDir 'folders.json'
    if (-not (Test-Path -LiteralPath $p)) { return }
    try {
        $j = (Read-DataText $p) | ConvertFrom-Json
        foreach ($k in 'queries', 'connections') {
            foreach ($x in @($j.$k)) { if ($x) { $SqlUI.FolderList[$k].Add([string]$x) } }
            foreach ($x in @($j."closed_$k")) { if ($x) { [void]$SqlUI.Closed[$k].Add([string]$x) } }
        }
    } catch { Write-Log "sql folders: $_" }
}
function Save-SqlFolders {
    if ($script:NoSave) { return }
    if (-not (Test-Path -LiteralPath $SqlDir)) { [void](New-Item -ItemType Directory -Path $SqlDir -Force) }
    $o = [ordered]@{}
    foreach ($k in 'queries', 'connections') { $o[$k] = @($SqlUI.FolderList[$k]); $o["closed_$k"] = @($SqlUI.Closed[$k]) }
    try { Write-JsonFile (Join-Path $SqlDir 'folders.json') (ConvertTo-Json -InputObject $o -Depth 3) } catch { Write-Log "sql folders save: $_" }
}
function Save-SqlKind([string]$Kind) {
    foreach ($it in (Get-SqlItems $Kind)) { $x = [string]$it.Folder; while ($x) { if (-not $SqlUI.FolderList[$Kind].Contains($x)) { $SqlUI.FolderList[$Kind].Add($x) }; $x = Get-DvFolderParent $x } }
    Save-SqlData $Kind; Save-SqlFolders; Update-SqlSideLists; if ($Kind -eq 'connections') { Update-SqlConnList ([string]$SqlUI.ConnName) } }

function New-SqlFolder([string]$Kind, [string]$Parent = '', [string]$Name = '') {
    $n = if ($Name) { $Name } else { Read-TextDialog 'New folder' $(if ($Parent) { "Folder name  (inside $($Parent.Replace('/', ' > ')))" } else { 'Folder name' }) '' $SqlUI.Form }
    $n = ConvertTo-DvFolderName $n
    if (-not $n) { return }
    $path = Join-DvFolder $Parent $n
    if (-not $SqlUI.FolderList[$Kind].Contains($path)) { $SqlUI.FolderList[$Kind].Add($path) }
    $x = $Parent; while ($x) { [void]$SqlUI.Closed[$Kind].Remove($x); $x = Get-DvFolderParent $x }
    $fl = $SqlUI.Fl[$Kind]; if ($fl) { $fl.SelectedFolder = $path; $fl.FocusFolder = $true }
    Save-SqlKind $Kind
}
function Rename-SqlFolder([string]$Kind, [string]$Path, [string]$Name = '') {
    $old = Get-DvFolderLeaf $Path
    $n = if ($Name) { $Name } else { Read-TextDialog 'Rename folder' 'New name' $old $SqlUI.Form }
    $n = ConvertTo-DvFolderName $n
    if (-not $n -or $n -ceq $old) { return }
    $new = Join-DvFolder (Get-DvFolderParent $Path) $n
    Rename-DvFolderPath (Get-SqlItems $Kind) $SqlUI.FolderList[$Kind] $SqlUI.Closed[$Kind] $Path $new
    $fl = $SqlUI.Fl[$Kind]; if ($fl) { $fl.SelectedFolder = $new; $fl.FocusFolder = $true }
    Save-SqlKind $Kind
}
function Remove-SqlFolder([string]$Kind, [string]$Path, [switch]$NoPrompt) {
    $items = @(Get-SqlItems $Kind | Where-Object { [string]$_.Folder -eq $Path -or ([string]$_.Folder).StartsWith($Path + '/') }).Count
    $subs = @($SqlUI.FolderList[$Kind] | Where-Object { $_.StartsWith($Path + '/') }).Count
    $parent = Get-DvFolderParent $Path
    if ($items + $subs -gt 0 -and -not $NoPrompt) {
        $where = if ($parent) { """$($parent.Replace('/', ' > '))""" } else { 'the top level' }
        $what = if ($Kind -eq 'connections') { 'connection(s)' } else { 'query(s)' }
        if ([System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "Delete the folder ""$(Get-DvFolderLeaf $Path)""? Nothing inside is deleted: its $items $what and $subs subfolder(s) move up to $where.", 'SQL client', 'OKCancel', 'Question') -ne 'OK') { return }
    }
    Remove-DvFolderPath (Get-SqlItems $Kind) $SqlUI.FolderList[$Kind] $SqlUI.Closed[$Kind] $Path
    Save-SqlKind $Kind
}
# a row dragged onto a folder, or picked in "Move to"
function Move-SqlRow([string]$Kind, $Row, [string]$To) {
    if (-not $Row -or $Row.Empty) { return }
    if ($Row.IsFolder) {
        if ($To -eq $Row.Path -or $To.StartsWith($Row.Path + '/') -or (Get-DvFolderParent $Row.Path) -eq $To) { return }
        $new = Join-DvFolder $To (Get-DvFolderLeaf $Row.Path)
        Rename-DvFolderPath (Get-SqlItems $Kind) $SqlUI.FolderList[$Kind] $SqlUI.Closed[$Kind] $Row.Path $new
    } else {
        if ([string]$Row.Item.Folder -eq $To) { return }
        Set-DvItemFolder $Row.Item $To
        if ($To -and -not $SqlUI.FolderList[$Kind].Contains($To)) { $SqlUI.FolderList[$Kind].Add($To) }
    }
    $x = $To; while ($x) { [void]$SqlUI.Closed[$Kind].Remove($x); $x = Get-DvFolderParent $x }
    Save-SqlKind $Kind
}

# ---- saved queries
function Open-SqlQuery($Q) {
    if (-not $Q) { return }
    $SqlUI.QueryName = $Q.Name
    $SqlUI.Editor.Text = $Q.Sql
    if ($SqlUI.Fl.queries) { $SqlUI.Fl.queries.List.Invalidate() }
}
function Save-SqlQuery($Folder = $null) {
    $t = $SqlUI.Editor.Text; if (-not $t.Trim()) { return }
    if ($null -eq $Folder) { $Folder = if ($SqlUI.Fl.queries) { Get-DvFolderSelected $SqlUI.Fl.queries } else { '' } }
    $first = ($t -split "`r?`n" | Where-Object { $_.Trim() } | Select-Object -First 1).Trim()
    $n = Read-TextDialog 'Save query' $(if ($Folder) { "Name  (in the folder $($Folder.Replace('/', ' > ')))" } else { 'Name' }) $(if ($SqlUI.QueryName) { $SqlUI.QueryName } else { $first }) $SqlUI.Form
    if (-not $n) { return }
    $same = @($SqlUI.Queries | Where-Object { $_.Name -eq $n -and [string]$_.Folder -eq $Folder }) | Select-Object -First 1
    if ($same) {
        if ([System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "Replace the saved query ""$n""?", 'SQL client', 'YesNo', 'Question') -ne 'Yes') { return }
        $same.Sql = $t
    } else { $SqlUI.Queries.Insert(0, [pscustomobject]@{ Name = $n; Sql = $t; Folder = $Folder }) }
    $SqlUI.QueryName = $n
    Save-SqlKind 'queries'
}
function Rename-SqlQuery($Q) {
    $n = Read-TextDialog 'Rename query' 'New name' $Q.Name $SqlUI.Form
    if (-not $n -or $n -ceq $Q.Name) { return }
    if ($SqlUI.QueryName -eq $Q.Name) { $SqlUI.QueryName = $n }
    $Q.Name = $n; Save-SqlKind 'queries'
}
function Remove-SqlQuery($Q, [switch]$NoPrompt) {
    if (-not $NoPrompt -and [System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "Delete the saved query ""$($Q.Name)""?", 'SQL client', 'YesNo', 'Question') -ne 'Yes') { return }
    [void]$SqlUI.Queries.Remove($Q); Save-SqlKind 'queries'
}

# ---- connections
function Update-SqlDbLabel { if ($SqlUI.DbLabel) { $SqlUI.DbLabel.Text = if ((Get-SqlDialect (Get-SqlConn)) -eq 'oracle') { 'Schema' } else { 'Database' } } }
function Select-SqlConn($Conn) {
    $i = $SqlUI.Conns.IndexOf($Conn)
    if ($i -lt 0) { return }
    $SqlUI.ConnBox.SelectedIndex = $i
    $SqlUI.ConnName = $Conn.Name
    $SqlUI.DbBox.Text = $Conn.Database
    Update-SqlDbLabel
    Update-SqlTree
    if ($SqlUI.Fl.connections) { $SqlUI.Fl.connections.List.Invalidate() }
}
function Add-SqlConnection($Folder = $null) {
    if ($null -eq $Folder) { $Folder = if ($SqlUI.Fl.connections) { Get-DvFolderSelected $SqlUI.Fl.connections } else { '' } }
    $n = Edit-SqlConnection
    if (-not $n) { Update-SqlConnList ([string]$SqlUI.ConnName); return }
    Set-DvItemFolder $n $Folder
    $SqlUI.Conns.Add($n); $SqlUI.ConnName = $n.Name
    Save-SqlKind 'connections'
    Select-SqlConn $n
}
function Edit-SqlConnItem($Conn) {
    $i = $SqlUI.Conns.IndexOf($Conn); if ($i -lt 0) { return }
    $n = Edit-SqlConnection $Conn
    if (-not $n) { return }
    Set-DvItemFolder $n ([string]$Conn.Folder)
    $SqlUI.Conns[$i] = $n; $SqlUI.ConnName = $n.Name
    Save-SqlKind 'connections'
    Select-SqlConn $n
}
function Remove-SqlConnItem($Conn, [switch]$NoPrompt) {
    if (-not $NoPrompt -and [System.Windows.Forms.MessageBox]::Show($SqlUI.Form, "Remove the connection ""$($Conn.Name)""?", 'SQL client', 'YesNo', 'Question') -ne 'Yes') { return }
    [void]$SqlUI.Conns.Remove($Conn)
    if ($SqlUI.ConnName -eq $Conn.Name) { $SqlUI.ConnName = '' }
    Save-SqlKind 'connections'
    Update-SqlTree
}

# the right-click menus of the two folder lists
function Show-SqlFolderMenu([string]$Kind, $Menu, $Row) {
    $SqlUI.MenuKind = $Kind
    $q = $Kind -eq 'queries'
    if ($Row -and $Row.IsFolder) {
        if ($q) { [void](Add-MenuItem $Menu 'Save the editor here...' { Save-SqlQuery $SqlUI.Fl.queries.MenuRow.Path } $Glyph.Save) }
        else { [void](Add-MenuItem $Menu 'New connection here...' { Add-SqlConnection $SqlUI.Fl.connections.MenuRow.Path } $Glyph.Add) }
        [void](Add-MenuItem $Menu 'New folder inside...' { New-SqlFolder $SqlUI.MenuKind $SqlUI.Fl[$SqlUI.MenuKind].MenuRow.Path } $Glyph.Folder)
        [void]$Menu.Items.Add('-')
        [void](Add-MenuItem $Menu 'Rename folder...' { Rename-SqlFolder $SqlUI.MenuKind $SqlUI.Fl[$SqlUI.MenuKind].MenuRow.Path } $Glyph.Edit 'F2')
        Add-DvMoveMenu $Menu $SqlUI.Fl[$Kind] (Get-DvFolderParent $Row.Path) $Row.Path { param($to) Move-SqlRow $SqlUI.MenuKind $SqlUI.Fl[$SqlUI.MenuKind].MenuRow $to }
        [void](Add-MenuItem $Menu 'Delete folder...' { Remove-SqlFolder $SqlUI.MenuKind $SqlUI.Fl[$SqlUI.MenuKind].MenuRow.Path } $Glyph.Delete 'Del')
    } elseif ($Row) {
        if ($q) {
            [void](Add-MenuItem $Menu 'Open' { Open-SqlQuery $SqlUI.Fl.queries.MenuRow.Item } $Glyph.Open 'Enter')
            [void](Add-MenuItem $Menu 'Open and run' { Open-SqlQuery $SqlUI.Fl.queries.MenuRow.Item; Start-SqlRun } $Glyph.Play)
            [void](Add-MenuItem $Menu 'Rename...' { Rename-SqlQuery $SqlUI.Fl.queries.MenuRow.Item } $Glyph.Edit 'F2')
        } else {
            [void](Add-MenuItem $Menu 'Use' { Select-SqlConn $SqlUI.Fl.connections.MenuRow.Item } $Glyph.Play 'Enter')
            [void](Add-MenuItem $Menu 'Edit...' { Edit-SqlConnItem $SqlUI.Fl.connections.MenuRow.Item } $Glyph.Edit 'F2')
        }
        Add-DvMoveMenu $Menu $SqlUI.Fl[$Kind] ([string]$Row.Item.Folder) '' { param($to) Move-SqlRow $SqlUI.MenuKind $SqlUI.Fl[$SqlUI.MenuKind].MenuRow $to }
        [void](Add-MenuItem $Menu $(if ($q) { 'Delete' } else { 'Remove' }) { $it = $SqlUI.Fl[$SqlUI.MenuKind].MenuRow.Item; if ($SqlUI.MenuKind -eq 'queries') { Remove-SqlQuery $it } else { Remove-SqlConnItem $it } } $Glyph.Delete 'Del')
    } else {
        if ($q) { [void](Add-MenuItem $Menu 'Save the editor...' { Save-SqlQuery '' } $Glyph.Save) }
        else { [void](Add-MenuItem $Menu 'New connection...' { Add-SqlConnection '' } $Glyph.Add) }
        [void](Add-MenuItem $Menu 'New folder...' { New-SqlFolder $SqlUI.MenuKind '' } $Glyph.Folder)
    }
}

function New-SqlFolderList([string]$Kind, $Parent) {
    $fl = New-DvFolderList $Parent $(if ($Kind -eq 'connections') { 'Search connections...' } else { 'Search saved queries...' })
    $fl.Kind = $Kind
    $fl.Collapsed = $SqlUI.Closed[$Kind]
    $fl.GetFolders = [scriptblock]::Create("`$SqlUI.FolderList['$Kind']")
    $fl.GetItems = [scriptblock]::Create("Get-SqlItems '$Kind'")
    $fl.Title = { param($it) [string]$it.Name }
    $fl.OnMenu = [scriptblock]::Create("param(`$menu, `$row) Show-SqlFolderMenu '$Kind' `$menu `$row")
    $fl.OnMove = [scriptblock]::Create("param(`$row, `$to) Move-SqlRow '$Kind' `$row `$to")
    $fl.OnCollapse = { Save-SqlFolders }
    $fl.OnRename = [scriptblock]::Create("param(`$row) if (`$row.IsFolder) { Rename-SqlFolder '$Kind' `$row.Path } elseif ('$Kind' -eq 'queries') { Rename-SqlQuery `$row.Item } else { Edit-SqlConnItem `$row.Item }")
    $fl.OnDelete = [scriptblock]::Create("param(`$row) if (`$row.IsFolder) { Remove-SqlFolder '$Kind' `$row.Path } elseif ('$Kind' -eq 'queries') { Remove-SqlQuery `$row.Item } else { Remove-SqlConnItem `$row.Item }")
    if ($Kind -eq 'connections') {
        $fl.Meta = { param($it) $t = Get-SqlDialect $it; "$(if ($t -ne 'mssql') { "$($SqlTypes[$t])  -  " })$($it.Server)$(if ($it.Database) { "  /  $($it.Database)" })$(if (-not $it.Windows) { "  /  $($it.User)" })" }
        $fl.IsCurrent = { param($it) $it -eq (Get-SqlConn) }
        $fl.OnOpen = { param($it) if ($it -ne (Get-SqlConn)) { Select-SqlConn $it } }
        $fl.EmptyText = 'No connections yet. Right-click: New connection.'
    } else {
        $fl.Meta = { param($it) $t = ([string]$it.Sql -replace '\s+', ' ').Trim(); $t.Substring(0, [Math]::Min(120, $t.Length)) }
        $fl.IsCurrent = { param($it) $SqlUI.QueryName -and $it.Name -eq $SqlUI.QueryName }
        $fl.OnOpen = { param($it) Open-SqlQuery $it }
        $fl.OpenOnDoubleClick = $true
        $fl.EmptyText = 'No saved queries yet. Save query keeps the editor here.'
    }
    $hdr = New-Object System.Windows.Forms.Label
    $hdr.Dock = 'Top'; $hdr.AutoSize = $false; $hdr.Height = Px 28; $hdr.Font = $FontSmall; $hdr.ForeColor = $C.Accent; $hdr.BackColor = $C.Panel; $hdr.TextAlign = 'MiddleLeft'
    $hdr.Text = if ($Kind -eq 'connections') { '  CONNECTIONS  (right-click for folders)' } else { '  SAVED QUERIES  (right-click for folders)' }
    $bar = New-Object System.Windows.Forms.FlowLayoutPanel
    $bar.Dock = 'Top'; $bar.AutoSize = $true; $bar.WrapContents = $true; $bar.BackColor = $C.Panel; $bar.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 6), (Px 6), (Px 2))
    if ($Kind -eq 'connections') { [void](New-Button 'New connection' 'A new connection in the selected folder' { Add-SqlConnection } $bar $Glyph.Add 2) }
    else { [void](New-Button 'Save query' 'Keep the editor in the selected folder' { Save-SqlQuery } $bar $Glyph.Save 2) }
    $b = New-Button 'Folder' 'A new folder inside the selected one' { New-SqlFolder $this.Tag (Get-DvFolderSelected $SqlUI.Fl[$this.Tag]) } $bar $Glyph.Folder 2
    $b.Tag = $Kind
    $Parent.Controls.Add($hdr); $Parent.Controls.Add($bar)
    $SqlUI.Fl[$Kind] = $fl
    $fl
}

# colours the SQL in place: the text, the selection and the scroll position stay as they are (setting the text again
# would count as a change, start the colouring again and lose what you marked)
function Set-SqlColors {
    $ed = $SqlUI.Editor
    if (-not $ed -or $ed.TextLength -ge 60000) { return }
    if ([System.Windows.Forms.Control]::MouseButtons -ne 'None') { $SqlUI.ColorTimer.Stop(); $SqlUI.ColorTimer.Start(); return }     # still marking with the mouse
    $SqlUI.Coloring = $true
    $ss = $ed.SelectionStart; $sl = $ed.SelectionLength
    $pos = [DgSql]::GetScroll($ed.Handle)
    [PowerClipTheme]::Redraw($ed.Handle, $false)
    try {
        $ed.SelectAll(); $ed.SelectionColor = $C.Fore
        $ed.SelectionFont = $ed.Font; $ed.SelectionBackColor = $ed.BackColor; $ed.SelectionBullet = $false; $ed.SelectionIndent = 0; $ed.SelectionHangingIndent = 0; $ed.SelectionRightIndent = 0     # whatever came in with the text
        $col = @{ 1 = $C.Accent; 2 = $C.Orange; 3 = $C.Dim; 4 = $C.Purple; 5 = $C.Green }
        foreach ($tk in [DevCode]::Tokens($ed.Text, 'sql')) { $cc = $col[[int]$tk[2]]; if ($null -eq $cc) { continue }; $ed.Select($tk[0], $tk[1]); $ed.SelectionColor = $cc }
    } finally {
        $ed.Select($ss, $sl)                       # the cursor and the view always come back, even if colouring stops
        [DgSql]::SetScroll($ed.Handle, $pos)
        [PowerClipTheme]::Redraw($ed.Handle, $true); $ed.Invalidate(); $SqlUI.Coloring = $false
    }
}

# ---- autocomplete: suggestions under the cursor as you type; Up / Down choose, Tab puts it in, Esc closes, Ctrl+Space opens it
# the columns of the current connection / database (shared with the live diagram; read again with Refresh columns)
# the databases (Oracle: schemas) of the current connection, read once and kept (Refresh columns reads them again); $null when they can't be listed
function Get-SqlDbNames {
    $c0 = Get-SqlConn
    if (-not $c0) { return $null }
    $k = "$($c0.Name)|$($c0.Server)|$($c0.Driver)"
    if (-not $SqlUI.DbNames) { $SqlUI.DbNames = @{} }
    if (-not $SqlUI.DbNames.ContainsKey($k)) {
        $set = $null
        try { $set = New-Object 'System.Collections.Generic.List[string]'; foreach ($r in ([DgDb]::Databases((Get-SqlConnString $c0 (Get-SqlListDb $c0)))).Rows) { $set.Add([string]$r[0]) } } catch { $set = $null }
        $SqlUI.DbNames[$k] = $set
    }
    , $SqlUI.DbNames[$k]
}
function Get-SqlSchema {
    $c0 = Get-SqlConn
    $db = [string]$SqlUI.DbBox.Text
    # a half-typed name in the Database box: don't connect to a database that isn't there (each try waits for the server)
    if ($c0 -and $db.Trim()) {
        $names = Get-SqlDbNames
        if ($names -and -not ($names | Where-Object { $_ -eq $db.Trim() })) { $SqlUI.SchemaError = "no database called '$db' (pick one from the list)"; return $null }
    }
    $key = if ($c0) { "$($c0.Name)|$db" } else { '' }
    if ($key -ne $SqlUI.SchemaKey) {
        $SqlUI.SchemaKey = $key; $SqlUI.Schema = $null; $SqlUI.SchemaError = ''
        if ($c0) { try { $SqlUI.Schema = [DgSqlSchema]::Load((Get-SqlConnString $c0 $SqlUI.DbBox.Text)) } catch { $SqlUI.SchemaError = Get-SqlError $_ } }
    }
    # the other saved connections, for [Name].schema.table
    if ($SqlUI.Schema) {
        $sig = (@($SqlUI.Conns | ForEach-Object { "$($_.Name)|$($_.Server)|$($_.Database)|$($_.Driver)" }) -join ';')
        if ($SqlUI.SourcesSig -ne $sig -or $SqlUI.Schema.Sources.Count -eq 0) {
            $SqlUI.SourcesSig = $sig
            $SqlUI.Schema.Sources.Clear()
            foreach ($cx in $SqlUI.Conns) { if ($cx.Name -and -not $SqlUI.Schema.Sources.ContainsKey([string]$cx.Name)) { try { $SqlUI.Schema.Sources[[string]$cx.Name] = Get-SqlConnString $cx } catch { } } }
        }
    }
    $SqlUI.Schema
}

function New-SqlCompleteList($Form) {
    $ac = New-Object System.Windows.Forms.ListBox
    $ac.DrawMode = 'OwnerDrawFixed'; $ac.ItemHeight = $FontMain.Height + (Px 8); $ac.BorderStyle = 'FixedSingle'; $ac.IntegralHeight = $false
    $ac.Visible = $false; $ac.TabStop = $false; $ac.Width = Px 460; $ac.BackColor = $C.Panel; $ac.ForeColor = $C.Fore; $ac.Font = $FontMain
    $ac.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0 -or -not $SqlUI.AcItems -or $e.Index -ge $SqlUI.AcItems.Count) { return }
        $it = $SqlUI.AcItems[$e.Index]
        $g = $e.Graphics; $r = $e.Bounds
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        $b = New-Object System.Drawing.SolidBrush $(if ($sel) { $C.Sel } else { $C.Panel }); $g.FillRectangle($b, $r); $b.Dispose()
        $kc = switch ($it.Kind) { 'table' { $C.Accent } 'column' { $C.Green } 'alias' { $C.Purple } 'function' { $C.Orange } 'schema' { $C.Yellow } 'connection' { $C.Red } default { $C.Dim } }
        $tag = switch ($it.Kind) { 'table' { 'T' } 'column' { 'C' } 'alias' { 'A' } 'function' { 'f' } 'schema' { 'S' } 'connection' { 'DB' } default { 'K' } }
        $flags = [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding'
        [System.Windows.Forms.TextRenderer]::DrawText($g, $tag, $FontSmall, (New-Object System.Drawing.Rectangle(($r.X + (Px 6)), $r.Y, (Px 16), $r.Height)), $kc, $flags)
        $dw = if ($it.Detail) { [Math]::Min([int]($r.Width * 0.45), [System.Windows.Forms.TextRenderer]::MeasureText($it.Detail, $FontSmall).Width + (Px 8)) } else { 0 }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $it.Label, $FontMain, (New-Object System.Drawing.Rectangle(($r.X + (Px 28)), $r.Y, ($r.Width - (Px 36) - $dw), $r.Height)), $C.Fore, $TextFlags)
        if ($dw) { [System.Windows.Forms.TextRenderer]::DrawText($g, $it.Detail, $FontSmall, (New-Object System.Drawing.Rectangle(($r.Right - $dw - (Px 6)), $r.Y, $dw, $r.Height)), $C.Dim, $TextFlags) }
    })
    $ac.add_MouseDown({ param($src, $e) $i = $src.IndexFromPoint($e.Location); if ($i -ge 0) { $src.SelectedIndex = $i; Complete-SqlSuggestion } })
    $Form.Controls.Add($ac)
    $SqlUI.Ac = $ac
    $SqlUI.AcTimer = New-TbDebounce 90 { if ($SqlUI.Form) { $SqlUI.AcTyped = $false; Update-SqlComplete } }
}

function Hide-SqlComplete { if ($SqlUI.Ac -and $SqlUI.Ac.Visible) { $SqlUI.Ac.Visible = $false } }

function Update-SqlComplete([switch]$Forced) {
    $ed = $SqlUI.Editor; $ac = $SqlUI.Ac
    if (-not $ac -or $ed.SelectionLength -gt 0 -or $ed.TextLength -gt 200000) { Hide-SqlComplete; return }
    $items = @([DgSqlComplete]::Suggest($ed.Text, $ed.SelectionStart, (Get-SqlSchema), (Get-SqlDialect (Get-SqlConn)), [bool]$Forced))
    if (-not $items.Count -or ($items.Count -eq 1 -and $items[0].Insert -ceq [DgSqlComplete]::Prefix)) { Hide-SqlComplete; return }
    $SqlUI.AcItems = $items; $SqlUI.AcStart = [DgSqlComplete]::Start; $SqlUI.AcLen = [DgSqlComplete]::Length
    $ac.BeginUpdate(); $ac.Items.Clear(); for ($i = 0; $i -lt $items.Count; $i++) { [void]$ac.Items.Add($i) }; $ac.SelectedIndex = 0; $ac.EndUpdate()
    # under the word (above it when there is no room below)
    $at = $SqlUI.AcStart
    if ($at -lt $ed.TextLength) { $p = $ed.GetPositionFromCharIndex($at) }
    else { $p = $ed.GetPositionFromCharIndex([Math]::Max(0, $at - 1)); if ($at -gt 0) { $p.X += [System.Windows.Forms.TextRenderer]::MeasureText('x', $ed.Font, (New-Object System.Drawing.Size(100, 100)), [System.Windows.Forms.TextFormatFlags]::NoPadding).Width } }
    $pt = $SqlUI.Form.PointToClient($ed.PointToScreen($p))
    $h = [Math]::Min(9, $items.Count) * $ac.ItemHeight + 4
    $cs = $SqlUI.Form.ClientSize
    $y = $pt.Y + $ed.Font.Height + (Px 4)
    if ($y + $h -gt $cs.Height - (Px 8)) { $y = [Math]::Max(0, $pt.Y - $h - (Px 2)) }
    $x = [Math]::Max(0, [Math]::Min($pt.X - (Px 28), $cs.Width - $ac.Width - (Px 8)))
    $ac.SetBounds($x, $y, $ac.Width, $h)
    $ac.Visible = $true; $ac.BringToFront()
}

function Complete-SqlSuggestion {
    $ac = $SqlUI.Ac; $ed = $SqlUI.Editor
    $i = $ac.SelectedIndex
    if ($i -lt 0 -or $i -ge $SqlUI.AcItems.Count) { Hide-SqlComplete; return }
    $it = $SqlUI.AcItems[$i]
    Hide-SqlComplete
    $start = [Math]::Min($SqlUI.AcStart, $ed.TextLength)
    $ed.Select($start, [Math]::Max(0, [Math]::Min($SqlUI.AcLen, $ed.TextLength - $start)))
    $ed.SelectedText = $it.Insert
    $ed.Focus()
}

# the editor's keys and events for the list
function Register-SqlComplete($Ed) {
    $Ed.add_KeyDown({
        param($src, $e)
        $ac = $SqlUI.Ac
        if ($ac.Visible) {
            switch ($e.KeyCode) {
                'Down' { if ($ac.SelectedIndex -lt $ac.Items.Count - 1) { $ac.SelectedIndex++ }; $e.SuppressKeyPress = $true; $e.Handled = $true }
                'Up' { if ($ac.SelectedIndex -gt 0) { $ac.SelectedIndex-- }; $e.SuppressKeyPress = $true; $e.Handled = $true }
                'PageDown' { $ac.SelectedIndex = [Math]::Min($ac.Items.Count - 1, $ac.SelectedIndex + 8); $e.SuppressKeyPress = $true; $e.Handled = $true }
                'PageUp' { $ac.SelectedIndex = [Math]::Max(0, $ac.SelectedIndex - 8); $e.SuppressKeyPress = $true; $e.Handled = $true }
                'Tab' { if (-not $e.Shift -and -not $e.Control) { Complete-SqlSuggestion; $e.SuppressKeyPress = $true; $e.Handled = $true } }
                'Escape' { Hide-SqlComplete; $e.SuppressKeyPress = $true; $e.Handled = $true }
                { $_ -in 'Return', 'Left', 'Right', 'Home', 'End' } { Hide-SqlComplete }
            }
        } elseif ($e.Control -and $e.KeyCode -eq 'Space') { $e.SuppressKeyPress = $true; $e.Handled = $true; Update-SqlComplete -Forced }
    })
    # what was typed: a letter, digit, _ or . (re)opens the list; Backspace updates it while open; anything else closes it
    $Ed.add_KeyPress({
        param($src, $e)
        $ch = $e.KeyChar
        if ([char]::IsLetterOrDigit($ch) -or $ch -in '_', '.', '@', '$', '#', '[' -or ($ch -eq ' ' -and $SqlUI.Ac.Visible -and $SqlUI.AcItems -and $SqlUI.AcItems[0].Kind -eq 'connection')) { $SqlUI.AcTyped = $true }
        elseif ([int]$ch -eq 8) { $SqlUI.AcTyped = $SqlUI.Ac.Visible }
        else { $SqlUI.AcTyped = $false; Hide-SqlComplete }
    })
    $Ed.add_TextChanged({ if (-not $SqlUI.Coloring -and $SqlUI.AcTyped) { $SqlUI.AcTimer.Stop(); $SqlUI.AcTimer.Start() } })
    $Ed.add_MouseDown({ Hide-SqlComplete })
    $Ed.add_VScroll({ Hide-SqlComplete })
    $Ed.add_LostFocus({ if ($SqlUI.Form) { [void]$SqlUI.Form.BeginInvoke([Action]{ if ($SqlUI.Ac -and -not $SqlUI.Editor.Focused) { Hide-SqlComplete } }) } })
}

# ---- examples: ready queries for each feature. {A} / {B} become your first two saved connections, {DIR} the sample files folder.
$SqlExampleDir = Join-Path $SqlDir 'examples'
$SqlExamples = @(
    @{ Group = 'Files (run as they are)'; Title = 'Query a CSV file'; Sql = @'
-- A CSV file is a table: the first row has the column names, numbers and dates are recognised.
SELECT s.region_code, COUNT(*) AS orders, SUM(s.amount) AS total
FROM [file:{DIR}\sales.csv] s
WHERE s.order_date >= DATE '2026-02-01'
GROUP BY s.region_code
ORDER BY total DESC;
'@ }
    @{ Group = 'Files (run as they are)'; Title = 'Join a CSV with an Excel sheet'; Sql = @'
-- [file:path].Sheet is a sheet of an .xlsx file. Joins, GROUP BY and HAVING run inside DevTools.
SELECT r.region, r.manager, SUM(s.amount) AS sold, MAX(t.target) AS target,
       SUM(s.amount) - MAX(t.target) AS gap,
       CASE WHEN SUM(s.amount) >= MAX(t.target) THEN 'on target' ELSE 'behind' END AS status
FROM [file:{DIR}\sales.csv] s
JOIN [file:{DIR}\regions.csv] r ON r.code = s.region_code
JOIN [file:{DIR}\targets.xlsx].Targets t ON t.region_code = s.region_code
GROUP BY r.region, r.manager
ORDER BY gap;
'@ }
    @{ Group = 'Files (run as they are)'; Title = 'Rows in one file but not in the other'; Sql = @'
-- LEFT JOIN ... WHERE x IS NULL: the regions that have sales but no target.
SELECT DISTINCT s.region_code
FROM [file:{DIR}\sales.csv] s
LEFT JOIN [file:{DIR}\targets.xlsx].Targets t ON t.region_code = s.region_code
WHERE t.region_code IS NULL;
'@ }
    @{ Group = 'Across connections'; Title = 'Join two connections'; Sql = @'
-- [Name] is a saved connection (Connections tab). Change the tables and columns to yours.
-- Each connection gets only the columns used and its own WHERE parts; the join happens in DevTools.
SELECT o.order_id, o.order_date, c.name, o.total
FROM [{A}].dbo.orders o
JOIN [{B}].dbo.customers c ON c.id = o.customer_id
WHERE o.order_date >= DATE '2026-01-01'
ORDER BY o.total DESC;
'@ }
    @{ Group = 'Across connections'; Title = 'A connection and an Excel file'; Sql = @'
-- A table without [Name] uses the connection selected at the top.
SELECT c.name, c.region_code, t.target
FROM dbo.customers c
JOIN [file:{DIR}\targets.xlsx].Targets t ON t.region_code = c.region_code;
'@ }
    @{ Group = 'Across connections'; Title = 'Three sources: Oracle, SQL Server and Excel'; Sql = @'
-- Write each table in its own database's syntax (Oracle names are usually in capitals).
SELECT o.ORDER_ID, c.name, r.region, o.AMOUNT
FROM [{B}].SALES.ORDERS o
JOIN [{A}].dbo.customers c ON c.id = o.CUSTOMER_ID
JOIN [file:{DIR}\regions.csv] r ON r.code = c.region_code
WHERE o.ORDER_DATE >= DATE '2026-01-01';
'@ }
    @{ Group = 'Across connections'; Title = 'Reconcile two systems (missing rows)'; Sql = @'
-- Customers in system A that system B doesn't have.
-- (The IS NULL filter is not sent to B: it has to see all of B's rows to know what is missing.)
SELECT a.id, a.name
FROM [{A}].dbo.customers a
LEFT JOIN [{B}].dbo.customers b ON b.id = a.id
WHERE b.id IS NULL;
'@ }
    @{ Group = 'Across connections'; Title = 'Compare totals between two systems'; Sql = @'
-- FULL JOIN keeps the rows of both sides; COALESCE fills the gaps.
SELECT COALESCE(a.customer_id, b.customer_id) AS customer_id,
       a.total AS total_a, b.total AS total_b,
       COALESCE(a.total, 0) - COALESCE(b.total, 0) AS difference
FROM [{A}].dbo.invoices a
FULL JOIN [{B}].dbo.invoices b ON b.customer_id = a.customer_id
WHERE a.total IS NULL OR b.total IS NULL OR a.total <> b.total
ORDER BY difference DESC;
'@ }
    @{ Group = 'Other databases and schemas'; Title = 'SQL Server: a table in another database'; Sql = @'
-- Db.schema.table (or Db..table for dbo) on the same server: the live diagram reads its columns too.
SELECT c.name, g.country_name
FROM dbo.customers c
JOIN Geography.dbo.countries g ON g.country_id = c.country_id;
'@ }
    @{ Group = 'Other databases and schemas'; Title = 'Oracle: another schema and a db link'; Sql = @'
-- OWNER.TABLE reads another schema; TABLE@LINK goes through a database link.
SELECT e.EMPLOYEE_ID, e.LAST_NAME, d.DEPARTMENT_NAME
FROM HR.EMPLOYEES e
JOIN DEPARTMENTS@REMOTE_LINK d ON d.DEPARTMENT_ID = e.DEPARTMENT_ID
FETCH FIRST 50 ROWS ONLY
'@ }
    @{ Group = 'Per database'; Title = 'SQL Server: top, paging, dates'; Sql = @'
SELECT TOP 100 o.order_id, o.total, DATEDIFF(day, o.order_date, GETDATE()) AS days_ago
FROM dbo.orders o
WHERE o.order_date >= DATEADD(month, -3, GETDATE())
ORDER BY o.order_date DESC;

-- page 3, 50 rows a page
SELECT order_id, total FROM dbo.orders ORDER BY order_id OFFSET 100 ROWS FETCH NEXT 50 ROWS ONLY;
'@ }
    @{ Group = 'Per database'; Title = 'PostgreSQL: LIMIT, ILIKE, date_trunc'; Sql = @'
SELECT date_trunc('month', o.order_date) AS month, COUNT(*) AS orders, SUM(o.total) AS total
FROM public.orders o
WHERE o.customer_name ILIKE '%smith%'
GROUP BY 1
ORDER BY 1 DESC
LIMIT 12;
'@ }
    @{ Group = 'Per database'; Title = 'Oracle: FETCH FIRST, NVL, a PL/SQL block'; Sql = @'
SELECT o.ORDER_ID, NVL(o.DISCOUNT, 0) AS discount, TRUNC(o.ORDER_DATE, 'MM') AS month
FROM ORDERS o
WHERE o.ORDER_DATE >= ADD_MONTHS(TRUNC(SYSDATE), -3)
ORDER BY o.ORDER_DATE DESC
FETCH FIRST 100 ROWS ONLY;

-- a PL/SQL block ends with a line that holds only /
BEGIN
  DBMS_OUTPUT.PUT_LINE('hello');
END;
/
'@ }
    @{ Group = 'Tips'; Title = 'Plans, the live diagram and suggestions'; Sql = @'
-- Put the cursor in a statement and:
--   F5 / Ctrl+Enter   run it (or the selection)
--   Ctrl+L            the plan without running it (SQL Server: drawn, with suggestions and fixes;
--                     PostgreSQL / Oracle: their own text plan)
--   Ctrl+M            run it and get the actual plan
--   Ctrl+Space        suggestions: tables after FROM / JOIN, columns after alias., your connections after [
-- The diagram on the right follows the statement under the cursor as you type.
SELECT c.name, COUNT(o.order_id) AS orders
FROM dbo.customers c
LEFT JOIN dbo.orders o ON o.customer_id = c.id
GROUP BY c.name
HAVING COUNT(o.order_id) > 1;
'@ }
)

# the sample files the file examples use (made once, in data\sql\examples)
function New-SqlExampleFiles {
    if (-not (Test-Path -LiteralPath $SqlExampleDir)) { [void](New-Item -ItemType Directory -Path $SqlExampleDir -Force) }
    $utf8 = New-Object System.Text.UTF8Encoding $false
    $f = Join-Path $SqlExampleDir 'regions.csv'
    if (-not (Test-Path -LiteralPath $f)) { [IO.File]::WriteAllText($f, "code;region;manager`r`nEU;Europe;Maria`r`nUS;Americas;John`r`nAPAC;Asia Pacific;Li`r`nLATAM;Latin America;Sofia`r`n", $utf8) }
    $f = Join-Path $SqlExampleDir 'sales.csv'
    if (-not (Test-Path -LiteralPath $f)) {
        $rows = @('order_id,region_code,amount,order_date', '1,EU,120.50,2026-01-05', '2,EU,80.00,2026-02-11', '3,US,45.25,2026-02-14', '4,US,60.00,2026-03-02', '5,APAC,30.00,2026-03-09', '6,LATAM,15.75,2026-03-20', '7,EU,99.90,2026-03-28', '8,APAC,12.00,2026-01-30')
        [IO.File]::WriteAllText($f, ($rows -join "`r`n") + "`r`n", $utf8)
    }
    $f = Join-Path $SqlExampleDir 'targets.xlsx'
    if (-not (Test-Path -LiteralPath $f)) {
        $cells = @(@('region_code', 'target', 'year'), @('EU', 250, 2026), @('US', 150, 2026), @('APAC', 40, 2026))
        $sb = New-Object System.Text.StringBuilder
        for ($r = 0; $r -lt $cells.Count; $r++) {
            [void]$sb.Append("<row r=`"$($r + 1)`">")
            for ($c = 0; $c -lt $cells[$r].Count; $c++) {
                $ref = [string][char](65 + $c) + ($r + 1); $v = $cells[$r][$c]
                if ($v -is [string]) { [void]$sb.Append("<c r=`"$ref`" t=`"inlineStr`"><is><t>$([Security.SecurityElement]::Escape($v))</t></is></c>") } else { [void]$sb.Append("<c r=`"$ref`"><v>$v</v></c>") }
            }
            [void]$sb.Append('</row>')
        }
        $parts = [ordered]@{
            '[Content_Types].xml' = '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'
            '_rels/.rels' = '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'
            'xl/workbook.xml' = '<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Targets" sheetId="1" r:id="rId1"/></sheets></workbook>'
            'xl/_rels/workbook.xml.rels' = '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'
            'xl/worksheets/sheet1.xml' = "<?xml version=`"1.0`" encoding=`"UTF-8`"?><worksheet xmlns=`"http://schemas.openxmlformats.org/spreadsheetml/2006/main`"><sheetData>$($sb.ToString())</sheetData></worksheet>"
        }
        $z = [IO.Compression.ZipFile]::Open($f, 'Create')
        try { foreach ($k in $parts.Keys) { $e = $z.CreateEntry($k); $w = New-Object IO.StreamWriter($e.Open(), $utf8); try { $w.Write($parts[$k]) } finally { $w.Dispose() } } } finally { $z.Dispose() }
    }
}

# an example into the editor: added at the end and selected, so F5 runs just it
function Add-SqlExample($Ex) {
    try { New-SqlExampleFiles } catch { Set-SqlStatus "Couldn't make the sample files: $($_.Exception.Message)" $C.Red }
    $names = @($SqlUI.Conns | ForEach-Object { [string]$_.Name } | Where-Object { $_ })
    $a = if ($names.Count -ge 1) { $names[0] } else { 'My SQL Server' }
    $b = if ($names.Count -ge 2) { $names[1] } else { 'Oracle prod' }
    $text = $Ex.Sql.Replace('{DIR}', $SqlExampleDir).Replace('{A}', $a).Replace('{B}', $b).Trim()
    $ed = $SqlUI.Editor
    $lead = if ($ed.TextLength -gt 0) { if ($ed.Text.EndsWith("`n")) { "`r`n" } else { "`r`n`r`n" } } else { '' }
    $ed.AppendText($lead + "-- Example: $($Ex.Title)`r`n" + $text + "`r`n")
    $start = $ed.TextLength - ("-- Example: $($Ex.Title)`r`n" + $text + "`r`n").Replace("`r`n", "`n").Length
    $ed.Select([Math]::Max(0, $start), $ed.TextLength - [Math]::Max(0, $start)); $ed.ScrollToCaret(); [void]$ed.Focus()
    Set-SqlStatus $(if ($Ex.Group -like 'Files*') { "Example added and selected: F5 runs it (the sample files are in $SqlExampleDir)." } else { 'Example added and selected: change the tables to yours, then F5.' }) $C.Accent
}
function Show-SqlExamplesMenu($Button) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    foreach ($g in @($SqlExamples | ForEach-Object { $_.Group } | Select-Object -Unique)) {
        $sub = New-Object System.Windows.Forms.ToolStripMenuItem($g)
        $sub.DropDown.Renderer = $MenuRenderer
        foreach ($ex in @($SqlExamples | Where-Object { $_.Group -eq $g })) { $it = $sub.DropDownItems.Add($ex.Title, $null, { param($s2, $e2) Add-SqlExample $s2.Tag }); $it.Tag = $ex }
        [void]$m.Items.Add($sub)
    }
    [void]$m.Items.Add('-')
    [void](Add-MenuItem $m 'Open the sample files folder' { New-SqlExampleFiles; Start-Process explorer.exe $SqlExampleDir } $Glyph.Open)
    $m.Show($Button, (New-Object System.Drawing.Point(0, $Button.Height)))
}

# ---- undo / redo in the editor (Ctrl+Z; Ctrl+Y or Ctrl+Shift+Z). The RichTextBox's own undo can't be used: colouring the
#      SQL counts as edits there, so Ctrl+Z took back colours instead of what you typed. Typing is undone a word at a time,
#      a paste, an example or a suggestion all at once.
function Register-SqlUndo($Ed) {
    $SqlUI.UndoList = New-Object System.Collections.Generic.List[object]
    $SqlUI.RedoList = New-Object System.Collections.Generic.List[object]
    $SqlUI.UndoLast = @{ Text = $Ed.Text; Sel = 0 }
    $SqlUI.UndoAt = [DateTime]::MinValue
    $Ed.add_TextChanged({ Add-SqlUndoStep })
    $Ed.add_KeyDown({
        param($src, $e)
        if (-not $e.Control -or $e.Alt) { return }
        if ($e.KeyCode -eq 'Z' -and -not $e.Shift) { $e.SuppressKeyPress = $true; $e.Handled = $true; Undo-SqlEdit }
        elseif ($e.KeyCode -eq 'Y' -or ($e.KeyCode -eq 'Z' -and $e.Shift)) { $e.SuppressKeyPress = $true; $e.Handled = $true; Undo-SqlEdit -Redo }
    })
}
function Add-SqlUndoStep {
    if ($SqlUI.Coloring -or $SqlUI.Restoring) { return }
    $ed = $SqlUI.Editor; $t = $ed.Text
    $last = $SqlUI.UndoLast
    if ($t -ceq $last.Text) { return }
    $now = Get-Date
    $i = $ed.SelectionStart
    $big = [Math]::Abs($t.Length - $last.Text.Length) -gt 1                                     # a paste, a cut, an example, a suggestion
    $wordEnd = $t.Length -gt $last.Text.Length -and $i -gt 0 -and " `n`t;,()".Contains([string]$t[$i - 1])
    if ($big -or $wordEnd -or ($now - $SqlUI.UndoAt).TotalMilliseconds -gt 1000 -or $SqlUI.UndoList.Count -eq 0) {
        $SqlUI.UndoList.Add($last)
        if ($SqlUI.UndoList.Count -gt 500) { $SqlUI.UndoList.RemoveAt(0) }
    }
    $SqlUI.RedoList.Clear()
    $SqlUI.UndoLast = @{ Text = $t; Sel = $i }
    $SqlUI.UndoAt = if ($big) { [DateTime]::MinValue } else { $now }                           # what comes after a paste is a new step
}
function Undo-SqlEdit([switch]$Redo) {
    if ($Redo) { $from = $SqlUI.RedoList; $to = $SqlUI.UndoList } else { $from = $SqlUI.UndoList; $to = $SqlUI.RedoList }     # (not "$x = if ..." : that would unroll the lists)
    if (-not $from -or $from.Count -eq 0) { Set-SqlStatus $(if ($Redo) { 'Nothing to redo.' } else { 'Nothing to undo.' }) $C.Dim; return }
    Hide-SqlComplete
    $ed = $SqlUI.Editor
    $to.Add(@{ Text = $ed.Text; Sel = $ed.SelectionStart })
    $st = $from[$from.Count - 1]; $from.RemoveAt($from.Count - 1)
    $SqlUI.Restoring = $true
    try {
        $pos = [DgSql]::GetScroll($ed.Handle)
        [PowerClipTheme]::Redraw($ed.Handle, $false)
        try {
            $ed.Text = $st.Text
            $ed.Select([Math]::Min([int]$st.Sel, $ed.TextLength), 0)
            [DgSql]::SetScroll($ed.Handle, $pos)
        } finally { [PowerClipTheme]::Redraw($ed.Handle, $true); $ed.Invalidate() }
    } finally { $SqlUI.Restoring = $false }
    $SqlUI.UndoLast = @{ Text = $st.Text; Sel = $st.Sel }
    $SqlUI.UndoAt = [DateTime]::MinValue
    Set-SqlColors
    $ed.ScrollToCaret()
}

# ---- pasting into the code editors (SQL client, Diagram studio): text only. Ctrl+V of a RichTextBox also brings the
#      formatting of where it came from (a note's font, size, colours, bullets), and text from notes / documents can hold
#      characters SQL doesn't take as spaces or quotes (non-breaking space, zero-width space, curly quotes).
function ConvertTo-PlainCode([string]$Text) {
    $Text.Replace([string][char]0x00A0, ' ').Replace([string][char]0x202F, ' ').Replace([string][char]0x200B, '').Replace([string][char]0xFEFF, '').Replace([string][char]0x2018, "'").Replace([string][char]0x2019, "'").Replace([string][char]0x201C, '"').Replace([string][char]0x201D, '"').Replace("`r`n", "`n").Replace("`r", "`n")
}
function Invoke-PlainPaste($Ed, [string]$Text) {
    if ($null -eq $Text) { return }
    $Ed.SelectedText = ConvertTo-PlainCode $Text
    $Ed.ScrollToCaret()
}
function Register-PlainPaste($Ed) {
    $Ed.add_KeyDown({
        param($src, $e)
        if (($e.Control -and -not $e.Alt -and -not $e.Shift -and $e.KeyCode -eq 'V') -or ($e.Shift -and -not $e.Control -and $e.KeyCode -eq 'Insert')) {
            $e.SuppressKeyPress = $true; $e.Handled = $true
            $t = $null
            try { if ([System.Windows.Forms.Clipboard]::ContainsText()) { $t = [System.Windows.Forms.Clipboard]::GetText() } } catch { }
            Invoke-PlainPaste $src $t
        }
    })
}

# ---- the result grid's right-click menu: copy in many shapes, filter by a value, sort / hide columns, use a value,
#      and totals of the selected cells in the status line
if (-not $SqlUI.GridState) { $SqlUI.GridState = @{} }

# what is selected: whole rows when -Rows (or when only one cell is selected and rows are asked for), else the selected block
function Get-SqlGridPick($Grid, [switch]$Rows) {
    $cells = @($Grid.SelectedCells)
    $ri = @($cells | ForEach-Object { $_.RowIndex } | Where-Object { $_ -ge 0 } | Sort-Object -Unique)
    $ci = @($cells | ForEach-Object { $_.ColumnIndex } | Sort-Object -Unique)
    if ($Rows -or $ci.Count -eq 0) { $ci = @($Grid.Columns | Where-Object { $_.Visible } | ForEach-Object { $_.Index }) }
    $cols = @($ci | ForEach-Object { $Grid.Columns[$_] } | Where-Object { $_.Visible } | Sort-Object DisplayIndex)
    $t = New-Object System.Data.DataTable
    foreach ($col in $cols) { [void]$t.Columns.Add($col.HeaderText, [object]) }
    foreach ($r in $ri) {
        $vals = foreach ($col in $cols) { $v = $Grid.Rows[$r].Cells[$col.Index].Value; if ($null -eq $v) { [DBNull]::Value } else { $v } }
        [void]$t.Rows.Add([object[]]@($vals))
    }
    , $t
}

# a value as SQL: NULL, a number as it is, text quoted ('' doubled; N'' on SQL Server for non-ASCII)
function Format-SqlLiteral($Value, [string]$Dialect) {
    if ($null -eq $Value -or $Value -is [DBNull]) { return 'NULL' }
    $s = [string]$Value
    if ($s -match '^-?\d+(\.\d+)?$' -and -not ($s -match '^-?0\d')) { return $s }
    $q = "'" + $s.Replace("'", "''") + "'"
    if ($Dialect -eq 'mssql' -and ($s.ToCharArray() | Where-Object { [int]$_ -gt 127 })) { return 'N' + $q }
    $q
}

# the table the last query read from (for INSERT statements), else a placeholder
function Get-SqlResultTable {
    $m = [regex]::Match([string]$SqlUI.RunSql, '(?is)\bFROM\s+((?:\[[^\]]+\]|"[^"]+"|[\w#@$]+)(?:\.(?:\[[^\]]+\]|"[^"]+"|[\w#@$]+))*)')
    if ($m.Success -and $m.Groups[1].Value -notmatch '^\[?file:') { $m.Groups[1].Value } else { 'table_name' }
}

function Get-SqlGridText($Grid, [string]$As) {
    $dl = Get-SqlDialect (Get-SqlConn)
    $cell = $Grid.CurrentCell
    $text = switch ($As) {
        'cell' { if ($cell -and $null -ne $cell.Value -and $cell.Value -isnot [DBNull]) { [string]$cell.Value } else { '' } }
        'tsv' { [DgSql]::ToCsv((Get-SqlGridPick $Grid), "`t") -replace '^[^\r\n]*\r\n', '' }
        'tsvh' { [DgSql]::ToCsv((Get-SqlGridPick $Grid), "`t") }
        'csv' { [DgSql]::ToCsv((Get-SqlGridPick $Grid -Rows), ',') }
        'json' { [DgSql]::ToJson((Get-SqlGridPick $Grid -Rows)) }
        'md' {
            $t = Get-SqlGridPick $Grid -Rows
            $cols = @($t.Columns | ForEach-Object { $_.ColumnName })
            $md = @(('| ' + (($cols | ForEach-Object { $_.Replace('|', '\|') }) -join ' | ') + ' |'), ('|' + (($cols | ForEach-Object { ' --- ' }) -join '|') + '|'))
            foreach ($r in $t.Rows) { $md += '| ' + (($r.ItemArray | ForEach-Object { if ($_ -is [DBNull]) { '' } else { ([string]$_).Replace('|', '\|').Replace("`r", ' ').Replace("`n", ' ') } }) -join ' | ') + ' |' }
            $md -join "`r`n"
        }
        'insert' {
            $t = Get-SqlGridPick $Grid -Rows
            $tbl = Get-SqlResultTable
            $names = (@($t.Columns | ForEach-Object { [DgDb]::QuoteName($dl, $_.ColumnName) }) -join ', ')
            (@($t.Rows | ForEach-Object { "INSERT INTO $tbl ($names) VALUES ($((@($_.ItemArray | ForEach-Object { Format-SqlLiteral $_ $dl })) -join ', '));" })) -join "`r`n"
        }
        'in' {
            $vals = @(@($Grid.SelectedCells) | Sort-Object RowIndex | ForEach-Object { $_.Value } | Where-Object { $null -ne $_ -and $_ -isnot [DBNull] } | ForEach-Object { [string]$_ } | Select-Object -Unique)
            '(' + ((@($vals | ForEach-Object { Format-SqlLiteral $_ $dl })) -join ', ') + ')'
        }
        'where' {
            $parts = @(@($Grid.SelectedCells) | Sort-Object ColumnIndex, RowIndex | ForEach-Object {
                $n = [DgDb]::QuoteName($dl, $Grid.Columns[$_.ColumnIndex].HeaderText)
                if ($null -eq $_.Value -or $_.Value -is [DBNull]) { "$n IS NULL" } else { "$n = $(Format-SqlLiteral $_.Value $dl)" } } | Select-Object -Unique)
            $parts -join "`r`n  AND "
        }
        'name' { if ($cell) { $Grid.Columns[$cell.ColumnIndex].HeaderText } else { '' } }
        'names' { (@($Grid.Columns | Where-Object { $_.Visible } | Sort-Object DisplayIndex | ForEach-Object { [DgDb]::QuoteName($dl, $_.HeaderText) })) -join ', ' }
        'column' {
            if (-not $cell) { '' } else {
                $ix = $cell.ColumnIndex
                (@($Grid.Rows | ForEach-Object { $v = $_.Cells[$ix].Value; if ($null -eq $v -or $v -is [DBNull]) { '' } else { [string]$v } })) -join "`r`n"
            }
        }
    }
    $text
}
function Copy-SqlGrid($Grid, [string]$As) {
    $text = [string](Get-SqlGridText $Grid $As)
    try { [System.Windows.Forms.Clipboard]::SetText($(if ($text.Length) { $text } else { ' ' })); Set-SqlStatus "Copied ($As)." $C.Green } catch { Set-SqlStatus "Couldn't copy: $($_.Exception.Message)" $C.Red }
}

# ---- filters: the grid shows the rows that pass; Export / Chart this use what is shown
function Set-SqlGridFilter($Grid, [string]$Column, $Value, [string]$How) {
    $st = $SqlUI.GridState[$Grid]
    if (-not $st) { $st = @{ Full = $Grid.Tag; Filters = (New-Object System.Collections.Generic.List[object]) }; $SqlUI.GridState[$Grid] = $st }
    if ($How -eq 'clear') { $st.Filters.Clear() } else { $st.Filters.Add(@{ Col = $Column; Value = $(if ($null -eq $Value -or $Value -is [DBNull]) { $null } else { [string]$Value }); How = $How }) }
    $full = $st.Full
    $t = $full.Clone()
    $t.BeginLoadData()
    foreach ($r in $full.Rows) {
        $ok = $true
        foreach ($fx in $st.Filters) {
            $v = $r[$fx.Col]; $isNull = $v -is [DBNull] -or $null -eq $v; $s = if ($isNull) { $null } else { [string]$v }
            $hit = switch ($fx.How) {
                'only' { if ($null -eq $fx.Value) { $isNull } else { -not $isNull -and $s -ceq $fx.Value } }
                'not' { if ($null -eq $fx.Value) { -not $isNull } else { $isNull -or $s -cne $fx.Value } }
                'null' { $isNull }
                'notnull' { -not $isNull }
            }
            if (-not $hit) { $ok = $false; break }
        }
        if ($ok) { [void]$t.LoadDataRow($r.ItemArray, $true) }
    }
    $t.EndLoadData()
    $hidden = @($Grid.Columns | Where-Object { -not $_.Visible } | ForEach-Object { $_.Name })
    $Grid.DataSource = $t; $Grid.Tag = $t
    foreach ($h in $hidden) { if ($Grid.Columns[$h]) { $Grid.Columns[$h].Visible = $false } }
    Set-SqlStatus $(if ($st.Filters.Count) { "Filtered: $($t.Rows.Count) of $($full.Rows.Count) rows  ($(@($st.Filters | ForEach-Object { "$($_.Col) $(switch ($_.How) { 'only' { '=' } 'not' { '<>' } 'null' { 'is NULL' } 'notnull' { 'is not NULL' } }) $(if ($_.How -in 'only', 'not') { if ($null -eq $_.Value) { 'NULL' } else { $_.Value } })" }) -join ', '))" } else { "All $($full.Rows.Count) rows." }) $C.Accent
}

# ---- a value in its own window (JSON / XML laid out), to read or copy
function Show-SqlValue([string]$Text, [string]$Title) {
    $shown = $Text
    $tr = $Text.Trim()
    try { if ($tr.StartsWith('{') -or $tr.StartsWith('[')) { $shown = [PowerClipFormat]::JsonSorted($tr) } elseif ($tr.StartsWith('<')) { $shown = [PowerClipFormat]::Xml($tr, $false) } } catch { $shown = $Text }
    $f = New-Object System.Windows.Forms.Form
    $f.Text = "Value  -  $Title"; $f.Icon = $IconActive; $f.StartPosition = 'CenterParent'
    $f.Size = New-Object System.Drawing.Size((Px 760), (Px 520)); $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $box = New-TbBox -Mono -Multi -ReadOnly; $box.Dock = 'Fill'; $box.WordWrap = $true; $box.ScrollBars = 'Vertical'; $box.Text = $shown.Replace("`r`n", "`n").Replace("`n", "`r`n")
    $bar = New-Object System.Windows.Forms.FlowLayoutPanel; $bar.Dock = 'Bottom'; $bar.AutoSize = $true; $bar.BackColor = $C.Panel; $bar.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 6))
    $f.Controls.Add($box); $f.Controls.Add($bar)
    $bc = New-Button 'Copy' 'Copy the value' { [System.Windows.Forms.Clipboard]::SetText($this.Tag) } $bar $Glyph.Copy 1; $bc.Tag = $(if ($Text.Length) { $Text } else { ' ' })
    [void](New-Button 'Close' '' { $this.FindForm().Close() } $bar '' 2)
    $f.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Escape') { $src.Close() } }); $f.KeyPreview = $true
    Register-ThemedWindow $f
    [void]$f.Show($SqlUI.Form)
}

# ---- Count / Sum / Average / Min / Max of the selected cells (numbers), in the status line
function Update-SqlSelectionTotals($Grid) {
    $count0 = $Grid.SelectedCells.Count
    if ($count0 -lt 2) { return }
    if ($count0 -gt 50000) { Set-SqlStatus "$count0 cells selected (totals are worked out for up to 50,000 cells)." $C.Accent; return }
    $cells = @($Grid.SelectedCells)
    $n = 0; $sum = [decimal]0; $min = $null; $max = $null; $count = 0
    foreach ($cl in $cells) {
        $v = $cl.Value
        if ($null -eq $v -or $v -is [DBNull]) { continue }
        $count++
        $d = [decimal]0
        if ([decimal]::TryParse([string]$v, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$d)) {
            $n++; $sum += $d
            if ($null -eq $min -or $d -lt $min) { $min = $d }
            if ($null -eq $max -or $d -gt $max) { $max = $d }
        }
    }
    $fmt = { param($x) ([decimal]$x).ToString('#,0.####', [Globalization.CultureInfo]::InvariantCulture) }
    $msg = "$($cells.Count) cells, $count with a value"
    if ($n) { $msg += "   |   Sum $(& $fmt $sum)   Average $(& $fmt ($sum / $n))   Min $(& $fmt $min)   Max $(& $fmt $max)   ($n numbers)" }
    Set-SqlStatus $msg $C.Accent
}

function Register-SqlGridMenu($Grid) {
    $Grid.add_CellMouseDown({
        param($src, $e)
        if ($e.Button -ne 'Right' -or $e.RowIndex -lt 0 -or $e.ColumnIndex -lt 0) { return }
        $cl = $src.Rows[$e.RowIndex].Cells[$e.ColumnIndex]
        if (-not $cl.Selected) { $src.ClearSelection(); $cl.Selected = $true }
        $src.CurrentCell = $cl
    })
    $Grid.add_SelectionChanged({ param($src, $e) if (-not $SqlUI.GridQuiet) { Update-SqlSelectionTotals $src } })
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $m.Tag = $Grid
    $m.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $g = $src.Tag; $SqlUI.MenuGrid = $g
        $cl = $g.CurrentCell
        if (-not $cl -or $g.Rows.Count -eq 0) { if (-not ($SqlUI.GridState[$g] -and $SqlUI.GridState[$g].Filters.Count)) { $e.Cancel = $true; return } }
        $col = if ($cl) { $g.Columns[$cl.ColumnIndex].HeaderText } else { '' }
        $val = if ($cl) { $cl.Value } else { $null }
        $isNull = $null -eq $val -or $val -is [DBNull]
        $show = if ($isNull) { 'NULL' } else { $sv = [string]$val -replace '\s+', ' '; if ($sv.Length -gt 30) { $sv.Substring(0, 30) + '...' } else { $sv } }
        $SqlUI.MenuCol = $col; $SqlUI.MenuVal = $val
        $sub = { param($title, $glyph) $it = New-Object System.Windows.Forms.ToolStripMenuItem($title, (New-GlyphImage $glyph)); $it.DropDown.Renderer = $MenuRenderer; [void]$src.Items.Add($it); $it }
        $add = { param($menu, $title, $sb, $glyph, $keys) $it = $menu.DropDownItems.Add($title, (New-GlyphImage $glyph), $sb); if ($keys) { $it.ShortcutKeyDisplayString = $keys }; $it }
        if ($cl) {
            [void](Add-MenuItem $src 'Copy with headers' { Copy-SqlGrid $SqlUI.MenuGrid 'tsvh' } $Glyph.Copy 'Ctrl+C')
            [void](Add-MenuItem $src 'Copy without headers' { Copy-SqlGrid $SqlUI.MenuGrid 'tsv' } $Glyph.Copy)
            $cp = & $sub 'Copy as' $Glyph.Copy
            [void](& $add $cp 'This value only' { Copy-SqlGrid $SqlUI.MenuGrid 'cell' } $Glyph.Copy)
            [void](& $add $cp 'CSV (selected rows)' { Copy-SqlGrid $SqlUI.MenuGrid 'csv' } $Glyph.Text)
            [void](& $add $cp 'JSON (selected rows)' { Copy-SqlGrid $SqlUI.MenuGrid 'json' } $Glyph.Code)
            [void](& $add $cp 'Markdown table (selected rows)' { Copy-SqlGrid $SqlUI.MenuGrid 'md' } $Glyph.Text)
            [void](& $add $cp 'INSERT statements (selected rows)' { Copy-SqlGrid $SqlUI.MenuGrid 'insert' } $Glyph.Code)
            [void]$cp.DropDownItems.Add('-')
            [void](& $add $cp 'IN (...) list of the selected values' { Copy-SqlGrid $SqlUI.MenuGrid 'in' } $Glyph.Code)
            [void](& $add $cp 'WHERE condition (column = value)' { Copy-SqlGrid $SqlUI.MenuGrid 'where' } $Glyph.Code)
            [void]$cp.DropDownItems.Add('-')
            [void](& $add $cp "Column name ($col)" { Copy-SqlGrid $SqlUI.MenuGrid 'name' } $Glyph.Text)
            [void](& $add $cp 'All column names' { Copy-SqlGrid $SqlUI.MenuGrid 'names' } $Glyph.Text)
            [void](& $add $cp "All values of $col" { Copy-SqlGrid $SqlUI.MenuGrid 'column' } $Glyph.Text)
            [void]$src.Items.Add('-')
            $fl = & $sub 'Filter' $Glyph.Filter
            [void](& $add $fl "Only rows where $col = $show" { Set-SqlGridFilter $SqlUI.MenuGrid $SqlUI.MenuCol $SqlUI.MenuVal 'only' } $Glyph.Search)
            [void](& $add $fl "Hide rows where $col = $show" { Set-SqlGridFilter $SqlUI.MenuGrid $SqlUI.MenuCol $SqlUI.MenuVal 'not' } $Glyph.Search)
            [void](& $add $fl "Only rows where $col is NULL" { Set-SqlGridFilter $SqlUI.MenuGrid $SqlUI.MenuCol $null 'null' } $Glyph.Search)
            [void](& $add $fl "Only rows where $col has a value" { Set-SqlGridFilter $SqlUI.MenuGrid $SqlUI.MenuCol $null 'notnull' } $Glyph.Search)
        }
        if ($SqlUI.GridState[$g] -and $SqlUI.GridState[$g].Filters.Count) { [void](Add-MenuItem $src "Clear the filters ($($SqlUI.GridState[$g].Filters.Count))" { Set-SqlGridFilter $SqlUI.MenuGrid '' $null 'clear' } $Glyph.Refresh) }
        if (-not $cl) { return }
        $cm = & $sub 'Column' $Glyph.Apps
        [void](& $add $cm 'Sort ascending' { $gg = $SqlUI.MenuGrid; $gg.Sort($gg.Columns[$gg.CurrentCell.ColumnIndex], 'Ascending') } ([string][char]0xE70E))
        [void](& $add $cm 'Sort descending' { $gg = $SqlUI.MenuGrid; $gg.Sort($gg.Columns[$gg.CurrentCell.ColumnIndex], 'Descending') } ([string][char]0xE70D))
        [void](& $add $cm "Hide $col" { $gg = $SqlUI.MenuGrid; $gg.Columns[$gg.CurrentCell.ColumnIndex].Visible = $false } $Glyph.View)
        [void](& $add $cm 'Show all columns' { foreach ($cx in $SqlUI.MenuGrid.Columns) { $cx.Visible = $true } } $Glyph.View)
        [void](& $add $cm 'Freeze columns up to here' { $gg = $SqlUI.MenuGrid; foreach ($cx in $gg.Columns) { $cx.Frozen = $false }; $gg.Columns[$gg.CurrentCell.ColumnIndex].Frozen = $true } $Glyph.Pin)
        [void](& $add $cm 'Fit column widths' { $SqlUI.MenuGrid.AutoResizeColumns('AllCells') } $Glyph.Apps)
        [void]$src.Items.Add('-')
        [void](Add-MenuItem $src 'View the value...' { $v = $SqlUI.MenuVal; Show-SqlValue $(if ($null -eq $v -or $v -is [DBNull]) { 'NULL' } else { [string]$v }) $SqlUI.MenuCol } $Glyph.View)
        [void](Add-MenuItem $src 'Put the value into the editor' { $v = $SqlUI.MenuVal; Insert-SqlText (Format-SqlLiteral $v (Get-SqlDialect (Get-SqlConn))) } $Glyph.Paste)
        [void](Add-MenuItem $src 'Put the selection into the editor as WHERE' { Insert-SqlText ("WHERE " + (Get-SqlGridText $SqlUI.MenuGrid 'where')) } $Glyph.Paste)
        [void]$src.Items.Add('-')
        [void](Add-MenuItem $src 'Chart this' { Send-SqlToDiagram 0 } $Glyph.Apps)
        [void](Add-MenuItem $src 'Diagram this' { Send-SqlToDiagram 1 } $Glyph.Apps)
        [void](Add-MenuItem $src 'Save as CSV...' { Export-SqlResult 'csv' } $Glyph.Save)
        [void](Add-MenuItem $src 'Save as JSON...' { Export-SqlResult 'json' } $Glyph.Save)
    })
    $Grid.ContextMenuStrip = $m
}

# ---- the object tree's filter: the tables / views / procedures / functions of the database selected at the top
#      whose name has every word typed; object lists are read once per database (Refresh reads them again)
function Get-SqlObjectList($Conn, [string]$Db, [string]$Type) {
    if (-not $SqlUI.ObjCache) { $SqlUI.ObjCache = @{} }
    $k = "$($Conn.Name)|$Db|$Type"
    if (-not $SqlUI.ObjCache.ContainsKey($k)) {
        $list = New-Object System.Collections.Generic.List[string[]]
        $t = [DgDb]::Objects((Get-SqlConnString $Conn $Db), $Type)
        foreach ($r in $t.Rows) { $list.Add([string[]]@([string]$r[0], [string]$r[1])) }
        $SqlUI.ObjCache[$k] = $list
    }
    , $SqlUI.ObjCache[$k]
}
function Add-SqlObjectNode($Parent, [string]$Schema, [string]$Name, [string]$Db, [string]$Type) {
    $full = "$Schema.$Name"
    $n = $Parent.Nodes.Add($full); $n.Tag = @{ Kind = 'object'; Db = $Db; Name = $full; Schema = $Schema; Object = $Name; Type = $Type }
    if ($Type -in 'U', 'V') { [void]$n.Nodes.Add('...') }
    $n
}
function Update-SqlTreeFilter {
    $tv = $SqlUI.Tree
    if (-not $tv -or $tv.Nodes.Count -eq 0 -or -not $SqlUI.TreeFilter) { return }
    $q = $SqlUI.TreeFilter.Text.Trim()
    $root = $tv.Nodes[0]
    $dbs = @($root.Nodes | Where-Object { $_.Tag -and $_.Tag.Kind -eq 'db' })
    if (-not $dbs.Count) { return }
    $dbNode = @($dbs | Where-Object { $_.Tag.Db -eq [string]$SqlUI.DbBox.Text }) | Select-Object -First 1
    if (-not $dbNode) { $dbNode = $dbs[0] }                       # Oracle: your own schema is first
    $c0 = Get-SqlConn
    $words = @($q -split '\s+' | Where-Object { $_ })
    $tv.BeginUpdate()
    try {
        $dbNode.Nodes.Clear()
        $total = 0
        foreach ($k in @(@('Tables', 'U'), @('Views', 'V'), @('Procedures', 'P'), @('Functions', 'FN'))) {
            $fn = $dbNode.Nodes.Add($k[0]); $fn.Tag = @{ Kind = 'folder'; Db = $dbNode.Tag.Db; Type = $k[1] }
            if (-not $words.Count) { [void]$fn.Nodes.Add('...'); continue }
            try { $rows = Get-SqlObjectList $c0 $dbNode.Tag.Db $k[1] } catch { $x = $fn.Nodes.Add((Get-SqlError $_)); $x.ForeColor = $C.Red; continue }
            $hits = @($rows | Where-Object { $nm = "$($_[0]).$($_[1])"; -not @($words | Where-Object { $nm.IndexOf($_, [StringComparison]::OrdinalIgnoreCase) -lt 0 }).Count })
            $total += $hits.Count
            $fn.Text = "$($k[0])  ($($hits.Count))"
            foreach ($h in @($hits | Select-Object -First 500)) { [void](Add-SqlObjectNode $fn $h[0] $h[1] $dbNode.Tag.Db $k[1]) }
            if ($hits.Count -gt 500) { $x = $fn.Nodes.Add("... $($hits.Count - 500) more: type more of the name"); $x.ForeColor = $C.Dim }
            if ($hits.Count) { $fn.Expand() } else { $fn.ForeColor = $C.Dim }
        }
        $dbNode.Expand()
        if ($words.Count) { $dbNode.EnsureVisible() }
    } finally { $tv.EndUpdate() }
    $SqlUI.TreeFilterInfo.Text = if ($words.Count) { "$total match$(if ($total -ne 1) { 'es' }) in $($dbNode.Tag.Db)" } else { '' }
}

function Show-SqlClient {
    Hide-Picker
    if (-not (Initialize-Diagrams)) { return }
    if ($SqlUI.Form) { if ($SqlUI.Form.WindowState -eq 'Minimized') { $SqlUI.Form.WindowState = 'Normal' }; $SqlUI.Form.Activate(); return }
    Import-SqlData
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'SQL client'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px 1400), (Px 880)); $f.MinimumSize = New-Object System.Drawing.Size((Px 900), (Px 560))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Panel; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $SqlUI.Form = $f

    # left: object browser, saved queries, history
    $left = New-Object System.Windows.Forms.Panel; $left.Dock = 'Left'; $left.Width = Px 390; $left.BackColor = $C.Bg
    $ltabs = New-TabSet $left
    $pObj = Add-ApiTab $ltabs 'Objects'; $pConn = Add-ApiTab $ltabs 'Connections'; $pSaved = Add-ApiTab $ltabs 'Saved'; $pHist = Add-ApiTab $ltabs 'History'
    $tv = New-Object System.Windows.Forms.TreeView
    $tv.Dock = 'Fill'; $tv.BorderStyle = 'None'; $tv.BackColor = $C.Bg; $tv.ForeColor = $C.Fore; $tv.ItemHeight = $FontMain.Height + (Px 8); $tv.HideSelection = $false; $tv.ShowLines = $false
    $tv.add_BeforeExpand({ param($src, $e) Expand-SqlNode $e.Node })
    $tv.add_NodeMouseDoubleClick({ param($src, $e) $tg = $e.Node.Tag; if ($tg -and $tg.Kind -eq 'object') { Insert-SqlText (ConvertTo-SqlName $tg.Name) } elseif ($tg -and $tg.Kind -eq 'column') { Insert-SqlText "[$($tg.Name)]" } elseif ($tg -and $tg.Kind -eq 'db') { $SqlUI.DbBox.Text = $tg.Db } })
    $tv.add_NodeMouseClick({ param($src, $e) if ($e.Button -eq 'Right') { $src.SelectedNode = $e.Node } })
    $tm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $tm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $n = $SqlUI.Tree.SelectedNode; $tg = if ($n) { $n.Tag } else { $null }
        if ($tg -and $tg.Kind -eq 'object') {
            $SqlUI.MenuObj = $tg
            if ($tg.Type -in 'U', 'V') { [void](Add-MenuItem $src 'First 100 rows' { $o = $SqlUI.MenuObj; $SqlUI.DbBox.Text = $o.Db; $SqlUI.Editor.Text = (Get-SqlTopSql $o); Start-SqlRun } $Glyph.Play) }
            [void](Add-MenuItem $src 'Script it (definition)' { $o = $SqlUI.MenuObj; $SqlUI.DbBox.Text = $o.Db; $SqlUI.Editor.Text = (Get-SqlScriptSql $o); Start-SqlRun } $Glyph.Code)
            if ($tg.Type -eq 'U') { [void](Add-MenuItem $src 'ER diagram from here (with linked tables)' { $o = $SqlUI.MenuObj; $SqlUI.DbBox.Text = $o.Db; New-SqlErDiagram @($o.Name) } $Glyph.Apps) }
            [void](Add-MenuItem $src 'Insert the name' { Insert-SqlText (ConvertTo-SqlName $SqlUI.MenuObj.Name) } $Glyph.Paste)
        } elseif ($tg -and $tg.Kind -eq 'db') {
            $SqlUI.MenuObj = $tg
            [void](Add-MenuItem $src 'Use this database' { $SqlUI.DbBox.Text = $SqlUI.MenuObj.Db } $Glyph.Play)
            [void](Add-MenuItem $src 'ER diagram of all tables' { $SqlUI.DbBox.Text = $SqlUI.MenuObj.Db; New-SqlErDiagram } $Glyph.Apps)
        }
        [void](Add-MenuItem $src 'Refresh' { $SqlUI.ObjCache = @{}; Update-SqlTree } $Glyph.Refresh)
    })
    $tv.ContextMenuStrip = $tm
    $pObj.Controls.Add($tv); $SqlUI.Tree = $tv
    $tfp = New-Object System.Windows.Forms.Panel; $tfp.Dock = 'Top'; $tfp.Height = Px 38; $tfp.BackColor = $C.Bg; $tfp.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 6), (Px 6), (Px 4))
    $tfb = New-Object System.Windows.Forms.TextBox; $tfb.Dock = 'Fill'; $tfb.BorderStyle = 'FixedSingle'; $tfb.BackColor = $C.Bg; $tfb.ForeColor = $C.Fore
    $tfb.add_HandleCreated({ param($src, $e) [PowerClipHost]::SetCueBanner($src.Handle, 'Filter tables, views, procedures, functions...') })
    $tfb.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Escape') { $src.Text = ''; $e.SuppressKeyPress = $true } })
    $tfp.Controls.Add($tfb)
    $tfi = New-Object System.Windows.Forms.Label; $tfi.Dock = 'Top'; $tfi.AutoSize = $false; $tfi.Height = $FontSmall.Height + (Px 4); $tfi.Font = $FontSmall; $tfi.ForeColor = $C.Dim; $tfi.BackColor = $C.Bg; $tfi.Padding = New-Object System.Windows.Forms.Padding((Px 8), 0, 0, 0)
    $pObj.Controls.Add($tfi); $pObj.Controls.Add($tfp)
    $SqlUI.TreeFilter = $tfb; $SqlUI.TreeFilterInfo = $tfi
    $SqlUI.TreeFilterTimer = New-TbDebounce 300 { if ($SqlUI.Form) { Update-SqlTreeFilter } }
    $tfb.add_TextChanged({ $SqlUI.TreeFilterTimer.Stop(); $SqlUI.TreeFilterTimer.Start() })
    $SqlUI.Fl = @{}
    [void](New-SqlFolderList 'connections' $pConn)
    [void](New-SqlFolderList 'queries' $pSaved)
    $SqlUI.LeftTabs = $ltabs
    $hl = New-Object System.Windows.Forms.ListBox; $hl.Dock = 'Fill'; $hl.BorderStyle = 'None'; $hl.BackColor = $C.Bg; $hl.ForeColor = $C.Fore; $hl.IntegralHeight = $false; $hl.ItemHeight = $FontMain.Height + (Px 8); $hl.HorizontalScrollbar = $true
    $hl.add_DoubleClick({ param($src, $e) $i = $src.SelectedIndex; if ($i -ge 0) { $SqlUI.Editor.Text = $SqlUI.History[$i].Sql } })
    $pHist.Controls.Add($hl); $SqlUI.HistList = $hl
    Select-ApiTab $ltabs 'Objects'

    # top: connection, database, run
    $top = New-Object System.Windows.Forms.FlowLayoutPanel
    $top.Dock = 'Top'; $top.AutoSize = $true; $top.WrapContents = $true; $top.BackColor = $C.Panel; $top.Padding = New-Object System.Windows.Forms.Padding((Px 8), (Px 6), (Px 8), (Px 6))
    $SqlUI.ConnBox = New-TbCombo $top @() 220
    $SqlUI.ConnBox.add_SelectionChangeCommitted({
        param($src, $e)
        if ($src.SelectedIndex -eq $SqlUI.Conns.Count) { Add-SqlConnection; return }
        $c0 = Get-SqlConn; if ($c0) { Select-SqlConn $c0 }
    })
    [void](New-Button '' 'Edit the connection' { $c0 = Get-SqlConn; if ($c0) { Edit-SqlConnItem $c0 } else { Add-SqlConnection } } $top $Glyph.Edit 2)
    [void](New-Button '' 'Remove the connection' { $c0 = Get-SqlConn; if ($c0) { Remove-SqlConnItem $c0 } } $top $Glyph.Delete 2)
    $SqlUI.DbLabel = New-TbLabel $top 'Database' -Dim; $SqlUI.DbLabel.Margin = New-Object System.Windows.Forms.Padding((Px 10), (Px 9), (Px 4), 0)
    $SqlUI.DbBox = New-Object System.Windows.Forms.ComboBox; $SqlUI.DbBox.DropDownStyle = 'DropDown'; $SqlUI.DbBox.FlatStyle = 'Flat'; $SqlUI.DbBox.BackColor = $C.Bg; $SqlUI.DbBox.ForeColor = $C.Fore; $SqlUI.DbBox.Width = Px 180
    $SqlUI.DbBox.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 10), 0)
    $SqlUI.DbBox.add_DropDown({ param($src, $e) $t = $src.Text; $src.Items.Clear(); $names = Get-SqlDbNames; if ($names) { foreach ($n in $names) { [void]$src.Items.Add($n) } }; $src.Text = $t })
    $top.Controls.Add($SqlUI.DbBox)
    $SqlUI.DbBox.add_TextChanged({ if ($SqlUI.LiveTimer) { $SqlUI.LiveTimer.Stop(); $SqlUI.LiveTimer.Start() } })
    $SqlUI.RunBtn = New-Button 'Run' 'Run the selection, or everything (F5 / Ctrl+Enter)' { Start-SqlRun } $top $Glyph.Play 1
    $SqlUI.CancelBtn = New-Button 'Cancel' 'Stop the running query' { if ($SqlUI.Run -and -not $SqlUI.Run.Done) { $SqlUI.Run.Cancel() }; if ($SqlUI.PlanRun -and -not $SqlUI.PlanRun.Done) { $SqlUI.PlanRun.Cancel() } } $top $Glyph.Pause 2
    [void](New-Button 'Plan' 'The estimated plan and suggestions (the query is NOT run)  -  Ctrl+L' { Start-SqlPlan $false } $top $Glyph.View 2)
    [void](New-Button 'Run with plan' 'Run the query and get the actual plan with real row counts  -  Ctrl+M' { Start-SqlPlan $true } $top $Glyph.Play 2)
    $SqlUI.CancelBtn.Enabled = $false
    New-TbLabel $top 'Max rows' -Dim | ForEach-Object { $_.Margin = New-Object System.Windows.Forms.Padding((Px 10), (Px 9), (Px 4), 0) }
    $SqlUI.MaxRows = New-TbNumber $top 10000 1 1000000; $SqlUI.MaxRows.Width = Px 90
    [void](New-Button 'Save query' 'Keep this query in Saved (in the folder selected there)' { Save-SqlQuery } $top $Glyph.Save 2)
    [void](New-Button 'Examples' 'Ready queries for each feature: files, joins across connections, other databases, per database, tips' { Show-SqlExamplesMenu $this } $top $Glyph.Text 2)
    [void](New-Button 'ER diagram' 'A diagram of the tables of this database, their columns and keys' { New-SqlErDiagram } $top $Glyph.Apps 2)
    $SqlUI.LiveBtn = New-Button 'Live diagram' 'Show / hide the diagram of the query as you write it' {
        $SqlUI.LiveSplit.Panel2Collapsed = -not $SqlUI.LiveSplit.Panel2Collapsed
        $this.Selected = -not $SqlUI.LiveSplit.Panel2Collapsed; $this.Invalidate()
        Update-SqlLive
    } $top $Glyph.View 2
    $SqlUI.LiveBtn.Selected = $true

    # middle: editor over results
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.SplitterWidth = 5; $split.BackColor = $C.Line; $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $live = New-Object System.Windows.Forms.SplitContainer
    $live.Dock = 'Fill'; $live.Orientation = 'Vertical'; $live.SplitterWidth = 5; $live.BackColor = $C.Line; $live.Panel1.BackColor = $C.Bg; $live.Panel2.BackColor = $C.Bg
    $split.Panel1.Controls.Add($live); $SqlUI.LiveSplit = $live
    $ed = New-TbRtb; $ed.Dock = 'Fill'; $ed.AcceptsTab = $true; $ed.WordWrap = $false
    $ed.Text = "-- F5 or Ctrl+Enter runs the selection, or everything. GO separates batches.`r`n-- Suggestions pop up as you type (Ctrl+Space opens them): Up / Down choose, Tab puts one in.`r`n-- Examples (top bar) adds ready queries: files, joins across connections, other databases.`r`n-- The diagram on the right follows the statement under the cursor as you write it.`r`nSELECT TOP 100 name, create_date FROM sys.tables ORDER BY create_date DESC;"
    $live.Panel1.Controls.Add($ed); $SqlUI.Editor = $ed
    Register-SqlComplete $ed
    Register-SqlUndo $ed
    Register-PlainPaste $ed
    $lcv = New-Object DgCanvas
    $lcv.Dock = 'Fill'; $lcv.UiScale = $Scale * $TextZoom; $lcv.Font = $FontMain; $lcv.Editable = $false; $lcv.Draggable = $true; $lcv.Animate = $false
    $SqlUI.LivePos = @{}
    $lcv.add_Moved({ param($src, $e) foreach ($id in $src.MovedIds) { $n = $src.Doc.Find($id); if ($n) { $SqlUI.LivePos["$($n.Label)|$($n.Badge)"] = @($n.X, $n.Y) } } })
    $lcv.add_SelectionChanged({
        param($src, $e)
        $id = $src.SelectedId; if (-not $id) { return }
        $m = $null; if ([DgSqlViz]::Map.TryGetValue($id, [ref]$m)) { $SqlUI.LiveQuiet = $true; $SqlUI.Editor.Select($m[0], $m[1]); $SqlUI.Editor.ScrollToCaret(); $SqlUI.LiveQuiet = $false }
    })
    $lbar = New-Object System.Windows.Forms.FlowLayoutPanel; $lbar.Dock = 'Top'; $lbar.AutoSize = $true; $lbar.WrapContents = $true; $lbar.BackColor = $C.Panel; $lbar.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 3), (Px 6), (Px 3))
    [void](New-Button 'Open in Diagram studio' 'Edit, style or export this diagram' { if ($SqlUI.LiveText) { Show-DiagramStudio; New-DiagramFromText 'Query' $SqlUI.LiveText } } $lbar $Glyph.Apps 2)
    [void](New-Button 'Refresh columns' 'Read the tables and columns of the database again' { $SqlUI.SchemaKey = '-'; $SqlUI.SourcesSig = ''; $SqlUI.DbNames = @{}; Update-SqlLive } $lbar $Glyph.Refresh 2)
    [void](New-Button 'Tidy up' 'Lay the tables out again (forgets where you dragged them)' { $SqlUI.LivePos = @{}; $SqlUI.LiveSig = ''; Update-SqlLive } $lbar $Glyph.Apps 2)
    $SqlUI.LiveInfo = New-TbLabel $lbar '' -Dim; $SqlUI.LiveInfo.Margin = New-Object System.Windows.Forms.Padding((Px 8), (Px 8), 0, 0)
    $live.Panel2.Controls.Add($lcv); $live.Panel2.Controls.Add($lbar)
    $SqlUI.LiveCanvas = $lcv
    $rb = New-Object System.Windows.Forms.FlowLayoutPanel; $rb.Dock = 'Bottom'; $rb.AutoSize = $true; $rb.BackColor = $C.Panel; $rb.Padding = New-Object System.Windows.Forms.Padding((Px 6), (Px 4), (Px 6), (Px 4))
    [void](New-Button 'Copy' 'Copy the result with headers (tab-separated, pastes into Excel)' { Export-SqlResult 'copy' } $rb $Glyph.Copy 2)
    [void](New-Button 'CSV...' 'Save the result as CSV' { Export-SqlResult 'csv' } $rb $Glyph.Save 2)
    [void](New-Button 'JSON...' 'Save the result as JSON' { Export-SqlResult 'json' } $rb $Glyph.Save 2)
    [void](New-Button 'Chart this' 'Make a chart of this result in the Diagram studio' { Send-SqlToDiagram 0 } $rb $Glyph.Apps 2)
    [void](New-Button 'Diagram this' 'Make a links / tree diagram of this result in the Diagram studio' { Send-SqlToDiagram 1 } $rb $Glyph.Apps 2)
    $SqlUI.Status = New-TbLabel $rb '' -Dim; $SqlUI.Status.Margin = New-Object System.Windows.Forms.Padding((Px 12), (Px 9), 0, 0)
    $resHost = New-Object System.Windows.Forms.Panel; $resHost.Dock = 'Fill'; $resHost.BackColor = $C.Bg
    $split.Panel2.Controls.Add($resHost); $split.Panel2.Controls.Add($rb)
    $SqlUI.ResTabs = New-TabSet $resHost

    $f.Controls.Add($split); $f.Controls.Add($left); $f.Controls.Add($top)
    New-SqlCompleteList $f
    $f.add_Deactivate({ Hide-SqlComplete })
    $split.BringToFront()

    $SqlUI.ColorTimer = New-TbDebounce 450 { if ($SqlUI.Form) { Set-SqlColors } }
    $ed.add_TextChanged({ if ($SqlUI.Coloring) { return }; $SqlUI.ColorTimer.Stop(); $SqlUI.ColorTimer.Start(); $SqlUI.LiveTimer.Stop(); $SqlUI.LiveTimer.Start() })
    $SqlUI.LiveTimer = New-TbDebounce 450 { if ($SqlUI.Form) { try { Update-SqlLive } catch { Write-Log "live diagram: $_" } } }
    $ed.add_SelectionChanged({ if (-not $SqlUI.Coloring -and -not $SqlUI.LiveQuiet -and $SqlUI.LiveTimer) { $SqlUI.LiveTimer.Stop(); $SqlUI.LiveTimer.Start() } })
    $SqlUI.PlanTimer = New-Object System.Windows.Forms.Timer; $SqlUI.PlanTimer.Interval = 120
    $SqlUI.PlanTimer.add_Tick({ if (-not $SqlUI.PlanRun) { $SqlUI.PlanTimer.Stop(); return }; if ($SqlUI.PlanRun.Done) { $SqlUI.PlanTimer.Stop(); try { Complete-SqlPlan } catch { Set-SqlStatus "Plan: $_" $C.Red } } else { Set-SqlStatus "Working...  $([Math]::Round(((Get-Date) - $SqlUI.Started).TotalSeconds, 1)) s" $C.Accent } })
    $SqlUI.Timer = New-Object System.Windows.Forms.Timer; $SqlUI.Timer.Interval = 120
    $SqlUI.Timer.add_Tick({ if (-not $SqlUI.Run) { $SqlUI.Timer.Stop(); return }; if ($SqlUI.Run.Done) { $SqlUI.Timer.Stop(); Complete-SqlRun } else { Set-SqlStatus "Running...  $([Math]::Round(((Get-Date) - $SqlUI.Started).TotalSeconds, 1)) s" $C.Accent } })
    $f.add_KeyDown({
        param($src, $e)
        if ($e.KeyCode -eq 'F5' -or ($e.Control -and $e.KeyCode -eq 'Return')) { $e.SuppressKeyPress = $true; Start-SqlRun }
        elseif ($e.Control -and $e.KeyCode -eq 'L') { $e.SuppressKeyPress = $true; Start-SqlPlan $false }
        elseif ($e.Control -and $e.KeyCode -eq 'M') { $e.SuppressKeyPress = $true; Start-SqlPlan $true }
        elseif ($e.KeyCode -eq 'Escape' -and $SqlUI.Run -and -not $SqlUI.Run.Done) { $SqlUI.Run.Cancel() }
    })
    $f.add_FormClosed({ if ($SqlUI.Run -and -not $SqlUI.Run.Done) { $SqlUI.Run.Cancel() }; foreach ($k in 'Timer', 'ColorTimer', 'LiveTimer', 'PlanTimer', 'AcTimer', 'TreeFilterTimer') { if ($SqlUI[$k]) { $SqlUI[$k].Dispose(); $SqlUI[$k] = $null } }; $SqlUI.Form = $null; $SqlUI.SchemaKey = ''; $SqlUI.Fl = @{}; $SqlUI.Ac = $null })
    Register-ThemedWindow $f
    $f.Show()
    [PowerClipHost]::EnsureShown($f.Handle)
    $split.SplitterDistance = [int]($split.Height * 0.5)
    $live.SplitterDistance = [int]($live.Width * 0.45)
    Update-SqlConnList
    $c0 = Get-SqlConn; if ($c0) { $SqlUI.DbBox.Text = $c0.Database }
    Update-SqlDbLabel
    Update-SqlSideLists
    Set-SqlColors
    Update-SqlTree
    Update-SqlLive
    if (-not $SqlUI.Conns.Count) { Set-SqlStatus 'Pick "New connection..." in the list at the top left to start.' $C.Accent }
}


Register-PaletteCommand 'SQL client' '' $Glyph.Code { Show-SqlClient } 'sql server database query select table er diagram mssql tsql'
Register-PaletteCommand 'Diagram studio' '' $Glyph.Apps { Show-DiagramStudio } 'diagram flowchart mermaid svg architecture network map draw chart graph org'

$ToolGroups = [ordered]@{
    'Clipboard & notes'     = @('Clipboard history', 'Notes', 'Snippets', 'Secrets', 'Paste stack=Paste stack: collect what I copy next')
    'Text & data'           = @('Transform=Transform text', 'page:json', 'page:regex', 'page:jwt', 'page:markdown', 'page:numbers', 'page:units', 'page:cron', 'page:time', 'page:gen')
    'Encode & share'        = @('page:qr', 'page:stego', 'page:codeimg')
    'Files'                 = @('Compare', 'Find in files', 'page:hash', 'page:log')
    'Web & API'             = @('API tester', 'API chains', 'Test API=Test API: start / stop')
    'Data'                  = @('Diagram studio', 'SQL client')
    'Network'               = @('Network tools', 'page:dns', 'page:subnet', 'page:hosts', 'page:ports', 'page:cert', 'page:certmake')
    'System'                = @('page:env', 'page:procs', 'Git')
    'Screen & productivity' = @('Screenshot=Take a screenshot', 'Text from a picture (OCR)=Copy text from the clipboard picture (OCR)', 'Edit clipboard picture=Edit the picture on the clipboard', 'page:color', 'page:record', 'page:timer', 'Reminder=New reminder...', 'page:mouse')
}

# One row per tool: Group, Title, Icon, and either Page (a Toolbox page) or Action (opens its own window / does it).
function Get-ToolRows {
    $seen = @{}
    foreach ($g in $ToolGroups.Keys) {
        foreach ($e in $ToolGroups[$g]) {
            if ($e -like 'page:*') {
                $p = $TbUI.Pages[$e.Substring(5)]
                if ($p) { $seen[$p.Key] = $true; [pscustomobject]@{ Id = "page:$($p.Key)"; Group = $g; Title = $p.Title; Icon = $p.Icon; Page = $p.Key; Action = $null; Words = $p.Words; Cmd = $null } }
            } else {
                if ($e -match '^(.+?)=(.+)$') { $label = $Matches[1]; $cmd = $Matches[2] } else { $label = $e; $cmd = $e }
                $pcmd = $script:PaletteCommands | Where-Object { $_.Title -eq $cmd } | Select-Object -First 1
                if ($pcmd) { [pscustomobject]@{ Id = "tool:$label"; Group = $g; Title = $label; Icon = $pcmd.Icon; Page = $null; Action = $pcmd.Action; Words = "$cmd $($pcmd.Words)"; Cmd = $pcmd } }
            }
        }
    }
    foreach ($p in $TbUI.Pages.Values) {          # a page nobody placed yet still shows up
        if (-not $seen[$p.Key]) { [pscustomobject]@{ Id = "page:$($p.Key)"; Group = 'More'; Title = $p.Title; Icon = $p.Icon; Page = $p.Key; Action = $null; Words = $p.Words; Cmd = $null } }
    }
}

# From the picker some tools use the selected clip(s): Compare compares two selected clips, and so on.
$PickerToolActions = @{
    'tool:Notes' = { Hide-Picker; Show-Notes }; 'tool:Compare' = { Compare-Selected }; 'tool:API tester' = { Open-ApiFromPicker }
    'tool:Transform' = { Open-TransformFromPicker }; 'tool:Network tools' = { Open-NetworkFromPicker }
}

function Invoke-ToolRow($Row, [switch]$FromPicker) {
    if ($FromPicker -and $PickerToolActions.ContainsKey($Row.Id)) { & $PickerToolActions[$Row.Id]; return }
    if ($Row.Page) { Show-Toolbox $Row.Page } else { & $Row.Action $null }
}

# ---- Favourites: starred tools (in the order they were starred)
function Get-FavoriteRows {
    $rows = @(Get-ToolRows)
    foreach ($id in $script:Favorites) { $r = $rows | Where-Object { $_.Id -eq $id } | Select-Object -First 1; if ($r) { $r } }
}
function Test-Favorite($Row) { $Row -and $Row.Id -and ($script:Favorites -contains $Row.Id) }
function Switch-Favorite($Row) {
    if (-not $Row -or -not $Row.Id) { return }
    if ($script:Favorites -contains $Row.Id) { $script:Favorites = @($script:Favorites | Where-Object { $_ -ne $Row.Id }) }
    else { $script:Favorites = @($script:Favorites) + $Row.Id }
    Save-Settings
    Update-Favorites
}
# everywhere favourites show: the Toolbox sidebar, the picker's top bar, the tray menu (rebuilt when it opens)
function Update-Favorites {
    if ($TbUI.List) { Update-ToolboxSidebar $(if ($TbUI.Search) { $TbUI.Search.Text } else { '' }) }
    Update-FavoriteButtons
}

# The picker's top bar: one icon per favourite, before Toolbox and All.
function Update-FavoriteButtons {
    if (-not $tools) { return }
    foreach ($b in @($script:FavButtons)) { if ($b) { $tools.Controls.Remove($b); [void]$script:IconTips.Remove($b); $b.Dispose() } }
    $script:FavButtons = @()
    $i = 0
    foreach ($r in @(Get-FavoriteRows | Select-Object -First 12)) {
        $b = New-IconButton $r.Icon ($r.Title.Substring(0, [Math]::Min(6, $r.Title.Length))) "$($r.Title)  -  favourite (right-click: remove from favourites)" { param($src, $e) Invoke-ToolRow $src.Tag -FromPicker } $tools
        $b.Tag = $r
        $cm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
        $it = Add-MenuItem $cm 'Remove from favourites' { param($s2, $e2) Switch-Favorite $s2.Owner.Tag } $Glyph.StarOff
        $cm.Tag = $r
        $b.ContextMenuStrip = $cm
        $tools.Controls.SetChildIndex($b, $i)
        $script:FavButtons += $b
        $i++
    }
}

# The palette shows each tool's group (and its keys) next to it.
function Set-PaletteGroups {
    foreach ($r in @(Get-ToolRows)) {
        $pcmd = if ($r.Cmd) { $r.Cmd } else { $script:PaletteCommands | Where-Object { $_.Title -eq $r.Title -and $_.Sub -eq 'Toolbox' } | Select-Object -First 1 }
        if (-not $pcmd) { continue }
        if (-not $pcmd.ToolId) { $pcmd | Add-Member -NotePropertyName ToolId -NotePropertyValue $r.Id -Force }     # so the palette can star it
        if ($pcmd.Grouped) { continue }
        $pcmd.Sub = if ($pcmd.Sub -and $pcmd.Sub -ne 'Toolbox') { "$($r.Group)  -  $($pcmd.Sub)" } else { $r.Group }
        $pcmd | Add-Member -NotePropertyName Grouped -NotePropertyValue $true -Force
    }
}

# Tray menu: one submenu per group.
function Add-ToolGroupMenus($Menu) {
    $rows = @(Get-ToolRows)
    foreach ($g in @($rows | ForEach-Object { $_.Group } | Select-Object -Unique)) {
        $sub = New-Object System.Windows.Forms.ToolStripMenuItem($g)
        $sub.DropDown.Renderer = $MenuRenderer
        foreach ($r in @($rows | Where-Object { $_.Group -eq $g })) {
            $it = $sub.DropDownItems.Add($r.Title, (New-GlyphImage $r.Icon), { param($s2, $e2) Invoke-ToolRow $s2.Tag })
            $it.Tag = $r
        }
        [void]$Menu.Items.Add($sub)
    }
}

# Toolbox sidebar: group headings, the tools under them (those that open their own window have an arrow),
# filtered by the search box.
function Update-ToolboxSidebar([string]$Filter = '') {
    $l = $TbUI.List
    if (-not $l) { return }
    $f = $Filter.Trim()
    $all = @(Get-ToolRows)
    $favs = @(Get-FavoriteRows | ForEach-Object { $x = $_.PSObject.Copy(); $x.Group = 'Favourites'; $x })
    $rows = @(@($favs) + @($all) | Where-Object { -not $f -or "$($_.Title) $($_.Group) $($_.Words)" -like "*$f*" })
    $TbUI.Rows = New-Object System.Collections.Generic.List[object]
    $g = $null
    foreach ($r in $rows) {
        if ($r.Group -ne $g) { $g = $r.Group; $TbUI.Rows.Add([pscustomobject]@{ Header = $g }) }
        $TbUI.Rows.Add($r)
    }
    $TbUI.Sidebar = $true
    $l.BeginUpdate()
    try {
        $l.Items.Clear()
        for ($i = 0; $i -lt $TbUI.Rows.Count; $i++) { [void]$l.Items.Add($i) }
        $l.SelectedIndex = Get-ToolboxRowIndex $TbUI.Current
    } finally { $l.EndUpdate(); $TbUI.Sidebar = $false }
}

function Get-ToolboxRowIndex([string]$Key) {
    if (-not $TbUI.Rows -or -not $Key) { return -1 }
    for ($i = 0; $i -lt $TbUI.Rows.Count; $i++) { if ($TbUI.Rows[$i].Page -eq $Key) { return $i } }
    -1
}

function Show-Toolbox([string]$Page = '', $InputText = $null) {
    Hide-Picker
    if (-not $TbUI.Form -or $TbUI.Form.IsDisposed) { New-ToolboxForm }
    if (-not $Page) { $Page = if ($TbUI.Current) { $TbUI.Current } else { @(Get-ToolRows | Where-Object { $_.Page })[0].Page } }
    Select-ToolboxPage $Page
    if ($null -ne $InputText -and $TbUI.Pages[$Page].State.SetInput) { & $TbUI.Pages[$Page].State.SetInput ([string]$InputText) }
    if ($TbUI.Form.WindowState -eq 'Minimized') { $TbUI.Form.WindowState = 'Normal' }
    $TbUI.Form.Show()
    [PowerClipHost]::EnsureShown($TbUI.Form.Handle)
    $TbUI.Form.Activate()
}

# A control docked to Fill must be laid out after its Top / Bottom neighbours; bringing it to the
# front of the z-order does that, whatever order the page added its controls in.
function Repair-Docking($Ctl) {
    foreach ($cx in @($Ctl.Controls)) {
        if ($cx.Dock -eq 'Fill') { $cx.BringToFront() }
        if ($cx.Controls.Count -gt 0) { Repair-Docking $cx }
    }
}

function Select-ToolboxPage([string]$Key) {
    $p = $TbUI.Pages[$Key]
    if (-not $p) { return }
    if (-not $p.Panel) {
        $panel = New-Object System.Windows.Forms.Panel
        $panel.Dock = 'Fill'; $panel.BackColor = $C.Bg; $panel.Visible = $false
        $TbUI.Host.Controls.Add($panel)
        $p.Panel = $panel
        $p.State = @{}                       # exists before the page is built, so its event handlers can use it
        [void](& $p.Build $panel $p.State)
        Repair-Docking $panel
        if ($TbUI.Form.IsHandleCreated) { Set-ControlTheme $panel $null $script:IsDark }
    }
    foreach ($x in $TbUI.Pages.Values) { if ($x.Panel) { $x.Panel.Visible = ($x.Key -eq $Key) } }
    $TbUI.Current = $Key
    $idx = Get-ToolboxRowIndex $Key
    if ($TbUI.List.SelectedIndex -ne $idx) { $TbUI.Sidebar = $true; try { $TbUI.List.SelectedIndex = $idx } finally { $TbUI.Sidebar = $false } }
    $TbUI.Form.Text = "Toolbox  -  $($p.Title)"
    if ($p.State.Focus) { & $p.State.Focus }
}

function New-ToolboxForm {
    $f = New-Object System.Windows.Forms.Form
    $f.Text = 'Toolbox'; $f.Icon = $IconActive
    $f.Size = New-Object System.Drawing.Size((Px (1180 * $TextZoom)), (Px 780))
    $f.MinimumSize = New-Object System.Drawing.Size((Px 760), (Px 460))
    $f.StartPosition = 'CenterScreen'; $f.BackColor = $C.Bg; $f.ForeColor = $C.Fore; $f.Font = $FontMain; $f.KeyPreview = $true
    $TbUI.Form = $f
    $hostPanel = New-Object System.Windows.Forms.Panel
    $hostPanel.Dock = 'Fill'; $hostPanel.BackColor = $C.Bg
    $f.Controls.Add($hostPanel)
    $TbUI.Host = $hostPanel
    $side = New-Object System.Windows.Forms.Panel
    $side.Dock = 'Left'; $side.Width = Px (240 * $TextZoom); $side.BackColor = $C.Panel
    $list = New-Object DevBufferedListBox
    $list.Dock = 'Fill'; $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawFixed'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + (Px 14); $list.BackColor = $C.Panel; $list.ForeColor = $C.Fore
    $side.Controls.Add($list)
    $sp = New-Object System.Windows.Forms.Panel
    $sp.Dock = 'Top'; $sp.Height = $FontMain.Height + (Px 22); $sp.BackColor = $C.Panel; $sp.Padding = New-Object System.Windows.Forms.Padding((Px 10), (Px 8), (Px 10), (Px 4))
    $search = New-TbBox -Cue 'Search  (right-click: star)'
    $search.Dock = 'Fill'
    $sp.Controls.Add($search)
    $side.Controls.Add($sp)
    $TbUI.Search = $search
    $search.add_TextChanged({ param($src, $e) Update-ToolboxSidebar $src.Text })
    $search.add_KeyDown({
        param($src, $e)
        if ($e.KeyCode -eq 'Escape') { $src.Text = ''; $e.SuppressKeyPress = $true }
        elseif ($e.KeyCode -eq 'Return') {
            $first = @($TbUI.Rows | Where-Object { -not $_.Header })[0]
            if ($first) { Invoke-ToolRow $first }
            $e.SuppressKeyPress = $true
        }
        elseif ($e.KeyCode -eq 'Down') { [void]$TbUI.List.Focus(); $e.SuppressKeyPress = $true }
    })
    $list.add_DrawItem({
        param($src, $e)
        if ($e.Index -lt 0 -or $e.Index -ge $TbUI.Rows.Count) { return }
        $p = $TbUI.Rows[$e.Index]
        $g = $e.Graphics; $r = $e.Bounds
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0 -and -not $p.Header
        $b = New-Object System.Drawing.SolidBrush $C.Panel; $g.FillRectangle($b, $r); $b.Dispose()
        if ($p.Header) {
            [System.Windows.Forms.TextRenderer]::DrawText($g, $p.Header.ToUpperInvariant(), $FontSmall, (New-Object System.Drawing.Rectangle(($r.X + (Px 16)), ($r.Y + (Px 6)), ($r.Width - (Px 16)), ($r.Height - (Px 6)))), $C.Accent,
                [System.Windows.Forms.TextFormatFlags]'Bottom, Left, NoPrefix, SingleLine, EndEllipsis')
            return
        }
        if ($sel) {
            $g.SmoothingMode = 'AntiAlias'
            $path = [PowerClipTheme]::Round((New-Object System.Drawing.RectangleF(($r.X + (Px 6)), ($r.Y + (Px 2)), ($r.Width - (Px 12)), ($r.Height - (Px 4)))), (Px 6))
            $b = New-Object System.Drawing.SolidBrush $C.Sel; $g.FillPath($b, $path); $b.Dispose(); $path.Dispose()
            $g.SmoothingMode = 'Default'
            $bar = New-Object System.Drawing.SolidBrush $C.Accent; $g.FillRectangle($bar, ($r.X + (Px 6)), ($r.Y + (Px 9)), (Px 3), ($r.Height - (Px 18))); $bar.Dispose()
        }
        $x = $r.X + (Px 18)
        if ($FontIconSmall) {
            [System.Windows.Forms.TextRenderer]::DrawText($g, $p.Icon, $FontIconSmall, (New-Object System.Drawing.Rectangle($x, $r.Y, (Px 20), $r.Height)), $(if ($sel) { $C.Accent } else { $C.Dim }),
                [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding')
            $x += Px 30
        }
        $right = $r.Right
        if ((Test-Favorite $p) -and $FontIconSmall) {      # starred
            [System.Windows.Forms.TextRenderer]::DrawText($g, $Glyph.StarOn, $FontIconSmall, (New-Object System.Drawing.Rectangle(($right - (Px 30)), $r.Y, (Px 20), $r.Height)), $C.Yellow,
                [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding')
            $right -= Px 26
        }
        if ($p.Action -and $FontIconSmall) {       # opens its own window
            [System.Windows.Forms.TextRenderer]::DrawText($g, $Glyph.Open, $FontIconSmall, (New-Object System.Drawing.Rectangle(($right - (Px 30)), $r.Y, (Px 20), $r.Height)), $C.Dim,
                [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine, NoPadding')
            $right -= Px 32
        }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $p.Title, $FontMain, (New-Object System.Drawing.Rectangle($x, $r.Y, ($right - $x), $r.Height)), $C.Fore, $TextFlags)
    })
    # pages show on the right; tools with their own window open with a click; headings can't be picked
    $list.add_SelectedIndexChanged({
        param($src, $e)
        if ($TbUI.Sidebar -or $src.SelectedIndex -lt 0) { return }
        $row = $TbUI.Rows[$src.SelectedIndex]
        if ($row.Page) { if ($row.Page -ne $TbUI.Current) { Select-ToolboxPage $row.Page } }
        else { $TbUI.Sidebar = $true; try { $src.SelectedIndex = Get-ToolboxRowIndex $TbUI.Current } finally { $TbUI.Sidebar = $false } }
    })
    $list.add_MouseClick({ param($src, $e) if ($e.Button -ne 'Left') { return }; $i = $src.IndexFromPoint($e.Location); if ($i -ge 0 -and $i -lt $TbUI.Rows.Count -and $TbUI.Rows[$i].Action) { Invoke-ToolRow $TbUI.Rows[$i] } })
    # right-click a tool: add to / remove from favourites
    $fm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $fm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $l = $TbUI.List
        $i = $l.IndexFromPoint($l.PointToClient([System.Windows.Forms.Cursor]::Position))
        if ($i -lt 0 -or $i -ge $TbUI.Rows.Count -or $TbUI.Rows[$i].Header) { $e.Cancel = $true; return }
        $r = $TbUI.Rows[$i]; $src.Tag = $r
        if (Test-Favorite $r) { [void](Add-MenuItem $src 'Remove from favourites' { param($s2, $e2) Switch-Favorite $s2.Owner.Tag } $Glyph.StarOff) }
        else { [void](Add-MenuItem $src 'Add to favourites (top of this list, picker top bar, tray menu)' { param($s2, $e2) Switch-Favorite $s2.Owner.Tag } $Glyph.StarOn) }
        [void](Add-MenuItem $src 'Open' { param($s2, $e2) Invoke-ToolRow $s2.Owner.Tag } $Glyph.Open)
    })
    $list.ContextMenuStrip = $fm
    $f.Controls.Add($side)
    $TbUI.List = $list
    Update-ToolboxSidebar
    $f.add_KeyDown({
        param($src, $e)
        if ($e.Control -and $e.KeyCode -in 'PageDown', 'PageUp') {       # next / previous page
            $keys = @($TbUI.Rows | Where-Object { $_.Page } | ForEach-Object { $_.Page })
            if ($keys) { $i = [array]::IndexOf($keys, $TbUI.Current); $i = if ($e.KeyCode -eq 'PageDown') { ($i + 1) % $keys.Count } else { ($i - 1 + $keys.Count) % $keys.Count }; Select-ToolboxPage $keys[$i] }
            $e.SuppressKeyPress = $true
        }
        elseif ($e.Control -and $e.KeyCode -eq 'F' -and $e.Shift) { [void]$TbUI.Search.Focus(); $e.SuppressKeyPress = $true }
    })
    $f.add_FormClosed({
        param($src, $e)
        foreach ($p in $TbUI.Pages.Values) { if ($p.State -and $p.State.Close) { try { & $p.State.Close } catch { } }; $p.Panel = $null; $p.State = $null }
        $TbUI.Form = $null; $TbUI.Current = $null; $TbUI.List = $null; $TbUI.Rows = $null
        $src.Dispose()
    })
    Register-ThemedWindow $f
}

# ======================================================================================
# JSON, YAML, CSV and XML: convert any to any, tree view with paths, JSONPath query, loop code helper.
# ======================================================================================
$DataFormats = [ordered]@{ 'Detect' = 'auto'; 'JSON' = 'json'; 'YAML' = 'yaml'; 'CSV' = 'csv'; 'Tab-separated' = 'tsv'; 'XML' = 'xml' }

function Get-JsonTreeText($Name, $Value) {
    $t = [DevJson]::TypeName($Value)
    if ($t -eq 'object' -or $t -eq 'array') { return "$Name  $([DevJson]::Short($Value, 60))" }
    "$Name : $([DevJson]::Short($Value, 120))"
}

# A path step: K = key, or I = array index.
function New-PathStep([string]$Key) {
    if ($Key -match '^\[(\d+)\]$') { [pscustomobject]@{ K = $null; I = [int]$Matches[1] } } else { [pscustomobject]@{ K = $Key; I = -1 } }
}

function Add-JsonTreeChildren($Nodes, $Value, $Steps = @()) {
    $n = 0
    foreach ($kv in [DevJson]::Children($Value)) {
        if (++$n -gt 2000) { [void]$Nodes.Add("... $(([DevJson]::Children($Value)).Count - 2000) more"); break }
        $node = New-Object System.Windows.Forms.TreeNode((Get-JsonTreeText $kv.Key $kv.Value))
        $node.Tag = [pscustomobject]@{ V = $kv.Value; Steps = @($Steps) + @(New-PathStep $kv.Key) }
        if ([DevJson]::Children($kv.Value).Count -gt 0) { [void]$node.Nodes.Add('') }
        [void]$Nodes.Add($node)
    }
}

Register-ToolboxPage 'json' 'JSON, YAML, CSV, XML' $Glyph.Code 'json yaml yml csv tsv tab separated delimited excel xml convert format pretty minify jsonpath tree validate path loop foreach code' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $bar = New-TbBar $panel
    $st.Input = New-TbBox -Mono -Multi -Cue 'Paste JSON, YAML, CSV or XML here'
    $st.Input.Dock = 'Fill'
    $split.Panel1.Controls.Add($st.Input)
    $ibar = New-TbBar $split.Panel1
    New-TbLabel $ibar 'Input' -Title | Out-Null
    $st.From = New-TbCombo $ibar @($DataFormats.Keys) 100
    $st.Detected = New-TbLabel $ibar '' -Dim

    $tabs = New-TabSet $split.Panel2
    $outPanel = Add-ApiTab $tabs 'Output'
    $treePanel = Add-ApiTab $tabs 'Tree'
    $pathPanel = Add-ApiTab $tabs 'Path & loop code'
    $queryPanel = Add-ApiTab $tabs 'Query'
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'
    $outPanel.Controls.Add($st.Output)
    $st.Tree = New-Object System.Windows.Forms.TreeView
    $st.Tree.Dock = 'Fill'; $st.Tree.BorderStyle = 'None'; $st.Tree.BackColor = $C.Bg; $st.Tree.ForeColor = $C.Fore
    $st.Tree.Font = New-Object System.Drawing.Font('Consolas', (Fz 10)); $st.Tree.HideSelection = $false
    $st.Tree.add_BeforeExpand({
        param($src, $e)
        if ($e.Node.Nodes.Count -eq 1 -and $e.Node.Nodes[0].Text -eq '') { $e.Node.Nodes.Clear(); Add-JsonTreeChildren $e.Node.Nodes $e.Node.Tag.V $e.Node.Tag.Steps }
    })
    $st.Tree.add_AfterSelect({ param($src, $e) $s = $TbUI.Pages['json'].State; if ($e.Node.Tag) { Update-JsonPathHelp $s $e.Node.Tag } })
    $st.Tree.add_NodeMouseDoubleClick({ param($src, $e) $s = $TbUI.Pages['json'].State; if ($e.Node.Tag) { Update-JsonPathHelp $s $e.Node.Tag; Select-ApiTab $s.Tabs 'Path & loop code' } })
    $treePanel.Controls.Add($st.Tree)
    $tbar = New-TbBar $treePanel 'Bottom'
    New-TbLabel $tbar 'Click a value to see its path and the code to read it (or loop over its list). Double-click opens Path & loop code.' -Dim | Out-Null
    $st.Code = New-TbRtb -ReadOnly; $st.Code.Dock = 'Fill'
    $pathPanel.Controls.Add($st.Code)
    $pbar = New-TbBar $pathPanel
    New-TbLabel $pbar 'Code reads' -Dim | Out-Null
    $st.CodeFor = New-TbCombo $pbar @('the input as it is', 'the converted JSON') 170
    $st.CodeFor.add_SelectedIndexChanged({ $s = $TbUI.Pages['json'].State; if ($s.PathTag) { Update-JsonPathHelp $s $s.PathTag } })
    $st.Lang = New-TbCombo $pbar @('All languages', 'JavaScript', 'Python', 'C#', 'PowerShell', 'Command line') 150
    $st.Lang.add_SelectedIndexChanged({ $s = $TbUI.Pages['json'].State; if ($s.PathTag) { Update-JsonPathHelp $s $s.PathTag } })
    [void](New-Button 'Copy' 'Copy the selected text, or everything' { $s = $TbUI.Pages['json'].State; Copy-TbText $(if ($s.Code.SelectionLength) { $s.Code.SelectedText } else { $s.Code.Text }) } $pbar $Glyph.Copy 1)
    [void](New-Button 'Query every item' 'Run the [*] path in the Query tab' { $s = $TbUI.Pages['json'].State; if ($s.WildPath) { $s.Path.Text = $s.WildPath; Select-ApiTab $s.Tabs 'Query' } } $pbar $Glyph.Search 2)
    $qbar = New-TbBar $queryPanel
    New-TbLabel $qbar 'JSONPath' -Dim | Out-Null
    $st.Path = New-TbBox -Mono -Cue '$.items[*].name   $..id   $.list[0:3]'
    $st.Path.Width = Px (360 * $TextZoom); $st.Path.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $qbar.Controls.Add($st.Path)
    $st.QueryOut = New-TbRtb -ReadOnly; $st.QueryOut.Dock = 'Fill'
    $queryPanel.Controls.Add($st.QueryOut)
    $queryPanel.Controls.SetChildIndex($qbar, $queryPanel.Controls.Count - 1)
    Select-ApiTab $tabs 'Output'
    $st.Tabs = $tabs

    New-TbLabel $bar 'Convert to' -Dim | Out-Null
    $st.Mode = 'json'
    $st.ModeButtons = @()
    foreach ($m in @(@('JSON', 'json', 'Pretty JSON'), @('Minified', 'minify', 'JSON on one line'), @('Sorted keys', 'sort', 'JSON with the keys of every object in alphabetical order'),
                     @('YAML', 'yaml', 'YAML'), @('CSV', 'csv', 'CSV: a list of objects becomes rows; nested values become a.b columns'),
                     @('Tab-separated', 'tsv', 'Tab-separated rows (paste straight into Excel or Google Sheets)'),
                     @('XML', 'xml', 'XML: keys become elements, "@name" keys attributes, lists repeated elements'))) {
        $b = New-Button $m[0] $m[2] {
            param($src, $e)
            $s = $TbUI.Pages['json'].State; $s.Mode = $src.Tag
            foreach ($x in $s.ModeButtons) { $x.Selected = ($x.Tag -eq $s.Mode); $x.Invalidate() }
            Update-JsonTool $s; Select-ApiTab $s.Tabs 'Output'
        } $bar '' 2
        $b.Tag = $m[1]
        $b.Selected = ($m[1] -eq 'json')
        $st.ModeButtons += $b
    }
    $st.Indent = New-TbCombo $bar @('2 spaces', '4 spaces', 'Tab') 100
    [void](New-Button 'Copy' 'Copy the output' { $s = $TbUI.Pages['json'].State; Copy-TbText $(switch ($s.Tabs.Current) { 'Query' { $s.QueryOut.Text } 'Path & loop code' { $s.Code.Text } default { $s.Output.Text } }) } $bar $Glyph.Copy 1)
    [void](New-Button 'Use as input' 'Replace the input with the output' { $s = $TbUI.Pages['json'].State; if ($s.Output.Text) { $s.Input.Text = $s.Output.Text } } $bar $Glyph.Undo 2)
    [void](New-Button 'Compare...' 'Compare the input with the clipboard (any of the formats), ignoring key order and formatting' {
        $s = $TbUI.Pages['json'].State
        $clip = ''; try { $clip = [System.Windows.Forms.Clipboard]::GetText() } catch { }
        if (-not $s.Root) { Set-TbStatus $s.Status 'The input is not valid.' 'error'; return }
        $left = [DevJson]::Write($s.Root, 2, $true)
        $right = try { [DevJson]::Write([DevData]::Parse($clip, 'auto'), 2, $true) } catch { '' }
        if (-not $right) { Set-TbStatus $s.Status 'Copy the second document first; it is compared with the input (keys sorted, same formatting).' 'warn' }
        Show-Compare ([pscustomobject]@{ Kind = 'text'; Text = $left; Id = '' }) ([pscustomobject]@{ Kind = 'text'; Text = $right; Id = '' })
    } $bar $Glyph.Compare 2)

    $st.Timer = New-TbDebounce 300 { Update-JsonTool $TbUI.Pages['json'].State }
    $st.Input.add_TextChanged({ $s = $TbUI.Pages['json'].State; $s.Timer.Stop(); $s.Timer.Start() })
    $st.Indent.add_SelectedIndexChanged({ Update-JsonTool $TbUI.Pages['json'].State })
    $st.From.add_SelectedIndexChanged({ Update-JsonTool $TbUI.Pages['json'].State })
    $st.QTimer = New-TbDebounce 300 { Update-JsonQuery $TbUI.Pages['json'].State }
    $st.Path.add_TextChanged({ $s = $TbUI.Pages['json'].State; $s.QTimer.Stop(); $s.QTimer.Start() })
    $st.SetInput = { param($t) $s = $TbUI.Pages['json'].State; $s.Input.Text = $t; Update-JsonTool $s }
    $st.Focus = { $TbUI.Pages['json'].State.Input.Focus() }
    $st.Code.Text = Get-JsonPathCheatSheet
    Set-TbStatus $st.Status 'Paste JSON, YAML, CSV or XML on the left and pick what to convert it to. Click a value in the Tree for its path and loop code.'
    $st
}

function Update-JsonTool($St) {
    $text = $St.Input.Text
    if (-not $text.Trim()) { $St.Output.Text = ''; $St.Tree.Nodes.Clear(); $St.Root = $null; $St.Json = ''; $St.Detected.Text = ''; Set-TbStatus $St.Status 'Paste JSON, YAML, CSV or XML on the left.'; return }
    $indent = switch ($St.Indent.SelectedIndex) { 1 { 4 } 2 { 1 } default { 2 } }
    $from = $DataFormats[[string]$St.From.SelectedItem]
    if ($from -eq 'auto') { $from = [DevData]::Detect($text) }
    $St.Detected.Text = if ($St.From.SelectedIndex -eq 0) { "read as $($from.ToUpper())" } else { '' }
    $St.InFormat = $from
    $St.Sep = if ($from -eq 'tsv') { "`t" } elseif ($from -eq 'csv') { [string][DevData]::CsvSeparator($text) } else { '' }
    try {
        $root = [DevData]::Parse($text, $from)
        $St.Root = $root
        $St.Json = [DevJson]::Write($root, -1, $false)
        if ($St.PathTag) { $St.PathTag = $null; $St.WildPath = $null; $St.Code.Text = Get-JsonPathCheatSheet }
        $out = switch ($St.Mode) {
            'minify' { [DevJson]::Write($root, -1, $false) }
            'sort'   { [DevJson]::Write($root, $indent, $true) }
            'yaml'   { [DevData]::Write($root, 'yaml', $indent, $false) }
            'csv'    { [DevData]::Write($root, 'csv', $indent, $false) }
            'tsv'    { [DevData]::Write($root, 'tsv', $indent, $false) }
            'xml'    { [DevData]::Write($root, 'xml', $indent, $false) }
            default  { [DevJson]::Write($root, $indent, $false) }
        }
        if ($St.Indent.SelectedIndex -eq 2 -and $St.Mode -in 'json', 'sort') { $out = [regex]::Replace($out, '(?m)^( +)', { param($m) "`t" * $m.Groups[1].Value.Length }) }
        $St.Output.Text = $out
        $St.Tree.BeginUpdate(); $St.Tree.Nodes.Clear()
        $rootNode = New-Object System.Windows.Forms.TreeNode((Get-JsonTreeText '$' $root)); $rootNode.Tag = [pscustomobject]@{ V = $root; Steps = @() }
        [void]$St.Tree.Nodes.Add($rootNode)
        Add-JsonTreeChildren $rootNode.Nodes $root @()
        $rootNode.Expand()
        $St.Tree.EndUpdate()
        Set-TbStatus $St.Status "Valid $($from.ToUpper())  $Dot  $([DevJson]::TypeName($root)) $([DevJson]::Short($root, 30))  $Dot  $('{0:N0}' -f $text.Length) characters" 'ok'
        Update-JsonQuery $St
    } catch {
        $St.Root = $null; $St.Json = ''
        $ex = $_.Exception.InnerException
        if (-not $ex) { $ex = $_.Exception }
        Set-TbStatus $St.Status "Not valid $($from.ToUpper()): $($ex.Message)" 'error'
        if ($ex -is [DevJsonException] -and $St.Input.Focused -eq $false) { $St.Input.Select([Math]::Min($ex.Position, $St.Input.TextLength), 1); $St.Input.ScrollToCaret() }
    }
}

function Get-JsonPathCheatSheet {
@'
Click a value in the Tree tab: this page then shows its path and ready-to-use code
to read it, or to loop over the list it is in.

JSONPath in short (try them in the Query tab)
  $                     the whole document
  $.store.name          a key inside a key
  $['first name']       a key with spaces or odd characters
  $.items[0]            the first item of a list ([-1] = the last)
  $.items[*]            every item of a list
  $.items[*].name       the name of every item
  $.items[0:3]          items 0, 1 and 2
  $..id                 every "id", at any depth
  $.*                   every value of an object
'@
}

function Test-PlainKey([string]$K) { $K -match '^[A-Za-z_$][A-Za-z0-9_$]*$' }

# Code to reach the steps, for each language. $Var = the variable the steps start from.
function Get-StepCode([string]$Lang, $Steps, [string]$Var) {
    $s = $Var
    foreach ($p in $Steps) {
        $isIdx = $p.I -ge 0
        $s += switch ($Lang) {
            'js'   { if ($isIdx) { "[$($p.I)]" } elseif (Test-PlainKey $p.K) { ".$($p.K)" } else { "[$(ConvertTo-JsonString $p.K)]" } }
            'py'   { if ($isIdx) { "[$($p.I)]" } else { "[$(ConvertTo-JsonString $p.K)]" } }
            'cs'   { if ($isIdx) { "[$($p.I)]" } else { ".GetProperty($(ConvertTo-JsonString $p.K))" } }
            'ps'   { if ($isIdx) { "[$($p.I)]" } elseif ($p.K -match '^[A-Za-z_][A-Za-z0-9_]*$') { ".$($p.K)" } else { ".'$($p.K -replace "'", "''")'" } }
            'jq'   { if ($isIdx) { "[$($p.I)]" } elseif (Test-PlainKey $p.K) { ".$($p.K)" } else { ".[$(ConvertTo-JsonString $p.K)]" } }
            'csdyn' { if ($isIdx) { "[$($p.I)]" } else { "[$(ConvertTo-JsonString $p.K)]" } }
            'psxml' { if ($isIdx) { "[$($p.I)]" } elseif ($p.K -eq '#text') { ".'#text'" } else { $k2 = $p.K.TrimStart('@'); if ($k2 -match '^[A-Za-z_][A-Za-z0-9_]*$') { ".$k2" } else { ".'$($k2 -replace "'", "''")'" } } }
            'path' { if ($isIdx) { "[$($p.I)]" } elseif (Test-PlainKey $p.K) { ".$($p.K)" } else { "['$($p.K -replace "'", "\'")']" } }
        }
    }
    if ($Lang -eq 'jq' -and $s -eq '') { $s = '.' }
    $s
}

function ConvertTo-JsonString([string]$S) { [DevJson]::Quote($S) }

# "servers" -> "server", "entries" -> "entry"; something readable for a loop variable.
function Get-LoopName([string]$Key) {
    $k = if ($Key -and (Test-PlainKey $Key)) { $Key } else { 'item' }
    if ($k -match 'ies$') { return $k -replace 'ies$', 'y' }
    if ($k -match '(ss|us)$') { return "$($k)Item" }
    if ($k -match 's$' -and $k.Length -gt 2) { return $k.Substring(0, $k.Length - 1) }
    if ($k -match '^(data|items?|list|results?|rows?|records?)$') { return 'item' }
    if ($k -in 'class', 'for', 'in', 'of', 'if', 'default', 'function', 'new', 'var', 'let', 'const', 'string', 'int', 'object', 'type', 'from', 'import', 'return', 'switch', 'case') { return "$($k)Item" }
    $k
}

function Get-ValueAt($Root, $Steps) {
    $v = $Root
    foreach ($p in $Steps) {
        if ($p.I -ge 0) { $v = ([System.Collections.Generic.List[object]]$v)[$p.I] } else { $v = $v.Get($p.K) }
    }
    $v
}

function Update-JsonPathHelp($St, $Tag) {
    $St.PathTag = $Tag
    $steps = @($Tag.Steps)
    $root = $St.Root
    $v = $Tag.V
    $type = [DevJson]::TypeName($v)
    # the code reads the input as it is (XML, YAML, CSV ...), or the JSON it converts to
    $fmt = if ($St.CodeFor.SelectedIndex -eq 1) { 'json' } else { [string]$St.InFormat }
    if (-not $fmt) { $fmt = 'json' }
    $sb = New-Object System.Text.StringBuilder
    $line = { param($t = '') [void]$sb.AppendLine($t) }

    # the list to loop over: the selected list itself, else the nearest list above it
    $loopAt = -1
    if ($type -eq 'array') { $loopAt = $steps.Count }
    else { for ($k = $steps.Count - 1; $k -ge 0; $k--) { if ($steps[$k].I -ge 0) { $loopAt = $k; break } } }
    $listSteps = @(if ($loopAt -gt 0) { $steps[0..($loopAt - 1)] })
    $inner = @(if ($type -ne 'array' -and $loopAt -ge 0 -and $loopAt + 1 -lt $steps.Count) { $steps[($loopAt + 1)..($steps.Count - 1)] })
    $lastKey = @($listSteps | Where-Object { $_.K } | Select-Object -Last 1).K
    $it = if ($fmt -in 'csv', 'tsv') { 'row' } else { Get-LoopName $lastKey }
    $list = if ($loopAt -ge 0) { Get-ValueAt $root $listSteps } else { $null }
    $first = if ($list -and $list.Count) { $list[0] } else { $null }
    $fields = New-Object System.Collections.Generic.List[object]
    if ($inner.Count) { $fields.Add($inner) }
    elseif ($first -is [DevJsonObject]) { foreach ($kv in @($first | Select-Object -First 3)) { $fields.Add(@(New-PathStep $kv.Key)) } }
    $isObj = $type -eq 'object'

    $St.WildPath = $null
    if ($loopAt -ge 0) { $St.WildPath = '$' + (Get-StepCode 'path' $listSteps '') + '[*]' + (Get-StepCode 'path' $inner '') }
    $sel = switch ($fmt) {
        'xml'   { Get-XPath $steps }
        { $_ -in 'csv', 'tsv' } { if ($steps.Count -and $steps[0].I -ge 0) { "row $($steps[0].I + 1)$(if ($steps.Count -gt 1) { ', column ' + (Get-CsvColumn @($steps[1..($steps.Count - 1)])) })" } else { 'all rows' } }
        default { '$' + (Get-StepCode 'path' $steps '') }
    }
    & $line "Input      $(([string]$St.InFormat).ToUpper())$(if ($St.CodeFor.SelectedIndex -eq 1) { '   (the code reads it converted to JSON)' })"
    & $line "Selected   $sel"
    & $line "Type       $type   $([DevJson]::Short($v, 80))"
    if ($loopAt -ge 0) {
        $every = switch ($fmt) { 'xml' { (Get-XPath $listSteps -NoLastIndex) + $(if ($inner.Count) { '/' + (Get-XPath $inner -Relative) }) } { $_ -in 'csv', 'tsv' } { "every row$(if ($inner.Count) { ', column ' + (Get-CsvColumn $inner) })" } default { $St.WildPath } }
        & $line "Every item $every"
    }
    & $line

    $pick = [string]$St.Lang.SelectedItem
    $langs = [ordered]@{ 'JavaScript' = 'js'; 'Python' = 'py'; 'C#' = 'cs'; 'PowerShell' = 'ps'; 'Command line' = 'cli' }
    $ctx = @{ Steps = $steps; ListSteps = $listSteps; Inner = $inner; Fields = $fields; It = $it; LoopAt = $loopAt; IsObj = $isObj; Line = $line; Fmt = $fmt; Sep = $St.Sep; Text = $St.Input.Text }
    foreach ($name in $langs.Keys) {
        if ($pick -ne 'All languages' -and $pick -ne $name) { continue }
        & $line "---- $name $('-' * [math]::Max(4, 50 - $name.Length))"
        switch ($fmt) {
            'xml'   { Write-XmlCode $langs[$name] $ctx }
            'csv'   { Write-CsvCode $langs[$name] $ctx }
            'tsv'   { Write-CsvCode $langs[$name] $ctx }
            default { Write-TreeCode $langs[$name] $ctx }
        }
        & $line
    }
    $St.Code.Text = $sb.ToString().TrimEnd()
}

# ---- JSON and YAML: the same shape in every language, only loading differs
function Write-TreeCode([string]$L, $X) {
    $line = $X.Line; $steps = $X.Steps; $listSteps = $X.ListSteps; $fields = $X.Fields; $it = $X.It
    $yaml = $X.Fmt -eq 'yaml'
    switch ($L) {
        'js' {
            & $line $(if ($yaml) { "// npm install js-yaml`nconst yaml = require('js-yaml');`nconst data = yaml.load(fs.readFileSync('file.yaml', 'utf8'));" } else { "const data = JSON.parse(text);   // or: await (await fetch(url)).json()" })
            & $line "const value = $(Get-StepCode 'js' $steps 'data');"
            if ($X.LoopAt -ge 0) {
                & $line "for (const $it of $(Get-StepCode 'js' $listSteps 'data')) {"
                & $line "  console.log($(if ($fields.Count) { ($fields | ForEach-Object { Get-StepCode 'js' $_ $it }) -join ', ' } else { $it }));"
                & $line '}'
                if ($fields.Count) { & $line "const values = $(Get-StepCode 'js' $listSteps 'data').map($it => $(Get-StepCode 'js' $fields[0] $it));" }
            }
            if ($X.IsObj) { & $line "for (const [key, val] of Object.entries($(Get-StepCode 'js' $steps 'data'))) {`n  console.log(key, val);`n}" }
        }
        'py' {
            & $line $(if ($yaml) { "import yaml   # pip install pyyaml`nwith open('file.yaml', encoding='utf-8') as f:`n    data = yaml.safe_load(f)" } else { "import json`nwith open('file.json', encoding='utf-8') as f:`n    data = json.load(f)" })
            & $line "value = $(Get-StepCode 'py' $steps 'data')"
            if ($X.LoopAt -ge 0) {
                & $line "for $it in $(Get-StepCode 'py' $listSteps 'data'):"
                & $line "    print($(if ($fields.Count) { ($fields | ForEach-Object { Get-StepCode 'py' $_ $it }) -join ', ' } else { $it }))"
                if ($fields.Count) { & $line "values = [$(Get-StepCode 'py' $fields[0] $it) for $it in $(Get-StepCode 'py' $listSteps 'data')]" }
            }
            if ($X.IsObj) { & $line "for key, val in $(Get-StepCode 'py' $steps 'data').items():`n    print(key, val)" }
        }
        'cs' {
            if ($yaml) {
                & $line '// dotnet add package YamlDotNet'
                & $line 'var data = new YamlDotNet.Serialization.Deserializer().Deserialize<dynamic>(File.ReadAllText("file.yaml"));'
                & $line "var value = $(Get-StepCode 'csdyn' $steps 'data');"
                if ($X.LoopAt -ge 0) {
                    & $line "foreach (var $it in $(Get-StepCode 'csdyn' $listSteps 'data'))"
                    & $line "    Console.WriteLine($(if ($fields.Count) { ($fields | ForEach-Object { Get-StepCode 'csdyn' $_ $it }) -join ' + " " + ' } else { $it }));"
                }
                if ($X.IsObj) { & $line "foreach (var kv in $(Get-StepCode 'csdyn' $steps 'data'))`n    Console.WriteLine(kv.Key + `": `" + kv.Value);" }
            } else {
                & $line 'using System.Text.Json;'
                & $line 'using var doc = JsonDocument.Parse(File.ReadAllText("file.json"));'
                & $line 'var root = doc.RootElement;'
                & $line "var value = $(Get-StepCode 'cs' $steps 'root');"
                if ($X.LoopAt -ge 0) {
                    & $line "foreach (var $it in $(Get-StepCode 'cs' $listSteps 'root').EnumerateArray())"
                    & $line "    Console.WriteLine($(if ($fields.Count) { ($fields | ForEach-Object { (Get-StepCode 'cs' $_ $it) + '.ToString()' }) -join ' + " " + ' } else { $it }));"
                }
                if ($X.IsObj) { & $line "foreach (var prop in $(Get-StepCode 'cs' $steps 'root').EnumerateObject())`n    Console.WriteLine(prop.Name + `": `" + prop.Value);" }
            }
        }
        'ps' {
            & $line $(if ($yaml) { "# Install-Module powershell-yaml`n`$data = Get-Content file.yaml -Raw | ConvertFrom-Yaml" } else { "`$data = Get-Content file.json -Raw | ConvertFrom-Json   # or: Invoke-RestMethod <url>" })
            & $line "`$value = $(Get-StepCode 'ps' $steps '$data')"
            if ($X.LoopAt -ge 0) {
                & $line "foreach (`$$it in $(Get-StepCode 'ps' $listSteps '$data')) {"
                & $line "    $(if ($fields.Count) { ($fields | ForEach-Object { '"$(' + (Get-StepCode 'ps' $_ "`$$it") + ')"' }) -join ' + " " + ' } else { "`$$it" })"
                & $line '}'
                if ($fields.Count) { & $line "$(Get-StepCode 'ps' $listSteps '$data') | ForEach-Object { $(Get-StepCode 'ps' $fields[0] '$_') }" }
            }
            if ($X.IsObj) { & $line $(if ($yaml) { "$(Get-StepCode 'ps' $steps '$data').GetEnumerator() | ForEach-Object { `"`$(`$_.Key) = `$(`$_.Value)`" }" } else { "$(Get-StepCode 'ps' $steps '$data').PSObject.Properties | ForEach-Object { `"`$(`$_.Name) = `$(`$_.Value)`" }" }) }
        }
        'cli' {
            $tool = if ($yaml) { 'yq' } else { 'jq' }; $file = if ($yaml) { 'file.yaml' } else { 'file.json' }
            & $line "$tool '$(Get-StepCode 'jq' $steps '')' $file"
            if ($X.LoopAt -ge 0) {
                $pickF = if ($fields.Count) { ' | ' + (($fields | ForEach-Object { Get-StepCode 'jq' $_ '' }) -join ', ') } else { '' }
                & $line "$tool '$(Get-StepCode 'jq' $listSteps '')[]$pickF' $file"
            }
            if ($X.IsObj) { & $line "$tool '$(Get-StepCode 'jq' $steps '') | to_entries[] | `"\(.key) = \(.value)`"' $file" }
        }
    }
}

# ---- XML: XPath, DOM / ElementTree / LINQ to XML / [xml]
# the tree from XML: { root: { "@attr": ..., child: ..., "#text": ... } }, repeated elements are lists
function Get-XPath($Steps, [switch]$Relative, [switch]$NoLastIndex) {
    $parts = New-Object System.Collections.Generic.List[string]
    $arr = @($Steps)
    for ($k = 0; $k -lt $arr.Count; $k++) {
        $p = $arr[$k]
        if ($p.I -ge 0) { if ($parts.Count -and -not ($NoLastIndex -and $k -eq $arr.Count - 1)) { $parts[$parts.Count - 1] += "[$($p.I + 1)]" }; continue }
        if ($p.K -eq '#text') { $parts.Add('text()') } else { $parts.Add($p.K) }
    }
    $s = $parts -join '/'
    if ($Relative) { $s } else { "/$s" }
}

# the steps below one element, as an XPath relative to it
function Get-XmlRel($Steps) { Get-XPath $Steps -Relative }

function Get-CssPath($Steps) {
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($p in @($Steps)) {
        if ($p.I -ge 0) { if ($parts.Count) { $parts[$parts.Count - 1] += ":nth-of-type($($p.I + 1))" }; continue }
        if ($p.K -like '@*' -or $p.K -eq '#text') { continue }
        $parts.Add(($p.K -replace '([:.])', '\$1'))
    }
    $parts -join ' > '
}

function Write-XmlCode([string]$L, $X) {
    $line = $X.Line; $steps = @($X.Steps); $listSteps = @($X.ListSteps); $fields = $X.Fields; $it = $X.It
    $xp = Get-XPath $steps
    $last = if ($steps.Count) { $steps[$steps.Count - 1] } else { $null }
    $isAttr = $last -and $last.K -like '@*'
    $listXp = Get-XPath $listSteps -NoLastIndex
    switch ($L) {
        'js' {
            & $line 'const doc = new DOMParser().parseFromString(text, "application/xml");'
            & $line "const value = doc.evaluate(`"string($xp)`", doc, null, XPathResult.STRING_TYPE, null).stringValue;"
            if ($X.LoopAt -ge 0) {
                & $line "for (const $it of doc.querySelectorAll(`"$(Get-CssPath $listSteps)`")) {"
                $parts = foreach ($f in $fields) {
                    $fa = @($f); $fl = $fa[$fa.Count - 1]
                    if ($fl.K -like '@*') { $css = Get-CssPath @($fa[0..($fa.Count - 1)]); if ($css) { "$it.querySelector(`":scope > $css`")?.getAttribute(`"$($fl.K.Substring(1))`")" } else { "$it.getAttribute(`"$($fl.K.Substring(1))`")" } }
                    elseif ($fl.K -eq '#text') { "$it.textContent" }
                    else { "$it.querySelector(`":scope > $(Get-CssPath $fa)`")?.textContent" }
                }
                & $line "  console.log($(if ($parts) { @($parts) -join ', ' } else { "$it.textContent" }));"
                & $line '}'
            }
            if ($X.IsObj) { & $line "const el = doc.evaluate(`"$xp`", doc, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;`nfor (const a of el.attributes) console.log(a.name, a.value);`nfor (const child of el.children) console.log(child.tagName, child.textContent);" }
        }
        'py' {
            & $line 'import xml.etree.ElementTree as ET'
            & $line "root = ET.parse('file.xml').getroot()   # or: ET.fromstring(text)"
            # ElementTree paths start below the root element and can't end in @attr / text()
            $below = @($steps | Select-Object -Skip 1)
            if ($isAttr -or ($last -and $last.K -eq '#text')) {
                $owner = @($below | Select-Object -First ([math]::Max(0, $below.Count - 1)))
                $el = if ($owner.Count) { "root.find(`"$(Get-XmlRel $owner)`")" } else { 'root' }
                $tail = if ($isAttr) { '.get("' + $last.K.Substring(1) + '")' } else { '.text' }
                & $line ('value = ' + $el + $tail)
            } elseif ($below.Count) { & $line "value = root.findtext(`"$(Get-XmlRel $below)`")" }
            else { & $line 'value = root.text' }
            if ($X.LoopAt -ge 0) {
                $lb = @($listSteps | Select-Object -Skip 1)
                & $line "for $it in root.findall(`"$(if ($lb.Count) { Get-XPath $lb -Relative -NoLastIndex } else { '.' })`"):"
                $parts = foreach ($f in $fields) {
                    $fa = @($f); $fl = $fa[$fa.Count - 1]
                    if ($fl.K -like '@*') { $o = @($fa | Select-Object -First ($fa.Count - 1)); if ($o.Count) { "$it.find(`"$(Get-XmlRel $o)`").get(`"$($fl.K.Substring(1))`")" } else { "$it.get(`"$($fl.K.Substring(1))`")" } }
                    elseif ($fl.K -eq '#text') { "$it.text" }
                    else { "$it.findtext(`"$(Get-XmlRel $fa)`")" }
                }
                & $line "    print($(if ($parts) { @($parts) -join ', ' } else { "$it.text" }))"
            }
            if ($X.IsObj) {
                $find = if ($steps.Count -gt 1) { '.find("' + (Get-XmlRel @($steps | Select-Object -Skip 1)) + '")' } else { '' }
                & $line ('el = root' + $find + "`nprint(el.attrib)`nfor child in el:`n    print(child.tag, child.text)")
            }
        }
        'cs' {
            & $line 'using System.Xml.Linq; using System.Xml.XPath;'
            & $line 'var doc = XDocument.Load("file.xml");   // or: XDocument.Parse(text)'
            $get = if ($isAttr) { '(string)doc.XPathEvaluate("string(' + $xp + ')")' } else { '(string)doc.XPathSelectElement("' + $xp + '")' }
            & $line ('var value = ' + $get + ';')
            if ($X.LoopAt -ge 0) {
                & $line "foreach (var $it in doc.XPathSelectElements(`"$listXp`"))"
                $parts = foreach ($f in $fields) {
                    $fa = @($f); $fl = $fa[$fa.Count - 1]
                    $chain = $it
                    foreach ($p in $fa) {
                        if ($p.I -ge 0) { $chain = $chain -replace '\.Element\(("[^"]*")\)$', ".Elements(`$1).ElementAt($($p.I))" }
                        elseif ($p.K -like '@*') { $chain += ".Attribute(`"$($p.K.Substring(1))`")" }
                        elseif ($p.K -ne '#text') { $chain += ".Element(`"$($p.K)`")" }
                    }
                    "(string)$chain"
                }
                & $line "    Console.WriteLine($(if ($parts) { @($parts) -join ' + " " + ' } else { "(string)$it" }));"
            }
            if ($X.IsObj) { & $line "var el = doc.XPathSelectElement(`"$xp`");`nforeach (var a in el.Attributes()) Console.WriteLine(a.Name + `" = `" + a.Value);`nforeach (var child in el.Elements()) Console.WriteLine(child.Name + `": `" + child.Value);" }
        }
        'ps' {
            & $line '[xml]$xml = Get-Content file.xml -Raw'
            & $line "`$value = $(Get-StepCode 'psxml' $steps '$xml')"
            & $line "`$value = `$xml.SelectSingleNode('$xp')$(if ($isAttr) { '.Value' } else { '.InnerText' })   # the same with XPath"
            if ($X.LoopAt -ge 0) {
                & $line "foreach (`$$it in $(Get-StepCode 'psxml' $listSteps '$xml')) {"
                & $line "    $(if ($fields.Count) { ($fields | ForEach-Object { '"$(' + (Get-StepCode 'psxml' $_ "`$$it") + ')"' }) -join ' + " " + ' } else { "`$$it.InnerText" })"
                & $line '}'
                & $line "`$xml.SelectNodes('$listXp') | ForEach-Object { `$_.OuterXml }"
            }
            if ($X.IsObj) { & $line "`$el = `$xml.SelectSingleNode('$xp')`n`$el.Attributes | ForEach-Object { `"`$(`$_.Name) = `$(`$_.Value)`" }`n`$el.ChildNodes | ForEach-Object { `"`$(`$_.Name): `$(`$_.InnerText)`" }" }
        }
        'cli' {
            & $line "xmllint --xpath 'string($xp)' file.xml"
            if ($X.LoopAt -ge 0) {
                $rel = if ($fields.Count) { '/' + (Get-XmlRel @($fields[0])) } else { '' }
                & $line "xmllint --xpath '$listXp$rel' file.xml"
                & $line "# PowerShell one-liner: Select-Xml -Path file.xml -XPath '$listXp$rel' | ForEach-Object { `$_.Node.InnerText }"
            }
        }
    }
}

# ---- CSV / tab-separated: rows with named columns ("a.b" columns are one column in the file)
function Get-CsvColumn($Steps) { (@($Steps | Where-Object { $_.K } | ForEach-Object { $_.K })) -join '.' }

function Write-CsvCode([string]$L, $X) {
    $line = $X.Line; $steps = @($X.Steps)
    $tsv = $X.Fmt -eq 'tsv'
    $sepChar = if ($tsv) { "`t" } else { [string]$X.Sep }
    if (-not $sepChar) { $sepChar = ',' }
    $sepCode = if ($tsv) { '\t' } else { $sepChar }
    $file = if ($tsv) { 'file.tsv' } else { 'file.csv' }
    $rowIdx = if ($steps.Count -and $steps[0].I -ge 0) { $steps[0].I } else { -1 }
    $col = if ($steps.Count -gt 1) { Get-CsvColumn @($steps[1..($steps.Count - 1)]) } else { '' }
    $head = @()
    try { $rows = [DevData]::CsvRows($X.Text, [char]$sepChar); if ($rows.Count) { $head = @($rows[0] | ForEach-Object { $_.Trim() }) } } catch { }
    $cols = @(if ($col) { $col } else { $head | Select-Object -First 3 })
    $q = { param($c) [DevJson]::Quote($c) }
    switch ($L) {
        'js' {
            & $line '// npm install papaparse'
            $delim = if ($sepChar -ne ',') { ', delimiter: "' + $sepCode + '"' } else { '' }
            & $line ('const rows = Papa.parse(text, { header: true, skipEmptyLines: true' + $delim + ' }).data;')
            if ($rowIdx -ge 0 -and $col) { & $line "const value = rows[$rowIdx][$(& $q $col)];" } elseif ($rowIdx -ge 0) { & $line "const row = rows[$rowIdx];" }
            & $line 'for (const row of rows) {'
            & $line "  console.log($((@($cols | ForEach-Object { "row[$(& $q $_)]" })) -join ', '));"
            & $line '}'
            if ($cols) { & $line "const values = rows.map(row => row[$(& $q $cols[0])]);" }
        }
        'py' {
            & $line 'import csv'
            & $line "with open('$file', newline='', encoding='utf-8') as f:"
            & $line "    rows = list(csv.DictReader(f$(if ($sepChar -ne ',') { ", delimiter='$sepCode'" })))"
            if ($rowIdx -ge 0 -and $col) { & $line "value = rows[$rowIdx][$(& $q $col)]" } elseif ($rowIdx -ge 0) { & $line "row = rows[$rowIdx]" }
            & $line 'for row in rows:'
            & $line "    print($((@($cols | ForEach-Object { "row[$(& $q $_)]" })) -join ', '))"
            if ($cols) { & $line "values = [row[$(& $q $cols[0])] for row in rows]" }
        }
        'cs' {
            & $line "// no package needed (for quoted fields with $(if ($tsv) { 'tabs' } else { 'separators' }) inside, use the CsvHelper package)"
            & $line "var lines = File.ReadAllLines(`"$file`");"
            & $line "var head = lines[0].Split('$sepCode');"
            & $line "var rows = lines.Skip(1).Where(l => l.Length > 0).Select(l => { var c = l.Split('$sepCode'); return head.Select((h, i) => new { h, v = i < c.Length ? c[i] : `"`" }).ToDictionary(x => x.h, x => x.v); }).ToList();"
            if ($rowIdx -ge 0 -and $col) { & $line "var value = rows[$rowIdx][$(& $q $col)];" }
            & $line 'foreach (var row in rows)'
            & $line "    Console.WriteLine($((@($cols | ForEach-Object { "row[$(& $q $_)]" })) -join ' + " " + '));"
        }
        'ps' {
            $imp = "Import-Csv $file$(if ($tsv) { ' -Delimiter "`t"' } elseif ($sepChar -ne ',') { " -Delimiter '$sepChar'" })"
            & $line "`$rows = $imp     # or: `$text | ConvertFrom-Csv$(if ($tsv) { ' -Delimiter "`t"' } elseif ($sepChar -ne ',') { " -Delimiter '$sepChar'" })"
            $pc = { param($c) if ($c -match '^[A-Za-z_][A-Za-z0-9_]*$') { $c } else { "'$($c -replace "'", "''")'" } }
            if ($rowIdx -ge 0 -and $col) { & $line "`$value = `$rows[$rowIdx].$(& $pc $col)" } elseif ($rowIdx -ge 0) { & $line "`$row = `$rows[$rowIdx]" }
            & $line 'foreach ($row in $rows) {'
            & $line "    $((@($cols | ForEach-Object { '"$($row.' + (& $pc $_) + ')"' })) -join ' + " " + ')"
            & $line '}'
            if ($cols) { & $line "`$rows | Select-Object $((@($cols | ForEach-Object { & $pc $_ })) -join ', ') | Format-Table" }
            if ($col) { & $line "`$rows | Where-Object { `$_.$(& $pc $col) -eq 'some value' }   # filter rows" }
        }
        'cli' {
            $io = if ($tsv) { '--itsv' } else { '--icsv' }
            & $line "# Miller (mlr):"
            & $line "mlr $io --opprint cut -f $(@($cols) -join ',') $file"
            if ($rowIdx -ge 0) { & $line "mlr $io --ojson head -n $($rowIdx + 1) then tail -n 1 $file" }
            & $line "mlr $io --ojson cat $file   # the whole table as JSON"
        }
    }
}

function Update-JsonQuery($St) {
    $p = $St.Path.Text.Trim()
    if (-not $p) { $St.QueryOut.Text = (Get-JsonPathCheatSheet); return }
    if (-not $St.Json) { $St.QueryOut.Text = 'Fix the input first.'; return }
    try {
        $hits = [DevJson]::Query($St.Json, $p)
        $sb = New-Object System.Text.StringBuilder
        [void]$sb.AppendLine("$($hits.Count) match(es)`n")
        foreach ($h in $hits) { [void]$sb.AppendLine("$($h.Key)"); [void]$sb.AppendLine("  " + ([DevJson]::Write($h.Value, 2, $false) -replace "`n", "`n  ")); [void]$sb.AppendLine() }
        $St.QueryOut.Text = $sb.ToString()
    } catch {
        $ex = $_.Exception.InnerException; if (-not $ex) { $ex = $_.Exception }
        $St.QueryOut.Text = "Query error: $($ex.Message)"
    }
}

# ======================================================================================
# JWT: decode header and payload, show expiry, verify HS256/384/512 signatures with a secret.
# ======================================================================================
function ConvertFrom-Base64Url([string]$Text) {
    $s = $Text.Replace('-', '+').Replace('_', '/')
    switch ($s.Length % 4) { 2 { $s += '==' } 3 { $s += '=' } }
    [Convert]::FromBase64String($s)
}

function ConvertTo-Base64Url([byte[]]$Bytes) { [Convert]::ToBase64String($Bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_') }

function Format-Relative([datetime]$When) {
    $span = $When - (Get-Date)
    $abs = [Math]::Abs($span.TotalSeconds)
    $txt = if ($abs -lt 90) { "$([int]$abs) s" } elseif ($abs -lt 5400) { "$([int]($abs / 60)) min" } elseif ($abs -lt 172800) { "$([Math]::Round($abs / 3600, 1)) h" } else { "$([Math]::Round($abs / 86400, 1)) days" }
    if ($span.TotalSeconds -ge 0) { "in $txt" } else { "$txt ago" }
}

Register-ToolboxPage 'jwt' 'JWT decoder' $Glyph.Lock 'jwt token bearer decode claims expiry signature' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Input = New-TbBox -Mono -Multi -Cue 'Paste a JWT (eyJ...), with or without "Bearer "'
    $st.Input.Dock = 'Fill'; $st.Input.WordWrap = $true; $st.Input.ScrollBars = 'Vertical'
    $split.Panel1.Controls.Add($st.Input)
    $vbar = New-TbBar $split.Panel1 'Bottom'
    New-TbLabel $vbar 'Secret (HS256/384/512)' -Dim | Out-Null
    $st.Secret = New-TbBox -Cue 'optional - to check the signature'
    $st.Secret.Width = Px (300 * $TextZoom); $st.Secret.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $vbar.Controls.Add($st.Secret)
    $st.SecretB64 = New-CheckBox $vbar 'Secret is Base64' $false 'Tick when the secret is Base64-encoded bytes'
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'; $st.Output.WordWrap = $true
    $split.Panel2.Controls.Add($st.Output)
    $st.Timer = New-TbDebounce 250 { Update-JwtTool $TbUI.Pages['jwt'].State }
    foreach ($box in $st.Input, $st.Secret) { $box.add_TextChanged({ $s = $TbUI.Pages['jwt'].State; $s.Timer.Stop(); $s.Timer.Start() }) }
    $st.SecretB64.add_CheckedChanged({ Update-JwtTool $TbUI.Pages['jwt'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['jwt'].State; $s.Input.Text = $t; Update-JwtTool $s }
    $st.Focus = { $TbUI.Pages['jwt'].State.Input.Focus() }
    $split.SplitterDistance = Px 120
    Set-TbStatus $st.Status 'Decoding happens here on your PC; the token is not sent anywhere.'
    $st
}

function Add-RtbLine($Rtb, [string]$Text, $Color = $null, [switch]$Bold) {
    $Rtb.SelectionStart = $Rtb.TextLength
    $Rtb.SelectionColor = if ($Color) { $Color } else { $C.Fore }
    $Rtb.SelectionFont = if ($Bold) { New-Object System.Drawing.Font($Rtb.Font, [System.Drawing.FontStyle]::Bold) } else { $Rtb.Font }
    $Rtb.AppendText($Text + "`n")
}

function Update-JwtTool($St) {
    $o = $St.Output
    $o.Clear()
    $tok = ($St.Input.Text -replace '\s', '') -replace '^(?i)bearer', ''
    if (-not $tok) { Set-TbStatus $St.Status 'Paste a token above.'; return }
    $parts = $tok.Split('.')
    if ($parts.Count -lt 2) { Set-TbStatus $St.Status 'A JWT has three parts separated by dots: header.payload.signature' 'error'; return }
    try {
        $hdrText = [Text.Encoding]::UTF8.GetString((ConvertFrom-Base64Url $parts[0]))
        $payText = [Text.Encoding]::UTF8.GetString((ConvertFrom-Base64Url $parts[1]))
    } catch { Set-TbStatus $St.Status "Not a valid JWT: $($_.Exception.Message)" 'error'; return }
    $hdr = $null; $pay = $null
    try { $hdr = [DevJson]::Parse($hdrText) } catch { }
    try { $pay = [DevJson]::Parse($payText) } catch { }
    Add-RtbLine $o 'HEADER' $C.Accent -Bold
    Add-RtbLine $o $(if ($hdr) { [DevJson]::Write($hdr, 2, $false) } else { $hdrText })
    Add-RtbLine $o ''
    Add-RtbLine $o 'PAYLOAD' $C.Accent -Bold
    Add-RtbLine $o $(if ($pay) { [DevJson]::Write($pay, 2, $false) } else { $payText })
    Add-RtbLine $o ''
    $summary = @()
    $kind = ''
    if ($pay -is [DevJsonObject]) {
        Add-RtbLine $o 'CLAIMS' $C.Accent -Bold
        $names = @{ iss = 'Issuer'; sub = 'Subject'; aud = 'Audience'; exp = 'Expires'; nbf = 'Not before'; iat = 'Issued at'; jti = 'Token id'; scope = 'Scope'; name = 'Name'; email = 'Email' }
        foreach ($k in 'iss', 'sub', 'aud', 'name', 'email', 'scope', 'iat', 'nbf', 'exp', 'jti') {
            if (-not $pay.Has($k)) { continue }
            $v = $pay.Get($k)
            $txt = if ($v -is [string]) { $v } else { [DevJson]::Write($v, -1, $false) }
            $color = $null
            if ($k -in 'exp', 'nbf', 'iat' -and $v -is [DevJsonNumber]) {
                $when = [DateTimeOffset]::FromUnixTimeSeconds([long][double]$v.Raw).LocalDateTime
                $txt = "$($v.Raw)  =  $($when.ToString('ddd yyyy-MM-dd HH:mm:ss'))  ($(Format-Relative $when))"
                if ($k -eq 'exp') { if ($when -lt (Get-Date)) { $color = $C.Red; $summary += "EXPIRED $(Format-Relative $when)"; $kind = 'error' } else { $color = $C.Green; $summary += "valid, expires $(Format-Relative $when)"; if (-not $kind) { $kind = 'ok' } } }
                if ($k -eq 'nbf' -and $when -gt (Get-Date)) { $color = $C.Yellow; $summary += "not valid yet ($(Format-Relative $when))"; $kind = 'warn' }
            }
            Add-RtbLine $o ("{0,-11} {1}" -f $names[$k], $txt) $color
        }
        Add-RtbLine $o ''
    }
    # signature
    $alg = if ($hdr -is [DevJsonObject] -and $hdr.Has('alg')) { [string]$hdr.Get('alg') } else { '' }
    Add-RtbLine $o 'SIGNATURE' $C.Accent -Bold
    if ($parts.Count -lt 3 -or -not $parts[2]) { Add-RtbLine $o 'none (unsigned token)' $C.Yellow; $summary += 'unsigned' }
    elseif ($alg -match '^HS(256|384|512)$') {
        if (-not $St.Secret.Text) { Add-RtbLine $o "$alg - enter the secret below to check it" $C.Dim }
        else {
            try {
                $key = if ($St.SecretB64.Checked) { [Convert]::FromBase64String($St.Secret.Text) } else { [Text.Encoding]::UTF8.GetBytes($St.Secret.Text) }
                $h = switch ($alg) { 'HS256' { New-Object Security.Cryptography.HMACSHA256(, $key) } 'HS384' { New-Object Security.Cryptography.HMACSHA384(, $key) } default { New-Object Security.Cryptography.HMACSHA512(, $key) } }
                $sig = ConvertTo-Base64Url ($h.ComputeHash([Text.Encoding]::ASCII.GetBytes("$($parts[0]).$($parts[1])")))
                $h.Dispose()
                if ($sig -eq $parts[2]) { Add-RtbLine $o "$alg - signature is VALID for this secret" $C.Green; $summary += 'signature valid' }
                else { Add-RtbLine $o "$alg - signature does NOT match this secret" $C.Red; $summary += 'signature invalid'; $kind = 'error' }
            } catch { Add-RtbLine $o "Could not check: $($_.Exception.Message)" $C.Red }
        }
    } else { Add-RtbLine $o "$alg - checking needs the issuer's public key (not supported here)" $C.Dim }
    $o.SelectionStart = 0; $o.ScrollToCaret()
    Set-TbStatus $St.Status ("JWT  $Dot  alg $(if ($alg) { $alg } else { '?' })" + $(if ($summary) { "  $Dot  " + ($summary -join "  $Dot  ") } else { '' })) $kind
}

# ======================================================================================
# Regex tester: live highlighting, groups, replace preview.
# ======================================================================================
Register-ToolboxPage 'regex' 'Regex tester' $Glyph.Search 'regular expression regex match replace groups test' {
    param($panel, $st)
    foreach ($kv in (@{ Busy = $false }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.Orientation = 'Horizontal'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Text = New-TbRtb; $st.Text.Dock = 'Fill'
    $split.Panel1.Controls.Add($st.Text)
    New-TbLabel (New-TbBar $split.Panel1) 'Test text  (matches are highlighted)' -Dim | Out-Null
    $tabs = New-TabSet $split.Panel2
    $mPanel = Add-ApiTab $tabs 'Matches'
    $rPanel = Add-ApiTab $tabs 'Replace'
    $cPanel = Add-ApiTab $tabs 'Code'
    $hPanel = Add-ApiTab $tabs 'Cheat sheet'
    $st.Code = New-TbRtb -ReadOnly; $st.Code.Dock = 'Fill'; $cPanel.Controls.Add($st.Code)
    $cbar = New-TbBar $cPanel
    New-TbLabel $cbar 'How to use this pattern in the chosen language (flags from the checkboxes)' -Dim | Out-Null
    [void](New-Button 'Copy code' 'Copy the code' { Copy-TbText $TbUI.Pages['regex'].State.Code.Text } $cbar $Glyph.Copy 1)
    $cPanel.Controls.SetChildIndex($cbar, $cPanel.Controls.Count - 1)
    $cs = New-Object System.Windows.Forms.ListView
    $cs.Dock = 'Fill'; $cs.View = 'Details'; $cs.FullRowSelect = $true; $cs.BorderStyle = 'None'; $cs.BackColor = $C.Bg; $cs.ForeColor = $C.Fore
    [void]$cs.Columns.Add('Write', (Px (170 * $TextZoom))); [void]$cs.Columns.Add('Means  (double-click to put it into the pattern)', (Px (620 * $TextZoom)))
    foreach ($row in $RegexCheatSheet) { $it = New-Object System.Windows.Forms.ListViewItem($row[0]); $it.Font = New-Object System.Drawing.Font('Consolas', (Fz 10)); $it.UseItemStyleForSubItems = $false; [void]$it.SubItems.Add($row[1]); [void]$cs.Items.Add($it) }
    $cs.add_ItemActivate({
        param($src, $e)
        if (-not $src.SelectedItems.Count) { return }
        $tok = ($src.SelectedItems[0].Text -split '  ')[0]
        if ($tok -match '^\$') { $b = $TbUI.Pages['regex'].State.Replace } else { $b = $TbUI.Pages['regex'].State.Pattern }
        $b.SelectedText = $tok; [void]$b.Focus()
    })
    $hPanel.Controls.Add($cs)
    $st.Matches = New-Object System.Windows.Forms.ListView
    $st.Matches.Dock = 'Fill'; $st.Matches.View = 'Details'; $st.Matches.FullRowSelect = $true; $st.Matches.BorderStyle = 'None'
    $st.Matches.BackColor = $C.Bg; $st.Matches.ForeColor = $C.Fore; $st.Matches.Font = New-Object System.Drawing.Font('Consolas', (Fz 10))
    foreach ($col in @(@('#', 50), @('At', 70), @('Match', 320), @('Groups', 520))) { [void]$st.Matches.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $st.Matches.add_SelectedIndexChanged({
        $s = $TbUI.Pages['regex'].State
        if ($s.Matches.SelectedItems.Count -eq 0) { return }
        $m = $s.Matches.SelectedItems[0].Tag
        $s.Text.Select($m.Index, $m.Length); $s.Text.ScrollToCaret()
    })
    $mPanel.Controls.Add($st.Matches)
    $rbar = New-TbBar $rPanel
    New-TbLabel $rbar 'Replace with' -Dim | Out-Null
    $st.Replace = New-TbBox -Mono -Cue '$1, ${name}, $0 = whole match'
    $st.Replace.Width = Px (320 * $TextZoom); $st.Replace.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $rbar.Controls.Add($st.Replace)
    [void](New-Button 'Copy result' 'Copy the replaced text' { Copy-TbText $TbUI.Pages['regex'].State.Result.Text } $rbar $Glyph.Copy 1)
    $st.Result = New-TbRtb -ReadOnly; $st.Result.Dock = 'Fill'
    $rPanel.Controls.Add($st.Result)
    $rPanel.Controls.SetChildIndex($rbar, $rPanel.Controls.Count - 1)
    Select-ApiTab $tabs 'Matches'

    $pbar = New-TbBar $panel
    New-TbLabel $pbar 'Language' -Dim | Out-Null
    $st.Flavor = New-TbCombo $pbar @($RegexFlavors.Keys) 190
    $st.Flavor.add_SelectedIndexChanged({ Update-RegexTool $TbUI.Pages['regex'].State })
    [void](New-Button 'Examples' 'Ready-made patterns with sample text: email, URL, IP, dates, GUID, log lines, JSON ...' { param($src, $e) Show-RegexExampleMenu $src } $pbar $Glyph.Lightning 2)
    New-TbLabel $pbar 'Pattern' -Title | Out-Null
    $st.Pattern = New-TbBox -Mono -Cue '\b(\w+)@(\w+\.\w+)\b'
    $st.Pattern.Width = Px (460 * $TextZoom); $st.Pattern.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 10), 0)
    $pbar.Controls.Add($st.Pattern)
    $st.Opt = @{}
    foreach ($o in @(@('IgnoreCase', 'Ignore case', $true), @('Multiline', '^ $ per line', $true), @('Singleline', '. matches newline', $false), @('IgnorePatternWhitespace', 'Ignore spaces in pattern', $false))) {
        $cb = New-CheckBox $pbar $o[1] $o[2]
        $cb.add_CheckedChanged({ Update-RegexTool $TbUI.Pages['regex'].State })
        $st.Opt[$o[0]] = $cb
    }
    $st.Timer = New-TbDebounce 250 { Update-RegexTool $TbUI.Pages['regex'].State }
    foreach ($box in $st.Pattern, $st.Text, $st.Replace) { $box.add_TextChanged({ $s = $TbUI.Pages['regex'].State; if ($s.Busy) { return }; $s.Timer.Stop(); $s.Timer.Start() }) }
    $st.SetInput = { param($t) $s = $TbUI.Pages['regex'].State; $s.Text.Text = $t; Update-RegexTool $s }
    $st.Focus = { $TbUI.Pages['regex'].State.Pattern.Focus() }
    # Split half and half once the page has its real size.
    $split.Tag = $true
    $split.add_Resize({ param($src, $e) if ($src.Tag -and $src.Height -gt (Px 300)) { $src.Tag = $false; $src.SplitterDistance = [int]($src.Height * 0.5) } })
    $st.Text.Text = "Contact ann@example.com or bob@test.org`r`nOrder 1234 shipped on 2026-10-17"
    $st.Pattern.Text = '(\w+)@(\w+\.\w+)'
    Set-TbStatus $st.Status 'Pick the language you write the pattern for. Matching stops after 2 seconds, so a runaway pattern cannot hang the window.'
    $st
}

function Show-RegexExampleMenu($Button) {
    $m = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $ex = Get-RegexExamples
    foreach ($k in $ex.Keys) {
        $it = Add-MenuItem $m $k { param($src, $e) Set-RegexExample $src.Tag }
        $it.Tag = $k
    }
    $m.Show($Button, 0, $Button.Height)
}

function Set-RegexExample([string]$Name) {
            $x = (Get-RegexExamples)[$Name]
            $s = $TbUI.Pages['regex'].State
            $f = $RegexFlavors[[string]$s.Flavor.SelectedItem]
            $p = $x.P
            if ($f -in 'py', 'go') { $p = $p -replace '\(\?<(?![=!])', '(?P<' }
            $s.Busy = $true
            try {
                $s.Pattern.Text = $p; $s.Text.Text = $x.T
                $s.Opt.IgnoreCase.Checked = -not ($x.ContainsKey('I') -and -not $x.I)      # upper / lower case matters for some
                $s.Replace.Text = if ($x.ContainsKey('R')) { if ($f -eq 'py') { $x.R -replace '\$\{(\w+)\}', '\g<$1>' } elseif ($f -eq 'js') { $x.R -replace '\$\{(\w+)\}', '$$<$1>' } else { $x.R } } else { '' }
            } finally { $s.Busy = $false }
            Update-RegexTool $s
}

# ---- Regex flavours: the pattern is written the way the chosen language wants it; DevTools tests it
#      with .NET after translating the differences, and says what that language can't do.
$RegexFlavors = [ordered]@{
    '.NET (C#, PowerShell)'   = 'net'
    'JavaScript'              = 'js'
    'Python'                  = 'py'
    'Java / Kotlin'           = 'java'
    'PHP (PCRE)'              = 'php'
    'Go (RE2)'                = 'go'
    'grep -E / sed -E (POSIX)' = 'posix'
}

# -> @{ Pattern = .NET pattern; Flags = 'ims' taken from /.../flags; Notes = @(); Errors = @() }
function Convert-RegexToNet([string]$P, [string]$F) {
    $notes = New-Object System.Collections.Generic.List[string]
    $errors = New-Object System.Collections.Generic.List[string]
    $flags = ''
    # literals with delimiters: /abc/gi (JavaScript), #abc#i or /abc/i (PHP)
    if ($F -eq 'js' -and $P -match '^/(.+)/([dgimsuvy]*)$') { $P = $Matches[1] -replace '\\/', '/'; $flags = $Matches[2]; $notes.Add("flags /$flags taken from the literal") }
    elseif ($F -eq 'php' -and $P.Length -gt 2 -and $P[0] -match '[/#~@%!|+]') {
        $dl = [regex]::Escape([string]$P[0])
        if ($P -match "^$dl(.*)$dl([imsxuADSUXJn]*)$") { $P = $Matches[1]; $flags = $Matches[2]; if ($flags) { $notes.Add("flags $flags taken from the delimiters") } }
    }
    $ascii = $F -in 'js', 'java', 'php', 'go', 'posix'
    $sb = New-Object System.Text.StringBuilder
    $inClass = $false; $classStart = 0
    $i = 0
    $posix = @{ alpha = 'a-zA-Z'; digit = '0-9'; alnum = 'a-zA-Z0-9'; upper = 'A-Z'; lower = 'a-z'; space = '\s'; blank = ' \t'; xdigit = '0-9A-Fa-f'; punct = '!-/:-@\[-`{-~'; word = '\w'; cntrl = '\x00-\x1f'; print = '\x20-\x7e'; graph = '\x21-\x7e' }
    while ($i -lt $P.Length) {
        $ch = $P[$i]
        if ($ch -eq '\' -and $i + 1 -lt $P.Length) {
            $nx = [string]$P[$i + 1]
            $out = $null
            switch -CaseSensitive ($nx) {
                'd' { if ($ascii) { $out = $(if ($inClass) { '0-9' } else { '[0-9]' }) } }
                'D' { if ($ascii -and -not $inClass) { $out = '[^0-9]' } }
                'w' { if ($ascii) { $out = $(if ($inClass) { 'a-zA-Z0-9_' } else { '[a-zA-Z0-9_]' }) } }
                'W' { if ($ascii -and -not $inClass) { $out = '[^a-zA-Z0-9_]' } }
                'h' { if ($F -in 'php', 'java') { $out = $(if ($inClass) { ' \t' } else { '[ \t]' }) } }
                'R' { if ($F -in 'php', 'java') { $out = '(?:\r\n|[\n\r])' } }
                'K' { if ($F -eq 'php') { $errors.Add('\K (keep out) is PCRE only - can''t be tested here; use a lookbehind (?<=...)'); $out = '' } }
                'Z' { if ($F -eq 'py') { $out = '\z' } }
                'A' { if ($F -eq 'js') { $errors.Add('JavaScript has no \A - use ^ (without the m flag)') } }
                'z' { if ($F -eq 'js') { $errors.Add('JavaScript has no \z - use $ (without the m flag)') } }
                'G' { if ($F -in 'js', 'py', 'go') { $errors.Add("\G isn't supported in this language") } }
                default { if ($nx -match '^[1-9]$' -and $F -eq 'go') { $errors.Add('Go (RE2) has no back-references like \1') } }
            }
            if ($null -ne $out) { [void]$sb.Append($out) } else { [void]$sb.Append($ch).Append($nx) }
            $i += 2; continue
        }
        if ($inClass) {
            if ($ch -eq '[' -and $i + 1 -lt $P.Length -and $P[$i + 1] -eq ':') {
                $end = $P.IndexOf(':]', $i + 2)
                if ($end -gt 0) {
                    $name = $P.Substring($i + 2, $end - $i - 2)
                    if ($posix.ContainsKey($name)) { [void]$sb.Append($posix[$name]); $i = $end + 2; continue }
                }
            }
            if ($ch -eq ']' -and $i -gt $classStart) { $inClass = $false }
            [void]$sb.Append($ch); $i++; continue
        }
        if ($ch -eq '[') {
            $inClass = $true; [void]$sb.Append('['); $i++
            if ($i -lt $P.Length -and $P[$i] -eq '^') { [void]$sb.Append('^'); $i++ }
            if ($i -lt $P.Length -and $P[$i] -eq ']') { [void]$sb.Append('\]'); $i++ }
            $classStart = $i
            continue
        }
        if ($ch -eq '(' -and $i + 1 -lt $P.Length -and $P[$i + 1] -eq '?') {
            $rest = $P.Substring($i)
            if ($rest -match '^\(\?P<') { if ($F -in 'py', 'php', 'go') { [void]$sb.Append('(?<'); $i += 4; continue } else { $errors.Add('(?P<name>...) is Python / PHP / Go syntax - here write (?<name>...)') } }
            if ($rest -match '^\(\?P=(\w+)\)') { [void]$sb.Append("\k<$($Matches[1])>"); $i += $Matches[0].Length; if ($F -eq 'go') { $errors.Add('Go (RE2) has no back-references') }; continue }
            if ($rest -match '^\(\?(P>|R\)|\d+\)|&)') { $errors.Add('recursion ((?R), (?1), (?P>name)) is PCRE only - .NET can''t test it') }
            if ($rest -match '^\(\?(=|!|<=|<!)' -and $F -in 'go', 'posix') { $errors.Add("$(if ($F -eq 'go') { 'Go (RE2)' } else { 'POSIX ERE' }) has no lookahead / lookbehind ((?=...), (?!...), (?<=...), (?<!...))") }
            if ($rest -match '^\(\?>' -and $F -in 'js', 'go', 'posix') { $errors.Add('atomic groups (?>...) aren''t supported in this language') }
            if ($rest -match '^\(\?#' -and $F -in 'js', 'go', 'posix') { $errors.Add('comments (?#...) aren''t supported in this language') }
            if ($rest -match '^\(\?[imsx-]+[):]' -and $F -in 'js', 'posix') { $errors.Add('inline flags like (?i) aren''t supported here - use the checkboxes (flags)') }
            if ($rest -match '^\(\?<\w+>' -and $F -eq 'posix') { $errors.Add('POSIX ERE has no named groups') }
            if ($rest -match '^\(\?:' -and $F -eq 'posix') { $errors.Add('POSIX ERE has no (?:...) - use (...)') }
        }
        # quantifier modifiers: possessive (Java, PHP) / lazy (not in POSIX)
        if ($ch -match '[*+?}]' -and $i + 1 -lt $P.Length -and -not ($ch -eq '?' -and $i -gt 0 -and $P[$i - 1] -eq '(')) {
            $nx = $P[$i + 1]
            if ($nx -eq '+' -and $F -in 'java', 'php') { [void]$sb.Append($ch); $i += 2; if (-not ($notes | Where-Object { $_ -like 'possessive*' })) { $notes.Add('possessive quantifiers (x++, x*+) are tested as normal greedy ones') }; continue }
            if ($nx -eq '?' -and $F -eq 'posix') { $errors.Add('POSIX ERE has no lazy quantifiers (*?, +?)') }
        }
        [void]$sb.Append($ch); $i++
    }
    if ($F -eq 'posix' -and $P -match '\\[dws]') { $notes.Add('grep -E / sed -E don''t know \d \w \s everywhere - [[:digit:]] [[:alnum:]_] [[:space:]] always work') }
    if ($F -eq 'go' -and $P -match '\(\?<\w+>') { $notes.Add('older Go versions need (?P<name>...)') }
    @{ Pattern = $sb.ToString(); Flags = $flags; Notes = @($notes); Errors = @($errors) }
}

# The replacement as the language writes it -> .NET ($1, ${name}, $0)
function Convert-RegexReplacement([string]$R, [string]$F) {
    switch ($F) {
        'js'    { $R = $R -replace '\$&', '$$0' -replace '\$<(\w+)>', '$${$1}' }
        'py'    { $R = $R.Replace('$', '$$') -replace '\\g<(\w+)>', '$${$1}' -replace '\\(\d)', '$$$1' }
        'php'   { $R = $R -replace '\\(\d)', '$$$1' }
        'go'    { $R = $R -replace '\$([A-Za-z_]\w*)', '$${$1}' }
        'posix' { $R = $R.Replace('$', '$$') -replace '(?<!\\)&', '$$0' -replace '\\&', '&' -replace '\\(\d)', '$$$1' }
    }
    $R
}

# Code that uses the pattern in the chosen language.
function Get-RegexCode([string]$F, [string]$P, [string]$R, [bool]$I, [bool]$M, [bool]$S, [bool]$X) {
    $q1 = { param($t) "'" + $t.Replace("'", "''") + "'" }                                   # PowerShell
    $dq = { param($t) '"' + $t.Replace('\', '\\').Replace('"', '\"') + '"' }               # Java-style string
    switch ($F) {
        'net' {
            $o = @(); if ($I) { $o += 'IgnoreCase' }; if ($M) { $o += 'Multiline' }; if ($S) { $o += 'Singleline' }; if ($X) { $o += 'IgnorePatternWhitespace' }
            $cs = if ($o) { ($o | ForEach-Object { "RegexOptions.$_" }) -join ' | ' } else { 'RegexOptions.None' }
            $ps = if ($o) { "'" + ($o -join ', ') + "'" } else { "'None'" }
            @"
// C#   (using System.Text.RegularExpressions;)
var rx = new Regex(@"$($P.Replace('"', '""'))", $cs);
foreach (Match m in rx.Matches(text))
    Console.WriteLine(m.Value + "  group 1: " + m.Groups[1].Value);
string replaced = rx.Replace(text, @"$($R.Replace('"', '""'))");

# PowerShell
`$rx = [regex]::new($(& $q1 $P), $ps)
foreach (`$m in `$rx.Matches(`$text)) { `$m.Value; `$m.Groups[1].Value }
`$replaced = `$rx.Replace(`$text, $(& $q1 $R))
if (`$text -match $(& $q1 $P)) { `$Matches[0] }      # -match ignores case by default (-cmatch doesn't)
"@
        }
        'js' {
            $fl = 'g' + $(if ($I) { 'i' }) + $(if ($M) { 'm' }) + $(if ($S) { 's' })
            $lit = $P -replace '(?<!\\)/', '\/'
            if ($P -match '^/(.+)/([a-z]*)$') { $lit = $Matches[1]; $fl = $Matches[2]; if ($fl -notmatch 'g') { $fl = 'g' + $fl } }
            @"
const re = /$lit/$fl;$(if ($X) { '        // JavaScript has no x flag: remove the spaces / comments' })
for (const m of text.matchAll(re)) {
  console.log(m[0], 'group 1:', m[1], 'at', m.index);   // named: m.groups.name
}
const replaced = text.replace(re, '$($R.Replace("'", "\'"))');    // `$1, `$<name>, `$& = whole match
const first = text.match(new RegExp(re.source, re.flags.replace('g', '')));
"@
        }
        'py' {
            $o = @(); if ($I) { $o += 're.IGNORECASE' }; if ($M) { $o += 're.MULTILINE' }; if ($S) { $o += 're.DOTALL' }; if ($X) { $o += 're.VERBOSE' }
            $qq = if ($P.Contains("'") -and -not $P.Contains('"')) { '"' } else { "'" }
            $pp = if ($P.EndsWith('\') -or ($P.Contains("'") -and $P.Contains('"'))) { & $dq $P } else { "r$qq$P$qq" }
            @"
import re

rx = re.compile($pp$(if ($o) { ', ' + ($o -join ' | ') }))
for m in rx.finditer(text):
    print(m.group(0), 'group 1:', m.group(1) if rx.groups else None, 'at', m.start())   # named: m.group('name')
replaced = rx.sub(r'$($R.Replace("'", "\'"))', text)      # \1, \g<name>, \g<0> = whole match
first = rx.search(text)
"@
        }
        'java' {
            $o = @(); if ($I) { $o += 'Pattern.CASE_INSENSITIVE' }; if ($M) { $o += 'Pattern.MULTILINE' }; if ($S) { $o += 'Pattern.DOTALL' }; if ($X) { $o += 'Pattern.COMMENTS' }
            @"
// import java.util.regex.*;
Pattern p = Pattern.compile($(& $dq $P)$(if ($o) { ', ' + ($o -join ' | ') }));
Matcher m = p.matcher(text);
while (m.find()) {
    System.out.println(m.group() + "  group 1: " + (m.groupCount() > 0 ? m.group(1) : null));   // named: m.group("name")
}
String replaced = p.matcher(text).replaceAll($(& $dq $R));   // `$1, `${name}, `$0
"@
        }
        'php' {
            $body = $P; $fl = $(if ($I) { 'i' }) + $(if ($M) { 'm' }) + $(if ($S) { 's' }) + $(if ($X) { 'x' }) + 'u'
            $lit = if ($P.Length -gt 2 -and $P[0] -match '[/#~@%!|+]' -and $P -match ('^' + [regex]::Escape([string]$P[0]) + '.*' + [regex]::Escape([string]$P[0]) + '[a-zA-Z]*$')) { $P } else { '/' + ($body -replace '(?<!\\)/', '\/') + '/' + $fl }
            @"
<?php
preg_match_all('$($lit.Replace('\', '\\').Replace("'", "\'"))', `$text, `$matches, PREG_SET_ORDER);
foreach (`$matches as `$m) {
    echo `$m[0], ' group 1: ', `$m[1] ?? '', PHP_EOL;     // named: `$m['name']
}
`$replaced = preg_replace('$($lit.Replace('\', '\\').Replace("'", "\'"))', '$($R.Replace('\', '\\').Replace("'", "\'"))', `$text);   // `$1, `${1}, \1
"@
        }
        'go' {
            $fl = $(if ($I) { 'i' }) + $(if ($M) { 'm' }) + $(if ($S) { 's' })
            $pp = $(if ($fl) { "(?$fl)" }) + $P
            $lit = if ($pp.Contains('`')) { & $dq $pp } else { '`' + $pp + '`' }
            @"
// import "regexp"
re := regexp.MustCompile($lit)$(if ($X) { '   // Go has no x flag: remove the spaces' })
for _, m := range re.FindAllStringSubmatch(text, -1) {
    fmt.Println(m[0], "group 1:", m[1:])          // named: re.SubexpIndex("name")
}
replaced := re.ReplaceAllString(text, $(if ($R.Contains('`')) { & $dq $R } else { '`' + $R + '`' }))   // `$1, `${1}, `${name}
"@
        }
        'posix' {
            $sq = { param($t) "'" + $t.Replace("'", "'\''") + "'" }
            $ci = if ($I) { ' -i' } else { '' }
            $sedP = $P.Replace('/', '\/'); $sedR = $R.Replace('/', '\/')
            @"
# lines that match / only the matching parts
grep -E$ci $(& $sq $P) file.txt
grep -E -o$ci $(& $sq $P) file.txt

# replace (GNU sed; \1 = group 1, & = whole match)
sed -E $(& $sq "s/$sedP/$sedR/g$(if ($I) { 'I' })") file.txt
"@
        }
    }
}

# Ready-made patterns (written so they work in most languages; named groups are adapted when chosen).
function Get-RegexExamples {
    [ordered]@{
        'Email address'          = @{ P = '[\w.+-]+@[\w-]+(\.[\w-]+)+'; T = "Write to ann.smith@example.com or bob+news@mail.test.org`r`nNot an email: ann@ or @test.org" }
        'URL (http / https)'     = @{ P = 'https?://[^\s/$.?#][^\s]*'; T = "Docs: https://example.com/docs?page=2#top and http://localhost:8080/api`r`nnot: ftp://x.org" }
        'IPv4 address'           = @{ P = '\b((25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(25[0-5]|2[0-4]\d|1?\d?\d)\b'; T = "Servers 10.0.0.1, 192.168.1.254 and 8.8.8.8`r`nInvalid: 256.1.1.1 and 1.2.3" }
        'Date YYYY-MM-DD (reorder to DD.MM.YYYY)' = @{ P = '\b(?<y>\d{4})-(?<m>\d{2})-(?<d>\d{2})\b'; T = "Released 2026-10-17, patched 2026-11-02."; R = '${d}.${m}.${y}' }
        'Time HH:MM(:SS)'        = @{ P = '\b([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?\b'; T = "Start 09:30, end 17:45:10, invalid 25:61" }
        'GUID / UUID'            = @{ P = '\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b'; T = "id=3f2504e0-4f89-11d3-9a0c-0305e82c3301 and 00000000-0000-0000-0000-000000000000" }
        'Phone number'           = @{ P = '\+?\d{1,3}[ -]?\(?\d{2,4}\)?[ -]?\d{3,4}[ -]?\d{3,4}'; T = "Call +359 88 123 4567 or (555) 123-4567 or 0888123456" }
        'Number (int / decimal)' = @{ P = '-?\b\d+(\.\d+)?\b'; T = "Totals: 42, -7, 3.14 and 1000.50" }
        'Hex colour'             = @{ P = '#([0-9a-fA-F]{3}){1,2}\b'; T = "color: #fff; background: #1E90FF; border: #12345" }
        'Words in quotes'        = @{ P = '"([^"\\]|\\.)*"|''([^''\\]|\\.)*'''; T = "say ""hello"" and 'bye', even ""with \""escape\"""" " }
        'Repeated word'          = @{ P = '\b(\w+)\s+\1\b'; T = "This is is a test of the the repeated words." }
        'Key = value pairs'      = @{ P = '^\s*(?<key>[\w.-]+)\s*[=:]\s*(?<value>.*?)\s*$'; T = "host = localhost`r`nport: 5432`r`n# comment`r`nuser=admin" }
        'Log line (time, level, message)' = @{ P = '^(?<time>\d{4}-\d{2}-\d{2}[ T][\d:.]+)\s+\[?(?<level>INFO|WARN|ERROR|DEBUG)\]?\s+(?<msg>.*)$'; T = "2026-10-17 09:12:01.123 INFO Service started`r`n2026-10-17 09:12:05.456 [ERROR] Connection refused`r`nrandom line" }
        'HTML tag'               = @{ P = '<(?<tag>[a-zA-Z][\w-]*)(?<attrs>[^>]*)>'; T = '<div class="box"><a href="/home">Home</a><br/></div>' }
        'JSON "key": value'      = @{ P = '"(?<key>[^"]+)"\s*:\s*(?<value>"[^"]*"|-?\d+(\.\d+)?|true|false|null)'; T = '{"name": "Ann", "age": 31, "admin": false, "city": null}' }
        'Strong password (lookaheads)' = @{ P = '^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^\w\s]).{8,}$'; T = "weakpass`r`nStr0ng!Pass`r`nNoDigits!!`r`nGood#Pass99"; I = $false }
        'Trailing spaces (remove)' = @{ P = '[ \t]+$'; T = "line with spaces   `r`nclean line`r`ntabs`t`t"; R = '' }
        'Empty lines (remove)'   = @{ P = '^\s*$\r?\n'; T = "first`r`n`r`n   `r`nsecond`r`n`r`nthird"; R = '' }
        'Between two words'      = @{ P = '(?<=START).*?(?=END)'; T = "xxSTART the part you want ENDyy" }
        'camelCase -> snake_case' = @{ P = '(?<=[a-z0-9])(?=[A-Z])'; T = "userName orderIdValue parseHTTPResponse"; R = '_'; I = $false }
    }
}

# Tokens for the cheat sheet (double-click one to put it into the pattern).
$RegexCheatSheet = @(
    @('.', 'any character (except a newline, unless "dot matches newline")'), @('\d  \D', 'a digit / not a digit'),
    @('\w  \W', 'a word character (letter, digit, _) / not one'), @('\s  \S', 'white space / not white space'),
    @('[abc]', 'one of a, b, c'), @('[^abc]', 'anything except a, b, c'), @('[a-z0-9]', 'a range'),
    @('^  $', 'start / end of the text (of each line with "^ $ per line")'), @('\b', 'word boundary'),
    @('*  +  ?', '0 or more / 1 or more / 0 or 1'), @('{3}  {2,5}  {2,}', 'exactly 3 / 2 to 5 / 2 or more'),
    @('*?  +?', 'lazy: as few as possible'), @('(abc)', 'group (captured as $1 ...)'), @('(?:abc)', 'group without capturing'),
    @('(?<name>abc)', 'named group (Python / Go: (?P<name>abc))'), @('\1  \k<name>', 'the same text as group 1 / group "name" again'),
    @('a|b', 'a or b'), @('(?=abc)', 'followed by abc (lookahead)'), @('(?!abc)', 'not followed by abc'),
    @('(?<=abc)', 'preceded by abc (lookbehind)'), @('(?<!abc)', 'not preceded by abc'),
    @('\.  \*  \\', 'a literal . * \ (escape special characters)'), @('\t  \n  \r', 'tab / newline / carriage return'),
    @('\uFFFF  \x41', 'a character by its code'), @('(?i)', 'ignore case from here (not in JavaScript)'),
    @('$1  ${name}  $0', 'in Replace: group 1 / group "name" / the whole match')
)

function Update-RegexTool($St) {
    $St.Busy = $true
    $rtb = $St.Text
    $selStart = $rtb.SelectionStart; $selLen = $rtb.SelectionLength
    [PowerClipTheme]::Redraw($rtb.Handle, $false)
    try {
        $rtb.SelectAll(); $rtb.SelectionBackColor = $C.Bg; $rtb.SelectionColor = $C.Fore
        $St.Matches.BeginUpdate(); $St.Matches.Items.Clear()
        $pattern = $St.Pattern.Text
        $flv = if ($St.Flavor) { $RegexFlavors[[string]$St.Flavor.SelectedItem] } else { 'net' }
        $lang = [string]$St.Flavor.SelectedItem
        if ($St.Code) { $St.Code.Text = if ($pattern) { Get-RegexCode $flv $pattern $St.Replace.Text $St.Opt.IgnoreCase.Checked $St.Opt.Multiline.Checked $St.Opt.Singleline.Checked $St.Opt.IgnorePatternWhitespace.Checked } else { '' } }
        if (-not $pattern) { $St.Result.Text = $rtb.Text; Set-TbStatus $St.Status 'Type a pattern.'; return }
        $cvt = Convert-RegexToNet $pattern $flv
        $pattern = $cvt.Pattern
        $opts = [System.Text.RegularExpressions.RegexOptions]::None
        foreach ($k in $St.Opt.Keys) { if ($St.Opt[$k].Checked) { $opts = $opts -bor [System.Text.RegularExpressions.RegexOptions]$k } }
        if ($cvt.Flags) {             # flags from /.../gi: they decide i, m, s, x
            $opts = [System.Text.RegularExpressions.RegexOptions]::None
            if ($cvt.Flags -cmatch 'i') { $opts = $opts -bor 'IgnoreCase' }; if ($cvt.Flags -cmatch 'm') { $opts = $opts -bor 'Multiline' }
            if ($cvt.Flags -cmatch 's') { $opts = $opts -bor 'Singleline' }; if ($cvt.Flags -cmatch 'x') { $opts = $opts -bor 'IgnorePatternWhitespace' }
        }
        try { $rx = New-Object System.Text.RegularExpressions.Regex($pattern, $opts, [TimeSpan]::FromSeconds(2)) }
        catch { Set-TbStatus $St.Status "Pattern error: $($_.Exception.InnerException.Message)" 'error'; return }
        $text = $rtb.Text
        try {
            $ms = $rx.Matches($text)
            $count = $ms.Count
            $hl = @([PowerClipTheme]::Mix($C.Bg, $C.Yellow, 0.35), [PowerClipTheme]::Mix($C.Bg, $C.Accent, 0.30))
            $n = 0
            foreach ($m in $ms) {
                if ($n -lt 2000 -and $m.Length -gt 0) { $rtb.Select($m.Index, $m.Length); $rtb.SelectionBackColor = $hl[$n % 2] }
                if ($n -lt 1000) {
                    $groups = @()
                    for ($g = 1; $g -lt $m.Groups.Count; $g++) {
                        $name = $rx.GroupNameFromNumber($g)
                        $groups += "$(if ($name -ne [string]$g) { $name } else { $g })=$($m.Groups[$g].Value)"
                    }
                    $it = New-Object System.Windows.Forms.ListViewItem([string]($n + 1))
                    [void]$it.SubItems.Add([string]$m.Index); [void]$it.SubItems.Add($m.Value); [void]$it.SubItems.Add($groups -join '   ')
                    $it.Tag = $m
                    [void]$St.Matches.Items.Add($it)
                }
                $n++
            }
            $St.Result.Text = $rx.Replace($text, (Convert-RegexReplacement $St.Replace.Text $flv))
            $msg = "$count match$(if ($count -ne 1) { 'es' })$(if ($count -gt 1000) { '  (first 1000 listed)' })"
            if ($cvt.Errors.Count) { $msg += "  -  Not valid in ${lang}: $($cvt.Errors -join '; ')" }
            elseif ($cvt.Notes.Count) { $msg += "  -  $($cvt.Notes -join '; ')" }
            Set-TbStatus $St.Status $msg $(if ($cvt.Errors.Count) { 'warn' } elseif ($count) { 'ok' } else { 'warn' })
        } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
            Set-TbStatus $St.Status 'Stopped: the pattern took longer than 2 seconds (catastrophic backtracking?)' 'error'
        } catch {
            $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
            Set-TbStatus $St.Status $(if ($ex -is [System.Text.RegularExpressions.RegexMatchTimeoutException]) { 'Stopped: the pattern took longer than 2 seconds (catastrophic backtracking?)' } else { "Error: $($ex.Message)" }) 'error'
        }
    } finally {
        $St.Matches.EndUpdate()
        $rtb.Select($selStart, $selLen)
        [PowerClipTheme]::Redraw($rtb.Handle, $true)
        $rtb.Invalidate()
        $St.Busy = $false
    }
}

# ======================================================================================
# Cron: explain an expression and list the next runs.
# ======================================================================================
Register-ToolboxPage 'cron' 'Cron expressions' $Glyph.History 'cron schedule crontab next run quartz' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Runs = New-TbRtb -ReadOnly; $st.Runs.Dock = 'Fill'
    $panel.Controls.Add($st.Runs)
    $desc = New-Object System.Windows.Forms.Label
    $desc.Dock = 'Top'; $desc.AutoSize = $false; $desc.Height = $FontTitle.Height * 2 + (Px 20); $desc.ForeColor = $C.Accent; $desc.BackColor = $C.Bg
    $desc.Font = New-Object System.Drawing.Font($UiFont, (Fz 13), [System.Drawing.FontStyle]::Bold); $desc.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
    $panel.Controls.Add($desc)
    $st.Desc = $desc
    $pre = New-TbBar $panel
    New-TbLabel $pre 'Examples' -Dim | Out-Null
    foreach ($x in @(@('Every 5 min', '*/5 * * * *'), @('Hourly', '0 * * * *'), @('Daily 09:00', '0 9 * * *'), @('Weekdays 09:00', '0 9 * * 1-5'),
                     @('Mon 08:30', '30 8 * * MON'), @('1st of month', '0 0 1 * *'), @('Every 15 s', '*/15 * * * * *'))) {
        $b = New-Button $x[0] $x[1] { param($src, $e) $TbUI.Pages['cron'].State.Expr.Text = $src.Tag } $pre '' 2
        $b.Tag = $x[1]
    }
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Expression' -Title | Out-Null
    $st.Expr = New-TbBox -Mono -Cue 'minute hour day month weekday   e.g.  */15 9-17 * * 1-5'
    $st.Expr.Width = Px (360 * $TextZoom); $st.Expr.Font = New-Object System.Drawing.Font('Consolas', (Fz 13)); $st.Expr.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), (Px 10), 0)
    $bar.Controls.Add($st.Expr)
    New-TbLabel $bar 'minute  hour  day-of-month  month  weekday   (6 fields = seconds first; @daily, @hourly ...)' -Dim | Out-Null
    $st.Expr.add_TextChanged({ Update-CronTool $TbUI.Pages['cron'].State })
    $st.SetInput = { param($t) $TbUI.Pages['cron'].State.Expr.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['cron'].State.Expr.Focus() }
    $st.Expr.Text = '*/15 9-17 * * 1-5'
    $st
}

function Update-CronTool($St) {
    $e = $St.Expr.Text.Trim()
    $St.Runs.Clear()
    if (-not $e) { $St.Desc.Text = ''; Set-TbStatus $St.Status 'Type a cron expression.'; return }
    try {
        $cx = [DevCron]::Parse($e)
        $St.Desc.Text = $cx.Describe()
        $St.Desc.ForeColor = $C.Accent
        Add-RtbLine $St.Runs 'NEXT RUNS (your local time)' $C.Accent -Bold
        $now = Get-Date
        foreach ($t in $cx.NextRuns($now, 12)) { Add-RtbLine $St.Runs ("{0}    {1}" -f $t.ToString('ddd  yyyy-MM-dd  HH:mm:ss'), (Format-Relative $t)) }
        Set-TbStatus $St.Status 'Valid expression' 'ok'
    } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        $St.Desc.Text = 'Not a valid cron expression'; $St.Desc.ForeColor = $C.Red
        Set-TbStatus $St.Status $ex.Message 'error'
    }
}

# ======================================================================================
# Generators: GUIDs, passwords, lorem ipsum, random test data.
# ======================================================================================
$TestData = @{
    First = 'Olivia Liam Emma Noah Ava Elijah Sophia James Isabella William Mia Benjamin Charlotte Lucas Amelia Henry Harper Alexander Evelyn Daniel Maria Ivan Elena Georgi Petar Yana Mateo Sofia Hiro Aiko Priya Arjun Fatima Omar Lena Jonas'.Split(' ')
    Last  = 'Smith Johnson Williams Brown Jones Garcia Miller Davis Rodriguez Martinez Hernandez Lopez Wilson Anderson Thomas Taylor Moore Jackson Martin Lee Petrov Ivanova Dimitrov Schmidt Muller Rossi Silva Tanaka Kim Nguyen Patel Novak Kowalski'.Split(' ')
    City  = 'Springfield Riverton Lakeside Fairview Greenville Madison Georgetown Franklin Clinton Salem Sofia Plovdiv Varna Berlin Munich Vienna Prague Lisbon Porto Dublin Austin Denver Portland Seattle Toronto'.Split(' ')
    Street = 'Main Oak Pine Maple Cedar Elm Washington Lake Hill Park Church High Station Mill River Sunset Forest Meadow'.Split(' ')
    Country = 'United States|Canada|United Kingdom|Germany|France|Bulgaria|Spain|Italy|Netherlands|Austria|Japan|Australia|Brazil|India'.Split('|')
    Company = 'Acme|Globex|Initech|Umbrella|Stark Industries|Wayne Enterprises|Hooli|Vandelay|Soylent|Tyrell|Cyberdyne|Wonka|Pied Piper|Northwind|Contoso|Fabrikam'.Split('|')
    Domain = 'example.com example.org example.net test.io mail.test demo.dev'.Split(' ')
    Lorem = 'lorem ipsum dolor sit amet consectetur adipiscing elit sed do eiusmod tempor incididunt ut labore et dolore magna aliqua enim ad minim veniam quis nostrud exercitation ullamco laboris nisi aliquip ex ea commodo consequat duis aute irure in reprehenderit voluptate velit esse cillum fugiat nulla pariatur excepteur sint occaecat cupidatat non proident sunt culpa qui officia deserunt mollit anim id est laborum'.Split(' ')
}
$Rng = New-Object System.Random

function Get-RandomItem($List) { $List[$Rng.Next($List.Count)] }

function New-LoremSentence {
    $n = $Rng.Next(6, 15)
    $w = 1..$n | ForEach-Object { Get-RandomItem $TestData.Lorem }
    $s = ($w -join ' ')
    $s.Substring(0, 1).ToUpper() + $s.Substring(1) + '.'
}

function New-TestRow([string[]]$Fields, [int]$Index) {
    $first = Get-RandomItem $TestData.First; $last = Get-RandomItem $TestData.Last
    $o = [ordered]@{}
    foreach ($f in $Fields) {
        $o[$f] = switch ($f) {
            'id'      { $Index }
            'name'    { "$first $last" }
            'email'   { "$($first.ToLower()).$($last.ToLower())$($Rng.Next(1, 99))@$(Get-RandomItem $TestData.Domain)" }
            'phone'   { '+1 555 {0:000} {1:0000}' -f $Rng.Next(100, 999), $Rng.Next(0, 9999) }
            'address' { "$($Rng.Next(1, 999)) $(Get-RandomItem $TestData.Street) Street" }
            'city'    { Get-RandomItem $TestData.City }
            'country' { Get-RandomItem $TestData.Country }
            'company' { Get-RandomItem $TestData.Company }
            'date'    { (Get-Date).AddDays(-$Rng.Next(0, 3650)).ToString('yyyy-MM-dd') }
            'amount'  { [Math]::Round($Rng.NextDouble() * 1000, 2) }
            'active'  { $Rng.Next(2) -eq 1 }
            'guid'    { [guid]::NewGuid().ToString() }
        }
    }
    $o
}

Register-ToolboxPage 'gen' 'Generators' $Glyph.Refresh 'generate guid uuid password lorem ipsum test data fake random' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Output = New-TbBox -Mono -Multi -ReadOnly
    $st.Output.Dock = 'Fill'
    $panel.Controls.Add($st.Output)
    $obar = New-TbBar $panel
    [void](New-Button 'Generate' 'Generate again (F5)' { New-GeneratorOutput $TbUI.Pages['gen'].State } $obar $Glyph.Refresh 1)
    [void](New-Button 'Copy' 'Copy the output' { Copy-TbText $TbUI.Pages['gen'].State.Output.Text } $obar $Glyph.Copy)
    $opts = New-TbBar $panel
    $kind = New-TbBar $panel
    New-TbLabel $kind 'Generate' -Title | Out-Null
    $st.Kind = New-TbCombo $kind @('GUIDs', 'Passwords', 'Lorem ipsum', 'Test data') 150
    New-TbLabel $kind 'How many' -Dim | Out-Null
    $st.Count = New-TbNumber $kind 5 1 10000
    $st.OptsBar = $opts
    $st.Kind.add_SelectedIndexChanged({ $s = $TbUI.Pages['gen'].State; Build-GeneratorOptions $s; New-GeneratorOutput $s })
    $st.Count.add_ValueChanged({ New-GeneratorOutput $TbUI.Pages['gen'].State })
    $st.Focus = { $TbUI.Pages['gen'].State.Kind.Focus() }
    Build-GeneratorOptions $st
    New-GeneratorOutput $st
    $st
}

function Build-GeneratorOptions($St) {
    $bar = $St.OptsBar
    $bar.Controls.Clear()
    $St.O = @{}
    $regen = { New-GeneratorOutput $TbUI.Pages['gen'].State }
    switch ($St.Kind.SelectedItem) {
        'GUIDs' {
            New-TbLabel $bar 'Format' -Dim | Out-Null
            $St.O.Format = New-TbCombo $bar @('lower case', 'UPPER CASE', 'no dashes', '{braces}', 'C# new Guid("...")') 180
            $St.O.Format.add_SelectedIndexChanged($regen)
        }
        'Passwords' {
            New-TbLabel $bar 'Length' -Dim | Out-Null
            $St.O.Length = New-TbNumber $bar 20 4 256; $St.O.Length.add_ValueChanged($regen)
            foreach ($x in @(@('Upper', 'A-Z'), @('Lower', 'a-z'), @('Digits', '0-9'), @('Symbols', '!@#...'))) {
                $St.O[$x[0]] = New-CheckBox $bar $x[1] $true; $St.O[$x[0]].add_CheckedChanged($regen)
            }
            New-TbLabel $bar 'Similar-looking characters (O 0 l 1 I) are left out.' -Dim | Out-Null
        }
        'Lorem ipsum' {
            New-TbLabel $bar 'Unit' -Dim | Out-Null
            $St.O.Unit = New-TbCombo $bar @('paragraphs', 'sentences', 'words') 130
            $St.O.Unit.add_SelectedIndexChanged($regen)
            $St.O.Classic = New-CheckBox $bar 'Start with "Lorem ipsum dolor sit amet"' $true; $St.O.Classic.add_CheckedChanged($regen)
        }
        'Test data' {
            New-TbLabel $bar 'As' -Dim | Out-Null
            $St.O.Format = New-TbCombo $bar @('JSON', 'CSV', 'SQL INSERT') 120
            $St.O.Format.add_SelectedIndexChanged($regen)
            $St.O.Fields = @{}
            foreach ($f in 'id', 'name', 'email', 'phone', 'address', 'city', 'country', 'company', 'date', 'amount', 'active', 'guid') {
                $on = $f -in 'id', 'name', 'email', 'city', 'date'
                $St.O.Fields[$f] = New-CheckBox $bar $f $on; $St.O.Fields[$f].add_CheckedChanged($regen)
            }
        }
    }
    Set-ControlTheme $bar $null $script:IsDark
}

function New-GeneratorOutput($St) {
    $n = [int]$St.Count.Value
    $out = switch ($St.Kind.SelectedItem) {
        'GUIDs' {
            $fmt = $St.O.Format.SelectedIndex
            (1..$n | ForEach-Object {
                $g = [guid]::NewGuid()
                switch ($fmt) { 1 { $g.ToString().ToUpper() } 2 { $g.ToString('N') } 3 { $g.ToString('B') } 4 { "new Guid(`"$g`")" } default { $g.ToString() } }
            }) -join "`r`n"
        }
        'Passwords' {
            (1..$n | ForEach-Object { [PowerClipVault]::Generate([int]$St.O.Length.Value, $St.O.Upper.Checked, $St.O.Lower.Checked, $St.O.Digits.Checked, $St.O.Symbols.Checked) }) -join "`r`n"
        }
        'Lorem ipsum' {
            $unit = $St.O.Unit.SelectedItem
            $classic = $St.O.Classic.Checked
            $txt = switch ($unit) {
                'words' { (1..$n | ForEach-Object { Get-RandomItem $TestData.Lorem }) -join ' ' }
                'sentences' { (1..$n | ForEach-Object { New-LoremSentence }) -join ' ' }
                default { (1..$n | ForEach-Object { (1..$Rng.Next(4, 8) | ForEach-Object { New-LoremSentence }) -join ' ' }) -join "`r`n`r`n" }
            }
            if ($classic) {
                $start = 'Lorem ipsum dolor sit amet, consectetur adipiscing elit'
                if ($unit -eq 'words') { $txt = (($start -replace ',', '').Split(' ') + $txt.Split(' '))[0..($n - 1)] -join ' ' }
                else { $txt = $start + '. ' + $txt }
            }
            $txt
        }
        'Test data' {
            $fields = @($St.O.Fields.Keys | Where-Object { $St.O.Fields[$_].Checked } | Sort-Object { @('id', 'name', 'email', 'phone', 'address', 'city', 'country', 'company', 'date', 'amount', 'active', 'guid').IndexOf($_) })
            if (-not $fields) { $fields = @('name') }
            $rows = foreach ($i in 1..$n) { New-TestRow $fields $i }
            switch ($St.O.Format.SelectedItem) {
                'CSV' {
                    $lines = @($fields -join ',')
                    foreach ($r in $rows) { $lines += (($fields | ForEach-Object { $v = [string]$r[$_]; if ($v -match '[,"]') { '"' + $v.Replace('"', '""') + '"' } else { $v } }) -join ',') }
                    $lines -join "`r`n"
                }
                'SQL INSERT' {
                    ($rows | ForEach-Object {
                        $r = $_
                        $vals = $fields | ForEach-Object { $v = $r[$_]; if ($v -is [bool]) { [int]$v } elseif ($v -is [int] -or $v -is [double]) { [string]$v } else { "'" + ([string]$v).Replace("'", "''") + "'" } }
                        "INSERT INTO people ($($fields -join ', ')) VALUES ($($vals -join ', '));"
                    }) -join "`r`n"
                }
                default { ConvertTo-Json -InputObject @($rows | ForEach-Object { [pscustomobject]$_ }) -Depth 3 }
            }
        }
    }
    $St.Output.Text = [string]$out
    Set-TbStatus $St.Status "$($St.Kind.SelectedItem): $n generated  $Dot  random values from a cryptographic generator (passwords, GUIDs)"
}

# ======================================================================================
# QR code
# ======================================================================================
Register-ToolboxPage 'qr' 'QR code' $Glyph.Apps 'qr code barcode generate image' {
    param($panel, $st)
    foreach ($kv in (@{ Bitmap = $null }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $st.Picture = New-Object System.Windows.Forms.PictureBox
    $st.Picture.Dock = 'Fill'; $st.Picture.SizeMode = 'Zoom'; $st.Picture.BackColor = $C.Bg
    $panel.Controls.Add($st.Picture)
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Error correction' -Dim | Out-Null
    $st.Level = New-TbCombo $bar @('L - 7%', 'M - 15%', 'Q - 25%', 'H - 30%') 110
    $st.Level.SelectedIndex = 1
    [void](New-Button 'Copy image' 'Copy the QR code as a picture' { $s = $TbUI.Pages['qr'].State; if ($s.Bitmap) { [System.Windows.Forms.Clipboard]::SetImage($s.Bitmap) } } $bar $Glyph.Copy 1)
    [void](New-Button 'Save PNG...' 'Save the QR code as a PNG file' {
        $s = $TbUI.Pages['qr'].State
        if (-not $s.Bitmap) { return }
        $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PNG image|*.png'; $d.FileName = 'qr.png'
        if ($d.ShowDialog($TbUI.Form) -eq 'OK') { $s.Bitmap.Save($d.FileName, [System.Drawing.Imaging.ImageFormat]::Png) }
        $d.Dispose()
    } $bar $Glyph.Save)
    $st.Text = New-TbBox -Multi -Cue 'Text or link to encode'
    $st.Text.Dock = 'Top'; $st.Text.Height = $FontMain.Height * 4; $st.Text.WordWrap = $true; $st.Text.ScrollBars = 'Vertical'
    $panel.Controls.Add($st.Text)
    $st.Text.add_TextChanged({ Update-QrTool $TbUI.Pages['qr'].State })
    $st.Level.add_SelectedIndexChanged({ Update-QrTool $TbUI.Pages['qr'].State })
    $st.SetInput = { param($t) $TbUI.Pages['qr'].State.Text.Text = $t }
    $st.Focus = { $TbUI.Pages['qr'].State.Text.Focus() }
    $st.Close = { $s = $TbUI.Pages['qr'].State; if ($s.Bitmap) { $s.Bitmap.Dispose() } }
    $st.Text.Text = 'https://example.com'
    $st
}

function Update-QrTool($St) {
    $t = $St.Text.Text
    if ($St.Bitmap) { $St.Picture.Image = $null; $St.Bitmap.Dispose(); $St.Bitmap = $null }
    if (-not $t) { Set-TbStatus $St.Status 'Type text or a link.'; return }
    try {
        $m = [DevQr]::Encode($t, $St.Level.SelectedIndex)
        $St.Bitmap = [DevQr]::ToBitmap($m, 10, 4, [System.Drawing.Color]::Black, [System.Drawing.Color]::White)
        $St.Picture.Image = $St.Bitmap
        $bytes = [Text.Encoding]::UTF8.GetByteCount($t)
        Set-TbStatus $St.Status "$($m.GetLength(0)) x $($m.GetLength(0)) modules  $Dot  $bytes bytes  $Dot  scans with any phone camera" 'ok'
    } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        Set-TbStatus $St.Status $ex.Message 'error'
    }
}

# ======================================================================================
# Hide secret messages: inside a picture, inside normal text (invisible characters) or at the end of any file.
# ======================================================================================
Register-ToolboxPage 'stego' 'Hide secret messages' $Glyph.Lock 'steganography hide secret message picture image png invisible zero width text file watermark' {
    param($panel, $st)
    foreach ($kv in (@{ Image = $null; ImageName = '' }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    # where the message goes (one panel per kind)
    $kh = New-Object System.Windows.Forms.Panel
    $kh.Dock = 'Fill'; $kh.BackColor = $C.Bg
    $panel.Controls.Add($kh)
    $st.Kinds = @{}
    # picture
    $pp = New-Object System.Windows.Forms.Panel; $pp.Dock = 'Fill'; $pp.BackColor = $C.Bg
    $st.Picture = New-Object System.Windows.Forms.PictureBox
    $st.Picture.Dock = 'Fill'; $st.Picture.SizeMode = 'Zoom'; $st.Picture.BackColor = $C.Bg; $st.Picture.AllowDrop = $true
    $st.Picture.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
    $st.Picture.add_DragDrop({ param($src, $e) $f = @([string[]]$e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]; if ($f) { Set-StegoImage $TbUI.Pages['stego'].State $f } })
    $pp.Controls.Add($st.Picture)
    $pb = New-TbBar $pp
    New-TbLabel $pb 'Picture' -Title | Out-Null
    [void](New-Button 'Open picture...' 'A PNG, JPEG, BMP ... (or drop one here). The result is always saved as PNG.' {
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Pictures|*.png;*.jpg;*.jpeg;*.bmp;*.gif;*.tif;*.tiff|All files|*.*'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { Set-StegoImage $TbUI.Pages['stego'].State $d.FileName } } finally { $script:Modal = $false; $d.Dispose() }
    } $pb $Glyph.Open 2)
    [void](New-Button 'Paste picture' 'Use the picture on the clipboard' { Set-StegoImage $TbUI.Pages['stego'].State '' -Clipboard } $pb $Glyph.Paste 2)
    [void](New-Button 'Close picture' 'Take the picture out of the tool' { Clear-StegoImage $TbUI.Pages['stego'].State } $pb $Glyph.Cancel 2)
    $st.PicInfo = New-TbLabel $pb 'Open or drop a picture.' -Dim
    $kh.Controls.Add($pp); $st.Kinds['picture'] = $pp
    # text
    $tp = New-Object System.Windows.Forms.Panel; $tp.Dock = 'Fill'; $tp.BackColor = $C.Bg; $tp.Visible = $false
    $st.Cover = New-TbBox -Multi -Cue 'The normal text people will see - the message is hidden inside it. To read a message, paste the text you received here.'
    $st.Cover.Dock = 'Fill'; $st.Cover.WordWrap = $true; $st.Cover.ScrollBars = 'Vertical'
    $tp.Controls.Add($st.Cover)
    $tb = New-TbBar $tp
    New-TbLabel $tb 'Cover text' -Title | Out-Null
    New-TbLabel $tb 'invisible characters carry the message; it survives copy and paste in most apps (chat, email, documents)' -Dim | Out-Null
    $kh.Controls.Add($tp); $st.Kinds['text'] = $tp
    # any file
    $fp = New-Object System.Windows.Forms.Panel; $fp.Dock = 'Fill'; $fp.BackColor = $C.Bg; $fp.Visible = $false; $fp.AllowDrop = $true
    $fb = New-TbBar $fp
    New-TbLabel $fb 'File' -Title | Out-Null
    $st.FilePath = New-TbBox -Cue 'any file: a picture, PDF, zip, Office document ... (or drop it here)'
    $st.FilePath.Width = Px (440 * $TextZoom); $st.FilePath.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0); $st.FilePath.AllowDrop = $true
    $fb.Controls.Add($st.FilePath)
    [void](New-Button 'Browse...' 'Pick the file' {
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'All files|*.*'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { $TbUI.Pages['stego'].State.FilePath.Text = $d.FileName } } finally { $script:Modal = $false; $d.Dispose() }
    } $fb $Glyph.Open 2)
    foreach ($ctl in $fp, $st.FilePath) {
        $ctl.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
        $ctl.add_DragDrop({ param($src, $e) $f = @([string[]]$e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]; if ($f) { $TbUI.Pages['stego'].State.FilePath.Text = $f } })
    }
    $fh = New-Object System.Windows.Forms.Label
    $fh.Dock = 'Top'; $fh.AutoSize = $false; $fh.Height = $FontMain.Height * 4; $fh.ForeColor = $C.Dim; $fh.Padding = New-Object System.Windows.Forms.Padding(0, (Px 8), 0, 0)
    $fh.Text = 'The message is added after the end of the file, so the file still opens normally (pictures show, PDFs and zips open). Anyone who looks at the raw bytes can see something was added - use a password to keep it unreadable. Hiding again replaces the earlier message.'
    $fp.Controls.Add($fh); $fh.BringToFront()
    $kh.Controls.Add($fp); $st.Kinds['file'] = $fp

    # actions
    $ab = New-TbBar $panel
    [void](New-Button 'Hide the message' 'Put the message into the picture / text / file' { Invoke-StegoHide $TbUI.Pages['stego'].State } $ab $Glyph.Lock 1)
    [void](New-Button 'Read the message' 'Find a hidden message in the picture / text / file' { Invoke-StegoReveal $TbUI.Pages['stego'].State } $ab $Glyph.View 2)
    [void](New-Button 'Remove it' 'Take a hidden message out of the text or file (pictures: open the original instead)' { Invoke-StegoRemove $TbUI.Pages['stego'].State } $ab $Glyph.Delete 2)
    New-TbLabel $ab 'Password' -Dim | Out-Null
    $st.Password = New-TbBox -Cue 'optional - encrypts it (AES-256)'
    $st.Password.UseSystemPasswordChar = $true; $st.Password.Width = Px (220 * $TextZoom); $st.Password.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $ab.Controls.Add($st.Password)
    # the secret
    $st.Secret = New-TbBox -Multi -Cue 'The secret message'
    $st.Secret.Dock = 'Top'; $st.Secret.Height = $FontMain.Height * 5; $st.Secret.WordWrap = $true; $st.Secret.ScrollBars = 'Vertical'
    $panel.Controls.Add($st.Secret)
    $st.Secret.add_TextChanged({ Update-StegoInfo $TbUI.Pages['stego'].State })
    New-TbLabel (New-TbBar $panel) 'Secret message' -Title | Out-Null
    $sb = New-TbBar $panel
    New-TbLabel $sb 'Hide in' -Dim | Out-Null
    $st.Kind = New-TbCombo $sb @('A picture (saved as PNG)', 'Normal text (invisible characters)', 'Any file (added at the end)') 270
    $st.Kind.add_SelectedIndexChanged({
        $s = $TbUI.Pages['stego'].State
        $k = @('picture', 'text', 'file')[$s.Kind.SelectedIndex]
        foreach ($n in $s.Kinds.Keys) { $s.Kinds[$n].Visible = $n -eq $k }
        Update-StegoInfo $s
    })
    $st.SetInput = { param($t) $s = $TbUI.Pages['stego'].State; if ($t -match '[\u200B\u200C\u200D\u2060]') { $s.Kind.SelectedIndex = 1; $s.Cover.Text = $t; Invoke-StegoReveal $s } else { $s.Secret.Text = $t } }
    $st.Focus = { $TbUI.Pages['stego'].State.Secret.Focus() }
    $st.Close = { $s = $TbUI.Pages['stego'].State; if ($s.Image) { $s.Picture.Image = $null; $s.Image.Dispose() } }
    Set-TbStatus $st.Status 'Write a message, pick where to hide it, then Hide the message. To read one: open the picture / paste the text / pick the file and press Read the message.'
    $st
}

function Get-StegoKind($S) { @('picture', 'text', 'file')[$S.Kind.SelectedIndex] }

function Set-StegoImage($S, [string]$Path, [switch]$Clipboard) {
    try {
        if ($Clipboard) {
            $img = [System.Windows.Forms.Clipboard]::GetImage()
            if (-not $img) { Set-TbStatus $S.Status 'There is no picture on the clipboard.' 'error'; return }
            $bmp = New-Object System.Drawing.Bitmap($img); $img.Dispose(); $name = 'pasted picture'
        } else {
            $ms = New-Object IO.MemoryStream(, [IO.File]::ReadAllBytes($Path))
            $img = [System.Drawing.Image]::FromStream($ms); $bmp = New-Object System.Drawing.Bitmap($img); $img.Dispose(); $ms.Dispose(); $name = $Path
        }
    } catch { Set-TbStatus $S.Status "Can't open that picture: $($_.Exception.Message)" 'error'; return }
    if ($S.Image) { $S.Picture.Image = $null; $S.Image.Dispose() }
    $S.Image = $bmp; $S.ImageName = $name; $S.Picture.Image = $bmp
    $S.Capacity = [DevStego]::Capacity($bmp)
    Update-StegoInfo $S
    # a picture that already carries a message says so
    $p = $null; try { $p = [DevStego]::ReadFromImage($bmp) } catch { }
    if ($p) { Set-TbStatus $S.Status "This picture has a hidden message$(if ([DevStego]::IsLocked($p)) { ' (locked with a password)' }) - press Read the message." 'ok' }
    else { Set-TbStatus $S.Status "Picture loaded. It can hold about $($S.Capacity.ToString('N0')) bytes of message." }
}

function Clear-StegoImage($S) {
    if ($S.Image) { $S.Picture.Image = $null; $S.Image.Dispose() }
    $S.Image = $null; $S.ImageName = ''; $S.Capacity = 0
    Update-StegoInfo $S
    Set-TbStatus $S.Status 'Picture closed.'
}

function Update-StegoInfo($S) {
    if (-not $S.PicInfo) { return }
    $need = [Text.Encoding]::UTF8.GetByteCount($S.Secret.Text) + 9 + $(if ($S.Password.Text) { 80 } else { 0 })
    $S.PicInfo.Text = if ($S.Image) { "$(Split-Path -Leaf $S.ImageName)  $($S.Image.Width) x $($S.Image.Height)  $Dot  room for $($S.Capacity.ToString('N0')) bytes, the message needs $need" } else { 'Open or drop a picture.' }
    $S.PicInfo.ForeColor = if ($S.Image -and $need -gt $S.Capacity + 9) { $C.Red } else { $C.Dim }
}

function Invoke-StegoHide($S) {
    $msg = $S.Secret.Text
    if (-not $msg) { Set-TbStatus $S.Status 'Write the secret message first.' 'error'; return }
    $payload = [DevStego]::Pack($msg, $S.Password.Text)
    $lock = if ($S.Password.Text) { ', locked with your password' } else { '' }
    try {
        switch (Get-StegoKind $S) {
            'picture' {
                if (-not $S.Image) { Set-TbStatus $S.Status 'Open or paste a picture first.' 'error'; return }
                $out = [DevStego]::HideInImage($S.Image, $payload)
                $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PNG picture|*.png'
                $d.FileName = if ($S.ImageName -and (Test-Path -LiteralPath $S.ImageName)) { [IO.Path]::GetFileNameWithoutExtension($S.ImageName) + '-hidden.png' } else { 'picture-hidden.png' }
                $script:Modal = $true
                try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { $out.Dispose(); return }; $path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
                $out.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
                $S.Picture.Image = $null; $S.Image.Dispose(); $S.Image = $out; $S.ImageName = $path; $S.Picture.Image = $out
                Update-StegoInfo $S
                Set-TbStatus $S.Status "Hidden$lock and saved to $(Split-Path -Leaf $path) - it looks the same. Send the PNG file itself: apps that shrink or re-save pictures (most chats, JPEG) destroy the message." 'ok'
            }
            'text' {
                $cover = [DevStego]::RemoveFromText($S.Cover.Text)
                if (-not $cover.Trim()) { Set-TbStatus $S.Status 'Write the cover text first - the normal text people will see.' 'error'; return }
                $S.Cover.Text = [DevStego]::HideInText($cover, $payload)
                Copy-TbText $S.Cover.Text
                Set-TbStatus $S.Status "Hidden$lock and copied - paste it anywhere; it looks like the cover text ($($payload.Length * 4) invisible characters inside)." 'ok'
            }
            'file' {
                $src = $S.FilePath.Text.Trim().Trim('"')
                if (-not $src -or -not (Test-Path -LiteralPath $src -PathType Leaf)) { Set-TbStatus $S.Status 'Pick a file first.' 'error'; return }
                $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'All files|*.*'
                $d.FileName = [IO.Path]::GetFileNameWithoutExtension($src) + '-hidden' + [IO.Path]::GetExtension($src)
                $d.InitialDirectory = Split-Path -Parent $src
                $script:Modal = $true
                try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { return }; $path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
                [DevStego]::AppendToFile($src, $path, $payload)
                Set-TbStatus $S.Status "Hidden$lock in $(Split-Path -Leaf $path); it still opens like the original." 'ok'
            }
        }
    } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        Set-TbStatus $S.Status $ex.Message 'error'
    }
}

function Invoke-StegoReveal($S) {
    try {
        $p = switch (Get-StegoKind $S) {
            'picture' { if (-not $S.Image) { Set-TbStatus $S.Status 'Open or paste the picture first.' 'error'; return }; [DevStego]::ReadFromImage($S.Image) }
            'text'    { [DevStego]::ReadFromText($S.Cover.Text) }
            'file'    { $f = $S.FilePath.Text.Trim().Trim('"'); if (-not $f -or -not (Test-Path -LiteralPath $f -PathType Leaf)) { Set-TbStatus $S.Status 'Pick the file first.' 'error'; return }; [DevStego]::ReadFromFile($f) }
        }
        $S.Secret.Text = [DevStego]::Unpack($p, $S.Password.Text)
        Set-TbStatus $S.Status "Found the hidden message$(if ([DevStego]::IsLocked($p)) { ' (unlocked with the password)' })." 'ok'
    } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        Set-TbStatus $S.Status $ex.Message 'error'
    }
}

function Invoke-StegoRemove($S) {
    switch (Get-StegoKind $S) {
        'text' { $S.Cover.Text = [DevStego]::RemoveFromText($S.Cover.Text); Set-TbStatus $S.Status 'Removed every invisible character from the text.' 'ok' }
        'file' {
            $f = $S.FilePath.Text.Trim().Trim('"')
            if (-not $f -or -not (Test-Path -LiteralPath $f -PathType Leaf)) { Set-TbStatus $S.Status 'Pick the file first.' 'error'; return }
            if ([System.Windows.Forms.MessageBox]::Show($TbUI.Form, "Remove the hidden message from $(Split-Path -Leaf $f)? The file is changed in place.", 'Hide secret messages', 'YesNo', 'Question') -ne 'Yes') { return }
            try { [DevStego]::RemoveFromFile($f); Set-TbStatus $S.Status 'Removed - the file is back to how it was.' 'ok' } catch { Set-TbStatus $S.Status $_.Exception.Message 'error' }
        }
        default { Set-TbStatus $S.Status 'A picture''s message is part of its pixels - open the original picture instead (or hide a new message over it).' }
    }
}

# ======================================================================================
# Log viewer: follow a log file as it grows, filter and colour its lines.
# ======================================================================================
Register-ToolboxPage 'log' 'Log viewer' $Glyph.Document 'log tail follow watch file errors filter grep live' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $v = New-Object DevLogView
    $v.Dock = 'Fill'; $v.UiScale = $Scale; $v.Font = New-Object System.Drawing.Font('Consolas', (Fz 10)); $v.AllowDrop = $true
    $v.Back = $C.Bg; $v.Fore = $C.Fore; $v.Dim = $C.Dim; $v.Red = $C.Red; $v.Yellow = $C.Yellow; $v.Accent = $C.Accent; $v.Sel = $C.Sel
    $v.Mark = [PowerClipTheme]::Mix($C.Bg, $C.Yellow, 0.35)
    $v.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
    $v.add_DragDrop({ param($src, $e) $f = @([string[]]$e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]; if ($f) { Open-LogFile $TbUI.Pages['log'].State $f } })
    $v.add_Changed({ Update-LogStatus $TbUI.Pages['log'].State })
    $panel.Controls.Add($v)
    $st.View = $v
    $fb = New-TbBar $panel
    New-TbLabel $fb 'Filter' -Dim | Out-Null
    $st.Filter = New-TbBox -Mono -Cue 'text to look for (e.g. error, user=42, timeout)'
    $st.Filter.Width = Px (300 * $TextZoom); $st.Filter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $fb.Controls.Add($st.Filter)
    $st.Regex = New-CheckBox $fb 'Regex' $false
    $st.Invert = New-CheckBox $fb 'Hide matching lines' $false
    foreach ($ctl in $st.Regex, $st.Invert) { $ctl.add_CheckedChanged({ $s = $TbUI.Pages['log'].State; $s.View.SetFilter($s.Filter.Text, $s.Regex.Checked, $s.Invert.Checked) }) }
    $st.FilterTimer = New-TbDebounce 250 { $s = $TbUI.Pages['log'].State; $s.View.SetFilter($s.Filter.Text, $s.Regex.Checked, $s.Invert.Checked) }
    $st.Filter.add_TextChanged({ $s = $TbUI.Pages['log'].State; $s.FilterTimer.Stop(); $s.FilterTimer.Start() })
    foreach ($q in @(@('Errors', 'error|fatal|exception|fail'), @('Warnings', 'warn'))) {
        $b = New-Button $q[0] "Show only lines with: $($q[1])" { param($src, $e) $s = $TbUI.Pages['log'].State; $s.Regex.Checked = $true; $s.Invert.Checked = $false; $s.Filter.Text = $src.Tag } $fb '' 2
        $b.Tag = $q[1]
    }
    $bar = New-TbBar $panel
    [void](New-Button 'Open log...' 'Open a log file (or drop one on the list)' {
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Logs|*.log;*.txt;*.out;*.err;*.json;*.csv|All files|*.*'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { Open-LogFile $TbUI.Pages['log'].State $d.FileName } } finally { $script:Modal = $false; $d.Dispose() }
    } $bar $Glyph.Open 1)
    $st.Follow = New-CheckBox $bar 'Follow new lines' $true
    $st.Follow.add_CheckedChanged({ $s = $TbUI.Pages['log'].State; if ($s.Follow.Checked) { $s.View.GoToEnd() } else { $s.View.Follow = $false } })
    [void](New-Button 'Clear' 'Empty the list (the file is not changed); new lines keep coming' { $TbUI.Pages['log'].State.View.Clear() } $bar $Glyph.Clear 2)
    [void](New-Button 'Copy' 'Copy the selected lines, or every shown line' { $s = $TbUI.Pages['log'].State; $t = $s.View.SelectedText(); if (-not $t) { $t = $s.View.ShownText() }; Copy-TbText $t } $bar $Glyph.Copy 2)
    [void](New-Button 'Show in Explorer' 'Open the folder of the log' { $s = $TbUI.Pages['log'].State; if ($s.View.FilePath) { Start-Process explorer.exe "/select,`"$($s.View.FilePath)`"" } } $bar $Glyph.Folder 2)
    $st.Path = New-TbLabel $bar '' -Dim
    $st.Timer = New-Object System.Windows.Forms.Timer
    $st.Timer.Interval = 500
    $st.Timer.add_Tick({
        $s = $TbUI.Pages['log'].State
        if (-not $s -or -not $s.View.FilePath) { return }
        $n = $s.View.Poll()
        if ($s.Follow.Checked -ne $s.View.Follow) { $s.Follow.Checked = $s.View.Follow }
        if ($n -lt 0) { Set-TbStatus $s.Status 'The file got shorter (rotated or emptied) - read it again from the start.' 'warn' }
    })
    $st.Timer.Start()
    $st.Close = { $s = $TbUI.Pages['log'].State; $s.Timer.Stop(); $s.Timer.Dispose() }
    $st.SetInput = { param($t) $p = $t.Trim().Trim('"'); if ($p -and (Test-Path -LiteralPath $p -PathType Leaf)) { Open-LogFile $TbUI.Pages['log'].State $p } else { $TbUI.Pages['log'].State.Filter.Text = $t } }
    $st.Focus = { $TbUI.Pages['log'].State.View.Focus() }
    Set-TbStatus $st.Status 'Open or drop a log file. New lines show up as they are written; ERROR lines are red, WARN yellow, DEBUG grey. Click / Shift+click lines, Ctrl+C copies.'
    $st
}

function Open-LogFile($S, [string]$Path) {
    try { $note = $S.View.Open($Path, 16MB) } catch { Set-TbStatus $S.Status "Can't open: $($_.Exception.Message)" 'error'; return }
    $S.Path.Text = $Path
    $S.Follow.Checked = $true
    Update-LogStatus $S
    if ($note) { Set-TbStatus $S.Status "Big file - $note. New lines keep coming." 'warn' }
}

function Update-LogStatus($S) {
    $v = $S.View
    if (-not $v.FilePath) { return }
    $size = try { (Get-Item -LiteralPath $v.FilePath).Length } catch { 0 }
    $txt = "$($v.LineCount.ToString('N0')) lines$(if ($v.Filter) { "  $Dot  $($v.ShownCount.ToString('N0')) shown" })  $Dot  $([Math]::Round($size / 1KB).ToString('N0')) KB  $Dot  $(if ($v.Follow) { 'following new lines' } else { 'paused - End or Follow to continue' })"
    if ($v.FilterError) { Set-TbStatus $S.Status "Filter: $($v.FilterError)" 'error' } else { Set-TbStatus $S.Status $txt 'ok' }
}

# ======================================================================================
# Subnet calculator: ranges, masks and host counts for IPv4 and IPv6, splitting, "is this IP inside?".
# ======================================================================================
Register-ToolboxPage 'subnet' 'Subnet calculator' $Glyph.Network 'subnet cidr netmask ip range network calculator ipv4 ipv6 broadcast hosts' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Out = New-TbRtb -ReadOnly; $st.Out.Dock = 'Fill'; $st.Out.Font = New-Object System.Drawing.Font('Consolas', (Fz 11))
    $panel.Controls.Add($st.Out)
    $b2 = New-TbBar $panel
    New-TbLabel $b2 'Split into' -Dim | Out-Null
    $st.Split = New-TbCombo $b2 @('(don''t split)') 140
    New-TbLabel $b2 'Is this address inside?' -Dim | Out-Null
    $st.Check = New-TbBox -Mono -Cue '10.0.3.200'
    $st.Check.Width = Px (200 * $TextZoom); $st.Check.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $b2.Controls.Add($st.Check)
    $st.CheckOut = New-TbLabel $b2 '' -Dim
    $b1 = New-TbBar $panel
    New-TbLabel $b1 'Network' -Title | Out-Null
    $st.Input = New-TbBox -Mono -Cue '192.168.1.10/24   10.0.0.0 255.255.252.0   2001:db8::/48'
    $st.Input.Width = Px (360 * $TextZoom); $st.Input.Font = New-Object System.Drawing.Font('Consolas', (Fz 12)); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 2), (Px 10), 0)
    $b1.Controls.Add($st.Input)
    [void](New-Button 'Copy' 'Copy the result' { Copy-TbText $TbUI.Pages['subnet'].State.Out.Text } $b1 $Glyph.Copy 2)
    $st.Input.add_TextChanged({ Update-SubnetTool $TbUI.Pages['subnet'].State -NewInput })
    $st.Split.add_SelectedIndexChanged({ $s = $TbUI.Pages['subnet'].State; if (-not $s.Busy) { Update-SubnetTool $s } })
    $st.Check.add_TextChanged({ Update-SubnetTool $TbUI.Pages['subnet'].State })
    $st.SetInput = { param($t) $TbUI.Pages['subnet'].State.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['subnet'].State.Input.Focus() }
    $st.Input.Text = '192.168.1.10/24'
    $st
}

function Update-SubnetTool($S, [switch]$NewInput) {
    $t = $S.Input.Text.Trim()
    if (-not $t) { $S.Out.Text = ''; Set-TbStatus $S.Status 'Type a network, e.g. 10.0.0.0/22'; return }
    try { $txt = [DevSubnet]::Describe($t) } catch { $S.Out.Text = ''; $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }; Set-TbStatus $S.Status $ex.Message 'error'; return }
    $p = [DevSubnet]::PrefixOf($t); $bits = [DevSubnet]::BitsOf($t)
    if ($NewInput) {                      # split choices: the next prefixes down
        $S.Busy = $true
        try {
            $keep = [string]$S.Split.SelectedItem
            $S.Split.Items.Clear(); [void]$S.Split.Items.Add('(don''t split)')
            for ($n = $p + 1; $n -le [Math]::Min($bits, $p + 12); $n++) { [void]$S.Split.Items.Add("/$n  ($([Math]::Pow(2, $n - $p)) networks)") }
            $i = [Math]::Max(0, $S.Split.Items.IndexOf($keep)); $S.Split.SelectedIndex = $i
        } finally { $S.Busy = $false }
    }
    if ($S.Split.SelectedIndex -gt 0) {
        $np = $p + $S.Split.SelectedIndex
        $txt += "`r`nSplit into /$($np):`r`n" + ([DevSubnet]::Split($t, $np, 256) -join "`r`n")
    }
    $S.Out.Text = $txt
    $chk = $S.Check.Text.Trim()
    if ($chk) {
        $r = [DevSubnet]::Contains($t, $chk)
        $S.CheckOut.Text = switch ($r) { 1 { 'yes, inside' } 0 { 'no, outside' } default { '(not an address of the same kind)' } }
        $S.CheckOut.ForeColor = switch ($r) { 1 { $C.Green } 0 { $C.Red } default { $C.Dim } }
    } else { $S.CheckOut.Text = '' }
    Set-TbStatus $S.Status 'Also accepts a mask (10.0.0.0 255.255.252.0) or a single address (shown as /32 or /128).' 'ok'
}

# ======================================================================================
# DNS lookup: any record type from any DNS server, plus whois.
# ======================================================================================
Register-ToolboxPage 'dns' 'DNS lookup & whois' $Glyph.Globe 'dns nslookup dig record mx txt cname ns soa srv ptr caa whois domain registrar' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $tabs = New-TabSet $panel
    $rp = Add-ApiTab $tabs 'Records'; $wp = Add-ApiTab $tabs 'Whois'
    $st.Tabs = $tabs
    $st.List = New-Object System.Windows.Forms.ListView
    $st.List.Dock = 'Fill'; $st.List.View = 'Details'; $st.List.FullRowSelect = $true; $st.List.BorderStyle = 'None'; $st.List.BackColor = $C.Bg; $st.List.ForeColor = $C.Fore
    $st.List.Font = New-Object System.Drawing.Font('Consolas', (Fz 10))
    foreach ($col in @(@('Type', 70), @('Name', 260), @('TTL', 70), @('Value', 640))) { [void]$st.List.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $st.List.add_KeyDown({ param($src, $e) if ($e.Control -and $e.KeyCode -eq 'C') { Copy-TbText ((@($src.SelectedItems) | ForEach-Object { $_.SubItems[3].Text }) -join "`r`n"); $e.Handled = $true } })
    $rp.Controls.Add($st.List)
    $st.Whois = New-TbRtb -ReadOnly; $st.Whois.Dock = 'Fill'
    $wp.Controls.Add($st.Whois)
    Select-ApiTab $tabs 'Records'
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Name' -Title | Out-Null
    $st.Name = New-TbBox -Mono -Cue 'example.com   or an IP for its name (PTR)'
    $st.Name.Width = Px (300 * $TextZoom); $st.Name.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $bar.Controls.Add($st.Name)
    $st.Type = New-TbCombo $bar @('All common', 'A', 'AAAA', 'CNAME', 'MX', 'TXT', 'NS', 'SOA', 'SRV', 'PTR', 'CAA') 110
    New-TbLabel $bar 'Server' -Dim | Out-Null
    $st.Server = New-TbCombo $bar @('This PC''s DNS', '1.1.1.1  Cloudflare', '8.8.8.8  Google', '9.9.9.9  Quad9') 170
    $st.Server.DropDownStyle = 'DropDown'
    [void](New-Button 'Look up' 'Ask the DNS server (Enter)' { Start-DnsLookup $TbUI.Pages['dns'].State } $bar $Glyph.Search 1)
    [void](New-Button 'Whois' 'Who owns the domain or IP (registrar, dates, name servers)' { Start-Whois $TbUI.Pages['dns'].State } $bar $Glyph.View 2)
    $st.Name.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Start-DnsLookup $TbUI.Pages['dns'].State; $e.SuppressKeyPress = $true } })
    $st.Timer = New-Object System.Windows.Forms.Timer; $st.Timer.Interval = 150
    $st.Timer.add_Tick({ Update-DnsJob $TbUI.Pages['dns'].State })
    $st.Close = { $s = $TbUI.Pages['dns'].State; $s.Timer.Stop(); $s.Timer.Dispose(); if ($s.Job) { try { $s.Job.PS.Stop() } catch { } } }
    $st.SetInput = { param($t) $s = $TbUI.Pages['dns'].State; $s.Name.Text = ($t.Trim() -replace '^\w+://', '' -replace '[/:].*$', ''); Start-DnsLookup $s }
    $st.Focus = { $TbUI.Pages['dns'].State.Name.Focus() }
    Set-TbStatus $st.Status 'Type a domain and press Enter. Any record type, from this PC''s DNS or a public one (type another server''s IP in the box).'
    $st
}

# Runs a script in the background (its own runspace) so the window doesn't freeze; Update-DnsJob collects it.
function Start-TbJob($S, [string]$Kind, [scriptblock]$Script, [object[]]$Arguments) {
    if ($S.Job) { try { $S.Job.PS.Stop() } catch { } }
    $ps = [PowerShell]::Create()
    [void]$ps.AddScript($Script.ToString())
    foreach ($a in $Arguments) { [void]$ps.AddArgument($a) }
    $S.Job = @{ PS = $ps; Handle = $ps.BeginInvoke(); Kind = $Kind; Started = Get-Date }
    $S.Timer.Start()
}

function Start-DnsLookup($S) {
    $name = $S.Name.Text.Trim() -replace '^\w+://', '' -replace '/.*$', ''
    if (-not $name) { Set-TbStatus $S.Status 'Type a domain name first.' 'error'; return }
    $type = [string]$S.Type.SelectedItem
    $ip = $null
    if ([System.Net.IPAddress]::TryParse($name, [ref]$ip)) { $type = 'PTR' }
    $types = if ($type -eq 'All common') { @('A', 'AAAA', 'CNAME', 'MX', 'TXT', 'NS', 'SOA', 'CAA') } else { @($type) }
    $server = ([string]$S.Server.Text -split '\s+')[0]
    if ($server -notmatch '^[\d.:a-fA-F]+$') { $server = '' }
    $S.List.Items.Clear()
    Select-ApiTab $S.Tabs 'Records'
    Set-TbStatus $S.Status "Looking up $name ..."
    Start-TbJob $S 'dns' {
        param($name, $types, $server)
        foreach ($t in $types) {
            try {
                $args2 = @{ Name = $name; Type = $t; DnsOnly = $true; ErrorAction = 'Stop'; QuickTimeout = $true }
                if ($server) { $args2.Server = $server }
                foreach ($r in @(Resolve-DnsName @args2 | Where-Object { $_.Section -eq 'Answer' })) {
                    $data = switch ([string]$r.Type) {
                        'A' { $r.IPAddress } 'AAAA' { $r.IPAddress } 'CNAME' { $r.NameHost } 'NS' { $r.NameHost } 'PTR' { $r.NameHost }
                        'MX' { "$($r.Preference)  $($r.NameExchange)" } 'TXT' { ($r.Strings -join '') }
                        'SOA' { "$($r.PrimaryServer)  $($r.NameAdministrator)  serial $($r.SerialNumber)  refresh $($r.TimeToZoneRefresh)" }
                        'SRV' { "$($r.Priority) $($r.Weight) $($r.Port)  $($r.NameTarget)" }
                        default { (($r | Select-Object * -ExcludeProperty Name, Type, TTL, Section, CharacterSet, DataLength, QueryType | Format-List | Out-String).Trim() -replace '\s*\r?\n\s*', '  ') }
                    }
                    [pscustomobject]@{ Type = [string]$r.Type; Name = [string]$r.Name; TTL = [string]$r.TTL; Data = [string]$data }
                }
            } catch {
                $m = $_.Exception.Message
                if ($m -notmatch 'DNS name does not exist|No records|record (does not|doesn.t) exist|9501') { [pscustomobject]@{ Type = $t; Name = $name; TTL = ''; Data = "($m)" } }
            }
        }
    } @($name, $types, $server)
}

function Start-Whois($S) {
    $q = $S.Name.Text.Trim() -replace '^\w+://', '' -replace '/.*$', '' -replace '^www\.', ''
    if (-not $q) { Set-TbStatus $S.Status 'Type a domain or IP first.' 'error'; return }
    Select-ApiTab $S.Tabs 'Whois'
    $S.Whois.Text = "Asking whois about $q ..."
    Set-TbStatus $S.Status "Whois $q ..."
    Start-TbJob $S 'whois' { param($q) [DevWhois]::Query($q) } @($q)
}

function Update-DnsJob($S) {
    $j = $S.Job
    if (-not $j) { $S.Timer.Stop(); return }
    if (-not $j.Handle.IsCompleted) {
        if (((Get-Date) - $j.Started).TotalSeconds -gt 30) { try { $j.PS.Stop() } catch { }; $S.Job = $null; $S.Timer.Stop(); Set-TbStatus $S.Status 'No answer after 30 seconds.' 'error' }
        return
    }
    $S.Timer.Stop(); $S.Job = $null
    try { $out = @($j.PS.EndInvoke($j.Handle)) } catch { $out = @(); $err = $_.Exception.Message }
    $errs = @($j.PS.Streams.Error | ForEach-Object { $_.Exception.Message })
    $j.PS.Dispose()
    if ($j.Kind -eq 'whois') {
        $S.Whois.Text = if ($out) { ($out -join "`n") -replace "`r?`n", "`r`n" } else { "Whois failed: $err $($errs -join ' ')" }
        Set-TbStatus $S.Status $(if ($out) { 'Whois answer below (registrar, dates, name servers ...).' } else { 'Whois failed (port 43 blocked?).' }) $(if ($out) { 'ok' } else { 'error' })
        return
    }
    $S.List.BeginUpdate()
    foreach ($r in $out) {
        $it = New-Object System.Windows.Forms.ListViewItem([string]$r.Type)
        [void]$it.SubItems.Add([string]$r.Name); [void]$it.SubItems.Add([string]$r.TTL); [void]$it.SubItems.Add([string]$r.Data)
        if ($r.Data -like '(*') { $it.ForeColor = $C.Red }
        [void]$S.List.Items.Add($it)
    }
    $S.List.EndUpdate()
    $n = @($out | Where-Object { $_.Data -notlike '(*' }).Count
    if ($errs -and -not $out) { Set-TbStatus $S.Status "Lookup failed: $($errs[0])" 'error' }
    else { Set-TbStatus $S.Status "$n record(s). Select rows and press Ctrl+C to copy their values." $(if ($n) { 'ok' } else { 'warn' }) }
}

$CertToolSource = @'
using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;

// Certificates: make a self-signed certificate or a signing request (CSR), read any certificate file
// (PEM, DER/CER, PFX) and write it out in another format. Needs .NET Framework 4.7.2+ (CertificateRequest).
public class DevCertResult {
    public X509Certificate2 Cert;
    public string CertPem = "", KeyPem = "", CsrPem = "";
}

public static class DevCertTool {
    public static string Pem(string label, byte[] der) {
        var b64 = Convert.ToBase64String(der);
        var sb = new StringBuilder("-----BEGIN " + label + "-----\n");
        for (int i = 0; i < b64.Length; i += 64) sb.Append(b64.Substring(i, Math.Min(64, b64.Length - i))).Append('\n');
        return sb.Append("-----END " + label + "-----\n").ToString();
    }

    // kind: 0 RSA 2048, 1 RSA 4096, 2 ECDSA P-256, 3 ECDSA P-384
    static object NewKey(int kind) {
        if (kind <= 1) return new RSACng(kind == 0 ? 2048 : 4096);
        return ECDsa.Create(kind == 2 ? ECCurve.NamedCurves.nistP256 : ECCurve.NamedCurves.nistP384);
    }
    static CertificateRequest Request(string subject, object key) {
        var dn = new X500DistinguishedName(subject.Contains("=") ? subject : "CN=" + subject);
        var rsa = key as RSA;
        return rsa != null ? new CertificateRequest(dn, rsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1) : new CertificateRequest(dn, (ECDsa)key, HashAlgorithmName.SHA256);
    }
    static void AddExtensions(CertificateRequest req, string[] dns, string[] ips, bool ca) {
        var san = new SubjectAlternativeNameBuilder(); bool any = false;
        foreach (var d in dns ?? new string[0]) if (!string.IsNullOrWhiteSpace(d)) { san.AddDnsName(d.Trim()); any = true; }
        foreach (var i in ips ?? new string[0]) { System.Net.IPAddress ip; if (System.Net.IPAddress.TryParse((i ?? "").Trim(), out ip)) { san.AddIpAddress(ip); any = true; } }
        if (any) req.CertificateExtensions.Add(san.Build());
        req.CertificateExtensions.Add(new X509BasicConstraintsExtension(ca, false, 0, true));
        req.CertificateExtensions.Add(new X509KeyUsageExtension(ca ? X509KeyUsageFlags.KeyCertSign | X509KeyUsageFlags.CrlSign | X509KeyUsageFlags.DigitalSignature
                                                                   : X509KeyUsageFlags.DigitalSignature | X509KeyUsageFlags.KeyEncipherment, true));
        if (!ca) req.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(new OidCollection { new Oid("1.3.6.1.5.5.7.3.1"), new Oid("1.3.6.1.5.5.7.3.2") }, false));
        req.CertificateExtensions.Add(new X509SubjectKeyIdentifierExtension(req.PublicKey, false));
    }

    public static DevCertResult SelfSigned(string subject, string[] dns, string[] ips, int kind, int days, bool ca) {
        var key = NewKey(kind);
        var req = Request(subject, key);
        AddExtensions(req, dns, ips, ca);
        var now = DateTimeOffset.UtcNow.AddMinutes(-5);
        var cert = req.CreateSelfSigned(now, now.AddDays(days));
        return new DevCertResult { Cert = cert, CertPem = Pem("CERTIFICATE", cert.RawData), KeyPem = KeyToPem(key) };
    }
    public static DevCertResult Csr(string subject, string[] dns, string[] ips, int kind) {
        var key = NewKey(kind);
        var req = Request(subject, key);
        AddExtensions(req, dns, ips, false);
        return new DevCertResult { CsrPem = Pem("CERTIFICATE REQUEST", req.CreateSigningRequest()), KeyPem = KeyToPem(key) };
    }

    // ---- private keys as PEM (RSA: PKCS#1, EC: SEC1) - .NET Framework has no exporter for these
    static string KeyToPem(object key) {
        var rsa = key as RSA;
        if (rsa != null) {
            var p = rsa.ExportParameters(true);
            var seq = Der(0x30, Concat(Int(new byte[] { 0 }), Int(p.Modulus), Int(p.Exponent), Int(p.D), Int(p.P), Int(p.Q), Int(p.DP), Int(p.DQ), Int(p.InverseQ)));
            return Pem("RSA PRIVATE KEY", seq);
        }
        var ec = (ECDsa)key;
        var e = ec.ExportParameters(true);
        string oid = e.Curve.Oid.Value ?? (e.D.Length == 32 ? "1.2.840.10045.3.1.7" : "1.3.132.0.34");
        var pub = new byte[1 + e.Q.X.Length + e.Q.Y.Length]; pub[0] = 4; e.Q.X.CopyTo(pub, 1); e.Q.Y.CopyTo(pub, 1 + e.Q.X.Length);
        var bits = new byte[pub.Length + 1]; pub.CopyTo(bits, 1);
        var body = Concat(Int(new byte[] { 1 }), Der(0x04, e.D), Der(0xA0, OidDer(oid)), Der(0xA1, Der(0x03, bits)));
        return Pem("EC PRIVATE KEY", Der(0x30, body));
    }
    static byte[] Concat(params byte[][] parts) { var r = new List<byte>(); foreach (var p in parts) r.AddRange(p); return r.ToArray(); }
    static byte[] Der(byte tag, byte[] content) {
        var r = new List<byte> { tag };
        int n = content.Length;
        if (n < 128) r.Add((byte)n);
        else { var lb = new List<byte>(); while (n > 0) { lb.Insert(0, (byte)(n & 255)); n >>= 8; } r.Add((byte)(0x80 | lb.Count)); r.AddRange(lb); }
        r.AddRange(content);
        return r.ToArray();
    }
    static byte[] Int(byte[] v) {
        int i = 0; while (i < v.Length - 1 && v[i] == 0) i++;
        var t = v.Skip(i).ToList();
        if ((t[0] & 0x80) != 0) t.Insert(0, 0);
        return Der(0x02, t.ToArray());
    }
    static byte[] OidDer(string oid) {
        var parts = oid.Split('.').Select(long.Parse).ToArray();
        var r = new List<byte> { (byte)(parts[0] * 40 + parts[1]) };
        for (int i = 2; i < parts.Length; i++) {
            long v = parts[i]; var st = new Stack<byte>(); st.Push((byte)(v & 0x7F)); v >>= 7;
            while (v > 0) { st.Push((byte)(0x80 | (v & 0x7F))); v >>= 7; }
            r.AddRange(st);
        }
        return Der(0x06, r.ToArray());
    }

    // ---- reading: PEM text (first certificate), DER / CER, PFX (with password)
    public static X509Certificate2 Load(string path, string password) {
        var bytes = System.IO.File.ReadAllBytes(path);
        var text = Encoding.ASCII.GetString(bytes);
        var m = System.Text.RegularExpressions.Regex.Match(text, "-----BEGIN CERTIFICATE-----([A-Za-z0-9+/=\\s]+)-----END CERTIFICATE-----");
        if (m.Success) return new X509Certificate2(Convert.FromBase64String(m.Groups[1].Value));
        if (text.Contains("-----BEGIN")) throw new Exception("This PEM file has no certificate in it (a key or a CSR?).");
        return new X509Certificate2(bytes, password ?? "", X509KeyStorageFlags.Exportable | X509KeyStorageFlags.EphemeralKeySet);
    }
    public static string Describe(X509Certificate2 c) {
        var sb = new StringBuilder();
        Action<string, string> row = (k, v) => sb.AppendLine(k.PadRight(28) + v);
        row("Subject", c.Subject);
        row("Issuer", c.Issuer + (c.Subject == c.Issuer ? "   (self-signed)" : ""));
        var left = (c.NotAfter - DateTime.Now).TotalDays;
        row("Valid", c.NotBefore.ToString("yyyy-MM-dd HH:mm") + "  to  " + c.NotAfter.ToString("yyyy-MM-dd HH:mm") + "   (" + (left < 0 ? "EXPIRED " + (int)-left + " days ago" : (int)left + " days left") + ")");
        row("Serial number", c.SerialNumber);
        row("Key", KeyText(c));
        row("Signature", c.SignatureAlgorithm.FriendlyName);
        row("SHA-1", c.Thumbprint);
        using (var sha = SHA256.Create()) row("SHA-256", BitConverter.ToString(sha.ComputeHash(c.RawData)).Replace("-", ""));
        row("Private key", c.HasPrivateKey ? "included" : "not included");
        foreach (var ext in c.Extensions) {
            string name = ext.Oid.FriendlyName ?? ext.Oid.Value;
            string val; try { val = ext.Format(false); } catch { val = "(can't show)"; }
            row(name, val);
        }
        return sb.ToString();
    }
    static string KeyText(X509Certificate2 c) {
        try { var r = c.GetRSAPublicKey(); if (r != null) return "RSA " + r.KeySize + " bits"; } catch { }
        try { var e = c.GetECDsaPublicKey(); if (e != null) return "ECDSA " + e.KeySize + " bits"; } catch { }
        return c.PublicKey.Oid.FriendlyName;
    }
    // format: pem, cer (DER), pfx (with the private key when there is one)
    public static byte[] Export(X509Certificate2 c, string format, string password) {
        switch (format) {
            case "pem": return Encoding.ASCII.GetBytes(Pem("CERTIFICATE", c.RawData));
            case "cer": return c.RawData;
            default: return c.Export(X509ContentType.Pfx, password ?? "");
        }
    }
}
'@

# ======================================================================================
# Certificate maker: self-signed certificates (also CAs), signing requests (CSR), open and convert PEM / CER / PFX.
# ======================================================================================
Register-ToolboxPage 'certmake' 'Certificate maker' $Glyph.Lock 'certificate self-signed csr pem pfx p12 cer der convert ssl tls https localhost key openssl' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    if (-not ('DevCertTool' -as [type])) {           # compiled the first time it's needed (needs .NET 4.7.2+)
        try { Add-Type -ReferencedAssemblies System.Core, System.Security -TypeDefinition $CertToolSource -ErrorAction Stop } catch { Write-Log "certificate maker: $_" }
    }
    if (-not ('DevCertTool' -as [type])) { Set-TbStatus $st.Status 'This needs .NET Framework 4.7.2 or newer (Windows 10 1803+ has it).' 'error'; return $st }
    $tabs = New-TabSet $panel
    $mk = Add-ApiTab $tabs 'Make'; $op = Add-ApiTab $tabs 'Open / convert'
    # make
    $st.MakeOut = New-TbRtb -ReadOnly; $st.MakeOut.Dock = 'Fill'
    $mk.Controls.Add($st.MakeOut)
    $ab = New-TbBar $mk
    [void](New-Button 'Make a self-signed certificate' 'Certificate + private key, ready for a local HTTPS server' { Invoke-CertMake $TbUI.Pages['certmake'].State $false } $ab $Glyph.Lock 1)
    [void](New-Button 'Make a signing request (CSR)' 'A CSR to send to a certificate authority, plus its private key' { Invoke-CertMake $TbUI.Pages['certmake'].State $true } $ab $Glyph.Send 2)
    [void](New-Button 'Save files...' 'Save the certificate (.crt), key (.key), PFX and CSR into a folder' { Save-CertFiles $TbUI.Pages['certmake'].State } $ab $Glyph.Save 2)
    $fb = New-TbBar $mk
    $fld = { param($label, $cue, $w) New-TbLabel $fb $label -Dim | Out-Null; $b = New-TbBox -Cue $cue; $b.Width = Px ($w * $TextZoom); $b.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 10), 0); $fb.Controls.Add($b); $b }
    $st.Cn = & $fld 'Name (CN)' 'localhost' 160
    $st.Dns = & $fld 'Other names' 'localhost, *.dev.local' 200
    $st.Ips = & $fld 'IPs' '127.0.0.1, ::1' 130
    $fb2 = New-TbBar $mk
    New-TbLabel $fb2 'Key' -Dim | Out-Null
    $st.Key = New-TbCombo $fb2 @('RSA 2048', 'RSA 4096', 'ECDSA P-256', 'ECDSA P-384') 130
    New-TbLabel $fb2 'Valid for (days)' -Dim | Out-Null
    $st.Days = New-SettingsNumber 825 1 36500 0 { }
    $st.Days.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 10), 0)
    $fb2.Controls.Add($st.Days)
    $st.Ca = New-CheckBox $fb2 'Certificate authority (to sign others)' $false
    New-TbLabel $fb2 'PFX password' -Dim | Out-Null
    $st.PfxPw = New-TbBox -Cue 'for the .pfx file'; $st.PfxPw.UseSystemPasswordChar = $true; $st.PfxPw.Width = Px (140 * $TextZoom); $st.PfxPw.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $fb2.Controls.Add($st.PfxPw)
    # open / convert
    $st.OpenOut = New-TbRtb -ReadOnly; $st.OpenOut.Dock = 'Fill'
    $op.Controls.Add($st.OpenOut)
    $ob = New-TbBar $op
    [void](New-Button 'Open certificate...' 'A .pem / .crt / .cer / .der / .pfx / .p12 file (or drop it here)' {
        $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Filter = 'Certificates|*.pem;*.crt;*.cer;*.der;*.pfx;*.p12|All files|*.*'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { Open-CertFile $TbUI.Pages['certmake'].State $d.FileName } } finally { $script:Modal = $false; $d.Dispose() }
    } $ob $Glyph.Open 1)
    New-TbLabel $ob 'Password' -Dim | Out-Null
    $st.OpenPw = New-TbBox -Cue 'for a .pfx'; $st.OpenPw.UseSystemPasswordChar = $true; $st.OpenPw.Width = Px (130 * $TextZoom); $st.OpenPw.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $ob.Controls.Add($st.OpenPw)
    foreach ($fmt in @(@('pem', 'Save as PEM...', 'Text, starts with -----BEGIN CERTIFICATE----- (.pem / .crt)'), @('cer', 'Save as CER...', 'Binary DER (.cer / .der), what Windows double-clicks'), @('pfx', 'Save as PFX...', 'With the private key when the file had one (.pfx / .p12)'))) {
        $b = New-Button $fmt[1] $fmt[2] { param($src, $e) Save-CertAs $TbUI.Pages['certmake'].State $src.Tag } $ob $Glyph.Save 2
        $b.Tag = $fmt[0]
    }
    $st.OpenOut.AllowDrop = $true
    $st.OpenOut.add_DragEnter({ param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } })
    $st.OpenOut.add_DragDrop({ param($src, $e) $f = @([string[]]$e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]; if ($f) { Open-CertFile $TbUI.Pages['certmake'].State $f } })
    $st.Tabs = $tabs
    Select-ApiTab $tabs 'Make'
    $st.Cn.Text = 'localhost'; $st.Dns.Text = 'localhost'; $st.Ips.Text = '127.0.0.1, ::1'
    Set-TbStatus $st.Status 'Make a certificate for local HTTPS, a CA, or a CSR - or open one to see what''s inside and convert it. Keys are made on this PC and never leave it.'
    $st
}

function Invoke-CertMake($S, [bool]$Csr) {
    $cn = $S.Cn.Text.Trim(); if (-not $cn) { $cn = 'localhost' }
    $dns = @($S.Dns.Text -split '[,;\s]+' | Where-Object { $_ }); $ips = @($S.Ips.Text -split '[,;\s]+' | Where-Object { $_ })
    try {
        $r = if ($Csr) { [DevCertTool]::Csr($cn, [string[]]$dns, [string[]]$ips, $S.Key.SelectedIndex) } else { [DevCertTool]::SelfSigned($cn, [string[]]$dns, [string[]]$ips, $S.Key.SelectedIndex, [int]$S.Days.Value, $S.Ca.Checked) }
    } catch { $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }; Set-TbStatus $S.Status $ex.Message 'error'; return }
    $S.Made = $r; $S.MadeName = ($cn -replace '^CN=', '' -replace '[\\/:*?"<>|, =]', '_')
    $o = $S.MakeOut; $o.Clear()
    if ($Csr) {
        Add-RtbLine $o 'Signing request - send this to your certificate authority:' $C.Accent -Bold
        Add-RtbLine $o $r.CsrPem.TrimEnd() $C.Fore
    } else {
        Add-RtbLine $o 'Certificate' $C.Accent -Bold
        Add-RtbLine $o ([DevCertTool]::Describe($r.Cert)).TrimEnd() $C.Fore
        Add-RtbLine $o '' ; Add-RtbLine $o $r.CertPem.TrimEnd() $C.Dim
    }
    Add-RtbLine $o ''
    Add-RtbLine $o 'Private key - keep it secret' $C.Red -Bold
    Add-RtbLine $o $r.KeyPem.TrimEnd() $C.Dim
    Set-TbStatus $S.Status "$(if ($Csr) { 'CSR' } else { 'Certificate' }) made. Save files... writes $($S.MadeName).$(if ($Csr) { 'csr' } else { 'crt, .pfx' }) and .key; select text here to copy one part." 'ok'
}

function Save-CertFiles($S) {
    if (-not $S.Made) { Set-TbStatus $S.Status 'Make a certificate or CSR first.' 'error'; return }
    $d = New-Object System.Windows.Forms.FolderBrowserDialog; $d.Description = 'Folder for the certificate files'
    $script:Modal = $true
    try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { return }; $dir = $d.SelectedPath } finally { $script:Modal = $false; $d.Dispose() }
    $n = Join-Path $dir $S.MadeName; $written = @()
    $enc = New-Object System.Text.UTF8Encoding $false
    if ($S.Made.CsrPem) { [IO.File]::WriteAllText("$n.csr", $S.Made.CsrPem, $enc); $written += "$($S.MadeName).csr" }
    if ($S.Made.CertPem) {
        [IO.File]::WriteAllText("$n.crt", $S.Made.CertPem, $enc); $written += "$($S.MadeName).crt"
        try { [IO.File]::WriteAllBytes("$n.pfx", [DevCertTool]::Export($S.Made.Cert, 'pfx', $S.PfxPw.Text)); $written += "$($S.MadeName).pfx$(if (-not $S.PfxPw.Text) { ' (no password)' })" } catch { }
    }
    [IO.File]::WriteAllText("$n.key", $S.Made.KeyPem, $enc); $written += "$($S.MadeName).key"
    Set-TbStatus $S.Status "Saved $($written -join ', ') in $dir" 'ok'
    Start-Process explorer.exe "`"$dir`""
}

function Open-CertFile($S, [string]$Path) {
    try { $cert = [DevCertTool]::Load($Path, $S.OpenPw.Text) } catch {
        $ex = $_.Exception; while ($ex.InnerException) { $ex = $ex.InnerException }
        Set-TbStatus $S.Status "Can't read it: $($ex.Message)$(if ($Path -match '\.(pfx|p12)$') { ' - type its password and open it again.' })" 'error'; return
    }
    $S.Opened = $cert; $S.OpenedName = [IO.Path]::GetFileNameWithoutExtension($Path)
    Select-ApiTab $S.Tabs 'Open / convert'
    $S.OpenOut.Clear()
    Add-RtbLine $S.OpenOut (Split-Path -Leaf $Path) $C.Accent -Bold
    Add-RtbLine $S.OpenOut ([DevCertTool]::Describe($cert)).TrimEnd() $C.Fore
    Set-TbStatus $S.Status 'Save it as PEM, CER or PFX to convert it.' 'ok'
}

function Save-CertAs($S, [string]$Format) {
    if (-not $S.Opened) { Set-TbStatus $S.Status 'Open a certificate first.' 'error'; return }
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = switch ($Format) { 'pem' { 'PEM certificate|*.pem;*.crt' } 'cer' { 'DER certificate|*.cer;*.der' } default { 'PFX|*.pfx;*.p12' } }
    $d.FileName = "$($S.OpenedName).$(if ($Format -eq 'pem') { 'pem' } else { $Format })"
    $script:Modal = $true
    try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { return }; $p = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    try { [IO.File]::WriteAllBytes($p, [DevCertTool]::Export($S.Opened, $Format, $S.OpenPw.Text)); Set-TbStatus $S.Status "Saved $(Split-Path -Leaf $p)$(if ($Format -eq 'pfx' -and -not $S.Opened.HasPrivateKey) { ' (no private key in the original, so none in the PFX)' })" 'ok' }
    catch { Set-TbStatus $S.Status "Can't save: $($_.Exception.Message)" 'error' }
}

# ======================================================================================
# Screen recorder: record an area of the screen as an animated GIF.
# ======================================================================================
Register-ToolboxPage 'record' 'Screen recorder (GIF)' $Glyph.Photo 'screen recorder record gif video capture animation demo bug report' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Preview = New-Object System.Windows.Forms.PictureBox
    $st.Preview.Dock = 'Fill'; $st.Preview.SizeMode = 'Zoom'; $st.Preview.BackColor = $C.Bg
    $panel.Controls.Add($st.Preview)
    $ob = New-TbBar $panel
    [void](New-Button 'Save GIF...' 'Save the last recording' { Save-Recording $TbUI.Pages['record'].State } $ob $Glyph.Save 2)
    [void](New-Button 'Copy file' 'Copy the GIF file - paste it into a chat, email, ticket or Explorer' { $s = $TbUI.Pages['record'].State; if ($s.File) { $fc = New-Object System.Collections.Specialized.StringCollection; [void]$fc.Add($s.File); [System.Windows.Forms.Clipboard]::SetFileDropList($fc); Set-TbStatus $s.Status 'GIF file copied - paste it anywhere.' 'ok' } } $ob $Glyph.Copy 2)
    $bar = New-TbBar $panel
    [void](New-Button 'Record an area...' 'Drag a box around what to record (Esc cancels)' { Start-ScreenRecording $TbUI.Pages['record'].State $false } $bar $Glyph.Play 1)
    [void](New-Button 'Record the whole screen' 'Record the screen the mouse is on' { Start-ScreenRecording $TbUI.Pages['record'].State $true } $bar $Glyph.Play 2)
    New-TbLabel $bar 'Frames a second' -Dim | Out-Null
    $st.Fps = New-TbCombo $bar @('5', '10', '15', '20') 60
    $st.Fps.SelectedIndex = 1
    $st.Cursor = New-CheckBox $bar 'Show the mouse pointer' $true
    $st.SetInput = { }
    $st.Close = { $s = $TbUI.Pages['record'].State; if ($s.Preview.Image) { $s.Preview.Image.Dispose(); $s.Preview.Image = $null } }
    Set-TbStatus $st.Status 'Record an area or the whole screen; a small Stop bar appears (it is not in the recording). Up to 2 minutes; the GIF plays here when you stop.'
    $st
}

# A box dragged on a dimmed copy of the screen; returns the rectangle (screen pixels) or $null.
function Select-ScreenArea {
    $vs = [System.Windows.Forms.SystemInformation]::VirtualScreen
    $f = New-Object System.Windows.Forms.Form
    $f.FormBorderStyle = 'None'; $f.StartPosition = 'Manual'; $f.Bounds = $vs; $f.TopMost = $true; $f.ShowInTaskbar = $false
    $f.BackColor = [System.Drawing.Color]::Black; $f.Opacity = 0.35; $f.Cursor = [System.Windows.Forms.Cursors]::Cross; $f.KeyPreview = $true
    $f.Tag = @{ A = $null; B = $null; Result = $null; Origin = $vs.Location }
    $f.GetType().GetProperty('DoubleBuffered', [Reflection.BindingFlags]'Instance, NonPublic').SetValue($f, $true, $null)
    $f.add_MouseDown({ param($src, $e) $src.Tag.A = $e.Location; $src.Tag.B = $e.Location })
    $f.add_MouseMove({ param($src, $e) if ($src.Tag.A) { $src.Tag.B = $e.Location; $src.Invalidate() } })
    $f.add_MouseUp({
        param($src, $e)
        $t = $src.Tag
        if (-not $t.A) { return }
        $r = [System.Drawing.Rectangle]::FromLTRB([Math]::Min($t.A.X, $e.X), [Math]::Min($t.A.Y, $e.Y), [Math]::Max($t.A.X, $e.X), [Math]::Max($t.A.Y, $e.Y))
        if ($r.Width -gt 8 -and $r.Height -gt 8) { $r.Offset($t.Origin); $t.Result = $r; $src.DialogResult = 'OK' } else { $t.A = $null; $src.Invalidate() }
    })
    $f.add_Paint({
        param($src, $e)
        $t = $src.Tag
        if ($t.A -and $t.B) {
            $r = [System.Drawing.Rectangle]::FromLTRB([Math]::Min($t.A.X, $t.B.X), [Math]::Min($t.A.Y, $t.B.Y), [Math]::Max($t.A.X, $t.B.X), [Math]::Max($t.A.Y, $t.B.Y))
            $p = New-Object System.Drawing.Pen ([System.Drawing.Color]::White), 2; $e.Graphics.DrawRectangle($p, $r); $p.Dispose()
            $e.Graphics.FillRectangle([System.Drawing.Brushes]::Gray, $r)
        }
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, 'Drag a box around what to record  -  Esc cancels', $FontTitle, (New-Object System.Drawing.Point((Px 30), (Px 30))), [System.Drawing.Color]::White)
    })
    $f.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Escape') { $src.DialogResult = 'Cancel' } })
    $script:Modal = $true
    try { $ok = $f.ShowDialog() -eq 'OK'; $res = $f.Tag.Result } finally { $script:Modal = $false; $f.Dispose() }
    if ($ok) { $res } else { $null }
}

function Start-ScreenRecording($S, [bool]$WholeScreen) {
    if ($script:Recording) { return }
    $TbUI.Form.Hide()
    Start-Sleep -Milliseconds 200
    $area = if ($WholeScreen) { [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).Bounds } else { Select-ScreenArea }
    if (-not $area) { Show-Toolbox 'record'; return }
    if ($area.Width % 2) { $area.Width-- }; if ($area.Height % 2) { $area.Height-- }
    $fps = [int]$S.Fps.SelectedItem
    $file = Join-Path ([IO.Path]::GetTempPath()) "DevTools-recording-$((Get-Date).ToString('yyyyMMdd-HHmmss')).gif"
    $fs = [IO.File]::Create($file)
    $rec = @{ S = $S; Area = $area; File = $file; Stream = $fs; Writer = (New-Object DevGifWriter($fs, $area.Width, $area.Height)); Delay = [int](100 / $fps); Started = Get-Date; Cursor = $S.Cursor.Checked }
    $script:Recording = $rec
    # the Stop bar: below the area (or above it, or in its corner), kept out of the recording
    $bar = New-Object System.Windows.Forms.Form
    $bar.FormBorderStyle = 'None'; $bar.StartPosition = 'Manual'; $bar.TopMost = $true; $bar.ShowInTaskbar = $false; $bar.BackColor = $C.Card
    $bar.Size = New-Object System.Drawing.Size((Px 230), (Px 40))
    $wa = [System.Windows.Forms.Screen]::FromRectangle($area).WorkingArea
    $y = if ($area.Bottom + $bar.Height + (Px 6) -le $wa.Bottom) { $area.Bottom + (Px 6) } elseif ($area.Top - $bar.Height - (Px 6) -ge $wa.Top) { $area.Top - $bar.Height - (Px 6) } else { $area.Bottom - $bar.Height - (Px 10) }
    $bar.Location = New-Object System.Drawing.Point(([Math]::Max($wa.Left, [Math]::Min($area.Right - $bar.Width, $wa.Right - $bar.Width))), $y)
    $lbl = New-Object System.Windows.Forms.Label; $lbl.AutoSize = $false; $lbl.Dock = 'Fill'; $lbl.TextAlign = 'MiddleLeft'; $lbl.ForeColor = $C.Red; $lbl.Font = $FontMain; $lbl.Padding = New-Object System.Windows.Forms.Padding((Px 10), 0, 0, 0)
    $lbl.Text = 'REC 0:00'
    $stop = New-Button 'Stop' 'Stop recording' { Stop-ScreenRecording } $bar $Glyph.Cancel 3
    $stop.Dock = 'Right'
    $bar.Controls.Add($lbl); $lbl.BringToFront()
    $rec.Bar = $bar; $rec.Label = $lbl
    $bar.Show()
    [DevGifWriter]::ExcludeFromCapture($bar.Handle)
    $rec.Timer = New-Object System.Windows.Forms.Timer
    $rec.Timer.Interval = [int](1000 / $fps)
    $rec.Timer.add_Tick({
        $r = $script:Recording
        if (-not $r) { return }
        try { $b = [DevGifWriter]::Capture($r.Area, $r.Cursor); $r.Writer.AddFrame($b, $r.Delay); $b.Dispose() } catch { }
        $sec = [int]((Get-Date) - $r.Started).TotalSeconds
        $r.Label.Text = 'REC {0}:{1:00}' -f [int][Math]::Floor($sec / 60), ($sec % 60)
        if ($sec -ge 120) { Stop-ScreenRecording }
    })
    $rec.Timer.Start()
}

function Stop-ScreenRecording {
    $r = $script:Recording
    if (-not $r) { return }
    $script:Recording = $null
    $r.Timer.Stop(); $r.Timer.Dispose()
    try { $r.Writer.Finish() } finally { $r.Stream.Dispose() }
    $r.Bar.Close(); $r.Bar.Dispose()
    $S = $r.S
    $S.File = $r.File
    if ($S.Preview.Image) { $S.Preview.Image.Dispose() }
    $S.Preview.Image = [System.Drawing.Image]::FromFile($r.File)
    $secs = [Math]::Round(((Get-Date) - $r.Started).TotalSeconds, 1)
    Show-Toolbox 'record'
    Set-TbStatus $S.Status "Recorded $secs s, $($r.Writer.Frames) frames, $([Math]::Round((Get-Item -LiteralPath $r.File).Length / 1KB).ToString('N0')) KB  -  Save GIF... or Copy file." 'ok'
}

function Save-Recording($S) {
    if (-not $S.File) { Set-TbStatus $S.Status 'Record something first.' 'error'; return }
    $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'GIF animation|*.gif'; $d.FileName = Split-Path -Leaf $S.File
    $script:Modal = $true
    try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { return }; $p = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    Copy-Item -LiteralPath $S.File -Destination $p -Force
    Set-TbStatus $S.Status "Saved $(Split-Path -Leaf $p)" 'ok'
}

# ======================================================================================
# Code to image: a nice picture of a code snippet (syntax colours, window frame, background) to share.
# ======================================================================================
$CodeImageBackgrounds = [ordered]@{
    'Purple' = @('#A78BFA', '#4F46E5'); 'Ocean' = @('#22D3EE', '#2563EB'); 'Sunset' = @('#FB923C', '#DB2777'); 'Forest' = @('#34D399', '#047857')
    'Grey' = @('#9CA3AF', '#4B5563'); 'None (transparent)' = @('', '')
}
Register-ToolboxPage 'codeimg' 'Code to image' $Glyph.Code 'code image screenshot snippet carbon share picture syntax highlight pretty' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $split = New-Object System.Windows.Forms.SplitContainer
    $split.Dock = 'Fill'; $split.BackColor = $C.Line; $split.SplitterWidth = 3
    $split.Panel1.BackColor = $C.Bg; $split.Panel2.BackColor = $C.Bg
    $panel.Controls.Add($split)
    $st.Code = New-TbBox -Mono -Multi -Cue 'Paste your code here'
    $st.Code.Dock = 'Fill'
    $split.Panel1.Controls.Add($st.Code)
    $st.Preview = New-Object System.Windows.Forms.PictureBox
    $st.Preview.Dock = 'Fill'; $st.Preview.SizeMode = 'Zoom'; $st.Preview.BackColor = $C.Bg
    $split.Panel2.Controls.Add($st.Preview)
    $ob = New-TbBar $panel
    [void](New-Button 'Copy image' 'Copy the picture - paste it into a chat, slides or a document' { $s = $TbUI.Pages['codeimg'].State; if ($s.Bitmap) { [System.Windows.Forms.Clipboard]::SetImage($s.Bitmap); Set-TbStatus $s.Status 'Image copied.' 'ok' } } $ob $Glyph.Copy 1)
    [void](New-Button 'Save PNG...' 'Save the picture' {
        $s = $TbUI.Pages['codeimg'].State; if (-not $s.Bitmap) { return }
        $d = New-Object System.Windows.Forms.SaveFileDialog; $d.Filter = 'PNG image|*.png'; $d.FileName = $(if ($s.Title.Text) { $s.Title.Text -replace '[\\/:*?"<>|]', '_' } else { 'code' }) + '.png'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -eq 'OK') { $s.Bitmap.Save($d.FileName, [System.Drawing.Imaging.ImageFormat]::Png) } } finally { $script:Modal = $false; $d.Dispose() }
    } $ob $Glyph.Save 2)
    $b1 = New-TbBar $panel
    New-TbLabel $b1 'Language' -Dim | Out-Null
    $st.Lang = New-TbCombo $b1 @('Guess', 'C#', 'JavaScript / TypeScript', 'Python', 'PowerShell', 'JSON', 'SQL', 'XML / HTML', 'Bash', 'Java / Kotlin', 'Go', 'Rust', 'C / C++', 'CSS', 'YAML', 'PHP', 'Plain text') 170
    New-TbLabel $b1 'Theme' -Dim | Out-Null
    $st.Theme = New-TbCombo $b1 @('Dark', 'Light') 80
    New-TbLabel $b1 'Background' -Dim | Out-Null
    $st.Bg = New-TbCombo $b1 @($CodeImageBackgrounds.Keys) 140
    New-TbLabel $b1 'Size' -Dim | Out-Null
    $st.Size = New-TbCombo $b1 @('10', '11', '12', '13', '14', '16', '18') 60
    $st.Size.SelectedIndex = 2
    $b2 = New-TbBar $panel
    $st.Lines = New-CheckBox $b2 'Line numbers' $true
    $st.Frame = New-CheckBox $b2 'Window frame' $true
    New-TbLabel $b2 'Title' -Dim | Out-Null
    $st.Title = New-TbBox -Cue 'e.g. app.js'
    $st.Title.Width = Px (200 * $TextZoom); $st.Title.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $b2.Controls.Add($st.Title)
    $st.Timer = New-TbDebounce 300 { Update-CodeImage $TbUI.Pages['codeimg'].State }
    foreach ($c2 in $st.Code, $st.Title) { $c2.add_TextChanged({ $s = $TbUI.Pages['codeimg'].State; $s.Timer.Stop(); $s.Timer.Start() }) }
    foreach ($c2 in $st.Lang, $st.Theme, $st.Bg, $st.Size) { $c2.add_SelectedIndexChanged({ Update-CodeImage $TbUI.Pages['codeimg'].State }) }
    foreach ($c2 in $st.Lines, $st.Frame) { $c2.add_CheckedChanged({ Update-CodeImage $TbUI.Pages['codeimg'].State }) }
    $split.Tag = $true
    $split.add_Resize({ param($src, $e) if ($src.Tag -and $src.Width -gt (Px 500)) { $src.Tag = $false; $src.SplitterDistance = [int]($src.Width * 0.42) } })
    $st.SetInput = { param($t) $TbUI.Pages['codeimg'].State.Code.Text = $t }
    $st.Focus = { $TbUI.Pages['codeimg'].State.Code.Focus() }
    $st.Close = { $s = $TbUI.Pages['codeimg'].State; if ($s.Bitmap) { $s.Preview.Image = $null; $s.Bitmap.Dispose() } }
    $st.Code.Text = "function greet(name) {`r`n  // say hello`r`n  return ``Hello, `${name}!``;`r`n}`r`n`r`nconsole.log(greet('world'));"
    $st.Title.Text = 'greet.js'
    $st
}

function Update-CodeImage($S) {
    if (-not $S.Code.Text.Trim()) { if ($S.Bitmap) { $S.Preview.Image = $null; $S.Bitmap.Dispose(); $S.Bitmap = $null }; Set-TbStatus $S.Status 'Paste some code.'; return }
    $lang = @('', 'cs', 'js', 'py', 'ps', 'json', 'sql', 'xml', 'sh', 'java', 'go', 'rust', 'c', 'css', 'yaml', 'php', 'none')[$S.Lang.SelectedIndex]
    $bg = $CodeImageBackgrounds[[string]$S.Bg.SelectedItem]
    $ca = if ($bg[0]) { [System.Drawing.ColorTranslator]::FromHtml($bg[0]) } else { [System.Drawing.Color]::Transparent }
    $cb = if ($bg[1]) { [System.Drawing.ColorTranslator]::FromHtml($bg[1]) } else { [System.Drawing.Color]::Transparent }
    try {
        $bmp = [DevCodeImage]::Render($S.Code.Text, $lang, ($S.Theme.SelectedIndex -eq 0), [float]$S.Size.SelectedItem, $S.Lines.Checked, $S.Frame.Checked, $S.Title.Text, $ca, $cb, 2)
    } catch { Set-TbStatus $S.Status $_.Exception.Message 'error'; return }
    $old = $S.Bitmap
    $S.Bitmap = $bmp; $S.Preview.Image = $bmp
    if ($old) { $old.Dispose() }
    Set-TbStatus $S.Status "$($bmp.Width) x $($bmp.Height) (sharp at 2x)  $Dot  Copy image, or Save PNG..." 'ok'
}

# ======================================================================================
# Colour: pick from the screen, convert between formats, shades, contrast.
# ======================================================================================
$ColorsFile = Join-Path $DataDir 'colors.json'

function ConvertFrom-ColorText([string]$Text) {
    $t = $Text.Trim()
    if (-not $t) { return $null }
    if ($t -match '^#?([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$') {
        $h = $Matches[1]
        if ($h.Length -le 4) { $h = -join ($h.ToCharArray() | ForEach-Object { "$_$_" }) }
        $v = [Convert]::ToUInt32($h, 16)
        if ($h.Length -eq 6) { return [System.Drawing.Color]::FromArgb([int](($v -shr 16) -band 255), [int](($v -shr 8) -band 255), [int]($v -band 255)) }
        return [System.Drawing.Color]::FromArgb([int]($v -band 255), [int](($v -shr 24) -band 255), [int](($v -shr 16) -band 255), [int](($v -shr 8) -band 255))
    }
    if ($t -match '^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+%?)\s*)?\)$') {
        $a = 255
        if ($Matches[4]) { $a = if ($Matches[4].EndsWith('%')) { [int]([double]$Matches[4].TrimEnd('%') * 2.55) } else { [int]([double]$Matches[4] * 255) } }
        return [System.Drawing.Color]::FromArgb([Math]::Min(255, $a), [Math]::Min(255, [int]$Matches[1]), [Math]::Min(255, [int]$Matches[2]), [Math]::Min(255, [int]$Matches[3]))
    }
    if ($t -match '^hsla?\(\s*([\d.]+)\s*,\s*([\d.]+)%\s*,\s*([\d.]+)%') { return ConvertFrom-Hsl ([double]$Matches[1]) ([double]$Matches[2] / 100) ([double]$Matches[3] / 100) }
    if ($t -match '^(\d{1,3})\s*[, ]\s*(\d{1,3})\s*[, ]\s*(\d{1,3})$') { return [System.Drawing.Color]::FromArgb([Math]::Min(255, [int]$Matches[1]), [Math]::Min(255, [int]$Matches[2]), [Math]::Min(255, [int]$Matches[3])) }
    $named = [System.Drawing.Color]::FromName($t)
    if ($named.IsKnownColor) { return [System.Drawing.Color]::FromArgb($named.A, $named.R, $named.G, $named.B) }
    $null
}

function ConvertFrom-Hsl([double]$H, [double]$S, [double]$L) {
    $cx = (1 - [Math]::Abs(2 * $L - 1)) * $S
    $hp = ($H % 360) / 60
    $x = $cx * (1 - [Math]::Abs($hp % 2 - 1))
    $r, $g, $b = switch ([int][Math]::Floor($hp)) { 0 { $cx, $x, 0 } 1 { $x, $cx, 0 } 2 { 0, $cx, $x } 3 { 0, $x, $cx } 4 { $x, 0, $cx } default { $cx, 0, $x } }
    $m = $L - $cx / 2
    [System.Drawing.Color]::FromArgb([int][Math]::Round(($r + $m) * 255), [int][Math]::Round(($g + $m) * 255), [int][Math]::Round(($b + $m) * 255))
}

function Get-ColorFormats([System.Drawing.Color]$Col) {
    $hex = '#{0:X2}{1:X2}{2:X2}' -f $Col.R, $Col.G, $Col.B
    $h = [int][Math]::Round($Col.GetHue()); $s = [int][Math]::Round($Col.GetSaturation() * 100); $l = [int][Math]::Round($Col.GetBrightness() * 100)
    $max = [Math]::Max($Col.R, [Math]::Max($Col.G, $Col.B)) / 255.0; $min = [Math]::Min($Col.R, [Math]::Min($Col.G, $Col.B)) / 255.0
    $sv = if ($max -eq 0) { 0 } else { [int][Math]::Round(($max - $min) / $max * 100) }
    $k = 1 - $max
    $cmyk = if ($k -ge 1) { 'cmyk(0%, 0%, 0%, 100%)' } else { 'cmyk({0}%, {1}%, {2}%, {3}%)' -f [int][Math]::Round((1 - $Col.R / 255.0 - $k) / (1 - $k) * 100), [int][Math]::Round((1 - $Col.G / 255.0 - $k) / (1 - $k) * 100), [int][Math]::Round((1 - $Col.B / 255.0 - $k) / (1 - $k) * 100), [int][Math]::Round($k * 100) }
    [ordered]@{
        'HEX' = $hex
        'RGB' = "rgb($($Col.R), $($Col.G), $($Col.B))"
        'HSL' = "hsl($h, $s%, $l%)"
        'HSV' = "hsv($h, $sv%, $([int][Math]::Round($max * 100))%)"
        'CMYK' = $cmyk
        'C#' = "Color.FromArgb($($Col.R), $($Col.G), $($Col.B))"
        'Integer' = [string](([int]$Col.R -shl 16) -bor ([int]$Col.G -shl 8) -bor [int]$Col.B)
    }
}

function Get-Luminance([System.Drawing.Color]$Col) {
    $f = { param($v) $cx = $v / 255.0; if ($cx -le 0.03928) { $cx / 12.92 } else { [Math]::Pow(($cx + 0.055) / 1.055, 2.4) } }
    0.2126 * (& $f $Col.R) + 0.7152 * (& $f $Col.G) + 0.0722 * (& $f $Col.B)
}

function Get-Contrast($A, $B) { $la = Get-Luminance $A; $lb = Get-Luminance $B; ([Math]::Max($la, $lb) + 0.05) / ([Math]::Min($la, $lb) + 0.05) }

Register-ToolboxPage 'color' 'Colour picker' $Glyph.Color 'colour color picker eyedropper hex rgb hsl contrast screen' {
    param($panel, $st)
    foreach ($kv in (@{ Color = [System.Drawing.Color]::FromArgb(15, 108, 189); History = (New-Object System.Collections.Generic.List[string]) }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    if (Test-Path $ColorsFile) { try { foreach ($x in @(ConvertFrom-JsonList (Read-DataText $ColorsFile))) { if ($x) { $st.History.Add([string]$x) } } } catch { } }

    $body = New-Object System.Windows.Forms.TableLayoutPanel
    $body.Dock = 'Fill'; $body.ColumnCount = 2; $body.BackColor = $C.Bg
    [void]$body.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Absolute', (Px 260))))
    [void]$body.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $panel.Controls.Add($body)
    $swatch = New-Object System.Windows.Forms.Panel
    $swatch.Size = New-Object System.Drawing.Size((Px 240), (Px 240)); $swatch.Margin = New-Object System.Windows.Forms.Padding(0, (Px 6), (Px 16), 0)
    $swatch.add_Paint({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $g = $e.Graphics; $g.SmoothingMode = 'AntiAlias'
        $r = New-Object System.Drawing.RectangleF(0.5, 0.5, ($src.Width - 1.5), ($src.Height - 1.5))
        $p = [PowerClipTheme]::Round($r, (Px 12))
        $b = New-Object System.Drawing.SolidBrush $s.Color; $g.FillPath($b, $p); $b.Dispose()
        $pen = New-Object System.Drawing.Pen $C.Line; $g.DrawPath($pen, $p); $pen.Dispose(); $p.Dispose()
        $txt = (Get-ColorFormats $s.Color).HEX
        $fore = if ((Get-Contrast $s.Color ([System.Drawing.Color]::White)) -ge (Get-Contrast $s.Color ([System.Drawing.Color]::Black))) { [System.Drawing.Color]::White } else { [System.Drawing.Color]::Black }
        $f = New-Object System.Drawing.Font($UiFont, (Fz 16), [System.Drawing.FontStyle]::Bold)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $txt, $f, [System.Drawing.Rectangle]::Round($r), $fore, [System.Windows.Forms.TextFormatFlags]'HorizontalCenter, VerticalCenter')
        $f.Dispose()
    })
    $st.Swatch = $swatch
    $body.Controls.Add($swatch, 0, 0)
    $right = New-Object System.Windows.Forms.FlowLayoutPanel
    $right.Dock = 'Fill'; $right.FlowDirection = 'TopDown'; $right.WrapContents = $false; $right.AutoScroll = $true; $right.BackColor = $C.Bg
    $body.Controls.Add($right, 1, 0)
    $st.Values = [ordered]@{}
    foreach ($k in (Get-ColorFormats $st.Color).Keys) {
        $row = New-Object System.Windows.Forms.FlowLayoutPanel
        $row.AutoSize = $true; $row.WrapContents = $false; $row.BackColor = $C.Bg; $row.Margin = New-Object System.Windows.Forms.Padding(0)
        $l = New-TbLabel $row $k -Dim; $l.AutoSize = $false; $l.Width = Px (70 * $TextZoom)
        $v = New-TbBox -Mono -ReadOnly; $v.Width = Px (300 * $TextZoom); $v.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
        $row.Controls.Add($v)
        $b = New-Button '' "Copy $k" { param($src, $e) Copy-TbText $src.Tag.Text } $row $Glyph.Copy 2
        $b.Tag = $v
        $right.Controls.Add($row)
        $st.Values[$k] = $v
    }
    $st.Contrast = New-TbLabel $right '' -Dim
    $st.Shades = New-Object System.Windows.Forms.Panel
    $st.Shades.Size = New-Object System.Drawing.Size((Px (420 * $TextZoom)), (Px 40)); $st.Shades.Margin = New-Object System.Windows.Forms.Padding(0, (Px 10), 0, 0); $st.Shades.Cursor = 'Hand'
    $st.Shades.add_Paint({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $w = $src.Width / 9
        for ($i = 0; $i -lt 9; $i++) {
            $cx = if ($i -lt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::White, (4 - $i) * 0.2) } elseif ($i -gt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::Black, ($i - 4) * 0.2) } else { $s.Color }
            $b = New-Object System.Drawing.SolidBrush $cx; $e.Graphics.FillRectangle($b, [float]($i * $w), 0, [float]($w + 1), $src.Height); $b.Dispose()
        }
        $pen = New-Object System.Drawing.Pen $C.Fore, 2; $e.Graphics.DrawRectangle($pen, [float](4 * $w), 1, [float]$w, ($src.Height - 2)); $pen.Dispose()
    })
    $st.Shades.add_MouseClick({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $i = [int][Math]::Floor($e.X / ($src.Width / 9))
        $cx = if ($i -lt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::White, (4 - $i) * 0.2) } elseif ($i -gt 4) { [PowerClipTheme]::Mix($s.Color, [System.Drawing.Color]::Black, ($i - 4) * 0.2) } else { $s.Color }
        Set-ToolColor $s $cx
    })
    $tooltip.SetToolTip($st.Shades, 'Lighter and darker shades - click one to use it')
    $right.Controls.Add($st.Shades)
    New-TbLabel $right 'Recent' -Dim | Out-Null
    $st.HistoryPanel = New-Object System.Windows.Forms.Panel
    $st.HistoryPanel.Size = New-Object System.Drawing.Size((Px (420 * $TextZoom)), (Px 34)); $st.HistoryPanel.Cursor = 'Hand'
    $st.HistoryPanel.add_Paint({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $e.Graphics.SmoothingMode = 'AntiAlias'
        for ($i = 0; $i -lt [Math]::Min(12, $s.History.Count); $i++) {
            $cx = ConvertFrom-ColorText $s.History[$i]
            if (-not $cx) { continue }
            $b = New-Object System.Drawing.SolidBrush $cx; $e.Graphics.FillEllipse($b, ($i * (Px 34) + (Px 2)), (Px 2), (Px 28), (Px 28)); $b.Dispose()
            $pen = New-Object System.Drawing.Pen $C.Line; $e.Graphics.DrawEllipse($pen, ($i * (Px 34) + (Px 2)), (Px 2), (Px 28), (Px 28)); $pen.Dispose()
        }
    })
    $st.HistoryPanel.add_MouseClick({
        param($src, $e)
        $s = $TbUI.Pages['color'].State
        $i = [int][Math]::Floor($e.X / (Px 34))
        if ($i -lt $s.History.Count) { Set-ToolColor $s (ConvertFrom-ColorText $s.History[$i]) -NoHistory }
    })
    $right.Controls.Add($st.HistoryPanel)

    $bar = New-TbBar $panel
    [void](New-Button 'Pick from screen' 'Click anywhere on the screen to take its colour (Esc cancels)' { Start-ScreenColorPick } $bar $Glyph.Color 1)
    New-TbLabel $bar 'or type a colour' -Dim | Out-Null
    $st.Input = New-TbBox -Mono -Cue '#1e90ff   rgb(30,144,255)   hsl(210,100%,56%)   DodgerBlue'
    $st.Input.Width = Px (340 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $bar.Controls.Add($st.Input)
    $st.Input.add_TextChanged({
        $s = $TbUI.Pages['color'].State
        $cx = ConvertFrom-ColorText $s.Input.Text
        if ($cx) { Set-ToolColor $s $cx -NoHistory -KeepInput } elseif ($s.Input.Text.Trim()) { Set-TbStatus $s.Status 'Not a colour I understand (try #rrggbb, rgb(...), hsl(...) or a name)' 'warn' }
    })
    $st.SetInput = { param($t) $TbUI.Pages['color'].State.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['color'].State.Input.Focus() }
    Set-ToolColor $st $st.Color -NoHistory
    $st
}

function Set-ToolColor($St, $Col, [switch]$NoHistory, [switch]$KeepInput) {
    if (-not $Col) { return }
    $St.Color = [System.Drawing.Color]::FromArgb(255, $Col.R, $Col.G, $Col.B)
    $fmt = Get-ColorFormats $St.Color
    foreach ($k in $fmt.Keys) { $St.Values[$k].Text = $fmt[$k] }
    $cw = Get-Contrast $St.Color ([System.Drawing.Color]::White); $cb = Get-Contrast $St.Color ([System.Drawing.Color]::Black)
    $grade = { param($r) if ($r -ge 7) { 'AAA' } elseif ($r -ge 4.5) { 'AA' } elseif ($r -ge 3) { 'AA large text' } else { 'fails' } }
    $St.Contrast.Text = "Contrast with white text {0:N1}:1 ({1})   $Dot   with black text {2:N1}:1 ({3})" -f $cw, (& $grade $cw), $cb, (& $grade $cb)
    if (-not $NoHistory) {
        [void]$St.History.Remove($fmt.HEX); $St.History.Insert(0, $fmt.HEX)
        while ($St.History.Count -gt 24) { $St.History.RemoveAt($St.History.Count - 1) }
        try { Write-JsonFile $ColorsFile (ConvertTo-Json -InputObject $St.History.ToArray()) } catch { }
    }
    $St.Swatch.Invalidate(); $St.Shades.Invalidate(); $St.HistoryPanel.Invalidate()
    Set-TbStatus $St.Status "$($fmt.HEX)  $Dot  $($fmt.RGB)  $Dot  $($fmt.HSL)" 'ok'
}

# Full-screen eyedropper: shows a frozen screenshot with a magnifier; click to pick, Esc to cancel.
function Start-ScreenColorPick {
    $vs = [System.Windows.Forms.SystemInformation]::VirtualScreen
    $shot = New-Object System.Drawing.Bitmap $vs.Width, $vs.Height
    $g = [System.Drawing.Graphics]::FromImage($shot); $g.CopyFromScreen($vs.Left, $vs.Top, 0, 0, $shot.Size); $g.Dispose()
    if ($TbUI.Form) { $TbUI.Form.Hide() }
    Start-Sleep -Milliseconds 120
    $pf = New-Object System.Windows.Forms.Form
    $pf.FormBorderStyle = 'None'; $pf.StartPosition = 'Manual'; $pf.Bounds = $vs; $pf.TopMost = $true; $pf.ShowInTaskbar = $false
    $pf.Cursor = [System.Windows.Forms.Cursors]::Cross; $pf.KeyPreview = $true
    $pf.Tag = @{ Shot = $shot; Pos = [System.Windows.Forms.Cursor]::Position; Origin = $vs.Location }
    $pf.GetType().GetProperty('DoubleBuffered', [Reflection.BindingFlags]'Instance, NonPublic').SetValue($pf, $true, $null)
    $pf.add_Paint({
        param($src, $e)
        $t = $src.Tag
        $gg = $e.Graphics
        $gg.DrawImageUnscaled($t.Shot, 0, 0)
        $px = $t.Pos.X - $t.Origin.X; $py = $t.Pos.Y - $t.Origin.Y
        $zoom = 12; $n = 11; $size = $zoom * $n
        $lx = $px + 24; $ly = $py + 24
        if ($lx + $size + 8 -gt $src.Width) { $lx = $px - $size - 24 }
        if ($ly + $size + 40 -gt $src.Height) { $ly = $py - $size - 56 }
        $gg.InterpolationMode = 'NearestNeighbor'; $gg.PixelOffsetMode = 'Half'
        $srcRect = New-Object System.Drawing.Rectangle(($px - 5), ($py - 5), $n, $n)
        $gg.FillRectangle([System.Drawing.Brushes]::Black, ($lx - 2), ($ly - 2), ($size + 4), ($size + 34))
        $gg.DrawImage($t.Shot, (New-Object System.Drawing.Rectangle($lx, $ly, $size, $size)), $srcRect, [System.Drawing.GraphicsUnit]::Pixel)
        $gg.DrawRectangle([System.Drawing.Pens]::White, ($lx + 5 * $zoom), ($ly + 5 * $zoom), $zoom, $zoom)
        $col = if ($px -ge 0 -and $py -ge 0 -and $px -lt $t.Shot.Width -and $py -lt $t.Shot.Height) { $t.Shot.GetPixel($px, $py) } else { [System.Drawing.Color]::Black }
        $hex = '#{0:X2}{1:X2}{2:X2}' -f $col.R, $col.G, $col.B
        $b = New-Object System.Drawing.SolidBrush $col; $gg.FillRectangle($b, $lx, ($ly + $size + 4), 26, 26); $b.Dispose()
        $font = New-Object System.Drawing.Font($UiFont, 10, [System.Drawing.FontStyle]::Bold)
        $gg.DrawString($hex, $font, [System.Drawing.Brushes]::White, ($lx + 32), ($ly + $size + 7)); $font.Dispose()
    })
    $pf.add_MouseMove({ param($src, $e) $src.Tag.Pos = [System.Windows.Forms.Cursor]::Position; $src.Invalidate() })
    $pf.add_MouseUp({ param($src, $e) Complete-ScreenColorPick $src ($e.Button -eq 'Left') })
    $pf.add_KeyDown({
        param($src, $e)
        $t = $src.Tag
        switch ($e.KeyCode) {
            'Escape' { Complete-ScreenColorPick $src $false; return }
            'Return' { Complete-ScreenColorPick $src $true; return }
            'Left'  { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point(($t.Pos.X - 1), $t.Pos.Y) }
            'Right' { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point(($t.Pos.X + 1), $t.Pos.Y) }
            'Up'    { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point($t.Pos.X, ($t.Pos.Y - 1)) }
            'Down'  { [System.Windows.Forms.Cursor]::Position = New-Object System.Drawing.Point($t.Pos.X, ($t.Pos.Y + 1)) }
        }
        $t.Pos = [System.Windows.Forms.Cursor]::Position; $src.Invalidate()
    })
    $pf.Show()
    $pf.Activate()
}

function Complete-ScreenColorPick($Form, [bool]$Pick) {
    $t = $Form.Tag
    if ($t.Finished) { return }
    $t.Finished = $true
    $col = $null
    if ($Pick) {
        $px = $t.Pos.X - $t.Origin.X; $py = $t.Pos.Y - $t.Origin.Y
        if ($px -ge 0 -and $py -ge 0 -and $px -lt $t.Shot.Width -and $py -lt $t.Shot.Height) { $col = $t.Shot.GetPixel($px, $py) }
    }
    $Form.Close(); $t.Shot.Dispose()
    Show-Toolbox 'color'
    if ($col) { Set-ToolColor $TbUI.Pages['color'].State $col; Copy-TbText ('#{0:X2}{1:X2}{2:X2}' -f $col.R, $col.G, $col.B) }
}

# ======================================================================================
# File hash: MD5 / SHA-1 / SHA-256 / SHA-512, compare with an expected value.
# ======================================================================================
Register-ToolboxPage 'hash' 'File hash' $Glyph.Document 'hash checksum md5 sha1 sha256 sha512 file verify download' {
    param($panel, $st)
    foreach ($kv in (@{ Job = $null }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $panel.AllowDrop = $true
    $body = New-Object System.Windows.Forms.FlowLayoutPanel
    $body.Dock = 'Fill'; $body.FlowDirection = 'TopDown'; $body.WrapContents = $false; $body.BackColor = $C.Bg; $body.AllowDrop = $true
    $panel.Controls.Add($body)
    $drop = New-Object System.Windows.Forms.Label
    $drop.AutoSize = $false; $drop.Size = New-Object System.Drawing.Size((Px (760 * $TextZoom)), (Px 90)); $drop.TextAlign = 'MiddleCenter'
    $drop.Text = 'Drop a file here, or click to choose one'; $drop.ForeColor = $C.Dim; $drop.BackColor = $C.Card; $drop.Cursor = 'Hand'; $drop.AllowDrop = $true
    $drop.add_Paint({ param($src, $e) $pen = New-Object System.Drawing.Pen $C.Line; $pen.DashStyle = 'Dash'; $e.Graphics.DrawRectangle($pen, 0, 0, ($src.Width - 1), ($src.Height - 1)); $pen.Dispose() })
    $drop.add_Click({ $d = New-Object System.Windows.Forms.OpenFileDialog; $d.Title = 'File to hash'; if ($d.ShowDialog($TbUI.Form) -eq 'OK') { Start-FileHashJob $TbUI.Pages['hash'].State $d.FileName }; $d.Dispose() })
    $body.Controls.Add($drop)
    $st.Drop = $drop
    $st.File = New-TbLabel $body '' -Title
    $st.Progress = New-Object System.Windows.Forms.ProgressBar
    $st.Progress.Width = Px (760 * $TextZoom); $st.Progress.Height = Px 8; $st.Progress.Visible = $false
    $body.Controls.Add($st.Progress)
    $st.Rows = [ordered]@{}
    foreach ($k in 'MD5', 'SHA-1', 'SHA-256', 'SHA-512') {
        $row = New-Object System.Windows.Forms.FlowLayoutPanel
        $row.AutoSize = $true; $row.WrapContents = $false; $row.BackColor = $C.Bg
        $l = New-TbLabel $row $k -Dim; $l.AutoSize = $false; $l.Width = Px (80 * $TextZoom)
        $v = New-TbBox -Mono -ReadOnly; $v.Width = Px (640 * $TextZoom); $v.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
        $row.Controls.Add($v)
        $b = New-Button '' "Copy $k" { param($src, $e) Copy-TbText $src.Tag.Text } $row $Glyph.Copy 2
        $b.Tag = $v
        $body.Controls.Add($row)
        $st.Rows[$k] = $v
    }
    $cmp = New-Object System.Windows.Forms.FlowLayoutPanel
    $cmp.AutoSize = $true; $cmp.WrapContents = $false; $cmp.BackColor = $C.Bg; $cmp.Margin = New-Object System.Windows.Forms.Padding(0, (Px 14), 0, 0)
    $l = New-TbLabel $cmp 'Expected' -Dim; $l.AutoSize = $false; $l.Width = Px (80 * $TextZoom)
    $st.Expected = New-TbBox -Mono -Cue 'paste the checksum from the download page to compare'
    $st.Expected.Width = Px (640 * $TextZoom); $st.Expected.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 6), 0)
    $cmp.Controls.Add($st.Expected)
    $body.Controls.Add($cmp)
    $st.Verdict = New-TbLabel $body '' -Title
    $st.Expected.add_TextChanged({ Update-HashVerdict $TbUI.Pages['hash'].State })
    $dragEnter = { param($src, $e) $e.Effect = if ($e.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) { 'Copy' } else { 'None' } }
    $dragDrop = { param($src, $e) $f = @($e.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop))[0]; if ($f -and (Test-Path -LiteralPath $f -PathType Leaf)) { Start-FileHashJob $TbUI.Pages['hash'].State $f } }
    foreach ($cx in $panel, $body, $drop) { $cx.add_DragEnter($dragEnter); $cx.add_DragDrop($dragDrop) }
    $st.Timer = New-Object System.Windows.Forms.Timer
    $st.Timer.Interval = 100
    $st.Timer.add_Tick({ Update-FileHashJob $TbUI.Pages['hash'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['hash'].State; $t = $t.Trim().Trim('"'); if (Test-Path -LiteralPath $t -PathType Leaf) { Start-FileHashJob $s $t } else { $s.Expected.Text = $t } }
    $st.Close = { $s = $TbUI.Pages['hash'].State; $s.Timer.Stop(); $s.Timer.Dispose(); if ($s.Job) { $s.Job.Cancel = $true } }
    Set-TbStatus $st.Status 'All four hashes are computed in one pass. Big files are fine; it runs in the background.'
    $st
}

function Start-FileHashJob($St, [string]$Path) {
    if ($St.Job -and -not $St.Job.Done) { $St.Job.Cancel = $true }
    foreach ($v in $St.Rows.Values) { $v.Text = '' }
    $St.File.Text = $Path
    $St.Progress.Value = 0; $St.Progress.Visible = $true
    $St.Job = [DevFileHash]::Start($Path)
    $St.Timer.Start()
    Set-TbStatus $St.Status 'Hashing...'
}

function Update-FileHashJob($St) {
    $j = $St.Job
    if (-not $j) { $St.Timer.Stop(); return }
    if ($j.Size -gt 0) { $St.Progress.Value = [int][Math]::Min(100, $j.Read * 100 / $j.Size) }
    if (-not $j.Done) { return }
    $St.Timer.Stop(); $St.Progress.Visible = $false
    if ($j.Error) { Set-TbStatus $St.Status $j.Error 'error'; return }
    $St.Rows['MD5'].Text = $j.Md5; $St.Rows['SHA-1'].Text = $j.Sha1; $St.Rows['SHA-256'].Text = $j.Sha256; $St.Rows['SHA-512'].Text = $j.Sha512
    $St.File.Text = "$($j.Path)   ($(Format-Size $j.Size))"
    Set-TbStatus $St.Status 'Done' 'ok'
    Update-HashVerdict $St
}

function Update-HashVerdict($St) {
    $want = ($St.Expected.Text -replace '[\s:-]', '').ToLower()
    foreach ($v in $St.Rows.Values) { $v.BackColor = $C.Card }
    if (-not $want) { $St.Verdict.Text = ''; return }
    $hit = $null
    foreach ($k in $St.Rows.Keys) { if ($St.Rows[$k].Text -and $St.Rows[$k].Text -eq $want) { $hit = $k } }
    if ($hit) { $St.Rows[$hit].BackColor = [PowerClipTheme]::Mix($C.Bg, $C.Green, 0.25); $St.Verdict.Text = "Match: the $hit is identical."; $St.Verdict.ForeColor = $C.Green }
    elseif (($St.Rows.Values | Where-Object { $_.Text }).Count -eq 0) { $St.Verdict.Text = 'Choose a file to compare.'; $St.Verdict.ForeColor = $C.Dim }
    else { $St.Verdict.Text = 'No match - the file is different (or the checksum is for another file).'; $St.Verdict.ForeColor = $C.Red }
}

# ======================================================================================
# Ports: what is listening / connected, with the process behind it.
# ======================================================================================
Register-ToolboxPage 'ports' 'Ports' $Glyph.Network 'ports listening netstat process kill tcp udp who uses port' {
    param($panel, $st)
    foreach ($kv in (@{ Rows = @() }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore
    foreach ($col in @(@('Proto', 70), @('Local address', 170), @('Port', 70), @('Remote', 210), @('State', 120), @('PID', 70), @('Process', 200))) { [void]$lv.Columns.Add($col[0], (Px ($col[1] * $TextZoom))) }
    $lv.add_ColumnClick({ param($src, $e) $s = $TbUI.Pages['ports'].State; $s.SortCol = $e.Column; $s.SortDesc = -not $s.SortDesc; Update-PortsList $s })
    $panel.Controls.Add($lv)
    $st.List = $lv
    $menu = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    [void](Add-MenuItem $menu 'Copy row' { $s = $TbUI.Pages['ports'].State; if ($s.List.SelectedItems.Count) { $it = $s.List.SelectedItems[0]; Copy-TbText (($it.SubItems | ForEach-Object { $_.Text }) -join "`t") } } $Glyph.Copy)
    [void](Add-MenuItem $menu 'Show the program file' { $s = $TbUI.Pages['ports'].State; if ($s.List.SelectedItems.Count) { $p = Get-Process -Id ([int]$s.List.SelectedItems[0].SubItems[5].Text) -ErrorAction SilentlyContinue; if ($p -and $p.Path) { Start-Process explorer.exe "/select,`"$($p.Path)`"" } } } $Glyph.Open)
    [void](Add-MenuItem $menu 'Test this port in Network tools' { $s = $TbUI.Pages['ports'].State; if ($s.List.SelectedItems.Count) { $it = $s.List.SelectedItems[0]; $st2 = Show-Network '127.0.0.1'; if ($st2 -and $st2.PortBox) { $st2.PortBox.Text = $it.SubItems[2].Text } } } $Glyph.Network)
    [void]$menu.Items.Add('-')
    [void](Add-MenuItem $menu 'End this process...' {
        $s = $TbUI.Pages['ports'].State
        if (-not $s.List.SelectedItems.Count) { return }
        $it = $s.List.SelectedItems[0]
        $procId = [int]$it.SubItems[5].Text; $name = $it.SubItems[6].Text
        if ($procId -le 4) { [void][System.Windows.Forms.MessageBox]::Show($TbUI.Form, 'That is a Windows system process.', 'Ports'); return }
        if ([System.Windows.Forms.MessageBox]::Show($TbUI.Form, "End $name (PID $procId)? Unsaved work in it is lost.", 'Ports', 'YesNo', 'Warning') -ne 'Yes') { return }
        try { Stop-Process -Id $procId -Force -ErrorAction Stop; Set-TbStatus $s.Status "Ended $name ($procId)." 'ok' } catch { Set-TbStatus $s.Status "Could not end it: $($_.Exception.Message) (try running DevTools as administrator)" 'error' }
        Start-Sleep -Milliseconds 300
        Update-PortsList $s -Reload
    } $Glyph.Delete)
    $lv.ContextMenuStrip = $menu
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Filter' -Dim | Out-Null
    $st.Filter = New-TbBox -Cue 'port, process or address  (e.g. 8080, node, 443)'
    $st.Filter.Width = Px (300 * $TextZoom); $st.Filter.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $bar.Controls.Add($st.Filter)
    $st.Listening = New-CheckBox $bar 'Listening only' $true 'Hide outgoing connections'
    [void](New-Button 'Refresh' 'Read the port table again (F5)' { Update-PortsList $TbUI.Pages['ports'].State -Reload } $bar $Glyph.Refresh 1)
    $st.Filter.add_TextChanged({ Update-PortsList $TbUI.Pages['ports'].State })
    $st.Listening.add_CheckedChanged({ Update-PortsList $TbUI.Pages['ports'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['ports'].State; $s.Filter.Text = $t.Trim(); Update-PortsList $s -Reload }
    $st.Focus = { $s = $TbUI.Pages['ports'].State; Update-PortsList $s -Reload; $s.Filter.Focus() }
    $st.SortCol = 2; $st.SortDesc = $false
    $st
}

function Update-PortsList($St, [switch]$Reload) {
    if ($Reload -or -not $St.Rows) {
        $names = @{}
        foreach ($p in Get-Process) { $names[$p.Id] = $p.ProcessName }
        $St.Rows = foreach ($e in [DevPorts]::List()) {
            [pscustomobject]@{ Proto = $e.Proto; Local = $e.LocalAddress; Port = $e.LocalPort; Remote = $(if ($e.RemoteAddress -and $e.RemotePort) { "$($e.RemoteAddress):$($e.RemotePort)" } else { '' })
                               State = $e.State; Pid = $e.Pid; Process = $(if ($names.ContainsKey($e.Pid)) { $names[$e.Pid] } elseif ($e.Pid -eq 4) { 'System' } else { '?' }) }
        }
        $St.Loaded = Get-Date
    }
    $q = $St.Filter.Text.Trim()
    $rows = @($St.Rows | Where-Object {
        (-not $St.Listening.Checked -or $_.State -eq 'LISTENING' -or $_.Proto -like 'UDP*') -and
        (-not $q -or [string]$_.Port -eq $q -or $_.Process -like "*$q*" -or $_.Local -like "*$q*" -or $_.Remote -like "*$q*" -or [string]$_.Pid -eq $q)
    })
    $prop = @('Proto', 'Local', 'Port', 'Remote', 'State', 'Pid', 'Process')[$St.SortCol]
    $rows = @($rows | Sort-Object -Property @{ Expression = $prop; Descending = [bool]$St.SortDesc }, Port)
    $lv = $St.List
    $lv.BeginUpdate(); $lv.Items.Clear()
    foreach ($r in $rows | Select-Object -First 2000) {
        $it = New-Object System.Windows.Forms.ListViewItem($r.Proto)
        foreach ($v in $r.Local, $r.Port, $r.Remote, $r.State, $r.Pid, $r.Process) { [void]$it.SubItems.Add([string]$v) }
        [void]$lv.Items.Add($it)
    }
    $lv.EndUpdate()
    Set-TbStatus $St.Status "$($rows.Count) shown of $(@($St.Rows).Count)  $Dot  read at $($St.Loaded.ToString('HH:mm:ss'))  $Dot  right-click a row to end its process" $(if ($q -and $rows.Count -eq 0) { 'warn' } else { '' })
}

# ======================================================================================
# Certificates: TLS certificate of a server (expiry, names, chain, protocol).
# ======================================================================================
Register-ToolboxPage 'cert' 'Certificates' $Glyph.Lock 'ssl tls certificate https expiry expires chain san check' {
    param($panel, $st)
    foreach ($kv in (@{ Job = $null }).GetEnumerator()) { $st[$kv.Key] = $kv.Value }
    $st.Status = New-TbPage $panel
    $st.Out = New-TbRtb -ReadOnly; $st.Out.Dock = 'Fill'; $st.Out.WordWrap = $true
    $panel.Controls.Add($st.Out)
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Host' -Title | Out-Null
    $st.HostBox = New-TbBox -Cue 'example.com  or  https://example.com:8443/path'
    $st.HostBox.Width = Px (340 * $TextZoom); $st.HostBox.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $bar.Controls.Add($st.HostBox)
    New-TbLabel $bar 'Port' -Dim | Out-Null
    $st.Port = New-TbNumber $bar 443 1 65535
    [void](New-Button 'Check' 'Connect and read the certificate (Enter)' { Start-CertCheck $TbUI.Pages['cert'].State } $bar $Glyph.Lock 1)
    $st.HostBox.add_KeyDown({ param($src, $e) if ($e.KeyCode -eq 'Return') { Start-CertCheck $TbUI.Pages['cert'].State; $e.SuppressKeyPress = $true } })
    $st.Timer = New-Object System.Windows.Forms.Timer
    $st.Timer.Interval = 150
    $st.Timer.add_Tick({ Update-CertCheck $TbUI.Pages['cert'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['cert'].State; $s.HostBox.Text = $t.Trim(); Start-CertCheck $s }
    $st.Focus = { $TbUI.Pages['cert'].State.HostBox.Focus() }
    $st.Close = { $s = $TbUI.Pages['cert'].State; $s.Timer.Stop(); $s.Timer.Dispose() }
    Set-TbStatus $st.Status 'Only the TLS handshake is done; nothing else is sent to the server.'
    $st
}

function Start-CertCheck($St) {
    $t = $St.HostBox.Text.Trim()
    if (-not $t) { return }
    $port = [int]$St.Port.Value
    if ($t -match '^(?:[a-z]+://)?([^/:\s]+)(?::(\d+))?') {
        $h = $Matches[1]
        if ($Matches[2]) { $port = [int]$Matches[2]; $St.Port.Value = $port }
    } else { return }
    $St.Out.Clear()
    Add-RtbLine $St.Out "Connecting to $h`:$port ..." $C.Dim
    $St.Job = [DevCertCheck]::Start($h, $port, 8000)
    $St.Timer.Start()
    Set-TbStatus $St.Status 'Checking...'
}

function Update-CertCheck($St) {
    $j = $St.Job
    if (-not $j -or -not $j.Done) { return }
    $St.Timer.Stop()
    $o = $St.Out; $o.Clear()
    $cx = $j.Certificate
    if (-not $cx) { Add-RtbLine $o "Could not get a certificate from $($j.Host):$($j.Port)" $C.Red -Bold; Add-RtbLine $o $j.Error; Set-TbStatus $St.Status 'Failed' 'error'; return }
    $days = [Math]::Floor(($cx.NotAfter - (Get-Date)).TotalDays)
    $ok = -not $j.PolicyErrors -and $days -ge 0
    if ($days -lt 0) { Add-RtbLine $o "EXPIRED $(-$days) days ago" $C.Red -Bold }
    elseif ($j.PolicyErrors) { Add-RtbLine $o "PROBLEM: $($j.PolicyErrors)" $C.Red -Bold }
    elseif ($days -lt 21) { Add-RtbLine $o "Valid, but expires in $days days" $C.Yellow -Bold }
    else { Add-RtbLine $o "Valid  -  expires in $days days" $C.Green -Bold }
    Add-RtbLine $o ''
    $rows = [ordered]@{
        'Host'        = "$($j.Host):$($j.Port)"
        'Subject'     = $cx.Subject
        'Issuer'      = $cx.Issuer
        'Valid from'  = $cx.NotBefore.ToString('yyyy-MM-dd HH:mm')
        'Valid until' = "$($cx.NotAfter.ToString('yyyy-MM-dd HH:mm'))   ($days days)"
        'Names (SAN)' = ([DevCertCheck]::SubjectAltNames($cx) -join ', ')
        'Key'         = "$($cx.PublicKey.Oid.FriendlyName) $(try { $cx.PublicKey.Key.KeySize } catch { '' }) bit"
        'Signature'   = $cx.SignatureAlgorithm.FriendlyName
        'Serial'      = $cx.SerialNumber
        'SHA-1 thumbprint' = $cx.Thumbprint
        'Protocol'    = $j.Protocol
        'Cipher'      = $j.Cipher
        'Handshake'   = "$($j.ElapsedMs) ms"
    }
    foreach ($k in $rows.Keys) { if ($rows[$k]) { Add-RtbLine $o ("{0,-17} {1}" -f $k, $rows[$k]) } }
    if ($j.Error) { Add-RtbLine $o ''; Add-RtbLine $o "Note: $($j.Error)" $C.Yellow }
    Add-RtbLine $o ''
    Add-RtbLine $o 'CHAIN' $C.Accent -Bold
    $i = 0
    foreach ($el in $j.Chain) {
        Add-RtbLine $o ("{0}{1}" -f ('  ' * $i), $el[0]) $(if ($el[3]) { $C.Red } else { $null })
        Add-RtbLine $o ("{0}  until {1}{2}" -f ('  ' * $i), $el[2], $(if ($el[3]) { "  -  $($el[3])" } else { '' })) $C.Dim
        $i++
    }
    $o.SelectionStart = 0; $o.ScrollToCaret()
    Set-TbStatus $St.Status $(if ($ok) { "Certificate OK, $days days left" } else { 'Certificate has problems' }) $(if ($ok) { if ($days -lt 21) { 'warn' } else { 'ok' } } else { 'error' })
}

# ======================================================================================
# Host monitor: keeps an eye on servers (ping or TCP port) and tells you when one goes down.
# ======================================================================================
$HostsFile = Join-Path $DataDir 'hosts.json'
$HostMon = New-Object DevHostMonitor
$script:HostTargets = New-Object System.Collections.Generic.List[object]
$script:HostSilence = @{}              # host id -> silenced until (DateTime.MaxValue = until turned back on)
if ($null -eq $script:HostFolders) { $script:HostFolders = @() }
if ($null -eq $script:HostCollapsed) { $script:HostCollapsed = @() }

$script:HostsLoadFailed = $false

# A host from saved / imported data ($null when it has no host name).
function ConvertTo-HostTarget($X, [switch]$NewId) {
    if (-not $X -or -not $X.Host) { return $null }
    $t = New-Object DevHostTarget
    $t.Id = if ($X.Id -and -not $NewId) { [string]$X.Id } else { [guid]::NewGuid().ToString('N') }
    $t.Name = [string]$X.Name; $t.Host = ([string]$X.Host).Trim(); $t.Ports = [string]$X.Ports; $t.Folder = [string]$X.Folder
    $p = 0; if ([int]::TryParse([string]$X.Port, [ref]$p)) { $t.Port = $p }
    $t
}

function Import-MonitoredHosts {
    if (-not (Test-Path $HostsFile)) { return }
    try { $items = @(ConvertFrom-JsonList (Read-DataText $HostsFile)) }
    catch {
        # unreadable: leave the file alone (no saving over it) and keep a copy of it
        $script:HostsLoadFailed = $true
        Write-Log "hosts load failed: $_"
        try { Copy-Item -LiteralPath $HostsFile -Destination ($HostsFile + '.unreadable-' + (Get-Date).ToString('yyyyMMdd-HHmmss')) -Force } catch { }
        return
    }
    foreach ($x in $items) {
        try {
            $t = ConvertTo-HostTarget $x
            if (-not $t) { continue }
            if ($x.SilencedUntil) { try { $script:HostSilence[$t.Id] = [datetime]::Parse([string]$x.SilencedUntil, $null, [Globalization.DateTimeStyles]::RoundtripKind) } catch { } }
            $script:HostTargets.Add($t)
        } catch { Write-Log "host skipped: $_" }
    }
    # the last list that loaded, in case something goes wrong later
    if ($script:HostTargets.Count) { try { Copy-Item -LiteralPath $HostsFile -Destination ($HostsFile + '.bak') -Force } catch { } }
}

# ---- Host alerts: a popup in the bottom-right corner for a few seconds; hosts can be silenced.
$script:HostAlerts = New-Object System.Collections.Generic.List[object]

function Test-HostSilenced($T) {
    $u = $script:HostSilence[$T.Id]
    if (-not $u) { return $false }
    if ($u -le (Get-Date)) { $script:HostSilence.Remove($T.Id); Save-MonitoredHosts; return $false }
    $true
}

function Set-HostSilence($T, $Until) {
    if ($Until) { $script:HostSilence[$T.Id] = $Until } else { $script:HostSilence.Remove($T.Id) }
    Save-MonitoredHosts
    $p = $TbUI.Pages['hosts']; if ($p -and $p.State) { $p.State.List.Invalidate() }
}

function Get-HostSilenceText($T) {
    $u = $script:HostSilence[$T.Id]
    if (-not $u) { return '' }
    if ($u -eq [datetime]::MaxValue) { 'alerts off' } else { "silenced until $($u.ToString('HH:mm'))" }
}

# Moves the open alerts up from the bottom-right corner, newest at the bottom.
function Set-HostAlertPositions {
    $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
    $y = $wa.Bottom - (Px 12)
    for ($i = $script:HostAlerts.Count - 1; $i -ge 0; $i--) {
        $f = $script:HostAlerts[$i]
        $y -= $f.Height
        $f.Location = New-Object System.Drawing.Point(($wa.Right - $f.Width - (Px 12)), $y)
        $y -= Px 8
    }
}

function Close-HostAlert($F) {
    if (-not $F -or $F.IsDisposed) { return }
    [void]$script:HostAlerts.Remove($F)
    $F.Tag.Timer.Dispose()
    $F.Close(); $F.Dispose()
    Set-HostAlertPositions
}

function Show-HostAlert($T, [bool]$Down) {
    $label = if ($T.Name) { $T.Name } else { $T.Host }
    $target = Get-HostTargetText $T
    $accent = if ($Down) { $C.Red } else { $C.Green }
    $f = New-Object PowerClipToast
    $f.BackColor = $C.Card; $f.ForeColor = $C.Fore; $f.Font = $FontMain
    $f.Size = New-Object System.Drawing.Size((Px 380), (Px 112))
    $f.Padding = New-Object System.Windows.Forms.Padding((Px 18), (Px 10), (Px 10), (Px 8))
    $title = New-Object System.Windows.Forms.Label
    $title.AutoSize = $false; $title.Dock = 'Top'; $title.Height = $FontTitle.Height + (Px 4)
    $title.Font = New-Object System.Drawing.Font($UiFont, (Fz 11), [System.Drawing.FontStyle]::Bold); $title.ForeColor = $accent
    $title.Text = if ($Down) { "$label is DOWN" } else { "$label is back up" }
    $body = New-Object System.Windows.Forms.Label
    $body.AutoSize = $false; $body.Dock = 'Top'; $body.Font = $FontSmall; $body.ForeColor = $C.Dim
    $body.Text = if ($Down) { "$target - $($T.Detail)`n$((Get-Date).ToString('HH:mm:ss'))" } else { "$target answers again ($($T.LatencyMs) ms)`n$((Get-Date).ToString('HH:mm:ss'))" }
    $bodyW = (Px 380) - (Px 28)
    $body.Height = [System.Windows.Forms.TextRenderer]::MeasureText($body.Text, $FontSmall, (New-Object System.Drawing.Size($bodyW, 0)), [System.Windows.Forms.TextFormatFlags]'WordBreak').Height + (Px 6)
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel
    $btns.Dock = 'Bottom'; $btns.Height = $FontButton.Height + (Px 12); $btns.WrapContents = $false; $btns.BackColor = $C.Card
    $btns.Margin = New-Object System.Windows.Forms.Padding(0)
    $f.Controls.AddRange(@($btns, $body, $title))      # docked from the last: title at the top, buttons at the bottom
    $ctx = @{ Host = $T; Timer = $null; Left = 9000 }
    $f.Tag = $ctx
    $mk = {
        param($text, $tip, $action, $variant)
        $b = New-Button $text $tip $action $btns '' $variant
        $b.Margin = New-Object System.Windows.Forms.Padding(0, 0, (Px 4), 0)
        $b.Tag = $f
        $b
    }
    [void](& $mk 'Silence 1 hour' 'No alerts for this host for an hour' { param($src, $e) $x = $src.Tag; Set-HostSilence $x.Tag.Host ((Get-Date).AddHours(1)); Close-HostAlert $x } 2)
    [void](& $mk 'Silence' 'No more alerts for this host until you turn them back on (Host monitor, right-click)' { param($src, $e) $x = $src.Tag; Set-HostSilence $x.Tag.Host ([datetime]::MaxValue); Close-HostAlert $x } 2)
    [void](& $mk 'Open' 'Open the host monitor' { param($src, $e) $x = $src.Tag; Close-HostAlert $x; Show-Toolbox 'hosts' } 2)
    [void](& $mk 'Close' '' { param($src, $e) Close-HostAlert $src.Tag } 2)
    # tall enough for the title, the text and the buttons (nothing cut off)
    $bh = 0; foreach ($bb in $btns.Controls) { $bh = [Math]::Max($bh, $bb.PreferredSize.Height + $bb.Margin.Vertical) }
    $btns.Height = $bh + (Px 2)
    $f.ClientSize = New-Object System.Drawing.Size($f.ClientSize.Width, ($f.Padding.Top + $title.Height + $body.Height + (Px 6) + $btns.Height + $f.Padding.Bottom))
    $f.add_Paint({
        param($src, $e)
        $b = New-Object System.Drawing.SolidBrush $(if ($src.Tag.Down) { $C.Red } else { $C.Green })
        $e.Graphics.FillRectangle($b, 0, 0, (Px 6), $src.Height); $b.Dispose()
        $p = New-Object System.Drawing.Pen $C.Line; $e.Graphics.DrawRectangle($p, 0, 0, ($src.Width - 1), ($src.Height - 1)); $p.Dispose()
    })
    $ctx.Down = $Down
    # closes by itself after a few seconds; pointing at it keeps it open
    $tm = New-Object System.Windows.Forms.Timer
    $tm.Interval = 250
    $tm.Tag = $f
    $tm.add_Tick({
        param($src, $e)
        $x = $src.Tag
        if (-not $x -or $x.IsDisposed) { $src.Stop(); return }
        if ($x.Bounds.Contains([System.Windows.Forms.Cursor]::Position)) { return }
        $x.Tag.Left -= $src.Interval
        if ($x.Tag.Left -le 0) { $src.Stop(); Close-HostAlert $x }
    })
    $ctx.Timer = $tm
    # one alert per host: a newer one replaces the older
    foreach ($old in @($script:HostAlerts.ToArray())) { if ($old.Tag.Host.Id -eq $T.Id) { Close-HostAlert $old } }
    $script:HostAlerts.Add($f)
    while ($script:HostAlerts.Count -gt 5) { Close-HostAlert $script:HostAlerts[0] }
    Set-HostAlertPositions
    $f.Show()
    $tm.Start()
    if ($Down) { [System.Media.SystemSounds]::Exclamation.Play() }
    $f
}

function Save-MonitoredHosts {
    if ($script:NoSave -or $script:HostsLoadFailed) { return }
    $json = ConvertTo-Json -InputObject @($script:HostTargets | ForEach-Object {
        $u = $script:HostSilence[$_.Id]
        [ordered]@{ Id = $_.Id; Name = $_.Name; Host = $_.Host; Port = $_.Port; Ports = [string]$_.Ports; Folder = [string]$_.Folder; SilencedUntil = $(if ($u) { $u.ToString('o') } else { $null }) } }) -Depth 3
    try { Write-JsonFile $HostsFile $json } catch { Write-Log "hosts save failed: $_" }
}

# Export: the hosts and folders as a JSON file (not encrypted) to keep, share or load on another PC.
# A message after export / import (or, with -Quiet, just the text back).
function Show-HostsMessage([bool]$Quiet, [string]$Text, [string]$Title) { if ($Quiet) { $Text } else { [void][System.Windows.Forms.MessageBox]::Show($TbUI.Form, $Text, $Title) } }

function Export-MonitoredHosts([string]$Path = '', [switch]$Quiet) {
    if ($Path) { $path = $Path } else {
    $d = New-Object System.Windows.Forms.SaveFileDialog
    $d.Filter = 'DevTools hosts|*.json|All files|*.*'; $d.FileName = "devtools-hosts-$((Get-Date).ToString('yyyy-MM-dd')).json"
    $script:Modal = $true
    try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { return }; $path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    }
    $o = [ordered]@{
        DevToolsHosts = 1
        Folders = @(Get-HostFolderPaths)
        Hosts = @($script:HostTargets | ForEach-Object { [ordered]@{ Name = [string]$_.Name; Host = [string]$_.Host; Port = $_.Port; Ports = [string]$_.Ports; Folder = [string]$_.Folder } })
    }
    try { [IO.File]::WriteAllText($path, (ConvertTo-Json -InputObject $o -Depth 4), (New-Object System.Text.UTF8Encoding $false)) }
    catch { Show-HostsMessage $Quiet "Couldn't write the file: $($_.Exception.Message)" 'Export hosts'; return }
    Show-HostsMessage $Quiet "Exported $($script:HostTargets.Count) host(s) to $(Split-Path -Leaf $path)." 'Export hosts'
}

# Import: adds the hosts of an exported file (also a plain list, or a text file with one host[:port] per line);
# ones you already have (same host, port(s) and folder) are skipped.
function Import-MonitoredHostsFile([string]$Path = '', [switch]$Quiet) {
    if (-not $Path) {
        $d = New-Object System.Windows.Forms.OpenFileDialog
        $d.Filter = 'DevTools hosts or a list|*.json;*.txt;*.csv|All files|*.*'
        $script:Modal = $true
        try { if ($d.ShowDialog($TbUI.Form) -ne 'OK') { return }; $Path = $d.FileName } finally { $script:Modal = $false; $d.Dispose() }
    }
    try { $text = Read-DataText $Path } catch { Show-HostsMessage $Quiet "Couldn't read the file: $($_.Exception.Message)" 'Import hosts'; return }
    $items = @(); $folders = @()
    if ($text.TrimStart().StartsWith('{') -or $text.TrimStart().StartsWith('[')) {
        try { $j = @(ConvertFrom-JsonList $text) } catch { Show-HostsMessage $Quiet "That isn't valid JSON: $($_.Exception.Message)" 'Import hosts'; return }
        if ($j.Count -eq 1 -and $j[0].PSObject.Properties['Hosts']) { $items = @($j[0].Hosts | ForEach-Object { $_ }); $folders = @($j[0].Folders | Where-Object { $_ }) }
        else { $items = $j }
    } else {
        # text: "host", "host:port", "name host:port" or "name,host,port" per line
        foreach ($line in ($text -split '\r?\n')) {
            $l = $line.Trim(); if (-not $l -or $l.StartsWith('#')) { continue }
            $f = @($l -split '\s*[,;\t]\s*|\s+' | Where-Object { $_ })
            $name = ''; $hp = $f[-1]; $port = ''
            if ($f.Count -ge 3 -and $f[-1] -match '^\d+$') { $name = $f[0]; $hp = $f[1]; $port = $f[2] } elseif ($f.Count -ge 2) { $name = $f[0]; if ($f[-1] -match '^\d+$' -and $f.Count -eq 2) { $name = ''; $hp = $f[0]; $port = $f[1] } }
            if ($hp -match '^(?:[a-z]+://)?\[?([^\]/\s]+?)\]?(?::(\d+))?(?:/.*)?$') { $hp = $Matches[1]; if ($Matches[2]) { $port = $Matches[2] } }
            $items += [pscustomobject]@{ Name = $name; Host = $hp; Port = $port; Ports = ''; Folder = '' }
        }
    }
    $have = @{}; foreach ($t in $script:HostTargets) { $have["$($t.Host)|$($t.Port)|$($t.Ports)|$($t.Folder)".ToLowerInvariant()] = $true }
    $added = 0; $skipped = 0
    foreach ($x in $items) {
        $t = ConvertTo-HostTarget $x -NewId
        if (-not $t) { continue }
        $k = "$($t.Host)|$($t.Port)|$($t.Ports)|$($t.Folder)".ToLowerInvariant()
        if ($have[$k]) { $skipped++; continue }
        $have[$k] = $true; $script:HostTargets.Add($t); $added++
    }
    $known = @(Get-HostFolderPaths)
    $script:HostFolders = @($known + @($folders | Where-Object { $known -notcontains [string]$_ } | ForEach-Object { [string]$_ }))
    $script:HostsLoadFailed = $false
    Save-MonitoredHosts; Save-Settings; Sync-HostMonitor
    if ($TbUI.Pages['hosts'] -and $TbUI.Pages['hosts'].State) { Update-HostsPage }
    $msg = "Added $added host(s)."; if ($skipped) { $msg += " $skipped you already had were skipped." }
    if (-not $added -and -not $skipped) { $msg = 'There were no hosts in that file.' }
    Show-HostsMessage $Quiet $msg 'Import hosts'
}

function Sync-HostMonitor {
    $list = New-Object 'System.Collections.Generic.List[DevHostTarget]'
    foreach ($t in $script:HostTargets) { $list.Add($t) }
    $HostMon.IntervalSec = $script:HostInterval
    $HostMon.Set($list)
    if ($list.Count -gt 0) { $HostMon.Start() } else { $HostMon.Stop() }
}

Import-MonitoredHosts
Sync-HostMonitor

# Watches for hosts going down / coming back, and refreshes the page.
$HostWatch = New-Object System.Windows.Forms.Timer
$HostWatch.Interval = 1500
$HostWatch.add_Tick({
    foreach ($t in $HostMon.TakeChanges()) {
        $label = if ($t.Name) { $t.Name } else { $t.Host }
        Write-Log "host $label is $($t.Status)"
        if ($script:HostNotify -and -not (Test-HostSilenced $t)) {
            try { [void](Show-HostAlert $t ($t.Status -eq 'down')) } catch { Write-Log "host alert failed: $_" }
        }
    }
    $p = $TbUI.Pages['hosts']
    if ($p -and $p.State -and $p.Panel.Visible) {
        # redraw only the rows whose state changed since the last look
        $l = $p.State.List
        if (-not $p.State.Sig) { $p.State.Sig = @{} }
        $rows = @($p.State.Rows)
        for ($i = 0; $i -lt $rows.Count -and $i -lt $l.Items.Count; $i++) {
            $rw = $rows[$i]
            if ($rw.Header) { $key = "f:$($rw.Folder)"; $sig = (@($rw.Hosts) | ForEach-Object { $_.Status }) -join ',' }
            else { $t = $rw.Host; $key = $t.Id; $sig = "$($t.Status)|$($t.LatencyMs)|$($t.LastCheck.Ticks)|$($t.Recent.Count)|$(Get-HostSilenceText $t)" }
            if ($p.State.Sig[$key] -ne $sig) { $p.State.Sig[$key] = $sig; $l.Invalidate($l.GetItemRectangle($i)) }
        }
    }
})
$HostWatch.Start()

# "server:443", "server: 22, 80, 443" or "server (ping)"
function Get-HostTargetText($T) {
    if ($T.Ports) { "$($T.Host): $($T.Ports)" } elseif ($T.Port) { "$($T.Host):$($T.Port)" } else { "$($T.Host) (ping)" }
}

function Show-HostDialog($Target) {
    $d = New-Object System.Windows.Forms.Form
    $d.Text = $(if ($Target) { 'Edit host' } else { 'Add host' }); $d.FormBorderStyle = 'FixedDialog'; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.StartPosition = 'CenterParent'; $d.ShowInTaskbar = $false; $d.BackColor = $C.Panel; $d.ForeColor = $C.Fore; $d.Font = $FontMain
    $d.ClientSize = New-Object System.Drawing.Size((Px (440 * $TextZoom)), ($FontMain.Height * 3 + (Px 150)))
    $tbl = New-Object System.Windows.Forms.TableLayoutPanel
    $tbl.Dock = 'Fill'; $tbl.ColumnCount = 2; $tbl.Padding = New-Object System.Windows.Forms.Padding((Px 14))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('AutoSize')))
    [void]$tbl.ColumnStyles.Add((New-Object System.Windows.Forms.ColumnStyle('Percent', 100)))
    $boxes = @{}
    $r = 0
    foreach ($f in @(@('Name', 'e.g. Web server'), @('Host', 'server name or IP'), @('Port(s)', '0 = ping;  443;  or several: 22, 80, 443'))) {
        $l = New-Object System.Windows.Forms.Label; $l.Text = $f[0]; $l.AutoSize = $true; $l.Margin = New-Object System.Windows.Forms.Padding(0, (Px 8), (Px 10), 0)
        $b = New-TbBox -Cue $f[1]; $b.Dock = 'Fill'; $b.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), 0, (Px 4))
        $tbl.Controls.Add($l, 0, $r); $tbl.Controls.Add($b, 1, $r); $boxes[$f[0]] = $b; $r++
    }
    if ($Target) { $boxes.Name.Text = $Target.Name; $boxes.Host.Text = $Target.Host; $boxes['Port(s)'].Text = $(if ($Target.Ports) { $Target.Ports } else { [string]$Target.Port }) } else { $boxes['Port(s)'].Text = '0' }
    $btns = New-Object System.Windows.Forms.FlowLayoutPanel
    $btns.FlowDirection = 'RightToLeft'; $btns.Dock = 'Fill'
    $cancel = New-Object PowerClipButton; $cancel.Text = 'Cancel'; $cancel.Font = $FontButton; $cancel.AutoSize = $true; $cancel.DialogResult = 'Cancel'
    $ok = New-Object PowerClipButton; $ok.Text = 'Save'; $ok.Variant = 1; $ok.Font = $FontButton; $ok.AutoSize = $true; $ok.DialogResult = 'OK'
    $btns.Controls.AddRange(@($cancel, $ok))
    $tbl.Controls.Add($btns, 1, $r)
    $d.Controls.Add($tbl)
    $d.AcceptButton = $ok; $d.CancelButton = $cancel
    Register-ThemedWindow $d
    $script:Modal = $true
    try { $res = $d.ShowDialog($TbUI.Form) } finally { $script:Modal = $false }
    $out = $null
    if ($res -eq 'OK' -and $boxes.Host.Text.Trim()) {
        $hostText = $boxes.Host.Text.Trim(); $port = 0
        if ($hostText -match '^(?:[a-z]+://)?([^/:\s]+)(?::(\d+))?') { $hostText = $Matches[1]; if ($Matches[2]) { $port = [int]$Matches[2] } }
        $plist = @($boxes['Port(s)'].Text -split '[,;\s]+' | ForEach-Object { $n = 0; if ([int]::TryParse($_, [ref]$n) -and $n -gt 0 -and $n -lt 65536) { $n } } | Select-Object -Unique)
        if ($plist.Count -ge 1) { $port = $plist[0] } elseif ($boxes['Port(s)'].Text.Trim() -eq '0') { $port = 0 }
        $out = @{ Name = $boxes.Name.Text.Trim(); Host = $hostText; Port = [Math]::Max(0, [Math]::Min(65535, $port)); Ports = $(if ($plist.Count -gt 1) { $plist -join ', ' } else { '' }) }
    }
    $d.Dispose()
    $out
}

Register-ToolboxPage 'hosts' 'Host monitor' $Glyph.Globe 'monitor uptime ping servers dashboard status up down' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $list = New-Object DevBufferedListBox
    $list.Dock = 'Fill'; $list.BorderStyle = 'None'; $list.DrawMode = 'OwnerDrawVariable'; $list.IntegralHeight = $false
    $list.ItemHeight = $FontMain.Height + $FontSmall.Height + (Px 22); $list.BackColor = $C.Bg; $list.ForeColor = $C.Fore
    $list.add_MeasureItem({
        param($src, $e)
        $s2 = $TbUI.Pages['hosts'].State
        $e.ItemHeight = if ($s2.Rows -and $e.Index -lt $s2.Rows.Count -and $s2.Rows[$e.Index].Header) { $FontMain.Height + (Px 16) } else { $FontMain.Height + $FontSmall.Height + (Px 22) }
    })
    $list.add_DrawItem({
        param($src, $e)
        $s2 = $TbUI.Pages['hosts'].State
        if ($e.Index -lt 0 -or -not $s2.Rows -or $e.Index -ge $s2.Rows.Count) { return }
        $row = $s2.Rows[$e.Index]
        $g = $e.Graphics; $r = $e.Bounds
        $sel = ($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0
        if ($row.Header) { Draw-HostFolderRow $g $r $row $sel; return }
        $t = $row.Host
        $b = New-Object System.Drawing.SolidBrush $(if ($sel) { $C.Sel } else { $C.Bg }); $g.FillRectangle($b, $r); $b.Dispose()
        if ($row.Depth) { $ind = $row.Depth * (Px 22); $r = New-Object System.Drawing.Rectangle(($r.X + $ind), $r.Y, ($r.Width - $ind), $r.Height) }
        $g.SmoothingMode = 'AntiAlias'
        $dotColor = switch ($t.Status) { 'up' { $C.Green } 'down' { $C.Red } default { $C.Dim } }
        $b = New-Object System.Drawing.SolidBrush $dotColor; $d = Px 12
        $g.FillEllipse($b, ($r.X + (Px 14)), ($r.Y + [int](($r.Height - $d) / 2)), $d, $d); $b.Dispose()
        $x = $r.X + (Px 38)
        $name = if ($t.Name) { $t.Name } else { $t.Host }
        $target = Get-HostTargetText $t
        [System.Windows.Forms.TextRenderer]::DrawText($g, $name, $FontMain, (New-Object System.Drawing.Rectangle($x, ($r.Y + (Px 6)), (Px 300), ($FontMain.Height + 2))), $C.Fore, $TextFlags)
        # latency + state text
        $state = switch ($t.Status) { 'up' { "$($t.LatencyMs) ms" } 'down' { "DOWN  $($t.Detail)" } default { 'checking...' } }
        $since = if ($t.LastChange -gt [datetime]::MinValue -and $t.Status -ne 'unknown') { "$(if ($t.Status -eq 'up') { 'up' } else { 'down' }) since $($t.LastChange.ToString('HH:mm'))" } else { '' }
        $mute = Get-HostSilenceText $t
        if ($mute) { $target += "   - $mute" }
        [System.Windows.Forms.TextRenderer]::DrawText($g, $target, $FontSmall, (New-Object System.Drawing.Rectangle($x, ($r.Y + (Px 8) + $FontMain.Height), (Px 300), ($FontSmall.Height + 2))), $(if ($mute) { $C.Yellow } else { $C.Dim }), $TextFlags)
        $sx = $r.X + (Px 350)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $state, $FontMain, (New-Object System.Drawing.Rectangle($sx, ($r.Y + (Px 6)), (Px 340), ($FontMain.Height + 2))), $dotColor, $TextFlags)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $since, $FontSmall, (New-Object System.Drawing.Rectangle($sx, ($r.Y + (Px 8) + $FontMain.Height), (Px 220), ($FontSmall.Height + 2))), $C.Dim, $TextFlags)
        # sparkline of recent latencies (red ticks = failures)
        $hist = @($t.Recent.ToArray())
        $gx = $r.X + (Px 710); $gw = [Math]::Max((Px 80), $r.Right - $gx - (Px 16)); $gy = $r.Y + (Px 8); $gh = $r.Height - (Px 16)
        if ($hist.Count -gt 1 -and $gw -gt 20) {
            $max = [Math]::Max(10, ($hist | Measure-Object -Maximum).Maximum)
            $step = $gw / 39.0
            $pts = New-Object System.Collections.Generic.List[System.Drawing.PointF]
            for ($i = 0; $i -lt $hist.Count; $i++) {
                $px = $gx + ($i + 40 - $hist.Count) * $step
                if ($hist[$i] -lt 0) { $pen = New-Object System.Drawing.Pen $C.Red, 2; $g.DrawLine($pen, [float]$px, [float]$gy, [float]$px, [float]($gy + $gh)); $pen.Dispose(); continue }
                $pts.Add((New-Object System.Drawing.PointF([float]$px, [float]($gy + $gh - $hist[$i] / $max * $gh))))
            }
            if ($pts.Count -gt 1) { $pen = New-Object System.Drawing.Pen $C.Accent, ([float](Px 2)); $g.DrawLines($pen, $pts.ToArray()); $pen.Dispose() }
        }
        $g.SmoothingMode = 'Default'
        $g.DrawLine($LinePen, $r.X, $r.Bottom - 1, $r.Right, $r.Bottom - 1)
    })
    $list.add_DoubleClick({ $rw = Get-HostSel; if ($rw -and -not $rw.Header) { Edit-MonitoredHost } })
    $list.add_MouseClick({ param($src, $e) if ($e.Button -ne 'Left') { return }; $i = $src.IndexFromPoint($e.Location); $s2 = $TbUI.Pages['hosts'].State; if ($i -ge 0 -and $i -lt $s2.Rows.Count -and $s2.Rows[$i].Header) { Switch-HostFolderOpen $s2.Rows[$i].Folder } })
    $list.add_KeyDown({
        param($src, $e)
        if ($e.Alt -and $e.KeyCode -eq 'Up') { Move-HostItem -1; $e.Handled = $true; $e.SuppressKeyPress = $true }
        elseif ($e.Alt -and $e.KeyCode -eq 'Down') { Move-HostItem 1; $e.Handled = $true; $e.SuppressKeyPress = $true }
        elseif ($e.KeyCode -eq 'Delete') { $rw = Get-HostSel; if ($rw -and $rw.Header) { Remove-HostFolder $rw.Folder } }
    })
    $hm = New-Object System.Windows.Forms.ContextMenuStrip -Property @{ Renderer = $MenuRenderer }
    $hm.add_Opening({
        param($src, $e)
        $src.Items.Clear()
        $row = Get-HostSel
        if (-not $row) {
            [void](Add-MenuItem $src 'New folder...' { New-HostFolder } $Glyph.Folder)
            return
        }
        if ($row.Header) {
            $src.Tag = $row.Folder
            [void](Add-MenuItem $src 'Add a host here...' { param($s2, $e2) Add-MonitoredHost $s2.Owner.Tag } $Glyph.Add)
            [void](Add-MenuItem $src $(if ($script:HostCollapsed -contains $row.Folder) { 'Open' } else { 'Close' }) { param($s2, $e2) Switch-HostFolderOpen $s2.Owner.Tag } $Glyph.Folder)
            [void](Add-MenuItem $src 'Move up  (Alt+Up)' { Move-HostItem -1 } $Glyph.Undo)
            [void](Add-MenuItem $src 'Move down  (Alt+Down)' { Move-HostItem 1 } $Glyph.Refresh)
            [void](Add-MenuItem $src 'New folder inside...' { param($s2, $e2) New-HostFolder $null $s2.Owner.Tag } $Glyph.Folder)
            [void](Add-MenuItem $src 'Rename folder...' { param($s2, $e2) Rename-HostFolder $s2.Owner.Tag } $Glyph.Edit)
            $mvf = New-Object System.Windows.Forms.ToolStripMenuItem('Move into', (New-GlyphImage $Glyph.Folder))
            $mvf.DropDown.Renderer = $MenuRenderer
            $it = $mvf.DropDownItems.Add('(top level)', $null, { param($s2, $e2) $f = $s2.OwnerItem.Owner.Tag; Rename-HostFolderPath $f ($f -split '/')[-1]; Save-HostLayout; Update-HostsPage $null "f:$(($f -split '/')[-1])" }); $it.Enabled = $row.Folder.Contains('/')
            foreach ($p in @(Get-HostFolderPaths)) {
                if ($p -eq $row.Folder -or $p.StartsWith("$($row.Folder)/") -or $p -eq (Get-HostFolderParent $row.Folder)) { continue }
                $it = $mvf.DropDownItems.Add(('    ' * ($p.Split('/').Count - 1)) + ($p -split '/')[-1], $null, { param($s2, $e2) $f = $s2.OwnerItem.Owner.Tag; $n = "$($s2.Tag)/$(($f -split '/')[-1])"; Rename-HostFolderPath $f $n; Save-HostLayout; Update-HostsPage $null "f:$n" })
                $it.Tag = $p
            }
            [void]$src.Items.Add($mvf)
            [void]$src.Items.Add('-')
            [void](Add-MenuItem $src 'Delete folder (keeps what is inside)...' { param($s2, $e2) Remove-HostFolder $s2.Owner.Tag } $Glyph.Delete)
            [void](Add-MenuItem $src 'New top-level folder...' { New-HostFolder } $Glyph.Folder)
            return
        }
        $t = $row.Host
        $src.Tag = $t
        [void](Add-MenuItem $src 'Move up  (Alt+Up)' { Move-HostItem -1 } $Glyph.Undo)
        [void](Add-MenuItem $src 'Move down  (Alt+Down)' { Move-HostItem 1 } $Glyph.Refresh)
        $mv = New-Object System.Windows.Forms.ToolStripMenuItem('Move to folder', (New-GlyphImage $Glyph.Folder))
        $mv.DropDown.Renderer = $MenuRenderer
        $it = $mv.DropDownItems.Add('(no folder)', $null, { param($s2, $e2) Set-HostFolder $s2.OwnerItem.Owner.Tag '' }); $it.Enabled = [bool]$t.Folder
        foreach ($f in @(Get-HostFolderPaths)) { $it = $mv.DropDownItems.Add(('    ' * ($f.Split('/').Count - 1)) + ($f -split '/')[-1], $null, { param($s2, $e2) Set-HostFolder $s2.OwnerItem.Owner.Tag $s2.Tag }); $it.Tag = $f; $it.Enabled = $f -ne $t.Folder }
        [void]$mv.DropDownItems.Add('-')
        [void]$mv.DropDownItems.Add('New folder...', $null, { param($s2, $e2) New-HostFolder $s2.OwnerItem.Owner.Tag $s2.OwnerItem.Owner.Tag.Folder })
        [void]$src.Items.Add($mv)
        [void]$src.Items.Add('-')
        if (Test-HostSilenced $t) { [void](Add-MenuItem $src "Turn alerts back on ($(Get-HostSilenceText $t))" { param($s2, $e2) Set-HostSilence $s2.Owner.Tag $null } $Glyph.Play) }
        else {
            [void](Add-MenuItem $src 'Silence for 1 hour' { param($s2, $e2) Set-HostSilence $s2.Owner.Tag ((Get-Date).AddHours(1)) } $Glyph.Pause)
            [void](Add-MenuItem $src 'Silence until tomorrow 8:00' { param($s2, $e2) Set-HostSilence $s2.Owner.Tag ((Get-Date).Date.AddDays(1).AddHours(8)) } $Glyph.Pause)
            [void](Add-MenuItem $src 'Silence (until I turn it back on)' { param($s2, $e2) Set-HostSilence $s2.Owner.Tag ([datetime]::MaxValue) } $Glyph.Pause)
        }
        [void](Add-MenuItem $src 'Show a test alert' { param($s2, $e2) [void](Show-HostAlert $s2.Owner.Tag ($s2.Owner.Tag.Status -ne 'up')) } $Glyph.View)
        [void]$src.Items.Add('-')
        [void](Add-MenuItem $src 'Edit...' { Edit-MonitoredHost } $Glyph.Edit)
    })
    $list.ContextMenuStrip = $hm
    $list.add_MouseDown({ param($src, $e) if ($e.Button -eq 'Right') { $i = $src.IndexFromPoint($e.Location); if ($i -ge 0) { $src.SelectedIndex = $i } else { $src.ClearSelected() } } })
    $panel.Controls.Add($list)
    $st.List = $list
    $bar = New-TbBar $panel
    [void](New-Button 'Add' 'Add a server to watch (into the selected folder)' { $rw = Get-HostSel; Add-MonitoredHost $(if ($rw) { $rw.Folder } else { '' }) } $bar $Glyph.Add 1)
    [void](New-Button 'Edit' 'Edit the selected server (or rename the folder)' { Edit-MonitoredHost } $bar $Glyph.Edit)
    [void](New-Button 'Remove' 'Stop watching the selected server (or delete the folder, keeping its hosts)' {
        $rw = Get-HostSel
        if (-not $rw) { return }
        if ($rw.Header) { Remove-HostFolder $rw.Folder; return }
        [void]$script:HostTargets.Remove($rw.Host); Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage
    } $bar $Glyph.Delete)
    [void](New-Button '' 'Move the selected host or folder up  (Alt+Up)' { Move-HostItem -1 } $bar ([string][char]0xE70E) 2)
    [void](New-Button '' 'Move the selected host or folder down  (Alt+Down)' { Move-HostItem 1 } $bar ([string][char]0xE70D) 2)
    [void](New-Button 'New folder' 'A folder for hosts (inside the selected folder); right-click a host > Move to folder' { $rw = Get-HostSel; New-HostFolder $null $(if ($rw -and $rw.Header) { $rw.Folder } else { '' }) } $bar $Glyph.Folder 2)
    [void](New-Button 'Check now' 'Check every server right away' { $HostMon.CheckNow = $true } $bar $Glyph.Refresh 2)
    [void](New-Button 'Export...' 'Save the hosts and folders to a file (to keep, share or load on another PC)' { Export-MonitoredHosts } $bar $Glyph.Save 2)
    [void](New-Button 'Import...' 'Add the hosts from an exported file, or a text file with one host[:port] per line (ones you already have are skipped)' { Import-MonitoredHostsFile } $bar $Glyph.Open 2)
    New-TbLabel $bar 'Every' -Dim | Out-Null
    $st.Every = New-TbCombo $bar @('10 seconds', '30 seconds', '1 minute', '5 minutes') 120
    $st.Every.SelectedIndex = switch ($script:HostInterval) { 10 { 0 } 60 { 2 } 300 { 3 } default { 1 } }
    $st.Every.add_SelectedIndexChanged({ param($src, $e) $script:HostInterval = @(10, 30, 60, 300)[$src.SelectedIndex]; Sync-HostMonitor; Save-Settings })
    $st.Notify = New-CheckBox $bar 'Alert me when one goes down or comes back (right-click a host to silence it)' $script:HostNotify
    $st.Notify.add_CheckedChanged({ param($src, $e) $script:HostNotify = $src.Checked; Save-Settings })
    $st.SetInput = { param($t) $r = $t.Trim(); if ($r) { $x = New-Object DevHostTarget; $x.Id = [guid]::NewGuid().ToString('N'); if ($r -match '^(?:[a-z]+://)?([^/:\s]+)(?::(\d+))?') { $x.Host = $Matches[1]; $x.Port = [int]$Matches[2] }; $script:HostTargets.Add($x); Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage } }
    Update-HostsPage $st
    $st
}

# ---- Host folders and order: hosts keep the order of the list; folders (in their own order, open or closed)
#      hold some of them. The page shows hosts without a folder first, then each folder with a summary.
function Get-HostFolderParent([string]$Path) { $i = $Path.LastIndexOf('/'); if ($i -gt 0) { $Path.Substring(0, $i) } else { '' } }

# Every folder path (parents included), in the user's order.
function Get-HostFolderPaths {
    $list = New-Object System.Collections.Generic.List[string]
    $add = { param($p) $parts = $p -split '/'; for ($k = 1; $k -le $parts.Count; $k++) { $q = ($parts[0..($k - 1)] -join '/'); if ($q -and -not $list.Contains($q)) { $list.Add($q) } } }
    foreach ($f in @($script:HostFolders)) { if ($f) { & $add $f } }
    foreach ($t in $script:HostTargets) { if ($t.Folder) { & $add $t.Folder } }
    $script:HostFolders = @($list)
    @($list)
}

function Get-HostRows {
    $paths = @(Get-HostFolderPaths)
    foreach ($t in $script:HostTargets) { if (-not $t.Folder) { [pscustomobject]@{ Header = $false; Host = $t; Folder = ''; Depth = 0 } } }
    $walk = $null
    $walk = {
        param($Parent, $Depth)
        foreach ($f in $paths) {
            if ((Get-HostFolderParent $f) -ne $Parent) { continue }
            $all = @($script:HostTargets | Where-Object { $_.Folder -eq $f -or $_.Folder.StartsWith("$f/") })
            [pscustomobject]@{ Header = $true; Folder = $f; Name = ($f -split '/')[-1]; Hosts = $all; Host = $null; Depth = $Depth }
            if ($script:HostCollapsed -notcontains $f) {
                foreach ($t in $script:HostTargets) { if ($t.Folder -eq $f) { [pscustomobject]@{ Header = $false; Host = $t; Folder = $f; Depth = $Depth + 1 } } }
                & $walk $f ($Depth + 1)
            }
        }
    }
    & $walk '' 0
}

function Get-HostSel {
    $s = $TbUI.Pages['hosts'].State
    if (-not $s -or -not $s.Rows) { return $null }
    $i = $s.List.SelectedIndex
    if ($i -ge 0 -and $i -lt $s.Rows.Count) { $s.Rows[$i] } else { $null }
}

# Rebuilds the list; Select = 'h:<host id>' or 'f:<folder>' to select that row again.
function Update-HostsPage($St = $null, [string]$Select = '') {
    if (-not $St) { $St = $TbUI.Pages['hosts'].State }
    if (-not $St) { return }
    if (-not $Select) { $cur = Get-HostSel; if ($cur) { $Select = if ($cur.Header) { "f:$($cur.Folder)" } else { "h:$($cur.Host.Id)" } } }
    $St.Rows = @(Get-HostRows)
    $St.Sig = @{}
    $l = $St.List
    $l.BeginUpdate()
    try {
        $l.Items.Clear()
        for ($i = 0; $i -lt $St.Rows.Count; $i++) { [void]$l.Items.Add($i) }
        for ($i = 0; $i -lt $St.Rows.Count; $i++) {
            $rw = $St.Rows[$i]
            if (($rw.Header -and $Select -eq "f:$($rw.Folder)") -or (-not $rw.Header -and $Select -eq "h:$($rw.Host.Id)")) { $l.SelectedIndex = $i; break }
        }
    } finally { $l.EndUpdate() }
    $n = $script:HostTargets.Count
    Set-TbStatus $St.Status $(if ($n) { "Watching $n server(s), also while this window is closed.  Alt+Up / Down moves the selection; right-click for folders." } else { 'Add the servers you care about; they are checked in the background and you get a notification when one goes down.' })
}

function Save-HostLayout { Save-MonitoredHosts; Save-Settings }

# Moves the selected host (within its folder) or folder one place up (-1) or down (1).
function Move-HostItem([int]$Dir) {
    $row = Get-HostSel
    if (-not $row) { return }
    if ($row.Header) {
        $f = @(Get-HostFolderPaths); $par = Get-HostFolderParent $row.Folder
        $sib = @(for ($k = 0; $k -lt $f.Count; $k++) { if ((Get-HostFolderParent $f[$k]) -eq $par) { $k } })
        $p = [array]::IndexOf($sib, [array]::IndexOf($f, $row.Folder)); $q = $p + $Dir
        if ($p -lt 0 -or $q -lt 0 -or $q -ge $sib.Count) { return }
        $a = $sib[$p]; $b = $sib[$q]; $x = $f[$a]; $f[$a] = $f[$b]; $f[$b] = $x; $script:HostFolders = $f
        Save-HostLayout; Update-HostsPage $null "f:$($row.Folder)"
        return
    }
    $t = $row.Host
    $same = @(for ($k = 0; $k -lt $script:HostTargets.Count; $k++) { if ([string]$script:HostTargets[$k].Folder -eq [string]$t.Folder) { $k } })
    $p = [array]::IndexOf($same, $script:HostTargets.IndexOf($t)); $q = $p + $Dir
    if ($p -lt 0 -or $q -lt 0 -or $q -ge $same.Count) { return }
    $a = $same[$p]; $b = $same[$q]
    $x = $script:HostTargets[$a]; $script:HostTargets[$a] = $script:HostTargets[$b]; $script:HostTargets[$b] = $x
    Save-HostLayout; Update-HostsPage $null "h:$($t.Id)"
}

function Set-HostFolder($T, [string]$Folder) {
    $T.Folder = $Folder
    if ($Folder -and $script:HostCollapsed -contains $Folder) { $script:HostCollapsed = @($script:HostCollapsed | Where-Object { $_ -ne $Folder }) }
    Save-HostLayout; Update-HostsPage $null "h:$($T.Id)"
}

function New-HostFolder($MoveHost = $null, [string]$Parent = '') {
    $name = Read-TextDialog 'New folder' $(if ($Parent) { "Folder name (inside $($Parent.Replace('/', ' > ')))" } else { 'Folder name (e.g. Production, Databases)' }) '' $TbUI.Form
    if (-not $name) { return }
    $name = ($name.Trim() -replace '[/\\]', '-')
    if ($Parent) { $name = "$Parent/$name" }
    if ($Parent -and $script:HostCollapsed -contains $Parent) { $script:HostCollapsed = @($script:HostCollapsed | Where-Object { $_ -ne $Parent }) }
    if (@($script:HostFolders) -notcontains $name) { $script:HostFolders = @($script:HostFolders) + $name }
    if ($MoveHost) { Set-HostFolder $MoveHost $name } else { Save-HostLayout; Update-HostsPage $null "f:$name" }
}

# A folder path renamed: the folder, its subfolders and the hosts in all of them.
function Rename-HostFolderPath([string]$Old, [string]$New) {
    $map = { param($p) if ($p -eq $Old) { $New } elseif ($p.StartsWith("$Old/")) { $New + $p.Substring($Old.Length) } else { $p } }
    foreach ($t in $script:HostTargets) { if ($t.Folder) { $t.Folder = & $map $t.Folder } }
    $script:HostFolders = @(@(Get-HostFolderPaths) | ForEach-Object { & $map $_ } | Select-Object -Unique)
    $script:HostCollapsed = @($script:HostCollapsed | ForEach-Object { & $map $_ })
}

function Rename-HostFolder([string]$Folder) {
    $leaf = ($Folder -split '/')[-1]
    $name = Read-TextDialog 'Rename folder' 'New name' $leaf $TbUI.Form
    if (-not $name -or $name.Trim() -eq $leaf) { return }
    $par = Get-HostFolderParent $Folder
    $name = ($name.Trim() -replace '[/\\]', '-'); if ($par) { $name = "$par/$name" }
    Rename-HostFolderPath $Folder $name
    Save-HostLayout; Update-HostsPage $null "f:$name"
}

function Remove-HostFolder([string]$Folder) {
    $n = @($script:HostTargets | Where-Object { $_.Folder -eq $Folder -or $_.Folder.StartsWith("$Folder/") }).Count
    $par = Get-HostFolderParent $Folder
    if ($n -and [System.Windows.Forms.MessageBox]::Show($TbUI.Form, "Delete the folder '$($Folder.Replace('/', ' > '))'? Its $n host(s) and subfolders move up one level.", 'Host monitor', 'YesNo', 'Question') -ne 'Yes') { return }
    $paths = @(Get-HostFolderPaths)
    $script:HostFolders = @($paths | Where-Object { $_ -ne $Folder })
    $script:HostCollapsed = @($script:HostCollapsed | Where-Object { $_ -ne $Folder })
    # what was inside goes to the parent: "A/B/C" without "B" -> "A/C"
    $up = { param($p) if ($p -eq $Folder) { $par } elseif ($p.StartsWith("$Folder/")) { $(if ($par) { "$par/" } else { '' }) + $p.Substring($Folder.Length + 1) } else { $p } }
    foreach ($t in $script:HostTargets) { if ($t.Folder) { $t.Folder = & $up $t.Folder } }
    $script:HostFolders = @($script:HostFolders | ForEach-Object { & $up $_ } | Where-Object { $_ } | Select-Object -Unique)
    Save-HostLayout; Update-HostsPage
}

function Switch-HostFolderOpen([string]$Folder) {
    if ($script:HostCollapsed -contains $Folder) { $script:HostCollapsed = @($script:HostCollapsed | Where-Object { $_ -ne $Folder }) }
    else { $script:HostCollapsed = @($script:HostCollapsed) + $Folder }
    Save-Settings; Update-HostsPage $null "f:$Folder"
}

function Draw-HostFolderRow($G, $R, $Row, [bool]$Sel) {
    $b = New-Object System.Drawing.SolidBrush $(if ($Sel) { $C.Sel } else { $C.Panel }); $G.FillRectangle($b, $R); $b.Dispose()
    $open = $script:HostCollapsed -notcontains $Row.Folder
    $hosts = @($Row.Hosts)
    $down = @($hosts | Where-Object { $_.Status -eq 'down' }).Count; $up = @($hosts | Where-Object { $_.Status -eq 'up' }).Count
    $x = $R.X + (Px 10) + $Row.Depth * (Px 22)
    if ($FontIconSmall) {
        [System.Windows.Forms.TextRenderer]::DrawText($G, $(if ($open) { [string][char]0xE70D } else { [string][char]0xE76C }), $FontIconSmall, (New-Object System.Drawing.Rectangle($x, $R.Y, (Px 20), $R.Height)), $C.Dim, [System.Windows.Forms.TextFormatFlags]'VerticalCenter, HorizontalCenter, NoPrefix, SingleLine')
    }
    $x += Px 26
    $G.SmoothingMode = 'AntiAlias'
    $dc = if ($down) { $C.Red } elseif ($hosts.Count -and $up -eq $hosts.Count) { $C.Green } else { $C.Dim }
    $b = New-Object System.Drawing.SolidBrush $dc; $d = Px 10
    $G.FillEllipse($b, $x, ($R.Y + [int](($R.Height - $d) / 2)), $d, $d); $b.Dispose()
    $G.SmoothingMode = 'Default'
    $x += Px 20
    if (-not $script:HostFolderFont) { $script:HostFolderFont = New-Object System.Drawing.Font($FontMain, [System.Drawing.FontStyle]::Bold) }
    $w = [System.Windows.Forms.TextRenderer]::MeasureText($Row.Name, $script:HostFolderFont).Width
    [System.Windows.Forms.TextRenderer]::DrawText($G, $Row.Name, $script:HostFolderFont, (New-Object System.Drawing.Rectangle($x, $R.Y, ($w + (Px 4)), $R.Height)), $C.Fore, [System.Windows.Forms.TextFormatFlags]'VerticalCenter, Left, NoPrefix, SingleLine')
    $sum = if (-not $hosts.Count) { 'empty - right-click a host > Move to folder' } else { "$($hosts.Count) host$(if ($hosts.Count -ne 1) { 's' })  $Dot  $up up$(if ($down) { "  $Dot  $down DOWN" })" }
    [System.Windows.Forms.TextRenderer]::DrawText($G, $sum, $FontSmall, (New-Object System.Drawing.Rectangle(($x + $w + (Px 14)), $R.Y, ($R.Right - $x - $w - (Px 20)), $R.Height)), $(if ($down) { $C.Red } else { $C.Dim }), [System.Windows.Forms.TextFormatFlags]'VerticalCenter, Left, NoPrefix, SingleLine, EndEllipsis')
    $G.DrawLine($LinePen, $R.X, $R.Bottom - 1, $R.Right, $R.Bottom - 1)
}

function Add-MonitoredHost([string]$Folder = '') {
    $r = Show-HostDialog $null
    if (-not $r) { return }
    $t = New-Object DevHostTarget; $t.Id = [guid]::NewGuid().ToString('N'); $t.Name = $r.Name; $t.Host = $r.Host; $t.Port = $r.Port; $t.Ports = $r.Ports; $t.Folder = $Folder
    if ($Folder -and $script:HostCollapsed -contains $Folder) { $script:HostCollapsed = @($script:HostCollapsed | Where-Object { $_ -ne $Folder }) }
    $script:HostTargets.Add($t); Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage $null "h:$($t.Id)"
}

function Edit-MonitoredHost {
    $row = Get-HostSel
    if (-not $row) { return }
    if ($row.Header) { Rename-HostFolder $row.Folder; return }
    $t = $row.Host
    $r = Show-HostDialog $t
    if (-not $r) { return }
    $t.Name = $r.Name; $t.Host = $r.Host; $t.Port = $r.Port; $t.Ports = $r.Ports; $t.Status = 'unknown'; $t.Recent.Clear()
    Save-MonitoredHosts; Sync-HostMonitor; Update-HostsPage
}

# ======================================================================================
# Number bases: decimal / hex / binary / octal, two's complement, bytes, as time / IP / colour.
# ======================================================================================
Register-ToolboxPage 'numbers' 'Number bases' $Glyph.Code 'number base convert hex binary octal decimal two complement bits bytes endian' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $st.Output = New-TbRtb -ReadOnly; $st.Output.Dock = 'Fill'
    $st.Output.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $panel.Controls.Add($st.Output)
    $bar = New-TbBar $panel
    New-TbLabel $bar 'Number' -Dim | Out-Null
    $st.Input = New-TbBox -Mono -Cue '255   0xFF   0b1010   0o17   -1   #ff8800'
    $st.Input.Width = Px (320 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $st.Input.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $bar.Controls.Add($st.Input)
    New-TbLabel $bar 'is in' -Dim | Out-Null
    $st.Base = New-TbCombo $bar @('Auto (0x, 0b, 0o prefix)', 'Decimal', 'Hex', 'Binary', 'Octal') 190
    [void](New-Button 'Copy' 'Copy the selected line, or everything' {
        $s = $TbUI.Pages['numbers'].State
        $t = if ($s.Output.SelectionLength -gt 0) { $s.Output.SelectedText } else { $s.Output.Text }
        Copy-TbText $t
    } $bar $Glyph.Copy 1)
    $st.Input.add_TextChanged({ Update-NumberTool $TbUI.Pages['numbers'].State })
    $st.Base.add_SelectedIndexChanged({ Update-NumberTool $TbUI.Pages['numbers'].State })
    $st.SetInput = { param($t) $s = $TbUI.Pages['numbers'].State; $s.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['numbers'].State.Input.Focus() }
    Set-TbStatus $st.Status 'Type a number in any base. Negative numbers show their two''s complement. Big numbers are fine.'
    $st
}

function Update-NumberTool($St) {
    $t = $St.Input.Text
    if (-not $t.Trim()) { $St.Output.Text = ''; return }
    $b = @(0, 10, 16, 2, 8)[$St.Base.SelectedIndex]
    try {
        $rows = [DevNum]::Describe($t, $b) -split "`n"
        $w = ($rows | ForEach-Object { ($_ -split "`t")[0].Length } | Measure-Object -Maximum).Maximum + 3
        $St.Output.Text = ($rows | ForEach-Object { $p = $_ -split "`t", 2; $p[0].PadRight($w) + $p[1] }) -join "`n"
        Set-TbStatus $St.Status 'Select a line and press Copy (or Ctrl+C) to copy just that value.'
    } catch {
        $m = if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message }
        $St.Output.Text = ''; Set-TbStatus $St.Status $m 'error'
    }
}

# ======================================================================================
# Units: length, weight, data size, time, speed, area, volume, temperature, pressure, energy.
# ======================================================================================
$UnitTable = [ordered]@{
    'Length'      = [ordered]@{ 'mm' = 0.001; 'cm' = 0.01; 'm' = 1; 'km' = 1000; 'in' = 0.0254; 'ft' = 0.3048; 'yd' = 0.9144; 'mi' = 1609.344; 'nautical mi' = 1852 }
    'Weight'      = [ordered]@{ 'mg' = 0.000001; 'g' = 0.001; 'kg' = 1; 't' = 1000; 'oz' = 0.028349523125; 'lb' = 0.45359237; 'st' = 6.35029318 }
    'Data size'   = [ordered]@{ 'bit' = 0.125; 'B' = 1; 'KB' = 1e3; 'MB' = 1e6; 'GB' = 1e9; 'TB' = 1e12; 'KiB' = 1024; 'MiB' = 1048576; 'GiB' = 1073741824; 'TiB' = 1099511627776 }
    'Data rate'   = [ordered]@{ 'bit/s' = 1; 'kbit/s' = 1e3; 'Mbit/s' = 1e6; 'Gbit/s' = 1e9; 'B/s' = 8; 'KB/s' = 8e3; 'MB/s' = 8e6; 'GB/s' = 8e9 }
    'Time'        = [ordered]@{ 'ms' = 0.001; 's' = 1; 'min' = 60; 'h' = 3600; 'day' = 86400; 'week' = 604800; 'month' = 2629746; 'year' = 31556952 }
    'Speed'       = [ordered]@{ 'm/s' = 1; 'km/h' = (1 / 3.6); 'mph' = 0.44704; 'knot' = (1852 / 3600); 'ft/s' = 0.3048 }
    'Area'        = [ordered]@{ 'mm2' = 1e-6; 'cm2' = 1e-4; 'm2' = 1; 'ha' = 1e4; 'km2' = 1e6; 'in2' = 0.00064516; 'ft2' = 0.09290304; 'acre' = 4046.8564224; 'mi2' = 2589988.110336 }
    'Volume'      = [ordered]@{ 'ml' = 0.001; 'l' = 1; 'm3' = 1000; 'tsp' = 0.00492892159; 'tbsp' = 0.0147867648; 'fl oz (US)' = 0.0295735296; 'cup (US)' = 0.2365882365; 'pint (US)' = 0.473176473; 'gallon (US)' = 3.785411784; 'gallon (UK)' = 4.54609 }
    'Temperature' = [ordered]@{ 'C' = 1; 'F' = 1; 'K' = 1 }
    'Pressure'    = [ordered]@{ 'Pa' = 1; 'kPa' = 1000; 'bar' = 1e5; 'psi' = 6894.757293; 'atm' = 101325; 'mmHg' = 133.322387 }
    'Energy'      = [ordered]@{ 'J' = 1; 'kJ' = 1000; 'cal' = 4.184; 'kcal' = 4184; 'Wh' = 3600; 'kWh' = 3.6e6; 'BTU' = 1055.05585 }
}

function Convert-Unit([string]$Category, [double]$Value, [string]$From, [string]$To) {
    if ($Category -eq 'Temperature') {
        $k = switch ($From) { 'C' { $Value + 273.15 } 'F' { ($Value - 32) * 5 / 9 + 273.15 } default { $Value } }
        return $(switch ($To) { 'C' { $k - 273.15 } 'F' { ($k - 273.15) * 9 / 5 + 32 } default { $k } })
    }
    $u = $UnitTable[$Category]
    $Value * $u[$From] / $u[$To]
}

function Format-UnitNumber([double]$V) {
    if ($V -eq 0) { return '0' }
    $a = [math]::Abs($V)
    if ($a -ge 1e15 -or $a -lt 1e-6) { return $V.ToString('0.######E+0', [Globalization.CultureInfo]::InvariantCulture) }
    $r = [math]::Round($V, [math]::Max(0, 9 - [int][math]::Floor([math]::Log10($a))))
    $r.ToString('#,0.##########', [Globalization.CultureInfo]::InvariantCulture).Replace(',', ' ')
}

Register-ToolboxPage 'units' 'Units' $Glyph.Refresh 'unit convert length weight data size mb gb mib time speed area volume temperature celsius fahrenheit pressure energy' {
    param($panel, $st)
    $st.Status = New-TbPage $panel
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Dock = 'Fill'; $lv.View = 'Details'; $lv.FullRowSelect = $true; $lv.BorderStyle = 'None'; $lv.HideSelection = $false
    $lv.BackColor = $C.Bg; $lv.ForeColor = $C.Fore; $lv.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    [void]$lv.Columns.Add('Value', (Px (320 * $TextZoom)), 'Right'); [void]$lv.Columns.Add('Unit', (Px (200 * $TextZoom)))
    $lv.add_DoubleClick({ param($src, $e) if ($src.SelectedItems.Count) { Copy-TbText ($src.SelectedItems[0].Text -replace ' ', ''); Set-TbStatus $TbUI.Pages['units'].State.Status "Copied $($src.SelectedItems[0].Text) $($src.SelectedItems[0].SubItems[1].Text)" 'ok' } })
    $panel.Controls.Add($lv)
    $st.List = $lv
    $bar = New-TbBar $panel
    $st.Cat = New-TbCombo $bar @($UnitTable.Keys) 140
    $st.Input = New-TbBox -Mono -Cue '1.5   or   5 km   or   100 F'
    $st.Input.Width = Px (200 * $TextZoom); $st.Input.Margin = New-Object System.Windows.Forms.Padding(0, (Px 4), (Px 8), 0)
    $st.Input.Font = New-Object System.Drawing.Font('Consolas', (Fz 12))
    $bar.Controls.Add($st.Input)
    $st.From = New-TbCombo $bar @() 140
    $st.Cat.add_SelectedIndexChanged({
        $s = $TbUI.Pages['units'].State
        $s.From.Items.Clear(); foreach ($u in $UnitTable[[string]$s.Cat.SelectedItem].Keys) { [void]$s.From.Items.Add($u) }
        $s.From.SelectedIndex = [math]::Min(1, $s.From.Items.Count - 1)
    })
    $st.From.add_SelectedIndexChanged({ Update-UnitTool $TbUI.Pages['units'].State })
    $st.Input.add_TextChanged({ Update-UnitTool $TbUI.Pages['units'].State -FromText })
    $st.Cat.SelectedIndex = 1; $st.Cat.SelectedIndex = 0
    $st.SetInput = { param($t) $TbUI.Pages['units'].State.Input.Text = $t.Trim() }
    $st.Focus = { $TbUI.Pages['units'].State.Input.Focus() }
    $st
}

function Update-UnitTool($St, [switch]$FromText) {
    $t = $St.Input.Text.Trim()
    $St.List.BeginUpdate(); $St.List.Items.Clear()
    try {
        if (-not $t) { Set-TbStatus $St.Status 'Type a number. You can add a unit ("5 km", "100 F", "3 GiB") and it is picked for you. Double-click a result to copy it.'; return }
        $m = [regex]::Match($t, '^\s*([-+]?[\d\s.,]*\d(?:[eE][-+]?\d+)?|[-+]?\.\d+)\s*(.*)$')
        if (-not $m.Success) { Set-TbStatus $St.Status 'That is not a number.' 'error'; return }
        $num = $m.Groups[1].Value -replace '\s', ''
        if ($num -match '^\d{1,3}(,\d{3})+(\.\d+)?$') { $num = $num -replace ',', '' } else { $num = $num -replace ',', '.' }
        $v = 0.0
        if (-not [double]::TryParse($num, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v)) { Set-TbStatus $St.Status 'That is not a number.' 'error'; return }
        $unitText = $m.Groups[2].Value.Trim() -replace "^(deg|$([char]0xB0))\s*", '' -replace [string][char]0xB2, '2' -replace [string][char]0xB3, '3'
        if ($FromText -and $unitText) {
            foreach ($cat in $UnitTable.Keys) {
                $hit = @($UnitTable[$cat].Keys) | Where-Object { $_ -ceq $unitText } | Select-Object -First 1
                if (-not $hit) { $hit = @($UnitTable[$cat].Keys) | Where-Object { $_ -eq $unitText -or ($_ -replace ' \(.*\)$', '') -eq $unitText -or "$($_)s" -eq $unitText } | Select-Object -First 1 }
                if ($hit) {
                    if ([string]$St.Cat.SelectedItem -ne $cat) { $St.Cat.SelectedItem = $cat }
                    if ([string]$St.From.SelectedItem -ne $hit) { $St.From.SelectedItem = $hit; return }   # that change refreshes the list
                    break
                }
            }
        }
        $cat = [string]$St.Cat.SelectedItem; $from = [string]$St.From.SelectedItem
        $St.List.Items.Clear()                 # picking the unit above may have filled it already
        foreach ($u in $UnitTable[$cat].Keys) {
            $r = Convert-Unit $cat $v $from $u
            $it = New-Object System.Windows.Forms.ListViewItem((Format-UnitNumber $r))
            [void]$it.SubItems.Add($(if ($cat -eq 'Temperature') { "$([char]0xB0)$u" -replace "$([char]0xB0)K", 'K' } else { $u }))
            if ($u -eq $from) { $it.ForeColor = $C.Accent }
            [void]$St.List.Items.Add($it)
        }
        Set-TbStatus $St.Status "$(Format-UnitNumber $v) $from in every $($cat.ToLower()) unit. Double-click a row to copy the number."
    } finally { $St.List.EndUpdate() }
}

# ======================================================================================
# Time: Unix timestamps, ISO dates, time zones.
# ======================================================================================

function ConvertTo-DateTimeOffset([string]$Text, [TimeZoneInfo]$Zone) {
    $t = $Text.Trim()
    $inv = [Globalization.CultureInfo]::InvariantCulture
    if (-not $t -or $t -eq 'now') { return [DateTimeOffset]::Now }
    if ($t -match '^/Date\((-?\d+)') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]$Matches[1]) }
    if ($t -match '^-?\d{1,11}(\.\d+)?$') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]([double]::Parse($t, $inv) * 1000)) }
    if ($t -match '^-?\d{12,14}$') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]$t) }
    if ($t -match '^\d{15,17}$') { return [DateTimeOffset]::FromUnixTimeMilliseconds([long]([long]$t / 1000)) }       # microseconds
    if ($t -match '^\d{18,19}$') { return (New-Object DateTimeOffset([long]$t, [TimeSpan]::Zero)) }                        # .NET ticks
    $hasZone = $t -match '(Z|[+-]\d\d:?\d\d|\b(GMT|UTC))$'
    $styles = [Globalization.DateTimeStyles]::AllowWhiteSpaces
    $dto = [DateTimeOffset]::MinValue
    if ($hasZone) {
        if ([DateTimeOffset]::TryParse(($t -replace '\bUTC$', 'Z'), $inv, $styles, [ref]$dto)) { return $dto }
        if ([DateTimeOffset]::TryParse($t, [Globalization.CultureInfo]::CurrentCulture, $styles, [ref]$dto)) { return $dto }
    }
    $dt = [datetime]::MinValue
    if (-not [datetime]::TryParse($t, [Globalization.CultureInfo]::CurrentCulture, $styles, [ref]$dt) -and
        -not [datetime]::TryParse($t, $inv, $styles, [ref]$dt)) { throw "Can't read that as a date or a timestamp." }
    $dt = [datetime]::SpecifyKind($dt, 'Unspecified')
    $utc = [TimeZoneInfo]::ConvertTimeToUtc($dt, $Zone)
    [TimeZoneInfo]::ConvertTime((New-Object DateTimeOffset($utc, [TimeSpan]::Zero)), $Zone)
}

function Format-Offset([TimeSpan]$O) { '{0}{1:00}:{2:00}' -f $(if ($O -lt [TimeSpan]::Zero) { '-' } else { '+' }), [math]::Abs($O.Hours), [math]::Abs($O.Minutes) }

